CREATE OR REPLACE FUNCTION "public"."add_occupancy_delinquency_note"("p_occupancy_id" "uuid", "p_note" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare o record; v_id uuid;
begin
  select occ.id, occ.association_id, a.portfolio_id as pid into o
    from public.occupancies occ join public.associations a on a.id = occ.association_id
   where occ.id = p_occupancy_id;
  if not found or not public.is_any_staff() or not public.can_access_portfolio(o.pid)
     or not public.can_manage_association(o.association_id) then
    raise exception 'Ownership record not found' using errcode = 'P0002';
  end if;
  if length(btrim(coalesce(p_note, ''))) = 0 then
    raise exception 'Write a note first' using errcode = '22023';
  end if;
  insert into public.occupancy_delinquency_notes (portfolio_id, occupancy_id, note, created_by, created_by_email)
  values (o.pid, p_occupancy_id, btrim(p_note), auth.uid(), (select email from auth.users where id = auth.uid()))
  returning id into v_id;
  return v_id;
end $$;


ALTER FUNCTION "public"."add_occupancy_delinquency_note"("p_occupancy_id" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_record_note"("p_entity_type" "text", "p_entity_id" "uuid", "p_body" "text", "p_mentions" "uuid"[] DEFAULT '{}'::"uuid"[], "p_app_url" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  v_pid uuid := public.record_portfolio_id(p_entity_type, p_entity_id);
  v_body text := btrim(coalesce(p_body, ''));
  v_mentions uuid[];
  v_author text;
  v_label text;
  v_link text;
  v_id uuid;
  v_base text := coalesce(nullif(rtrim(p_app_url, '/'), ''), 'https://portier369.com');
  m record;
begin
  if p_entity_type not in ('association', 'unit', 'owner', 'vendor') then
    raise exception 'Notes are not supported on this record' using errcode = '22023';
  end if;
  if v_pid is null or not public.can_access_portfolio(v_pid) or not public.app_record_in_manager_scope(p_entity_type, p_entity_id) then
    raise exception 'Record not found' using errcode = 'P0002';
  end if;
  if length(v_body) = 0 then raise exception 'Write a note first' using errcode = '22023'; end if;
  if length(v_body) > 5000 then raise exception 'Notes are limited to 5,000 characters' using errcode = '22023'; end if;
  -- The link goes to the company's own address, never one the caller passes.
  select case
           when p.custom_domain is not null and p.custom_domain_verified_at > now() - interval '3 hours' then 'https://' || p.custom_domain
           when p.slug ~ '^[a-z0-9](?:[a-z0-9-]{0,30}[a-z0-9])$' then 'https://' || p.slug || '.portier369.com'
           else rtrim(public.app_portal_url(), '/')
         end into v_base
    from public.portfolios p where p.id = v_pid;

  select coalesce(array_agg(distinct p.id), '{}') into v_mentions
    from public.profiles p
   where p.id = any (coalesce(p_mentions, '{}'))
     and p.id <> auth.uid()
     and p.portfolio_id = v_pid and p.disabled_at is null
     and p.hoa_role in ('manager', 'company_admin');

  select coalesce(nullif(btrim(p.full_name), ''), nullif(btrim(p.display_name), ''), p.email) into v_author
    from public.profiles p where p.id = auth.uid();

  insert into public.record_notes (portfolio_id, entity_type, entity_id, body, mentioned_user_ids, created_by, created_by_name)
  values (v_pid, p_entity_type, p_entity_id, v_body, v_mentions, auth.uid(), v_author)
  returning id into v_id;

  if cardinality(v_mentions) > 0 then
    v_label := coalesce(public.record_label(p_entity_type, p_entity_id), 'a record');
    v_link := v_base || case p_entity_type when 'association' then '/associations/' when 'unit' then '/units/'
                                          when 'owner' then '/owners/' else '/vendors/' end
              || p_entity_id || '#notes';
    for m in select p.id, p.email, coalesce(nullif(btrim(p.full_name), ''), p.email) as name
               from public.profiles p where p.id = any (v_mentions) and p.email is not null loop
      insert into public.email_queue (to_email, to_name, subject, body, status, from_address, from_name,
                                      portfolio_id, sent_by, idempotency_key)
      values (m.email, m.name,
              left(coalesce(v_author, 'A colleague') || ' mentioned you on ' || v_label, 200),
              '<div style="font-family:system-ui,-apple-system,Segoe UI,Arial,sans-serif;line-height:1.6;color:#111827">'
                || '<p><strong>' || replace(replace(replace(coalesce(v_author, 'A colleague'), '&', '&amp;'), '<', '&lt;'), '>', '&gt;')
                || '</strong> mentioned you in a note on <strong>'
                || replace(replace(replace(v_label, '&', '&amp;'), '<', '&lt;'), '>', '&gt;') || '</strong>:</p>'
                || '<blockquote style="margin:0;padding:8px 12px;border-left:3px solid #d1d5db;white-space:pre-wrap;color:#374151">'
                || replace(replace(replace(v_body, '&', '&amp;'), '<', '&lt;'), '>', '&gt;') || '</blockquote>'
                || '<p><a href="' || v_link || '">Open the record</a></p></div>',
              'pending', 'noreply@portier369.com', null, v_pid, auth.uid(),
              'mention:' || v_id || ':' || m.id)
      on conflict do nothing;
    end loop;
  end if;
  return v_id;
end $_$;


ALTER FUNCTION "public"."add_record_note"("p_entity_type" "text", "p_entity_id" "uuid", "p_body" "text", "p_mentions" "uuid"[], "p_app_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."adopt_budget"("p_association_id" "uuid", "p_fiscal_year" integer, "p_note" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_portfolio uuid;
begin
  if not public.can_mutate_association_budget(p_association_id) then
    raise exception 'Finance authorization required' using errcode = '42501';
  end if;
  if length(coalesce(p_note, '')) > 2000 then raise exception 'Note is too long' using errcode = '22023'; end if;
  if not exists (select 1 from public.budget_lines where association_id = p_association_id and fiscal_year = p_fiscal_year) then
    raise exception 'Add budget lines before adopting' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtext('budget_adopt:' || p_association_id::text || ':' || p_fiscal_year::text));
  if exists (select 1 from public.association_budgets where association_id = p_association_id and fiscal_year = p_fiscal_year and status = 'adopted') then
    raise exception 'The FY% budget is already adopted', p_fiscal_year using errcode = '55000';
  end if;
  select portfolio_id into v_portfolio from public.associations where id = p_association_id;
  insert into public.association_budgets (portfolio_id, association_id, fiscal_year, status, adopted_at, adopted_by, adoption_note)
  values (v_portfolio, p_association_id, p_fiscal_year, 'adopted', now(), auth.uid(), nullif(btrim(p_note), ''))
  on conflict (association_id, fiscal_year) do update
    set status = 'adopted', adopted_at = now(), adopted_by = auth.uid(), adoption_note = nullif(btrim(p_note), ''), updated_at = now();
  insert into public.audit_logs (portfolio_id, entity_type, entity_id, action, actor_id, actor_email, changes)
  values (v_portfolio, 'association', p_association_id, 'budget_adopted', auth.uid(), (select email from auth.users where id = auth.uid()),
          jsonb_build_object('fiscal_year', p_fiscal_year, 'note', p_note,
            'income', (select sum(annual_total) from public.budget_lines where association_id = p_association_id and fiscal_year = p_fiscal_year and category = 'income'),
            'expense', (select sum(annual_total) from public.budget_lines where association_id = p_association_id and fiscal_year = p_fiscal_year and category = 'expense')));
end $$;


ALTER FUNCTION "public"."adopt_budget"("p_association_id" "uuid", "p_fiscal_year" integer, "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."advance_delinquency_case"("p_case_id" "uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  case_row public.delinquency_cases;
  next_step public.delinquency_steps;
begin
  select * into case_row from public.delinquency_cases where id = p_case_id for update;
  if not found then raise exception 'Delinquency case not found'; end if;
  if not public.can_view_association_row(case_row.association_id) then raise exception 'Delinquency case not found'; end if;
  if not (public.can_access_portfolio(case_row.portfolio_id) and (public.is_any_staff() or public.is_company_admin() or public.is_platform_operator())) then
    raise exception 'Not authorized to manage this delinquency case';
  end if;
  if case_row.status not in ('open', 'legal_review') then
    raise exception 'Case must be open before advancing';
  end if;
  select * into next_step
  from public.delinquency_steps
  where policy_id = case_row.policy_id and step_number > case_row.current_step_number
  order by step_number limit 1;
  if not found then raise exception 'No further policy step is configured'; end if;
  if case_row.oldest_due_date is null
     or (public.association_local_date(case_row.association_id) - case_row.oldest_due_date) < next_step.days_past_due then
    raise exception 'The next policy step is not due yet';
  end if;

  update public.delinquency_cases
  set current_step_number = next_step.step_number,
      status = case when next_step.action_type = 'legal_review' then 'legal_review' else 'open' end,
      next_action_at = null
  where id = p_case_id;
  insert into public.delinquency_case_events (case_id, event_type, step_number, balance_snapshot, note, metadata)
  values (p_case_id, case when next_step.action_type = 'legal_review' then 'legal_review_requested' else 'step_advanced' end,
          next_step.step_number, case_row.balance_snapshot, nullif(btrim(coalesce(p_note, '')), ''),
          jsonb_build_object('step_name', next_step.name, 'action_type', next_step.action_type, 'requires_human_approval', next_step.requires_human_approval));
  return jsonb_build_object('step_number', next_step.step_number, 'action_type', next_step.action_type,
                            'requires_human_approval', next_step.requires_human_approval);
end;
$$;


ALTER FUNCTION "public"."advance_delinquency_case"("p_case_id" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."advance_violation"("p_violation_id" "uuid", "p_note" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare v public.violations; s record; nxt record; settings public.association_violation_settings; v_portfolio uuid; v_cat public.charge_categories; v_charge_id uuid; v_new_status public.violation_status; v_hearing_days integer;
begin
  select * into v from public.violations where id = p_violation_id for update;
  if not found or not public.can_manage_violations(v.association_id) then raise exception 'Permission denied' using errcode = '42501'; end if;
  if v.archived_at is not null or v.status in ('cured', 'closed') then raise exception 'This violation is already resolved' using errcode = '22023'; end if;
  select * into s from public.violation_schedule(v.association_id, v.house_rule_id) where ordinal = v.current_step + 1;
  if not found then raise exception 'The follow-up schedule is complete — resolve the violation or record a hearing decision' using errcode = '22023'; end if;
  select * into nxt from public.violation_schedule(v.association_id, v.house_rule_id) where ordinal = v.current_step + 2;
  select * into settings from public.association_violation_settings where association_id = v.association_id;
  v_hearing_days := coalesce(settings.hearing_request_days, 14);
  v_new_status := case when v.status = 'open' then 'notice_sent'::public.violation_status else v.status end;
  if s.fee > 0 then
    if v.unit_id is null then raise exception 'Fines need a unit — add the unit to this violation first' using errcode = '22023'; end if;
    if v.board_decision = 'dismissed' then raise exception 'A hearing dismissed this violation' using errcode = '22023'; end if;
    if coalesce(settings.hearing_required_before_fine, true) and coalesce(v.board_decision, '') <> 'upheld' then
      if v.hearing_requested_at is not null then raise exception 'The owner requested a hearing — record the hearing decision before fining' using errcode = '22023'; end if;
      if v.notice_sent_at is null then raise exception 'Due process: send a notice before fining' using errcode = '22023'; end if;
      if public.association_local_date(v.association_id, v.notice_sent_at) + v_hearing_days >= public.association_local_date(v.association_id) then
        raise exception 'Due process: the owner has until % to request a hearing', to_char(public.association_local_date(v.association_id, v.notice_sent_at) + v_hearing_days, 'Mon DD, YYYY') using errcode = '22023';
      end if;
    end if;
    select a.portfolio_id into v_portfolio from public.associations a where a.id = v.association_id;
    select * into v_cat from public.charge_categories c
     where c.portfolio_id = v_portfolio and c.active and c.archived_at is null
       and (c.id = settings.fine_charge_category_id or (settings.fine_charge_category_id is null and c.charge_type = 'fine'))
     order by (c.id = settings.fine_charge_category_id) desc nulls last, c.sort_order limit 1;
    if not found then raise exception 'No active fine charge category is configured' using errcode = '22023'; end if;
    insert into public.charges (unit_id, charge_category_id, charge_type, description, amount, due_date, gl_account_id, created_by)
    values (v.unit_id, v_cat.id, 'fine', left('Violation fine — ' || v.title || ' (' || s.follow_up_name || ')', 500), round(s.fee, 2), public.association_local_date(v.association_id) + 30,
            coalesce(s.gl_account_id, v_cat.gl_account_id), case when exists (select 1 from public.profiles where id = auth.uid()) then auth.uid() end)
    returning id into v_charge_id;
    insert into public.violation_fines (violation_id, step_id, step_order, step_name, charge_id, amount, assessed_by)
    values (v.id, s.id, s.ordinal, s.follow_up_name, v_charge_id, round(s.fee, 2), auth.uid());
    v_new_status := 'fined';
  end if;
  update public.violations
     set current_step = s.ordinal, status = v_new_status,
         current_step_terms = jsonb_build_object('step', s.ordinal, 'step_name', s.follow_up_name, 'fee', s.fee, 'letter_template_id', s.letter_template_id, 'delivery_methods', s.delivery_methods, 'offers_hearing', s.offers_hearing, 'hearing_request_days', v_hearing_days, 'template_subject', (select t.subject from public.document_templates t where t.id = s.letter_template_id), 'template_body', (select t.body from public.document_templates t where t.id = s.letter_template_id)), last_step_at = now(), notice_sent_at = coalesce(notice_sent_at, now()),
         hearing_required = hearing_required or s.offers_hearing,
         fines_total = fines_total + case when s.fee > 0 then round(s.fee, 2) else 0 end,
         fine_amount = case when s.fee > 0 then fines_total + round(s.fee, 2) else fine_amount end,
         fine_assessed_at = case when s.fee > 0 then now() else fine_assessed_at end,
         next_followup_on = case when nxt.ordinal is not null then public.association_local_date(v.association_id) + nxt.days_after_previous end
   where id = v.id;
  perform public.log_violation_event(v.id,
    s.follow_up_name
      || case when s.fee > 0 then ' — fine of $' || to_char(s.fee, 'FM999,999,990.00') || ' posted to the unit ledger' else '' end
      || case when s.offers_hearing then ' — hearing offered (request within ' || v_hearing_days || ' days)' else '' end
      || case when nullif(btrim(coalesce(p_note, '')), '') is not null then '. ' || btrim(p_note) else '' end,
    v_new_status, true);
  return jsonb_build_object('step', s.ordinal, 'step_name', s.follow_up_name, 'fee', s.fee, 'charge_id', v_charge_id,
    'letter_template_id', s.letter_template_id, 'delivery_methods', s.delivery_methods, 'offers_hearing', s.offers_hearing, 'status', v_new_status,
    'next_followup_on', case when nxt.ordinal is not null then public.association_local_date(v.association_id) + nxt.days_after_previous end);
end;
$_$;


ALTER FUNCTION "public"."advance_violation"("p_violation_id" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."aggregate_usage_metrics"("p_year" integer, "p_month" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  period_start timestamptz := make_timestamptz(p_year, p_month, 1, 0, 0, 0, 'UTC');
  period_end timestamptz := period_start + interval '1 month';
  month_open boolean := now() < period_end;
begin
  insert into public.usage_metrics (
    portfolio_id, period_year, period_month,
    staff_count, owner_count, association_count, unit_count,
    work_orders_created, service_requests_created, bills_posted,
    payments_received, emails_sent, sms_sent, api_calls
  )
  select
    p.id,
    p_year,
    p_month,
    coalesce((select count(*) from public.profiles where portfolio_id = p.id and hoa_role in ('manager', 'company_admin')), 0),
    coalesce((select count(*) from public.profiles where portfolio_id = p.id and hoa_role in ('owner', 'tenant')), 0),
    coalesce((select count(*) from public.associations where portfolio_id = p.id and archived_at is null), 0),
    coalesce((select count(*) from public.units u
              join public.buildings b on b.id = u.building_id
              join public.associations a on a.id = b.association_id
              where a.portfolio_id = p.id and u.archived_at is null), 0),
    coalesce((select count(*) from public.work_orders w
              where w.portfolio_id = p.id and w.created_at >= period_start and w.created_at < period_end), 0),
    coalesce((select count(*) from public.service_requests s
              where s.portfolio_id = p.id and s.created_at >= period_start and s.created_at < period_end), 0),
    coalesce((select count(*) from public.payable_bills b
              where b.portfolio_id = p.id and b.created_at >= period_start and b.created_at < period_end), 0),
    coalesce((select count(*) from public.payments pm
              join public.units u on u.id = pm.unit_id
              join public.buildings b on b.id = u.building_id
              join public.associations a on a.id = b.association_id
              where a.portfolio_id = p.id and pm.created_at >= period_start and pm.created_at < period_end), 0),
    coalesce((select count(*) from public.email_queue eq
              join public.associations a on a.id = eq.association_id
              where a.portfolio_id = p.id and eq.sent_at >= period_start and eq.sent_at < period_end), 0),
    coalesce((select count(*) from public.sms_messages sm
              join public.sms_conversations sc on sc.id = sm.conversation_id
              where sc.portfolio_id = p.id and sm.created_at >= period_start and sm.created_at < period_end), 0),
    coalesce((select sum(d.request_count) from public.api_key_usage_daily d
              where d.portfolio_id = p.id
                and d.usage_date >= period_start::date and d.usage_date < period_end::date), 0)
  from public.portfolios p
  where p.archived_at is null
    and p.created_at < period_end
  on conflict (portfolio_id, period_year, period_month) do update set
    staff_count = case when month_open then excluded.staff_count else public.usage_metrics.staff_count end,
    owner_count = case when month_open then excluded.owner_count else public.usage_metrics.owner_count end,
    association_count = case when month_open then excluded.association_count else public.usage_metrics.association_count end,
    unit_count = case when month_open then excluded.unit_count else public.usage_metrics.unit_count end,
    work_orders_created = excluded.work_orders_created,
    service_requests_created = excluded.service_requests_created,
    bills_posted = excluded.bills_posted,
    payments_received = excluded.payments_received,
    emails_sent = excluded.emails_sent,
    sms_sent = excluded.sms_sent,
    api_calls = excluded.api_calls,
    updated_at = now();
end;
$$;


ALTER FUNCTION "public"."aggregate_usage_metrics"("p_year" integer, "p_month" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."alert_overdue_bills"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  row record;
  n integer := 0;
begin
  for row in
    select pb.id, pb.portfolio_id, pb.vendor_id, v.name as vendor_name,
           pb.amount, pb.due_date, pb.bill_number
      from public.payable_bills pb
      join public.vendors v on v.id = pb.vendor_id
     where pb.archived_at is null
       and pb.status in ('approved','pending_approval')
       and pb.due_date < current_date
       and pb.paid_at is null
  loop
    perform public.dispatch_webhook(
      row.portfolio_id,
      'bill.created'::public.webhook_event,
      jsonb_build_object(
        'bill_id', row.id, 'vendor_id', row.vendor_id, 'vendor_name', row.vendor_name,
        'amount', row.amount, 'due_date', row.due_date, 'days_overdue',
        (current_date - row.due_date)
      )
    );
    n := n + 1;
  end loop;
  return n;
end;
$$;


ALTER FUNCTION "public"."alert_overdue_bills"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."alert_overdue_bills"() IS 'Daily: dispatches bill.created webhooks for overdue bills so external systems can follow up.';



CREATE OR REPLACE FUNCTION "public"."amenity_reservations_owner_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare n public.amenity_reservations;
begin
  if pg_trigger_depth() > 1 or not public.is_self_service_caller()
     or old.owner_id is null or old.owner_id not in (select public.current_owner_ids()) then
    return new;
  end if;
  if new.status is distinct from old.status and new.status <> 'cancelled' then
    raise exception 'You can only cancel your own reservation' using errcode = '42501';
  end if;
  n := new;
  new := old;
  new.status := n.status;
  new.updated_at := now();
  return new;
end $$;


ALTER FUNCTION "public"."amenity_reservations_owner_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."amenity_reservations_resident_insert_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  am record; v_start timestamp; v_end timestamp; v_end_time time;
begin
  if pg_trigger_depth() > 1 or auth.uid() is null then return new; end if;
  if (public.is_platform_operator() or public.is_any_staff() or public.is_company_admin())
     and public.can_access_association(new.association_id) then
    return new;
  end if;
  select a.id, a.association_id, a.allow_reservations, a.archived_at, a.reserve_method,
         a.reservation_email, a.reservation_url, a.opens_at, a.closes_at,
         coalesce(nullif(s.timezone, ''), 'America/Chicago') as tz
    into am
    from public.association_amenities a
    left join public.associations s on s.id = a.association_id
   where a.id = new.amenity_id
     for share of a;
  if not found or am.archived_at is not null or not coalesce(am.allow_reservations, false)
     or (am.reserve_method::text = 'email' and nullif(btrim(coalesce(am.reservation_email, '')), '') is not null)
     or (am.reserve_method::text = 'platform_link' and nullif(btrim(coalesce(am.reservation_url, '')), '') is not null)
     or am.association_id is distinct from new.association_id then
    raise exception 'That amenity does not take reservation requests here' using errcode = '42501';
  end if;
  if new.start_time is null or new.end_time is null or new.end_time <= new.start_time then
    raise exception 'A reservation must end after it starts' using errcode = '22023';
  end if;
  if new.start_time <= now() then
    raise exception 'Pick a time in the future' using errcode = '22023';
  end if;
  if am.opens_at is not null or am.closes_at is not null then
    v_start := new.start_time at time zone am.tz;
    v_end := new.end_time at time zone am.tz;
    -- codex_379_380_followups: hours that run past midnight (e.g. 18:00-02:00).
    if am.opens_at is not null and am.closes_at is not null and am.opens_at > am.closes_at then
      if v_end::date = v_start::date then
        -- Inside [opens, 24:00] or inside [00:00, closes] on one day.
        if v_start::time < am.opens_at and v_end::time > am.closes_at then
          raise exception 'That time is outside the amenity''s hours' using errcode = '22023';
        end if;
      elsif v_end::date = v_start::date + 1 then
        -- Across midnight: from opening on the start day to closing the next.
        if v_start::time < am.opens_at or v_end::time > am.closes_at then
          raise exception 'That time is outside the amenity''s hours' using errcode = '22023';
        end if;
      else
        raise exception 'A reservation must end by the next day' using errcode = '22023';
      end if;
      return new;
    end if;
    if v_end::date = v_start::date then
      v_end_time := v_end::time;
    elsif v_end::date = v_start::date + 1 and v_end::time = time '00:00' then
      v_end_time := time '24:00';
    else
      raise exception 'A reservation must start and end on the same day' using errcode = '22023';
    end if;
    if am.opens_at is null or am.closes_at is null or am.opens_at < am.closes_at then
      if (am.opens_at is not null and v_start::time < am.opens_at)
         or (am.closes_at is not null and v_end_time > am.closes_at) then
        raise exception 'That time is outside the amenity''s hours' using errcode = '22023';
      end if;
    end if;
  end if;
  return new;
end
$$;


ALTER FUNCTION "public"."amenity_reservations_resident_insert_guard"() OWNER TO "postgres";


