CREATE OR REPLACE FUNCTION "public"."app_bank_account_association_ids"("p_bank_account_id" "uuid") RETURNS "uuid"[]
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare b public.bank_accounts; v uuid[];
begin
  select * into b from public.bank_accounts where id = p_bank_account_id;
  if b.id is null then return '{}'; end if;
  if b.association_id is not null then return array[b.association_id]; end if;
  select coalesce(array_agg(a.id), '{}') into v
    from public.associations a
   where a.portfolio_id = b.portfolio_id and a.archived_at is null
     and b.id in (a.operating_bank_account_id, a.reserve_bank_account_id, a.primary_bank_account_id);
  return v;
end
$$;


ALTER FUNCTION "public"."app_bank_account_association_ids"("p_bank_account_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."app_bank_book_balance"("p_bank_account_id" "uuid", "p_through" "date") RETURNS numeric
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select coalesce(sum(jl.debit_amount - jl.credit_amount), 0)
    from public.bank_accounts b
    join public.journal_lines jl
      on jl.gl_account_id = b.gl_account_id
     and (b.association_id is null or jl.association_id = b.association_id)
    join public.journal_entries je on je.id = jl.entry_id and je.posted and je.entry_date <= p_through
   where b.id = p_bank_account_id
$$;


