CREATE OR REPLACE FUNCTION "public"."app_bank_transaction_for_update"("p_id" "uuid") RETURNS "public"."bank_transactions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare t public.bank_transactions; b public.bank_accounts;
begin
  select * into t from public.bank_transactions where id = p_id for update;
  if not found then raise exception 'Bank transaction not found' using errcode = 'P0002'; end if;
  select * into b from public.bank_accounts where id = t.bank_account_id;
  if b.id is null or not public.can_manage_finance(b.portfolio_id)
     or (b.association_id is not null and not public.can_view_association_row(b.association_id)) then
    raise exception 'Bank transaction not found' using errcode = 'P0002';
  end if;
  if b.gl_account_id is null then raise exception 'Link the bank account to a GL account first' using errcode = '22023'; end if;
  -- matched_at covers every claim, including Stripe payout reconciliation,
  -- which sets it without a ledger line or deposit.
  if t.matched_at is not null or t.matched_journal_line_id is not null or t.matched_bank_deposit_id is not null then
    raise exception 'This transaction is already matched' using errcode = '22023';
  end if;
  if t.pending then raise exception 'Wait until the bank posts this transaction' using errcode = '22023'; end if;
  return t;
end $$;


ALTER FUNCTION "public"."app_bank_transaction_for_update"("p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."app_bill_management_fees"("p_portfolio_id" "uuid", "p_month" "date", "p_association_ids" "uuid"[], "p_vendor_id" "uuid", "p_gl_account_id" "uuid", "p_bill_date" "date", "p_actor" "uuid", "p_source" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  v_month date := date_trunc('month', p_month)::date;
  v_bill_date date := coalesce(p_bill_date, (date_trunc('month', p_month) + interval '1 month - 1 day')::date);
  r record;
  v_bill uuid;
  n integer := 0;
begin
  if not exists (select 1 from public.vendors v where v.id = p_vendor_id and v.portfolio_id = p_portfolio_id and v.archived_at is null
                   and v.is_management_company) then
    raise exception 'Choose the management company vendor' using errcode = '22023';
  end if;
  if not exists (select 1 from public.gl_accounts g where g.id = p_gl_account_id and g.portfolio_id = p_portfolio_id and g.active
                   and g.association_id is null and g.account_type::text in ('expense', 'other_expense')) then
    raise exception 'Choose a company-wide expense account for management fees' using errcode = '22023';
  end if;

  for r in
    select * from public.app_management_fee_calc(p_portfolio_id, v_month) pv
     where pv.association_id = any (p_association_ids) and not pv.already_billed and pv.fee > 0
  loop
    insert into public.payable_bills (portfolio_id, vendor_id, association_id, gl_account_id, bill_number, bill_date, due_date,
                                      amount, memo, status, approval_required, approved_at, approved_by, created_by)
    values (p_portfolio_id, p_vendor_id, r.association_id, p_gl_account_id,
            'MGMT-' || to_char(v_month, 'YYYY-MM'), v_bill_date, v_bill_date, r.fee,
            'Management fee ' || chr(8212) || ' ' || to_char(v_month, 'FMMonth YYYY') || ' (' ||
              case r.fee_type when 'per_door' then r.door_count || ' units ' || chr(215) || ' ' || to_char(r.rate, 'FM$999,990.00')
                              when 'flat_monthly' then 'flat monthly'
                              else r.rate || '% of ' || to_char(r.basis, 'FM$999,999,990.00') || ' assessments' end || ')',
            'approved', false, now(), p_actor, p_actor)
    returning id into v_bill;
    perform public.ensure_payable_bill_accrual(v_bill);

    insert into public.management_fees (portfolio_id, association_id, month, fee_amount_cents, door_count,
                                        avg_per_door_cents, fee_type, rate, basis_cents, bill_id, created_by)
    values (p_portfolio_id, r.association_id, v_month, round(r.fee * 100)::int, r.door_count,
            case when r.door_count > 0 then round(r.fee * 100 / r.door_count)::int end,
            r.fee_type, r.rate, round(coalesce(r.basis, 0) * 100)::bigint, v_bill, p_actor)
    on conflict (association_id, month) do update
      set fee_amount_cents = excluded.fee_amount_cents, door_count = excluded.door_count,
          avg_per_door_cents = excluded.avg_per_door_cents, fee_type = excluded.fee_type, rate = excluded.rate,
          basis_cents = excluded.basis_cents, bill_id = excluded.bill_id, created_by = excluded.created_by
      where public.management_fees.bill_id is null
         or exists (select 1 from public.payable_bills vb where vb.id = public.management_fees.bill_id and vb.status = 'void'::public.payable_bill_status);
    if not found then
      raise exception 'Management fee for % was already billed', to_char(v_month, 'FMMonth YYYY') using errcode = '23505';
    end if;
    n := n + 1;
  end loop;

  insert into public.audit_logs (portfolio_id, entity_type, entity_id, action, actor_id, actor_email, changes)
  values (p_portfolio_id, 'management_fees', null, 'management_fees_billed', p_actor,
          (select email from auth.users where id = p_actor),
          jsonb_build_object('month', v_month, 'bills', n, 'associations', to_jsonb(p_association_ids), 'source', p_source));
  return n;
end $_$;


ALTER FUNCTION "public"."app_bill_management_fees"("p_portfolio_id" "uuid", "p_month" "date", "p_association_ids" "uuid"[], "p_vendor_id" "uuid", "p_gl_account_id" "uuid", "p_bill_date" "date", "p_actor" "uuid", "p_source" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."bank_accounts" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "portfolio_id" "uuid" NOT NULL,
    "association_id" "uuid",
    "name" "text" NOT NULL,
    "bank_name" "text",
    "description" "text",
    "routing_number" "text",
    "account_number" "text",
    "account_type" "public"."bank_account_type" DEFAULT 'checking'::"public"."bank_account_type" NOT NULL,
    "gl_account_id" "uuid",
    "use_printable_deposit_slip" boolean DEFAULT false NOT NULL,
    "address_street" "text",
    "address_city" "text",
    "address_state" "text",
    "address_zip" "text",
    "payments_enabled" boolean DEFAULT false NOT NULL,
    "auto_reconciliation" boolean DEFAULT false NOT NULL,
    "last_reconciliation_date" "date",
    "next_check_number" integer,
    "company_name" "text",
    "company_address" "text",
    "check_signature" "text",
    "entity_name" "text",
    "entity_address" "text",
    "archived_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "purpose" "public"."bank_account_purpose" DEFAULT 'other'::"public"."bank_account_purpose" NOT NULL,
    "fund_type" "text" DEFAULT 'operating'::"text" NOT NULL,
    "account_number_last4" "text" GENERATED ALWAYS AS ("right"(NULLIF("btrim"("account_number"), ''::"text"), 4)) STORED,
    "routing_number_last4" "text" GENERATED ALWAYS AS ("right"(NULLIF("btrim"("routing_number"), ''::"text"), 4)) STORED,
    CONSTRAINT "bank_accounts_fund_type_check" CHECK (("fund_type" = ANY (ARRAY['operating'::"text", 'reserve'::"text", 'insurance_proceeds'::"text", 'special_assessment'::"text", 'construction_escrow'::"text", 'petty_cash'::"text"]))),
    CONSTRAINT "bank_accounts_name_check" CHECK ((("length"("name") >= 1) AND ("length"("name") <= 200)))
);


