CREATE OR REPLACE FUNCTION "public"."app_meeting_quorum_snapshot"("p_meeting" "public"."meetings", OUT "total_units" integer, OUT "quorum_percentage" integer, OUT "quorum_needed" integer, OUT "attendee_count" integer, OUT "board_count" integer, OUT "owner_count" integer) RETURNS "record"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_date date := public.association_local_date(p_meeting.association_id, coalesce(p_meeting.start_time, now()));
begin
  select greatest(1, least(100, coalesce(a.quorum_percentage, 51))),
         greatest(0, coalesce(a.unit_count, 0))
    into quorum_percentage, total_units
    from public.associations a
   where a.id = p_meeting.association_id;

  select count(*)::integer,
         count(*) filter (where ma.attendee_role = 'board_member')::integer,
         count(distinct ma.owner_id) filter (
           where ma.owner_id is not null
             and coalesce(ma.voting_eligible, false)
             and exists (
               select 1 from public.occupancies o
                where o.owner_id = ma.owner_id
                  and o.association_id = p_meeting.association_id
                  and o.occupancy_type = 'owner'
                  and (o.status::text <> 'past' or o.move_out_date is not null)
                  and (o.move_in_date is null or o.move_in_date <= v_date)
                  and (o.move_out_date is null or o.move_out_date > v_date)))::integer
    into attendee_count, board_count, owner_count
    from public.meeting_attendees ma
   where ma.meeting_id = p_meeting.id
     and ma.present;

  quorum_needed := coalesce(p_meeting.quorum_requirement, ceil(total_units * quorum_percentage / 100.0)::integer);
end
$$;


ALTER FUNCTION "public"."app_meeting_quorum_snapshot"("p_meeting" "public"."meetings", OUT "total_units" integer, OUT "quorum_percentage" integer, OUT "quorum_needed" integer, OUT "attendee_count" integer, OUT "board_count" integer, OUT "owner_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."app_normalize_je_lines"("p_pid" "uuid", "p_lines" "jsonb", "p_check_scope" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  l jsonb;
  out jsonb := '[]'::jsonb;
  v_gl uuid; v_assoc uuid; v_d numeric; v_c numeric;
  v_td numeric := 0; v_tc numeric := 0; n int := 0;
begin
  if p_lines is null or jsonb_typeof(p_lines) <> 'array' then raise exception 'Add journal lines' using errcode = '22023'; end if;
  for l in select * from jsonb_array_elements(p_lines) loop
    n := n + 1;
    begin
      v_gl := nullif(l->>'gl_account_id', '')::uuid;
      v_assoc := nullif(l->>'association_id', '')::uuid;
      v_d := round(coalesce(nullif(l->>'debit', '')::numeric, 0), 2);
      v_c := round(coalesce(nullif(l->>'credit', '')::numeric, 0), 2);
    exception when others then
      raise exception 'Line %: amounts must be numbers', n using errcode = '22023';
    end;
    if v_d < 0 or v_c < 0 or (v_d > 0) = (v_c > 0) then
      raise exception 'Line %: enter either a debit or a credit, not both', n using errcode = '22023';
    end if;
    if v_assoc is null or not exists (select 1 from public.associations a where a.id = v_assoc and a.portfolio_id = p_pid)
       or (p_check_scope and not public.can_manage_association(v_assoc)) then
      raise exception 'Line %: choose an association you manage', n using errcode = '22023';
    end if;
    if v_gl is null or not exists (select 1 from public.gl_accounts g where g.id = v_gl and g.portfolio_id = p_pid and g.active
                                     and (g.association_id is null or g.association_id = v_assoc)) then
      raise exception 'Line %: choose an active GL account of that association', n using errcode = '22023';
    end if;
    v_td := v_td + v_d; v_tc := v_tc + v_c;
    out := out || jsonb_build_object('gl_account_id', v_gl, 'association_id', v_assoc, 'debit', v_d, 'credit', v_c,
                                     'memo', nullif(btrim(coalesce(l->>'memo', '')), ''));
  end loop;
  if n < 2 then raise exception 'A journal entry needs at least two lines' using errcode = '22023'; end if;
  if v_td <= 0 or v_td <> v_tc then
    raise exception 'Debits (%) must equal credits (%)', v_td, v_tc using errcode = '22023';
  end if;
  return out;
end $$;


ALTER FUNCTION "public"."app_normalize_je_lines"("p_pid" "uuid", "p_lines" "jsonb", "p_check_scope" boolean) OWNER TO "postgres";


