CREATE OR REPLACE FUNCTION "public"."app_reverse_owner_payable_entry"("r" "public"."owner_payables", "p_source" "text", "p_reversal_source" "text", "p_label" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_orig uuid;
  v_rev uuid;
  l record;
begin
  select id into v_orig from public.journal_entries where source_type = p_source and source_id = r.id order by created_at desc limit 1;
  if v_orig is null then return null; end if;
  insert into public.journal_entries (portfolio_id, entry_date, description, memo, reference_number, source_type, source_id, created_by, posted, posted_at)
  values (r.portfolio_id, coalesce(public.association_local_date(r.association_id, now()), current_date), p_label, r.memo, r.payable_number, p_reversal_source, r.id, auth.uid(), true, now())
  returning id into v_rev;
  for l in select * from public.journal_lines where entry_id = v_orig order by sort_order loop
    insert into public.journal_lines (entry_id, association_id, gl_account_id, debit_amount, credit_amount, memo, sort_order)
    values (v_rev, l.association_id, l.gl_account_id, l.credit_amount, l.debit_amount, 'Reversal: ' || coalesce(l.memo, ''), l.sort_order);
  end loop;
  return v_rev;
end $$;


ALTER FUNCTION "public"."app_reverse_owner_payable_entry"("r" "public"."owner_payables", "p_source" "text", "p_reversal_source" "text", "p_label" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."app_revoke_trigger_function_execute"() RETURNS "event_trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare c record;
begin
  for c in select objid from pg_event_trigger_ddl_commands()
            where object_type = 'function' and schema_name = 'public' loop
    if exists (select 1 from pg_proc p where p.oid = c.objid and p.prorettype = 'trigger'::regtype) then
      execute format('revoke execute on function %s from public, anon, authenticated', c.objid::regprocedure);
    end if;
  end loop;
end $$;


ALTER FUNCTION "public"."app_revoke_trigger_function_execute"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."app_scan_unapplied_credits"("p_portfolio_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare n integer;
begin
  create temporary table if not exists _unapplied_now (unit_id uuid, title text) on commit drop;
  truncate _unapplied_now;
  insert into _unapplied_now (unit_id, title)
  select x.unit_id,
         'Unit ' || x.unit_number || ' has ' || to_char(x.unapplied, 'FM$999,999,990.00') || ' unapplied while '
           || to_char(x.open_charges, 'FM$999,999,990.00') || ' in charges is open — apply the credit'
    from (
      select u.id as unit_id, u.unit_number,
             (select coalesce(sum(p.amount), 0) from public.payments p where p.unit_id = u.id)
               - (select coalesce(sum(pa.amount_applied), 0) from public.payment_applications pa
                    join public.payments p on p.id = pa.payment_id where p.unit_id = u.id) as unapplied,
             (select coalesce(sum(c.amount), 0) from public.charges c where c.unit_id = u.id)
               - (select coalesce(sum(pa.amount_applied), 0) from public.payment_applications pa
                    join public.charges c on c.id = pa.charge_id where c.unit_id = u.id) as open_charges
        from public.units u
        join public.buildings b on b.id = u.building_id
        join public.associations a on a.id = b.association_id
       where a.portfolio_id = p_portfolio_id and a.archived_at is null and u.archived_at is null
    ) x
   where x.unapplied > 0.005 and x.open_charges > 0.005;

  update public.data_diagnostics d
     set resolved_at = now()
   where d.portfolio_id = p_portfolio_id and d.category = 'unapplied_credit_open_charges' and d.resolved_at is null
     and not exists (select 1 from _unapplied_now c where c.unit_id = d.entity_id and c.title = d.title);

  insert into public.data_diagnostics (portfolio_id, category, entity_type, entity_id, severity, title)
  select p_portfolio_id, 'unapplied_credit_open_charges', 'unit', c.unit_id, 'warning', c.title from _unapplied_now c
  on conflict (portfolio_id, category, (coalesce(entity_id, '00000000-0000-0000-0000-000000000000'::uuid)), title) where resolved_at is null
  do update set last_seen_at = now(), occurrence_count = public.data_diagnostics.occurrence_count + 1;
  get diagnostics n = row_count;
  return n;
end $_$;


ALTER FUNCTION "public"."app_scan_unapplied_credits"("p_portfolio_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."app_unit_owner_since"("p_unit_id" "uuid") RETURNS "date"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$#variable_conflict use_column
begin
  return (select s.x from (

  select min(o.move_in_date) from public.occupancies o
   where o.unit_id = p_unit_id and o.status = 'current' and o.occupancy_type = 'owner'
  ) s(x) limit 1);
end$$;


ALTER FUNCTION "public"."app_unit_owner_since"("p_unit_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_architectural_review_settings"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  s public.architectural_review_settings%rowtype;
begin
  select * into s from public.architectural_review_settings where association_id = new.association_id;
  if not found then
    return new;
  end if;
  if coalesce(s.online_requests_disabled, false)
     and not ((public.is_platform_operator() or public.is_any_staff() or public.is_company_admin())
              and coalesce(public.can_access_association(new.association_id), false)) then
    raise exception 'This association does not take architectural requests online. Please contact your management office.'
      using errcode = '42501';
  end if;
  if new.committee_id is null then
    new.committee_id := s.default_committee_id;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."apply_architectural_review_settings"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_assessment_update"("p_association_id" "uuid", "p_fiscal_year" integer, "p_budget_gl_account_id" "uuid", "p_charge_category_id" "uuid", "p_method" "text", "p_frequency" "text", "p_effective_date" "date") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_portfolio uuid;
  v_cat record;
  w record;
  r record;
  v_increase uuid;
  n integer := 0;
  v_missing integer;
  v_units integer;
  v_total numeric := 0;
  v_annual numeric;
  v_later date;
begin
  if not public.can_mutate_association_budget(p_association_id) then
    raise exception 'Finance authorization required' using errcode = '42501';
  end if;
  select portfolio_id into v_portfolio from public.associations where id = p_association_id;
  if not exists (select 1 from public.association_budgets where association_id = p_association_id and fiscal_year = p_fiscal_year and status = 'adopted') then
    raise exception 'Adopt the FY% budget before updating assessments', p_fiscal_year using errcode = '55000';
  end if;
  select * into v_cat from public.charge_categories
   where id = p_charge_category_id and active and archived_at is null
     and (portfolio_id is null or portfolio_id = v_portfolio)
     and (association_id is null or association_id = p_association_id);
  if not found then raise exception 'Choose an active charge category for this association' using errcode = '22023'; end if;
  if v_cat.charge_type::text not in ('assessment', 'special_assessment') then
    raise exception 'The charge category must be an assessment' using errcode = '22023';
  end if;
  select * into w from public.association_fiscal_window(p_association_id, p_fiscal_year);
  if p_effective_date is null or p_effective_date < current_date or p_effective_date > w.period_end then
    raise exception 'The effective date must be between today and the end of FY% (%)', p_fiscal_year, w.period_end using errcode = '22023';
  end if;

  select count(*), count(*) filter (where a.period_amount is null), max(a.budget_annual) into v_units, v_missing, v_annual
    from public.assessment_allocation(p_association_id, p_fiscal_year, p_budget_gl_account_id, p_charge_category_id, p_method, p_frequency) a;
  if v_units = 0 then raise exception 'This association has no active units' using errcode = '22023'; end if;
  if v_missing > 0 then
    raise exception '% unit(s) have no % — fix the unit records or choose another method', v_missing,
      case p_method when 'sqft' then 'square footage' else 'ownership percentage' end using errcode = '22023';
  end if;
  if v_annual <= 0 then raise exception 'The budgeted amount must be greater than zero' using errcode = '22023'; end if;

  perform pg_advisory_xact_lock(hashtext('assessment_update:' || p_association_id::text));
  -- The same update twice (a double submit) changes nothing.
  if exists (select 1 from public.unit_recurring_charges rc
               join public.units un on un.id = rc.unit_id
               join public.buildings bd on bd.id = un.building_id
              where bd.association_id = p_association_id and rc.charge_category_id = p_charge_category_id
                and rc.active and rc.identifier = 'budget:' || p_fiscal_year and rc.start_date = p_effective_date) then
    raise exception 'The FY% assessments are already applied from %', p_fiscal_year, p_effective_date using errcode = '23505';
  end if;
  -- Never end a schedule that starts later (e.g. next year's): apply in date order.
  select min(rc.start_date) into v_later
    from public.unit_recurring_charges rc
    join public.units un on un.id = rc.unit_id
    join public.buildings bd on bd.id = un.building_id
   where bd.association_id = p_association_id and rc.charge_category_id = p_charge_category_id
     and rc.active and rc.start_date > p_effective_date;
  if v_later is not null then
    raise exception 'Assessments in this charge are already scheduled from %. Apply budgets in date order, or end that schedule first.', v_later using errcode = '55000';
  end if;

  insert into public.dues_increases (portfolio_id, association_id, name, status, effective_date, notes, posted_at, posted_by, created_by)
  values (v_portfolio, p_association_id, format('FY%s assessments', p_fiscal_year), 'posted', p_effective_date,
          format('From the adopted FY%s budget; %s allocation, billed %s.', p_fiscal_year, replace(p_method, '_', ' '), p_frequency),
          now(), auth.uid(), auth.uid())
  returning id into v_increase;

  for r in select * from public.assessment_allocation(p_association_id, p_fiscal_year, p_budget_gl_account_id, p_charge_category_id, p_method, p_frequency) loop
    update public.unit_recurring_charges rc
       set active = case when rc.start_date >= p_effective_date then false else rc.active end,
           end_date = case when rc.start_date >= p_effective_date then rc.start_date else p_effective_date - 1 end,
           updated_at = now()
     where rc.unit_id = r.unit_id and rc.charge_category_id = p_charge_category_id and rc.active
       and (rc.end_date is null or rc.end_date >= p_effective_date);

    if r.period_amount > 0 then
      insert into public.unit_recurring_charges (unit_id, charge_category_id, amount, frequency, start_date, next_post_date, memo, active, created_by, identifier)
      values (r.unit_id, p_charge_category_id, r.period_amount, p_frequency::public.recurring_frequency, p_effective_date, p_effective_date,
              format('FY%s %s', p_fiscal_year, v_cat.name), true, auth.uid(), 'budget:' || p_fiscal_year);
    end if;

    update public.occupancies
       set dues_amount = r.period_amount,
           dues_frequency = p_frequency::public.recurring_frequency,
           last_dues_increase_date = p_effective_date,
           last_dues_increase_amount = r.period_amount - coalesce(dues_amount, 0),
           updated_at = now()
     where unit_id = r.unit_id and status::text = 'current' and occupancy_type::text = 'owner';
    if r.occupancy_id is not null then
      insert into public.dues_increase_lines (dues_increase_id, occupancy_id, unit_id, old_amount, new_amount, change_type, change_value)
      values (v_increase, r.occupancy_id, r.unit_id, coalesce(r.current_amount, 0), r.period_amount, 'flat', r.period_amount - coalesce(r.current_amount, 0));
    end if;
    n := n + 1;
    v_total := v_total + r.annual_amount;
  end loop;

  insert into public.audit_logs (portfolio_id, entity_type, entity_id, action, actor_id, actor_email, changes)
  values (v_portfolio, 'association', p_association_id, 'assessments_updated', auth.uid(), (select email from auth.users where id = auth.uid()),
          jsonb_build_object('fiscal_year', p_fiscal_year, 'dues_increase_id', v_increase, 'units', n, 'method', p_method,
                             'frequency', p_frequency, 'effective_date', p_effective_date, 'charge_category_id', p_charge_category_id,
                             'budgeted', v_annual, 'allocated', v_total));
  return v_increase;
end $$;


ALTER FUNCTION "public"."apply_assessment_update"("p_association_id" "uuid", "p_fiscal_year" integer, "p_budget_gl_account_id" "uuid", "p_charge_category_id" "uuid", "p_method" "text", "p_frequency" "text", "p_effective_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_credits"("p_association_id" "uuid", "p_unit_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_pid uuid;
  c record;
  res jsonb;
  v_applied numeric := 0;
  v_payments integer := 0;
  v_charge_ids uuid[];
begin
  select portfolio_id into v_pid from public.associations where id = p_association_id and archived_at is null;
  if v_pid is null or not public.can_manage_finance(v_pid) or not public.can_manage_association(p_association_id) then
    raise exception 'You do not have accounting access to this association' using errcode = '42501';
  end if;
  if p_unit_id is not null and not exists (
       select 1 from public.units u join public.buildings b on b.id = u.building_id
        where u.id = p_unit_id and b.association_id = p_association_id) then
    raise exception 'That unit is not in this association' using errcode = '22023';
  end if;

  for c in
    select v.payment_id, v.unit_id, bd.period_from, bd.period_to
      from public.v_unapplied_credits v
      join public.units u on u.id = v.unit_id
      join public.buildings b on b.id = u.building_id
      cross join lateral public.app_ownership_bounds(v.unit_id, v.payment_date) bd
     where b.association_id = p_association_id
       and (p_unit_id is null or v.unit_id = p_unit_id)
       and v.unapplied_amount > 0.005
       and bd.period_to = 'infinity'::date
     order by v.unit_id, v.payment_date, v.payment_id
  loop
    select array_agg(cb.charge_id order by cb.due_date, ch.created_at, cb.charge_id) into v_charge_ids
      from public.v_charge_balances cb join public.charges ch on ch.id = cb.charge_id
     where cb.unit_id = c.unit_id and cb.balance_due > 0.005
       and coalesce(cb.due_date, ch.created_at::date) >= c.period_from
       and coalesce(cb.due_date, ch.created_at::date) < c.period_to;
    continue when v_charge_ids is null;
    res := public.apply_payment(c.payment_id, 'auto_specific', v_charge_ids);
    if coalesce((res ->> 'applied_total')::numeric, 0) > 0 then
      v_applied := v_applied + (res ->> 'applied_total')::numeric;
      v_payments := v_payments + 1;
    end if;
  end loop;

  insert into public.audit_logs (portfolio_id, entity_type, entity_id, action, actor_id, actor_email, changes)
  values (v_pid, 'association', p_association_id, 'credits_applied', auth.uid(), (select email from auth.users where id = auth.uid()),
          jsonb_build_object('unit_id', p_unit_id, 'payments', v_payments, 'applied_total', v_applied));
  return jsonb_build_object('payments', v_payments, 'applied_total', round(v_applied, 2));
end $$;


ALTER FUNCTION "public"."apply_credits"("p_association_id" "uuid", "p_unit_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_delinquency_jurisdiction"("p_association_id" "uuid", "p_state_code" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_portfolio uuid;
  v_code text := upper(btrim(coalesce(p_state_code, '')));
  v_rule record;
  v_policy uuid;
begin
  select portfolio_id into v_portfolio from public.associations where id = p_association_id;
  if v_portfolio is null then raise exception 'Association not found'; end if;
  if not (public.can_admin_portfolio(v_portfolio) or public.is_platform_operator()) then
    raise exception 'Only a portfolio administrator may change collection compliance settings';
  end if;

  select x.* into v_rule from (
    select r.state_code, r.pre_referral_notice_days, r.notice_method, r.payment_plan_offer_required,
           r.payment_plan_min_months, r.board_vote_required, r.foreclosure_min_balance, r.foreclosure_min_months,
           'company'::text as source, 1 as rank
      from public.company_state_rules r
     where r.portfolio_id = v_portfolio and r.state_code = v_code
    union all
    select p.state_code, p.pre_referral_notice_days, p.notice_method, p.payment_plan_offer_required,
           p.payment_plan_min_months, p.board_vote_required, p.foreclosure_min_balance, p.foreclosure_min_months,
           'built_in'::text, 2
      from public.collection_jurisdiction_profiles p
     where p.state_code = v_code
    union all
    select p.state_code, p.pre_referral_notice_days, p.notice_method, p.payment_plan_offer_required,
           p.payment_plan_min_months, p.board_vote_required, p.foreclosure_min_balance, p.foreclosure_min_months,
           'built_in'::text, 3
      from public.collection_jurisdiction_profiles p
     where p.state_code = 'DEFAULT'
  ) x
  order by x.rank
  limit 1;
  if not found then raise exception 'No collection rules are set up'; end if;

  select id into v_policy from public.delinquency_policies where association_id = p_association_id;
  if v_policy is null then raise exception 'Initialize the association''s collection policy first'; end if;

  update public.delinquency_policies
     set jurisdiction = v_rule.state_code,
         pre_referral_notice_days = v_rule.pre_referral_notice_days,
         notice_method = v_rule.notice_method,
         payment_plan_offer_required = v_rule.payment_plan_offer_required,
         payment_plan_min_months = v_rule.payment_plan_min_months,
         board_vote_required = v_rule.board_vote_required,
         foreclosure_min_balance = v_rule.foreclosure_min_balance,
         foreclosure_min_months = v_rule.foreclosure_min_months,
         updated_at = now()
   where id = v_policy;

  insert into public.audit_logs (portfolio_id, entity_type, entity_id, action, actor_id, changes)
  values (v_portfolio, 'association', p_association_id, 'delinquency_jurisdiction_applied', auth.uid(),
          jsonb_build_object('jurisdiction', v_rule.state_code, 'source', v_rule.source));
  return v_rule.state_code;
end;
$$;


ALTER FUNCTION "public"."apply_delinquency_jurisdiction"("p_association_id" "uuid", "p_state_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_dues_increase"("p_association_id" "uuid", "p_charge_category_id" "uuid", "p_mode" "text", "p_value" numeric, "p_effective_date" "date", "p_apply" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_portfolio uuid;
  r record;
  v_new numeric;
  v_cycle date;
  v_step interval;
  v_guard integer;
  v_rows jsonb := '[]'::jsonb;
begin
  if auth.uid() is null then raise exception 'Authentication required' using errcode = '42501'; end if;
  select portfolio_id into v_portfolio from public.associations where id = p_association_id and archived_at is null;
  if v_portfolio is null or not public.can_manage_finance(v_portfolio) then
    raise exception 'Permission denied for this association' using errcode = '42501';
  end if;
  if not exists (select 1 from public.charge_categories c where c.id = p_charge_category_id and c.portfolio_id = v_portfolio) then
    raise exception 'Charge category is outside this portfolio' using errcode = '42501';
  end if;
  if p_mode is null or p_mode not in ('percent', 'amount', 'set') then raise exception 'Choose percent, amount, or set' using errcode = '22023'; end if;
  if p_value is null or (p_mode = 'set' and p_value <= 0) or (p_mode = 'percent' and (p_value <= -100 or p_value > 1000)) then
    raise exception 'Enter a valid increase' using errcode = '22023';
  end if;
  if p_effective_date is null then raise exception 'Enter the effective date' using errcode = '22023'; end if;

  for r in
    select urc.*, u.unit_number,
           (select o.full_name from public.occupancies occ join public.owners o on o.id = occ.owner_id
             where occ.unit_id = u.id and occ.status = 'current' and occ.occupancy_type = 'owner' order by occ.is_primary desc limit 1) as homeowner
      from public.unit_recurring_charges urc
      join public.units u on u.id = urc.unit_id and u.archived_at is null
      join public.buildings b on b.id = u.building_id and b.association_id = p_association_id
     where urc.active
       and urc.charge_category_id = p_charge_category_id
       and (urc.end_date is null or urc.end_date >= p_effective_date)
     order by u.unit_number
     for update of urc
  loop
    v_new := case p_mode
      when 'percent' then round(r.amount * (1 + p_value / 100), 2)
      when 'amount' then round(r.amount + p_value, 2)
      else round(p_value, 2)
    end;
    if v_new < 0 then raise exception 'Unit % would have a negative amount', r.unit_number using errcode = '22023'; end if;

    v_step := case r.frequency
      when 'daily' then interval '1 day' when 'weekly' then interval '1 week'
      when 'monthly' then interval '1 month' when 'quarterly' then interval '3 months'
      else interval '1 year' end;
    v_cycle := coalesce(r.next_post_date, r.start_date, p_effective_date);
    v_guard := 0;
    while v_cycle < p_effective_date and v_guard < 5000 loop
      v_cycle := public.recurring_next_date(v_cycle, r.frequency::text, 1, extract(day from coalesce(r.start_date, r.next_post_date, v_cycle))::integer);
      v_guard := v_guard + 1;
    end loop;
    continue when r.end_date is not null and r.end_date < v_cycle;

    v_rows := v_rows || jsonb_build_object(
      'recurring_id', r.id, 'unit_number', r.unit_number, 'homeowner', r.homeowner,
      'frequency', r.frequency::text, 'old_amount', r.amount, 'new_amount', v_new, 'first_new_post', v_cycle);

    if p_apply and v_new <> r.amount then
      if v_cycle <= coalesce(r.next_post_date, v_cycle) then
        update public.unit_recurring_charges set amount = v_new, updated_at = now() where id = r.id;
      else
        update public.unit_recurring_charges set end_date = v_cycle - 1, updated_at = now() where id = r.id;
        insert into public.unit_recurring_charges (
          unit_id, charge_category_id, amount, frequency, start_date, end_date, next_post_date, memo, identifier, active, created_by
        ) values (
          r.unit_id, r.charge_category_id, v_new, r.frequency, v_cycle, r.end_date, v_cycle, r.memo, r.identifier, true, auth.uid()
        );
      end if;
      update public.occupancies
         set last_dues_increase_date = p_effective_date,
             last_dues_increase_amount = v_new - r.amount,
             dues_amount = case when dues_amount = r.amount then v_new else dues_amount end,
             updated_at = now()
       where unit_id = r.unit_id and status = 'current' and occupancy_type = 'owner';
    end if;
  end loop;

  if p_apply then
    insert into public.audit_logs (portfolio_id, actor_id, action, entity_type, entity_id, changes)
    values (v_portfolio, auth.uid(), 'dues_increase', 'association', p_association_id,
            jsonb_build_object('charge_category_id', p_charge_category_id, 'mode', p_mode, 'value', p_value,
                               'effective_date', p_effective_date, 'schedules', jsonb_array_length(v_rows)));
  end if;
  return v_rows;
end;
$$;


ALTER FUNCTION "public"."apply_dues_increase"("p_association_id" "uuid", "p_charge_category_id" "uuid", "p_mode" "text", "p_value" numeric, "p_effective_date" "date", "p_apply" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_dues_increase_checked"("p_association_id" "uuid", "p_charge_category_id" "uuid", "p_mode" "text", "p_value" numeric, "p_effective_date" "date", "p_apply" boolean DEFAULT false, "p_expected" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_preview jsonb;
  v_now text[];
  v_expected text[];
begin
  if auth.uid() is null then raise exception 'Authentication required' using errcode = '42501'; end if;
  if not public.can_mutate_association_budget(p_association_id) then
    raise exception 'Permission denied for this association' using errcode = '42501';
  end if;
  if not exists (
    select 1 from public.charge_categories c
     where c.id = p_charge_category_id
       and c.active and c.archived_at is null
       and c.charge_type in ('assessment', 'special_assessment')
       and (c.association_id is null or c.association_id = p_association_id)
       and (c.portfolio_id is null or c.portfolio_id = (select a.portfolio_id from public.associations a where a.id = p_association_id))
  ) then
    raise exception 'Choose an active assessment charge for this association' using errcode = '22023';
  end if;

  v_preview := public.apply_dues_increase(p_association_id, p_charge_category_id, p_mode, p_value, p_effective_date, false);
  if not p_apply then return v_preview; end if;

  if p_expected is null or jsonb_typeof(p_expected) <> 'array' then
    raise exception 'Preview the increase before applying it' using errcode = '22023';
  end if;
  select coalesce(array_agg(k order by k), '{}') into v_expected
    from (select (e->>'recurring_id') || ':' || round((e->>'old_amount')::numeric, 2)::text as k
            from jsonb_array_elements(p_expected) e) x;
  select coalesce(array_agg(k order by k), '{}') into v_now
    from (select (e->>'recurring_id') || ':' || round((e->>'old_amount')::numeric, 2)::text as k
            from jsonb_array_elements(v_preview) e) x;
  if v_expected is distinct from v_now then
    raise exception 'The dues changed since you previewed (or this increase was already applied). Preview again before applying.' using errcode = '40001';
  end if;

  return public.apply_dues_increase(p_association_id, p_charge_category_id, p_mode, p_value, p_effective_date, true);
end;
$$;


ALTER FUNCTION "public"."apply_dues_increase_checked"("p_association_id" "uuid", "p_charge_category_id" "uuid", "p_mode" "text", "p_value" numeric, "p_effective_date" "date", "p_apply" boolean, "p_expected" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_late_fees"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare r record; n integer := 0;
begin
  for r in
    select c.id
      from public.charges c
      join public.units u on u.id = c.unit_id
      join public.buildings b on b.id = u.building_id
      join public.associations a on a.id = b.association_id
     where a.late_fee_enabled and a.archived_at is null
       and c.charge_type = 'assessment'
       and c.due_date < public.association_local_date(a.id) - coalesce(a.late_fee_grace_days, 0)
       and not exists (select 1 from public.late_fee_assessments l where l.charge_id = c.id)
  loop
    if public.assess_late_fee(r.id) is not null then n := n + 1; end if;
  end loop;
  return n;
end $$;


ALTER FUNCTION "public"."apply_late_fees"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_payment"("p_payment_id" "uuid", "p_strategy" "text" DEFAULT 'auto_oldest_first'::"text", "p_charge_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  pay public.payments;
  remaining numeric(14,2);
  charge_row record;
  to_apply numeric(14,2);
  applied_total numeric(14,2) := 0;
  applications_made jsonb := '[]'::jsonb;
  alloc_order text[];
  v_since date;
  v_from date := '-infinity';
  v_to date := 'infinity';
begin
  select * into pay from public.payments where id = p_payment_id for update;
  if not found then raise exception 'payment % not found', p_payment_id; end if;
  perform pg_advisory_xact_lock(hashtextextended('unit-apply:' || pay.unit_id::text, 0));

  remaining := pay.amount - coalesce(
    (select sum(amount_applied) from public.payment_applications where payment_id = p_payment_id),
    0
  );

  if remaining <= 0 then
    return jsonb_build_object(
      'payment_id', p_payment_id,
      'applied_total', 0,
      'remaining', 0,
      'note', 'payment is already fully applied'
    );
  end if;

  -- One ownership period: the ownership that covers the payment date.
  select b.period_from, b.period_to into v_from, v_to
    from public.app_ownership_bounds(pay.unit_id, coalesce(pay.payment_date, current_date)) b;

  if p_strategy = 'association_policy' then
    select a.payment_allocation_order into alloc_order
      from public.units u
      join public.buildings b on b.id = u.building_id
      join public.associations a on a.id = b.association_id
     where u.id = pay.unit_id;
    if alloc_order is null then
      alloc_order := array['late_fee','nsf_fee','fine','interest','legal','special_assessment','assessment','other'];
    end if;

    for charge_row in
      select c.id as charge_id,
             (c.amount - coalesce((select sum(amount_applied) from public.payment_applications where charge_id = c.id), 0)) as bal
        from public.charges c
       where c.unit_id = pay.unit_id
         and coalesce(c.due_date, c.created_at::date) >= v_from and coalesce(c.due_date, c.created_at::date) < v_to
         and (c.amount - coalesce((select sum(amount_applied) from public.payment_applications where charge_id = c.id), 0)) > 0
       order by
         coalesce(array_position(alloc_order, c.charge_type::text), 999),
         c.due_date, c.created_at
    loop
      exit when remaining <= 0;
      to_apply := least(remaining, charge_row.bal);
      if to_apply > 0 then
        insert into public.payment_applications (payment_id, charge_id, amount_applied, applied_by, application_method)
        values (p_payment_id, charge_row.charge_id, to_apply, auth.uid(), 'association_policy');
        remaining := remaining - to_apply;
        applied_total := applied_total + to_apply;
        applications_made := applications_made || jsonb_build_object('charge_id', charge_row.charge_id, 'amount', to_apply);
      end if;
    end loop;

  elsif p_strategy = 'auto_late_fees_first' then
    for charge_row in
      select c.id as charge_id, c.charge_type, c.due_date,
             (c.amount - coalesce((select sum(amount_applied) from public.payment_applications where charge_id = c.id), 0)) as bal
        from public.charges c
       where c.unit_id = pay.unit_id
         and coalesce(c.due_date, c.created_at::date) >= v_from and coalesce(c.due_date, c.created_at::date) < v_to
         and (c.amount - coalesce((select sum(amount_applied) from public.payment_applications where charge_id = c.id), 0)) > 0
       order by
         case c.charge_type
           when 'late_fee' then 1
           when 'nsf_fee' then 2
           when 'fine' then 3
           when 'assessment' then 4
           when 'special_assessment' then 5
           else 9
         end,
         c.due_date
    loop
      exit when remaining <= 0;
      to_apply := least(remaining, charge_row.bal);
      if to_apply > 0 then
        insert into public.payment_applications (payment_id, charge_id, amount_applied, applied_by, application_method)
        values (p_payment_id, charge_row.charge_id, to_apply, auth.uid(), 'auto_late_fees_first');
        remaining := remaining - to_apply;
        applied_total := applied_total + to_apply;
        applications_made := applications_made || jsonb_build_object('charge_id', charge_row.charge_id, 'amount', to_apply);
      end if;
    end loop;

  elsif p_strategy = 'auto_specific' then
    if p_charge_ids is null or array_length(p_charge_ids, 1) is null then
      raise exception 'auto_specific strategy requires p_charge_ids';
    end if;
    for charge_row in
      select c.id as charge_id,
             (c.amount - coalesce((select sum(amount_applied) from public.payment_applications where charge_id = c.id), 0)) as bal
        from public.charges c
       where c.unit_id = pay.unit_id
         and c.id = any(p_charge_ids)
         and (c.amount - coalesce((select sum(amount_applied) from public.payment_applications where charge_id = c.id), 0)) > 0
       order by array_position(p_charge_ids, c.id)
    loop
      exit when remaining <= 0;
      to_apply := least(remaining, charge_row.bal);
      if to_apply > 0 then
        insert into public.payment_applications (payment_id, charge_id, amount_applied, applied_by, application_method)
        values (p_payment_id, charge_row.charge_id, to_apply, auth.uid(), 'auto_specific');
        remaining := remaining - to_apply;
        applied_total := applied_total + to_apply;
        applications_made := applications_made || jsonb_build_object('charge_id', charge_row.charge_id, 'amount', to_apply);
      end if;
    end loop;

  else
    for charge_row in
      select c.id as charge_id,
             (c.amount - coalesce((select sum(amount_applied) from public.payment_applications where charge_id = c.id), 0)) as bal
        from public.charges c
       where c.unit_id = pay.unit_id
         and coalesce(c.due_date, c.created_at::date) >= v_from and coalesce(c.due_date, c.created_at::date) < v_to
         and (c.amount - coalesce((select sum(amount_applied) from public.payment_applications where charge_id = c.id), 0)) > 0
       order by c.due_date, c.created_at
    loop
      exit when remaining <= 0;
      to_apply := least(remaining, charge_row.bal);
      if to_apply > 0 then
        insert into public.payment_applications (payment_id, charge_id, amount_applied, applied_by, application_method)
        values (p_payment_id, charge_row.charge_id, to_apply, auth.uid(), 'auto_oldest_first');
        remaining := remaining - to_apply;
        applied_total := applied_total + to_apply;
        applications_made := applications_made || jsonb_build_object('charge_id', charge_row.charge_id, 'amount', to_apply);
      end if;
    end loop;
  end if;

  return jsonb_build_object(
    'payment_id', p_payment_id,
    'strategy', p_strategy,
    'applied_total', applied_total,
    'remaining_credit', remaining,
    'applications', applications_made
  );
end;
$$;


ALTER FUNCTION "public"."apply_payment"("p_payment_id" "uuid", "p_strategy" "text", "p_charge_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."apply_payment"("p_payment_id" "uuid", "p_strategy" "text", "p_charge_ids" "uuid"[]) IS 'Applies a payment to outstanding charges. Strategies: auto_oldest_first (HOA default), auto_late_fees_first (pay fees before assessments), auto_specific (caller provides charge list). Leftover becomes an unapplied credit.';



CREATE OR REPLACE FUNCTION "public"."apply_pending_invitation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_invitation public.user_invitations%rowtype;
  v_invitation_id uuid;
  v_assoc_id uuid;
  v_tenant_id uuid;
begin
  begin
    v_invitation_id := nullif(new.raw_user_meta_data ->> 'invitation_id', '')::uuid;
  exception when invalid_text_representation then
    raise exception 'Invalid invitation reference';
  end;

  -- A matching email is not an invitation credential. Every current invite
  -- flow binds the exact invitation id into Auth metadata; unbound signups
  -- must never claim whichever pending invitation happens to share an email.
  if v_invitation_id is null then
    return new;
  end if;

  select *
    into v_invitation
  from public.user_invitations
  where id = v_invitation_id
    and lower(email) = lower(new.email)
    and status = 'pending'
    and expires_at > now();

  if not found then
    raise exception 'Invitation is invalid, expired, or belongs to another email';
  end if;

  if v_invitation.hoa_role = 'tenant' then
    select t.id
      into v_tenant_id
    from public.tenants t
    where t.portfolio_id = v_invitation.portfolio_id
      and t.unit_id = v_invitation.unit_id
      and lower(t.email) = lower(new.email)
      and t.status = 'active'
      and t.archived_at is null
      and (t.auth_user_id is null or t.auth_user_id = new.id)
    order by t.created_at desc
    limit 1;

    if v_tenant_id is null then
      raise exception 'Resident invitation does not match an active tenant record';
    end if;
  end if;

  insert into public.profiles (id, email, full_name, portfolio_id, mvp_role, hoa_role)
  values (
    new.id,
    new.email,
    coalesce(v_invitation.full_name, ''),
    v_invitation.portfolio_id,
    v_invitation.mvp_role,
    v_invitation.hoa_role
  )
  on conflict (id) do update
    set portfolio_id = excluded.portfolio_id,
        mvp_role     = excluded.mvp_role,
        hoa_role     = excluded.hoa_role,
        full_name    = coalesce(nullif(excluded.full_name, ''), public.profiles.full_name);

  if (v_invitation.hoa_role = 'manager'
      or v_invitation.mvp_role in ('manager', 'assistant_manager'))
     and array_length(v_invitation.association_ids, 1) > 0 then
    foreach v_assoc_id in array v_invitation.association_ids loop
      insert into public.association_managers (
        user_id, association_id, portfolio_id, assigned_by, assigned_at
      ) values (
        new.id, v_assoc_id, v_invitation.portfolio_id, v_invitation.invited_by, now()
      )
      on conflict (user_id, association_id) do nothing;
    end loop;
  end if;

  if v_tenant_id is not null then
    update public.tenants
       set auth_user_id = new.id,
           portal_activated = true,
           updated_at = now()
     where id = v_tenant_id;
  end if;

  update public.user_invitations
     set status = 'accepted',
         used_at = now(),
         used_by = new.id,
         accepted_at = coalesce(accepted_at, now()),
         updated_at = now()
   where id = v_invitation.id;

  return new;
end;
$$;


ALTER FUNCTION "public"."apply_pending_invitation"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."apply_pending_invitation"() IS 'Trigger function: when a user signs up, finds the most recent pending invitation for their email and applies portfolio_id + mvp_role + association assignments. Marks the invitation accepted.';



CREATE OR REPLACE FUNCTION "public"."apply_twilio_sms_status"("p_provider_message_id" "text", "p_status" "public"."sms_status", "p_error_code" "text" DEFAULT NULL::"text", "p_error_message" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if coalesce(auth.role(), '') <> 'service_role' then raise exception 'Service role required'; end if;
  update public.sms_messages message
  set status = p_status,
      delivered_at = case when p_status = 'delivered' then coalesce(message.delivered_at, now()) else message.delivered_at end,
      error_code = p_error_code,
      error_message = left(p_error_message, 1000),
      locked_at = null
  where message.provider = 'twilio'
    and message.provider_message_id = p_provider_message_id
    and (
      message.error_code = 'provider_outcome_unknown'
      or message.status = p_status
      or (case p_status when 'queued' then 1 when 'sent' then 2 when 'delivered' then 3 when 'failed' then 3 when 'undelivered' then 3 else 0 end)
         >
         (case message.status when 'queued' then 1 when 'sent' then 2 when 'delivered' then 3 when 'failed' then 3 when 'undelivered' then 3 else 0 end)
    );
end;
$$;


ALTER FUNCTION "public"."apply_twilio_sms_status"("p_provider_message_id" "text", "p_status" "public"."sms_status", "p_error_code" "text", "p_error_message" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_vendor_credit"("p_credit_id" "uuid", "p_bill_id" "uuid", "p_amount" numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  c public.vendor_credits;
  b public.payable_bills;
  v_amt numeric := round(p_amount, 2);
  v_left numeric;
begin
  select * into c from public.vendor_credits where id = p_credit_id for update;
  if c.id is null or not (public.can_manage_finance(c.portfolio_id) and public.can_manage_association(c.association_id)) then
    raise exception 'Credit not found' using errcode = '42501';
  end if;
  if c.credit_date > coalesce(public.association_local_date(c.association_id, now()), current_date) then
    raise exception 'This credit is dated %; it can be applied on or after that date', c.credit_date using errcode = '22023';
  end if;
  select * into b from public.payable_bills where id = p_bill_id for update;
  if b.id is null or b.vendor_id <> c.vendor_id or b.association_id is distinct from c.association_id or b.portfolio_id <> c.portfolio_id then
    raise exception 'Apply the credit to a bill from the same vendor and association' using errcode = '22023';
  end if;
  if b.status <> 'approved'::public.payable_bill_status or b.paid_at is not null or b.check_number is not null or b.archived_at is not null then
    raise exception 'Credits can only be applied to approved, unpaid bills' using errcode = '22023';
  end if;
  v_left := b.amount - b.credit_applied;
  if v_amt is null or v_amt <= 0 then raise exception 'Enter an amount greater than zero' using errcode = '22023'; end if;
  if v_amt > c.amount - c.applied_amount then raise exception 'Only % of this credit is left', c.amount - c.applied_amount using errcode = '22023'; end if;
  if v_amt > v_left then raise exception 'Only % is still owed on this bill', v_left using errcode = '22023'; end if;
  perform public.ensure_payable_bill_accrual(b.id);

  insert into public.vendor_credit_applications (credit_id, bill_id, amount, applied_by) values (c.id, b.id, v_amt, auth.uid());
  update public.vendor_credits set applied_amount = applied_amount + v_amt where id = c.id;
  if v_amt = v_left then
    update public.payable_bills
       set credit_applied = credit_applied + v_amt, status = 'paid'::public.payable_bill_status,
           paid_at = (coalesce(public.association_local_date(b.association_id, now()), current_date)::timestamp + interval '12 hours') at time zone 'UTC',
           updated_at = now()
     where id = b.id;
  else
    update public.payable_bills set credit_applied = credit_applied + v_amt, updated_at = now() where id = b.id;
  end if;
  return jsonb_build_object('applied', v_amt, 'bill_remaining', v_left - v_amt, 'credit_remaining', c.amount - c.applied_amount - v_amt);
end $$;


ALTER FUNCTION "public"."apply_vendor_credit"("p_credit_id" "uuid", "p_bill_id" "uuid", "p_amount" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approval_requests_approve_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if new.status = 'approved'::public.approval_request_status
     and (tg_op = 'INSERT' or old.status is distinct from 'approved'::public.approval_request_status)
     and coalesce(current_setting('app.approval_decision', true), '') <> 'on'
     and not public.app_is_repair_session() then
    raise exception 'Record the board''s decision on the approval request to approve it' using errcode = '42501';
  end if;
  return new;
end
$$;


ALTER FUNCTION "public"."approval_requests_approve_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approval_requests_decision_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if current_user not in ('authenticated', 'anon')
     or coalesce(current_setting('app.approval_decision', true), '') = 'on' then
    if tg_op = 'DELETE' then return old; end if;
    return new;
  end if;
  if tg_op = 'DELETE' then
    raise exception 'Approval requests can''t be deleted' using errcode = '42501';
  end if;
  if new.status is distinct from old.status
     or new.required_votes is distinct from old.required_votes
     or new.voting_scheme is distinct from old.voting_scheme
     or new.board_member_ids is distinct from old.board_member_ids
     or new.percentage_required is distinct from old.percentage_required
     or new.signatures_required is distinct from old.signatures_required
     or new.amount is distinct from old.amount
     or new.votes_for is distinct from old.votes_for
     or new.votes_against is distinct from old.votes_against
     or new.votes_abstain is distinct from old.votes_abstain
     or new.decision_by is distinct from old.decision_by
     or new.decision_at is distinct from old.decision_at
     or new.archived_at is distinct from old.archived_at
     or new.request_type is distinct from old.request_type
     or new.association_id is distinct from old.association_id
     or new.portfolio_id is distinct from old.portfolio_id
     or new.vendor_id is distinct from old.vendor_id
     or new.owner_id is distinct from old.owner_id
     or new.unit_id is distinct from old.unit_id
     -- approval_request_decided_context: once decided, what the board decided
     -- on (title, scope, due date, evidence, requester) is history too.
     or (old.status is distinct from 'pending'::public.approval_request_status
         and (new.notes is distinct from old.notes
              or new.title is distinct from old.title
              or new.description is distinct from old.description
              or new.due_date is distinct from old.due_date
              or new.attachments is distinct from old.attachments
              or new.requested_by_name is distinct from old.requested_by_name
              or new.requested_by_email is distinct from old.requested_by_email
              or new.requested_at is distinct from old.requested_at)) then
    raise exception 'Record the board''s decision from the bill or purchase order page' using errcode = '42501';
  end if;
  return new;
end
$$;


ALTER FUNCTION "public"."approval_requests_decision_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approval_requests_owner_identity"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if auth.uid() is not null and new.owner_id is not null and not public.can_access_portfolio(new.portfolio_id) then
    select coalesce(nullif(btrim(p.full_name), ''), nullif(btrim(p.display_name), ''), p.email), p.email
      into new.requested_by_name, new.requested_by_email
      from public.profiles p where p.id = auth.uid();
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."approval_requests_owner_identity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_owner_payable"("p_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  r public.owner_payables := public.app_owner_payable_for_update(p_id);
  v_ap uuid;
  v_entry uuid;
  v_owner text := (select full_name from public.owners where id = r.owner_id);
begin
  if r.status not in ('draft', 'pending_approval') then
    raise exception 'Only a payable waiting for approval can be approved' using errcode = '22023';
  end if;
  if r.gl_account_id is null then raise exception 'Choose the GL account this payable is charged to before approving' using errcode = '22023'; end if;
  v_ap := public.app_ap_account(r.portfolio_id, r.association_id);
  if v_ap is null then raise exception 'No active Accounts Payable GL account is configured' using errcode = '22023'; end if;

  insert into public.journal_entries (portfolio_id, entry_date, description, memo, reference_number, source_type, source_id, created_by, posted, posted_at)
  values (r.portfolio_id, coalesce(r.payable_date, current_date), 'Homeowner payable: ' || coalesce(v_owner, 'homeowner'), r.memo,
          r.payable_number, 'owner_payable', r.id, auth.uid(), true, now())
  returning id into v_entry;
  insert into public.journal_lines (entry_id, association_id, gl_account_id, debit_amount, credit_amount, memo, sort_order)
  values (v_entry, r.association_id, r.gl_account_id, r.amount, 0, r.memo, 1),
         (v_entry, r.association_id, v_ap, 0, r.amount, r.memo, 2);

  update public.owner_payables set status = 'approved', approved_by = auth.uid(), approved_at = now(), updated_at = now() where id = r.id;
  insert into public.audit_logs (portfolio_id, entity_type, entity_id, action, actor_id, changes)
  values (r.portfolio_id, 'owner_payable', r.id, 'approved', auth.uid(), jsonb_build_object('amount', r.amount));
  return v_entry;
end $$;


ALTER FUNCTION "public"."approve_owner_payable"("p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_payable_bill"("p_bill_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  entry_id uuid;
  bill_row public.payable_bills;
  request_status public.approval_request_status;
begin
  select * into bill_row from public.payable_bills where id = p_bill_id for update;
  if not found then raise exception 'Bill not found'; end if;
  if not public.can_manage_finance(bill_row.portfolio_id) then raise exception 'Permission denied'; end if;
  if not public.can_view_association_row(bill_row.association_id) then raise exception 'Bill not found'; end if;
  if not public.operator_may_write(false) then raise exception 'Permission denied'; end if;
  if bill_row.status not in ('pending_approval'::public.payable_bill_status, 'approved'::public.payable_bill_status) then
    raise exception 'Only submitted, unpaid bills can be approved';
  end if;
  if bill_row.approval_required then
    if bill_row.approval_request_id is null then raise exception 'Board approval has not been requested'; end if;
    select status into request_status from public.approval_requests
     where id = bill_row.approval_request_id
       and portfolio_id = bill_row.portfolio_id
       and association_id = bill_row.association_id;
    if request_status is distinct from 'approved'::public.approval_request_status then
      raise exception 'Board approval is not complete';
    end if;
  end if;
  update public.payable_bills
     set status = 'approved'::public.payable_bill_status,
         approved_at = coalesce(approved_at, now()),
         approved_by = coalesce(approved_by, auth.uid()),
         updated_at = now()
   where id = p_bill_id;
  entry_id := public.ensure_payable_bill_accrual(p_bill_id);
  return entry_id;
end;
$$;


ALTER FUNCTION "public"."approve_payable_bill"("p_bill_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."arc_append_attachment"("p_request_id" "uuid", "p_association_id" "uuid", "p_attachment" "jsonb", "p_max" integer) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v public.architectural_requests;
  v_list jsonb;
  v_path text := p_attachment ->> 'path';
  v_max integer := coalesce(p_max, 10);
begin
  if v_path is null
     or v_path not like 'architectural/' || p_request_id::text || '/%'
     or position('..' in v_path) > 0 or position(chr(92) in v_path) > 0 then
    raise exception 'Invalid document reference' using errcode = '22023';
  end if;
  select * into v from public.architectural_requests
   where id = p_request_id and association_id = p_association_id for update;
  if not found then raise exception 'Request not found' using errcode = 'P0002'; end if;
  if v.status not in ('submitted', 'under_review', 'more_info') then
    raise exception 'Documents can only be added while the request is open' using errcode = '55000';
  end if;
  v_list := case when jsonb_typeof(v.attachments) = 'array' then v.attachments else '[]'::jsonb end;
  if exists (select 1 from jsonb_array_elements(v_list) e where e ->> 'path' = v_path) then
    return 'exists';
  end if;
  if jsonb_array_length(v_list) >= v_max then
    raise exception 'Limit of % documents reached', v_max using errcode = '54000';
  end if;
  update public.architectural_requests
     set attachments = v_list || jsonb_build_array(p_attachment)
   where id = p_request_id;
  return 'added';
end
$$;


ALTER FUNCTION "public"."arc_append_attachment"("p_request_id" "uuid", "p_association_id" "uuid", "p_attachment" "jsonb", "p_max" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."arc_remove_attachment"("p_request_id" "uuid", "p_association_id" "uuid", "p_path" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v public.architectural_requests;
  v_list jsonb;
begin
  select * into v from public.architectural_requests
   where id = p_request_id and association_id = p_association_id for update;
  if not found then raise exception 'Request not found' using errcode = 'P0002'; end if;
  if v.status not in ('submitted', 'under_review', 'more_info') then
    raise exception 'Documents can no longer be changed on a decided request' using errcode = '55000';
  end if;
  v_list := case when jsonb_typeof(v.attachments) = 'array' then v.attachments else '[]'::jsonb end;
  if not exists (select 1 from jsonb_array_elements(v_list) e where e ->> 'path' = p_path) then
    return false;
  end if;
  update public.architectural_requests
     set attachments = (select coalesce(jsonb_agg(e order by o), '[]'::jsonb)
                          from jsonb_array_elements(v_list) with ordinality t(e, o)
                         where e ->> 'path' is distinct from p_path)
   where id = p_request_id;
  return true;
end
$$;


ALTER FUNCTION "public"."arc_remove_attachment"("p_request_id" "uuid", "p_association_id" "uuid", "p_path" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."arch_msg_set_author"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_assoc uuid;
  v_owner uuid;
  v_is_owner boolean;
  v_is_staff boolean;
  v_name text;
begin
  -- arc_msg_author_v2: a trusted definer function (or the service role)
  -- writes as itself; only direct inserts by signed-in users are stamped.
  if current_user not in ('authenticated', 'anon') or auth.uid() is null then
    return new;
  end if;
  select r.association_id, r.owner_id into v_assoc, v_owner
    from public.architectural_requests r where r.id = new.request_id;
  v_is_owner := v_owner is not null and v_owner in (select public.current_owner_ids());
  v_is_staff := v_assoc is not null
    and (public.is_platform_operator() or public.is_any_staff() or public.is_company_admin())
    and coalesce(public.can_access_association(v_assoc), false);
  select nullif(btrim(p.full_name), '') into v_name from public.profiles p where p.id = auth.uid();
  new.author_id := auth.uid();
  new.created_at := now();
  if v_is_owner and (new.author_role = 'owner' or not v_is_staff) then
    -- The homeowner on their own request (a staff member who owns this unit
    -- and posts from the owner portal stays the homeowner).
    new.author_role := 'owner';
    new.author_name := coalesce(v_name, 'Owner');
  elsif v_is_staff then
    new.author_role := 'staff';
    new.author_name := coalesce(v_name, 'Staff');
  else
    -- Neither: the insert policies refuse it; never keep a claimed name.
    new.author_role := 'owner';
    new.author_name := coalesce(v_name, 'Owner');
  end if;
  return new;
end
$$;


ALTER FUNCTION "public"."arch_msg_set_author"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."architectural_requests_final_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_fk_columns text[] := array['owner_id', 'unit_id', 'committee_id', 'updated_at'];
begin
  if public.app_is_repair_session() then
    return new;
  end if;
  if tg_op = 'UPDATE' then
    if old.status in ('approved', 'denied', 'withdrawn') then
      -- A deleted owner, unit or committee sets its reference to null
      -- (ON DELETE SET NULL); nothing else may change.
      if (to_jsonb(new) - v_fk_columns) = (to_jsonb(old) - v_fk_columns)
         and (new.owner_id is null or new.owner_id = old.owner_id)
         and (new.unit_id is null or new.unit_id = old.unit_id)
         and (new.committee_id is null or new.committee_id = old.committee_id) then
        return new;
      end if;
      raise exception 'This request is already %; it can no longer be changed', old.status
        using errcode = '55000';
    end if;
    if new.status is distinct from old.status then
      if new.status = 'withdrawn'
         and not (old.owner_id is not null and old.owner_id in (select public.current_owner_ids())) then
        raise exception 'Only the homeowner can withdraw a request' using errcode = '42501';
      end if;
      if new.status in ('approved', 'denied') then
        new.decided_by := auth.uid();
        new.decided_at := now();
      end if;
    end if;
  end if;
  if new.status = 'denied'
     and (tg_op = 'INSERT' or old.status is distinct from 'denied')
     and nullif(btrim(coalesce(new.decision_notes, '')), '') is null then
    raise exception 'Give the homeowner a reason when denying a request' using errcode = '23514';
  end if;
  return new;
end
$$;


ALTER FUNCTION "public"."architectural_requests_final_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."architectural_requests_owner_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare n public.architectural_requests;
begin
  if pg_trigger_depth() > 1 or ((public.is_platform_operator() or public.is_any_staff() or public.is_company_admin())
         and coalesce(public.can_access_association(old.association_id), false))
     or old.owner_id is null or old.owner_id not in (select public.current_owner_ids()) then
    return new;
  end if;
  if new.status is distinct from old.status and new.status <> 'withdrawn' then
    raise exception 'You can only withdraw your own request' using errcode = '42501';
  end if;
  n := new;
  new := old;
  new.status := n.status;
  new.updated_at := now();
  return new;
end $$;


ALTER FUNCTION "public"."architectural_requests_owner_guard"() OWNER TO "postgres";


