CREATE OR REPLACE FUNCTION "public"."assemble_vendor_1099_data"("p_portfolio_id" "uuid", "p_tax_year" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$#variable_conflict use_column
begin
  return (select s.x from (

  select coalesce(jsonb_agg(to_jsonb(r.*) order by r.association_name, r.total_paid desc), '[]'::jsonb)
    from (
      select
        a.id as association_id,
        a.name as association_name,
        a.tax_id as payer_tax_id,
        v.id as vendor_id,
        v.name as vendor_name,
        v.taxpayer_name,
        vfd.taxpayer_id,
        v.address_street, v.address_city, v.address_state, v.address_zip,
        sum(pb.amount - coalesce(pb.credit_applied, 0)) as total_paid,
        count(*) filter (where pb.amount - coalesce(pb.credit_applied, 0) > 0) as bill_count,
        p_tax_year as tax_year
      from public.payable_bills pb
      join public.associations a on a.id = pb.association_id and a.portfolio_id = p_portfolio_id
      join public.vendors v on v.id = pb.vendor_id
      left join public.vendor_financial_details vfd on vfd.vendor_id = v.id
      where pb.status = 'paid'
        and pb.archived_at is null
        and pb.paid_at is not null
        and pb.paid_at >= make_date(p_tax_year, 1, 1)::timestamp at time zone 'UTC' - interval '2 days'
        and pb.paid_at <  make_date(p_tax_year + 1, 1, 1)::timestamp at time zone 'UTC' + interval '2 days'
        and pb.paid_at >= (make_date(p_tax_year, 1, 1)::timestamp at time zone coalesce(nullif(a.timezone, ''), 'America/Chicago'))
        and pb.paid_at <  (make_date(p_tax_year + 1, 1, 1)::timestamp at time zone coalesce(nullif(a.timezone, ''), 'America/Chicago'))
        and v.portfolio_id = p_portfolio_id
        and (auth.role() = 'service_role' or (auth.uid() is null and session_user <> 'authenticator') or public.can_manage_finance(p_portfolio_id) or public.is_platform_operator())
        and v.send_1099 = true
      group by a.id, a.name, a.tax_id, v.id, v.name, v.taxpayer_name, vfd.taxpayer_id,
               v.address_street, v.address_city, v.address_state, v.address_zip
      having sum(pb.amount - coalesce(pb.credit_applied, 0)) >= 600  -- IRS threshold, per payer
    ) r
  ) s(x) limit 1);
end$$;


ALTER FUNCTION "public"."assemble_vendor_1099_data"("p_portfolio_id" "uuid", "p_tax_year" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."assemble_vendor_1099_data"("p_portfolio_id" "uuid", "p_tax_year" integer) IS 'Returns per-vendor 1099-MISC data for a tax year: aggregate payments, taxpayer info, address. Only includes vendors with send_1099=true and >= $600 paid.';



CREATE OR REPLACE FUNCTION "public"."assess_association_interest"("p_as_of" "date" DEFAULT CURRENT_DATE) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  a record; u record;
  v_period date := date_trunc('month', p_as_of)::date;
  v_last_day integer := extract(day from (date_trunc('month', p_as_of) + interval '1 month - 1 day'))::integer;
  v_post_date date;
  v_cat uuid; v_charge uuid; v_amount numeric;
  n_assoc integer := 0; n_charges integer := 0; n_failed integer := 0; n_here integer;
  v_errors text[] := '{}';
begin
  for a in
    select id, portfolio_id, name, annual_interest_rate, coalesce(interest_grace_days, 0) grace_days,
           coalesce(interest_grace_balance, 0) grace_balance, interest_income_gl_account_id,
           least(greatest(coalesce(interest_post_day_of_month, 1), 1), v_last_day) post_day
      from public.associations
     where archived_at is null and coalesce(annual_interest_rate, 0) > 0
       and least(greatest(coalesce(interest_post_day_of_month, 1), 1), v_last_day) <= extract(day from p_as_of)::integer
  loop
    n_assoc := n_assoc + 1;
    v_post_date := v_period + (a.post_day - 1);
    n_here := 0;
    begin
      select id into v_cat from public.charge_categories c
       where c.portfolio_id = a.portfolio_id and c.active and c.archived_at is null
         and (upper(coalesce(c.code, '')) = 'INTEREST' or c.name ilike '%interest%')
       order by c.sort_order limit 1;
      for u in
        select un.id unit_id,
               sum(greatest(ch.amount - coalesce((select sum(pa.amount_applied)
                                                     from public.payment_applications pa
                                                     join public.payments p on p.id = pa.payment_id
                                                    where pa.charge_id = ch.id
                                                      and p.payment_date <= v_post_date), 0), 0)) principal
          from public.units un
          join public.buildings b on b.id = un.building_id
          cross join lateral (select (public.app_ownership_bounds(un.id, v_post_date)).period_from as owner_from offset 0) ob
          join public.charges ch on ch.unit_id = un.id and ch.due_date >= ob.owner_from
         where b.association_id = a.id and un.archived_at is null
           and ch.due_date < v_post_date - a.grace_days
           and ch.charge_type not in ('late_fee', 'nsf_fee')  -- interest on principal, not on fees
           and not exists (select 1 from public.interest_assessments ia where ia.charge_id = ch.id)
         group by un.id
      loop
        continue when u.principal <= a.grace_balance or u.principal <= 0;
        continue when exists (select 1 from public.interest_assessments ia where ia.unit_id = u.unit_id and ia.period_month = v_period);
        v_amount := round(u.principal * a.annual_interest_rate / 100.0 / 12.0, 2);
        continue when v_amount <= 0;
        insert into public.charges (unit_id, charge_category_id, charge_type, description, amount, due_date, gl_account_id)
        values (u.unit_id, v_cat, 'other',
                'Interest on past-due balance (' || to_char(a.annual_interest_rate, 'FM990.###') || '% APR, ' || to_char(v_period, 'Mon YYYY') || ')',
                v_amount, v_post_date + 15, a.interest_income_gl_account_id)
        returning id into v_charge;
        insert into public.interest_assessments (association_id, unit_id, period_month, principal, annual_rate, amount, charge_id)
        values (a.id, u.unit_id, v_period, round(u.principal, 2), a.annual_interest_rate, v_amount, v_charge);
        n_here := n_here + 1;
      end loop;
      n_charges := n_charges + n_here;
    exception when others then
      n_failed := n_failed + 1;
      v_errors := v_errors || (a.name || ': ' || sqlerrm);
    end;
  end loop;
  return jsonb_build_object('as_of', p_as_of, 'associations', n_assoc, 'charges', n_charges,
                            'failed', n_failed, 'errors', to_jsonb(v_errors));
end;
$$;


ALTER FUNCTION "public"."assess_association_interest"("p_as_of" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assess_late_fee"("p_charge_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_charge public.charges;
  v_assoc  public.associations;
  v_cat    public.charge_categories;
  v_balance numeric;
  v_fee     numeric;
  v_fee_charge public.charges;
  v_ovr record;
begin
  select * into v_charge from public.charges where id = p_charge_id;
  if not found then raise exception 'charge not found'; end if;

  select a.* into v_assoc
    from public.associations a
    join public.buildings b on b.association_id = a.id
    join public.units u on u.building_id = b.id
   where u.id = v_charge.unit_id;
  if not found then raise exception 'association not found for charge'; end if;

  if auth.uid() is not null and not public.can_manage_finance(v_assoc.portfolio_id) then
    raise exception 'permission denied';
  end if;

  if not v_assoc.late_fee_enabled or coalesce(v_assoc.late_fee_amount, 0) <= 0 then
    return null;
  end if;
  if v_charge.charge_type <> 'assessment' then
    return null;
  end if;
  if v_charge.due_date + coalesce(v_assoc.late_fee_grace_days, 0) >= public.association_local_date(v_assoc.id) then
    return null;
  end if;
  if exists (select 1 from public.late_fee_assessments where charge_id = p_charge_id) then
    return null;
  end if;

  v_balance := coalesce(v_charge.amount, 0) - coalesce(
    (select sum(pa.amount_applied) from public.payment_applications pa
      where pa.charge_id = p_charge_id), 0);
  if v_balance <= 0 then return null; end if;
  -- A previous owner's charge: a new owner has taken over the unit since, so
  -- a fee dated today would fall in (and be paid from) the new owner's period.
  if (public.app_ownership_bounds(v_charge.unit_id, v_charge.due_date)).period_to <= public.association_local_date(v_assoc.id) then
    return null;
  end if;

  select * into v_ovr from public.unit_late_fee_override(v_charge.unit_id);
  if coalesce(v_ovr.exempt, false) then
    return null;
  end if;

  v_fee := case
    when v_ovr.amount is not null and v_ovr.is_percent then round(v_balance * v_ovr.amount / 100.0, 2)
    when v_ovr.amount is not null then v_ovr.amount
    when v_assoc.late_fee_is_percent then round(v_balance * v_assoc.late_fee_amount / 100.0, 2)
    else v_assoc.late_fee_amount
  end;
  if v_fee is null or v_fee <= 0 then return null; end if;

  select * into v_cat
    from public.charge_categories
   where portfolio_id = v_assoc.portfolio_id
     and charge_type = 'late_fee'
     and active
     and archived_at is null
   order by sort_order
   limit 1;
  if v_cat.id is null then
    return null;
  end if;

  insert into public.charges (
    unit_id, charge_category_id, charge_type, description, amount, due_date, gl_account_id, created_by
  ) values (
    v_charge.unit_id, v_cat.id, 'late_fee',
    'Late fee — ' || coalesce(v_charge.description, 'assessment')
      || ' (due ' || to_char(v_charge.due_date, 'YYYY-MM-DD') || ')',
    v_fee, public.association_local_date(v_assoc.id), v_cat.gl_account_id, auth.uid()
  ) returning * into v_fee_charge;

  insert into public.late_fee_assessments (association_id, charge_id, fee_charge_id)
  values (v_assoc.id, p_charge_id, v_fee_charge.id);

  return v_fee_charge.id;
end $$;


ALTER FUNCTION "public"."assess_late_fee"("p_charge_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assessment_allocation"("p_association_id" "uuid", "p_fiscal_year" integer, "p_budget_gl_account_id" "uuid", "p_charge_category_id" "uuid", "p_method" "text", "p_frequency" "text") RETURNS TABLE("unit_id" "uuid", "unit_number" "text", "occupancy_id" "uuid", "owner_name" "text", "basis" numeric, "share_pct" numeric, "annual_amount" numeric, "period_amount" numeric, "current_amount" numeric, "current_frequency" "text", "budget_annual" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_annual numeric; v_periods integer;
begin
  if not public.can_mutate_association_budget(p_association_id) then
    raise exception 'Finance authorization required' using errcode = '42501';
  end if;
  if p_method not in ('ownership_pct', 'equal', 'sqft') then raise exception 'Unknown allocation method' using errcode = '22023'; end if;
  v_periods := case p_frequency when 'monthly' then 12 when 'quarterly' then 4 when 'annually' then 1 end;
  if v_periods is null then raise exception 'Frequency must be monthly, quarterly or annually' using errcode = '22023'; end if;

  select bl.annual_total into v_annual from public.budget_lines bl
   where bl.association_id = p_association_id and bl.fiscal_year = p_fiscal_year and bl.gl_account_id = p_budget_gl_account_id and bl.category = 'income';
  if v_annual is null then raise exception 'That income account has no line in the FY% budget', p_fiscal_year using errcode = '22023'; end if;

  return query
  with u as (
    select un.id, un.unit_number,
           case p_method when 'ownership_pct' then nullif(un.ownership_pct, 0)
                         when 'sqft' then nullif(un.sqft, 0)::numeric
                         else 1::numeric end as b
      from public.units un join public.buildings bd on bd.id = un.building_id
     where bd.association_id = p_association_id and un.archived_at is null
  ), tot as (
    select sum(b) as t, bool_and(b is not null) as complete from u
  ), raw as (
    select u.id, u.unit_number, u.b,
           case when tot.t > 0 and u.b is not null then round(v_annual * u.b / tot.t / v_periods, 2) end as p,
           tot.t, tot.complete,
           row_number() over (order by u.b desc nulls last, u.unit_number, u.id) as rn
      from u cross join tot
  ), fix as (
    -- What one billing period must add up to, and the cents rounding left over;
    -- the leftover goes to the unit with the largest share (only when every
    -- unit has a basis, so the totals are meant to add up).
    select round(v_annual / v_periods, 2) - coalesce(sum(p), 0) as leftover from raw
  ), alloc as (
    select raw.*, case when raw.p is not null and raw.rn = 1 and raw.complete then raw.p + fix.leftover else raw.p end as pa
      from raw cross join fix
  )
  select alloc.id, alloc.unit_number, occ.id, ow.full_name, alloc.b,
         case when alloc.t > 0 and alloc.b is not null then round(alloc.b / alloc.t * 100, 4) end,
         alloc.pa * v_periods,
         alloc.pa,
         cur.amount, cur.frequency::text, v_annual
    from alloc
    left join lateral (
      select o.id, o.owner_id from public.occupancies o
       where o.unit_id = alloc.id and o.status::text = 'current' and o.occupancy_type::text = 'owner'
       order by o.is_primary desc, o.move_in_date desc nulls last, o.created_at desc limit 1
    ) occ on true
    left join public.owners ow on ow.id = occ.owner_id
    left join lateral (
      select rc.amount, rc.frequency from public.unit_recurring_charges rc
       where rc.unit_id = alloc.id and rc.charge_category_id = p_charge_category_id and rc.active
         and (rc.end_date is null or rc.end_date >= current_date)
       order by rc.start_date desc limit 1
    ) cur on true
   order by alloc.unit_number;
end
$$;


ALTER FUNCTION "public"."assessment_allocation"("p_association_id" "uuid", "p_fiscal_year" integer, "p_budget_gl_account_id" "uuid", "p_charge_category_id" "uuid", "p_method" "text", "p_frequency" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assign_audit_log_portfolio"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if new.portfolio_id is null and new.actor_id is not null then
    select p.portfolio_id into new.portfolio_id
    from public.profiles p
    where p.id = new.actor_id;
  end if;

  if new.portfolio_id is null and new.entity_type = 'company' then
    select p.id into new.portfolio_id
    from public.portfolios p
    where p.id = new.entity_id;
  end if;

  if new.portfolio_id is null and new.entity_type = 'user' then
    select p.portfolio_id into new.portfolio_id
    from public.profiles p
    where p.id = new.entity_id;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."assign_audit_log_portfolio"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assign_message_thread"("p_thread" "uuid", "p_user" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare a record;
begin
  select * into a from public.message_thread_access(p_thread, 'staff');
  if p_user is not null and not public.can_be_assigned_message_thread(p_user, (a.thread).portfolio_id, (a.thread).association_id) then
    raise exception 'That person can''t see this association''s conversations' using errcode = '22023';
  end if;
  update public.message_threads set assigned_to = p_user where id = p_thread;
end $$;


