CREATE OR REPLACE FUNCTION "public"."assign_role"("p_profile_id" "uuid", "p_role_id" "uuid") RETURNS "public"."profiles"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  target public.profiles;
  target_role public.user_roles;
begin
  select * into target from public.profiles where id = p_profile_id;
  if not found then
    raise exception 'assign_role: profile % not found', p_profile_id;
  end if;

  if not public.can_admin_portfolio(target.portfolio_id) then
    raise exception 'assign_role: must be admin of profile''s portfolio';
  end if;

  if target.hoa_role is null or target.hoa_role::text not in ('manager', 'company_admin') then
    raise exception 'assign_role: staff roles can only be assigned to staff members (target is %)', coalesce(target.hoa_role::text, 'unknown');
  end if;

  select * into target_role from public.user_roles where id = p_role_id;
  if not found then
    raise exception 'assign_role: role % not found', p_role_id;
  end if;
  if target_role.portfolio_id is not null and target_role.portfolio_id <> target.portfolio_id then
    raise exception 'assign_role: role belongs to a different portfolio';
  end if;

  update public.profiles
     set role_id = p_role_id, updated_at = now()
   where id = p_profile_id
   returning * into target;
  return target;
end;
$$;


ALTER FUNCTION "public"."assign_role"("p_profile_id" "uuid", "p_role_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."association_fiscal_window"("p_association_id" "uuid", "p_fiscal_year" integer) RETURNS TABLE("period_start" "date", "period_end" "date")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  with m as (
    select coalesce(nullif(a.fiscal_year_start, 0), 1)::integer as start_month
      from public.associations a where a.id = p_association_id
  )
  select case when m.start_month = 1 then make_date(p_fiscal_year, 1, 1)
              else make_date(p_fiscal_year - 1, m.start_month, 1) end,
         (case when m.start_month = 1 then make_date(p_fiscal_year + 1, 1, 1)
               else make_date(p_fiscal_year, m.start_month, 1) end - 1)
    from m;
$$;


ALTER FUNCTION "public"."association_fiscal_window"("p_association_id" "uuid", "p_fiscal_year" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."association_fiscal_year_of"("p_association_id" "uuid", "p_date" "date") RETURNS integer
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$#variable_conflict use_column
begin
  return (select s.x from (

  select case
           when coalesce(nullif(a.fiscal_year_start, 0), 1) = 1 then extract(year from p_date)::int
           when extract(month from p_date)::int >= a.fiscal_year_start then extract(year from p_date)::int + 1
           else extract(year from p_date)::int
         end
    from public.associations a where a.id = p_association_id
  ) s(x) limit 1);
end$$;


ALTER FUNCTION "public"."association_fiscal_year_of"("p_association_id" "uuid", "p_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."association_loans_bind"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_portfolio uuid;
  v_moved boolean;
begin
  select portfolio_id into v_portfolio from public.associations where id = new.association_id;
  if v_portfolio is null then
    raise exception 'Association not found' using errcode = '23503';
  end if;
  new.portfolio_id := v_portfolio;
  v_moved := tg_op = 'INSERT' or new.association_id is distinct from old.association_id;
  if tg_op = 'UPDATE' and new.association_id is distinct from old.association_id
     and exists (select 1 from public.loan_payments p where p.loan_id = old.id) then
    raise exception 'This loan has recorded payments in its association''s ledger — it can''t be moved to another association' using errcode = '22023';
  end if;
  if new.gl_account_id is not null and (v_moved or new.gl_account_id is distinct from old.gl_account_id) and not exists (
       select 1 from public.gl_accounts g where g.id = new.gl_account_id and g.portfolio_id = v_portfolio
         and (g.association_id is null or g.association_id = new.association_id)
         and g.account_type::text = 'liability' and coalesce(g.active, true)) then
    raise exception 'The loan account must be an active liability account of this association' using errcode = '22023';
  end if;
  if new.interest_gl_account_id is not null and (v_moved or new.interest_gl_account_id is distinct from old.interest_gl_account_id) and not exists (
       select 1 from public.gl_accounts g where g.id = new.interest_gl_account_id and g.portfolio_id = v_portfolio
         and (g.association_id is null or g.association_id = new.association_id)
         and g.account_type::text in ('expense', 'other_expense') and coalesce(g.active, true)) then
    raise exception 'The interest account must be an active expense account of this association' using errcode = '22023';
  end if;
  if new.bank_account_id is not null and (v_moved or new.bank_account_id is distinct from old.bank_account_id) and not exists (
       select 1 from public.bank_accounts b where b.id = new.bank_account_id and b.portfolio_id = v_portfolio
         and (b.association_id is null or b.association_id = new.association_id) and b.archived_at is null) then
    raise exception 'The bank account must belong to this association' using errcode = '22023';
  end if;
  if tg_op = 'UPDATE' and new.current_balance is distinct from old.current_balance
     and coalesce(current_setting('app.loan_ledger', true), '') <> 'on'
     and exists (select 1 from public.loan_payments p where p.loan_id = old.id) then
    raise exception 'This loan has recorded payments — its balance changes only by recording or voiding a payment' using errcode = '22023';
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."association_loans_bind"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."association_local_date"("p_association_id" "uuid", "p_at" timestamp with time zone DEFAULT "now"()) RETURNS "date"
