CREATE OR REPLACE FUNCTION "public"."associations_move_vendor_portfolio"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  r record;
  v_bad boolean;
begin
  if exists (select 1 from public.vendors ven where ven.association_id = new.id) then
    raise exception 'This association has vendors. It cannot move to another company.'
      using errcode = '23514';
  end if;

  for r in select * from public.vendor_link_tables() loop
    execute format(
      'select exists (select 1 from %s x join public.vendors ven on ven.id = x.%I '
      || 'where x.association_id = $1 and ven.is_management_company and ven.portfolio_id is distinct from $2)',
      r.tbl, r.col) into v_bad using new.id, new.portfolio_id;
    if v_bad then
      raise exception 'This association has records that use the management company of its current company. It cannot move to another company.'
        using errcode = '23514';
    end if;
  end loop;
  for r in select * from public.vendor_parent_link_tables() loop
    execute format(
      'select exists (select 1 from %s x join %s p on p.id = x.%I join public.vendors ven on ven.id = x.%I '
      || 'where p.association_id = $1 and ven.is_management_company and ven.portfolio_id is distinct from $2)',
      r.tbl, r.parent, r.parent_col, r.col) into v_bad using new.id, new.portfolio_id;
    if v_bad then
      raise exception 'This association has records that use the management company of its current company. It cannot move to another company.'
        using errcode = '23514';
    end if;
  end loop;
  return new;
end;
$_$;


ALTER FUNCTION "public"."associations_move_vendor_portfolio"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."associations_payment_settings_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if current_user not in ('authenticated', 'anon') then
    return new;
  end if;
  if tg_op = 'INSERT' then
    if new.stripe_account_id is not null or coalesce(new.stripe_charges_enabled, false)
       or coalesce(new.stripe_payouts_enabled, false) or coalesce(new.stripe_details_submitted, false)
       or new.stripe_onboarded_at is not null or new.stripe_deauthorized_at is not null
       or new.stripe_disabled_reason is not null or new.stripe_last_status_at is not null then
      raise exception 'Online payment settings are set up from the association''s Payments tab' using errcode = '42501';
    end if;
  elsif new.stripe_account_id is distinct from old.stripe_account_id
     or new.stripe_charges_enabled is distinct from old.stripe_charges_enabled
     or new.stripe_payouts_enabled is distinct from old.stripe_payouts_enabled
     or new.stripe_details_submitted is distinct from old.stripe_details_submitted
     or new.stripe_onboarded_at is distinct from old.stripe_onboarded_at
     or new.stripe_deauthorized_at is distinct from old.stripe_deauthorized_at
     or new.stripe_disabled_reason is distinct from old.stripe_disabled_reason
     or new.stripe_last_status_at is distinct from old.stripe_last_status_at then
    raise exception 'Online payment settings are set up from the association''s Payments tab' using errcode = '42501';
  end if;

  if (tg_op = 'INSERT' and new.stripe_settlement_bank_account_id is not null)
     or (tg_op = 'UPDATE' and (
          new.payment_allocation_order is distinct from old.payment_allocation_order
       or new.stripe_settlement_bank_account_id is distinct from old.stripe_settlement_bank_account_id)) then
    if not (coalesce(public.is_finance_staff(), false)
            or coalesce(public.is_company_admin(), false)
            or coalesce(public.is_platform_operator(), false)) then
      raise exception 'Only finance staff can change how payments are applied or settled' using errcode = '42501';
    end if;
  end if;

  -- Where owners send Zelle payments: finance staff, company admins, operators.
  if (tg_op = 'INSERT' and (new.zelle_recipient is not null or new.zelle_recipient_name is not null))
     or (tg_op = 'UPDATE' and (
          new.zelle_recipient is distinct from old.zelle_recipient
       or new.zelle_recipient_name is distinct from old.zelle_recipient_name)) then
    if not (coalesce(public.is_finance_staff(), false)
            or coalesce(public.is_company_admin(), false)
            or coalesce(public.is_platform_operator(), false)) then
      raise exception 'Only finance staff can change where owners send Zelle payments' using errcode = '42501';
    end if;
  end if;
  return new;
end
$$;


ALTER FUNCTION "public"."associations_payment_settings_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."associations_set_slug"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  base text;
  candidate text;
  n int := 1;
begin
  if NEW.slug is not null and NEW.slug <> '' then
    return NEW;
  end if;
  base := public.slugify_association_name(NEW.name);
  candidate := base;
  while exists (select 1 from public.associations a where a.slug = candidate and a.id <> NEW.id) loop
    n := n + 1;
    candidate := base || '-' || n;
  end loop;
  NEW.slug := candidate;
  return NEW;
end;
$$;


ALTER FUNCTION "public"."associations_set_slug"() OWNER TO "postgres";


