CREATE OR REPLACE FUNCTION "public"."audit_association_private_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_new jsonb := to_jsonb(new) - 'association_id' - 'updated_at';
  v_old jsonb := case when tg_op = 'UPDATE' then to_jsonb(old) - 'association_id' - 'updated_at' else '{}'::jsonb end;
  v_fields text[] := '{}';
  k text;
begin
  for k in select jsonb_object_keys(v_new) loop
    if (v_new -> k) is distinct from coalesce(v_old -> k, 'null'::jsonb) then
      v_fields := v_fields || k;
    end if;
  end loop;
  if cardinality(v_fields) = 0 then return null; end if;
  insert into public.audit_logs (portfolio_id, entity_type, entity_id, action, actor_id, actor_email, changes)
  select a.portfolio_id, 'association', a.id, 'association_private_settings_updated', auth.uid(),
         (select u.email from auth.users u where u.id = auth.uid()),
         jsonb_build_object('fields', to_jsonb(v_fields))
    from public.associations a where a.id = new.association_id;
  return null;
end $$;


ALTER FUNCTION "public"."audit_association_private_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."audit_inspection_finding_lifecycle"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if tg_op = 'INSERT' then
    insert into public.inspection_finding_events(inspection_item_id, action, note, actor_user_id)
    values (new.id, 'captured', new.issue, coalesce(new.captured_by, auth.uid()));
    return new;
  end if;
  if new.resolved is distinct from old.resolved then
    insert into public.inspection_finding_events(inspection_item_id, action, note, actor_user_id)
    values (new.id, case when new.resolved then 'resolved' else 'reopened' end, new.resolution_notes, auth.uid());
  end if;
  if new.work_order_id is distinct from old.work_order_id and new.work_order_id is not null then
    insert into public.inspection_finding_events(inspection_item_id, action, note, work_order_id, actor_user_id)
    values (new.id, 'remediation_linked', 'Remediation work order linked', new.work_order_id, auth.uid());
  end if;
  return new;
end;
$$;


