CREATE OR REPLACE FUNCTION "public"."board_members_owner_association_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if new.owner_id is not null and not exists (
    select 1 from public.owners o where o.id = new.owner_id and o.association_id = new.association_id
  ) then
    raise exception 'This homeowner is not in that association' using errcode = '42501';
  end if;
  return new;
end
$$;


ALTER FUNCTION "public"."board_members_owner_association_guard"() OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."platform_operators" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "auth_user_id" "uuid" NOT NULL,
    "email" "text" NOT NULL,
    "full_name" "text",
    "role" "text" DEFAULT 'admin'::"text" NOT NULL,
    "active" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid",
    "mfa_required" boolean DEFAULT true NOT NULL,
    "mfa_enrolled_at" timestamp with time zone,
    CONSTRAINT "platform_operators_role_check" CHECK (("role" = ANY (ARRAY['admin'::"text", 'support'::"text", 'readonly'::"text"])))
);


ALTER TABLE "public"."platform_operators" OWNER TO "postgres";


COMMENT ON TABLE "public"."platform_operators" IS 'SaaS vendor staff (super admins). Separate from portfolio staff. Bypasses portfolio_id isolation for support, cross-tenant analytics, and platform admin.';



COMMENT ON COLUMN "public"."platform_operators"."mfa_required" IS 'Legacy configuration field retained for compatibility. Portier369 policy requires MFA unconditionally for every platform operator because the role crosses tenant boundaries.';



CREATE OR REPLACE FUNCTION "public"."bootstrap_platform_admin"("p_auth_user_id" "uuid", "p_full_name" "text" DEFAULT NULL::"text") RETURNS "public"."platform_operators"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  existing_count integer;
  po_row public.platform_operators;
  user_email text;
begin
  select count(*) into existing_count from public.platform_operators;
  if existing_count > 0 then
    raise exception 'platform_operators already bootstrapped; use the regular admin flow';
  end if;

  select email into user_email from auth.users where id = p_auth_user_id;
  if user_email is null then
    raise exception 'no auth.users row for %', p_auth_user_id;
  end if;

  insert into public.platform_operators (auth_user_id, email, full_name, role)
  values (p_auth_user_id, user_email, p_full_name, 'admin')
  returning * into po_row;
  return po_row;
end;
$$;


ALTER FUNCTION "public"."bootstrap_platform_admin"("p_auth_user_id" "uuid", "p_full_name" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."bootstrap_platform_admin"("p_auth_user_id" "uuid", "p_full_name" "text") IS 'ONE-TIME bootstrap: call via service role to register the first platform admin. Refuses to run once platform_operators has any rows.';



CREATE OR REPLACE FUNCTION "public"."budget_gl_account_scope_valid"("p_association_id" "uuid", "p_gl_account_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$#variable_conflict use_column
begin
  return (select s.x from (

  select exists (
    select 1
    from public.associations a
    join public.gl_accounts ga
      on ga.id = p_gl_account_id
     and ga.portfolio_id = a.portfolio_id
     and (ga.association_id is null or ga.association_id = a.id)
    where a.id = p_association_id
  )
  ) s(x) limit 1);
end$$;


ALTER FUNCTION "public"."budget_gl_account_scope_valid"("p_association_id" "uuid", "p_gl_account_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."budget_worksheet_source"("p_association_id" "uuid", "p_fiscal_year" integer, "p_source" "text") RETURNS TABLE("gl_account_id" "uuid", "monthly_amounts" numeric[])
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare w record;
begin
  if p_association_id is null or p_fiscal_year not between 2000 and 2100 then
    raise exception 'Invalid budget scope' using errcode = '22023';
  end if;
  if not public.can_read_association_budget(p_association_id) then
    raise exception 'Not authorized for this association budget' using errcode = '42501';
  end if;

  if p_source = 'prior_budget' then
    return query select bl.gl_account_id, bl.monthly_amounts from public.budget_lines bl
      where bl.association_id = p_association_id and bl.fiscal_year = p_fiscal_year - 1;
  elsif p_source in ('prior_actuals', 'current_actuals') then
    select * into w from public.association_fiscal_window(p_association_id,
      case when p_source = 'prior_actuals' then p_fiscal_year - 1 else p_fiscal_year end);
    return query
      with m as (
        select s.gid, public.fiscal_month_index(w.period_start, s.mon) as idx,
               public.gl_normal_amount(s.account_type, s.d, s.c) as amt
          from (select jl.gl_account_id as gid, ga.account_type::text as account_type,
                       date_trunc('month', je.entry_date)::date as mon,
                       sum(jl.debit_amount) as d, sum(jl.credit_amount) as c
                  from public.journal_lines jl
                  join public.journal_entries je on je.id = jl.entry_id and je.posted
                  join public.gl_accounts ga on ga.id = jl.gl_account_id
                 where jl.association_id = p_association_id
                   and je.entry_date between w.period_start and w.period_end
                 group by 1, 2, 3) s
         where public.gl_section(s.account_type) in ('income', 'expense')
      )
      select m.gid, array_agg(round(greatest(coalesce(x.amt, 0), 0), 2) order by g.i)
        from (select distinct gid from m) m
        cross join generate_series(1, 12) g(i)
        left join m x on x.gid = m.gid and x.idx = g.i
       group by m.gid;
  else
    raise exception 'Unknown source %', p_source using errcode = '22023';
  end if;
end $$;


ALTER FUNCTION "public"."budget_worksheet_source"("p_association_id" "uuid", "p_fiscal_year" integer, "p_source" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."build_year_end_snapshot"("p_association_id" "uuid", "p_fiscal_year" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  w record; a record;
  v_tb jsonb; v_bs jsonb; v_is jsonb; v_funds jsonb; v_ar jsonb; v_banks jsonb;
  v_ni_year numeric; v_ni_prior numeric; v_assets numeric; v_liab numeric; v_equity numeric;
  v_income numeric; v_expense numeric; v_budget_income numeric; v_budget_expense numeric;
begin
  select * into w from public.association_fiscal_window(p_association_id, p_fiscal_year);
  select id, name, legal_name, address, city, state, zip, tax_id, portfolio_id into a from public.associations where id = p_association_id;

  create temp table if not exists _ye_lines (
    gl_id uuid, number integer, name text, account_type text, fund_account text,
    d_to_end numeric, c_to_end numeric, d_prior numeric, c_prior numeric, d_year numeric, c_year numeric
  ) on commit drop;
  truncate _ye_lines;
  insert into _ye_lines
    select g.id, g.number, g.name, g.account_type::text, g.fund_account::text,
           sum(case when je.entry_date <= w.period_end then jl.debit_amount else 0 end),
           sum(case when je.entry_date <= w.period_end then jl.credit_amount else 0 end),
           sum(case when je.entry_date < w.period_start then jl.debit_amount else 0 end),
           sum(case when je.entry_date < w.period_start then jl.credit_amount else 0 end),
           sum(case when je.entry_date between w.period_start and w.period_end then jl.debit_amount else 0 end),
           sum(case when je.entry_date between w.period_start and w.period_end then jl.credit_amount else 0 end)
      from public.journal_lines jl
      join public.journal_entries je on je.id = jl.entry_id and je.posted
      join public.gl_accounts g on g.id = jl.gl_account_id
     where jl.association_id = p_association_id
     group by g.id;

  select coalesce(jsonb_agg(jsonb_build_object('number', number, 'name', name, 'type', account_type, 'fund', fund_account,
            'debit', round(d_year, 2), 'credit', round(c_year, 2)) order by number, name, gl_id) filter (where d_year <> 0 or c_year <> 0), '[]'::jsonb)
    into v_tb from _ye_lines;

  select coalesce(sum(public.gl_normal_amount(account_type, d_year, c_year)) filter (where public.gl_section(account_type) = 'income'), 0)
       - coalesce(sum(public.gl_normal_amount(account_type, d_year, c_year)) filter (where public.gl_section(account_type) = 'expense'), 0),
         coalesce(sum(public.gl_normal_amount(account_type, d_prior, c_prior)) filter (where public.gl_section(account_type) = 'income'), 0)
       - coalesce(sum(public.gl_normal_amount(account_type, d_prior, c_prior)) filter (where public.gl_section(account_type) = 'expense'), 0),
         coalesce(sum(public.gl_normal_amount(account_type, d_to_end, c_to_end)) filter (where public.gl_section(account_type) = 'asset'), 0),
         coalesce(sum(public.gl_normal_amount(account_type, d_to_end, c_to_end)) filter (where public.gl_section(account_type) = 'liability'), 0),
         coalesce(sum(public.gl_normal_amount(account_type, d_to_end, c_to_end)) filter (where public.gl_section(account_type) = 'equity'), 0)
    into v_ni_year, v_ni_prior, v_assets, v_liab, v_equity
    from _ye_lines;

  select jsonb_build_object(
    'assets', coalesce((select jsonb_agg(jsonb_build_object('number', number, 'name', name, 'fund', fund_account, 'balance', round(public.gl_normal_amount(account_type, d_to_end, c_to_end), 2)) order by number, name, gl_id)
                          from _ye_lines where public.gl_section(account_type) = 'asset' and public.gl_normal_amount(account_type, d_to_end, c_to_end) <> 0), '[]'::jsonb),
    'liabilities', coalesce((select jsonb_agg(jsonb_build_object('number', number, 'name', name, 'fund', fund_account, 'balance', round(public.gl_normal_amount(account_type, d_to_end, c_to_end), 2)) order by number, name, gl_id)
                          from _ye_lines where public.gl_section(account_type) = 'liability' and public.gl_normal_amount(account_type, d_to_end, c_to_end) <> 0), '[]'::jsonb),
    'equity', coalesce((select jsonb_agg(jsonb_build_object('number', number, 'name', name, 'fund', fund_account, 'balance', round(public.gl_normal_amount(account_type, d_to_end, c_to_end), 2)) order by number, name, gl_id)
                          from _ye_lines where public.gl_section(account_type) = 'equity' and public.gl_normal_amount(account_type, d_to_end, c_to_end) <> 0), '[]'::jsonb),
    'accumulated_surplus_prior_years', round(v_ni_prior, 2),
    'net_income_current_year', round(v_ni_year, 2),
    'total_assets', round(v_assets, 2),
    'total_liabilities', round(v_liab, 2),
    'total_equity', round(v_equity + v_ni_prior + v_ni_year, 2),
    'balanced', abs(v_assets - (v_liab + v_equity + v_ni_prior + v_ni_year)) < 0.005
  ) into v_bs;

  with acct as (
    select l.number, l.name, l.account_type, public.gl_section(l.account_type) sec, l.gl_id,
           public.gl_normal_amount(l.account_type, l.d_year, l.c_year) actual
      from _ye_lines l where public.gl_section(l.account_type) in ('income', 'expense')
  ), bud as (
    select bl.gl_account_id, sum(bl.annual_total) budget
      from public.budget_lines bl where bl.association_id = p_association_id and bl.fiscal_year = p_fiscal_year
     group by bl.gl_account_id
  ), merged as (
    select coalesce(acct.number, g.number) number, coalesce(acct.name, g.name) name,
           coalesce(acct.sec, public.gl_section(g.account_type::text)) sec,
           coalesce(acct.actual, 0) actual, coalesce(bud.budget, 0) budget
      from acct full join bud on bud.gl_account_id = acct.gl_id
      left join public.gl_accounts g on g.id = bud.gl_account_id
  )
  select coalesce(jsonb_agg(jsonb_build_object('number', number, 'name', name, 'section', sec,
            'actual', round(actual, 2), 'budget', round(budget, 2),
            'variance', round(case when sec = 'income' then actual - budget else budget - actual end, 2)) order by sec desc, number, name)
            filter (where actual <> 0 or budget <> 0), '[]'::jsonb),
         coalesce(sum(actual) filter (where sec = 'income'), 0), coalesce(sum(actual) filter (where sec = 'expense'), 0),
         coalesce(sum(budget) filter (where sec = 'income'), 0), coalesce(sum(budget) filter (where sec = 'expense'), 0)
    into v_is, v_income, v_expense, v_budget_income, v_budget_expense
    from merged;

  select coalesce(jsonb_agg(jsonb_build_object('fund', fund, 'income', round(income, 2), 'expense', round(expense, 2), 'net', round(income - expense, 2)) order by fund), '[]'::jsonb)
    into v_funds
    from (select coalesce(fund_account, 'operating') fund,
                 sum(public.gl_normal_amount(account_type, d_year, c_year)) filter (where public.gl_section(account_type) = 'income') income,
                 sum(public.gl_normal_amount(account_type, d_year, c_year)) filter (where public.gl_section(account_type) = 'expense') expense
            from _ye_lines group by 1) f
   where coalesce(income, 0) <> 0 or coalesce(expense, 0) <> 0;

  select jsonb_build_object('total', coalesce(round(sum(bal), 2), 0), 'accounts', count(*),
           'units', coalesce(jsonb_agg(jsonb_build_object('unit', unit_number, 'balance', round(bal, 2)) order by bal desc, unit_number, unit_id), '[]'::jsonb))
    into v_ar
    from (
      select u.id unit_id, u.unit_number,
             coalesce((select sum(c.amount) from public.charges c where c.unit_id = u.id and c.due_date <= w.period_end), 0)
           - coalesce((select sum(p.amount) from public.payments p where p.unit_id = u.id and p.payment_date <= w.period_end), 0) bal
        from public.units u join public.buildings b on b.id = u.building_id
       where b.association_id = p_association_id and u.archived_at is null
    ) x where bal > 0.004;

  select coalesce(jsonb_agg(jsonb_build_object('name', ba.name, 'purpose', ba.purpose,
           'balance', round(coalesce(public.gl_normal_amount(l.account_type, l.d_to_end, l.c_to_end), 0), 2),
           'reconciled_through', ba.last_reconciliation_date) order by ba.name, ba.id), '[]'::jsonb)
    into v_banks
    from public.bank_accounts ba left join _ye_lines l on l.gl_id = ba.gl_account_id
   where ba.association_id = p_association_id and ba.archived_at is null;

  return jsonb_build_object(
    'format', 'portier369.year_end.v1',
    'association', jsonb_build_object('id', a.id, 'name', a.name, 'legal_name', a.legal_name,
      'address', concat_ws(', ', a.address, a.city, concat_ws(' ', a.state, a.zip)), 'tax_id', a.tax_id),
    'fiscal_year', p_fiscal_year, 'period_start', w.period_start, 'period_end', w.period_end,
    'trial_balance', v_tb,
    'balance_sheet', v_bs,
    'income_statement', jsonb_build_object('lines', v_is,
      'total_income', round(v_income, 2), 'total_expense', round(v_expense, 2), 'net_income', round(v_income - v_expense, 2),
      'budget_income', round(v_budget_income, 2), 'budget_expense', round(v_budget_expense, 2), 'budget_net', round(v_budget_income - v_budget_expense, 2)),
    'funds', v_funds,
    'receivables', v_ar,
    'bank_accounts', v_banks
  );
end;
$$;


ALTER FUNCTION "public"."build_year_end_snapshot"("p_association_id" "uuid", "p_fiscal_year" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."buildings_move_keeps_association"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if exists (select 1 from public.units u join public.occupancies o on o.unit_id = u.id where u.building_id = new.id)
     or exists (select 1 from public.units u join public.unit_owners uo on uo.unit_id = u.id where u.building_id = new.id) then
    raise exception 'This building has units with homeowners or residents, so it cannot move to another association.'
      using errcode = '23514';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."buildings_move_keeps_association"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bulk_create_charges"("p_charges" "jsonb", "p_charge_category_id" "uuid" DEFAULT NULL::"uuid", "p_due_date" "date" DEFAULT NULL::"date", "p_description" "text" DEFAULT NULL::"text", "p_gl_account_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("inserted_count" integer, "charge_ids" "uuid"[])
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  charge record;
  new_ids uuid[] := '{}';
  new_id uuid;
  cnt integer := 0;
  v_portfolio uuid;
  v_assoc uuid;
  v_cat public.charge_categories;
  v_cat_id uuid;
  v_due date;
  v_gl_id uuid;
begin
  if auth.uid() is null then raise exception 'Authentication required' using errcode = '42501'; end if;
  if p_charges is null or jsonb_typeof(p_charges) <> 'array' or jsonb_array_length(p_charges) = 0 then
    raise exception 'No charges supplied' using errcode = '22023';
  end if;
  if jsonb_array_length(p_charges) > 5000 then
    raise exception 'At most 5000 charges per batch' using errcode = '22023';
  end if;

  for charge in
    select * from jsonb_to_recordset(p_charges)
      as x(unit_id uuid, amount numeric, description text, charge_category_id uuid, due_date date, gl_account_id uuid)
  loop
    v_portfolio := public.unit_portfolio_id(charge.unit_id);
    if v_portfolio is null or not public.can_manage_finance(v_portfolio) then
      raise exception 'Permission denied for unit %', charge.unit_id using errcode = '42501';
    end if;
    v_assoc := public.unit_association_id(charge.unit_id);
    if not public.can_view_association_row(v_assoc) then
      raise exception 'Permission denied for unit %', charge.unit_id using errcode = '42501';
    end if;
    if charge.amount is null or charge.amount <= 0 or charge.amount > 10000000 then
      raise exception 'Charge amount must be positive' using errcode = '22023';
    end if;

    v_cat_id := coalesce(charge.charge_category_id, p_charge_category_id);
    v_cat := null;
    if v_cat_id is not null then
      -- fix: the category must also be the unit's association's (or company-wide).
      select * into v_cat from public.charge_categories c
       where c.id = v_cat_id and c.portfolio_id = v_portfolio and c.active and c.archived_at is null
         and (c.association_id is null or c.association_id = v_assoc);
      if not found then raise exception 'Charge category is outside this association or inactive' using errcode = '42501'; end if;
    end if;

    v_gl_id := coalesce(charge.gl_account_id, p_gl_account_id, v_cat.gl_account_id);
    if v_gl_id is not null and not exists (
      select 1 from public.gl_accounts g where g.id = v_gl_id and g.portfolio_id = v_portfolio and g.active
    ) then
      raise exception 'GL account is outside this company or inactive' using errcode = '42501';
    end if;

    -- fix: association-local today, not the server's (UTC).
    v_due := coalesce(charge.due_date, p_due_date, (public.association_local_date(v_assoc) + 30));

    insert into public.charges (
      unit_id, charge_category_id, charge_type, description, amount, due_date, gl_account_id, created_by
    ) values (
      charge.unit_id, v_cat_id, coalesce(v_cat.charge_type, 'assessment'::public.charge_type),
      left(coalesce(nullif(btrim(charge.description), ''), nullif(btrim(p_description), ''), v_cat.name, 'Assessment charge'), 500),
      round(charge.amount, 2), v_due, v_gl_id, auth.uid()
    ) returning id into new_id;

    new_ids := array_append(new_ids, new_id);
    cnt := cnt + 1;
  end loop;

  return query select cnt, new_ids;
end;
$$;


ALTER FUNCTION "public"."bulk_create_charges"("p_charges" "jsonb", "p_charge_category_id" "uuid", "p_due_date" "date", "p_description" "text", "p_gl_account_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bulk_create_recurring_charges"("p_subscriptions" "jsonb", "p_charge_category_id" "uuid" DEFAULT NULL::"uuid", "p_frequency" "text" DEFAULT 'monthly'::"text", "p_start_date" "date" DEFAULT NULL::"date", "p_memo" "text" DEFAULT NULL::"text") RETURNS TABLE("inserted_count" integer, "subscription_ids" "uuid"[])
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  sub record;
  new_ids uuid[] := '{}';
  new_id uuid;
  cnt integer := 0;
  v_portfolio uuid;
  v_assoc uuid;
  v_cat_id uuid;
  v_freq public.recurring_frequency;
  v_row_freq public.recurring_frequency;
  v_start date;
  v_next date;
begin
  if auth.uid() is null then raise exception 'Authentication required' using errcode = '42501'; end if;
  if p_subscriptions is null or jsonb_typeof(p_subscriptions) <> 'array' or jsonb_array_length(p_subscriptions) = 0 then
    raise exception 'No subscriptions supplied' using errcode = '22023';
  end if;
  if jsonb_array_length(p_subscriptions) > 5000 then
    raise exception 'At most 5000 subscriptions per batch' using errcode = '22023';
  end if;
  begin
    v_freq := coalesce(p_frequency, 'monthly')::public.recurring_frequency;
  exception when others then
    raise exception 'Invalid frequency: %', p_frequency using errcode = '22023';
  end;

  for sub in
    select * from jsonb_to_recordset(p_subscriptions)
      as x(unit_id uuid, amount numeric, charge_category_id uuid, frequency text, start_date date, memo text)
  loop
    v_portfolio := public.unit_portfolio_id(sub.unit_id);
    if v_portfolio is null or not public.can_manage_finance(v_portfolio) then
      raise exception 'Permission denied for unit %', sub.unit_id using errcode = '42501';
    end if;
    v_assoc := public.unit_association_id(sub.unit_id);
    if not public.can_view_association_row(v_assoc) then
      raise exception 'Permission denied for unit %', sub.unit_id using errcode = '42501';
    end if;
    if sub.amount is null or sub.amount <= 0 or sub.amount > 10000000 then
      raise exception 'Recurring amount must be positive' using errcode = '22023';
    end if;
    v_cat_id := coalesce(sub.charge_category_id, p_charge_category_id);
    -- fix: the category must also be the unit's association's (or company-wide).
    if v_cat_id is null or not exists (
      select 1 from public.charge_categories c
       where c.id = v_cat_id and c.portfolio_id = v_portfolio and c.active and c.archived_at is null
         and (c.association_id is null or c.association_id = v_assoc)
    ) then
      raise exception 'Charge category is outside this association or inactive' using errcode = '42501';
    end if;

    v_row_freq := v_freq;
    if sub.frequency is not null then
      begin
        v_row_freq := sub.frequency::public.recurring_frequency;
      exception when others then
        raise exception 'Invalid frequency: %', sub.frequency using errcode = '22023';
      end;
    end if;
    -- fix: "today" is the association's date, not the server's (UTC).
    v_start := coalesce(sub.start_date, p_start_date, public.association_local_date(v_assoc));

    -- fix: two runs at once (double click) for the same unit each ended the
    -- old subscription and inserted a new one. Serialize per unit; the next
    -- statement then sees the other run's subscription and ends it.
    perform 1 from public.units u where u.id = sub.unit_id for update;

    -- fix: a replaced subscription that already posted charges on or after
    -- the new start date: start the new one at its next unposted date, so
    -- those periods are not charged twice.
    select max(r.next_post_date) into v_next
      from public.unit_recurring_charges r
     where r.unit_id = sub.unit_id
       and r.charge_category_id = v_cat_id
       and r.active
       and (r.end_date is null or r.end_date >= v_start)
       and r.last_posted_at is not null
       and r.next_post_date > v_start;

    update public.unit_recurring_charges
       set end_date = greatest(start_date, v_start - 1),
           active = coalesce(start_date < v_start and next_post_date <= v_start - 1, false),
           updated_at = now()
     where unit_id = sub.unit_id
       and charge_category_id = v_cat_id
       and active
       and (end_date is null or end_date >= v_start);

    insert into public.unit_recurring_charges (
      unit_id, charge_category_id, amount, frequency, start_date, next_post_date, memo, active, created_by
    ) values (
      sub.unit_id, v_cat_id, round(sub.amount, 2), v_row_freq, v_start, greatest(v_start, coalesce(v_next, v_start)),
      left(coalesce(nullif(btrim(sub.memo), ''), nullif(btrim(p_memo), '')), 500), true, auth.uid()
    ) returning id into new_id;

    new_ids := array_append(new_ids, new_id);
    cnt := cnt + 1;
  end loop;

  return query select cnt, new_ids;
end;
$$;


ALTER FUNCTION "public"."bulk_create_recurring_charges"("p_subscriptions" "jsonb", "p_charge_category_id" "uuid", "p_frequency" "text", "p_start_date" "date", "p_memo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bulk_queue_reports"("p_association_ids" "uuid"[], "p_report_slugs" "text"[], "p_scope" "text" DEFAULT 'association'::"text", "p_date_start" "date" DEFAULT NULL::"date", "p_date_end" "date" DEFAULT NULL::"date", "p_output_format" "text" DEFAULT 'csv'::"text") RETURNS TABLE("queued_count" integer, "run_ids" "uuid"[])
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_assoc_id uuid;
  v_slug text;
  v_def_id uuid;
  v_created_by uuid := auth.uid();
  v_portfolio_id uuid;
  v_fmt public.report_format;
  new_ids uuid[] := '{}';
  new_id uuid;
  cnt integer := 0;
begin
  if v_created_by is null then
    raise exception 'authentication required';
  end if;

  if not public.is_any_staff() then
    raise exception 'staff access required';
  end if;

  select p.portfolio_id
  into v_portfolio_id
  from public.profiles p
  where p.id = v_created_by;

  if v_portfolio_id is null or not public.can_access_portfolio(v_portfolio_id) then
    raise exception 'cannot determine an authorized portfolio';
  end if;

  if coalesce(cardinality(p_association_ids), 0) = 0
     or coalesce(cardinality(p_report_slugs), 0) = 0 then
    raise exception 'at least one association and report are required';
  end if;

  if exists (
    select 1
    from unnest(p_association_ids) requested(id)
    left join public.associations a on a.id = requested.id
    where a.id is null
       or a.portfolio_id <> v_portfolio_id
       or a.archived_at is not null
  ) then
    raise exception 'one or more associations are outside the authorized portfolio';
  end if;

  begin
    v_fmt := p_output_format::public.report_format;
  exception when invalid_text_representation then
    raise exception 'unsupported report output format';
  end;

  foreach v_assoc_id in array p_association_ids loop
    foreach v_slug in array p_report_slugs loop
      select id
      into v_def_id
      from public.report_definitions
      where slug = v_slug
        and active = true
        and (portfolio_id is null or portfolio_id = v_portfolio_id);

      if v_def_id is null then
        raise exception 'report slug "%" is not available for this portfolio', v_slug;
      end if;

      if public.report_params_access_error(v_portfolio_id, v_slug, jsonb_build_object('association_id', v_assoc_id)) is not null then
        raise exception '%', public.report_params_access_error(v_portfolio_id, v_slug, jsonb_build_object('association_id', v_assoc_id))
          using errcode = '42501';
      end if;

      insert into public.report_runs (
        definition_id,
        portfolio_id,
        parameters,
        output_format,
        status,
        triggered_by
      ) values (
        v_def_id,
        v_portfolio_id,
        jsonb_build_object(
          'scope', p_scope,
          'association_id', v_assoc_id,
          'date_from', p_date_start,
          'date_to', p_date_end
        ),
        v_fmt,
        'queued',
        v_created_by
      )
      returning id into new_id;

      new_ids := array_append(new_ids, new_id);
      cnt := cnt + 1;
    end loop;
  end loop;

  return query select cnt, new_ids;
end;
$$;


ALTER FUNCTION "public"."bulk_queue_reports"("p_association_ids" "uuid"[], "p_report_slugs" "text"[], "p_scope" "text", "p_date_start" "date", "p_date_end" "date", "p_output_format" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bulk_update_statement_settings"("p_association_ids" "uuid"[], "p_settings" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  update_count integer := 0;
BEGIN
  UPDATE associations
  SET
    use_enhanced_statement = COALESCE((p_settings->>'use_enhanced_statement')::boolean, use_enhanced_statement),
    include_current_and_upcoming_charges = COALESCE((p_settings->>'include_current_and_upcoming_charges')::boolean, include_current_and_upcoming_charges),
    include_upcoming_in_amount_due = COALESCE((p_settings->>'include_upcoming_in_amount_due')::boolean, include_upcoming_in_amount_due),
    upcoming_charges_timeframe = COALESCE(p_settings->>'upcoming_charges_timeframe', upcoming_charges_timeframe),
    include_current_message_on_statement = COALESCE((p_settings->>'include_current_message_on_statement')::boolean, include_current_message_on_statement),
    include_logo_on_statement = COALESCE((p_settings->>'include_logo_on_statement')::boolean, include_logo_on_statement),
    charge_history_includes = COALESCE(p_settings->>'charge_history_includes', charge_history_includes),
    include_payments_due_date = COALESCE((p_settings->>'include_payments_due_date')::boolean, include_payments_due_date),
    include_payments_history_and_balance_forward = COALESCE((p_settings->>'include_payments_history_and_balance_forward')::boolean, include_payments_history_and_balance_forward),
    show_remaining_amount_for_past_due_charges = COALESCE((p_settings->>'show_remaining_amount_for_past_due_charges')::boolean, show_remaining_amount_for_past_due_charges),
    include_payment_coupon_on_statement = COALESCE((p_settings->>'include_payment_coupon_on_statement')::boolean, include_payment_coupon_on_statement)
  WHERE id = ANY(p_association_ids)
    AND archived_at IS NULL;
  
  GET DIAGNOSTICS update_count = ROW_COUNT;
  RETURN update_count;
END;
$$;


ALTER FUNCTION "public"."bulk_update_statement_settings"("p_association_ids" "uuid"[], "p_settings" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bump_saved_report_on_run"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if new.status = 'succeeded' and new.saved_report_id is not null then
    update public.saved_reports
       set last_run_at = coalesce(new.finished_at, now()),
           run_count = run_count + 1,
           updated_at = now()
     where id = new.saved_report_id;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."bump_saved_report_on_run"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calc_next_maintenance_due"("p_frequency" "text", "p_custom_interval_days" integer, "p_from_date" "date") RETURNS "date"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
    BEGIN
      RETURN CASE p_frequency
        WHEN 'weekly' THEN p_from_date + 7
        WHEN 'monthly' THEN p_from_date + INTERVAL '1 month'
        WHEN 'bimonthly' THEN p_from_date + INTERVAL '2 months'
        WHEN 'quarterly' THEN p_from_date + INTERVAL '3 months'
        WHEN 'semiannual' THEN p_from_date + INTERVAL '6 months'
        WHEN 'annual' THEN p_from_date + INTERVAL '1 year'
        WHEN 'custom' THEN p_from_date + (p_custom_interval_days || ' days')::INTERVAL
        ELSE p_from_date + INTERVAL '1 month'
      END;
    END;
    $$;


ALTER FUNCTION "public"."calc_next_maintenance_due"("p_frequency" "text", "p_custom_interval_days" integer, "p_from_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_convenience_fee"("p_portfolio_id" "uuid", "p_amount_cents" bigint, "p_method" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  pf public.portfolios;
  fee_pct numeric := 0;
  fee_fixed integer := 0;
  fee_cents integer := 0;
  owner_pays integer := 0;
begin
  select * into pf from public.portfolios where id = p_portfolio_id;
  if not found then
    return jsonb_build_object('error', 'portfolio not found');
  end if;

  if p_method in ('card','credit_card','debit_card') then
    fee_pct := pf.convenience_fee_card_pct;
    fee_fixed := pf.convenience_fee_card_fixed_cents;
  elsif p_method in ('ach','echeck','bank_transfer') then
    fee_pct := pf.convenience_fee_ach_pct;
    fee_fixed := pf.convenience_fee_ach_fixed_cents;
  else
    return jsonb_build_object('fee_cents', 0, 'owner_pays_cents', p_amount_cents);
  end if;

  fee_cents := round((p_amount_cents * fee_pct / 100.0) + fee_fixed);
  fee_cents := greatest(fee_cents, pf.convenience_fee_minimum_cents);

  case pf.convenience_fee_mode
    when 'absorb'       then owner_pays := p_amount_cents;
    when 'pass_through' then owner_pays := p_amount_cents + fee_cents;
    when 'split'        then owner_pays := p_amount_cents + (fee_cents / 2);
    when 'flat_addon'   then owner_pays := p_amount_cents + pf.convenience_fee_card_fixed_cents;
  end case;

  return jsonb_build_object(
    'fee_cents', fee_cents,
    'owner_pays_cents', owner_pays,
    'mode', pf.convenience_fee_mode,
    'label', pf.convenience_fee_label
  );
end;
$$;


ALTER FUNCTION "public"."calculate_convenience_fee"("p_portfolio_id" "uuid", "p_amount_cents" bigint, "p_method" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_meeting_quorum"("p_meeting_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_meeting public.meetings%rowtype;
  q record;
  v_reached boolean;
  v_needed integer;
  v_total integer;
begin
  if auth.uid() is null or p_meeting_id is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;

  select * into v_meeting from public.meetings m where m.id = p_meeting_id;
  if not found then
    raise exception 'Meeting not found' using errcode = 'P0002';
  end if;

  if not (
    public.is_platform_operator()
    or (
      (public.is_any_staff() or public.is_company_admin())
      and public.can_access_portfolio(v_meeting.portfolio_id) and public.can_view_association_row(v_meeting.association_id)
      and (v_meeting.meeting_type <> 'executive_session'
        or public.can_access_confidential_meeting_mvp(v_meeting.association_id))
    )
    or (
      public.current_owner_id() is not null
      and v_meeting.meeting_type <> 'executive_session'
      and v_meeting.association_id in (select public.current_resident_association_ids())
    )
  ) then
    raise exception 'Not authorized for this meeting' using errcode = '42501';
  end if;

  select * into q from public.app_meeting_quorum_snapshot(v_meeting);

  -- A completed meeting reports what was recorded when it was held; one
  -- completed before results were recorded is counted from its attendance.
  if v_meeting.status::text = 'completed' and v_meeting.quorum_met is not null
     and v_meeting.quorum_requirement is not null and v_meeting.total_units is not null then
    v_reached := v_meeting.quorum_met;
    v_needed := v_meeting.quorum_requirement;
    v_total := v_meeting.total_units;
  else
    v_reached := q.owner_count >= q.quorum_needed;
    v_needed := q.quorum_needed;
    v_total := q.total_units;
  end if;

  return jsonb_build_object(
    'meeting_id', p_meeting_id,
    'total_units', v_total,
    'quorum_percentage', q.quorum_percentage,
    'quorum_needed', v_needed,
    'attendee_count', q.attendee_count,
    'board_count', q.board_count,
    'owner_count', q.owner_count,
    'quorum_reached', v_reached
  );
end;
$$;


ALTER FUNCTION "public"."calculate_meeting_quorum"("p_meeting_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_meeting_quorum_tenant_checked_impl"("p_meeting_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_meeting public.meetings%rowtype;
  v_quorum_pct integer;
  v_total_units integer;
  v_attendee_count integer;
  v_board_count integer;
  v_owner_count integer;
  v_quorum_needed integer;
  v_quorum_reached boolean;
  v_authorized boolean;
begin
  if auth.uid() is null or p_meeting_id is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;

  select * into v_meeting
  from public.meetings m
  where m.id = p_meeting_id
  for update;

  if not found then
    raise exception 'Meeting not found' using errcode = 'P0002';
  end if;

  v_authorized := public.is_platform_operator()
    or (
      (public.is_any_staff() or public.is_company_admin())
      and public.can_access_portfolio(v_meeting.portfolio_id)
    )
    
    or (
      public.is_portal_resident()
      and v_meeting.association_id in (select public.current_resident_association_ids())
    );

  if not v_authorized then
    raise exception 'Not authorized for this meeting' using errcode = '42501';
  end if;

  select greatest(1, least(100, coalesce(a.quorum_percentage, 51))),
         greatest(0, coalesce(a.unit_count, 0))
  into v_quorum_pct, v_total_units
  from public.associations a
  where a.id = v_meeting.association_id;

  select count(*)::integer,
         count(*) filter (where ma.attendee_role = 'board_member')::integer,
         count(distinct ma.owner_id) filter (
           where ma.owner_id is not null
             and coalesce(ma.voting_eligible, false)
             and exists (
               select 1 from public.occupancies o
               where o.owner_id = ma.owner_id
                 and o.association_id = v_meeting.association_id
                 and o.status = 'current'
             )
         )::integer
  into v_attendee_count, v_board_count, v_owner_count
  from public.meeting_attendees ma
  where ma.meeting_id = p_meeting_id
    and ma.present;

  v_quorum_needed := ceil(v_total_units * v_quorum_pct / 100.0)::integer;
  v_quorum_reached := v_owner_count >= v_quorum_needed;

  update public.meetings m
  set quorum_met = v_quorum_reached,
      quorum_requirement = v_quorum_needed,
      total_units = v_total_units
  where m.id = p_meeting_id;

  return jsonb_build_object(
    'meeting_id', p_meeting_id,
    'total_units', v_total_units,
    'quorum_percentage', v_quorum_pct,
    'quorum_needed', v_quorum_needed,
    'attendee_count', v_attendee_count,
    'board_count', v_board_count,
    'owner_count', v_owner_count,
    'quorum_reached', v_quorum_reached
  );
end;
$$;


ALTER FUNCTION "public"."calculate_meeting_quorum_tenant_checked_impl"("p_meeting_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calendar_event_reminders_scope_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_event record;
begin
  select e.portfolio_id, e.association_id into v_event
    from public.calendar_events e where e.id = new.calendar_event_id;
  if not found then
    raise exception 'Calendar event not found' using errcode = '23503';
  end if;
  if new.portfolio_id is distinct from v_event.portfolio_id
     or new.association_id is distinct from v_event.association_id then
    raise exception 'A reminder belongs to its event''s association' using errcode = '42501';
  end if;
  return new;
end
$$;


ALTER FUNCTION "public"."calendar_event_reminders_scope_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calendar_event_vendor_in_company"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_company uuid;
begin
  if new.vendor_id is null then
    return new;
  end if;
  if tg_op = 'UPDATE'
     and new.vendor_id is not distinct from old.vendor_id
     and new.association_id is not distinct from old.association_id
     and new.portfolio_id is not distinct from old.portfolio_id then
    return new;
  end if;
  if new.association_id is not null then
    select a.portfolio_id into v_company
      from public.associations a where a.id = new.association_id for share;
  else
    v_company := new.portfolio_id;
  end if;
  if v_company is null or not exists (
    select 1 from public.vendors v
     where v.id = new.vendor_id and v.portfolio_id = v_company
       for share
  ) then
    raise exception 'That vendor belongs to a different company' using errcode = '23514';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."calendar_event_vendor_in_company"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_access_association"("a_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$#variable_conflict use_column
begin
  return (select s.x from (

  select a_id is not null
    and exists (
      select 1 from public.associations a
      where a.id = a_id
        and public.can_access_portfolio(a.portfolio_id)
    )
    and public.can_view_association_row(a_id)
  ) s(x) limit 1);
end$$;


ALTER FUNCTION "public"."can_access_association"("a_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."can_access_association"("a_id" "uuid") IS 'Company access plus a scoped manager''s associations (can_view_association_row). Policies use the copy rls_private.my_accessible_association_ids(); change both together (20261013010000, 20261013030000).';



CREATE OR REPLACE FUNCTION "public"."can_access_association_mvp"("a_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
#variable_conflict use_column
begin
  return (
    a_id is not null
    and (
      public.is_platform_operator()
      or exists (
        select 1
          from public.profiles p
          join public.associations a on a.portfolio_id = p.portfolio_id
         where p.id = auth.uid()
           and (p.mvp_role in ('company_admin', 'accountant') or p.hoa_role = 'company_admin')
           and a.id = a_id
      )
      or exists (
        select 1
          from public.profiles p
          join public.association_managers am
            on am.user_id = p.id
           and am.ended_at is null
          join public.associations a
            on a.id = am.association_id
           and a.portfolio_id = p.portfolio_id
         where p.id = auth.uid()
           and (
             p.mvp_role in ('manager', 'assistant_manager')
             or (p.mvp_role is null and p.hoa_role = 'manager')
           )
           and a.id = a_id
      )
      or exists (
        select 1
          from public.board_members bm
         where bm.auth_user_id = auth.uid()
           and bm.association_id = a_id
           and bm.active = true
      )
      or (
        public.current_owner_id() is not null
        and a_id in (select public.current_resident_association_ids())
      )
    )
  );
end
$$;


ALTER FUNCTION "public"."can_access_association_mvp"("a_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."can_access_association_mvp"("a_id" "uuid") IS 'Role-aware association read boundary. Supports current mvp_role identities and assigned legacy hoa_role staff.';



CREATE OR REPLACE FUNCTION "public"."can_access_confidential_meeting_mvp"("a_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$#variable_conflict use_column
begin
  return (select s.x from (

  select a_id is not null
    and public.is_current_identity_enabled()
    and (
      public.can_edit_association_mvp(a_id)
      or exists (
        select 1
        from public.profiles p
        join public.association_managers am
          on am.user_id = p.id
         and am.association_id = a_id
         and am.ended_at is null
        join public.associations a
          on a.id = am.association_id
         and a.portfolio_id = p.portfolio_id
        where p.id = auth.uid()
          and p.disabled_at is null
          and p.mvp_role = 'assistant_manager'
      )
      or exists (
        select 1
        from public.board_members bm
        where bm.auth_user_id = auth.uid()
          and bm.association_id = a_id
          and bm.active = true
      )
    )
  ) s(x) limit 1);
end$$;


ALTER FUNCTION "public"."can_access_confidential_meeting_mvp"("a_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."can_access_confidential_meeting_mvp"("a_id" "uuid") IS 'Policies on agenda_items, meeting_documents and meeting_action_items use the set copy rls_private.my_confidential_meeting_association_ids(); change both together (20261013110000, 20261013120000, 20261013130000).';



CREATE OR REPLACE FUNCTION "public"."can_access_meeting"("p_meeting_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$#variable_conflict use_column
begin
  return (select s.x from (

  select auth.uid() is not null
    and exists (
      select 1
      from public.meetings m
      join public.associations a
        on a.id = m.association_id
       and a.portfolio_id = m.portfolio_id
      where m.id = p_meeting_id
        and (
          public.is_platform_operator()
          or (
            (public.is_any_staff() or public.is_company_admin())
            and public.can_access_portfolio(a.portfolio_id)
            and public.can_access_association(a.id)
          )
          or (
            public.is_board_user()
            and a.id in (select public.current_board_association_ids())
          )
          or (
            m.meeting_type <> 'executive_session'
            and (
              (
                public.current_owner_id() is not null
                and a.id in (select public.current_resident_association_ids())
              )
              or (
                public.is_tenant_user()
                and a.id in (select public.current_tenant_association_ids())
              )
            )
          )
        )
    )
  ) s(x) limit 1);
end$$;


