CREATE TABLE IF NOT EXISTS "public"."autopay_mandates" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "portfolio_id" "uuid" NOT NULL,
    "association_id" "uuid",
    "owner_id" "uuid" NOT NULL,
    "unit_id" "uuid",
    "payment_method_id" "uuid" NOT NULL,
    "authorized_amount_max_cents" integer NOT NULL,
    "frequency" "public"."autopay_frequency" DEFAULT 'on_charge_posted'::"public"."autopay_frequency" NOT NULL,
    "day_of_month" smallint,
    "start_date" "date" DEFAULT CURRENT_DATE NOT NULL,
    "end_date" "date",
    "status" "public"."autopay_status" DEFAULT 'pending_verification'::"public"."autopay_status" NOT NULL,
    "mandate_signed_at" timestamp with time zone,
    "mandate_ip_address" "text",
    "mandate_user_agent" "text",
    "mandate_document_url" "text",
    "processor_mandate_id" "text",
    "next_run_date" "date",
    "last_run_at" timestamp with time zone,
    "success_count" integer DEFAULT 0 NOT NULL,
    "failure_count" integer DEFAULT 0 NOT NULL,
    "last_failure_at" timestamp with time zone,
    "last_failure_reason" "text",
    "paused_at" timestamp with time zone,
    "paused_reason" "text",
    "canceled_at" timestamp with time zone,
    "canceled_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "mode" "text" DEFAULT 'current_balance'::"text" NOT NULL,
    "fixed_amount_cents" integer,
    "minimum_amount_cents" integer,
    "include_late_fees" boolean DEFAULT true NOT NULL,
    "skip_until" "date",
    "setup_attempt_id" "uuid",
    CONSTRAINT "autopay_mandates_authorized_amount_max_cents_check" CHECK (("authorized_amount_max_cents" > 0)),
    CONSTRAINT "autopay_mandates_day_of_month_check" CHECK ((("day_of_month" IS NULL) OR (("day_of_month" >= 1) AND ("day_of_month" <= 28)))),
    CONSTRAINT "autopay_mandates_mode_check" CHECK (("mode" = ANY (ARRAY['fixed'::"text", 'current_balance'::"text", 'minimum'::"text", 'recurring_only'::"text", 'special_only'::"text"])))
);


ALTER TABLE "public"."autopay_mandates" OWNER TO "postgres";


COMMENT ON TABLE "public"."autopay_mandates" IS 'Recurring-payment authorization from the homeowner. ACH autopay is the single biggest processor-cost saver vs one-off card payments.';



COMMENT ON COLUMN "public"."autopay_mandates"."setup_attempt_id" IS 'The Stripe setup attempt that enrolled this mandate (null for older rows).';



CREATE OR REPLACE FUNCTION "public"."cancel_autopay"("p_mandate_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "public"."autopay_mandates"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare m public.autopay_mandates;
begin
  select * into m from public.autopay_mandates where id = p_mandate_id;
  if not found then raise exception 'autopay mandate not found'; end if;
  if m.owner_id not in (select public.current_owner_ids()) and not public.can_manage_finance(m.portfolio_id) then
    raise exception 'permission denied';
  end if;
  update public.autopay_mandates
     set status = 'canceled', canceled_at = now(), canceled_by = auth.uid(),
         paused_reason = p_reason, updated_at = now()
   where id = p_mandate_id
   returning * into m;
  return m;
end;
$$;


ALTER FUNCTION "public"."cancel_autopay"("p_mandate_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_autopay_when_occupancy_ends"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if old.status = 'current' and new.status is distinct from 'current' and new.owner_id is not null then
    update public.autopay_mandates
       set status = 'canceled', canceled_at = now(), updated_at = now()
     where owner_id = new.owner_id
       and unit_id = new.unit_id
       and status <> 'canceled';
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."cancel_autopay_when_occupancy_ends"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_payment_plan"("p_plan_id" "uuid", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  pl public.payment_plans;
  v_case record;
begin
  select * into pl from public.payment_plans where id = p_plan_id for update;
  if pl.id is null or not public.can_manage_association(pl.association_id) or not public.is_any_staff() then
    raise exception 'Payment plan not found' using errcode = '42501';
  end if;
  if pl.status <> 'active' then
    raise exception 'This payment plan is no longer active' using errcode = '22023';
  end if;
  if char_length(btrim(coalesce(p_reason, ''))) < 5 then
    raise exception 'Say why the plan is being cancelled' using errcode = '22023';
  end if;
  update public.payment_plans
     set status = 'cancelled', cancel_reason = btrim(p_reason), cancelled_at = now(), updated_at = now()
   where id = pl.id;
  perform public.app_release_payment_plan_holds(pl.unit_id, 'Payment plan cancelled');
  insert into public.audit_logs (portfolio_id, entity_type, entity_id, action, actor_id, actor_email, changes)
  values (pl.portfolio_id, 'payment_plan', pl.id, 'payment_plan_cancelled', auth.uid(), (select email from auth.users where id = auth.uid()),
          jsonb_build_object('reason', btrim(p_reason)));
end $$;


ALTER FUNCTION "public"."cancel_payment_plan"("p_plan_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_purchase_order"("p_purchase_order_id" "uuid", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  po_row public.purchase_orders;
begin
  select * into po_row from public.purchase_orders where id = p_purchase_order_id for update;
  if not found then raise exception 'Purchase order not found'; end if;
  if not public.can_manage_finance(po_row.portfolio_id)
     or (po_row.association_id is not null and not public.can_manage_association(po_row.association_id)) then
    raise exception 'Permission denied';
  end if;
  if po_row.status = 'cancelled'::public.purchase_order_status then return; end if;
  if po_row.status = 'billed'::public.purchase_order_status or po_row.po_billed > 0 then
    raise exception 'Purchase orders with billed amounts cannot be cancelled';
  end if;
  if nullif(btrim(coalesce(p_reason, '')), '') is null then raise exception 'A cancellation reason is required'; end if;

  if po_row.approval_request_id is not null then
    update public.approval_requests
       set status = 'cancelled'::public.approval_request_status,
           decision_at = now(), decision_by = auth.uid()
     where id = po_row.approval_request_id
       and status = 'pending'::public.approval_request_status;
  end if;
  update public.purchase_orders
     set status = 'cancelled'::public.purchase_order_status,
         cancelled_at = now(),
         decision_note = btrim(p_reason),
         updated_at = now()
   where id = p_purchase_order_id;
end;
$$;


ALTER FUNCTION "public"."cancel_purchase_order"("p_purchase_order_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_report_run"("p_run_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare r public.report_runs;
begin
  select * into r from public.report_runs where id = p_run_id for update;
  if not found or not public.app_can_view_report_run(r.portfolio_id, r.definition_id, r.parameters) then
    raise exception 'Report run not found' using errcode = 'P0002';
  end if;
  if r.status not in ('queued', 'running') then
    raise exception 'This report has already finished' using errcode = '22023';
  end if;
  update public.report_runs set status = 'cancelled', finished_at = now(), updated_at = now() where id = r.id;
end $$;


ALTER FUNCTION "public"."cancel_report_run"("p_run_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_tenant_service_request"("p_service_request_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_updated uuid;
begin
  if auth.uid() is null or not public.is_tenant_user() then
    raise exception 'Resident portal access is required';
  end if;

  update public.service_requests sr
     set status = 'cancelled', updated_at = now()
   where sr.id = p_service_request_id
     and sr.tenant_id in (select public.current_tenant_ids())
     and sr.status in ('open', 'waiting')
     and sr.archived_at is null
     and not exists (
       select 1 from public.work_orders wo
       where wo.service_request_id = sr.id and wo.archived_at is null
     )
  returning sr.id into v_updated;

  return v_updated is not null;
end;
$$;


ALTER FUNCTION "public"."cancel_tenant_service_request"("p_service_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."capital_project_cost_totals"() RETURNS TABLE("project_id" "uuid", "work_order_count" integer, "committed_amount" numeric, "spent_amount" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  -- Same access as capital_project_spend_totals: worked out once per call.
  v_op boolean := coalesce(public.is_platform_operator(), false);
  v_pf uuid := public.my_access_portfolio();
  v_scoped boolean := coalesce(public.manager_is_scoped(), false);
  -- Purchase orders are finance-only: their open amounts count only for
  -- finance staff (same check as the purchase_orders policy).
  v_fin boolean := v_op or coalesce(public.my_finance_portfolio() = v_pf, false);
begin
  if not (v_op or v_pf is not null) then
    return;
  end if;

  return query
  with proj as (
    select p.id, p.association_id
      from public.capital_projects p
     where p.portfolio_id is not null
       and (v_op or p.portfolio_id = v_pf)
       and (not v_scoped
            or p.association_id is null
            or p.association_id in (select am.association_id
                                      from public.association_managers am
                                     where am.user_id = auth.uid()))
  ),
  links as (
    select distinct link.project_id, link.work_order_id, proj.association_id
      from public.capital_project_work_orders link
      join proj on proj.id = link.project_id
  ),
  bills as (
    select lk.project_id,
           sum(b.amount) filter (where b.status::text = 'paid') as spent,
           sum(b.amount) filter (where b.status::text in ('draft', 'pending_approval', 'approved')) as unpaid
      from links lk
      join public.payable_bills b on b.work_order_id = lk.work_order_id
     where b.archived_at is null
       and b.association_id = lk.association_id
     group by lk.project_id
  ),
  po_lines as (
    select lk.project_id, po.po_billed, l.line_total,
           sum(l.line_total) over (partition by lk.project_id, po.id order by l.sort_order, l.id) as running
      from links lk
      join public.purchase_orders po on po.work_order_id = lk.work_order_id
      join public.purchase_order_line_items l on l.purchase_order_id = po.id
     where v_fin
       and po.archived_at is null
       and po.association_id = lk.association_id
       and po.approval_status = 'approved'
       and po.status::text <> 'cancelled'
  ),
  pos as (
    select pl.project_id,
           sum(greatest(least(pl.line_total, pl.running - coalesce(pl.po_billed, 0)), 0)) as open_balance
      from po_lines pl
     group by pl.project_id
  ),
  counts as (
    select lk.project_id, count(*) as n from links lk group by lk.project_id
  )
  select proj.id,
         coalesce(counts.n, 0)::integer,
         (coalesce(pos.open_balance, 0) + coalesce(bills.unpaid, 0))::numeric(16, 2),
         coalesce(bills.spent, 0)::numeric(16, 2)
    from proj
    left join counts on counts.project_id = proj.id
    left join bills on bills.project_id = proj.id
    left join pos on pos.project_id = proj.id;
end
$$;


ALTER FUNCTION "public"."capital_project_cost_totals"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."capital_project_spend_totals"() RETURNS TABLE("project_id" "uuid", "work_order_count" integer, "committed_spend" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  -- Access is worked out once per call, not once per project. Same rules as
  -- project_budget_vs_actual: staff, company admin or platform operator;
  -- the caller's own company (any company for an operator); a scoped
  -- manager only their assigned associations. The company filter also sits
  -- inside the two totals so they never add up other companies' rows.
  v_op boolean := coalesce(public.is_platform_operator(), false);
  v_pf uuid := public.my_access_portfolio();
  v_scoped boolean := coalesce(public.manager_is_scoped(), false);
begin
  if not (v_op or v_pf is not null) then
    return;
  end if;

  return query
  select p.id,
         coalesce(links.n, 0)::integer,
         coalesce(spend.amount, 0)::numeric(16, 2)
    from public.capital_projects p
    left join (
      select link.project_id, count(distinct link.work_order_id) as n
        from public.capital_project_work_orders link
        join public.capital_projects lp on lp.id = link.project_id
       where v_op or lp.portfolio_id = v_pf
       group by link.project_id
    ) links on links.project_id = p.id
    left join (
      select link.project_id, sum(b.amount) as amount
        from public.capital_project_work_orders link
        join public.capital_projects lp on lp.id = link.project_id
        join public.payable_bills b on b.work_order_id = link.work_order_id
       where (v_op or lp.portfolio_id = v_pf)
         and b.archived_at is null
         and b.association_id = lp.association_id
         and b.status::text in ('approved', 'paid')
       group by link.project_id
    ) spend on spend.project_id = p.id
   where p.portfolio_id is not null
     and (v_op or p.portfolio_id = v_pf)
     and (not v_scoped
          or p.association_id is null
          or p.association_id in (select am.association_id
                                    from public.association_managers am
                                   where am.user_id = auth.uid()));
end
$$;


ALTER FUNCTION "public"."capital_project_spend_totals"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."capture_issued_payable_check"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare payment_id uuid; check_id uuid;
begin
  if new.status = 'paid'::public.payable_bill_status
     and new.paid_at is not null and new.bank_account_id is not null and new.check_number is not null
     and (old.status is distinct from new.status or old.check_number is distinct from new.check_number) then
    select id into payment_id from public.journal_entries
     where source_type = 'check_payment' and source_id = new.id
     order by created_at desc limit 1;
    if payment_id is null then raise exception 'Paid check is missing its payment journal entry'; end if;
    insert into public.payable_checks (
      portfolio_id, association_id, bill_id, vendor_id, bank_account_id,
      check_number, amount, payment_date, payment_entry_id, issued_by
    ) values (
      new.portfolio_id, new.association_id, new.id, new.vendor_id, new.bank_account_id,
      new.check_number, new.amount - coalesce(new.credit_applied, 0), new.paid_at::date, payment_id, auth.uid()
    ) returning id into check_id;
    -- Payment entries belong to checks, not bills. This permits a later reissue
    -- while retaining every original and reversal in the audit trail.
    update public.journal_entries set source_id = check_id where id = payment_id;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."capture_issued_payable_check"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cast_board_approval"("p_request_id" "uuid", "p_decision" "text", "p_signature" "text", "p_comment" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  r public.approval_requests%rowtype;
  v_member_id uuid;
  v_for integer;
  v_against integer;
  v_abstain integer;
  v_eligible integer;
  v_new_status public.approval_request_status;
  v_email text;
  v_pct numeric;
begin
  select * into r from public.approval_requests where id = p_request_id for update;
  if not found then raise exception 'Approval request not found'; end if;
  if r.archived_at is not null then raise exception 'Approval request not found'; end if;
  if r.status is distinct from 'pending'::public.approval_request_status then
    raise exception 'This approval request is already finalized';
  end if;
  if r.association_id is null or r.association_id not in (select public.current_board_association_ids()) then
    raise exception 'Not a board member for this request';
  end if;
  if r.owner_id is not null and r.owner_id in (select public.current_owner_ids()) then
    raise exception 'You cannot vote on your own request';
  end if;

  select lower(email) into v_email from auth.users where id = auth.uid() and email_confirmed_at is not null;
  if v_email is not null then
    update public.board_members bm
       set auth_user_id = auth.uid()
     where bm.auth_user_id is null
       and bm.active
       and bm.association_id = r.association_id
       and lower(bm.email) = v_email;
  end if;

  select bm.id into v_member_id
    from public.board_members bm
   where bm.auth_user_id = auth.uid()
     and bm.active
     and bm.association_id = r.association_id
   limit 1;
  if v_member_id is null then raise exception 'Not a board member for this request'; end if;
  if coalesce(cardinality(r.board_member_ids), 0) > 0
     and not (v_member_id = any(r.board_member_ids)) then
    raise exception 'Not an eligible voter for this approval request';
  end if;
  if p_decision not in ('approve', 'reject', 'abstain') then
    raise exception 'Invalid decision: %', p_decision;
  end if;
  if coalesce(r.signatures_required, false)
     and nullif(btrim(coalesce(p_signature, '')), '') is null then
    raise exception 'Signature required';
  end if;

  insert into public.approval_decisions (
    approval_request_id, board_member_id, decided_by, decision,
    signature_name, comment, decided_at
  ) values (
    p_request_id, v_member_id, auth.uid(), p_decision,
    nullif(btrim(coalesce(p_signature, '')), ''),
    nullif(btrim(coalesce(p_comment, '')), ''), now()
  )
  on conflict (approval_request_id, decided_by) do update
     set decision = excluded.decision,
         signature_name = excluded.signature_name,
         comment = excluded.comment,
         board_member_id = excluded.board_member_id,
         decided_at = now();

  select count(*) filter (where decision = 'approve'),
         count(*) filter (where decision = 'reject'),
         count(*) filter (where decision = 'abstain')
    into v_for, v_against, v_abstain
    from public.approval_decisions
   where approval_request_id = p_request_id;

  if coalesce(cardinality(r.board_member_ids), 0) > 0 then
    v_eligible := cardinality(r.board_member_ids);
  else
    select count(*) into v_eligible from public.board_members where association_id = r.association_id and active;
  end if;
  v_eligible := greatest(coalesce(v_eligible, 0), 0);

  v_new_status := null;
  if r.voting_scheme = 'any_one_approver' then
    if v_for >= 1 then v_new_status := 'approved';
    elsif v_for + v_against + v_abstain >= v_eligible and v_for = 0 then v_new_status := 'rejected';
    end if;
  elsif r.voting_scheme = 'majority_approval_required' then
    if v_for > v_eligible / 2.0 then v_new_status := 'approved';
    elsif v_against >= ceil(v_eligible / 2.0) then v_new_status := 'rejected';
    end if;
  elsif r.voting_scheme = 'unanimous_approval_required' then
    if v_against >= 1 or v_abstain >= 1 then v_new_status := 'rejected';
    elsif v_eligible > 0 and v_for >= v_eligible then v_new_status := 'approved';
    end if;
  elsif r.voting_scheme = 'percentage_required' then
    v_pct := coalesce(r.percentage_required::numeric, 50.0001);
    if v_for * 100.0 / greatest(v_eligible, 1) >= v_pct then
      v_new_status := 'approved';
    elsif (v_eligible - v_against - v_abstain) * 100.0 / greatest(v_eligible, 1) < v_pct then
      v_new_status := 'rejected';
    end if;
  end if;

  update public.approval_requests
     set votes_for = v_for,
         votes_against = v_against,
         votes_abstain = v_abstain,
         status = coalesce(v_new_status, status),
         decision_by = case when v_new_status is null then decision_by else auth.uid() end,
         decision_at = case when v_new_status is null then decision_at else now() end
   where id = p_request_id;
end;
$$;


ALTER FUNCTION "public"."cast_board_approval"("p_request_id" "uuid", "p_decision" "text", "p_signature" "text", "p_comment" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."change_unit_homeowner"("p_unit_id" "uuid", "p_new_owner_id" "uuid", "p_transfer_date" "date") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_association_id uuid;
  v_portfolio_id uuid;
  v_owner_portfolio_id uuid;
  v_dues numeric;
  v_frequency public.recurring_frequency;
begin
  if p_unit_id is null or p_new_owner_id is null or p_transfer_date is null then
    raise exception 'Unit, new owner and transfer date are required.' using errcode = '22023';
  end if;

  select b.association_id, a.portfolio_id
    into v_association_id, v_portfolio_id
  from public.units u
  join public.buildings b on b.id = u.building_id
  join public.associations a on a.id = b.association_id
  where u.id = p_unit_id and u.archived_at is null;

  if v_association_id is null then
    raise exception 'Unit not found.' using errcode = 'P0002';
  end if;

  if not public.can_manage_association(v_association_id)
     or not public.can_access_portfolio(v_portfolio_id) then
    raise exception 'You are not authorized to manage this unit.' using errcode = '42501';
  end if;

  -- ownership_fixes: checked before the buyer's occupancy is created.
  if p_transfer_date > public.association_local_date(v_association_id) then
    raise exception 'The transfer date can''t be in the future. Record the sale on or after its closing date.' using errcode = '22023';
  end if;

  select ow.portfolio_id into v_owner_portfolio_id
  from public.owners ow
  where ow.id = p_new_owner_id and ow.archived_at is null;

  if v_owner_portfolio_id is null or v_owner_portfolio_id <> v_portfolio_id then
    raise exception 'The new owner does not belong to this unit''s portfolio.' using errcode = '42501';
  end if;

  perform 1 from public.units where id = p_unit_id for update;

  if not exists (
    select 1 from public.occupancies o
    where o.unit_id = p_unit_id and o.owner_id = p_new_owner_id
      and o.occupancy_type = 'owner' and o.status = 'current'
  ) then
    select o.dues_amount, o.dues_frequency
      into v_dues, v_frequency
    from public.occupancies o
    where o.unit_id = p_unit_id and o.occupancy_type = 'owner' and o.status = 'current'
    order by o.is_primary desc nulls last, o.move_in_date desc nulls last
    limit 1;

    insert into public.occupancies (
      owner_id, unit_id, association_id, occupancy_type, status,
      move_in_date, dues_amount, dues_frequency, share_pct, is_primary
    ) values (
      p_new_owner_id, p_unit_id, v_association_id, 'owner', 'current',
      p_transfer_date, coalesce(v_dues, 0), coalesce(v_frequency, 'monthly'::public.recurring_frequency), 100, false
    );
  elsif not exists (
    select 1 from public.occupancies o
    where o.unit_id = p_unit_id and o.owner_id is distinct from p_new_owner_id
      and o.occupancy_type = 'owner' and o.status = 'current'
  ) then
    raise exception 'That owner already owns this unit.' using errcode = '22023';
  end if;

  return public.transfer_unit_ownership(p_unit_id, p_new_owner_id, p_transfer_date);
end;
$$;


ALTER FUNCTION "public"."change_unit_homeowner"("p_unit_id" "uuid", "p_new_owner_id" "uuid", "p_transfer_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."charge_back_work_order"("p_work_order" "uuid", "p_category" "uuid", "p_amount" numeric, "p_description" "text", "p_due_date" "date" DEFAULT NULL::"date") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  w public.work_orders;
  v_portfolio uuid;
  cat public.charge_categories;
  v_amount numeric(14,2);
  v_desc text;
  v_id uuid;
begin
  if auth.uid() is null then raise exception 'Authentication required' using errcode = '42501'; end if;
  select * into w from public.work_orders where id = p_work_order and archived_at is null for update;
  if not found then raise exception 'Work order not found' using errcode = 'P0002'; end if;
  -- The company comes from the association, never from the work order row.
  select a.portfolio_id into v_portfolio from public.associations a where a.id = w.association_id;
  if w.portfolio_id is not null and w.portfolio_id is distinct from v_portfolio then
    raise exception 'This work order''s company does not match its association' using errcode = '22023';
  end if;
  if v_portfolio is null
     or not (public.is_platform_operator()
             or (public.can_manage_finance(v_portfolio) and public.can_manage_association(w.association_id))) then
    raise exception 'Work order not found' using errcode = 'P0002';
  end if;
  if w.unit_id is null then
    raise exception 'This work order is for a common area — there is no homeowner to charge' using errcode = '22023';
  end if;
  if not exists (select 1 from public.units u join public.buildings b on b.id = u.building_id
                 where u.id = w.unit_id and b.association_id = w.association_id) then
    raise exception 'This work order''s unit is not in its association — fix the work order first' using errcode = '22023';
  end if;
  if p_amount is null or p_amount <= 0 then raise exception 'Enter an amount above zero' using errcode = '22023'; end if;
  if p_amount <> round(p_amount, 2) then raise exception 'Amount can have at most two decimals' using errcode = '22023'; end if;
  if p_amount > 100000 then raise exception 'Amount looks too large — enter it as a regular charge if intended' using errcode = '22023'; end if;
  v_amount := p_amount;
  select * into cat from public.charge_categories c
   where c.id = p_category and c.portfolio_id = v_portfolio and c.archived_at is null and coalesce(c.active, true)
     and (c.association_id is null or c.association_id = w.association_id);
  if not found then raise exception 'Pick a charge category' using errcode = '22023'; end if;
  v_desc := nullif(btrim(coalesce(p_description, '')), '');
  if v_desc is null then
    v_desc := 'Chargeback: ' || coalesce(w.title, 'repair') || coalesce(' (work order #' || w.number || ')', '');
  end if;
  if length(v_desc) > 500 then raise exception 'Keep the description under 500 characters' using errcode = '22023'; end if;
  insert into public.charges (unit_id, charge_category_id, charge_type, description, amount, due_date, gl_account_id, created_by, work_order_id)
  values (w.unit_id, cat.id, cat.charge_type, v_desc, v_amount, coalesce(p_due_date, current_date), cat.gl_account_id, auth.uid(), w.id)
  returning id into v_id;
  insert into public.work_order_updates (work_order_id, note, created_by, staff_only)
  values (w.id, 'Charged back ' || to_char(v_amount, 'FM$999,999,990.00') || ' to the homeowner (' || cat.name || ')', auth.uid(), true);
  return v_id;
end $_$;


ALTER FUNCTION "public"."charge_back_work_order"("p_work_order" "uuid", "p_category" "uuid", "p_amount" numeric, "p_description" "text", "p_due_date" "date") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."charges" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "unit_id" "uuid" NOT NULL,
    "assessment_period_id" "uuid",
    "charge_type" "public"."charge_type" DEFAULT 'assessment'::"public"."charge_type" NOT NULL,
    "description" "text" NOT NULL,
    "amount" numeric(10,2) NOT NULL,
    "due_date" "date" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid",
    "gl_account_id" "uuid",
    "charge_category_id" "uuid",
    "work_order_id" "uuid",
    CONSTRAINT "charges_amount_check" CHECK (("amount" >= (0)::numeric))
);


ALTER TABLE "public"."charges" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."charge_gl_accounts"("p_charge" "public"."charges", OUT "portfolio_id" "uuid", OUT "association_id" "uuid", OUT "ar" "uuid", OUT "income" "uuid") RETURNS "record"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_assoc uuid; v_portfolio uuid; v_cat_gl uuid;
begin
  v_assoc := public.unit_association_id(p_charge.unit_id);
  select a.portfolio_id into v_portfolio from public.associations a where a.id = v_assoc;
  select cc.gl_account_id into v_cat_gl from public.charge_categories cc where cc.id = p_charge.charge_category_id;
  portfolio_id := v_portfolio;
  association_id := v_assoc;
  ar := coalesce(public.app_gl_map(v_portfolio, v_assoc, 'accounts_receivable'), public.gl_pick(v_portfolio, v_assoc, array['accounts_receivable'], null, '%allowance%'));
  income := coalesce(
    case when public.budget_gl_account_scope_valid(v_assoc, p_charge.gl_account_id) then p_charge.gl_account_id end,
    case when public.budget_gl_account_scope_valid(v_assoc, v_cat_gl) then v_cat_gl end,
    case when p_charge.charge_type::text = 'late_fee' then coalesce(public.app_gl_map(v_portfolio, v_assoc, 'late_fee_income'), public.gl_pick(v_portfolio, v_assoc, array['income'], '%late fee%')) end,
    case when p_charge.charge_type::text = 'nsf_fee' then public.gl_pick(v_portfolio, v_assoc, array['income', 'other_income'], '%nsf fee%', '%transfer%') end,
    case when p_charge.charge_type::text = 'fine' then coalesce(
      public.gl_pick(v_portfolio, v_assoc, array['income', 'other_income'], '%violation%'),
      public.gl_pick(v_portfolio, v_assoc, array['income', 'other_income'], '%fine%', '%refin%')) end,
    public.app_gl_map(v_portfolio, v_assoc, 'default_income'),
    public.gl_pick(v_portfolio, v_assoc, array['income']));
end $$;


ALTER FUNCTION "public"."charge_gl_accounts"("p_charge" "public"."charges", OUT "portfolio_id" "uuid", OUT "association_id" "uuid", OUT "ar" "uuid", OUT "income" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."charge_late_fees_now"("p_association_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_pid uuid;
  c record;
  v_fee uuid;
  v_count integer := 0;
  v_total numeric := 0;
begin
  select portfolio_id into v_pid from public.associations where id = p_association_id and archived_at is null;
  if v_pid is null or not public.can_manage_finance(v_pid) or not public.can_manage_association(p_association_id) then
    raise exception 'You do not have accounting access to this association' using errcode = '42501';
  end if;
  if not exists (select 1 from public.associations where id = p_association_id and late_fee_enabled and coalesce(late_fee_amount, 0) > 0) then
    raise exception 'Late fees are turned off for this association — set the late fee policy first' using errcode = '22023';
  end if;

  for c in
    select ch.id
      from public.charges ch
      join public.units u on u.id = ch.unit_id
      join public.buildings b on b.id = u.building_id
     where b.association_id = p_association_id and ch.charge_type = 'assessment'
       and ch.due_date + coalesce((select a.late_fee_grace_days from public.associations a where a.id = p_association_id), 0) < (select public.association_local_date(p_association_id))
       and not exists (select 1 from public.late_fee_assessments l where l.charge_id = ch.id)
       and ch.amount - coalesce((select sum(pa.amount_applied) from public.payment_applications pa where pa.charge_id = ch.id), 0) > 0.005
     order by ch.due_date
  loop
    v_fee := public.assess_late_fee(c.id);
    if v_fee is not null then
      v_count := v_count + 1;
      v_total := v_total + coalesce((select amount from public.charges where id = v_fee), 0);
    end if;
  end loop;

  insert into public.audit_logs (portfolio_id, entity_type, entity_id, action, actor_id, actor_email, changes)
  values (v_pid, 'association', p_association_id, 'late_fees_charged', auth.uid(), (select email from auth.users where id = auth.uid()),
          jsonb_build_object('fees', v_count, 'total', v_total));
  return jsonb_build_object('fees', v_count, 'total', round(v_total, 2));
end $$;


ALTER FUNCTION "public"."charge_late_fees_now"("p_association_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."charge_ledger_date"("p_charge" "public"."charges") RETURNS "date"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_date date := coalesce(p_charge.due_date, current_date);
begin
  if p_charge.charge_type::text in ('fine', 'late_fee', 'nsf_fee') then
    v_date := least(v_date, public.association_local_date(public.unit_association_id(p_charge.unit_id), coalesce(p_charge.created_at, now())));
  end if;
  return v_date;
end $$;


ALTER FUNCTION "public"."charge_ledger_date"("p_charge" "public"."charges") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."chargeback_totals"("p_association_id" "uuid" DEFAULT NULL::"uuid", "p_unit_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    SET "plan_cache_mode" TO 'force_generic_plan'
    AS $$
declare
  v_totals jsonb;
begin
  select jsonb_build_object(
           'count', count(*),
           'unpaid', coalesce(sum(x.balance_due) filter (where x.balance_due > 0.004), 0))
    into v_totals
    from (
      select coalesce(cb.balance_due, c.amount) as balance_due
        from public.charges c
        join public.units u on u.id = c.unit_id
        join public.buildings b on b.id = u.building_id
        left join public.v_charge_balances cb on cb.charge_id = c.id
       where c.work_order_id is not null
         and (p_association_id is null or b.association_id = p_association_id)
         and (p_unit_ids is null or c.unit_id = any (p_unit_ids))
    ) x;
  return v_totals;
end
$$;


ALTER FUNCTION "public"."chargeback_totals"("p_association_id" "uuid", "p_unit_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."charges_late_fee_removed_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if current_user in ('authenticated', 'anon') and public.is_removed_late_fee(old.id) then
    if tg_op = 'DELETE' then
      raise exception 'This late fee was removed and can''t be deleted.' using errcode = '42501';
    end if;
    if (to_jsonb(new) - 'description') is distinct from (to_jsonb(old) - 'description') then
      raise exception 'This late fee was removed and can''t be changed.' using errcode = '42501';
    end if;
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end
$$;


ALTER FUNCTION "public"."charges_late_fee_removed_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_insurance_expirations"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  with ld as (
    select x.aid, public.association_local_date(x.aid) as today
      from (select distinct association_id as aid from public.insurance_policies where status = 'active') x
  )
  update public.insurance_policies ip
     set status = 'expiring_soon', updated_at = pg_catalog.now()
    from ld
   where ld.aid is not distinct from ip.association_id
     and ip.status = 'active'
     and ip.expiration_date <= ld.today + 30
     and ip.expiration_date > ld.today;
  with ld as (
    select x.aid, public.association_local_date(x.aid) as today
      from (select distinct association_id as aid from public.insurance_policies where status in ('active', 'expiring_soon')) x
  )
  update public.insurance_policies ip
     set status = 'expired', updated_at = pg_catalog.now()
    from ld
   where ld.aid is not distinct from ip.association_id
     and ip.status in ('active', 'expiring_soon')
     and ip.expiration_date < ld.today;
end
$$;


ALTER FUNCTION "public"."check_insurance_expirations"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_portfolio_not_suspended"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  is_suspended boolean;
begin
  if new.portfolio_id is not null then
    select suspended_at is not null into is_suspended
      from public.portfolios where id = new.portfolio_id;
    if is_suspended then
      raise exception 'portfolio % is suspended; no new user assignments allowed', new.portfolio_id;
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."check_portfolio_not_suspended"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_posted_entry_lines_balanced"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_entry uuid;
  v_debit numeric;
  v_credit numeric;
begin
  foreach v_entry in array array_remove(array[
    case when tg_op <> 'DELETE' then new.entry_id end,
    case when tg_op <> 'INSERT' then old.entry_id end
  ], null) loop
    continue when not exists (select 1 from public.journal_entries where id = v_entry and posted);
    select coalesce(sum(debit_amount), 0), coalesce(sum(credit_amount), 0)
      into v_debit, v_credit
      from public.journal_lines where entry_id = v_entry;
    if abs(v_debit - v_credit) > 0.001 then
      raise exception 'Posted journal entry % would be unbalanced: debits=% credits=%', v_entry, v_debit, v_credit
        using errcode = '23514';
    end if;
  end loop;
  return null;
end;
$$;


ALTER FUNCTION "public"."check_posted_entry_lines_balanced"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_seat_limit"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  sub public.subscriptions;
  current_staff_count integer;
begin
  if new.portfolio_id is null or new.hoa_role <> 'manager' then
    return new;
  end if;

  if tg_op = 'UPDATE' and old.portfolio_id = new.portfolio_id and old.hoa_role = 'manager' then
    return new;  -- no-op for this table
  end if;

  select * into sub from public.subscriptions where portfolio_id = new.portfolio_id;
  if not found then
    return new;  -- no subscription = no limit enforced
  end if;

  select count(*) into current_staff_count
    from public.profiles
   where portfolio_id = new.portfolio_id and hoa_role = 'manager';

  if current_staff_count >= sub.seats_included then
    raise exception 'portfolio % has reached its seat limit (% of %). Upgrade to add more staff.',
      new.portfolio_id, current_staff_count, sub.seats_included
      using errcode = 'P0001';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."check_seat_limit"() OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."automation_flow_runs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "flow_id" "uuid" NOT NULL,
    "subject_type" "text" NOT NULL,
    "subject_id" "uuid" NOT NULL,
    "fired_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "status" "text" DEFAULT 'success'::"text" NOT NULL,
    "detail" "jsonb",
    "attempt_count" integer DEFAULT 1 NOT NULL,
    "last_attempt_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "automation_flow_runs_attempt_count_check" CHECK ((("attempt_count" >= 1) AND ("attempt_count" <= 5))),
    CONSTRAINT "automation_flow_runs_status_check" CHECK (("status" = ANY (ARRAY['success'::"text", 'partial'::"text", 'failed'::"text"])))
);


ALTER TABLE "public"."automation_flow_runs" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_automation_flow_run"("p_flow_id" "uuid", "p_subject_type" "text", "p_subject_id" "uuid") RETURNS SETOF "public"."automation_flow_runs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if auth.role() <> 'service_role' then raise exception 'Service role required'; end if;
  if nullif(trim(p_subject_type), '') is null then raise exception 'Subject type is required'; end if;
  -- Changed: a suspended company's flows wait until it is reactivated (no run
  -- row is written, so the subject is claimed on a later run).
  if exists (select 1 from public.automation_flows f
               join public.portfolios pf on pf.id = f.portfolio_id
              where f.id = p_flow_id and pf.suspended_at is not null) then
    return;
  end if;
  return query
  insert into public.automation_flow_runs
    (flow_id, subject_type, subject_id, status, attempt_count, last_attempt_at)
  values (p_flow_id, left(trim(p_subject_type), 100), p_subject_id, 'failed', 1, now())
  on conflict (flow_id, subject_type, subject_id) do update
    set status = 'failed', attempt_count = public.automation_flow_runs.attempt_count + 1, last_attempt_at = now()
    where public.automation_flow_runs.status in ('failed', 'partial')
      and public.automation_flow_runs.attempt_count < 5
      and public.automation_flow_runs.last_attempt_at < now() - interval '10 minutes'
  returning *;
end;
$$;


ALTER FUNCTION "public"."claim_automation_flow_run"("p_flow_id" "uuid", "p_subject_type" "text", "p_subject_id" "uuid") OWNER TO "postgres";


