COMMENT ON COLUMN "public"."email_queue"."suppressed_at" IS 'Set when the email was not sent because the address is unsubscribed, bounced or complained (error_message says which).';



COMMENT ON COLUMN "public"."email_queue"."platform_mail" IS 'The platform''s own mail (set by server code only; signed-in writes can''t set it). Exempt from the suspended-company hold and the company unsubscribe link; sent from the platform address.';



CREATE OR REPLACE FUNCTION "public"."claim_email_queue"("p_limit" integer DEFAULT 10) RETURNS SETOF "public"."email_queue"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if auth.role() <> 'service_role' then raise exception 'Service role required'; end if;
  if p_limit < 1 or p_limit > 50 then raise exception 'Claim limit must be between 1 and 50'; end if;

  return query
  with due as (
    select id
    from public.email_queue
    where status in ('pending', 'failed')
      and attempt_count < 5
      and next_attempt_at <= now()
      and (processing_at is null or processing_at < now() - interval '10 minutes')
    order by next_attempt_at, created_at
    for update skip locked
    limit p_limit
  )
  update public.email_queue q
  set processing_at = now(), attempt_count = q.attempt_count + 1, status = 'pending', error_message = null
  from due
  where q.id = due.id
  returning q.*;
end;
$$;


ALTER FUNCTION "public"."claim_email_queue"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_email_queue_snapshot"("p_limit" integer DEFAULT 10) RETURNS SETOF "public"."email_queue"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if auth.role() <> 'service_role' then raise exception 'Service role required'; end if;
  if p_limit < 1 or p_limit > 50 then raise exception 'Claim limit must be between 1 and 50'; end if;

  return query
  with due as (
    select id
    from public.email_queue
    where status in ('pending', 'failed')
      and attempt_count < 5
      and suppressed_at is null
      and next_attempt_at <= now()
      and (processing_at is null or processing_at < now() - interval '10 minutes')
      and not exists (
        select 1 from public.portfolios pf
         where pf.id = email_queue.portfolio_id
           and pf.suspended_at is not null
           and not email_queue.platform_mail)
    order by holds_auth_link desc, next_attempt_at, created_at
    for update skip locked
    limit p_limit
  )
  update public.email_queue q
  set processing_at = now(), attempt_count = q.attempt_count + 1, snapshot_claims = q.snapshot_claims + 1,
      status = 'pending', error_message = null
  from due
  where q.id = due.id
  returning q.*;
end;
$$;


ALTER FUNCTION "public"."claim_email_queue_snapshot"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_import_lock"("p_scope_id" "uuid", "p_kind" "text") RETURNS timestamp with time zone
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_claimed_at timestamptz;
begin
  if not public.can_hold_import_lock(p_scope_id) then
    raise exception 'Association or company not found' using errcode = '42501';
  end if;
  if p_kind is null or length(p_kind) not between 1 and 60 then
    raise exception 'Invalid import kind' using errcode = '22023';
  end if;
  delete from public.import_locks
   where scope_id = p_scope_id and kind = p_kind
     and claimed_at < now() - interval '15 minutes';
  insert into public.import_locks (scope_id, kind, claimed_by, claimed_at)
  values (p_scope_id, p_kind, auth.uid(), now())
  on conflict (scope_id, kind) do nothing
  returning claimed_at into v_claimed_at;
  return v_claimed_at;
end $$;


ALTER FUNCTION "public"."claim_import_lock"("p_scope_id" "uuid", "p_kind" "text") OWNER TO "postgres";


