CREATE OR REPLACE FUNCTION "public"."claim_sms_messages"("p_limit" integer DEFAULT 20) RETURNS SETOF "public"."sms_messages"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'Service role required';
  end if;
  return query
  with candidates as (
    select id from public.sms_messages
    where direction = 'outbound'
      and status in ('queued', 'failed')
      and attempt_count < 8
      and next_attempt_at <= now()
      and (locked_at is null or locked_at < now() - interval '5 minutes')
      and exists (
        select 1
        from public.sms_conversations conversation
        join public.sms_opt_ins consent
          on consent.portfolio_id = conversation.portfolio_id
         and consent.phone_number = sms_messages.to_number
         and consent.opted_in
        -- Changed: not for a suspended company (waits until reactivated).
        join public.portfolios pf
          on pf.id = conversation.portfolio_id
         and pf.suspended_at is null
        where conversation.id = sms_messages.conversation_id
      )
    order by next_attempt_at, created_at
    for update skip locked
    limit least(greatest(p_limit, 1), 100)
  )
  update public.sms_messages message
  set locked_at = now(), last_attempt_at = now(), attempt_count = attempt_count + 1
  from candidates where message.id = candidates.id
  returning message.*;
end;
$$;


ALTER FUNCTION "public"."claim_sms_messages"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_stripe_autopay_run"("p_mandate_id" "uuid", "p_scheduled_for" "date") RETURNS TABLE("run_id" "uuid", "idempotency_key" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_mandate public.autopay_mandates%rowtype;
  v_method public.payment_methods%rowtype;
  v_association public.associations%rowtype;
  v_run public.stripe_autopay_runs%rowtype;
  v_run_id uuid := gen_random_uuid();
begin
  select * into v_mandate
  from public.autopay_mandates
  where id = p_mandate_id
  for update;

  if not found
     or v_mandate.status::text <> 'active'
     or v_mandate.next_run_date is distinct from p_scheduled_for
     or p_scheduled_for > current_date then
    return;
  end if;

  -- Changed: no AutoPay charge while the company is suspended (the run is not
  -- claimed and the mandate keeps its date, so it runs after reactivation).
  if exists (select 1 from public.portfolios pf
              where pf.id = v_mandate.portfolio_id and pf.suspended_at is not null) then
    return;
  end if;

  select * into v_method from public.payment_methods where id = v_mandate.payment_method_id;
  select * into v_association from public.associations where id = v_mandate.association_id;

  if v_method.id is null
     or v_association.id is null
     or v_method.owner_id is distinct from v_mandate.owner_id
     or v_method.portfolio_id is distinct from v_mandate.portfolio_id
     or v_method.association_id is distinct from v_mandate.association_id
     or v_method.processor::text <> 'stripe'
     or v_method.processor_account_id is distinct from v_association.stripe_account_id
     or not coalesce(v_association.stripe_charges_enabled, false)
     or not coalesce(v_association.stripe_payouts_enabled, false)
     or v_association.stripe_deauthorized_at is not null then
    raise exception 'AutoPay mandate is not bound to a payment-ready association Stripe account';
  end if;

  insert into public.stripe_autopay_runs(
    id, mandate_id, scheduled_for, processor_account_id, idempotency_key
  ) values (
    v_run_id,
    p_mandate_id,
    p_scheduled_for,
    v_association.stripe_account_id,
    'autopay-run-' || v_run_id::text
  )
  on conflict (mandate_id, scheduled_for) do nothing
  returning * into v_run;

  if found then
    run_id := v_run.id;
    idempotency_key := v_run.idempotency_key;
    return next;
    return;
  end if;

  update public.stripe_autopay_runs
  set status = 'claimed',
      attempts = attempts + 1,
      claimed_at = now(),
      updated_at = now(),
      failure_reason = null
  where mandate_id = p_mandate_id
    and scheduled_for = p_scheduled_for
    and attempts < 3
    and (
      (status = 'claimed' and claimed_at < now() - interval '10 minutes')
      or (status = 'intent_created' and updated_at < now() - interval '10 minutes')
      or (status = 'failed' and processor_payment_intent_id is null)
    )
  returning * into v_run;

  if found then
    run_id := v_run.id;
    idempotency_key := v_run.idempotency_key;
    return next;
  end if;
end;
$$;


ALTER FUNCTION "public"."claim_stripe_autopay_run"("p_mandate_id" "uuid", "p_scheduled_for" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_stripe_webhook_event"("p_event_id" "text", "p_processor_account_id" "text", "p_event_type" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  v_claimed boolean := false;
begin
  if p_event_id !~ '^evt_[A-Za-z0-9_]+$'
     or length(p_event_type) not between 1 and 120
     or (p_processor_account_id is not null and p_processor_account_id !~ '^acct_[A-Za-z0-9]+$') then
    raise exception 'Invalid Stripe event identity';
  end if;

  insert into public.stripe_webhook_events(event_id, processor_account_id, event_type)
  values (p_event_id, p_processor_account_id, p_event_type)
  on conflict (event_id) do nothing;
  if found then
    return true;
  end if;

  update public.stripe_webhook_events
  set status = 'processing',
      attempts = attempts + 1,
      claimed_at = now(),
      last_error = null
  where event_id = p_event_id
    and processor_account_id is not distinct from p_processor_account_id
    and event_type = p_event_type
    and (status = 'failed' or (status = 'processing' and claimed_at < now() - interval '5 minutes'))
  returning true into v_claimed;

  return coalesce(v_claimed, false);
end;
$_$;


ALTER FUNCTION "public"."claim_stripe_webhook_event"("p_event_id" "text", "p_processor_account_id" "text", "p_event_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_webhook_deliveries"("p_limit" integer DEFAULT 20) RETURNS TABLE("delivery_id" "uuid", "endpoint_id" "uuid", "endpoint_url" "text", "signing_secret" "text", "event_type" "public"."webhook_event", "payload" "jsonb", "attempts" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if coalesce(auth.role(), '') <> 'service_role' then raise exception 'Service role required'; end if;
  return query
  with candidates as (
    select delivery.id
    from public.webhook_deliveries delivery
    join public.webhook_endpoints endpoint on endpoint.id = delivery.endpoint_id
    where delivery.status in ('pending', 'retrying')
      and delivery.next_attempt_at <= now()
      and (delivery.locked_at is null or delivery.locked_at < now() - interval '5 minutes')
      and endpoint.active
      and (endpoint.disabled_until is null or endpoint.disabled_until < now())
      -- Changed: a suspended company's events wait until it is reactivated.
      and not exists (
        select 1 from public.portfolios pf
         where pf.id = endpoint.portfolio_id and pf.suspended_at is not null)
    order by delivery.next_attempt_at, delivery.created_at
    for update of delivery skip locked
    limit least(greatest(p_limit, 1), 100)
  ), claimed as (
    update public.webhook_deliveries delivery
    set locked_at = now()
    from candidates where delivery.id = candidates.id
    returning delivery.*
  )
  select claimed.id, endpoint.id, endpoint.url, endpoint.signing_secret,
         claimed.event_type, claimed.payload, claimed.attempts
  from claimed join public.webhook_endpoints endpoint on endpoint.id = claimed.endpoint_id;
end;
$$;


ALTER FUNCTION "public"."claim_webhook_deliveries"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."classify_service_request"("p_text" "text", OUT "kind" "text", OUT "topic" "text", OUT "category" "public"."work_order_category", OUT "priority_floor" "public"."service_request_priority", OUT "reasons" "text"[]) RETURNS "record"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  t text := lower(coalesce(p_text, ''));
  m text;
begin
  reasons := '{}';
  priority_floor := 'low';
  m := substring(t from '\m(flood(ed|ing)?|burst( pipe)?|pipe burst|gas leak|gas smell|smell(s|ing)? (of |like )?gas|carbon monoxide|sparks?|sparking|burning smell|smell(s|ing)? (of |like )?burning|smoke (coming|from|in the)|sewage|sewer back(ing|up|s)?|no heat|water (is )?(pouring|gushing)|ceiling (collapsed|caving|is falling)|stuck in (the |an )?elevator|trapped)\M');
  if m is not null then
    priority_floor := 'emergency';
    reasons := reasons || ('Emergency wording: "' || m || '"');
  else
    m := substring(t from '\m(leak(s|ing|ed|age|y)?|no hot water|water damage|mold|mould|rats?|mice|mouse|roach(es)?|cockroach(es)?|bed ?bugs?|infest(ed|ation)?|no (power|electricity)|not locking|won''t lock|broken (lock|door|window|entry door)|urgent(ly)?|asap|emergency)\M');
    if m is not null then
      priority_floor := 'high';
      reasons := reasons || ('Urgent wording: "' || m || '"');
    end if;
  end if;
  category := case
    when t ~ '\m(rats?|mice|mouse|rodents?|roach(es)?|cockroach(es)?|pests?|exterminat\w*|bugs?|insects?|bed ?bugs?|ants|termites?|wasps?|bees)\M' then 'pest_control'
    when t ~ '\m(leak\w*|pipes?|drain\w*|toilets?|sinks?|faucets?|water heater|hot water|sewer|sewage|clog\w*|plumb\w*|showers?|tub|flood\w*|water)\M' then 'plumbing'
    when t ~ '\m(lights?|lighting|outlets?|breakers?|power|electric\w*|bulbs?|fuses?|wiring|sparks?|sparking)\M' then 'electrical'
    when t ~ '\m(dryers?|washers?|washing machine|dishwasher|refrigerator|fridge|stove|oven|microwave|garbage disposal|laundry)\M' then 'appliance'
    when t ~ '\m(heat\w*|a/c|ac|air condition\w*|hvac|furnace|boiler|vents?|ducts?|thermostat|radiators?)\M' then 'hvac'
    when t ~ '\m(weeds?|grass|trees?|lawn|landscap\w*|snow|shrubs?|bushes|mulch|branches|yard)\M' then 'landscaping'
    when t ~ '\m(hallways?|lobby|parking|garage|elevators?|mailbox(es)?|doors?|buzzer|intercom|roof|gutters?|stairs|stairwell|balcony|porch|chute|trash|debris|gate|windows?|ceiling|walls?)\M' then 'common_area'
    else null end;
  topic := case
    when t ~ '\m(ledger|statement|balance|late fees?|special assessment|invoice|refund|autopay|auto-pay|payments?|charged|move[- ]in (charge|fee)|dues)\M' then 'account'
    when t ~ '\m(move[- ]?(in|out)|moving (in|out)|movers?|my move|elevator reservation)\M' then 'move'
    when t ~ '\m(insurance|dec page|declarations? page|certificate of insurance|coi|hazard coverage|master policy|ho-?6)\M' then 'insurance'
    when t ~ '\m(minutes|bylaws|by-laws|declaration|rules and regulations|budget|financials|financial statements?|resale|estoppel|paid assessment letter|disclosure)\M' then 'documents'
    when t ~ '\m(key ?fobs?|fobs?|keys? (copy|copies|made)|call ?box|directory|buzzer code|gate code|garage (remote|opener))\M' then 'access'
    when t ~ '\m(board members?|contact the board|the board|meeting|vote|election|proxy)\M' then 'governance'
    else null end;
  if topic is not null and priority_floor = 'low'
     and (category is null or topic in ('account', 'documents', 'insurance')) then
    kind := 'admin';
    category := 'other';
    reasons := reasons || ('Looks like a ' || case topic
      when 'account' then 'billing / account question'
      when 'documents' then 'document request'
      when 'insurance' then 'insurance question'
      when 'move' then 'move-in / move-out question'
      when 'access' then 'keys / access question'
      else 'board / governance question' end || ', not a repair');
  else
    kind := 'maintenance';
    topic := null;
    category := coalesce(category, 'general_repair');
  end if;
end $$;


ALTER FUNCTION "public"."classify_service_request"("p_text" "text", OUT "kind" "text", OUT "topic" "text", OUT "category" "public"."work_order_category", OUT "priority_floor" "public"."service_request_priority", OUT "reasons" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."clear_email_bounce"("p_suppression_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  s public.email_suppressions;
begin
  select * into s from public.email_suppressions where id = p_suppression_id;
  if not found or not public.is_any_staff() or public.manager_is_scoped()
     or not public.can_access_portfolio(s.portfolio_id) then
    raise exception 'Suppression not found' using errcode = '42501';
  end if;
  if s.reason <> 'bounced' then
    raise exception 'Only the recipient can undo an unsubscribe or spam report' using errcode = '42501';
  end if;
  if s.cleared_at is not null then return; end if;
  update public.email_suppressions
     set cleared_at = now(), cleared_by = auth.uid(), source = 'cleared_by_staff'
   where id = p_suppression_id;
end $$;


ALTER FUNCTION "public"."clear_email_bounce"("p_suppression_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."clear_service_request_duplicate"("p_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v public.service_requests;
begin
  v := public.service_request_staff_scope(p_id);
  update public.service_requests
     set duplicate_of = null, duplicate_score = null, duplicate_reviewed = true, updated_at = now()
   where id = p_id;
end $$;


ALTER FUNCTION "public"."clear_service_request_duplicate"("p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."company_state_rules_audit"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_row public.company_state_rules := coalesce(new, old);
begin
  -- Rows removed with their company (on delete cascade) leave no log entry.
  if tg_op = 'DELETE' and not exists (select 1 from public.portfolios p where p.id = old.portfolio_id) then
    return null;
  end if;
  insert into public.audit_logs (portfolio_id, entity_type, entity_id, action, actor_id, changes)
  values (v_row.portfolio_id, 'company_state_rule', v_row.id,
          case tg_op when 'INSERT' then 'state_rule_added' when 'UPDATE' then 'state_rule_updated' else 'state_rule_removed' end,
          auth.uid(),
          jsonb_build_object('state_code', v_row.state_code,
                             'before', case when tg_op <> 'INSERT' then to_jsonb(old) end,
                             'after', case when tg_op <> 'DELETE' then to_jsonb(new) end));
  return null;
end;
$$;


ALTER FUNCTION "public"."company_state_rules_audit"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."company_state_rules_touch"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if tg_op = 'UPDATE' then
    new.id := old.id;
    new.portfolio_id := old.portfolio_id;
    new.state_code := old.state_code;
    new.created_at := old.created_at;
  else
    new.created_at := now();
  end if;
  new.updated_at := now();
  new.updated_by := auth.uid();
  return new;
end;
$$;


ALTER FUNCTION "public"."company_state_rules_touch"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_bank_transfer"("p_transfer_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  t public.bank_transfers;
  f public.bank_accounts;
  d public.bank_accounts;
  v_assoc uuid;
  v_entry uuid;
begin
  select * into t from public.bank_transfers where id = p_transfer_id for update;
  if not found or not public.can_manage_finance(t.portfolio_id) then
    raise exception 'Transfer not found';
  end if;
  if t.voided_at is not null then
    raise exception 'This transfer is void';
  end if;
  if t.journal_entry_id is not null then
    raise exception 'This transfer is already completed';
  end if;
  perform public.app_check_transfer_accounts(t.portfolio_id, t.from_bank_account_id, t.to_bank_account_id);
  select * into f from public.bank_accounts where id = t.from_bank_account_id and portfolio_id = t.portfolio_id;
  select * into d from public.bank_accounts where id = t.to_bank_account_id and portfolio_id = t.portfolio_id;
  if f.id is null or d.id is null then
    raise exception 'One of the transfer''s bank accounts was not found';
  end if;
  if not public.can_view_association_row(f.association_id) or not public.can_view_association_row(d.association_id) then
    raise exception 'This transfer involves an association you do not manage';
  end if;
  if f.gl_account_id is null or d.gl_account_id is null then
    raise exception 'Link both bank accounts to GL accounts before completing this transfer';
  end if;
  v_assoc := coalesce(f.association_id, d.association_id);

  select id into v_entry from public.journal_entries
   where source_type = 'bank_transfer' and source_id = t.id and not posted
   order by created_at desc limit 1;
  if v_entry is not null then
    update public.journal_entries set posted = true, posted_at = now() where id = v_entry;
    update public.bank_transfers set journal_entry_id = v_entry, updated_at = now() where id = t.id;
    return v_entry;
  end if;

  insert into public.journal_entries (portfolio_id, entry_date, description, reference_number, memo, source_type, source_id, posted, created_by)
  values (t.portfolio_id, t.transfer_date, 'Bank transfer — ' || f.name || ' → ' || d.name, t.reference_number, t.memo,
          'bank_transfer', t.id, false, auth.uid())
  returning id into v_entry;
  insert into public.journal_lines (entry_id, gl_account_id, association_id, debit_amount, credit_amount, memo, sort_order) values
    (v_entry, d.gl_account_id, coalesce(d.association_id, v_assoc), t.amount, 0, t.memo, 0),
    (v_entry, f.gl_account_id, coalesce(f.association_id, v_assoc), 0, t.amount, t.memo, 1);
  update public.journal_entries set posted = true, posted_at = now() where id = v_entry;
  update public.bank_transfers set journal_entry_id = v_entry, updated_at = now() where id = t.id;
  return v_entry;
end $$;


ALTER FUNCTION "public"."complete_bank_transfer"("p_transfer_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_email_delivery"("p_email_id" "uuid", "p_provider_message_id" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_message_id uuid;
begin
  if auth.role() <> 'service_role' then raise exception 'Service role required'; end if;
  update public.email_queue
  set status = 'sent', sent_at = now(), processing_at = null,
      provider_message_id = nullif(left(trim(p_provider_message_id), 500), ''), error_message = null
  where id = p_email_id and status = 'pending' and processing_at is not null
  returning communication_message_id into v_message_id;
  if not found then return false; end if;

  if v_message_id is not null and not exists (
    select 1 from public.email_queue
    where communication_message_id = v_message_id and status <> 'sent' and suppressed_at is null
  ) then
    update public.communication_messages
    set status = 'sent', sent_at = now(), error_message = null, updated_at = now()
    where id = v_message_id;
  end if;
  return true;
end;
$$;


ALTER FUNCTION "public"."complete_email_delivery"("p_email_id" "uuid", "p_provider_message_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_maintenance_task"("p_task_id" "uuid", "p_seen_completed_at" timestamp with time zone, "p_seen_due" "date", "p_next_due" "date", "p_notes" "text", "p_event_type" "text", "p_next_start" timestamp with time zone, "p_next_end" timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  t public.maintenance_tasks;
  v_now timestamptz := now();
  v_portfolio uuid;
begin
  if p_next_due is not null and (p_seen_due is null or p_next_start is null) then
    raise exception 'A recurring task needs the due date that was shown and the next start time' using errcode = '22023';
  end if;

  update public.maintenance_tasks
     set last_completed_at = v_now,
         next_due_date = coalesce(p_next_due, next_due_date),
         status = case when p_next_due is not null then 'active' else 'completed' end
   where id = p_task_id
     and archived_at is null
     and last_completed_at is not distinct from p_seen_completed_at
     and (
       (p_next_due is not null and next_due_date = p_seen_due)
       or (p_next_due is null and status is distinct from 'completed')
     )
  returning * into t;
  if not found then
    raise exception 'The task was already completed since this page loaded, or you cannot edit it' using errcode = 'P0002';
  end if;

  insert into public.maintenance_task_history (task_id, completed_at, completed_by, notes, vendor_id, next_due_date)
  values (p_task_id, v_now, auth.uid(), p_notes, t.vendor_id, p_next_due);

  update public.calendar_events
     set operations_status = 'completed'
   where maintenance_task_id = p_task_id
     and archived_at is null
     and operations_status = 'scheduled';

  if p_next_due is not null then
    select a.portfolio_id into v_portfolio from public.associations a where a.id = t.association_id;
    if v_portfolio is null then
      raise exception 'The task''s association is unavailable' using errcode = 'P0002';
    end if;
    insert into public.calendar_events (
      portfolio_id, association_id, vendor_id, maintenance_task_id, title, event_type,
      calendar_scope, start_datetime, end_datetime, location, description, internal_notes,
      operations_status, notification_recipients, reminder_rules, created_by
    ) values (
      v_portfolio, t.association_id, t.vendor_id, p_task_id,
      left(chr(128295) || ' ' || t.task_name, 200),
      coalesce(nullif(p_event_type, ''), 'custom_event')::public.event_type,
      'daily'::public.calendar_scope, p_next_start, p_next_end, null, null,
      left(nullif(btrim(coalesce(p_notes, '')), ''), 200),
      'scheduled', '["management_office"]'::jsonb,
      '[{"minutes_before": 10080, "actions": ["notify_management_office"]}]'::jsonb,
      auth.uid()
    );
  end if;
end;
$$;


ALTER FUNCTION "public"."complete_maintenance_task"("p_task_id" "uuid", "p_seen_completed_at" timestamp with time zone, "p_seen_due" "date", "p_next_due" "date", "p_notes" "text", "p_event_type" "text", "p_next_start" timestamp with time zone, "p_next_end" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_physical_mail"("p_id" "uuid", "p_provider_piece_id" "text", "p_provider_url" "text", "p_expected_delivery_date" "date") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if coalesce(auth.role(), '') <> 'service_role' then raise exception 'Service role required'; end if;
  update public.physical_mail_deliveries
  set status = 'submitted', provider = 'lob', provider_piece_id = left(p_provider_piece_id, 200),
      provider_url = left(p_provider_url, 1000), expected_delivery_date = p_expected_delivery_date,
      submitted_at = now(), last_status_at = now(), locked_at = null, error_message = null
  where id = p_id;
end;
$$;


ALTER FUNCTION "public"."complete_physical_mail"("p_id" "uuid", "p_provider_piece_id" "text", "p_provider_url" "text", "p_expected_delivery_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_sms_delivery"("p_message_id" "uuid", "p_provider_message_id" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if coalesce(auth.role(), '') <> 'service_role' then raise exception 'Service role required'; end if;
  update public.sms_messages
  set status = 'sent', provider = 'twilio', provider_message_id = left(p_provider_message_id, 200),
      sent_at = now(), locked_at = null, error_code = null, error_message = null
  where id = p_message_id and direction = 'outbound';
end;
$$;


ALTER FUNCTION "public"."complete_sms_delivery"("p_message_id" "uuid", "p_provider_message_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."consume_api_rate_limit"("p_scope" "text", "p_key_hash" "text", "p_window_seconds" integer, "p_max_requests" integer) RETURNS TABLE("allowed" boolean, "remaining" integer, "reset_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  v_window_start timestamptz;
  v_count integer;
begin
  if p_scope !~ '^[a-z0-9:_-]{1,80}$'
     or p_key_hash !~ '^[a-f0-9]{64}$'
     or p_window_seconds not between 1 and 86400
     or p_max_requests not between 1 and 10000 then
    raise exception 'Invalid rate-limit parameters';
  end if;

  v_window_start := to_timestamp(
    floor(extract(epoch from clock_timestamp()) / p_window_seconds) * p_window_seconds
  );

  insert into public.api_rate_limits(scope, key_hash, window_start, request_count)
  values (p_scope, p_key_hash, v_window_start, 1)
  on conflict (scope, key_hash, window_start)
  do update set request_count = api_rate_limits.request_count + 1
  returning request_count into v_count;

  allowed := v_count <= p_max_requests;
  remaining := greatest(0, p_max_requests - v_count);
  reset_at := v_window_start + make_interval(secs => p_window_seconds);
  return next;
end;
$_$;


ALTER FUNCTION "public"."consume_api_rate_limit"("p_scope" "text", "p_key_hash" "text", "p_window_seconds" integer, "p_max_requests" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."convert_violation_report"("p_case_id" "uuid", "p_unit_id" "uuid", "p_house_rule_id" "uuid", "p_title" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  c public.violation_cases;
  v_id uuid;
  v_observed date;
begin
  select * into c from public.violation_cases where id = p_case_id for update;
  if c.id is null or c.archived_at is not null then
    raise exception 'Report not found';
  end if;
  if not public.can_manage_violations(c.association_id) then
    raise exception 'Permission denied' using errcode = '42501';
  end if;
  if c.status <> 'reported' then
    raise exception 'This report was already %', c.status using errcode = '22023';
  end if;
  v_observed := least(coalesce(c.reported_at::date, current_date), current_date);

  v_id := public.open_violation(
    c.association_id, p_unit_id, p_house_rule_id,
    coalesce(nullif(btrim(coalesce(p_title, '')), ''), initcap(replace(coalesce(c.violation_type, 'other'), '_', ' ')) || ' reported by a resident'),
    c.violation_description, v_observed, public.violation_report_type(c.violation_type));

  perform public.log_violation_event(v_id,
    left('Opened from a resident report received ' || to_char(coalesce(c.reported_at, now()), 'Mon DD, YYYY')
      || ' — reported by ' || coalesce(c.reporter_name, 'unknown')
      || coalesce(' (unit ' || c.reporter_unit || ')', '')
      || coalesce('; contact ' || c.reporter_contact, '')
      || coalesce('; when: ' || c.dates_times, '')
      || coalesce('; witnesses: ' || c.witnesses, '')
      || '; requested: ' || coalesce(c.requested_action, 'warning'), 2000),
    'open', false);

  update public.violation_cases
     set status = 'converted', violation_id = v_id, reviewed_by = auth.uid(), reviewed_at = now(), updated_at = now()
   where id = c.id;
  return v_id;
end $$;


ALTER FUNCTION "public"."convert_violation_report"("p_case_id" "uuid", "p_unit_id" "uuid", "p_house_rule_id" "uuid", "p_title" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."copy_house_rules"("p_source_association_id" "uuid", "p_target_association_ids" "uuid"[], "p_include_schedules" boolean) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_target uuid; v_rule public.house_rules; v_new_rule uuid; n integer := 0;
begin
  if not public.can_manage_violations(p_source_association_id) then raise exception 'Permission denied' using errcode = '42501'; end if;
  if coalesce(cardinality(p_target_association_ids), 0) = 0 then raise exception 'Choose at least one association' using errcode = '22023'; end if;
  if cardinality(p_target_association_ids) > 200 then raise exception 'Copy to at most 200 associations at once' using errcode = '22023'; end if;
  foreach v_target in array p_target_association_ids loop
    if v_target = p_source_association_id then continue; end if;
    if not public.can_manage_violations(v_target) then raise exception 'Permission denied for a target association' using errcode = '42501'; end if;
    if (select portfolio_id from public.associations where id = v_target) is distinct from (select portfolio_id from public.associations where id = p_source_association_id) then
      raise exception 'Rules can only be copied within one portfolio' using errcode = '42501';
    end if;
    for v_rule in select * from public.house_rules where association_id = p_source_association_id and archived_at is null order by sort_order loop
      if exists (select 1 from public.house_rules hr where hr.association_id = v_target and lower(hr.rule_number) = lower(v_rule.rule_number) and hr.archived_at is null) then
        continue;
      end if;
      insert into public.house_rules (association_id, rule_number, title, description, action_to_resolve, category, default_violation_type, penalty_type, fine_amount, active, sort_order, custom_schedule)
      values (v_target, v_rule.rule_number, v_rule.title, v_rule.description, v_rule.action_to_resolve, v_rule.category, v_rule.default_violation_type, v_rule.penalty_type, v_rule.fine_amount, v_rule.active, v_rule.sort_order,
              coalesce(p_include_schedules, false) and v_rule.custom_schedule)
      returning id into v_new_rule;
      n := n + 1;
      if coalesce(p_include_schedules, false) and v_rule.custom_schedule then
        insert into public.violation_followup_steps (association_id, house_rule_id, step_order, days_after_previous, follow_up_name, delivery_methods, fee, offers_hearing)
        select v_target, v_new_rule, s.step_order, s.days_after_previous, s.follow_up_name, s.delivery_methods, s.fee, s.offers_hearing
          from public.violation_followup_steps s where s.house_rule_id = v_rule.id and s.archived_at is null;
      end if;
    end loop;
    if coalesce(p_include_schedules, false) and not exists (select 1 from public.violation_followup_steps where association_id = v_target and house_rule_id is null and archived_at is null) then
      insert into public.violation_followup_steps (association_id, step_order, days_after_previous, follow_up_name, delivery_methods, fee, offers_hearing)
      select v_target, s.step_order, s.days_after_previous, s.follow_up_name, s.delivery_methods, s.fee, s.offers_hearing
        from public.violation_followup_steps s where s.association_id = p_source_association_id and s.house_rule_id is null and s.archived_at is null;
    end if;
  end loop;
  return n;
end;
$$;


ALTER FUNCTION "public"."copy_house_rules"("p_source_association_id" "uuid", "p_target_association_ids" "uuid"[], "p_include_schedules" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."corporate_receivable_bills"("p_portfolio_id" "uuid") RETURNS TABLE("bill_id" "uuid", "association_id" "uuid", "association" "text", "bill_number" "text", "bill_date" "date", "due_date" "date", "memo" "text", "amount" numeric, "paid_on" "date")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select pb.id, pb.association_id, a.name, pb.bill_number, pb.bill_date, pb.due_date, pb.memo,
         round(pb.amount - coalesce(pb.credit_applied, 0), 2),
         case when pb.status = 'paid' then coalesce(pb.paid_at::date, pb.bill_date) end
    from public.payable_bills pb
    join public.portfolios p on p.id = pb.portfolio_id and p.management_fee_vendor_id = pb.vendor_id
    join public.associations a on a.id = pb.association_id
   where pb.portfolio_id = p_portfolio_id and pb.archived_at is null and pb.status::text <> 'void';
$$;


ALTER FUNCTION "public"."corporate_receivable_bills"("p_portfolio_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_api_key"("p_portfolio_id" "uuid", "p_name" "text", "p_scopes" "text"[] DEFAULT '{}'::"text"[], "p_expires_days" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public', 'extensions'
    AS $$
declare
  raw_key text;
  key_prefix text;
  k_hash text;
  new_id uuid;
begin
  -- Generates a 48-char hex key prefixed with cak_ (Condo App Key)
  raw_key := 'cak_' || replace(gen_random_uuid()::text, '-', '') || replace(gen_random_uuid()::text, '-', '');
  key_prefix := substring(raw_key from 1 for 12);
  k_hash := encode(extensions.digest(raw_key, 'sha256'), 'hex');

  insert into public.api_keys (
    portfolio_id, name, prefix, key_hash, scopes, created_by, expires_at
  ) values (
    p_portfolio_id, p_name, key_prefix, k_hash, coalesce(p_scopes, '{}'),
    auth.uid(),
    case when p_expires_days is not null then now() + make_interval(days => p_expires_days) end
  ) returning id into new_id;

  return jsonb_build_object(
    'id', new_id,
    'api_key', raw_key,
    'prefix', key_prefix,
    'warning', 'Store this key securely — it will not be shown again.'
  );
end;
$$;


ALTER FUNCTION "public"."create_api_key"("p_portfolio_id" "uuid", "p_name" "text", "p_scopes" "text"[], "p_expires_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_bank_deposit"("p_bank_account_id" "uuid", "p_deposit_date" "date", "p_payment_ids" "uuid"[], "p_other_receipt_ids" "uuid"[], "p_memo" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_bank public.bank_accounts;
  v_id uuid;
  v_total numeric := 0;
  v_count integer := 0;
  v_n integer;
  v_sum numeric;
begin
  select * into v_bank from public.bank_accounts where id = p_bank_account_id and archived_at is null;
  if not found or not public.can_manage_finance(v_bank.portfolio_id)
     or (v_bank.association_id is not null and not public.can_view_association_row(v_bank.association_id)) then
    raise exception 'Bank account not found' using errcode = 'P0002';
  end if;
  if p_deposit_date is null then raise exception 'Choose the deposit date' using errcode = '22023'; end if;
  if coalesce(cardinality(p_payment_ids), 0) + coalesce(cardinality(p_other_receipt_ids), 0) = 0 then
    raise exception 'Select at least one receipt' using errcode = '22023';
  end if;

  insert into public.bank_deposits (portfolio_id, association_id, bank_account_id, deposit_date, amount, receipt_count, memo, created_by)
  values (v_bank.portfolio_id, v_bank.association_id, v_bank.id, p_deposit_date, 0.01, 0, nullif(btrim(coalesce(p_memo, '')), ''), auth.uid())
  returning id into v_id;

  if coalesce(cardinality(p_payment_ids), 0) > 0 then
    with picked as (
      update public.payments p set bank_deposit_id = v_id
       where p.id = any (p_payment_ids) and p.bank_account_id = v_bank.id and p.bank_deposit_id is null
         and p.reversed_at is null and p.payment_date <= p_deposit_date
      returning p.amount)
    select count(*), coalesce(sum(amount), 0) into v_n, v_sum from picked;
    if v_n <> (select count(distinct x) from unnest(p_payment_ids) x) then
      raise exception 'A selected receipt is already deposited, reversed, dated after the deposit, or went to another bank account' using errcode = '22023';
    end if;
    v_count := v_count + v_n; v_total := v_total + v_sum;
  end if;

  if coalesce(cardinality(p_other_receipt_ids), 0) > 0 then
    with picked as (
      update public.other_receipts r set bank_deposit_id = v_id
       where r.id = any (p_other_receipt_ids) and r.bank_account_id = v_bank.id and r.bank_deposit_id is null
         and r.voided_at is null and r.receipt_date <= p_deposit_date
      returning r.amount)
    select count(*), coalesce(sum(amount), 0) into v_n, v_sum from picked;
    if v_n <> (select count(distinct x) from unnest(p_other_receipt_ids) x) then
      raise exception 'A selected receipt is already deposited, voided, dated after the deposit, or went to another bank account' using errcode = '22023';
    end if;
    v_count := v_count + v_n; v_total := v_total + v_sum;
  end if;

  if v_total <= 0 then raise exception 'The deposit total must be greater than zero' using errcode = '22023'; end if;
  update public.bank_deposits set amount = round(v_total, 2), receipt_count = v_count where id = v_id;
  insert into public.audit_logs (portfolio_id, entity_type, entity_id, action, actor_id, changes)
  values (v_bank.portfolio_id, 'bank_deposit', v_id, 'created', auth.uid(), jsonb_build_object('amount', round(v_total, 2), 'receipts', v_count));
  return v_id;
end $$;


ALTER FUNCTION "public"."create_bank_deposit"("p_bank_account_id" "uuid", "p_deposit_date" "date", "p_payment_ids" "uuid"[], "p_other_receipt_ids" "uuid"[], "p_memo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_inspections_from_template"("p_template_id" "uuid", "p_association_id" "uuid", "p_unit_ids" "uuid"[], "p_all_units" boolean, "p_scheduled_date" "date", "p_inspection_type" "text", "p_notes" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  t public.inspection_templates;
  v_pid uuid;
  v_units uuid[];
  v_unit uuid;
  v_insp uuid;
  n integer := 0;
begin
  select a.portfolio_id into v_pid from public.associations a where a.id = p_association_id and a.archived_at is null;
  if v_pid is null or not public.can_manage_association(p_association_id) then
    raise exception 'Choose an association you manage' using errcode = '42501';
  end if;
  select * into t from public.inspection_templates where id = p_template_id and portfolio_id = v_pid and archived_at is null;
  if not found then raise exception 'Template not found' using errcode = 'P0002'; end if;
  if p_scheduled_date is null then raise exception 'Choose the date to schedule the inspections for' using errcode = '22023'; end if;

  if coalesce(p_all_units, false) then
    select array_agg(u.id order by u.unit_number) into v_units
      from public.units u join public.buildings b on b.id = u.building_id
     where b.association_id = p_association_id and u.archived_at is null;
    if v_units is null then raise exception 'This association has no units' using errcode = '22023'; end if;
  elsif p_unit_ids is not null and cardinality(p_unit_ids) > 0 then
    if exists (select 1 from unnest(p_unit_ids) x(id)
                where not exists (select 1 from public.units u join public.buildings b on b.id = u.building_id
                                   where u.id = x.id and b.association_id = p_association_id and u.archived_at is null)) then
      raise exception 'A unit is not in this association' using errcode = '22023';
    end if;
    v_units := (select array_agg(distinct x) from unnest(p_unit_ids) x);
  else
    v_units := array[null::uuid];
  end if;
  if cardinality(v_units) > 2000 then raise exception 'At most 2,000 inspections at a time' using errcode = '22023'; end if;

  foreach v_unit in array v_units loop
    insert into public.inspections (portfolio_id, association_id, unit_id, inspection_type, scheduled_date, status, notes, created_by, template_id)
    values (v_pid, p_association_id, v_unit, coalesce(nullif(btrim(coalesce(p_inspection_type, '')), ''), t.inspection_type, t.name),
            p_scheduled_date, 'scheduled', nullif(btrim(coalesce(p_notes, '')), ''), auth.uid(), t.id)
    returning id into v_insp;
    insert into public.inspection_checklist_items (inspection_id, area, item, sort_order)
    select v_insp, e ->> 'area', e ->> 'item', o::integer
      from jsonb_array_elements(t.items) with ordinality as x(e, o);
    n := n + 1;
  end loop;
  return n;
end $$;


ALTER FUNCTION "public"."create_inspections_from_template"("p_template_id" "uuid", "p_association_id" "uuid", "p_unit_ids" "uuid"[], "p_all_units" boolean, "p_scheduled_date" "date", "p_inspection_type" "text", "p_notes" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."user_invitations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "portfolio_id" "uuid" NOT NULL,
    "email" "text" NOT NULL,
    "hoa_role" "public"."hoa_role" DEFAULT 'manager'::"public"."hoa_role" NOT NULL,
    "role_id" "uuid",
    "token" "text" DEFAULT ("replace"(("gen_random_uuid"())::"text", '-'::"text", ''::"text") || "replace"(("gen_random_uuid"())::"text", '-'::"text", ''::"text")) NOT NULL,
    "status" "public"."invitation_status" DEFAULT 'pending'::"public"."invitation_status" NOT NULL,
    "expires_at" timestamp with time zone DEFAULT ("now"() + '14 days'::interval) NOT NULL,
    "used_at" timestamp with time zone,
    "used_by" "uuid",
    "invited_by" "uuid",
    "message" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "mvp_role" "public"."mvp_company_role",
    "unit_id" "uuid",
    "association_ids" "uuid"[] DEFAULT '{}'::"uuid"[] NOT NULL,
    "full_name" "text",
    "role" "text",
    "association_id" "uuid",
    "accepted_at" timestamp with time zone,
    "created_by" "text",
    "metadata" "jsonb" DEFAULT '{}'::"jsonb",
    CONSTRAINT "user_invitations_email_check" CHECK ((("length"("email") >= 3) AND ("length"("email") <= 320))),
    CONSTRAINT "user_invitations_token_format" CHECK (("token" ~ '^[0-9a-f]{64}$'::"text"))
);


ALTER TABLE "public"."user_invitations" OWNER TO "postgres";


COMMENT ON TABLE "public"."user_invitations" IS 'Tokenized email invites. Portfolio admins create invitations; recipients accept via token RPC → auto-links profile to portfolio + role.';



COMMENT ON COLUMN "public"."user_invitations"."mvp_role" IS 'Role to assign on accept: company_admin / manager / assistant_manager / accountant. NULL when invitation is for board/owner/tenant (those use hoa_role + unit_id / board_members links instead).';



COMMENT ON COLUMN "public"."user_invitations"."association_ids" IS 'For manager/assistant_manager invitations: associations they will be assigned to on accept. Empty for company_admin/accountant (full company access) or non-staff invites.';



CREATE OR REPLACE FUNCTION "public"."create_invitation"("p_portfolio_id" "uuid", "p_email" "text", "p_hoa_role" "public"."hoa_role" DEFAULT 'manager'::"public"."hoa_role", "p_role_id" "uuid" DEFAULT NULL::"uuid", "p_message" "text" DEFAULT NULL::"text", "p_expires_days" integer DEFAULT 14) RETURNS "public"."user_invitations"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  inv public.user_invitations;
begin
  insert into public.user_invitations (
    portfolio_id, email, hoa_role, role_id, message, invited_by, expires_at
  ) values (
    p_portfolio_id, lower(p_email), p_hoa_role, p_role_id, p_message, auth.uid(),
    now() + make_interval(days => p_expires_days)
  )
  returning * into inv;
  return inv;
end;
$$;


ALTER FUNCTION "public"."create_invitation"("p_portfolio_id" "uuid", "p_email" "text", "p_hoa_role" "public"."hoa_role", "p_role_id" "uuid", "p_message" "text", "p_expires_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_manager_invitation"("p_email" "text", "p_association_ids" "uuid"[] DEFAULT ARRAY[]::"uuid"[], "p_message" "text" DEFAULT NULL::"text", "p_expires_days" integer DEFAULT 14) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  v_actor_id uuid := auth.uid();
  v_portfolio_id uuid;
  v_role_id uuid;
  v_email text := lower(trim(coalesce(p_email, '')));
  v_association_ids uuid[];
  v_invitation public.user_invitations;
begin
  if v_email = '' or v_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then
    raise exception 'Enter a valid manager email address';
  end if;

  if p_expires_days < 1 or p_expires_days > 30 then
    raise exception 'Invitation expiry must be between 1 and 30 days';
  end if;

  select p.portfolio_id
  into v_portfolio_id
  from public.profiles p
  where p.id = v_actor_id
    and p.hoa_role = 'company_admin'
    and p.disabled_at is null;

  if v_portfolio_id is null then
    raise exception 'Active company administrator access is required';
  end if;

  select coalesce(array_agg(distinct requested.association_id), array[]::uuid[])
  into v_association_ids
  from unnest(coalesce(p_association_ids, array[]::uuid[])) requested(association_id);

  if exists (
    select 1
    from unnest(v_association_ids) requested(association_id)
    left join public.associations association
      on association.id = requested.association_id
     and association.portfolio_id = v_portfolio_id
     and association.archived_at is null
    where association.id is null
  ) then
    raise exception 'One or more associations are outside your portfolio';
  end if;

  if exists (
    select 1
    from public.user_invitations invitation
    where invitation.portfolio_id = v_portfolio_id
      and lower(invitation.email) = v_email
      and invitation.hoa_role = 'manager'
      and invitation.status = 'pending'
      and invitation.expires_at > now()
  ) then
    raise exception 'A pending manager invitation already exists for this email';
  end if;

  select role.id
  into v_role_id
  from public.user_roles role
  where role.name = 'Property Manager'
    and (role.portfolio_id = v_portfolio_id or (role.is_system and role.portfolio_id is null))
  order by (role.portfolio_id = v_portfolio_id) desc nulls last
  limit 1;

  if v_role_id is null then
    raise exception 'The Property Manager role is not configured';
  end if;

  insert into public.user_invitations (
    portfolio_id,
    email,
    hoa_role,
    role_id,
    invited_by,
    message,
    expires_at,
    association_ids,
    metadata
  ) values (
    v_portfolio_id,
    v_email,
    'manager',
    v_role_id,
    v_actor_id,
    p_message,
    now() + make_interval(days => p_expires_days),
    v_association_ids,
    jsonb_build_object('email_delivery', 'application')
  )
  returning * into v_invitation;

  return jsonb_build_object(
    'invitation_id', v_invitation.id,
    'token', v_invitation.token,
    'expires_at', v_invitation.expires_at,
    'association_ids', to_jsonb(v_association_ids)
  );
end;
$_$;


ALTER FUNCTION "public"."create_manager_invitation"("p_email" "text", "p_association_ids" "uuid"[], "p_message" "text", "p_expires_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_owner_payable"("p_association_id" "uuid", "p_owner_id" "uuid", "p_gl_account_id" "uuid", "p_bank_account_id" "uuid", "p_payable_type" "text", "p_payable_date" "date", "p_due_date" "date", "p_amount" numeric, "p_memo" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_pid uuid := public.current_portfolio_id();
  v_id uuid;
begin
  if v_pid is null or not public.can_manage_finance(v_pid) then
    raise exception 'Permission denied' using errcode = '42501';
  end if;
  if p_association_id is null or not exists (select 1 from public.associations a where a.id = p_association_id and a.portfolio_id = v_pid)
     or not public.can_manage_association(p_association_id) then
    raise exception 'Choose an association' using errcode = '22023';
  end if;
  if not exists (select 1 from public.owners o
                   join public.unit_owners uo on uo.owner_id = o.id
                   join public.units u on u.id = uo.unit_id
                   join public.buildings b on b.id = u.building_id
                  where o.id = p_owner_id and o.portfolio_id = v_pid and b.association_id = p_association_id) then
    raise exception 'Choose a homeowner of this association' using errcode = '22023';
  end if;
  if p_amount is null or p_amount <= 0 then raise exception 'Amount must be greater than zero' using errcode = '22023'; end if;
  if p_payable_type not in ('refund', 'settlement', 'distribution', 'other') then
    raise exception 'Choose a payable type' using errcode = '22023';
  end if;
  if p_gl_account_id is not null and not exists (select 1 from public.gl_accounts g where g.id = p_gl_account_id and g.portfolio_id = v_pid
             and g.active and (g.association_id is null or g.association_id = p_association_id)) then
    raise exception 'GL account does not belong to this association' using errcode = '22023';
  end if;
  if p_bank_account_id is not null and not exists (select 1 from public.bank_accounts b where b.id = p_bank_account_id and b.portfolio_id = v_pid
             and b.archived_at is null and (b.association_id is null or b.association_id = p_association_id)) then
    raise exception 'Bank account does not belong to this association' using errcode = '22023';
  end if;

  insert into public.owner_payables (portfolio_id, association_id, owner_id, gl_account_id, bank_account_id,
    payable_type, payable_date, due_date, amount, memo, status, created_by)
  values (v_pid, p_association_id, p_owner_id, p_gl_account_id, p_bank_account_id,
    p_payable_type::public.owner_payable_type, coalesce(p_payable_date, current_date), p_due_date, round(p_amount, 2),
    nullif(btrim(coalesce(p_memo, '')), ''), 'pending_approval', auth.uid())
  returning id into v_id;
  insert into public.audit_logs (portfolio_id, entity_type, entity_id, action, actor_id, changes)
  values (v_pid, 'owner_payable', v_id, 'created', auth.uid(), jsonb_build_object('amount', round(p_amount, 2), 'type', p_payable_type));
  return v_id;
end $$;


ALTER FUNCTION "public"."create_owner_payable"("p_association_id" "uuid", "p_owner_id" "uuid", "p_gl_account_id" "uuid", "p_bank_account_id" "uuid", "p_payable_type" "text", "p_payable_date" "date", "p_due_date" "date", "p_amount" numeric, "p_memo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_payable_bill"("p_portfolio_id" "uuid", "p_vendor_id" "uuid", "p_association_id" "uuid", "p_gl_account_id" "uuid", "p_bank_account_id" "uuid", "p_bill_number" "text", "p_bill_date" "date", "p_due_date" "date", "p_amount" numeric, "p_memo" "text", "p_submit_for_approval" boolean, "p_board_approval" boolean) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  bill_id uuid;
  board_mode text := 'never';
  board_threshold numeric;
  requires_board boolean;
begin
  if p_portfolio_id is null or not public.can_manage_finance(p_portfolio_id) then raise exception 'Permission denied'; end if;
  if not public.can_view_association_row(p_association_id) then raise exception 'Permission denied'; end if;
  if p_vendor_id is null or p_bill_date is null or p_amount is null or p_amount <= 0 then
    raise exception 'Vendor, bill date, and a positive amount are required';
  end if;
  -- One bill per vendor invoice number (same lock as import_bills and
  -- submit_vendor_invoice), so the same invoice can't be paid twice.
  if nullif(btrim(coalesce(p_bill_number, '')), '') is not null then
    perform pg_advisory_xact_lock(hashtextextended(p_vendor_id::text || ':' || lower(btrim(p_bill_number)), 0));
    if exists (
      select 1 from public.payable_bills pb
       where pb.vendor_id = p_vendor_id
         and pb.archived_at is null
         and pb.status <> 'void'::public.payable_bill_status
         and lower(btrim(pb.bill_number)) = lower(btrim(p_bill_number))
    ) then
      raise exception 'Invoice number % already exists for this vendor', btrim(p_bill_number) using errcode = '23505';
    end if;
  end if;
  if p_association_id is not null then
    select coalesce(s.sends_bills_to_board, 'never'), s.bills_threshold
      into board_mode, board_threshold
      from public.board_approval_settings s
     where s.association_id = p_association_id;
  end if;
  requires_board := coalesce(coalesce(p_board_approval, false)
    or coalesce(board_mode, 'never') = 'always'
    or (board_mode = 'over_threshold' and p_amount >= coalesce(board_threshold, 0)), false);
  if requires_board and p_association_id is null then
    raise exception 'Board-approved bills require an association';
  end if;

  insert into public.payable_bills (
    portfolio_id, vendor_id, association_id, gl_account_id, bank_account_id,
    bill_number, bill_date, due_date, amount, memo, status,
    approval_required, created_by
  ) values (
    p_portfolio_id, p_vendor_id, p_association_id, p_gl_account_id, p_bank_account_id,
    nullif(trim(coalesce(p_bill_number, '')), ''), p_bill_date, p_due_date, p_amount,
    nullif(trim(coalesce(p_memo, '')), ''), 'draft'::public.payable_bill_status,
    requires_board, auth.uid()
  ) returning id into bill_id;

  if coalesce(p_submit_for_approval, false) then
    perform public.request_payable_bill_approval(bill_id);
  end if;
  return bill_id;
end;
$$;


ALTER FUNCTION "public"."create_payable_bill"("p_portfolio_id" "uuid", "p_vendor_id" "uuid", "p_association_id" "uuid", "p_gl_account_id" "uuid", "p_bank_account_id" "uuid", "p_bill_number" "text", "p_bill_date" "date", "p_due_date" "date", "p_amount" numeric, "p_memo" "text", "p_submit_for_approval" boolean, "p_board_approval" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_payment_plan"("p_unit_id" "uuid", "p_total" numeric, "p_installments" integer, "p_frequency" "text", "p_first_due" "date", "p_notes" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_assoc uuid;
  v_pid uuid;
  v_owner uuid;
  v_plan uuid;
  v_each numeric;
  v_case record;
  i integer;
begin
  select b.association_id, a.portfolio_id into v_assoc, v_pid
    from public.units u join public.buildings b on b.id = u.building_id join public.associations a on a.id = b.association_id
   where u.id = p_unit_id;
  if v_assoc is null or not public.can_manage_association(v_assoc) or not public.is_any_staff() then
    raise exception 'You do not manage this unit' using errcode = '42501';
  end if;
  if p_total is null or round(p_total, 2) <= 0 then
    raise exception 'Enter the amount the plan covers' using errcode = '22023';
  end if;
  if p_installments is null or p_installments not between 1 and 60 then
    raise exception 'Choose between 1 and 60 installments' using errcode = '22023';
  end if;
  if round(p_total, 2) < p_installments * 0.01 then
    raise exception 'Each installment must be at least one cent — use fewer installments' using errcode = '22023';
  end if;
  if coalesce(p_frequency, '') not in ('weekly', 'biweekly', 'monthly') then
    raise exception 'Choose weekly, every two weeks or monthly' using errcode = '22023';
  end if;
  if p_first_due is null or p_first_due < public.association_local_date(v_assoc) - 31 or p_first_due > public.association_local_date(v_assoc) + 366 then
    raise exception 'Choose a first due date within the next year' using errcode = '22023';
  end if;
  if exists (select 1 from public.delinquency_cases where unit_id = p_unit_id and status in ('legal_review', 'approved_for_counsel')) then
    raise exception 'This unit''s collection case is in legal review — resolve it before agreeing a payment plan' using errcode = '22023';
  end if;
  if exists (select 1 from public.payment_plans where unit_id = p_unit_id and status = 'active') then
    raise exception 'This unit already has an active payment plan' using errcode = '23505';
  end if;

  select oc.owner_id into v_owner from public.occupancies oc
   where oc.unit_id = p_unit_id and oc.status = 'current' order by oc.is_primary desc nulls last, oc.created_at limit 1;

  insert into public.payment_plans (portfolio_id, association_id, unit_id, owner_id, total_amount, installment_count,
                                    frequency, first_due_date, notes, created_by, start_date)
  values (v_pid, v_assoc, p_unit_id, v_owner, round(p_total, 2), p_installments, p_frequency, p_first_due,
          nullif(btrim(coalesce(p_notes, '')), ''), auth.uid(), public.association_local_date(v_assoc))
  returning id into v_plan;

  v_each := trunc(round(p_total, 2) / p_installments, 2);
  for i in 1..p_installments loop
    insert into public.payment_plan_installments (plan_id, installment_number, due_date, amount)
    values (v_plan, i,
            case p_frequency
              when 'monthly' then (p_first_due + make_interval(months => i - 1))::date
              when 'biweekly' then p_first_due + (i - 1) * 14
              else p_first_due + (i - 1) * 7 end,
            case when i = p_installments then round(p_total, 2) - v_each * (p_installments - 1) else v_each end);
  end loop;

  for v_case in select id from public.delinquency_cases where unit_id = p_unit_id and status = 'open' loop
    perform public.set_delinquency_case_hold(v_case.id, true, 'Payment plan agreed — collections paused while the plan is current');
  end loop;

  insert into public.audit_logs (portfolio_id, entity_type, entity_id, action, actor_id, actor_email, changes)
  values (v_pid, 'payment_plan', v_plan, 'payment_plan_created', auth.uid(), (select email from auth.users where id = auth.uid()),
          jsonb_build_object('unit_id', p_unit_id, 'total', round(p_total, 2), 'installments', p_installments, 'frequency', p_frequency));
  return v_plan;
end $$;


ALTER FUNCTION "public"."create_payment_plan"("p_unit_id" "uuid", "p_total" numeric, "p_installments" integer, "p_frequency" "text", "p_first_due" "date", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_po_from_recurring"("p_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  r public.recurring_purchase_orders;
begin
  select * into r from public.recurring_purchase_orders where id = p_id and archived_at is null;
  if not found or not public.can_manage_finance(r.portfolio_id) or not public.can_manage_association(r.association_id) then
    raise exception 'Recurring purchase order not found' using errcode = '42501';
  end if;
  return public.app_po_from_recurring(p_id, null);
end $$;


ALTER FUNCTION "public"."create_po_from_recurring"("p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_signature_request"("p_portfolio_id" "uuid", "p_association_id" "uuid", "p_subject_type" "text", "p_subject_id" "uuid", "p_title" "text", "p_message" "text", "p_document_kind" "text", "p_document_path" "text", "p_body_text" "text", "p_document_sha256" "text", "p_signers" "jsonb", "p_expires_days" integer, "p_sequential" boolean) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_id uuid; s jsonb; n integer := 0; v_subject_portfolio uuid; v_subject_association uuid;
begin
  if not public.can_manage_signatures(p_portfolio_id) then raise exception 'Permission denied' using errcode = '42501'; end if;
  if p_association_id is not null and not exists (
    select 1 from public.associations a where a.id = p_association_id and a.portfolio_id = p_portfolio_id and a.archived_at is null
  ) then raise exception 'Association is outside your portfolio' using errcode = '42501'; end if;
  if p_association_id is not null and not public.can_view_association_row(p_association_id) then
    raise exception 'Permission denied for this association' using errcode = '42501';
  end if;
  if p_subject_id is not null then
    v_subject_portfolio := case p_subject_type
      when 'architectural_request' then (select portfolio_id from public.architectural_requests where id = p_subject_id)
      when 'management_agreement' then (select portfolio_id from public.management_agreements where id = p_subject_id)
      when 'year_end_package' then (select portfolio_id from public.year_end_packages where id = p_subject_id and status = 'finalized')
      else null end;
    if v_subject_portfolio is distinct from p_portfolio_id then
      raise exception 'Linked record is outside your portfolio' using errcode = '42501';
    end if;
    -- The linked record's association: the caller must see it (a manager
    -- assigned to some associations: only theirs) and the request is filed
    -- under it.
    v_subject_association := case p_subject_type
      when 'architectural_request' then (select association_id from public.architectural_requests where id = p_subject_id)
      when 'management_agreement' then (select association_id from public.management_agreements where id = p_subject_id)
      when 'year_end_package' then (select association_id from public.year_end_packages where id = p_subject_id)
      else null end;
    if v_subject_association is null then
      if coalesce(public.manager_is_scoped(), false) then
        raise exception 'Linked record is outside the associations you manage' using errcode = '42501';
      end if;
    else
      if not coalesce(public.can_view_association_row(v_subject_association), false) then
        raise exception 'Linked record is outside the associations you manage' using errcode = '42501';
      end if;
      if not exists (select 1 from public.associations a where a.id = v_subject_association and a.archived_at is null) then
        raise exception 'The linked record belongs to an archived association' using errcode = '22023';
      end if;
      if p_association_id is not null and p_association_id <> v_subject_association then
        raise exception 'The linked record belongs to another association' using errcode = '22023';
      end if;
    end if;
  end if;
  if p_signers is null or jsonb_typeof(p_signers) <> 'array' or jsonb_array_length(p_signers) not between 1 and 20 then
    raise exception 'Add between 1 and 20 signers' using errcode = '22023';
  end if;
  if coalesce(p_expires_days, 0) not between 1 and 90 then raise exception 'Expiry must be 1–90 days' using errcode = '22023'; end if;
  insert into public.signature_requests (
    portfolio_id, association_id, subject_type, subject_id, title, message, document_kind, document_path, body_text,
    document_sha256, sequential, expires_at, created_by
  ) values (
    -- signature_request_association: filed under the linked record's association.
    p_portfolio_id, coalesce(p_association_id, v_subject_association), coalesce(p_subject_type, 'document'), p_subject_id, btrim(p_title),
    nullif(btrim(coalesce(p_message, '')), ''), p_document_kind, p_document_path, p_body_text,
    lower(p_document_sha256), coalesce(p_sequential, false), now() + make_interval(days => p_expires_days), auth.uid()
  ) returning id into v_id;
  for s in select * from jsonb_array_elements(p_signers) loop
    n := n + 1;
    insert into public.signature_signers (request_id, sign_order, name, email, role_label, token_hash)
    values (v_id, n, btrim(s ->> 'name'), lower(btrim(s ->> 'email')), nullif(btrim(coalesce(s ->> 'role_label', '')), ''), lower(s ->> 'token_hash'));
  end loop;
  insert into public.signature_events (request_id, event_type, actor_id, detail)
  values (v_id, 'sent', auth.uid(), jsonb_build_object('signers', n, 'document_sha256', lower(p_document_sha256), 'sequential', coalesce(p_sequential, false)));
  if p_subject_type = 'year_end_package' and p_subject_id is not null then
    update public.year_end_packages set signature_request_id = v_id where id = p_subject_id and portfolio_id = p_portfolio_id;
  end if;
  return v_id;
end;
$$;


ALTER FUNCTION "public"."create_signature_request"("p_portfolio_id" "uuid", "p_association_id" "uuid", "p_subject_type" "text", "p_subject_id" "uuid", "p_title" "text", "p_message" "text", "p_document_kind" "text", "p_document_path" "text", "p_body_text" "text", "p_document_sha256" "text", "p_signers" "jsonb", "p_expires_days" integer, "p_sequential" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cron_assess_late_fees"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  a record;
  c record;
  v_fee uuid;
  v_assoc_count integer := 0;
  v_candidates integer := 0;
  v_assessed integer := 0;
  v_skipped integer := 0;
  v_failed integer := 0;
  v_autopay_held integer := 0;
  v_details text[] := '{}';
begin
  for a in
    -- Changed: table alias x (equivalent), for the suspension check below.
    select x.id, x.name, coalesce(x.late_fee_grace_days, 0) as grace, public.association_local_date(x.id) as today,
           -- Changed: whether the company's last suspension was lifted in the
           -- last 24 hours.
           coalesce((select pf.reactivated_at > now() - interval '24 hours'
                       from public.portfolios pf where pf.id = x.portfolio_id), false) as just_reactivated
      from public.associations x
     where x.late_fee_enabled and coalesce(x.late_fee_amount, 0) > 0 and x.archived_at is null
       -- Changed: no automatic late fees while the company is suspended (its
       -- owners can't sign in to pay and AutoPay is paused).
       and not exists (select 1 from public.portfolios pf
                        where pf.id = x.portfolio_id and pf.suspended_at is not null)
     order by x.name
  loop
    v_assoc_count := v_assoc_count + 1;
    for c in
      select ch.id, ch.unit_id
        from public.charges ch
        join public.units u on u.id = ch.unit_id
        join public.buildings b on b.id = u.building_id
       where b.association_id = a.id
         and ch.charge_type = 'assessment'
         and ch.due_date + a.grace < a.today
         and not exists (select 1 from public.late_fee_assessments l where l.charge_id = ch.id)
         and ch.amount - coalesce((select sum(pa.amount_applied) from public.payment_applications pa where pa.charge_id = ch.id), 0) > 0.005
       order by ch.due_date, ch.id
    loop
      -- Changed (Mirsad, 2026-10-14): late fees run at 11:10 UTC (here) and
      -- 15:00 UTC (Vercel), the held AutoPay charges at 14:00 UTC. For 24 hours
      -- after a reactivation (both runs that day), a unit whose AutoPay
      -- mandate is due gets no late fee yet. And in every company, a unit with
      -- money in flight gets none: a payment processing for under 14 days (ACH
      -- takes days) or an AutoPay payment pending for under a day. An unpaid
      -- portal checkout doesn't count, and the age bounds keep a stuck row
      -- from holding fees forever. A later run assesses what's unpaid.
      if (a.just_reactivated and exists (
            select 1 from public.autopay_mandates am
             where am.unit_id = c.unit_id
               and am.status = 'active'
               and am.canceled_at is null
               and (am.end_date is null or am.end_date >= a.today)
               and am.next_run_date <= a.today
               and (am.skip_until is null or am.skip_until < a.today)))
         or exists (
            select 1 from public.payment_intents pi
             where pi.unit_id = c.unit_id
               and pi.status in ('pending', 'processing')
               and ((pi.status = 'processing' and pi.created_at > now() - interval '14 days')
                    or (pi.status = 'pending' and pi.created_at > now() - interval '1 day'
                        -- AutoPay creates its payment_intents row with the run's id.
                        and exists (select 1 from public.stripe_autopay_runs r where r.id = pi.id)))) then
        v_autopay_held := v_autopay_held + 1;
        continue;
      end if;
      v_candidates := v_candidates + 1;
      begin
        v_fee := public.assess_late_fee(c.id);
        if v_fee is not null then v_assessed := v_assessed + 1; else v_skipped := v_skipped + 1; end if;
      exception when others then
        v_failed := v_failed + 1;
        if cardinality(v_details) < 50 then
          v_details := v_details || (a.name || ' charge ' || c.id || ': ' || sqlerrm);
        end if;
      end;
    end loop;
  end loop;

  return jsonb_build_object(
    'associations', v_assoc_count, 'candidates', v_candidates, 'assessed', v_assessed,
    'skipped', v_skipped, 'failed', v_failed, 'autopay_held', v_autopay_held,
    'details', to_jsonb(v_details));
end;
$$;


ALTER FUNCTION "public"."cron_assess_late_fees"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."csv_association_id"("p_pid" "uuid", "p_value" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$#variable_conflict use_column
begin
  return (select s.x from (

  select a.id from public.associations a
   where a.portfolio_id = p_pid and a.archived_at is null
     and (a.id::text = btrim(p_value) or lower(a.name) = lower(btrim(p_value)))
   order by (a.id::text = btrim(p_value)) desc limit 1
  ) s(x) limit 1);
end$$;


