    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$#variable_conflict use_column
begin
  return (select s.x from (

  select g.id from public.gl_accounts g
   where g.portfolio_id = p_pid and g.active
     and (g.association_id is null or g.association_id = p_assoc)
     and (g.id::text = btrim(p_value) or g.number::text = btrim(p_value))
