  if new.status = 'open'
     and exists (select 1 from public.payment_plans p where p.unit_id = new.unit_id and p.status = 'active') then
    new.status := 'on_hold';
    new.hold_reason := 'Payment plan agreed — collections paused while the plan is current';
  end if;
  return new;
end $$;


