CREATE OR REPLACE FUNCTION "public"."delinquency_referral_blockers"("p_case_id" "uuid") RETURNS "text"[]
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare c public.delinquency_cases; p public.delinquency_policies; blockers text[] := '{}'; v_notice_ok boolean; v_latest_board text;
begin
  select * into c from public.delinquency_cases where id = p_case_id;
  if not found then return array['Case not found']; end if;
  select * into p from public.delinquency_policies where id = c.policy_id;
  if not found then return array['No collection policy is configured for this association']; end if;
  select exists (
    select 1 from public.physical_mail_deliveries m
     where m.delinquency_case_id = c.id and m.status = 'delivered' and m.delivered_at is not null
       and m.delivered_at <= now() - make_interval(days => p.pre_referral_notice_days)
       and (p.notice_method <> 'certified_mail' or m.provider = 'manual_usps' or coalesce(m.mail_class, '') ilike '%certified%')
  ) into v_notice_ok;
  if not v_notice_ok then
    blockers := blockers || format('Delivered %s notice at least %s days before referral',
      case when p.notice_method = 'certified_mail' then 'certified-mail' else 'written' end, p.pre_referral_notice_days);
  end if;
  if p.payment_plan_offer_required and not exists (
    select 1 from public.delinquency_case_events e
     where e.case_id = c.id and e.event_type = 'payment_plan_offered'
       and coalesce((e.metadata ->> 'months')::integer, 0) >= coalesce(p.payment_plan_min_months, 1)
  ) then
    blockers := blockers || format('Recorded payment-plan offer%s', case when p.payment_plan_min_months is not null then ' of at least ' || p.payment_plan_min_months || ' months' else '' end);
  end if;
  if p.board_vote_required then
    select e.event_type into v_latest_board from public.delinquency_case_events e
     where e.case_id = c.id and e.event_type in ('board_referral_approved', 'board_referral_denied') order by e.created_at desc limit 1;
    if v_latest_board is distinct from 'board_referral_approved' then blockers := blockers || 'Recorded board vote approving referral'::text; end if;
  end if;
  return blockers;
end;
$$;


ALTER FUNCTION "public"."delinquency_referral_blockers"("p_case_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delinquency_referral_readiness"("p_case_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare c public.delinquency_cases; p public.delinquency_policies; warnings text[] := '{}';
begin
  select * into c from public.delinquency_cases where id = p_case_id;
  if not found then raise exception 'Delinquency case not found'; end if;
  if not (public.can_access_portfolio(c.portfolio_id) and (public.is_any_staff() or public.is_company_admin() or public.is_platform_operator())
          and public.can_view_association_row(c.association_id)) then
    raise exception 'Not authorized to view this delinquency case';
  end if;
  select * into p from public.delinquency_policies where id = c.policy_id;
  if p.foreclosure_min_balance is not null and c.balance_snapshot < p.foreclosure_min_balance then
    warnings := warnings || format('Balance is below the $%s foreclosure threshold for %s — lien or other remedies only', to_char(p.foreclosure_min_balance, 'FM999,990'), coalesce(p.jurisdiction, 'this jurisdiction'));
  end if;
  if p.foreclosure_min_months is not null and c.oldest_due_date is not null and c.oldest_due_date > public.association_local_date(c.association_id) - make_interval(months => p.foreclosure_min_months) then
    warnings := warnings || format('Delinquent less than %s months — below the foreclosure threshold for %s', p.foreclosure_min_months, coalesce(p.jurisdiction, 'this jurisdiction'));
  end if;
  return jsonb_build_object('blockers', to_jsonb(public.delinquency_referral_blockers(p_case_id)), 'warnings', to_jsonb(warnings), 'jurisdiction', p.jurisdiction);
end;
$_$;


ALTER FUNCTION "public"."delinquency_referral_readiness"("p_case_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."dismiss_violation_report"("p_case_id" "uuid", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  c public.violation_cases;
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
begin
  select * into c from public.violation_cases where id = p_case_id for update;
  if c.id is null or c.archived_at is not null then
    raise exception 'Report not found';
  end if;
  if not public.can_manage_violations(c.association_id) then
    raise exception 'Permission denied' using errcode = '42501';
  end if;
  if c.status <> 'reported' then
    raise exception 'This report was already %', c.status using errcode = '22023';
  end if;
  if v_reason is null then
    raise exception 'Enter a reason for dismissing the report' using errcode = '22023';
  end if;
  update public.violation_cases
     set status = 'dismissed', determination_notes = left(v_reason, 2000), determined_at = now(), determined_by = auth.uid(),
         reviewed_by = auth.uid(), reviewed_at = now(), updated_at = now()
   where id = c.id;
end $$;


