CREATE OR REPLACE FUNCTION "public"."dispatch_wo_status_webhook"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  pid uuid;
begin
  if new.status is distinct from old.status then
    select a.portfolio_id into pid
      from public.associations a
     where a.id = new.association_id;

    if pid is not null then
      perform public.dispatch_webhook(
        pid,
        case when new.status in ('completed','done') then 'work_order.completed'
             else 'work_order.status_changed' end::public.webhook_event,
        jsonb_build_object(
          'work_order_id', new.id,
          'old_status', old.status,
          'new_status', new.status,
          'title', new.title,
          'priority', new.priority,
          'vendor_id', new.vendor_id,
          'unit_id', new.unit_id,
          'association_id', new.association_id
        )
      );
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."dispatch_wo_status_webhook"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."document_path_matches_entity"("p_entity_type" "text", "p_entity_id" "uuid", "p_file_url" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
  select p_entity_id is not null
    and p_file_url is not null
    and octet_length(p_file_url) <= 2048
    and position(chr(92) in p_file_url) = 0
    and p_file_url !~* '(^|/)(\.\.|%2e%2e)(/|$)'
    and p_file_url !~* '^[a-z][a-z0-9+.-]*://'
    and (
      p_file_url = ''
      or (lower(trim(p_entity_type)) = 'association'
          and p_file_url like 'associations/' || p_entity_id::text || '/%')
      or (lower(trim(p_entity_type)) = 'owner'
          and (
            p_file_url like 'insurance/' || p_entity_id::text || '/%'
            or p_file_url like 'owners/' || p_entity_id::text || '/%'
          ))
      or (lower(trim(p_entity_type)) = 'vendor'
          and p_file_url like 'vendors/' || p_entity_id::text || '/%')
      or (lower(trim(p_entity_type)) = 'unit'
          and p_file_url like 'units/' || p_entity_id::text || '/%')
    );
$_$;


ALTER FUNCTION "public"."document_path_matches_entity"("p_entity_type" "text", "p_entity_id" "uuid", "p_file_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."document_portfolio_id"("p_entity_type" "text", "p_entity_id" "uuid", "p_uploaded_by" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$#variable_conflict use_column
begin
  return (select s.x from (

  select case lower(trim(p_entity_type))
    when 'association' then (
      select a.portfolio_id from public.associations a where a.id = p_entity_id
    )
    when 'owner' then (
      select o.portfolio_id from public.owners o where o.id = p_entity_id
    )
    when 'vendor' then (
      select v.portfolio_id from public.vendors v where v.id = p_entity_id
    )
    when 'unit' then (
      select a.portfolio_id
      from public.units u
      join public.buildings b on b.id = u.building_id
      join public.associations a on a.id = b.association_id
      where u.id = p_entity_id
    )
    when 'general' then (
      select p.portfolio_id from public.profiles p where p.id = p_uploaded_by
    )
    else null
  end
  ) s(x) limit 1);
end$$;


