CREATE OR REPLACE FUNCTION "public"."email_queue_sender_problem"("p_portfolio_id" "uuid", "p_association_id" "uuid", "p_from_name" "text", "p_reply_to" "text", "p_own_email" "text", "p_from_address" "text", "p_owner_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_company text;
  v_support text;
  v_association text;
  v_reply text := lower(btrim(coalesce(p_reply_to, '')));
  v_from text := lower(btrim(coalesce(p_from_address, '')));
begin
  select p.company_name, lower(btrim(p.support_email)) into v_company, v_support
    from public.portfolios p where p.id = p_portfolio_id;
  if p_association_id is not null then
    select a.name into v_association from public.associations a
     where a.id = p_association_id and a.portfolio_id = p_portfolio_id;
  end if;

  if p_from_name is not null
     and lower(btrim(p_from_name)) is distinct from lower(btrim(coalesce(v_company, '')))
     and lower(btrim(p_from_name)) is distinct from lower(btrim(coalesce(v_association, ''))) then
    return 'Emails are sent under the company''s or association''s name';
  end if;

  if v_reply <> ''
     and v_reply is distinct from v_support
     and v_reply is distinct from lower(btrim(coalesce(p_own_email, '')))
     and not exists (select 1 from public.portfolio_email_domains d
                      where d.portfolio_id = p_portfolio_id and d.enabled and d.status = 'verified'
                        and lower(d.domain) = split_part(v_reply, '@', 2)) then
    return 'Replies go to the company''s support address, your own address or the company''s email domain';
  end if;

  if v_from <> ''
     and v_from not in ('hello@portier369.com', 'noreply@portier369.com', 'maintenance@portier369.com')
     and not exists (select 1 from public.portfolio_email_domains d
                      where d.portfolio_id = p_portfolio_id and d.enabled and d.status = 'verified'
                        and lower(d.domain) = split_part(v_from, '@', 2)) then
    return 'Emails are sent from the company''s or the platform''s own address';
  end if;

  if p_owner_id is not null and not exists (
       select 1 from public.owners o where o.id = p_owner_id and o.portfolio_id = p_portfolio_id) then
    return 'That owner is not with this company';
  end if;
  return null;
end
$$;


ALTER FUNCTION "public"."email_queue_sender_problem"("p_portfolio_id" "uuid", "p_association_id" "uuid", "p_from_name" "text", "p_reply_to" "text", "p_own_email" "text", "p_from_address" "text", "p_owner_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."email_queue_user_rate_limit"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  r record;
  v_over text;
begin
  if current_user not in ('authenticated', 'anon') then
    return null;
  end if;
  -- One company's sends are checked one at a time (locks taken in a fixed
  -- order, so two multi-company inserts can't deadlock). This function must
  -- stay VOLATILE and the count must be its own statement after the lock: under
  -- READ COMMITTED it then sees every send committed while it waited.
  for r in select distinct portfolio_id from new_rows where portfolio_id is not null order by portfolio_id loop
    perform pg_advisory_xact_lock(hashtextextended('email_queue_rate:' || r.portfolio_id::text, 0));
  end loop;
  select coalesce(p.company_name, n.portfolio_id::text) into v_over
    from (select distinct portfolio_id from new_rows where portfolio_id is not null) n
    left join public.portfolios p on p.id = n.portfolio_id
   where public.email_queue_company_recent_count(n.portfolio_id) > 5000
   limit 1;
  if v_over is not null then
    raise exception 'More than 5,000 emails were queued for % in the last hour; try again later', v_over using errcode = '54000';
  end if;
  return null;
end
$$;


ALTER FUNCTION "public"."email_queue_user_rate_limit"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."email_queue_zz_suppression"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if tg_op = 'INSERT' then
    if public.email_queue_optional_key(new.idempotency_key) then
      new.mail_class := 'optional';
    elsif current_user in ('authenticated', 'anon')
          and new.mail_class = 'required'
          and not coalesce(new.holds_auth_link, false)
          and not public.email_queue_required_key(new.idempotency_key) then
      new.mail_class := 'optional';
    end if;
    new.suppressed_at := null;
    return new;
  end if;
  if current_user in ('authenticated', 'anon') then
    new.mail_class := old.mail_class;
  end if;
  if old.suppressed_at is not null and new.status = 'pending' and old.status <> 'pending' then
    new.suppressed_at := null;
  elsif current_user in ('authenticated', 'anon') then
    new.suppressed_at := old.suppressed_at;
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."email_queue_zz_suppression"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."email_set_unsubscribed"("p_token" "text", "p_unsubscribed" boolean, "p_source" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  l public.email_unsubscribe_links;
begin
  if coalesce(auth.role(), '') <> 'service_role' then raise exception 'Service role required'; end if;
  if p_token !~ '^[0-9a-f]{64}$' then return false; end if;
  select * into l from public.email_unsubscribe_links where token = p_token;
  if not found then return false; end if;
  if p_unsubscribed then
    insert into public.email_suppressions (portfolio_id, email, reason, source)
    values (l.portfolio_id, l.email, 'unsubscribed', left(coalesce(p_source, 'unsubscribe_link'), 100))
    on conflict (portfolio_id, email, reason) do update
      set cleared_at = null, cleared_by = null, suppressed_at = now(), source = excluded.source
      where public.email_suppressions.cleared_at is not null;
  else
    update public.email_suppressions s
       set cleared_at = now(), cleared_by = null, source = 'resubscribed_by_recipient'
     where s.portfolio_id = l.portfolio_id and s.email = l.email
       and s.reason in ('unsubscribed', 'complained') and s.cleared_at is null;
  end if;
  return true;
end $_$;


ALTER FUNCTION "public"."email_set_unsubscribed"("p_token" "text", "p_unsubscribed" boolean, "p_source" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."email_suppress_from_event"("p_provider_message_id" "text", "p_reason" "text", "p_detail" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  q public.email_queue;
  v_portfolio uuid;
begin
  if coalesce(auth.role(), '') <> 'service_role' then raise exception 'Service role required'; end if;
  if p_reason not in ('bounced', 'complained') then raise exception 'Unknown suppression reason'; end if;
  select * into q from public.email_queue where provider_message_id = p_provider_message_id limit 1;
  if not found then return false; end if;
  v_portfolio := coalesce((select a.portfolio_id from public.associations a where a.id = q.association_id), q.portfolio_id);
  if v_portfolio is null or coalesce(q.to_email, '') !~ '@' then return false; end if;
  insert into public.email_suppressions (portfolio_id, email, reason, source, detail)
  values (v_portfolio, lower(btrim(q.to_email)), p_reason, 'resend_' || p_reason, left(p_detail, 500))
  on conflict (portfolio_id, email, reason) do update
    set cleared_at = null, cleared_by = null, suppressed_at = now(), source = excluded.source, detail = excluded.detail
    where public.email_suppressions.cleared_at is not null;
  return true;
end $$;


ALTER FUNCTION "public"."email_suppress_from_event"("p_provider_message_id" "text", "p_reason" "text", "p_detail" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."email_suppression_reason"("p_portfolio" "uuid", "p_email" "text", "p_class" "text", "p_owner" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select case
    when p_portfolio is null then null
    when exists (select 1 from public.email_suppressions s
                  where s.portfolio_id = p_portfolio and s.email = lower(btrim(p_email))
                    and s.reason = 'bounced' and s.cleared_at is null)
      then 'Not sent: email to this address bounced. Fix the address, then allow email to it again.'
    when p_class = 'optional' and exists (select 1 from public.email_suppressions s
                  where s.portfolio_id = p_portfolio and s.email = lower(btrim(p_email))
                    and s.reason = 'complained' and s.cleared_at is null)
      then 'Not sent: the recipient marked an earlier email as spam, so optional email stopped.'
    when p_class = 'optional' and exists (select 1 from public.email_suppressions s
                  where s.portfolio_id = p_portfolio and s.email = lower(btrim(p_email))
                    and s.reason = 'unsubscribed' and s.cleared_at is null)
      then 'Not sent: the recipient unsubscribed from optional email.'
  end
$$;


ALTER FUNCTION "public"."email_suppression_reason"("p_portfolio" "uuid", "p_email" "text", "p_class" "text", "p_owner" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."email_suppressions_audit"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  new.updated_at := now();
  if tg_op = 'INSERT' or (old.cleared_at is not null and new.cleared_at is null) then
    insert into public.email_suppression_events (suppression_id, portfolio_id, email, reason, action, source)
    values (new.id, new.portfolio_id, new.email, new.reason, 'suppressed', new.source);
  elsif old.cleared_at is null and new.cleared_at is not null then
    insert into public.email_suppression_events (suppression_id, portfolio_id, email, reason, action, source)
    values (new.id, new.portfolio_id, new.email, new.reason, 'cleared', new.source);
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."email_suppressions_audit"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."email_unsubscribe_session"("p_token" "text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
  select jsonb_build_object(
           'portfolio_id', l.portfolio_id,
           'company_name', p.company_name,
           'email_hint', left(l.email, 1) || '***@' || split_part(l.email, '@', 2),
           'unsubscribed', exists (select 1 from public.email_suppressions s
                                    where s.portfolio_id = l.portfolio_id and s.email = l.email
                                      and s.reason = 'unsubscribed' and s.cleared_at is null))
    from public.email_unsubscribe_links l
    join public.portfolios p on p.id = l.portfolio_id
   where l.token = p_token and p_token ~ '^[0-9a-f]{64}$'
$_$;


ALTER FUNCTION "public"."email_unsubscribe_session"("p_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."end_occupancies_past_move_out"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare n integer;
begin
  -- ownership_fixes: a move-out date is a day in the association's calendar.
  update public.occupancies o
     set status = 'past', updated_at = now()
   where o.status = 'current'
     and o.move_out_date is not null
     and o.move_out_date <= public.association_local_date(o.association_id);
  get diagnostics n = row_count;
  return n;
end $$;


ALTER FUNCTION "public"."end_occupancies_past_move_out"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."end_owner_unit_items_when_occupancy_ends"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_day date;
  v_charge_ids uuid[];
begin
  if not (old.status = 'current' and new.status = 'past'
          and new.occupancy_type = 'owner' and new.owner_id is not null) then
    return null;
  end if;

  -- Still an owner of this unit through another current occupancy: keep.
  if exists (
    select 1 from public.occupancies o
     where o.id <> new.id
       and o.unit_id = new.unit_id
       and o.owner_id = new.owner_id
       and o.occupancy_type = 'owner'
       and o.status = 'current'
  ) then
    return null;
  end if;

  v_day := coalesce(new.move_out_date, public.association_local_date(new.association_id));

  with ended as (
    update public.parking_assignments pa
       set status = 'ended',
           end_date = greatest(v_day, pa.start_date),
           updated_at = now()
     where pa.unit_id = new.unit_id
       and pa.owner_id = new.owner_id
       and pa.status = 'active'
    returning pa.recurring_charge_id
  )
  select array_agg(recurring_charge_id) filter (where recurring_charge_id is not null)
    into v_charge_ids
    from ended;

  if v_charge_ids is not null then
    update public.unit_recurring_charges urc
       set active = false,
           end_date = greatest(v_day, urc.start_date)
     where urc.id = any (v_charge_ids)
       and urc.unit_id = new.unit_id
       and urc.active;
  end if;

  update public.unit_pets p
     set archived_at = now()
   where p.unit_id = new.unit_id
     and p.owner_id = new.owner_id
     and p.archived_at is null;

  return null;
end
$$;


ALTER FUNCTION "public"."end_owner_unit_items_when_occupancy_ends"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_applied_row_unit_fixed"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_applied boolean;
begin
  if new.unit_id is not distinct from old.unit_id then
    return new;
  end if;
  if tg_table_name = 'payments' then
    v_applied := exists (select 1 from public.payment_applications pa where pa.payment_id = old.id);
  else
    v_applied := exists (select 1 from public.payment_applications pa where pa.charge_id = old.id);
  end if;
  if v_applied then
    raise exception 'This % is applied, so its unit cannot change. Remove the application first.',
      case when tg_table_name = 'payments' then 'payment' else 'charge' end
      using errcode = '23514';
  end if;
  return new;
end
$$;


ALTER FUNCTION "public"."enforce_applied_row_unit_fixed"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_association_property_group_company"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  -- FOR SHARE locks the group row: a concurrent move of the group (an UPDATE,
  -- which conflicts) waits for this transaction, then its own check sees this
  -- association; and if the move got there first, this waits and re-reads the
  -- moved row, which no longer matches. The two checks can't both pass.
  if new.property_group_id is not null and not exists (
    select 1 from public.property_groups pg
     where pg.id = new.property_group_id
       and pg.portfolio_id = new.portfolio_id
       for share
  ) then
    raise exception 'Property group not found for this company' using errcode = '23503';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."enforce_association_property_group_company"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_capital_project_scope"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  association_portfolio uuid;
  component_portfolio uuid;
  component_association uuid;
begin
  select portfolio_id into association_portfolio
  from public.associations where id = new.association_id;

  if association_portfolio is null or association_portfolio <> new.portfolio_id then
    raise exception 'Capital project association must belong to the same portfolio';
  end if;

  if new.reserve_component_id is not null then
    select portfolio_id, association_id into component_portfolio, component_association
    from public.reserve_components where id = new.reserve_component_id;
    if component_portfolio is null
       or component_portfolio <> new.portfolio_id
       or component_association <> new.association_id then
      raise exception 'Reserve component must match the capital project scope';
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."enforce_capital_project_scope"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_capital_project_work_order_scope"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  project_portfolio uuid;
  project_association uuid;
  work_order_portfolio uuid;
  work_order_association uuid;
begin
  select portfolio_id, association_id into project_portfolio, project_association
  from public.capital_projects where id = new.project_id;
  select coalesce(wo.portfolio_id, a.portfolio_id), wo.association_id
    into work_order_portfolio, work_order_association
  from public.work_orders wo
  join public.associations a on a.id = wo.association_id
  where wo.id = new.work_order_id;

  if project_portfolio is null or work_order_portfolio is null
     or project_portfolio <> work_order_portfolio
     or project_association <> work_order_association then
    raise exception 'Work order must match the capital project portfolio and association';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."enforce_capital_project_work_order_scope"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_certified_funds_only"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if new.method in ('check', 'cash', 'other') and exists (
    select 1 from public.occupancies o
     where o.unit_id = new.unit_id and o.status = 'current' and o.certified_funds_only
  ) then
    raise exception 'This homeowner is on certified funds only. Record a money order, cashier''s check or wire instead.'
      using errcode = '23514';
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."enforce_certified_funds_only"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_charge_category_company"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if new.association_id is not null and not exists (
    select 1 from public.associations a
     where a.id = new.association_id and a.portfolio_id = new.portfolio_id
  ) then
    raise exception 'The association must belong to the charge category''s company' using errcode = '42501';
  end if;
  if new.gl_account_id is not null and not exists (
    select 1 from public.gl_accounts g
     where g.id = new.gl_account_id and g.portfolio_id = new.portfolio_id
  ) then
    raise exception 'The GL account must belong to the charge category''s company' using errcode = '42501';
  end if;
  -- A category already used by other associations' units can't be narrowed
  -- to one association (or moved to another company): their recurring
  -- charges would stop posting.
  if tg_op = 'UPDATE'
     and (new.portfolio_id is distinct from old.portfolio_id
          or (new.association_id is not null and new.association_id is distinct from old.association_id))
     and (exists (
           select 1 from public.unit_recurring_charges r
             join public.units u on u.id = r.unit_id
             join public.buildings b on b.id = u.building_id
             join public.associations a on a.id = b.association_id
            where r.charge_category_id = new.id
              and (a.portfolio_id is distinct from new.portfolio_id
                   or (new.association_id is not null and b.association_id is distinct from new.association_id)))
       or exists (
           select 1 from public.charges c
             join public.units u on u.id = c.unit_id
             join public.buildings b on b.id = u.building_id
             join public.associations a on a.id = b.association_id
            where c.charge_category_id = new.id
              and (a.portfolio_id is distinct from new.portfolio_id
                   or (new.association_id is not null and b.association_id is distinct from new.association_id)))) then
    raise exception 'This charge category is already used by other associations'' units' using errcode = '42501';
  end if;
  return new;
end
$$;


ALTER FUNCTION "public"."enforce_charge_category_company"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_charge_category_unit_scope"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_assoc uuid;
  v_portfolio uuid;
  v_cat record;
begin
  if new.charge_category_id is null or new.unit_id is null then
    return new;
  end if;
  if tg_op = 'UPDATE'
     and new.charge_category_id is not distinct from old.charge_category_id
     and new.unit_id is not distinct from old.unit_id then
    return new;
  end if;
  v_assoc := public.unit_association_id(new.unit_id);
  select a.portfolio_id into v_portfolio from public.associations a where a.id = v_assoc;
  select c.portfolio_id, c.association_id into v_cat
    from public.charge_categories c where c.id = new.charge_category_id
    for share;
  if not found then
    raise exception 'Charge category not found' using errcode = '23503';
  end if;
  if v_cat.portfolio_id is not null and v_cat.portfolio_id is distinct from v_portfolio then
    raise exception 'This charge category belongs to another company' using errcode = '42501';
  end if;
  if tg_argv[0] = 'association'
     and v_cat.association_id is not null and v_cat.association_id is distinct from v_assoc then
    raise exception 'This charge category belongs to another association' using errcode = '42501';
  end if;
  return new;
end
$$;


ALTER FUNCTION "public"."enforce_charge_category_unit_scope"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_delinquency_scope"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  association_portfolio uuid;
  unit_association uuid;
  policy_association uuid;
begin
  select portfolio_id into association_portfolio from public.associations where id = new.association_id;
  select b.association_id into unit_association
  from public.units u join public.buildings b on b.id = u.building_id where u.id = new.unit_id;
  if new.policy_id is not null then
    select association_id into policy_association from public.delinquency_policies where id = new.policy_id;
  end if;
  if association_portfolio is null or association_portfolio <> new.portfolio_id
     or unit_association is null or unit_association <> new.association_id
     or (new.policy_id is not null and policy_association <> new.association_id) then
    raise exception 'Delinquency case records must share one portfolio and association';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."enforce_delinquency_scope"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_gl_use_permission"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  gl_id uuid;
begin
  gl_id := nullif(to_jsonb(new) ->> tg_argv[0], '')::uuid;
  -- Service jobs have no end-user auth identity and remain governed by their
  -- service-role boundary. Every authenticated write must honor `full`.
  if auth.uid() is not null and gl_id is not null and not public.can_use_gl(gl_id) then
    raise exception 'Your role does not have full permission for this GL account';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."enforce_gl_use_permission"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_payable_association_scope"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if auth.uid() is null then return new; end if;  -- scheduled jobs
  if (new.association_id is not null and not public.can_view_association_row(new.association_id))
     or (tg_op = 'UPDATE' and old.association_id is not null and not public.can_view_association_row(old.association_id)) then
    raise exception 'You do not manage this association' using errcode = '42501';
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."enforce_payable_association_scope"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_payment_application_same_unit"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_payment_unit uuid;
  v_charge_unit uuid;
begin
  select p.unit_id into v_payment_unit from public.payments p where p.id = new.payment_id for share;
  select c.unit_id into v_charge_unit from public.charges c where c.id = new.charge_id for share;
  if v_payment_unit is null or v_charge_unit is null or v_payment_unit <> v_charge_unit then
    raise exception 'A payment can only be applied to a charge on the same unit'
      using errcode = '23514';
  end if;
  return new;
end
$$;


ALTER FUNCTION "public"."enforce_payment_application_same_unit"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_physical_mail_scope"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  case_portfolio uuid;
  case_association uuid;
  case_owner uuid;
begin
  if new.association_id is not null and not exists (
    select 1 from public.associations association
    where association.id = new.association_id and association.portfolio_id = new.portfolio_id
  ) then
    raise exception 'physical-mail association must belong to the same portfolio';
  end if;
  if new.owner_id is not null and not exists (
    select 1 from public.owners owner
    where owner.id = new.owner_id and owner.portfolio_id = new.portfolio_id
  ) then
    raise exception 'physical-mail owner must belong to the same portfolio';
  end if;
  if new.delinquency_case_id is not null then
    select portfolio_id, association_id, owner_id into case_portfolio, case_association, case_owner
    from public.delinquency_cases where id = new.delinquency_case_id;
    if case_portfolio is null
       or case_portfolio <> new.portfolio_id
       or new.association_id is distinct from case_association
       or new.owner_id is distinct from case_owner then
      raise exception 'physical mail must match its delinquency case scope';
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."enforce_physical_mail_scope"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_property_group_company_move"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if new.portfolio_id is distinct from old.portfolio_id and exists (
    select 1 from public.associations a where a.property_group_id = old.id
  ) then
    raise exception 'Remove the associations from this group before moving it to another company' using errcode = '23503';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."enforce_property_group_company_move"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_reserve_component_scope"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  parent_portfolio uuid;
  parent_association uuid;
  asset_portfolio uuid;
  asset_association uuid;
begin
  select portfolio_id, association_id
    into parent_portfolio, parent_association
  from public.reserve_studies
  where id = new.study_id;

  if parent_portfolio is null
     or parent_portfolio <> new.portfolio_id
     or parent_association <> new.association_id then
    raise exception 'Reserve planning record must match its study scope';
  end if;

  if new.fixed_asset_id is not null then
    select portfolio_id, association_id
      into asset_portfolio, asset_association
    from public.fixed_assets
    where id = new.fixed_asset_id
    -- reserve_component_asset_lock: a share lock waits for (and blocks) a
    -- concurrent move of the asset, so the move's own check sees this link.
    for share;

    -- purchase_orders_fixes: an asset with no association matches nothing.
    if asset_portfolio is null
       or asset_portfolio <> new.portfolio_id
       or asset_association is distinct from new.association_id then
      raise exception 'The fixed asset must belong to the same association as this reserve study';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."enforce_reserve_component_scope"() OWNER TO "postgres";


