CREATE OR REPLACE FUNCTION "public"."enforce_row_association_scope"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  n jsonb := case when tg_op <> 'DELETE' then to_jsonb(new) end;
  o jsonb := case when tg_op <> 'INSERT' then to_jsonb(old) end;
  a uuid;
  v_vendor_association uuid;
begin
  if auth.uid() is null or not public.manager_is_scoped() then return coalesce(new, old); end if;  -- jobs, unscoped users
  foreach a in array array[public.row_association_id(n), public.row_association_id(o)] loop
    if a is not null and not public.can_view_association_row(a) then
      raise exception 'You do not manage this association' using errcode = '42501';
    end if;
  end loop;
  -- Notes and tags on an owner record follow the owner's associations.
  if coalesce(lower(n->>'entity_type'), lower(o->>'entity_type')) = 'owner'
     and not public.can_view_owner_row(coalesce(n->>'entity_id', o->>'entity_id')::uuid) then
    raise exception 'You do not manage this owner' using errcode = '42501';
  end if;
  -- Notes and tags on a vendor follow the vendor's association.
  if coalesce(lower(n->>'entity_type'), lower(o->>'entity_type')) = 'vendor' then
    select ven.association_id into v_vendor_association
      from public.vendors ven where ven.id = coalesce(n->>'entity_id', o->>'entity_id')::uuid;
    if found and (not public.can_write_vendor_row(v_vendor_association)
                  or (v_vendor_association is not null and not public.can_view_association_row(v_vendor_association))) then
      raise exception 'You do not manage this vendor' using errcode = '42501';
    end if;
  end if;
  return coalesce(new, old);
end $$;


ALTER FUNCTION "public"."enforce_row_association_scope"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_communication_message"("p_message_id" "uuid", "p_recipients" "jsonb", "p_html" "text", "p_from_name" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $_$
declare
  v_message public.communication_messages%rowtype;
  v_reply text;
  v_count integer := 0;
begin
  if not (public.is_staff() or public.is_platform_operator()) then
    raise exception 'Staff access required';
  end if;

  select * into v_message
  from public.communication_messages
  where id = p_message_id
  for update;

  if not found then raise exception 'Message not found or unavailable'; end if;
  if v_message.channel <> 'email' then raise exception 'Only email messages may be queued'; end if;
  if v_message.status in ('queued', 'sent') then
    select count(*) into v_count from public.email_queue where communication_message_id = p_message_id;
    return v_count;
  end if;
  if coalesce(length(v_message.subject), 0) < 1 or length(v_message.subject) > 300 then
    raise exception 'Message subject length is invalid';
  end if;
  if coalesce(length(v_message.body), 0) < 1 or length(v_message.body) > 50000 then
    raise exception 'Message body length is invalid';
  end if;
  if jsonb_typeof(p_recipients) <> 'array' or jsonb_array_length(p_recipients) < 1
     or jsonb_array_length(p_recipients) > 5000 then
    raise exception 'Recipient count must be between 1 and 5,000';
  end if;
  if coalesce(length(p_html), 0) < 1 or length(p_html) > 200000 then
    raise exception 'Rendered message length is invalid';
  end if;

  select nullif(lower(btrim(p.support_email)), '') into v_reply
    from public.portfolios p where p.id = v_message.portfolio_id;

  if exists (select 1 from jsonb_array_elements(p_recipients) x(value)
              where length(lower(trim(x.value ->> 'email'))) > 320
                 or coalesce(lower(trim(x.value ->> 'email')), '') !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$') then
    raise exception 'Invalid recipient email address';
  end if;

  insert into public.email_queue (
    to_email, to_name, subject, body, association_id, portfolio_id,
    sent_by, status, from_address, from_name, reply_to,
    communication_message_id, idempotency_key, owner_id
  )
  select distinct on (r.email)
         r.email, r.name, v_message.subject, p_html, v_message.association_id,
         v_message.portfolio_id, auth.uid(), 'pending', 'hello@portier369.com',
         left(nullif(trim(p_from_name), ''), 200), v_reply, p_message_id,
         'communication:' || p_message_id::text || ':' || r.email,
         o.id
    from (select lower(trim(x.value ->> 'email')) as email,
                 nullif(trim(x.value ->> 'name'), '') as name,
                 case when (x.value ->> 'owner_id') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                      then (x.value ->> 'owner_id')::uuid end as owner_id
            from jsonb_array_elements(p_recipients) x(value)) r
    left join public.owners o
      on o.id = r.owner_id and o.portfolio_id = v_message.portfolio_id and lower(btrim(o.email)) = r.email
   order by r.email
  on conflict (idempotency_key) do update
    set status = 'pending',
        attempt_count = 0,
        next_attempt_at = now(),
        processing_at = null,
        error_message = null
    where public.email_queue.status = 'failed';
  get diagnostics v_count = row_count;

  update public.communication_messages
  set status = 'queued', queued_at = now(), error_message = null, updated_at = now()
  where id = p_message_id;

  return v_count;
end;
$_$;


ALTER FUNCTION "public"."enqueue_communication_message"("p_message_id" "uuid", "p_recipients" "jsonb", "p_html" "text", "p_from_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_scheduled_reports"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  row record;
  n integer := 0;
  v_run_as uuid;
  v_error text;
begin
  for row in
    select s.*, d.slug as report_slug
      from public.scheduled_reports s
      left join public.report_definitions d on d.id = s.definition_id
     where s.active and s.archived_at is null
       and (s.next_run_at is null or s.next_run_at <= now())
  loop
    v_run_as := coalesce(row.run_as, row.created_by);
    -- One schedule's failed check pauses that schedule, not the whole run.
    begin
      v_error := public.report_access_error_as(v_run_as, row.portfolio_id, row.report_slug, coalesce(row.parameters, '{}'::jsonb));
    exception when others then
      v_error := 'The access check for this report could not be completed.';
    end;
    if v_error is not null then
      -- One failed run says why; the schedule stops until someone with access
      -- saves or resumes it (which makes it run with their access).
      insert into public.report_runs (
        portfolio_id, definition_id, saved_report_id, scheduled_report_id,
        status, parameters, output_format, triggered_by, started_at, finished_at, error_message
      ) values (
        row.portfolio_id, row.definition_id, row.saved_report_id, row.id,
        'failed', row.parameters, row.output_format, v_run_as, now(), now(),
        'Schedule paused: ' || v_error || ' Someone who can see this report can resume the schedule; it then runs with their access.'
      );
      update public.scheduled_reports
         set active = false, last_run_at = now(), updated_at = now()
       where id = row.id;
      continue;
    end if;

    insert into public.report_runs (
      portfolio_id, definition_id, saved_report_id, scheduled_report_id,
      status, parameters, output_format, triggered_by
    ) values (
      row.portfolio_id, row.definition_id, row.saved_report_id, row.id,
      'queued', row.parameters, row.output_format, v_run_as
    );

    update public.scheduled_reports
       set next_run_at = public.scheduled_report_next_run(
             row.frequency, row.day_of_week, row.day_of_month,
             coalesce(row.local_hour, row.hour_utc),
             case when row.local_hour is null then 'UTC' else row.time_zone end,
             case when row.frequency = 'biweekly' then now() + interval '7 days' else now() end),
           last_run_at = now(),
           updated_at = now()
     where id = row.id;
    n := n + 1;
  end loop;
  return n;
end;
$$;


ALTER FUNCTION "public"."enqueue_scheduled_reports"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enroll_autopay"("p_unit_id" "uuid", "p_payment_method_id" "uuid", "p_authorized_max_cents" integer, "p_frequency" "public"."autopay_frequency" DEFAULT 'on_charge_posted'::"public"."autopay_frequency") RETURNS "public"."autopay_mandates"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  m public.autopay_mandates;
  v_owner uuid;
  v_portfolio uuid;
  v_assoc uuid;
begin
  if not exists (select 1 from public.current_owner_ids()) then
    raise exception 'must be logged in as a homeowner to enroll';
  end if;

  select a.portfolio_id, a.id into v_portfolio, v_assoc
    from public.units u
    join public.buildings b on b.id = u.building_id
    join public.associations a on a.id = b.association_id
   where u.id = p_unit_id;

  select o.owner_id into v_owner
    from public.occupancies o
   where o.unit_id = p_unit_id and o.owner_id in (select public.current_owner_ids()) and o.status = 'current'
   order by o.created_at, o.id
   limit 1;
  if v_owner is null then
    raise exception 'you are not a current occupant of this unit';
  end if;

  if not exists (
    select 1 from public.payment_methods pm
     where pm.id = p_payment_method_id and pm.owner_id = v_owner and pm.archived_at is null
  ) then
    raise exception 'payment method not found or not owned by you';
  end if;

  insert into public.autopay_mandates (
    portfolio_id, association_id, owner_id, unit_id, payment_method_id,
    authorized_amount_max_cents, frequency, status,
    mandate_signed_at
  ) values (
    v_portfolio, v_assoc, v_owner, p_unit_id, p_payment_method_id,
    p_authorized_max_cents, p_frequency, 'active',
    now()
  ) returning * into m;
  return m;
end;
$$;


ALTER FUNCTION "public"."enroll_autopay"("p_unit_id" "uuid", "p_payment_method_id" "uuid", "p_authorized_max_cents" integer, "p_frequency" "public"."autopay_frequency") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ensure_default_violation_schedule"("p_association_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare n integer;
begin
  if not public.can_manage_violations(p_association_id) then raise exception 'Permission denied' using errcode = '42501'; end if;
  select count(*) into n from public.violation_followup_steps where association_id = p_association_id and house_rule_id is null and archived_at is null;
  if n > 0 then return 0; end if;
  insert into public.violation_followup_steps (association_id, step_order, days_after_previous, follow_up_name, delivery_methods, fee, offers_hearing)
  values
    (p_association_id, 1, 0,  'Courtesy notice', '{email,portal}', 0, false),
    (p_association_id, 2, 14, 'Formal notice with hearing opportunity', '{email,portal,mail}', 0, true),
    (p_association_id, 3, 14, 'First fine', '{email,portal,mail}', 50, false),
    (p_association_id, 4, 30, 'Continuing violation fine', '{email,portal,mail}', 100, false);
  return 4;
end;
$$;


ALTER FUNCTION "public"."ensure_default_violation_schedule"("p_association_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ensure_operating_and_reserve_accounts"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  op_id uuid;
  rs_id uuid;
BEGIN
  INSERT INTO public.bank_accounts (portfolio_id, association_id, name, account_type, purpose)
  VALUES (NEW.portfolio_id, NEW.id, 'Operating', 'checking', 'operating')
  RETURNING id INTO op_id;

  INSERT INTO public.bank_accounts (portfolio_id, association_id, name, account_type, purpose)
  VALUES (NEW.portfolio_id, NEW.id, 'Reserve', 'savings', 'reserve')
  RETURNING id INTO rs_id;

  UPDATE public.associations
    SET operating_bank_account_id = op_id,
        reserve_bank_account_id   = rs_id
  WHERE id = NEW.id;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."ensure_operating_and_reserve_accounts"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ensure_payable_bill_accrual"("p_bill_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  bill_row public.payable_bills;
  ap_account_id uuid;
  entry_id uuid;
begin
  select * into bill_row from public.payable_bills where id = p_bill_id for update;
  if not found then raise exception 'Bill not found'; end if;
  if coalesce(auth.role(), '') not in ('', 'service_role')
     and not (public.can_manage_finance(bill_row.portfolio_id) and public.can_view_association_row(bill_row.association_id)) then
    raise exception 'Permission denied';
  end if;
  if bill_row.status not in ('approved'::public.payable_bill_status, 'paid'::public.payable_bill_status) then
    raise exception 'Bill must be approved before posting';
  end if;
  if bill_row.association_id is null or bill_row.gl_account_id is null then
    raise exception 'Bill requires an association and expense GL account before posting';
  end if;

  select id into entry_id from public.journal_entries
   where source_type = 'payable_bill' and source_id = p_bill_id;
  if found then return entry_id; end if;

  perform 1 from public.gl_accounts
   where id = bill_row.gl_account_id
     and portfolio_id = bill_row.portfolio_id
     and active
     and (association_id is null or association_id = bill_row.association_id);
  if not found then raise exception 'Bill expense GL account is not active in this portfolio/association'; end if;

  ap_account_id := public.app_ap_account(bill_row.portfolio_id, bill_row.association_id);
  if ap_account_id is null then raise exception 'No active Accounts Payable GL account is configured'; end if;

  insert into public.journal_entries (
    portfolio_id, entry_date, description, memo, reference_number,
    source_type, source_id, created_by, posted, posted_at
  ) values (
    bill_row.portfolio_id, bill_row.bill_date,
    'Bill accrued: ' || coalesce(bill_row.bill_number, p_bill_id::text), bill_row.memo,
    bill_row.bill_number, 'payable_bill', p_bill_id, coalesce(auth.uid(), bill_row.created_by), true, now()
  ) returning id into entry_id;

  insert into public.journal_lines (entry_id, association_id, gl_account_id, debit_amount, credit_amount, memo, sort_order)
  values
    (entry_id, bill_row.association_id, bill_row.gl_account_id, bill_row.amount, 0, bill_row.memo, 1),
    (entry_id, bill_row.association_id, ap_account_id, 0, bill_row.amount, bill_row.memo, 2);
  return entry_id;
end $$;


ALTER FUNCTION "public"."ensure_payable_bill_accrual"("p_bill_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enter_vendor_credit"("p_association_id" "uuid", "p_vendor_id" "uuid", "p_credit_date" "date", "p_gl_account_id" "uuid", "p_amount" numeric, "p_reference" "text", "p_memo" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_pid uuid;
  v_amt numeric := round(p_amount, 2);
  v_ap uuid;
  v_gl public.gl_accounts;
  v_vendor text;
  v_credit uuid;
  v_entry uuid;
begin
  select portfolio_id into v_pid from public.associations where id = p_association_id and archived_at is null;
  if v_pid is null or not public.can_manage_finance(v_pid) or not public.can_manage_association(p_association_id) then
    raise exception 'You do not have accounting access to this association' using errcode = '42501';
  end if;
  select name into v_vendor from public.vendors where id = p_vendor_id and portfolio_id = v_pid and archived_at is null;
  if v_vendor is null then raise exception 'Vendor not found' using errcode = '22023'; end if;
  if p_credit_date is null or p_credit_date > current_date + 31 or p_credit_date < date '2000-01-01' then
    raise exception 'Enter a valid credit date' using errcode = '22023';
  end if;
  if v_amt is null or v_amt <= 0 or v_amt > 10000000 then
    raise exception 'Enter an amount greater than zero' using errcode = '22023';
  end if;
  select * into v_gl from public.gl_accounts g where g.id = p_gl_account_id and g.portfolio_id = v_pid and coalesce(g.active, true)
     and (g.association_id is null or g.association_id = p_association_id);
  if v_gl.id is null or v_gl.account_type::text in ('cash', 'accounts_receivable', 'accounts_payable') then
    raise exception 'Choose the account the credit reduces (usually the original expense)' using errcode = '22023';
  end if;
  v_ap := public.app_ap_account(v_pid, p_association_id);
  if v_ap is null then raise exception 'No Accounts Payable account is set up for this association' using errcode = '22023'; end if;
  if v_gl.id = v_ap then raise exception 'Choose the account the credit reduces (usually the original expense)' using errcode = '22023'; end if;

  insert into public.vendor_credits (portfolio_id, association_id, vendor_id, credit_date, gl_account_id, amount, reference, memo, created_by)
  values (v_pid, p_association_id, p_vendor_id, p_credit_date, v_gl.id, v_amt,
          nullif(left(btrim(coalesce(p_reference, '')), 100), ''), nullif(left(btrim(coalesce(p_memo, '')), 1000), ''), auth.uid())
  returning id into v_credit;

  insert into public.journal_entries (portfolio_id, entry_date, reference_number, description, memo, source_type, source_id, posted, created_by)
  values (v_pid, p_credit_date, nullif(left(btrim(coalesce(p_reference, '')), 100), ''), left('Vendor credit — ' || v_vendor, 250),
          nullif(left(btrim(coalesce(p_memo, '')), 1000), ''), 'vendor_credit', v_credit, false, auth.uid())
  returning id into v_entry;
  insert into public.journal_lines (entry_id, gl_account_id, association_id, debit_amount, credit_amount, memo, sort_order)
  values (v_entry, v_ap, p_association_id, v_amt, 0, left('Vendor credit — ' || v_vendor, 250), 0),
         (v_entry, v_gl.id, p_association_id, 0, v_amt, left('Vendor credit — ' || v_vendor, 250), 1);
  update public.journal_entries set posted = true, posted_at = now() where id = v_entry;
  update public.vendor_credits set journal_entry_id = v_entry where id = v_credit;
  return v_credit;
end $$;


ALTER FUNCTION "public"."enter_vendor_credit"("p_association_id" "uuid", "p_vendor_id" "uuid", "p_credit_date" "date", "p_gl_account_id" "uuid", "p_amount" numeric, "p_reference" "text", "p_memo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."escrow_offset_by_association"("p_escrow_gl_ids" "uuid"[]) RETURNS TABLE("association_id" "uuid", "offset_balance" numeric)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select jl.association_id, sum(jl.credit_amount - jl.debit_amount)
    from public.journal_lines jl
    join public.journal_entries je on je.id = jl.entry_id and je.posted
   where not (jl.gl_account_id = any (p_escrow_gl_ids))
     and exists (select 1 from public.journal_lines e
                  where e.entry_id = jl.entry_id and e.gl_account_id = any (p_escrow_gl_ids))
   group by jl.association_id;
$$;


ALTER FUNCTION "public"."escrow_offset_by_association"("p_escrow_gl_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fail_email_delivery"("p_email_id" "uuid", "p_error" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_attempt integer; v_message_id uuid;
begin
  if auth.role() <> 'service_role' then raise exception 'Service role required'; end if;
  update public.email_queue
  set status = 'failed', processing_at = null,
      error_message = left(coalesce(nullif(trim(p_error), ''), 'Email provider error'), 2000),
      next_attempt_at = now() + case attempt_count
        when 1 then interval '1 minute'
        when 2 then interval '5 minutes'
        when 3 then interval '25 minutes'
        else interval '2 hours'
      end
  where id = p_email_id and status = 'pending' and processing_at is not null
  returning attempt_count, communication_message_id into v_attempt, v_message_id;
  if not found then return false; end if;

  if v_attempt >= 5 and v_message_id is not null then
    update public.communication_messages
    set status = 'failed', error_message = left(coalesce(nullif(trim(p_error), ''), 'Email provider error'), 2000), updated_at = now()
    where id = v_message_id;
  end if;
  return true;
end;
$$;


ALTER FUNCTION "public"."fail_email_delivery"("p_email_id" "uuid", "p_error" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fail_physical_mail"("p_id" "uuid", "p_error" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare current_attempts integer;
begin
  if coalesce(auth.role(), '') <> 'service_role' then raise exception 'Service role required'; end if;
  select attempt_count into current_attempts from public.physical_mail_deliveries where id = p_id for update;
  update public.physical_mail_deliveries
  set status = 'failed', locked_at = null, error_message = left(coalesce(p_error, 'Physical-mail submission failed'), 1000),
      next_attempt_at = now() + make_interval(secs => least(power(4, greatest(current_attempts, 1))::integer * 60, 43200))
  where id = p_id;
end;
$$;


ALTER FUNCTION "public"."fail_physical_mail"("p_id" "uuid", "p_error" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fail_sms_delivery"("p_message_id" "uuid", "p_error_code" "text", "p_error_message" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare current_attempts integer;
begin
  if coalesce(auth.role(), '') <> 'service_role' then raise exception 'Service role required'; end if;
  select attempt_count into current_attempts from public.sms_messages where id = p_message_id for update;
  update public.sms_messages
  set status = 'failed', locked_at = null,
      error_code = left(coalesce(p_error_code, 'provider_error'), 100),
      error_message = left(coalesce(p_error_message, 'SMS delivery failed'), 1000),
      next_attempt_at = now() + make_interval(secs => least(power(3, greatest(current_attempts, 1))::integer * 60, 21600))
  where id = p_message_id and direction = 'outbound';
end;
$$;


