CREATE OR REPLACE FUNCTION "public"."finalize_stripe_autopay_run"("p_run_id" "uuid", "p_processor_account_id" "text", "p_processor_payment_intent_id" "text", "p_payment_intent_id" "uuid", "p_outcome" "text", "p_failure_reason" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  v_run public.stripe_autopay_runs%rowtype;
  v_mandate public.autopay_mandates%rowtype;
  v_next_run date;
begin
  if p_processor_account_id !~ '^acct_[A-Za-z0-9]+$'
     or p_outcome not in ('succeeded', 'failed')
     or (p_outcome = 'succeeded' and p_processor_payment_intent_id !~ '^pi_[A-Za-z0-9]+$')
     or (p_outcome = 'failed' and p_processor_payment_intent_id is not null
         and p_processor_payment_intent_id !~ '^pi_[A-Za-z0-9]+$') then
    raise exception 'Invalid Stripe AutoPay finalization identity';
  end if;

  select * into v_run
  from public.stripe_autopay_runs
  where id = p_run_id
  for update;
  if not found then raise exception 'Stripe AutoPay run not found'; end if;

  if v_run.processor_account_id is distinct from p_processor_account_id
     or (v_run.processor_payment_intent_id is not null
         and v_run.processor_payment_intent_id is distinct from p_processor_payment_intent_id)
     or (v_run.payment_intent_id is not null
         and v_run.payment_intent_id is distinct from p_payment_intent_id) then
    raise exception 'Stripe AutoPay run belongs to a different processor object';
  end if;

  select * into v_mandate
  from public.autopay_mandates
  where id = v_run.mandate_id
  for update;
  if not found then raise exception 'AutoPay mandate not found'; end if;

  v_next_run := (
    date_trunc('month', v_run.scheduled_for::timestamp)
    + interval '1 month'
    + (least(28, greatest(1, coalesce(v_mandate.day_of_month, 1))) - 1) * interval '1 day'
  )::date;

  if p_outcome = 'succeeded' then
    if v_run.status = 'succeeded' then return false; end if;
    if v_run.status = 'skipped' then
      raise exception 'A skipped AutoPay run cannot settle';
    end if;

    update public.stripe_autopay_runs
    set status = 'succeeded',
        processor_payment_intent_id = p_processor_payment_intent_id,
        payment_intent_id = p_payment_intent_id,
        failure_reason = null,
        completed_at = now(),
        updated_at = now()
    where id = v_run.id;

    update public.autopay_mandates
    set next_run_date = case when next_run_date = v_run.scheduled_for then v_next_run else next_run_date end,
        last_run_at = now(),
        success_count = coalesce(success_count, 0) + 1,
        failure_count = case
          when v_run.status = 'failed' then greatest(coalesce(failure_count, 0) - 1, 0)
          else coalesce(failure_count, 0)
        end,
        last_failure_reason = case when v_run.status = 'failed' then null else last_failure_reason end,
        updated_at = now()
    where id = v_mandate.id;
    return true;
  end if;

  if v_run.status in ('failed', 'succeeded') then return false; end if;
  if v_run.status = 'skipped' then
    raise exception 'A skipped AutoPay run cannot fail at Stripe';
  end if;

  update public.stripe_autopay_runs
  set status = 'failed',
      processor_payment_intent_id = coalesce(p_processor_payment_intent_id, processor_payment_intent_id),
      payment_intent_id = p_payment_intent_id,
      failure_reason = left(coalesce(p_failure_reason, 'Stripe payment failed'), 500),
      completed_at = now(),
      updated_at = now()
  where id = v_run.id;

  update public.autopay_mandates
  set next_run_date = case when next_run_date = v_run.scheduled_for then v_next_run else next_run_date end,
      last_run_at = now(),
      failure_count = coalesce(failure_count, 0) + 1,
      last_failure_at = now(),
      last_failure_reason = left(coalesce(p_failure_reason, 'Stripe payment failed'), 500),
      updated_at = now()
  where id = v_mandate.id;
  return true;
end;
$_$;


ALTER FUNCTION "public"."finalize_stripe_autopay_run"("p_run_id" "uuid", "p_processor_account_id" "text", "p_processor_payment_intent_id" "text", "p_payment_intent_id" "uuid", "p_outcome" "text", "p_failure_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_year_end_package"("p_package_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare pkg public.year_end_packages; v_readiness jsonb; v_current jsonb;
begin
  select * into pkg from public.year_end_packages where id = p_package_id for update;
  if not found then raise exception 'Package not found'; end if;
  if not (public.can_manage_finance(pkg.portfolio_id) or public.can_admin_portfolio(pkg.portfolio_id) or public.is_platform_operator()) then
    raise exception 'Only finance staff can finalize year-end packages' using errcode = '42501';
  end if;
  if not public.can_view_association_row(pkg.association_id) then raise exception 'Package not found'; end if;
  if pkg.status <> 'draft' then raise exception 'Only a draft package can be finalized'; end if;
  perform 1 from public.accounting_periods where portfolio_id = pkg.portfolio_id for share;
  v_readiness := public.year_end_readiness(pkg.association_id, pkg.fiscal_year);
  if not (v_readiness ->> 'ready')::boolean then
    raise exception 'Year-end checks are not complete: %',
      (select string_agg(i ->> 'label', '; ') from jsonb_array_elements(v_readiness -> 'items') i where (i ->> 'required')::boolean and not (i ->> 'ok')::boolean);
  end if;
  v_current := public.build_year_end_snapshot(pkg.association_id, pkg.fiscal_year);
  if encode(sha256(convert_to(v_current::text, 'UTF8')), 'hex') <> pkg.snapshot_sha256 then
    raise exception 'The books changed after this draft was prepared. Regenerate the package, review it, then finalize.';
  end if;
  update public.year_end_packages set status = 'finalized', finalized_by = auth.uid(), finalized_at = now(), checklist = v_readiness -> 'items' where id = p_package_id;
  insert into public.audit_logs (portfolio_id, entity_type, entity_id, action, actor_id, changes)
  values (pkg.portfolio_id, 'association', pkg.association_id, 'year_end_package_finalized', auth.uid(),
          jsonb_build_object('package_id', pkg.id, 'fiscal_year', pkg.fiscal_year, 'sha256', pkg.snapshot_sha256));
end;
$$;


ALTER FUNCTION "public"."finalize_year_end_package"("p_package_id" "uuid") OWNER TO "postgres";


