CREATE OR REPLACE FUNCTION "public"."generate_monthly_statements"("p_year" integer DEFAULT (EXTRACT(year FROM ("now"() - '1 mon'::interval)))::integer, "p_month" integer DEFAULT (EXTRACT(month FROM ("now"() - '1 mon'::interval)))::integer) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  n_statements integer := 0;
  row record;
  period_start date;
  period_end date;
begin
  period_start := make_date(p_year, p_month, 1);
  period_end := (period_start + interval '1 month')::date;  -- exclusive

  -- ownership_fixes: one owner per unit whose ownership overlaps the month
  -- (the primary one when several do; a seller is no longer primary), instead
  -- of whoever is current and primary when the job runs.
  for row in
    select u.id as unit_id, b.association_id, occ.owner_id,
           -- opening balance: charges - payments before period_start
           coalesce((select sum(amount) from public.charges
                     where unit_id = u.id and due_date < period_start), 0)
           -
           coalesce((select sum(amount) from public.payments
                     where unit_id = u.id and payment_date < period_start), 0)
             as opening_balance,
           coalesce((select sum(amount) from public.charges
                     where unit_id = u.id and due_date >= period_start and due_date < period_end), 0)
             as total_charges,
           coalesce((select sum(amount) from public.payments
                     where unit_id = u.id and payment_date >= period_start and payment_date < period_end), 0)
             as total_payments
      from public.units u
      join public.buildings b on b.id = u.building_id
      join lateral (
        select o.owner_id
          from public.occupancies o
         where o.unit_id = u.id
           and o.occupancy_type = 'owner'
           and o.owner_id is not null
           and (o.move_in_date is null or o.move_in_date < period_end)
           and ((o.status = 'current'
                 and (o.move_out_date is null or o.move_out_date > period_start))
                or (o.status = 'past'
                    and o.move_out_date is not null and o.move_out_date > period_start))
         order by o.is_primary desc, (o.status = 'current') desc,
                  o.move_in_date desc nulls last, o.id
         limit 1
      ) occ on true
     where u.archived_at is null
  loop
    insert into public.statements (
      owner_id, unit_id, association_id, period_month, period_year,
      opening_balance, total_charges, total_payments, closing_balance
    ) values (
      row.owner_id, row.unit_id, row.association_id, p_month, p_year,
      row.opening_balance, row.total_charges, row.total_payments,
      row.opening_balance + row.total_charges - row.total_payments
    )
    on conflict do nothing;

    if found then n_statements := n_statements + 1; end if;
  end loop;

  return n_statements;
end;
$$;


ALTER FUNCTION "public"."generate_monthly_statements"("p_year" integer, "p_month" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_owner_payable_number"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_year text;
  v_seq int;
BEGIN
  v_year := to_char(CURRENT_DATE, 'YYYY');
  SELECT COALESCE(MAX(NULLIF(regexp_replace(payable_number, '^OP-\d{4}-', ''), '')::int), 0) + 1
    INTO v_seq
    FROM owner_payables
    WHERE payable_number LIKE 'OP-' || v_year || '-%';
  NEW.payable_number := 'OP-' || v_year || '-' || lpad(v_seq::text, 4, '0');
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."generate_owner_payable_number"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_owner_statements"("p_association_id" "uuid", "p_period_start" "date", "p_period_end" "date", "p_delivery_channel" "text" DEFAULT 'email'::"text", "p_batch_name" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_batch_id uuid;
  v_portfolio uuid;
  v_owner record;
  v_charged numeric;
  v_charged_before numeric;
  v_paid numeric;
  v_balance numeric;
  v_past_due numeric;
begin
  select a.portfolio_id into v_portfolio from public.associations a
   where a.id = p_association_id and a.archived_at is null;
  if v_portfolio is null or not public.can_manage_finance(v_portfolio) then
    raise exception 'Permission denied' using errcode = '42501';
  end if;
  if not public.can_view_association_row(p_association_id) then
    raise exception 'Permission denied' using errcode = '42501';
  end if;
  if p_period_start is null or p_period_end is null or p_period_end < p_period_start then
    raise exception 'Enter a valid statement period' using errcode = '22023';
  end if;

  insert into public.statement_batches (
    association_id, batch_name, period_start, period_end, delivery_channel, status, created_by
  ) values (
    p_association_id,
    left(coalesce(nullif(btrim(p_batch_name), ''), 'Statement batch ' || to_char(p_period_end, 'Mon YYYY')), 200),
    p_period_start, p_period_end, p_delivery_channel, 'generating', auth.uid()
  ) returning id into v_batch_id;

  -- ownership_fixes: the owners whose ownership overlaps the period (moved in
  -- by its last day, not moved out before its first), one statement per owner
  -- and unit, instead of whoever is current when the batch runs.
  for v_owner in
    select distinct on (occ.owner_id, occ.unit_id)
           o.id as owner_id, occ.unit_id, occ.id as occupancy_id,
           -- An owner who left during the period is stated as of their last
           -- day (the move-out day is the next owner's first), so the
           -- seller's statement leaves out the buyer's charges and payments.
           case when occ.move_out_date is not null and occ.move_out_date <= p_period_end
                then occ.move_out_date - 1 else p_period_end end as cutoff
      from public.occupancies occ
      join public.owners o on o.id = occ.owner_id
     where occ.association_id = p_association_id
       and occ.occupancy_type = 'owner'
       and o.archived_at is null
       and (occ.move_in_date is null or occ.move_in_date <= p_period_end)
       and ((occ.status = 'current'
             and (occ.move_out_date is null or occ.move_out_date > p_period_start))
            or (occ.status = 'past'
                and occ.move_out_date is not null and occ.move_out_date > p_period_start))
     order by occ.owner_id, occ.unit_id, (occ.status = 'current') desc,
              occ.move_in_date desc nulls last, occ.id
  loop
    select coalesce(sum(case when c.due_date <= v_owner.cutoff then c.amount else 0 end), 0),
           coalesce(sum(case when c.due_date < p_period_start then c.amount else 0 end), 0)
      into v_charged, v_charged_before
      from public.charges c
     where c.unit_id = v_owner.unit_id;

    select coalesce(sum(p.amount), 0) into v_paid
      from public.payments p
     where p.unit_id = v_owner.unit_id
       and p.payment_date <= v_owner.cutoff;

    v_balance := v_charged - v_paid;
    v_past_due := greatest(v_charged_before - v_paid, 0);

    insert into public.owner_statements (
      batch_id, association_id, owner_id, unit_id, occupancy_id, period_start, period_end,
      delivery_channel, delivery_status, amount_due, amount_past_due, amount_prepaid, total_due, created_by
    ) values (
      v_batch_id, p_association_id, v_owner.owner_id, v_owner.unit_id, v_owner.occupancy_id,
      p_period_start, p_period_end, p_delivery_channel, 'pending',
      greatest(greatest(v_balance, 0) - v_past_due, 0), v_past_due, greatest(-v_balance, 0),
      greatest(v_balance, 0), auth.uid()
    );
  end loop;

  update public.statement_batches
     set total_owners = (select count(*) from public.owner_statements where batch_id = v_batch_id),
         generated_count = (select count(*) from public.owner_statements where batch_id = v_batch_id),
         status = 'generated',
         updated_at = now()
   where id = v_batch_id;

  return v_batch_id;
end;
$$;


ALTER FUNCTION "public"."generate_owner_statements"("p_association_id" "uuid", "p_period_start" "date", "p_period_end" "date", "p_delivery_channel" "text", "p_batch_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_portfolio_slug"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_base text;
  v_candidate text;
  v_suffix text;
  v_counter integer := 1;
begin
  if new.slug is not null and btrim(new.slug) <> '' then
    return new;
  end if;

  v_base := lower(regexp_replace(coalesce(new.company_name, ''), '[^a-zA-Z0-9]+', '-', 'g'));
  v_base := trim(both '-' from v_base);
  v_base := rtrim(left(v_base, 32), '-');
  if v_base = '' then v_base := 'company'; end if;

  if public.reserved_portfolio_slug(v_base) then
    v_base := rtrim(left('company-' || v_base, 32), '-');
  end if;

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('portfolio_slug_assignment', 0));

  v_candidate := v_base;
  while exists (select 1 from public.portfolios p where p.slug = v_candidate)
     or exists (select 1 from public.portfolio_slug_aliases a where a.slug = v_candidate) loop
    v_counter := v_counter + 1;
    v_suffix := '-' || v_counter::text;
    v_candidate := rtrim(left(v_base, 32 - char_length(v_suffix)), '-') || v_suffix;
  end loop;

  new.slug := v_candidate;
  return new;
end;
$$;


ALTER FUNCTION "public"."generate_portfolio_slug"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_recurring_bills"() RETURNS integer
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select public.generate_recurring_bills_through(null, current_date, false);
$$;


ALTER FUNCTION "public"."generate_recurring_bills"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_recurring_bills_through"("p_portfolio_id" "uuid", "p_through" "date", "p_scoped" boolean) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  t record;
  v_date date;
  v_guard integer;
  n integer := 0;
  v_mode text;
  v_threshold numeric;
  v_needs_board boolean;
  v_bill uuid;
begin
  for t in
    select * from public.recurring_bills
     where auto_generate and archived_at is null and next_post_date is not null
       and next_post_date <= p_through
       and (end_date is null or next_post_date <= end_date)
       and (p_portfolio_id is null or portfolio_id = p_portfolio_id)
       -- A manager limited to some associations posts only those.
       and (not p_scoped or public.can_access_association(association_id))
     for update skip locked
  loop
    begin
      v_date := t.next_post_date;
      v_guard := 0;
      v_mode := null;
      v_threshold := null;
      select s.sends_bills_to_board, s.bills_threshold into v_mode, v_threshold
        from public.board_approval_settings s where s.association_id = t.association_id;
      v_needs_board := coalesce(t.association_id is not null and (coalesce(v_mode, 'never') = 'always'
                       or (v_mode = 'over_threshold' and t.amount >= coalesce(v_threshold, 0))), false);

      while v_date <= p_through and (t.end_date is null or v_date <= t.end_date) and v_guard < 400 loop
        v_bill := null;
        insert into public.payable_bills (
          portfolio_id, vendor_id, association_id, gl_account_id, bank_account_id,
          bill_date, due_date, amount, memo, status, approval_required, approved_at,
          created_by, recurring_bill_id)
        values (
          t.portfolio_id, t.vendor_id, t.association_id, t.gl_account_id, t.bank_account_id,
          v_date, v_date + t.due_days, t.amount,
          coalesce(nullif(btrim(t.memo), ''), t.name) || ' — ' || to_char(v_date, 'Mon YYYY'),
          case when v_needs_board then 'draft' else 'approved' end::public.payable_bill_status,
          v_needs_board,
          case when v_needs_board then null else now() end,
          t.created_by, t.id)
        on conflict (recurring_bill_id, bill_date) where recurring_bill_id is not null do nothing
        returning id into v_bill;
        if v_bill is not null then
          n := n + 1;
          if not v_needs_board then perform public.ensure_payable_bill_accrual(v_bill); end if;
        end if;
        v_date := public.recurring_next_date(v_date, t.frequency::text, t.interval_count, extract(day from coalesce(t.start_date, t.next_post_date))::integer);
        v_guard := v_guard + 1;
      end loop;

      update public.recurring_bills
         set next_post_date = v_date, last_generated_at = now(), last_error = null, updated_at = now(), auto_generate = (t.end_date is null or v_date <= t.end_date)
       where id = t.id;
    exception when others then
      update public.recurring_bills set last_error = left(sqlerrm, 500), updated_at = now() where id = t.id;
    end;
  end loop;
  return n;
end $$;


ALTER FUNCTION "public"."generate_recurring_bills_through"("p_portfolio_id" "uuid", "p_through" "date", "p_scoped" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_recurring_journal_entries"() RETURNS integer
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select public.generate_recurring_journal_entries_through(null, current_date, false);
$$;


ALTER FUNCTION "public"."generate_recurring_journal_entries"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_recurring_journal_entries_through"("p_portfolio_id" "uuid", "p_through" "date", "p_scoped" boolean) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  t record;
  v_entry uuid;
  v_lines jsonb;
  v_date date;
  v_guard int;
  n integer := 0;
begin
  for t in
    select * from public.recurring_journal_entries
     where auto_generate and archived_at is null and next_post_date is not null and next_post_date <= p_through
       and (end_date is null or next_post_date <= end_date)
       and (p_portfolio_id is null or portfolio_id = p_portfolio_id)
     for update skip locked
  loop
    begin
      v_lines := public.app_normalize_je_lines(t.portfolio_id, t.template_lines, p_scoped);
      v_date := t.next_post_date;
      v_guard := 0;
      while v_date <= p_through and (t.end_date is null or v_date <= t.end_date) and v_guard < 400 loop
        if not exists (select 1 from public.journal_entries je
                        where je.source_type = 'recurring_je' and je.source_id = t.id and je.portfolio_id = t.portfolio_id
                          and je.entry_date = v_date and je.posted and je.reversed_by_entry_id is null) then
          insert into public.journal_entries (portfolio_id, entry_date, description, memo, source_type, source_id, created_by, posted)
          values (t.portfolio_id, v_date, left(t.name, 500), coalesce(nullif(btrim(t.memo), ''), t.name) || ' (recurring)',
                  'recurring_je', t.id, t.created_by, false)
          returning id into v_entry;
          insert into public.journal_lines (entry_id, gl_account_id, association_id, debit_amount, credit_amount, memo, sort_order)
          select v_entry, (l->>'gl_account_id')::uuid, (l->>'association_id')::uuid, (l->>'debit')::numeric, (l->>'credit')::numeric,
                 l->>'memo', (ord - 1)::int
            from jsonb_array_elements(v_lines) with ordinality as x(l, ord);
          update public.journal_entries set posted = true, posted_at = now() where id = v_entry;
          n := n + 1;
        end if;
        v_date := public.recurring_next_date(v_date, t.frequency::text, t.interval_count);
        v_guard := v_guard + 1;
      end loop;
      update public.recurring_journal_entries
         set next_post_date = v_date, last_generated_at = now(), last_error = null, updated_at = now(),
             auto_generate = (t.end_date is null or v_date <= t.end_date)
       where id = t.id;
    exception when others then
      update public.recurring_journal_entries set last_error = left(sqlerrm, 500), updated_at = now() where id = t.id;
    end;
  end loop;
  return n;
end $$;


ALTER FUNCTION "public"."generate_recurring_journal_entries_through"("p_portfolio_id" "uuid", "p_through" "date", "p_scoped" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_recurring_purchase_orders"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  t record;
  v_today date;
  v_date date;
  v_next date;
  v_guard integer;
  n integer := 0;
begin
  for t in
    select * from public.recurring_purchase_orders r
     where r.auto_generate and r.archived_at is null and r.next_post_date is not null
       -- po_decisions: the association's own day, not the database's.
       and r.next_post_date <= coalesce(public.association_local_date(r.association_id), current_date)
       and (r.end_date is null or r.next_post_date <= r.end_date)
  loop
    begin
      v_today := coalesce(public.association_local_date(t.association_id), current_date);
      v_date := t.next_post_date;
      -- po_decisions: a schedule that fell behind (first date in the past,
      -- a missed run, or resumed late) skips the older missed periods
      -- without creating them and creates the current one: the latest
      -- scheduled date on or before today. (A schedule whose next date is
      -- still in the future isn't selected above, so nothing is created
      -- until it's due.)
      v_guard := 0;
      loop
        v_next := public.recurring_next_date(v_date, t.frequency::text, t.interval_count, extract(day from coalesce(t.start_date, t.next_post_date))::integer);
        exit when v_next is null or v_next <= v_date or v_next > v_today or v_guard >= 10000;
        v_date := v_next;
        v_guard := v_guard + 1;
      end loop;
      if t.end_date is null or v_date <= t.end_date then
        if public.app_po_from_recurring(t.id, v_date) is not null then n := n + 1; end if;
        v_date := public.recurring_next_date(v_date, t.frequency::text, t.interval_count, extract(day from coalesce(t.start_date, t.next_post_date))::integer);
      end if;
      update public.recurring_purchase_orders
         set next_post_date = v_date, last_generated_at = now(), last_error = null, updated_at = now(),
             auto_generate = (t.end_date is null or v_date <= t.end_date)
       where id = t.id;
    exception when others then
      update public.recurring_purchase_orders set last_error = left(sqlerrm, 500), updated_at = now() where id = t.id;
    end;
  end loop;
  return n;
end $$;


ALTER FUNCTION "public"."generate_recurring_purchase_orders"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_recurring_work_order_now"("p_id" "uuid", "p_expected_due" "date", "p_next" "date", "p_scheduled" "date") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  tpl public.recurring_work_orders%rowtype;
  wo_id uuid;
begin
  update public.recurring_work_orders
     set last_generated_at = now(), next_due_date = p_next
   where id = p_id
     and archived_at is null
     and next_due_date is not distinct from p_expected_due
  returning * into tpl;
  if not found then
    return null;
  end if;

  insert into public.work_orders (
    portfolio_id, association_id, unit_id, vendor_id, title, description,
    category, priority, trade, scheduled_date, status, created_by
  ) values (
    tpl.portfolio_id, tpl.association_id, tpl.unit_id, tpl.vendor_id, tpl.title, tpl.description,
    coalesce(tpl.category::text, 'other')::public.work_order_category,
    coalesce(tpl.priority::text, 'normal')::public.work_order_priority,
    tpl.trade::text::public.vendor_trade,
    p_scheduled,
    (case when tpl.vendor_id is not null then 'assigned' else 'new' end)::public.work_order_status,
    auth.uid()
  ) returning id into wo_id;

  return wo_id;
end;
$$;


ALTER FUNCTION "public"."generate_recurring_work_order_now"("p_id" "uuid", "p_expected_due" "date", "p_next" "date", "p_scheduled" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_recurring_work_orders"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  row record;
  new_sr_id uuid;
  next_due date;
  n_generated integer := 0;
begin
  for row in
    select *
      from public.recurring_work_orders
     where auto_generate
       and archived_at is null
       and next_due_date <= current_date
       and (end_date is null or next_due_date <= end_date)
  loop
   begin
    next_due := public.recurring_next_date(row.next_due_date, row.frequency::text, coalesce(row.interval_count, 1), extract(day from coalesce(row.start_date, row.next_due_date))::integer);

    update public.recurring_work_orders
       set next_due_date = next_due,
           last_generated_at = now(),
           updated_at = now()
     where id = row.id
       and archived_at is null
       and next_due_date = row.next_due_date;
    if not found then
      continue;
    end if;

    insert into public.service_requests (
      portfolio_id, association_id, unit_id,
      description, priority, source, created_by
    ) values (
      row.portfolio_id, row.association_id, row.unit_id,
      coalesce(nullif(row.description, ''), row.title) || E'\n(auto-generated from recurring work order)',
      coalesce(row.priority::text, 'normal')::public.service_request_priority,
      'recurring', row.created_by
    ) returning id into new_sr_id;

    insert into public.work_orders (
      service_request_id, portfolio_id, unit_id, association_id,
      title, description, category, priority, vendor_id,
      trade, created_by, scheduled_date, status
    ) values (
      new_sr_id, row.portfolio_id, row.unit_id, row.association_id,
      row.title, row.description, coalesce(row.category, 'other'::public.work_order_category), row.priority, row.vendor_id,
      row.trade, row.created_by, row.next_due_date,
      case when row.vendor_id is not null then 'assigned' else 'new' end::public.work_order_status
    );

    n_generated := n_generated + 1;
   exception when others then
    raise warning 'generate_recurring_work_orders: template % skipped: %', row.id, sqlerrm;
   end;
  end loop;

  return n_generated;
end;
$$;


ALTER FUNCTION "public"."generate_recurring_work_orders"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_year_end_package"("p_association_id" "uuid", "p_fiscal_year" integer, "p_notes" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_portfolio uuid; v_readiness jsonb; v_snapshot jsonb; v_id uuid;
begin
  select portfolio_id into v_portfolio from public.associations where id = p_association_id and archived_at is null;
  if v_portfolio is null then raise exception 'Association not found'; end if;
  if not (public.can_manage_finance(v_portfolio) or public.can_admin_portfolio(v_portfolio) or public.is_platform_operator())
     or not public.can_view_association_row(p_association_id) then
    raise exception 'Only finance staff can prepare year-end packages' using errcode = '42501';
  end if;
  if p_fiscal_year not between 2000 and extract(year from current_date)::integer + 1 then raise exception 'Invalid fiscal year'; end if;
  if exists (select 1 from public.year_end_packages where association_id = p_association_id and fiscal_year = p_fiscal_year and status = 'finalized') then
    raise exception 'This fiscal year is already finalized. Supersede it to prepare a revision.';
  end if;
  v_readiness := public.year_end_readiness(p_association_id, p_fiscal_year);
  v_snapshot := public.build_year_end_snapshot(p_association_id, p_fiscal_year);
  delete from public.year_end_packages where association_id = p_association_id and fiscal_year = p_fiscal_year and status = 'draft';
  insert into public.year_end_packages (portfolio_id, association_id, fiscal_year, period_start, period_end, checklist, snapshot, snapshot_sha256, notes, generated_by)
  values (v_portfolio, p_association_id, p_fiscal_year, (v_readiness ->> 'period_start')::date, (v_readiness ->> 'period_end')::date,
          v_readiness -> 'items', v_snapshot, encode(sha256(convert_to(v_snapshot::text, 'UTF8')), 'hex'), nullif(btrim(coalesce(p_notes, '')), ''), auth.uid())
  returning id into v_id;
  insert into public.audit_logs (portfolio_id, entity_type, entity_id, action, actor_id, changes)
  values (v_portfolio, 'association', p_association_id, 'year_end_package_generated', auth.uid(), jsonb_build_object('package_id', v_id, 'fiscal_year', p_fiscal_year));
  return v_id;
end;
$$;


ALTER FUNCTION "public"."generate_year_end_package"("p_association_id" "uuid", "p_fiscal_year" integer, "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_budget_vs_actuals"("p_association_id" "uuid", "p_fiscal_year" integer) RETURNS TABLE("budget_line_id" "uuid", "gl_account_id" "uuid", "gl_account_number" integer, "gl_account_name" "text", "category" "text", "notes" "text", "monthly_budget" numeric[], "monthly_actuals" numeric[], "monthly_variance" numeric[], "annual_budget" numeric, "annual_actual" numeric, "annual_variance" numeric, "annual_variance_pct" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare w record;
begin
  if p_association_id is null or p_fiscal_year is null or p_fiscal_year not between 1900 and 2200 then
    raise exception 'Invalid budget scope' using errcode = '22023';
  end if;
  if not public.can_read_association_budget(p_association_id) then
    raise exception 'Not authorized for this association budget' using errcode = '42501';
  end if;
  select * into w from public.association_fiscal_window(p_association_id, p_fiscal_year);

  return query
  with act as (
    select s.gid, public.fiscal_month_index(w.period_start, s.mon) as idx,
           public.gl_normal_amount(s.account_type, s.d, s.c) as amt
      from (select jl.gl_account_id as gid, ga.account_type::text as account_type,
                   date_trunc('month', je.entry_date)::date as mon,
                   sum(jl.debit_amount) as d, sum(jl.credit_amount) as c
              from public.journal_lines jl
              join public.journal_entries je on je.id = jl.entry_id and je.posted
              join public.gl_accounts ga on ga.id = jl.gl_account_id
             where jl.association_id = p_association_id and je.entry_date between w.period_start and w.period_end
             group by 1, 2, 3) s
  ), budgeted as (
    select bl.id, bl.gl_account_id, ga.number as gl_number, ga.name as gl_name, bl.category::text as category,
           bl.notes, bl.monthly_amounts::numeric[] as monthly_amounts
      from public.budget_lines bl
      join public.gl_accounts ga on ga.id = bl.gl_account_id
      join public.associations a on a.id = bl.association_id
     where bl.association_id = p_association_id and bl.fiscal_year = p_fiscal_year
       and ga.portfolio_id = a.portfolio_id and (ga.association_id is null or ga.association_id = bl.association_id)
  ), unbudgeted as (
    select null::uuid as id, ga.id as gl_account_id, ga.number as gl_number, ga.name as gl_name,
           public.gl_section(ga.account_type::text) as category, null::text as notes,
           array_fill(0::numeric, array[12]) as monthly_amounts
      from public.gl_accounts ga
     where ga.id in (select act.gid from act group by act.gid having bool_or(act.amt <> 0))
       and public.gl_section(ga.account_type::text) in ('income', 'expense')
       and not exists (select 1 from budgeted b where b.gl_account_id = ga.id)
  ), lines as (
    select x.*,
           (select array_agg(coalesce(a.amt, 0) order by g.i) from generate_series(1, 12) g(i)
              left join act a on a.gid = x.gl_account_id and a.idx = g.i) as actuals
      from (select * from budgeted union all select * from unbudgeted) x
  )
  select l.id, l.gl_account_id, l.gl_number, l.gl_name, l.category, l.notes,
         l.monthly_amounts, l.actuals,
         (select array_agg(l.actuals[i] - coalesce(l.monthly_amounts[i], 0) order by i) from generate_series(1, 12) i),
         (select sum(x) from unnest(l.monthly_amounts) x),
         (select sum(x) from unnest(l.actuals) x),
         (select sum(x) from unnest(l.actuals) x) - (select sum(x) from unnest(l.monthly_amounts) x),
         case when (select sum(x) from unnest(l.monthly_amounts) x) <> 0
              then round(((select sum(x) from unnest(l.actuals) x) - (select sum(x) from unnest(l.monthly_amounts) x))
                         / (select sum(x) from unnest(l.monthly_amounts) x) * 100, 1)
              else 0 end
    from lines l
   order by l.gl_number;
end $$;


ALTER FUNCTION "public"."get_budget_vs_actuals"("p_association_id" "uuid", "p_fiscal_year" integer) OWNER TO "postgres";


