CREATE OR REPLACE FUNCTION "public"."gl_account_in_use"("p_gl_account_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  r record;
  v_found boolean;
  v_portfolio uuid;
begin
  select portfolio_id into v_portfolio from public.gl_accounts where id = p_gl_account_id;
  if v_portfolio is null or not public.can_manage_finance(v_portfolio) then
    raise exception 'GL account not found';
  end if;
  for r in
    select c.conrelid::regclass as tbl, a.attname as col
      from pg_constraint c
      join pg_attribute a on a.attrelid = c.conrelid and a.attnum = c.conkey[1]
     where c.contype = 'f'
       and c.confrelid = 'public.gl_accounts'::regclass
       and array_length(c.conkey, 1) = 1
       and c.conrelid <> 'public.gl_accounts'::regclass
  loop
    execute format('select exists (select 1 from %s where %I = $1)', r.tbl, r.col)
      into v_found using p_gl_account_id;
    if v_found then
      return true;
    end if;
  end loop;
  return exists (select 1 from public.gl_accounts where sub_account_of_id = p_gl_account_id);
end $_$;


ALTER FUNCTION "public"."gl_account_in_use"("p_gl_account_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."gl_account_vendor_default_scope"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if exists (select 1 from public.vendors v
              where v.default_gl_account_id = new.id
                and (v.portfolio_id is distinct from new.portfolio_id
                     or (new.association_id is not null and new.association_id is distinct from v.association_id))) then
    raise exception 'This account is a vendor''s default account. Change that vendor''s default first.'
      using errcode = '23514';
  end if;
  return new;
end;
$$;


