CREATE OR REPLACE FUNCTION "public"."guard_adopted_budget_lines"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare r record;
begin
  for r in select * from (values (case when tg_op <> 'INSERT' then old.association_id end, case when tg_op <> 'INSERT' then old.fiscal_year end),
                                 (case when tg_op <> 'DELETE' then new.association_id end, case when tg_op <> 'DELETE' then new.fiscal_year end)) v(aid, fy)
           where v.aid is not null loop
    if exists (select 1 from public.association_budgets b where b.association_id = r.aid and b.fiscal_year = r.fy and b.status = 'adopted') then
      raise exception 'The FY% budget is adopted. Reopen it before changing lines.', r.fy using errcode = '55000';
    end if;
  end loop;
  return coalesce(new, old);
end $$;


ALTER FUNCTION "public"."guard_adopted_budget_lines"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_amenity_overlap"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if new.status <> 'approved' or new.start_time is null or new.end_time is null then
    return new;
  end if;
  if new.end_time <= new.start_time then
    raise exception 'A reservation must end after it starts' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('amenity-booking:' || new.amenity_id::text, 0));
  if exists (
    select 1 from public.amenity_reservations r
     where r.amenity_id = new.amenity_id
       and r.id <> new.id
       and r.status = 'approved'
       and r.start_time < new.end_time
       and r.end_time > new.start_time
  ) then
    raise exception 'That time overlaps another approved reservation for this amenity' using errcode = '23P01';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."guard_amenity_overlap"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_capital_project_governance"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if ((tg_op = 'INSERT' and (new.board_approved_at is not null or new.board_approved_by is not null or new.approved_budget_amount is not null))
      or (tg_op = 'UPDATE' and (new.board_approved_at, new.board_approved_by, new.approved_budget_amount)
       is distinct from
     (old.board_approved_at, old.board_approved_by, old.approved_budget_amount)))
     and not (public.can_admin_portfolio(new.portfolio_id) or public.is_platform_operator()) then
    raise exception 'portfolio administrator approval is required to change project governance fields';
  end if;
  if new.board_approved_at is not null and new.board_approved_by is null then
    raise exception 'board approval must identify the administrator who recorded it';
  end if;
  if tg_op = 'UPDATE'
     and old.board_approval_required
     and not new.board_approval_required
     and not (public.can_admin_portfolio(new.portfolio_id) or public.is_platform_operator()) then
    raise exception 'portfolio administrator approval is required to remove the board-approval requirement';
  end if;
  if new.board_approval_required
     and new.status in ('active', 'completed')
     and new.board_approved_at is null then
    raise exception 'board approval is required before project activation';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."guard_capital_project_governance"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_closed_period_on_je"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  -- Posting into a closed month.
  if tg_op in ('INSERT', 'UPDATE') and new.posted = true
     and (tg_op = 'INSERT' or old.posted is distinct from true or new.entry_date is distinct from old.entry_date
          or new.portfolio_id is distinct from old.portfolio_id)
     and public.app_period_closed(new.portfolio_id, new.entry_date) then
    raise exception 'cannot post journal entry to closed period %/%',
      extract(year from new.entry_date)::int, extract(month from new.entry_date)::int;
  end if;
  -- Changing or removing an entry already posted in a closed month.
  if tg_op in ('UPDATE', 'DELETE') and old.posted = true and public.app_period_closed(old.portfolio_id, old.entry_date)
     and (tg_op = 'DELETE' or new.posted is distinct from old.posted or new.entry_date is distinct from old.entry_date
          or new.portfolio_id is distinct from old.portfolio_id) then
    raise exception 'cannot change a journal entry in closed period %/%',
      extract(year from old.entry_date)::int, extract(month from old.entry_date)::int;
  end if;
  return coalesce(new, old);
end;
$$;


ALTER FUNCTION "public"."guard_closed_period_on_je"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_closed_period_on_lines"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare e record;
begin
  for e in
    select je.portfolio_id, je.entry_date from public.journal_entries je
     where je.posted and je.id in (case when tg_op <> 'INSERT' then old.entry_id end, case when tg_op <> 'DELETE' then new.entry_id end)
  loop
    if public.app_period_closed(e.portfolio_id, e.entry_date) then
      raise exception 'cannot change journal lines in closed period %/%',
        extract(year from e.entry_date)::int, extract(month from e.entry_date)::int;
    end if;
  end loop;
  return coalesce(new, old);
end;
$$;


ALTER FUNCTION "public"."guard_closed_period_on_lines"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_cross_fund_transfer"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  from_fund text;
  to_fund text;
begin
  select fund_type into from_fund from public.bank_accounts where id = new.from_bank_account_id;
  select fund_type into to_fund from public.bank_accounts where id = new.to_bank_account_id;
  if from_fund is distinct from to_fund and new.authorized_by is null then
    raise exception 'Transfers between % and % funds require explicit authorization (set authorized_by with an authorization note).', from_fund, to_fund;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."guard_cross_fund_transfer"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_delinquency_legal_transition"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare blockers text[];
begin
  if new.status = 'legal_review' and old.status is distinct from 'legal_review' then
    blockers := public.delinquency_referral_blockers(new.id);
    if coalesce(cardinality(blockers), 0) > 0 then raise exception 'Not ready for legal review. Still required: %', array_to_string(blockers, '; '); end if;
  end if;
  if new.status = 'approved_for_counsel' and old.status is distinct from 'approved_for_counsel' then
    if old.status <> 'legal_review' or not (public.can_admin_portfolio(new.portfolio_id) or public.is_platform_operator())
       or new.legal_reviewed_by is distinct from auth.uid() or char_length(btrim(coalesce(new.legal_review_note, ''))) < 20 then
      raise exception 'A documented human portfolio-admin legal review is required';
    end if;
    blockers := public.delinquency_referral_blockers(new.id);
    if coalesce(cardinality(blockers), 0) > 0 then raise exception 'Referral protections are no longer satisfied: %', array_to_string(blockers, '; '); end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."guard_delinquency_legal_transition"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_deposit_receipt_not_feed_matched"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if new.bank_deposit_id is null or new.bank_deposit_id is not distinct from old.bank_deposit_id then
    return new;
  end if;
  if exists (select 1
               from public.bank_transactions bt
               join public.journal_lines jl on jl.id = bt.matched_journal_line_id
               join public.journal_entries je on je.id = jl.entry_id
              where je.source_type = tg_argv[0] and je.source_id = new.id) then
    raise exception 'A selected receipt is already matched to a bank transaction on its own, so it can''t be part of a deposit.' using errcode = '22023';
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."guard_deposit_receipt_not_feed_matched"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_feed_line_not_deposited"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_type text; v_src uuid; v_deposit uuid;
begin
  if new.matched_journal_line_id is null
     or (tg_op = 'UPDATE' and new.matched_journal_line_id is not distinct from old.matched_journal_line_id) then
    return new;
  end if;
  select je.source_type, je.source_id into v_type, v_src
    from public.journal_lines jl join public.journal_entries je on je.id = jl.entry_id
   where jl.id = new.matched_journal_line_id;
  if v_type = 'payment' then
    select bank_deposit_id into v_deposit from public.payments where id = v_src;
  elsif v_type = 'other_receipt' then
    select bank_deposit_id into v_deposit from public.other_receipts where id = v_src;
  end if;
  if v_deposit is not null and exists (select 1 from public.bank_deposits d where d.id = v_deposit and d.voided_at is null) then
    raise exception 'That receipt is part of a bank deposit. Match the bank transaction to the deposit instead.' using errcode = '22023';
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."guard_feed_line_not_deposited"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_gl_account_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_parent public.gl_accounts;
  v_cursor uuid;
  v_hops int := 0;
  v_balance numeric;
begin
  if (tg_op = 'INSERT' or new.number is distinct from old.number or new.association_id is distinct from old.association_id)
     and exists (select 1 from public.gl_accounts o
                  where o.portfolio_id = new.portfolio_id and o.number = new.number and o.id <> new.id
                    and (o.association_id is null or new.association_id is null or o.association_id = new.association_id)) then
    raise exception 'Account number % is already used in this chart of accounts', new.number using errcode = '23505';
  end if;

  if tg_op = 'UPDATE' and new.portfolio_id is not distinct from old.portfolio_id
     and new.association_id is not distinct from old.association_id
     and new.account_type is not distinct from old.account_type
     and new.sub_account_of_id is not distinct from old.sub_account_of_id then
    null;
  elsif new.association_id is not null and not exists (
       select 1 from public.associations a where a.id = new.association_id and a.portfolio_id = new.portfolio_id) then
    raise exception 'That association is not in this company' using errcode = '22023';
  elsif new.sub_account_of_id is not null then
    select * into v_parent from public.gl_accounts where id = new.sub_account_of_id;
    if v_parent.id is null or v_parent.portfolio_id <> new.portfolio_id then
      raise exception 'Parent account not found' using errcode = '22023';
    end if;
    if v_parent.account_type <> new.account_type then
      raise exception 'A sub-account must have the same type as its parent' using errcode = '22023';
    end if;
    if v_parent.association_id is not null and v_parent.association_id is distinct from new.association_id then
      raise exception 'A sub-account must belong to its parent''s association' using errcode = '22023';
    end if;
    v_cursor := new.sub_account_of_id;
    while v_cursor is not null and v_hops < 50 loop
      if v_cursor = new.id then raise exception 'An account cannot be under its own sub-account' using errcode = '22023'; end if;
      select sub_account_of_id into v_cursor from public.gl_accounts where id = v_cursor;
      v_hops := v_hops + 1;
    end loop;
    if v_cursor is not null then
      raise exception 'This account hierarchy is too deep to check; choose a parent nearer the top' using errcode = '22023';
    end if;
  end if;

  if tg_op = 'UPDATE' then
    if (new.account_type is distinct from old.account_type or new.association_id is distinct from old.association_id
        or new.portfolio_id is distinct from old.portfolio_id)
       and exists (select 1 from public.journal_lines where gl_account_id = old.id) then
      raise exception 'This account has ledger entries; its type and association cannot change. Create a new account instead.' using errcode = '22023';
    end if;
    if (new.account_type is distinct from old.account_type or new.association_id is distinct from old.association_id
        or new.portfolio_id is distinct from old.portfolio_id)
       and exists (select 1 from public.gl_accounts where sub_account_of_id = old.id) then
      raise exception 'This account has sub-accounts; its type and association cannot change' using errcode = '22023';
    end if;
    if (new.account_type is distinct from old.account_type or new.association_id is distinct from old.association_id
        or new.portfolio_id is distinct from old.portfolio_id)
       and not public.app_is_repair_session()
       and public.app_gl_account_referenced(old.id) then
      raise exception 'This account is already used (a bank account, loan, charge category, bill or similar), so its type and association cannot change. Create a new account instead.' using errcode = '22023';
    end if;
    if old.active and not new.active and old.account_type::text in
         ('asset', 'liability', 'equity', 'cash', 'accounts_receivable', 'accounts_payable', 'fixed_asset') then
      select coalesce(sum(jl.debit_amount - jl.credit_amount), 0) into v_balance
        from public.journal_lines jl join public.journal_entries je on je.id = jl.entry_id and je.posted
       where jl.gl_account_id = old.id;
      if round(v_balance, 2) <> 0 then
        raise exception 'This account has a balance of %; move it to another account before deactivating', round(v_balance, 2) using errcode = '22023';
      end if;
    end if;
    if old.active and not new.active then
      if exists (select 1 from public.bank_accounts where gl_account_id = old.id and archived_at is null) then
        raise exception 'A bank account posts to this GL account; change the bank account first' using errcode = '22023';
      end if;
      if exists (select 1 from public.gl_account_map where gl_account_id = old.id) then
        raise exception 'This account is a default in the GL account map; choose another default first' using errcode = '22023';
      end if;
      if exists (select 1 from public.gl_accounts where sub_account_of_id = old.id and active) then
        raise exception 'This account has active sub-accounts; deactivate them first' using errcode = '22023';
      end if;
    end if;
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."guard_gl_account_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_gl_account_delete"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if public.app_is_repair_session() then
    return old;
  end if;
  if exists (select 1 from public.gl_accounts where sub_account_of_id = old.id) then
    raise exception 'This account has sub-accounts; it cannot be deleted' using errcode = '23503';
  end if;
  if public.app_gl_account_referenced(old.id) then
    raise exception 'This account is used by ledger entries or other records; mark it inactive instead of deleting it' using errcode = '23503';
  end if;
  return old;
end $$;


ALTER FUNCTION "public"."guard_gl_account_delete"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_invitation_accept_verified_email"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
