    AS $$
begin
  if auth.uid() is not null
     and new.status::text = 'accepted' and old.status::text is distinct from 'accepted' and new.used_by is not null then
    if not exists (select 1 from auth.users u where u.id = new.used_by and u.email_confirmed_at is not null) then
      raise exception 'Confirm your email address before accepting this invitation'
        using errcode = '42501';
    end if;
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."guard_invitation_accept_verified_email"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_meeting_action_item_audit"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if tg_op = 'UPDATE' then
    new.id := old.id;
    new.meeting_id := old.meeting_id;
    new.created_by := old.created_by;
    new.created_at := old.created_at;
  end if;

  if new.status = 'completed' then
    if tg_op = 'INSERT' or old.status is distinct from 'completed' then
      new.completed_at := now();
      new.completed_by := coalesce(auth.uid(), new.completed_by);
    else
      new.completed_at := old.completed_at;
      new.completed_by := old.completed_by;
    end if;
  else
    new.completed_at := null;
    new.completed_by := null;
  end if;

  new.updated_at := now();
  return new;
end;
$$;


ALTER FUNCTION "public"."guard_meeting_action_item_audit"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_posted_journal_entry"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if current_user not in ('authenticated', 'anon') then return coalesce(new, old); end if;
  -- Any direct change to (or removal of) a posted entry: description, memo,
  -- reversal links and every other column included.
  if old.posted then
    raise exception 'A posted journal entry cannot be changed or removed; reverse it instead' using errcode = '42501';
  end if;
  return coalesce(new, old);
end $$;


ALTER FUNCTION "public"."guard_posted_journal_entry"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_posted_journal_lines"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if current_user not in ('authenticated', 'anon') then return coalesce(new, old); end if;
  if exists (select 1 from public.journal_entries je
              where je.posted and je.id in (case when tg_op <> 'INSERT' then old.entry_id end, case when tg_op <> 'DELETE' then new.entry_id end)) then
    raise exception 'Lines of a posted journal entry cannot be changed; reverse the entry instead' using errcode = '42501';
  end if;
  return coalesce(new, old);
end $$;


ALTER FUNCTION "public"."guard_posted_journal_lines"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_profile_insert_delete"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if auth.uid() is null or public.is_platform_operator() then
    if tg_op = 'DELETE' then
      return old;
    end if;
    return new;
  end if;

  if tg_op = 'DELETE' then
    if old.portfolio_id is not null and public.can_admin_portfolio(old.portfolio_id) then
      return old;
    end if;
    raise exception 'profile deletion denied: requires platform operator or company admin of the portfolio'
      using errcode = '42501';
  end if;

  if new.portfolio_id is not null and public.can_admin_portfolio(new.portfolio_id) then
    return new;
  end if;

  if new.id = auth.uid()
     and new.portfolio_id is null
     and new.hoa_role = 'owner'
     and new.role_id is null
     and new.mvp_role is null
     and new.disabled_at is null then
    return new;
  end if;

  if new.id = auth.uid() and new.disabled_at is null and exists (
       select 1 from public.user_invitations i
        where i.used_by = auth.uid() and i.status = 'accepted' and i.used_at = now()
          and i.portfolio_id is not distinct from new.portfolio_id
          and i.hoa_role is not distinct from new.hoa_role
          and i.role_id is not distinct from new.role_id
          and i.mvp_role is not distinct from new.mvp_role) then
    return new;
  end if;

  raise exception 'profile creation denied: requires platform operator or company admin of the portfolio'
    using errcode = '42501';
end
$$;


ALTER FUNCTION "public"."guard_profile_insert_delete"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_profile_privilege_changes"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  is_role_change boolean;
  is_account_control_change boolean;
begin
  is_role_change := (new.portfolio_id is distinct from old.portfolio_id) or (new.role_id is distinct from old.role_id)
    or (new.hoa_role is distinct from old.hoa_role) or (new.mvp_role is distinct from old.mvp_role);
  is_account_control_change := (new.disabled_at is distinct from old.disabled_at) or (new.mfa_required is distinct from old.mfa_required)
    or (new.profile_access is distinct from old.profile_access) or (new.gl_account_permissions is distinct from old.gl_account_permissions);
  if not (is_role_change or is_account_control_change) then return new; end if;
  if auth.uid() is null then return new; end if;
  if (public.is_platform_operator() and public.is_platform_admin())
     or (not public.is_platform_operator() and public.can_admin_portfolio(coalesce(new.portfolio_id, old.portfolio_id))) then
    return new;
  end if;
  if not is_account_control_change and new.id = auth.uid() and exists (
       select 1 from public.user_invitations i
        where i.used_by = auth.uid() and i.status = 'accepted' and i.used_at = now()
          and i.portfolio_id is not distinct from new.portfolio_id and i.hoa_role is not distinct from new.hoa_role
          and i.role_id is not distinct from new.role_id and i.mvp_role is not distinct from new.mvp_role) then
    return new;
  end if;
  raise exception 'profile privilege change denied: requires platform operator or full-access staff in portfolio %',
    coalesce(new.portfolio_id, old.portfolio_id)::text;
end $$;


ALTER FUNCTION "public"."guard_profile_privilege_changes"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."guard_profile_privilege_changes"() IS 'Prevents self-escalation. A user cannot change their own portfolio_id / role_id / hoa_role via UPDATE; only platform operators or portfolio admins can.';



CREATE OR REPLACE FUNCTION "public"."guard_scheduled_report_change"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_slug text;
  v_error text;
  v_takeover boolean := false;
begin
  if current_user not in ('authenticated', 'anon') then return new; end if;
  if auth.uid() is null then raise exception 'Sign in to change scheduled reports.' using errcode = '42501'; end if;

  if tg_op = 'INSERT' then
    new.created_by := auth.uid();
    new.run_as := auth.uid();
    v_takeover := true;
  else
    new.created_by := old.created_by;
    new.portfolio_id := old.portfolio_id;
    v_takeover :=
      (new.definition_id, new.saved_report_id, new.parameters, new.delivery_targets, new.delivery_channel, new.output_format)
        is distinct from (old.definition_id, old.saved_report_id, old.parameters, old.delivery_targets, old.delivery_channel, old.output_format)
      or (new.name, new.frequency, new.day_of_week, new.day_of_month, new.local_hour, new.hour_utc, new.time_zone)
        is distinct from (old.name, old.frequency, old.day_of_week, old.day_of_month, old.local_hour, old.hour_utc, old.time_zone)
      or (old.active is not true and new.active is true);
    if v_takeover then
      new.run_as := auth.uid();
    else
      new.run_as := old.run_as;
    end if;
  end if;

  if v_takeover then
    if new.saved_report_id is not null and not exists (
         select 1 from public.saved_reports s where s.id = new.saved_report_id and s.portfolio_id = new.portfolio_id) then
      raise exception 'That custom report was not found.' using errcode = 'P0002';
    end if;
    select d.slug into v_slug from public.report_definitions d where d.id = new.definition_id and d.active;
    if v_slug is null then raise exception 'That report is not available.' using errcode = 'P0002'; end if;
    v_error := public.report_params_access_error(new.portfolio_id, v_slug, coalesce(new.parameters, '{}'::jsonb));
    if v_error is not null then raise exception '%', v_error using errcode = '42501'; end if;

    -- Emailed reports go only to the company's own staff who can see the report.
    if new.delivery_channel::text = 'email' then
      v_error := public.report_recipients_error(new.portfolio_id, v_slug, coalesce(new.parameters, '{}'::jsonb), new.delivery_targets);
      if v_error is not null then raise exception '%', v_error using errcode = '42501'; end if;
    end if;
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."guard_scheduled_report_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_sms_consent"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if new.entity_type not in ('owner', 'vendor') then
    raise exception 'live SMS consent is limited to owners and vendors';
  end if;
  if new.entity_type = 'owner' and not exists (
    select 1 from public.owners owner where owner.id = new.entity_id and owner.portfolio_id = new.portfolio_id
  ) then
    raise exception 'SMS owner consent must match the portfolio';
  end if;
  if new.entity_type = 'vendor' and not exists (
    select 1 from public.vendors vendor where vendor.id = new.entity_id and vendor.portfolio_id = new.portfolio_id
  ) then
    raise exception 'SMS vendor consent must match the portfolio';
  end if;
  if new.opted_in
     and (tg_op = 'INSERT' or not coalesce(old.opted_in, false))
     and char_length(btrim(coalesce(new.source, ''))) < 10 then
    raise exception 'documented SMS consent evidence is required';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."guard_sms_consent"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_stripe_autopay_mandate_scope"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_method public.payment_methods%rowtype;
  v_account_id text;
begin
  select * into v_method from public.payment_methods where id = new.payment_method_id;
  if v_method.processor::text <> 'stripe' then
    return new;
  end if;

  select stripe_account_id into v_account_id
  from public.associations
  where id = new.association_id
    and portfolio_id = new.portfolio_id;

  if v_method.owner_id is distinct from new.owner_id
     or v_method.portfolio_id is distinct from new.portfolio_id
     or v_method.association_id is distinct from new.association_id
     or v_method.processor_account_id is distinct from v_account_id then
    raise exception 'Stripe AutoPay mandate crosses owner, portfolio, association, or connected-account scope';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."guard_stripe_autopay_mandate_scope"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_stripe_setup_attempt_scope"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_association public.associations%rowtype;
begin
  select * into v_association
  from public.associations
  where id = new.association_id;

  if not found
     or v_association.portfolio_id is distinct from new.portfolio_id
     or v_association.stripe_account_id is distinct from new.processor_account_id
     or not coalesce(v_association.stripe_charges_enabled, false)
     or not coalesce(v_association.stripe_payouts_enabled, false)
     or v_association.stripe_deauthorized_at is not null then
    raise exception 'AutoPay setup does not match a payment-ready association Stripe account';
  end if;

  if not exists (
    select 1
    from public.occupancies o
    where o.owner_id = new.owner_id
      and o.unit_id = new.unit_id
      and o.association_id = new.association_id
      and o.status = 'current'
  ) then
    raise exception 'AutoPay setup owner, unit, and association do not match a current occupancy';
  end if;

  new.updated_at := now();
  return new;
end;
$$;


ALTER FUNCTION "public"."guard_stripe_setup_attempt_scope"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_year_end_package"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if old.status in ('finalized', 'superseded') then
    if new.snapshot is distinct from old.snapshot or new.snapshot_sha256 is distinct from old.snapshot_sha256
       or new.checklist is distinct from old.checklist or new.period_start is distinct from old.period_start
       or new.period_end is distinct from old.period_end or new.finalized_at is distinct from old.finalized_at
       or new.finalized_by is distinct from old.finalized_by or new.generated_by is distinct from old.generated_by
       or new.generated_at is distinct from old.generated_at or new.notes is distinct from old.notes
       or new.association_id is distinct from old.association_id or new.portfolio_id is distinct from old.portfolio_id
       or new.fiscal_year is distinct from old.fiscal_year then
      raise exception 'A finalized year-end package cannot be changed';
    end if;
    if old.status = 'superseded' and new.status <> 'superseded' then
      raise exception 'A superseded package cannot be reinstated';
    end if;
    if old.status = 'superseded' and (new.superseded_by is distinct from old.superseded_by
       or new.superseded_at is distinct from old.superseded_at or new.supersede_reason is distinct from old.supersede_reason) then
      raise exception 'A superseded year-end package cannot be changed';
    end if;
    if old.status = 'finalized' and new.status not in ('finalized', 'superseded') then
      raise exception 'A finalized year-end package cannot go back to draft; supersede it to prepare a revision';
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."guard_year_end_package"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_new_auth_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  insert into public.profiles (id, email, hoa_role)
  values (
    new.id,
    new.email,
    -- Default to 'owner' for portal signups. Staff get upgraded via invitation acceptance.
    'owner'::public.hoa_role
  )
  on conflict (id) do update
    set email = excluded.email,
        updated_at = now();
  return new;
end;
$$;


ALTER FUNCTION "public"."handle_new_auth_user"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."has_entitlement"("p_portfolio_id" "uuid", "p_feature_key" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$#variable_conflict use_column
begin
  return (select s.x from (

  select (auth.uid() is null or public.can_access_portfolio(p_portfolio_id) or public.is_platform_operator())
    and exists (
    select 1
      from public.portfolios p
      join public.feature_entitlements fe on true
     where p.id = p_portfolio_id
       and fe.key = p_feature_key
       and case
             when fe.min_tier = 'foundation' then true
             when fe.min_tier = 'growth' then p.tier in ('growth','portfolio','enterprise')
             when fe.min_tier = 'portfolio' then p.tier in ('portfolio','enterprise')
             when fe.min_tier = 'enterprise' then p.tier = 'enterprise'
           end
       and p.suspended_at is null
  )
  ) s(x) limit 1);
end$$;


ALTER FUNCTION "public"."has_entitlement"("p_portfolio_id" "uuid", "p_feature_key" "text") OWNER TO "postgres";


