CREATE OR REPLACE FUNCTION "public"."hook_password_verification_attempt"("event" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_user_id uuid;
  v_valid boolean;
  v_email text;
  v_portfolio_id uuid;
begin
  v_user_id := (event->>'user_id')::uuid;
  v_valid := coalesce((event->>'valid')::boolean, false);

  select u.email
    into v_email
    from auth.users u
   where u.id = v_user_id;

  select p.portfolio_id
    into v_portfolio_id
    from public.profiles p
   where p.id = v_user_id;

  insert into public.login_attempts (
    email,
    auth_user_id,
    portfolio_id,
    success,
    failure_reason,
    mfa_used
  ) values (
    lower(v_email),
    v_user_id,
    v_portfolio_id,
    v_valid,
    case when v_valid then null else 'invalid_credentials' end,
    false
  );

  if v_valid then
    update public.profiles
       set last_login_at = now(), updated_at = now()
     where id = v_user_id;
  end if;

  return jsonb_build_object('decision', 'continue');
end;
$$;


ALTER FUNCTION "public"."hook_password_verification_attempt"("event" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."hook_password_verification_attempt"("event" "jsonb") IS 'Supabase Auth password-verification hook. Records direct and application sign-in attempts and always returns continue.';



