    '&', '&amp;'), '<', '&lt;'), '>', '&gt;'), '"', '&quot;'), '''', '&#39;');
$$;


ALTER FUNCTION "public"."html_escape"("p" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."import_bills"("p_rows" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  v_pid uuid := public.current_portfolio_id();
  v_errors text[] := '{}';
  r jsonb;
  v_row int;
  v_vendor uuid;
  v_vendor_text text;
  v_assoc uuid;
  v_gl uuid;
  v_amount numeric;
  v_bill_date date;
  v_due date;
  v_ids uuid[] := '{}';
  v_total numeric := 0;
  t record;
  v_matches int;
  v_vendor_matches int;
begin
  if v_pid is null or not public.can_manage_finance(v_pid) then raise exception 'Permission denied' using errcode = '42501'; end if;
  if jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) = 0 then raise exception 'The file has no rows' using errcode = '22023'; end if;
  if jsonb_array_length(p_rows) > 1000 then raise exception 'Upload at most 1,000 bills at a time' using errcode = '22023'; end if;
  create temp table if not exists _bill_rows (row_no int, vendor_id uuid, association_id uuid, gl_account_id uuid, bill_number text,
                                bill_date date, due_date date, amount numeric, memo text) on commit drop;
  truncate _bill_rows;
  for r in select * from jsonb_array_elements(p_rows) loop
    v_row := coalesce((r->>'row')::int, 0);
    v_vendor_text := btrim(coalesce(r->>'vendor', ''));
    v_assoc := public.csv_association_id(v_pid, r->>'association');
    v_matches := public.csv_association_matches(v_pid, r->>'association');
    v_vendor := null; v_vendor_matches := 0;
    -- The vendor is one of the row's association (or the management company).
    if v_assoc is not null and v_matches = 1 then
      select v.id into v_vendor from public.vendors v
       where v.portfolio_id = v_pid and v.archived_at is null
         and (v.association_id = v_assoc or v.is_management_company)
         and (v.id::text = v_vendor_text or lower(v.name) = lower(v_vendor_text))
       order by (v.id::text = v_vendor_text) desc limit 1;
      select count(*) into v_vendor_matches from public.vendors v
       where v.portfolio_id = v_pid and v.archived_at is null
         and (v.association_id = v_assoc or v.is_management_company)
         and lower(v.name) = lower(v_vendor_text);
    end if;
    v_gl := null; v_bill_date := null; v_due := null; v_amount := null;
    begin v_bill_date := public.csv_date(r->>'bill_date'); exception when others then v_bill_date := null; end;
    begin v_due := public.csv_date(r->>'due_date'); exception when others then v_due := '0001-01-01'; end;
    begin v_amount := public.csv_money(r->>'amount'); exception when others then v_amount := null; end;
    if v_matches > 1 then v_errors := v_errors || format('Row %s: more than one association is named "%s"; use its id instead', v_row, r->>'association');
    elsif v_assoc is null then v_errors := v_errors || format('Row %s: association "%s" not found', v_row, coalesce(r->>'association', ''));
    elsif not public.can_manage_association(v_assoc) then v_errors := v_errors || format('Row %s: you do not manage that association', v_row);
    else
      if v_vendor_matches > 1 and v_vendor_text !~* '^[0-9a-f-]{36}$' then
        v_errors := v_errors || format('Row %s: more than one vendor of that association is named "%s"; use its id instead', v_row, r->>'vendor');
      elsif v_vendor is null then
        -- Only associations the caller can see are named (a manager limited
        -- to some associations gets plain "not found" for the others).
        if exists (select 1 from public.vendors v
                    where v.portfolio_id = v_pid and v.archived_at is null
                      and public.can_view_association_row(v.association_id)
                      and (v.id::text = v_vendor_text or lower(v.name) = lower(v_vendor_text))) then
          v_errors := v_errors || format('Row %s: vendor "%s" is not a vendor of that association; add it to the association first', v_row, v_vendor_text);
        else
          v_errors := v_errors || format('Row %s: vendor "%s" not found', v_row, v_vendor_text);
        end if;
      end if;
      v_gl := public.csv_gl_id(v_pid, v_assoc, r->>'gl');
      if v_gl is null then v_errors := v_errors || format('Row %s: GL account "%s" not found for that association', v_row, coalesce(r->>'gl', '')); end if;
    end if;
    if v_bill_date is null then v_errors := v_errors || format('Row %s: bill_date must be YYYY-MM-DD', v_row); end if;
    if v_due = '0001-01-01' then v_errors := v_errors || format('Row %s: due_date must be YYYY-MM-DD or blank', v_row); end if;
    if v_amount is null or v_amount <= 0 then v_errors := v_errors || format('Row %s: amount must be a positive number', v_row);
    elsif scale(v_amount) > 2 then v_errors := v_errors || format('Row %s: amount can have at most two decimals', v_row); end if;
    if v_bill_date is not null and v_due is not null and v_due <> '0001-01-01' and v_due < v_bill_date then
      v_errors := v_errors || format('Row %s: due_date is before bill_date', v_row);
    end if;
    insert into _bill_rows values (v_row, v_vendor, v_assoc, v_gl, nullif(btrim(r->>'bill_number'), ''), v_bill_date,
                                   nullif(v_due, '0001-01-01'), v_amount, nullif(btrim(r->>'memo'), ''));
  end loop;
  if cardinality(v_errors) = 0 then
    for t in select distinct vendor_id, lower(btrim(bill_number)) as bn from _bill_rows where bill_number is not null order by 1, 2 loop
      perform pg_advisory_xact_lock(hashtextextended(t.vendor_id::text || ':' || t.bn, 0));
    end loop;
    for t in select b.row_no, b.bill_number from _bill_rows b
              where b.bill_number is not null and exists (
                select 1 from public.payable_bills pb
                 where pb.vendor_id = b.vendor_id and lower(btrim(pb.bill_number)) = lower(btrim(b.bill_number)) and pb.archived_at is null
                   and pb.status <> 'void'::public.payable_bill_status) loop
      v_errors := v_errors || format('Row %s: bill %s from this vendor is already entered', t.row_no, t.bill_number);
    end loop;
    for t in select min(b.row_no) as row_no, min(b.bill_number) as bill_number from _bill_rows b where b.bill_number is not null
              group by b.vendor_id, lower(btrim(b.bill_number)) having count(*) > 1 loop
      v_errors := v_errors || format('Row %s: bill %s appears more than once for the same vendor in this file', t.row_no, t.bill_number);
    end loop;
  end if;
  if cardinality(v_errors) > 0 then
    return jsonb_build_object('ok', false, 'errors', to_jsonb(v_errors[1:50]), 'error_count', cardinality(v_errors));
  end if;
  for t in select * from _bill_rows order by row_no loop
    v_ids := v_ids || public.create_payable_bill(v_pid, t.vendor_id, t.association_id, t.gl_account_id, null,
                                                 t.bill_number, t.bill_date, coalesce(t.due_date, t.bill_date), t.amount, t.memo, false, false);
    v_total := v_total + t.amount;
  end loop;
  insert into public.audit_logs (portfolio_id, entity_type, entity_id, action, actor_id, actor_email, changes)
  values (v_pid, 'payable_bill', null, 'bills_uploaded', auth.uid(), (select email from auth.users where id = auth.uid()),
          jsonb_build_object('count', cardinality(v_ids), 'total', v_total));
  return jsonb_build_object('ok', true, 'count', cardinality(v_ids), 'total', v_total);
end $_$;


ALTER FUNCTION "public"."import_bills"("p_rows" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."import_credit_income_account"("p_unit_id" "uuid", "p_charge_category_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_assoc uuid := public.unit_association_id(p_unit_id);
  v_pid uuid;
  v_cat public.charge_categories;
  v_probe public.charges;
begin
  select a.portfolio_id into v_pid from public.associations a where a.id = v_assoc;
  if v_pid is null or not public.can_manage_finance(v_pid) or not public.can_manage_association(v_assoc) then
    raise exception 'Unit not found' using errcode = 'P0002';
  end if;
  select * into v_cat from public.charge_categories cc
   where cc.id = p_charge_category_id
     and cc.portfolio_id = v_pid
     and (cc.association_id is null or cc.association_id = v_assoc);
  if not found then raise exception 'Charge category not found' using errcode = 'P0002'; end if;
  v_probe.unit_id := p_unit_id;
  v_probe.charge_category_id := v_cat.id;
  v_probe.charge_type := v_cat.charge_type;
  v_probe.gl_account_id := v_cat.gl_account_id;
  return (public.charge_gl_accounts(v_probe)).income;
end
$$;


ALTER FUNCTION "public"."import_credit_income_account"("p_unit_id" "uuid", "p_charge_category_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."import_journal_entry_batch"("p_name" "text", "p_rows" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_pid uuid := public.current_portfolio_id();
  v_errors text[] := '{}';
  r jsonb;
  v_row int;
  v_assoc uuid;
  v_gl uuid;
  v_debit numeric;
  v_credit numeric;
  v_date date;
  v_batch uuid;
  v_entry uuid;
  e record;
  v_entries int := 0;
  v_total numeric := 0;
  v_matches int;
begin
  if v_pid is null or not public.can_manage_finance(v_pid) then raise exception 'Permission denied' using errcode = '42501'; end if;
  if jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) = 0 then raise exception 'The file has no rows' using errcode = '22023'; end if;
  if jsonb_array_length(p_rows) > 5000 then raise exception 'Upload at most 5,000 lines at a time' using errcode = '22023'; end if;

  create temp table if not exists _je_rows (row_no int, entry_key text, entry_date date, association_id uuid, gl_account_id uuid,
                              debit numeric, credit numeric, memo text) on commit drop;
  truncate _je_rows;

  for r in select * from jsonb_array_elements(p_rows) loop
    v_row := coalesce((r->>'row')::int, 0);
    v_assoc := public.csv_association_id(v_pid, r->>'association');
    v_matches := public.csv_association_matches(v_pid, r->>'association');
    v_gl := null; v_date := null; v_debit := null; v_credit := null;
    begin v_date := public.csv_date(r->>'date'); exception when others then v_date := null; end;
    begin v_debit := coalesce(public.csv_money(r->>'debit'), 0);
          v_credit := coalesce(public.csv_money(r->>'credit'), 0);
    exception when others then v_debit := null; end;
    if coalesce(btrim(r->>'entry'), '') = '' then v_errors := v_errors || format('Row %s: entry is required (rows with the same entry form one journal entry)', v_row); end if;
    if v_date is null then v_errors := v_errors || format('Row %s: date must be YYYY-MM-DD', v_row); end if;
    if v_matches > 1 then v_errors := v_errors || format('Row %s: more than one association is named "%s" — use its id instead', v_row, r->>'association');
    elsif v_assoc is null then v_errors := v_errors || format('Row %s: association "%s" not found', v_row, coalesce(r->>'association', ''));
    elsif not public.can_manage_association(v_assoc) then v_errors := v_errors || format('Row %s: you do not manage that association', v_row);
    else
      v_gl := public.csv_gl_id(v_pid, v_assoc, r->>'gl');
      if v_gl is null then v_errors := v_errors || format('Row %s: GL account "%s" not found for that association', v_row, coalesce(r->>'gl', '')); end if;
    end if;
    if v_debit is not null and (scale(v_debit) > 2 or scale(v_credit) > 2) then
      v_errors := v_errors || format('Row %s: amounts can have at most two decimals', v_row);
    end if;
    if v_debit is null then v_errors := v_errors || format('Row %s: debit/credit must be numbers', v_row);
    elsif v_debit < 0 or v_credit < 0 or (v_debit > 0) = (v_credit > 0) then
      v_errors := v_errors || format('Row %s: enter either a debit or a credit (positive), not both', v_row);
    end if;
    insert into _je_rows values (v_row, btrim(r->>'entry'), v_date, v_assoc, v_gl, v_debit, v_credit, nullif(btrim(r->>'memo'), ''));
  end loop;

  if cardinality(v_errors) = 0 then
    for e in
      select entry_key, count(distinct entry_date) dates, sum(debit) d, sum(credit) c, count(*) n
        from _je_rows group by entry_key
    loop
      if e.dates > 1 then v_errors := v_errors || format('Entry "%s": all its lines need the same date', e.entry_key); end if;
      if e.n < 2 then v_errors := v_errors || format('Entry "%s": needs at least two lines', e.entry_key); end if;
      if round(e.d, 2) <> round(e.c, 2) then
        v_errors := v_errors || format('Entry "%s": debits %s do not equal credits %s', e.entry_key, e.d, e.c);
      end if;
    end loop;
  end if;
  if cardinality(v_errors) > 0 then
    return jsonb_build_object('ok', false, 'errors', to_jsonb(v_errors[1:50]), 'error_count', cardinality(v_errors));
  end if;

  insert into public.journal_entry_batches (portfolio_id, name, status, total_entries, total_debit, total_credit, created_by)
  values (v_pid, coalesce(nullif(btrim(p_name), ''), 'Upload ' || to_char(now(), 'YYYY-MM-DD HH24:MI')), 'validated',
          (select count(distinct entry_key) from _je_rows), (select sum(debit) from _je_rows), (select sum(credit) from _je_rows), auth.uid())
  returning id into v_batch;

  for e in select entry_key, min(entry_date) entry_date, string_agg(distinct memo, '; ') memo from _je_rows group by entry_key order by min(row_no) loop
    insert into public.journal_entries (portfolio_id, entry_date, reference_number, memo, description, source_type, created_by, posted, batch_id)
    values (v_pid, e.entry_date, left(e.entry_key, 60), left(e.memo, 500), left(coalesce(e.memo, e.entry_key), 500), 'je_batch', auth.uid(), false, v_batch)
    returning id into v_entry;
    insert into public.journal_lines (entry_id, gl_account_id, association_id, debit_amount, credit_amount, memo, sort_order)
    select v_entry, gl_account_id, association_id, debit, credit, memo, row_number() over (order by row_no) - 1
      from _je_rows where entry_key = e.entry_key;
    update public.journal_entries set posted = true where id = v_entry;
    v_entries := v_entries + 1;
  end loop;

  update public.journal_entry_batches set status = 'posted', posted_at = now(), posted_by = auth.uid(), updated_at = now() where id = v_batch;
  select sum(debit) into v_total from _je_rows;
  insert into public.audit_logs (portfolio_id, entity_type, entity_id, action, actor_id, actor_email, changes)
  values (v_pid, 'journal_entry_batch', v_batch, 'uploaded', auth.uid(), (select email from auth.users where id = auth.uid()),
          jsonb_build_object('entries', v_entries, 'total', v_total));
  return jsonb_build_object('ok', true, 'batch_id', v_batch, 'entries', v_entries, 'total', v_total);
end $$;


ALTER FUNCTION "public"."import_journal_entry_batch"("p_name" "text", "p_rows" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."import_lockbox_batch"("p_bank_account_id" "uuid", "p_batch_date" "date", "p_reference" "text", "p_rows" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_pid uuid := public.current_portfolio_id();
  v_bank record;
  v_batch uuid;
  r jsonb;
  v_amount numeric;
  v_errors text[] := '{}';
  m record;
  v_items int := 0;
  v_matched int := 0;
  v_total numeric := 0;
begin
  if v_pid is null or not public.can_manage_finance(v_pid) then raise exception 'Permission denied' using errcode = '42501'; end if;
  select * into v_bank from public.bank_accounts where id = p_bank_account_id and portfolio_id = v_pid and archived_at is null;
  if not found then raise exception 'Choose the bank account the lockbox deposits into' using errcode = '22023'; end if;
  if v_bank.association_id is null or not public.can_manage_association(v_bank.association_id) then
    raise exception 'That bank account is not linked to an association you manage' using errcode = '22023';
  end if;
  if p_batch_date is null then raise exception 'Enter the deposit date' using errcode = '22023'; end if;
  if jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) = 0 then raise exception 'The file has no checks' using errcode = '22023'; end if;
  if jsonb_array_length(p_rows) > 2000 then raise exception 'Upload at most 2,000 checks at a time' using errcode = '22023'; end if;
  if nullif(btrim(p_reference), '') is not null and exists (
       select 1 from public.lockbox_batches where portfolio_id = v_pid and bank_account_id = p_bank_account_id
          and lower(deposit_reference) = lower(btrim(p_reference))) then
    raise exception 'A lockbox batch with reference % was already imported for this account', btrim(p_reference) using errcode = '23505';
  end if;

  for r in select * from jsonb_array_elements(p_rows) loop
    v_amount := null;
    begin v_amount := public.csv_money(r->>'amount'); exception when others then v_amount := -1; end;
    if v_amount is null or v_amount <= 0 then
      v_errors := v_errors || format('Row %s: amount "%s" is not a positive number', coalesce(r->>'row', '?'), coalesce(r->>'amount', ''));
    elsif scale(v_amount) > 2 then
      v_errors := v_errors || format('Row %s: amount has more than two decimals', coalesce(r->>'row', '?'));
    end if;
  end loop;
  if cardinality(v_errors) > 0 then
    return jsonb_build_object('ok', false, 'errors', to_jsonb(v_errors[1:50]), 'error_count', cardinality(v_errors));
  end if;

  insert into public.lockbox_batches (portfolio_id, bank_account_id, association_id, provider, batch_date, status,
                                      deposit_reference, received_at, created_by)
  values (v_pid, p_bank_account_id, v_bank.association_id, 'upload', p_batch_date, 'received',
          nullif(btrim(p_reference), ''), now(), auth.uid())
  returning id into v_batch;

  for r in select * from jsonb_array_elements(p_rows) loop
    v_amount := public.csv_money(r->>'amount');
    select * into m from public.lockbox_match_unit(v_bank.association_id, r->>'unit', r->>'payer', v_amount);
    insert into public.lockbox_items (batch_id, portfolio_id, association_id, unit_id, owner_id, row_no, check_number,
                                      check_amount_cents, payer_name, memo, matched_confidence, match_reason,
                                      manually_matched, rejected)
    values (v_batch, v_pid, v_bank.association_id, m.unit_id, m.owner_id, nullif(r->>'row', '')::int,
            nullif(btrim(r->>'check_number'), ''), round(v_amount * 100)::bigint,
            nullif(btrim(r->>'payer'), ''), nullif(btrim(r->>'memo'), ''), m.confidence, m.reason, false, false);
    v_items := v_items + 1;
    v_total := v_total + v_amount;
    if m.unit_id is not null then v_matched := v_matched + 1; end if;
  end loop;

  update public.lockbox_batches set total_items = v_items, total_amount_cents = round(v_total * 100)::bigint, updated_at = now()
   where id = v_batch;
  return jsonb_build_object('ok', true, 'batch_id', v_batch, 'items', v_items, 'matched', v_matched, 'total', v_total);
end $$;


ALTER FUNCTION "public"."import_lockbox_batch"("p_bank_account_id" "uuid", "p_batch_date" "date", "p_reference" "text", "p_rows" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."import_opening_balance"("p_unit_id" "uuid", "p_charge_category_id" "uuid", "p_amount" numeric, "p_description" "text", "p_as_of" "date") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_charge public.charges;
  v_assoc uuid;
  v_pid uuid;
begin
  select b.association_id, a.portfolio_id into v_assoc, v_pid
    from public.units u join public.buildings b on b.id = u.building_id join public.associations a on a.id = b.association_id
   where u.id = p_unit_id;
  if v_pid is null then raise exception 'Unit not found' using errcode = 'P0002'; end if;
  v_charge := public.post_ad_hoc_charge(p_unit_id, p_charge_category_id, p_amount, p_description, p_as_of);
  insert into public.imported_balances (portfolio_id, association_id, unit_id, as_of_date, imported_balance, memo, charge_id, created_by)
  values (v_pid, v_assoc, p_unit_id, p_as_of, round(p_amount, 2), p_description, v_charge.id, auth.uid());
  return v_charge.id;
end
$$;


ALTER FUNCTION "public"."import_opening_balance"("p_unit_id" "uuid", "p_charge_category_id" "uuid", "p_amount" numeric, "p_description" "text", "p_as_of" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."import_opening_credit"("p_unit_id" "uuid", "p_charge_category_id" "uuid", "p_amount" numeric, "p_description" "text", "p_as_of" "date") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_assoc uuid;
  v_pid uuid;
  v_memo text := coalesce(nullif(btrim(p_description), ''), 'Opening credit');
  v_income uuid;
  v_payment uuid;
begin
  select b.association_id, a.portfolio_id into v_assoc, v_pid
    from public.units u
    join public.buildings b on b.id = u.building_id
    join public.associations a on a.id = b.association_id
   where u.id = p_unit_id;
  if v_pid is null then raise exception 'Unit not found' using errcode = 'P0002'; end if;
  if p_amount is null or p_amount <= 0 then
    raise exception 'Enter a credit amount greater than zero' using errcode = '22023';
  end if;
  if p_as_of is null then raise exception 'Enter the as-of date' using errcode = '22023'; end if;

  v_income := public.import_credit_income_account(p_unit_id, p_charge_category_id);
  if v_income is null then
    raise exception 'No income account is set up for this company, so the credit cannot be posted' using errcode = '22023';
  end if;

  -- Checks finance access to the unit's association, posts Dr income / Cr A/R
  -- (trg_post_payment_to_gl) and writes the audit log.
  v_payment := public.post_homeowner_credit(p_unit_id, p_amount, p_as_of, v_income, v_memo, null);

  insert into public.imported_balances (portfolio_id, association_id, unit_id, as_of_date, imported_balance, memo, charge_id, created_by)
  values (v_pid, v_assoc, p_unit_id, p_as_of, -round(p_amount, 2), v_memo, null, auth.uid());
  return v_payment;
end
$$;


ALTER FUNCTION "public"."import_opening_credit"("p_unit_id" "uuid", "p_charge_category_id" "uuid", "p_amount" numeric, "p_description" "text", "p_as_of" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."initialize_accounting_year"("p_portfolio_id" "uuid", "p_fiscal_year" integer) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  inserted_count integer;
begin
  if p_fiscal_year < 2000 or p_fiscal_year > 2100 then
    raise exception 'Fiscal year must be between 2000 and 2100';
  end if;
  if not (public.can_manage_finance(p_portfolio_id) or public.can_admin_portfolio(p_portfolio_id) or public.is_platform_operator()) then
    raise exception 'Not authorized to initialize accounting periods';
  end if;
  if public.manager_is_scoped() is true and not public.is_platform_operator() then
    raise exception 'Months are set up for the whole company. Ask a company admin or a manager who is not limited to specific associations.' using errcode = '42501';
  end if;

  insert into public.accounting_periods (portfolio_id, fiscal_year, period_month)
  select p_portfolio_id, p_fiscal_year, month_number
  from generate_series(1, 12) as month_number
  on conflict (portfolio_id, fiscal_year, period_month) do nothing;
  get diagnostics inserted_count = row_count;

  insert into public.audit_logs (entity_type, entity_id, action, actor_id, changes)
  values (
    'accounting_year', p_portfolio_id, 'accounting_year_initialized', auth.uid(),
    jsonb_build_object('fiscal_year', p_fiscal_year, 'periods_created', inserted_count)
  );
  return inserted_count;
end;
$$;


ALTER FUNCTION "public"."initialize_accounting_year"("p_portfolio_id" "uuid", "p_fiscal_year" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."initialize_delinquency_policy"("p_association_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare portfolio uuid; policy uuid; v_state text;
begin
  select portfolio_id, upper(coalesce(state, '')) into portfolio, v_state from public.associations where id = p_association_id;
  if portfolio is null then raise exception 'Association not found'; end if;
  if not (public.can_admin_portfolio(portfolio) or public.is_platform_operator()) then raise exception 'Not authorized to configure delinquency policy'; end if;
  insert into public.delinquency_policies (portfolio_id, association_id) values (portfolio, p_association_id)
  on conflict (association_id) do update set updated_at = now() returning id into policy;
  insert into public.delinquency_steps (policy_id, step_number, name, days_past_due, action_type, requires_human_approval, instructions)
  values
    (policy, 1, 'Courtesy reminder', 10, 'email', false, 'Review account and send a courteous balance reminder.'),
    (policy, 2, 'Formal collection notice', 30, 'letter', true, 'Confirm ledger accuracy and approve the formal notice.'),
    (policy, 3, 'Tracked physical notice', 45, 'physical_mail', true, 'Approve physical-mail fulfillment and retain delivery evidence.'),
    (policy, 4, 'Counsel review gate', 60, 'legal_review', true, 'Human portfolio administrator must approve or reject referral. No filing is automated.')
  on conflict (policy_id, step_number) do nothing;
  if (select jurisdiction from public.delinquency_policies where id = policy) is null then
    perform public.apply_delinquency_jurisdiction(p_association_id, v_state);
  end if;
  return policy;
end;
$$;


ALTER FUNCTION "public"."initialize_delinquency_policy"("p_association_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."inspection_item_scores"() RETURNS TABLE("inspection_id" "uuid", "score" integer, "flags" integer)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    SET "plan_cache_mode" TO 'force_generic_plan'
    AS $$
begin
  return query
  select i.inspection_id,
         round(avg(case i.severity::text
                     when 'info' then 100
                     when 'minor' then 80
                     when 'moderate' then 60
                     when 'major' then 40
                     when 'critical' then 20
                   end))::integer,
         (count(*) filter (where not coalesce(i.resolved, false)))::integer
    from public.inspection_items i
   group by i.inspection_id;
end
$$;


ALTER FUNCTION "public"."inspection_item_scores"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."inspection_items_self_service_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_assoc uuid;
begin
  if pg_trigger_depth() > 1 or auth.uid() is null then return new; end if;
  select i.association_id into v_assoc from public.inspections i
   where i.id = case when tg_op = 'INSERT' then new.inspection_id else old.inspection_id end;
  if (public.is_platform_operator() or public.is_any_staff() or public.is_company_admin())
     and public.can_access_association(v_assoc) then
    return new;
  end if;
  if tg_op = 'INSERT' then
    if coalesce(new.resolved, false) or new.resolved_at is not null
       or new.resolution_notes is not null or new.work_order_id is not null then
      raise exception 'Only management can resolve a finding or link a work order' using errcode = '42501';
    end if;
    return new;
  end if;
  if new.resolved is distinct from old.resolved
     or new.resolved_at is distinct from old.resolved_at
     or new.resolution_notes is distinct from old.resolution_notes
     or new.work_order_id is distinct from old.work_order_id then
    raise exception 'Only management can resolve a finding or link a work order' using errcode = '42501';
  end if;
  return new;
end
$$;


ALTER FUNCTION "public"."inspection_items_self_service_guard"() OWNER TO "postgres";


