CREATE OR REPLACE FUNCTION "public"."insurance_policies_due_for_reminder"("p_within_days" integer, "p_association_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS TABLE("id" "uuid", "owner_id" "uuid", "association_id" "uuid", "policy_number" "text", "insurance_company" "text", "effective_date" "date", "expiration_date" "date", "remind_owner" boolean, "remind_manager" boolean, "reminder_30_sent_at" timestamp with time zone, "reminder_15_sent_at" timestamp with time zone, "days_left" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
#variable_conflict use_column
begin
  return query
  with cand as (
    select ip.* from public.insurance_policies ip
     where ip.archived_at is null
       and ip.status in ('active', 'expiring_soon')
       and (p_association_ids is null or ip.association_id = any (p_association_ids))
  ), ld as (
    select x.aid, public.association_local_date(x.aid) as today
      from (select distinct c.association_id as aid from cand c) x
  )
  select c.id, c.owner_id, c.association_id, c.policy_number, c.insurance_company,
         c.effective_date, c.expiration_date, c.remind_owner, c.remind_manager,
         c.reminder_30_sent_at, c.reminder_15_sent_at,
         (c.expiration_date - ld.today)::integer
    from cand c
    join ld on ld.aid is not distinct from c.association_id
   where c.expiration_date >= ld.today
     and c.expiration_date <= ld.today + greatest(coalesce(p_within_days, 0), 0)
     and exists (select 1 from public.owners o where o.id = c.owner_id and o.archived_at is null)
     and exists (select 1 from public.occupancies oc where oc.owner_id = c.owner_id and oc.status = 'current'
                  and (c.association_id is null or oc.association_id = c.association_id))
   order by c.id;
end
$$;


ALTER FUNCTION "public"."insurance_policies_due_for_reminder"("p_within_days" integer, "p_association_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."insurance_policies_self_service_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_owner boolean; v_manager boolean;
begin
  if pg_trigger_depth() > 1 or not public.is_self_service_caller() then return new; end if;
  v_owner := new.remind_owner; v_manager := new.remind_manager;
  new := old;
  new.remind_owner := v_owner; new.remind_manager := v_manager; new.updated_at := now();
  return new;
end $$;


ALTER FUNCTION "public"."insurance_policies_self_service_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."insurance_policies_supersede_earlier"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if new.archived_at is not null or new.expiration_date is null then
    return null;
  end if;
  perform pg_advisory_xact_lock(hashtextextended('insurance-renewal:' || new.owner_id::text, 0));
  update public.insurance_policies p
     set archived_at = now(), updated_at = now()
   where p.owner_id = new.owner_id
     and p.association_id is not distinct from new.association_id
     and p.id <> new.id
     and p.archived_at is null
     and p.status in ('active', 'expiring_soon')
     and p.expiration_date < new.expiration_date;
  return null;
end
$$;


ALTER FUNCTION "public"."insurance_policies_supersede_earlier"() OWNER TO "postgres";


