CREATE OR REPLACE FUNCTION "public"."link_owner_on_invitation_accept"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_owner uuid;
  v_assoc uuid;
  v_matches int;
begin
  if new.hoa_role::text not in ('owner', 'board')
     or new.status::text <> 'accepted' or old.status::text is not distinct from 'accepted'
     or new.used_by is null then
    return new;
  end if;

  if nullif(new.metadata ->> 'owner_id', '') is not null then
    v_owner := (new.metadata ->> 'owner_id')::uuid;
    v_assoc := new.association_id;
  elsif new.hoa_role::text = 'owner' then
    -- An owner invitation created before invitations named their record (or
    -- by an older app version): the one unlinked owner record of that email
    -- in the invitation's company (and association, when it has one).
    select count(*), min(o.id::text)::uuid into v_matches, v_owner
      from public.owners o
     where o.portfolio_id = new.portfolio_id
       and (new.association_id is null or o.association_id = new.association_id)
       and o.archived_at is null
       and o.auth_user_id is null
       and not exists (select 1 from public.owner_portal_logins l where l.owner_id = o.id and l.revoked_at is null)
       and lower(btrim(o.email)) = lower(btrim(new.email));
    if v_matches <> 1 then
      raise exception 'This owner invitation does not identify one owner record. Ask the management office for a new invitation.'
        using errcode = 'P0001';
    end if;
    select o.association_id into v_assoc from public.owners o where o.id = v_owner;
  else
    -- A board invitation naming no owner record links no owner record.
    return new;
  end if;

  -- Only the person the invitation was sent to (accept_invitation checks this
  -- too; a direct status change by an admin must not bypass it).
  if v_assoc is null
     or not exists (select 1 from auth.users u
                     where u.id = new.used_by and lower(btrim(u.email)) = lower(btrim(new.email))) then
    raise exception 'This owner invitation cannot be used by this account. Ask the management office for a new invitation.'
      using errcode = '42501';
  end if;

  if not exists (select 1 from public.owners x where x.auth_user_id = new.used_by) then
    update public.owners o
       set auth_user_id = new.used_by, portal_activated = true
     where o.id = v_owner
       and o.portfolio_id = new.portfolio_id
       and o.association_id = v_assoc
       and o.archived_at is null
       and o.auth_user_id is null
       and not exists (select 1 from public.owner_portal_logins l where l.owner_id = o.id and l.revoked_at is null)
       and lower(btrim(o.email)) = lower(btrim(new.email));
  else
    insert into public.owner_portal_logins (owner_id, auth_user_id, portfolio_id, invitation_id)
    select o.id, new.used_by, o.portfolio_id, new.id
      from public.owners o
     where o.id = v_owner
       and o.portfolio_id = new.portfolio_id
       and o.association_id = v_assoc
       and o.archived_at is null
       and o.auth_user_id is null
       and lower(btrim(o.email)) = lower(btrim(new.email))
    on conflict (owner_id) do update
      set auth_user_id = excluded.auth_user_id, portfolio_id = excluded.portfolio_id,
          invitation_id = excluded.invitation_id, linked_at = now(), revoked_at = null
      where public.owner_portal_logins.revoked_at is not null;

    -- Activate it for this login (also the login's own first record that
    -- staff had turned off and invited again).
    update public.owners o
       set portal_activated = true
     where o.id = v_owner
       and o.portfolio_id = new.portfolio_id
       and o.association_id = v_assoc
       -- The record still carries the invited email (a stale invitation for an
       -- old address must not switch an old account back on).
       and lower(btrim(o.email)) = lower(btrim(new.email))
       and not o.portal_activated
       and o.archived_at is null
       and (o.auth_user_id = new.used_by
            or exists (select 1 from public.owner_portal_logins l
                        where l.owner_id = o.id and l.auth_user_id = new.used_by and l.revoked_at is null));
  end if;

  -- Fail loudly: if the exact record could not be linked (archived, its email
  -- changed, or it is on another login), the whole acceptance rolls back, so
  -- the invitation stays usable and the profile is not changed.
  if not exists (
    select 1 from public.owners o
     where o.id = v_owner
       and o.portfolio_id = new.portfolio_id
       and o.association_id = v_assoc
       and o.archived_at is null
       and lower(btrim(o.email)) = lower(btrim(new.email))
       and (o.auth_user_id = new.used_by
            or exists (select 1 from public.owner_portal_logins l
                        where l.owner_id = o.id and l.auth_user_id = new.used_by and l.revoked_at is null))) then
    raise exception 'The invited owner record could not be linked to this account. Ask the management office for a new invitation.'
      using errcode = 'P0001';
  end if;
  return new;
end
$$;


ALTER FUNCTION "public"."link_owner_on_invitation_accept"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."link_portal_user"("p_user_id" "uuid", "p_email" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_portfolio_id uuid;
begin
  select p.portfolio_id into v_portfolio_id
  from public.profiles p
  where p.id = p_user_id and p.disabled_at is null;

  if v_portfolio_id is null or p_email is null then
    return;
  end if;

  -- Owner records are not linked here: only their own invitation links them
  -- (link_owner_on_invitation_accept), never a matching email.

  -- One vendor record per sign-in (vendors.auth_user_id is unique). With one
  -- record per association, the same email can be on several records: link
  -- the oldest instead of failing the whole sign-up on the second.
  update public.vendors v
     set auth_user_id = p_user_id, portal_activated = true
   where v.id = (
     select candidate.id
       from public.vendors candidate
      where candidate.portfolio_id = v_portfolio_id
        and candidate.auth_user_id is null
        and candidate.archived_at is null
        -- Never a record already added to another login.
        and not exists (select 1 from public.vendor_portal_logins l where l.vendor_id = candidate.id and l.revoked_at is null)
        and exists (
          select 1 from jsonb_array_elements_text(candidate.emails) as e(email)
          where lower(e.email) = lower(p_email)
        )
      order by candidate.created_at, candidate.id
      limit 1
   )
     and not exists (select 1 from public.vendors linked where linked.auth_user_id = p_user_id)
     -- An invited vendor is linked to the exact record of the invitation when it
     -- is accepted (link_vendor_on_invitation_accept), not to the oldest match.
     and not exists (
       select 1 from public.user_invitations i
       where i.portfolio_id = v_portfolio_id and i.hoa_role::text = 'vendor' and i.status::text = 'pending'
         -- An expired invitation (still 'pending') no longer holds the link.
         and (i.expires_at is null or i.expires_at > now())
         and lower(btrim(i.email)) = lower(btrim(p_email))
     )
     and exists (
       select 1 from public.profiles p
       where p.id = p_user_id and p.hoa_role = 'vendor' and p.disabled_at is null
     );

  update public.board_members bm
     set auth_user_id = p_user_id
   where bm.auth_user_id is null
     and bm.active
     and lower(bm.email) = lower(p_email)
     and exists (
       select 1 from public.profiles p
       where p.id = p_user_id and p.hoa_role = 'board' and p.disabled_at is null
     )
     and exists (
       select 1 from public.associations a
       where a.id = bm.association_id and a.portfolio_id = v_portfolio_id
     );

  update public.tenants t
     set auth_user_id = p_user_id,
         portal_activated = true,
         updated_at = now()
   where t.id = (
     select candidate.id
     from public.tenants candidate
     where candidate.portfolio_id = v_portfolio_id
       and candidate.auth_user_id is null
       and candidate.status = 'active'
       and candidate.archived_at is null
       and lower(candidate.email) = lower(p_email)
       and exists (
         select 1 from public.profiles p
         where p.id = p_user_id and p.hoa_role = 'tenant' and p.disabled_at is null
       )
     order by candidate.created_at desc, candidate.id
     limit 1
   );

  update public.profiles p
     set hoa_role = 'board'
   where p.id = p_user_id
     and p.hoa_role = 'owner'
     and exists (
       select 1 from public.board_members bm
       where bm.auth_user_id = p_user_id and bm.active
     );
end;
$$;


ALTER FUNCTION "public"."link_portal_user"("p_user_id" "uuid", "p_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."link_vendor_on_invitation_accept"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  -- Only the person the invitation was sent to (accept_invitation checks this
  -- too; a direct status change by a company admin must not bypass it), as
  -- link_owner_on_invitation_accept does.
  if new.hoa_role::text = 'vendor'
     and new.status::text = 'accepted' and old.status::text is distinct from 'accepted'
     and new.used_by is not null
     and not exists (select 1 from auth.users u
                      where u.id = new.used_by and lower(btrim(u.email)) = lower(btrim(new.email))) then
    raise exception 'This vendor invitation cannot be used by this account. Ask the management office for a new invitation.'
      using errcode = '42501';
  end if;

  if new.hoa_role::text = 'vendor'
     and new.status::text = 'accepted' and old.status::text is distinct from 'accepted'
     and new.used_by is not null
     and not exists (select 1 from public.vendors x where x.auth_user_id = new.used_by) then
    update public.vendors v
       set auth_user_id = new.used_by, portal_activated = true
     -- Re-checked on the row itself, so two accepts at the same moment cannot
     -- both bind it.
     where v.auth_user_id is null
       and not exists (select 1 from public.vendor_portal_logins l2 where l2.vendor_id = v.id and l2.revoked_at is null)
       and v.id = (
       select c.id from public.vendors c
        where c.portfolio_id = new.portfolio_id
          and c.auth_user_id is null
          and c.archived_at is null
          -- Never a record already added to another login.
          and not exists (select 1 from public.vendor_portal_logins l where l.vendor_id = c.id and l.revoked_at is null)
          -- An invitation for one exact vendor record links that record or
          -- nothing (never another association's record with the same email);
          -- older invitations without one fall back to association, then email.
          and (nullif(new.metadata ->> 'vendor_id', '') is null
               or c.id::text = new.metadata ->> 'vendor_id')
          and jsonb_typeof(c.emails) = 'array'
          and exists (
            select 1 from jsonb_array_elements(c.emails) as e(val)
             where lower(btrim(case jsonb_typeof(e.val)
                                 when 'string' then e.val #>> '{}'
                                 when 'object' then e.val ->> 'email'
                               end)) = lower(btrim(new.email)))
        order by (c.id::text = coalesce(new.metadata ->> 'vendor_id', '')) desc,
                 (c.association_id is not distinct from new.association_id and new.association_id is not null) desc,
                 c.created_at desc, c.id
        limit 1);
  elsif new.hoa_role::text = 'vendor'
     and new.status::text = 'accepted' and old.status::text is distinct from 'accepted'
     and new.used_by is not null
     and nullif(new.metadata ->> 'vendor_id', '') is not null
     and exists (select 1 from public.profiles p
                  where p.id = new.used_by and p.portfolio_id = new.portfolio_id
                    and p.hoa_role = 'vendor' and p.disabled_at is null) then
    -- The login already has a vendor record: add the invited record to it.
    insert into public.vendor_portal_logins (vendor_id, auth_user_id, portfolio_id, invitation_id)
    select c.id, new.used_by, c.portfolio_id, new.id
      from public.vendors c
     where c.id::text = new.metadata ->> 'vendor_id'
       and c.portfolio_id = new.portfolio_id
       and c.archived_at is null
       and c.auth_user_id is null
       and jsonb_typeof(c.emails) = 'array'
       and exists (
         select 1 from jsonb_array_elements(c.emails) as e(val)
          where lower(btrim(case jsonb_typeof(e.val)
                              when 'string' then e.val #>> '{}'
                              when 'object' then e.val ->> 'email'
                            end)) = lower(btrim(new.email)))
    -- A link revoked when staff turned the portal off is replaced.
    on conflict (vendor_id) do update
      set auth_user_id = excluded.auth_user_id, portfolio_id = excluded.portfolio_id,
          invitation_id = excluded.invitation_id, linked_at = now(), revoked_at = null
      where public.vendor_portal_logins.revoked_at is not null;

    -- Activate it for this login (also a record of this login that staff had
    -- turned off and invited again).
    update public.vendors v
       set portal_activated = true
     where v.id::text = new.metadata ->> 'vendor_id'
       and not v.portal_activated
       and v.archived_at is null
       and (v.auth_user_id = new.used_by
            or exists (select 1 from public.vendor_portal_logins l
                        where l.vendor_id = v.id and l.auth_user_id = new.used_by and l.revoked_at is null));
  end if;
  return new;
end
$$;


ALTER FUNCTION "public"."link_vendor_on_invitation_accept"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."link_year_end_signature"("p_package_id" "uuid", "p_signature_request_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare pkg public.year_end_packages;
begin
  select * into pkg from public.year_end_packages where id = p_package_id for update;
  if not found or not (public.can_manage_finance(pkg.portfolio_id) or public.can_admin_portfolio(pkg.portfolio_id) or public.is_platform_operator()) then
    raise exception 'Permission denied' using errcode = '42501';
  end if;
  if not public.can_view_association_row(pkg.association_id) then
    raise exception 'Permission denied' using errcode = '42501';
  end if;
  if not exists (select 1 from public.signature_requests r where r.id = p_signature_request_id and r.portfolio_id = pkg.portfolio_id
                   and r.subject_type = 'year_end_package' and r.subject_id = pkg.id) then
    raise exception 'Signature request does not belong to this package';
  end if;
  update public.year_end_packages set signature_request_id = p_signature_request_id where id = p_package_id;
end;
$$;


ALTER FUNCTION "public"."link_year_end_signature"("p_package_id" "uuid", "p_signature_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_budget_lines"("p_association_id" "uuid", "p_fiscal_year" integer DEFAULT NULL::integer) RETURNS TABLE("id" "uuid", "association_id" "uuid", "gl_account_id" "uuid", "gl_account_number" integer, "gl_account_name" "text", "fiscal_year" integer, "monthly_amounts" numeric[], "annual_total" numeric, "category" "text", "notes" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if p_association_id is null
     or (p_fiscal_year is not null and p_fiscal_year not between 1900 and 2200) then
    raise exception 'Invalid budget scope' using errcode = '22023';
  end if;

  if not public.can_read_association_budget(p_association_id) then
    raise exception 'Not authorized for this association budget' using errcode = '42501';
  end if;

  return query
  select bl.id,
         bl.association_id,
         bl.gl_account_id,
         ga.number,
         ga.name,
         bl.fiscal_year,
         bl.monthly_amounts,
         bl.annual_total,
         bl.category::text,
         bl.notes,
         bl.created_at,
         bl.updated_at
  from public.budget_lines bl
  join public.gl_accounts ga on ga.id = bl.gl_account_id
  join public.associations a on a.id = bl.association_id
  where bl.association_id = p_association_id
    and (p_fiscal_year is null or bl.fiscal_year = p_fiscal_year)
    and ga.portfolio_id = a.portfolio_id
    and (ga.association_id is null or ga.association_id = bl.association_id)
  order by bl.category, ga.number;
end;
$$;


ALTER FUNCTION "public"."list_budget_lines"("p_association_id" "uuid", "p_fiscal_year" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."loan_periods_per_year"("p_frequency" "text") RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select case p_frequency when 'quarterly' then 4 when 'semi_annual' then 2 when 'annual' then 1 else 12 end;
$$;


