CREATE OR REPLACE FUNCTION "public"."lock_boxes_scope_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_unit_building uuid;
  v_building_assoc uuid;
begin
  if new.unit_id is not null then
    select u.building_id into v_unit_building from public.units u where u.id = new.unit_id;
    if v_unit_building is null then raise exception 'Unit not found' using errcode = '23503'; end if;
    if new.building_id is null then
      new.building_id := v_unit_building;
    elsif new.building_id is distinct from v_unit_building then
      raise exception 'The unit is not in that building' using errcode = '42501';
    end if;
  end if;
  if new.building_id is not null then
    select b.association_id into v_building_assoc from public.buildings b where b.id = new.building_id;
    if v_building_assoc is null then raise exception 'Building not found' using errcode = '23503'; end if;
    if new.association_id is null then
      new.association_id := v_building_assoc;
    elsif new.association_id is distinct from v_building_assoc then
      raise exception 'The building is not in that association' using errcode = '42501';
    end if;
  end if;
  if new.association_id is not null and not exists (
    select 1 from public.associations a where a.id = new.association_id and a.portfolio_id = new.portfolio_id
  ) then
    raise exception 'That association belongs to another company' using errcode = '42501';
  end if;
  return new;
end
$$;


ALTER FUNCTION "public"."lock_boxes_scope_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."lockbox_item_scope"("p_item" "uuid", OUT "batch_id" "uuid", OUT "association_id" "uuid", OUT "posted" boolean) RETURNS "record"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_batch uuid;
begin
  select i.batch_id into v_batch from public.lockbox_items i where i.id = p_item;
  if v_batch is null then raise exception 'Lockbox item not found' using errcode = 'P0002'; end if;
  perform 1 from public.lockbox_batches b where b.id = v_batch for update;
  select i.batch_id, b.association_id, i.payment_id is not null into batch_id, association_id, posted
    from public.lockbox_items i join public.lockbox_batches b on b.id = i.batch_id
   where i.id = p_item and public.can_manage_finance(b.portfolio_id) and public.can_manage_association(b.association_id)
   for update of i;
  if batch_id is null then raise exception 'Lockbox item not found' using errcode = 'P0002'; end if;
  if posted then raise exception 'That check is already posted' using errcode = '22023'; end if;
end $$;


ALTER FUNCTION "public"."lockbox_item_scope"("p_item" "uuid", OUT "batch_id" "uuid", OUT "association_id" "uuid", OUT "posted" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."lockbox_match_unit"("p_association_id" "uuid", "p_unit" "text", "p_payer" "text", "p_amount" numeric, OUT "unit_id" "uuid", OUT "owner_id" "uuid", OUT "confidence" numeric, OUT "reason" "text") RETURNS "record"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_payer text := lower(regexp_replace(btrim(coalesce(p_payer, '')), '\s+', ' ', 'g')); v_n int;
begin
  if btrim(coalesce(p_unit, '')) <> '' then
    select count(*) into v_n from public.units u join public.buildings b on b.id = u.building_id
     where b.association_id = p_association_id and u.archived_at is null and lower(u.unit_number) = lower(btrim(p_unit));
    if v_n = 1 then
      select u.id into unit_id from public.units u join public.buildings b on b.id = u.building_id
       where b.association_id = p_association_id and u.archived_at is null and lower(u.unit_number) = lower(btrim(p_unit));
      confidence := 0.95; reason := 'Unit number';
    end if;
  end if;

  if unit_id is null and v_payer <> '' then
    select count(distinct occ.unit_id) into v_n
      from public.occupancies occ join public.owners o on o.id = occ.owner_id
     where occ.association_id = p_association_id and occ.status = 'current' and occ.occupancy_type = 'owner'
       and public.payer_name_matches(p_payer, o.first_name, o.last_name, o.full_name);
    if v_n = 1 then
      select occ.unit_id into unit_id
        from public.occupancies occ join public.owners o on o.id = occ.owner_id
       where occ.association_id = p_association_id and occ.status = 'current' and occ.occupancy_type = 'owner'
         and public.payer_name_matches(p_payer, o.first_name, o.last_name, o.full_name)
       limit 1;
      confidence := 0.80; reason := 'Owner name';
    end if;
  end if;

  if unit_id is null and p_amount > 0 then
    with bal as (
      select c.unit_id, sum(c.amount - coalesce((select sum(pa.amount_applied) from public.payment_applications pa where pa.charge_id = c.id), 0)) as open
        from public.charges c join public.units u on u.id = c.unit_id join public.buildings b on b.id = u.building_id
       where b.association_id = p_association_id and u.archived_at is null
       group by c.unit_id)
    select count(*) into v_n from bal where round(open, 2) = round(p_amount, 2);
    if v_n = 1 then
      with bal as (
        select c.unit_id, sum(c.amount - coalesce((select sum(pa.amount_applied) from public.payment_applications pa where pa.charge_id = c.id), 0)) as open
          from public.charges c join public.units u on u.id = c.unit_id join public.buildings b on b.id = u.building_id
         where b.association_id = p_association_id and u.archived_at is null
         group by c.unit_id)
      select bal.unit_id into unit_id from bal where round(open, 2) = round(p_amount, 2);
      confidence := 0.50; reason := 'Amount matches balance';
    end if;
  end if;

  if unit_id is not null then
    select occ.owner_id into owner_id from public.occupancies occ
     where occ.unit_id = lockbox_match_unit.unit_id and occ.status = 'current' and occ.occupancy_type = 'owner'
     order by occ.is_primary desc nulls last limit 1;
  end if;
end $$;


ALTER FUNCTION "public"."lockbox_match_unit"("p_association_id" "uuid", "p_unit" "text", "p_payer" "text", "p_amount" numeric, OUT "unit_id" "uuid", OUT "owner_id" "uuid", OUT "confidence" numeric, OUT "reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_audit_event"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
BEGIN
  INSERT INTO public.audit_logs (entity_type, entity_id, action, actor_id, actor_email, changes)
  VALUES (TG_TABLE_NAME, NEW.id, TG_OP, auth.uid(), (SELECT email FROM auth.users WHERE id = auth.uid()), to_jsonb(NEW));
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."log_audit_event"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_invitation_event"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  insert into public.permission_audit_log (
    actor_user_id, actor_portfolio_id, target_entity_type, target_entity_id,
    action, before_state, after_state
  ) values (
    auth.uid(), coalesce(new.portfolio_id, old.portfolio_id),
    'user_invitation', coalesce(new.id, old.id),
    case
      when tg_op = 'INSERT' then 'invitation_created'
      when tg_op = 'UPDATE' and new.status = 'accepted' and old.status = 'pending' then 'invitation_accepted'
      when tg_op = 'UPDATE' and new.status = 'revoked' and old.status = 'pending' then 'invitation_revoked'
      when tg_op = 'UPDATE' and new.status = 'expired' then 'invitation_expired'
      else 'invitation_update'
    end,
    case when tg_op = 'UPDATE' then to_jsonb(old) end,
    to_jsonb(new)
  );
  return new;
end;
$$;


ALTER FUNCTION "public"."log_invitation_event"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_owner_audit"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_changes jsonb;
  v_entity uuid;
  v_row jsonb;
begin
  if tg_op = 'UPDATE' then
    select jsonb_object_agg(n.key, jsonb_build_object(
      'from', case when n.key in ('taxpayer_id','bank_account_number','bank_routing_number') then '"[redacted]"'::jsonb else o.value end,
      'to',   case when n.key in ('taxpayer_id','bank_account_number','bank_routing_number') then '"[redacted]"'::jsonb else n.value end))
      into v_changes
    from jsonb_each(to_jsonb(old)) o
    join jsonb_each(to_jsonb(new)) n on n.key = o.key
    where o.value is distinct from n.value and n.key not in ('updated_at','updated_by');
    if v_changes is null then return new; end if;
  end if;
  v_row := to_jsonb(coalesce(new, old));
  if tg_table_name = 'owners' then
    v_entity := (v_row->>'id')::uuid;
  else
    v_entity := (v_row->>'owner_id')::uuid;
  end if;
  insert into public.audit_logs (entity_type, entity_id, action, actor_id, actor_email, changes)
  values ('owner', v_entity, lower(tg_op) || case when tg_table_name <> 'owners' then ':' || tg_table_name else '' end,
          auth.uid(), (select email from auth.users where id = auth.uid()), v_changes);
  return coalesce(new, old);
end $$;


ALTER FUNCTION "public"."log_owner_audit"() OWNER TO "postgres";


