CREATE OR REPLACE FUNCTION "public"."log_violation_event"("p_violation_id" "uuid", "p_note" "text", "p_new_status" "public"."violation_status", "p_owner_visible" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  insert into public.violation_updates (violation_id, note, new_status, created_by)
  values (p_violation_id, left(p_note, 2000), p_new_status, case when exists (select 1 from public.profiles where id = auth.uid()) then auth.uid() end);
  if p_owner_visible then
    update public.violations
       set owner_visible_history = coalesce(owner_visible_history, '[]'::jsonb) || jsonb_build_array(jsonb_build_object('at', now(), 'event', left(p_note, 500)))
     where id = p_violation_id;
  end if;
end;
