CREATE OR REPLACE FUNCTION "public"."maintenance_attachments_enforce_limit"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_count int;
begin
  if new.work_order_id is not null then
    perform pg_advisory_xact_lock(hashtextextended('maint-files:' || new.work_order_id::text, 0));
    select count(*) into v_count from public.maintenance_attachments where work_order_id = new.work_order_id;
  else
    perform pg_advisory_xact_lock(hashtextextended('maint-files:' || new.service_request_id::text, 0));
    select count(*) into v_count from public.maintenance_attachments
     where service_request_id = new.service_request_id and work_order_id is null;
  end if;
  if coalesce(v_count, 0) >= 12 then
    raise exception 'Limit of 12 files reached' using errcode = '23514';
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."maintenance_attachments_enforce_limit"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."maintenance_history_links_valid"("p_task_id" "uuid", "p_vendor_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$#variable_conflict use_column
begin
  return (select s.x from (

  select exists (
    select 1
    from public.maintenance_tasks mt
    join public.associations a on a.id = mt.association_id
    where mt.id = p_task_id
      and (
        p_vendor_id is null
        or exists (
          select 1 from public.vendors v
          where v.id = p_vendor_id and v.portfolio_id = a.portfolio_id
        )
      )
  )
  ) s(x) limit 1);
end$$;


