CREATE OR REPLACE FUNCTION "public"."maintenance_task_links_valid"("p_association_id" "uuid", "p_vendor_id" "uuid", "p_assigned_staff_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$#variable_conflict use_column
begin
  return (select s.x from (

  select exists (
    select 1
    from public.associations a
    where a.id = p_association_id
      and a.portfolio_id is not null
      and (
        p_vendor_id is null
        or exists (
          select 1 from public.vendors v
          where v.id = p_vendor_id and v.portfolio_id = a.portfolio_id
        )
      )
      and (
        p_assigned_staff_id is null
        or exists (
          select 1 from public.profiles p
          where p.id = p_assigned_staff_id and p.portfolio_id = a.portfolio_id
        )
      )
  )
  ) s(x) limit 1);
end$$;


ALTER FUNCTION "public"."maintenance_task_links_valid"("p_association_id" "uuid", "p_vendor_id" "uuid", "p_assigned_staff_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."management_fee_collection_from_bill"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_due integer;
begin
  if tg_table_name = 'payable_bills' then
    v_due := round((new.amount - coalesce(new.credit_applied, 0)) * 100)::int;
    update public.management_fees mf
       set collected_cents = case when new.status = 'paid' and new.archived_at is null then v_due else 0 end,
           delinquent_cents = case when new.status in ('paid', 'void') or new.archived_at is not null then 0 else v_due end
     where mf.bill_id = new.id;
    return new;
  end if;

  if new.bill_id is not null then
    select case when pb.status = 'paid' and pb.archived_at is null then round((pb.amount - coalesce(pb.credit_applied, 0)) * 100)::int else 0 end,
           case when pb.status in ('paid', 'void') or pb.archived_at is not null then 0 else round((pb.amount - coalesce(pb.credit_applied, 0)) * 100)::int end
      into new.collected_cents, new.delinquent_cents
      from public.payable_bills pb
     where pb.id = new.bill_id;
    new.collected_cents := coalesce(new.collected_cents, 0);
    new.delinquent_cents := coalesce(new.delinquent_cents, 0);
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."management_fee_collection_from_bill"() OWNER TO "postgres";


