CREATE OR REPLACE FUNCTION "public"."mark_owner_statement_delivery"("p_batch_id" "uuid", "p_sent_statement_ids" "uuid"[], "p_failed_statement_ids" "uuid"[] DEFAULT '{}'::"uuid"[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_portfolio uuid;
  v_sent integer;
  v_failed integer;
begin
  select a.portfolio_id into v_portfolio
    from public.statement_batches b join public.associations a on a.id = b.association_id
   where b.id = p_batch_id;
  if v_portfolio is null or not public.can_manage_finance(v_portfolio) then
    raise exception 'Permission denied' using errcode = '42501';
  end if;
  if not public.can_view_association_row((select association_id from public.statement_batches where id = p_batch_id)) then
    raise exception 'Permission denied' using errcode = '42501';
  end if;

  update public.owner_statements
     set delivery_status = 'queued', sent_at = now(), updated_at = now()
   where batch_id = p_batch_id and id = any(coalesce(p_sent_statement_ids, '{}'));
  get diagnostics v_sent = row_count;

  update public.owner_statements
     set delivery_status = 'failed', updated_at = now()
   where batch_id = p_batch_id and id = any(coalesce(p_failed_statement_ids, '{}'));
  get diagnostics v_failed = row_count;

  update public.statement_batches
     set sent_count = v_sent,
         failed_count = v_failed,
         status = case when v_sent = 0 and v_failed > 0 then 'failed'
                       when v_failed > 0 then 'partial'
                       else 'sent' end,
         updated_at = now()
   where id = p_batch_id;
end;
$$;


ALTER FUNCTION "public"."mark_owner_statement_delivery"("p_batch_id" "uuid", "p_sent_statement_ids" "uuid"[], "p_failed_statement_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_webhook_delivery"("p_delivery_id" "uuid", "p_success" boolean, "p_response_code" integer DEFAULT NULL::integer, "p_response_body" "text" DEFAULT NULL::"text", "p_error_message" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  d public.webhook_deliveries;
  ep public.webhook_endpoints;
  retry_delay_seconds integer;
begin
  select * into d from public.webhook_deliveries where id = p_delivery_id for update;
  if not found then return; end if;

  select * into ep from public.webhook_endpoints where id = d.endpoint_id for update;

  if p_success then
    update public.webhook_deliveries
       set status = 'succeeded',
           attempts = attempts + 1,
           last_attempt_at = now(),
           succeeded_at = now(),
           response_code = p_response_code,
           response_body = left(coalesce(p_response_body, ''), 4000),
           error_message = null
     where id = p_delivery_id;

    update public.webhook_endpoints
       set failure_count = 0,
           last_success_at = now(),
           disabled_until = null
     where id = d.endpoint_id;
  else
    -- Exponential backoff: 1m, 5m, 25m, 2h, capped; abandon after 8 attempts
    retry_delay_seconds := least(power(5, d.attempts)::integer * 60, 7200);

    update public.webhook_deliveries
       set attempts = attempts + 1,
           last_attempt_at = now(),
           response_code = p_response_code,
           response_body = left(coalesce(p_response_body, ''), 4000),
           error_message = left(coalesce(p_error_message, ''), 1000),
           status = case when attempts + 1 >= 8 then 'abandoned'::public.webhook_delivery_status
                         else 'retrying'::public.webhook_delivery_status end,
           next_attempt_at = now() + make_interval(secs => retry_delay_seconds)
     where id = p_delivery_id;

    update public.webhook_endpoints
       set failure_count = failure_count + 1,
           last_failure_at = now(),
           last_failure_message = left(coalesce(p_error_message, ''), 500),
           -- Auto-disable endpoint for 1 hour after 10 consecutive failures
           disabled_until = case when failure_count + 1 >= 10 then now() + interval '1 hour' else disabled_until end
     where id = d.endpoint_id;
  end if;
end;
$$;


ALTER FUNCTION "public"."mark_webhook_delivery"("p_delivery_id" "uuid", "p_success" boolean, "p_response_code" integer, "p_response_body" "text", "p_error_message" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."match_bank_transaction"("p_id" "uuid", "p_journal_line_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  t public.bank_transactions := public.app_bank_transaction_for_update(p_id);
  b public.bank_accounts;
begin
  select * into b from public.bank_accounts where id = t.bank_account_id;
  if not exists (select 1 from public.journal_lines jl join public.journal_entries je on je.id = jl.entry_id
                  where jl.id = p_journal_line_id and je.posted and je.portfolio_id = b.portfolio_id
                    and jl.gl_account_id = b.gl_account_id and jl.association_id is not distinct from b.association_id
                    and round(jl.debit_amount - jl.credit_amount, 2) = round(-t.amount, 2)) then
    raise exception 'That ledger line is not on this bank account for the same amount' using errcode = '22023';
  end if;
  if exists (select 1 from public.bank_transactions where matched_journal_line_id = p_journal_line_id) then
    raise exception 'That ledger line is already matched to another bank transaction' using errcode = '22023';
  end if;
  update public.bank_transactions set matched_journal_line_id = p_journal_line_id, matched_at = now(),
         match_method = 'manual', reviewed = true, ignored_at = null
   where id = t.id;
end $$;


ALTER FUNCTION "public"."match_bank_transaction"("p_id" "uuid", "p_journal_line_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."match_bank_transaction_to_deposit"("p_id" "uuid", "p_deposit_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare t public.bank_transactions := public.app_bank_transaction_for_update(p_id);
begin
  if t.matched_bank_deposit_id is not null then raise exception 'This transaction is already matched' using errcode = '22023'; end if;
  if t.amount >= 0 then raise exception 'Only money coming in can match a deposit' using errcode = '22023'; end if;
  if not exists (select 1 from public.bank_deposits d where d.id = p_deposit_id and d.bank_account_id = t.bank_account_id
                    and d.voided_at is null and round(d.amount, 2) = round(-t.amount, 2)) then
    raise exception 'That deposit is not on this bank account for the same amount' using errcode = '22023';
  end if;
  if exists (select 1 from public.bank_transactions where matched_bank_deposit_id = p_deposit_id) then
    raise exception 'That deposit is already matched to another bank transaction' using errcode = '22023';
  end if;
  update public.bank_transactions set matched_bank_deposit_id = p_deposit_id, matched_at = now(),
         match_method = 'deposit', reviewed = true, ignored_at = null
   where id = t.id;
end $$;


ALTER FUNCTION "public"."match_bank_transaction_to_deposit"("p_id" "uuid", "p_deposit_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."match_lockbox_item"("p_item" "uuid", "p_unit_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare s record; v_owner uuid;
begin
  select * into s from public.lockbox_item_scope(p_item);
  if p_unit_id is not null and not exists (
       select 1 from public.units u join public.buildings b on b.id = u.building_id
        where u.id = p_unit_id and b.association_id = s.association_id and u.archived_at is null) then
    raise exception 'Choose a unit in this association' using errcode = '22023';
  end if;
  select occ.owner_id into v_owner from public.occupancies occ
   where occ.unit_id = p_unit_id and occ.status = 'current' and occ.occupancy_type = 'owner'
   order by occ.is_primary desc nulls last limit 1;
  update public.lockbox_items
     set unit_id = p_unit_id, owner_id = v_owner, manually_matched = true,
         matched_confidence = case when p_unit_id is null then null else 1 end,
         match_reason = case when p_unit_id is null then null else 'Chosen by staff' end,
         rejected = false, rejection_reason = null, post_error = null
   where id = p_item;
  perform public.refresh_lockbox_batch_status(s.batch_id);
end $$;


ALTER FUNCTION "public"."match_lockbox_item"("p_item" "uuid", "p_unit_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."me"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
#variable_conflict use_column
begin
  return (select s.x from (
  select jsonb_build_object(
    'auth_user_id', auth.uid(),
    'email', (select email from auth.users where id = auth.uid()),
    'profile', (select to_jsonb(p) from public.profiles p where p.id = auth.uid()),
    'portfolio', (
      select case
        when public.is_any_staff() or public.is_company_admin() or public.is_platform_operator()
          then to_jsonb(po) - 'ai_api_key' - 'ai_api_key_ciphertext' - 'ai_endpoint'
        else jsonb_build_object(
          'id', po.id, 'company_name', po.company_name, 'slug', po.slug,
          'logo_url', po.logo_url, 'favicon_url', po.favicon_url, 'brand_color', po.brand_color,
          'brand_email', po.brand_email, 'website', po.website, 'public_website', po.public_website,
          'phone_number', po.phone_number, 'texting_phone_number', po.texting_phone_number,
          'support_email', po.support_email, 'support_phone', po.support_phone,
          'address_street', po.address_street, 'address_city', po.address_city,
          'address_state', po.address_state, 'address_zip', po.address_zip,
          'archived_at', po.archived_at, 'suspended_at', po.suspended_at)
      end
      from public.portfolios po
      where po.id = public.current_portfolio_id()
    ),
    'role_name', public.current_role_name(),
    'is_platform_operator', public.is_platform_operator(), 'platform_operator_role', (select po.role from public.platform_operators po where po.auth_user_id = auth.uid() and po.active limit 1),
    'is_company_admin', public.is_company_admin(),
    'is_full_access_staff', public.is_full_access_staff(),
    'is_finance_staff', public.is_finance_staff(),
    'is_staff', public.is_staff(),
    'is_board', public.is_board_user(),
    'is_resident', public.is_portal_resident(),
    'is_tenant', public.is_tenant_user(),
    'owner_id', public.current_owner_id(),
    'owner_ids', array(select public.current_owner_ids()),
    'tenant_id', public.current_tenant_id(),
    'vendor_id', public.current_vendor_id(),
    'vendor_ids', array(select public.current_vendor_ids()),
    'board_association_ids', array(select public.current_board_association_ids()),
    'resident_association_ids', array(select public.current_resident_association_ids()),
    'resident_unit_ids', array(select public.current_resident_unit_ids()),
    'tenant_association_ids', array(select public.current_tenant_association_ids()),
    'tenant_unit_ids', array(select public.current_tenant_unit_ids())
  )
  ) s(x) limit 1);
end
$$;


ALTER FUNCTION "public"."me"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."me"() IS 'Single-call identity bootstrap, including separate owner and resident-occupant scopes.';



CREATE OR REPLACE FUNCTION "public"."meeting_attendees_only_while_open"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_status text;
begin
  if public.app_is_repair_session() then
    return case when tg_op = 'DELETE' then old else new end;
  end if;
  select m.status::text into v_status
    from public.meetings m
   where m.id = case when tg_op = 'DELETE' then old.meeting_id else new.meeting_id end
   for share;
  if v_status in ('completed', 'cancelled') then
    raise exception 'Attendance cannot change after the meeting is completed or cancelled' using errcode = '55000';
  end if;
  if tg_op = 'UPDATE' and new.meeting_id is distinct from old.meeting_id then
    select m.status::text into v_status from public.meetings m where m.id = old.meeting_id for share;
    if v_status in ('completed', 'cancelled') then
      raise exception 'Attendance cannot change after the meeting is completed or cancelled' using errcode = '55000';
    end if;
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end
$$;


ALTER FUNCTION "public"."meeting_attendees_only_while_open"() OWNER TO "postgres";


