CREATE OR REPLACE FUNCTION "public"."message_notify"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  t public.message_threads; v_assoc text; v_company text; v_support text; v_slug text; v_base text;
  v_custom text; v_custom_verified timestamptz; v_link text;
  v_to text; v_to_name text; v_text text; v_html text; r record; v_assignee_ok boolean;
begin
  if new.internal then return new; end if;
  begin
    select * into t from public.message_threads where id = new.thread_id;
    select a.name into v_assoc from public.associations a where a.id = t.association_id;
    select p.company_name, p.support_email, p.slug, p.custom_domain, p.custom_domain_verified_at
      into v_company, v_support, v_slug, v_custom, v_custom_verified
      from public.portfolios p where p.id = t.portfolio_id;
    v_base := case
      when v_custom is not null and v_custom_verified > now() - interval '3 hours' then 'https://' || v_custom
      when v_slug ~ '^[a-z0-9](?:[a-z0-9-]{0,30}[a-z0-9])$' then 'https://' || v_slug || '.portier369.com'
      else rtrim(public.app_portal_url(), '/')
    end;
    if new.author_role = 'resident' then
      v_link := v_base || '/inbox/' || t.id;
      select exists (select 1 from public.profiles p where p.id = t.assigned_to and p.disabled_at is null and btrim(coalesce(p.email, '')) like '%@%') into v_assignee_ok;
      v_text := coalesce(new.author_name, 'A resident') || coalesce(' (' || v_assoc || ')', '') || ' wrote:' || chr(10) || chr(10)
             || new.body || chr(10) || chr(10) || 'Reply from the Inbox: ' || v_link;
      v_html := '<div style="font-family:system-ui,-apple-system,Segoe UI,Arial,sans-serif;white-space:pre-wrap;line-height:1.6;color:#111827">'
             || replace(replace(replace(v_text, '&', '&amp;'), '<', '&lt;'), '>', '&gt;') || '</div>';
      for r in
        select distinct lower(btrim(e)) as email from (
          select p.email as e from public.profiles p where p.id = t.assigned_to and p.disabled_at is null
          union all
          select pr.email from public.association_managers am join public.profiles pr on pr.id = am.user_id
           where not v_assignee_ok and am.association_id = t.association_id and am.ended_at is null and pr.disabled_at is null
          union all
          select pr.email from public.profiles pr
           where not v_assignee_ok and pr.portfolio_id = t.portfolio_id and pr.hoa_role = 'manager' and pr.disabled_at is null
             and not exists (select 1 from public.association_managers own where own.user_id = pr.id)
             and not exists (select 1 from public.association_managers am where am.association_id = t.association_id and am.ended_at is null)
          union all select v_support where not v_assignee_ok
        ) x where e is not null and btrim(e) like '%@%'
      loop
        insert into public.email_queue (to_email, subject, body, association_id, portfolio_id, from_address, from_name, idempotency_key)
        values (r.email, 'New message: ' || t.subject, v_html, t.association_id, t.portfolio_id, 'hello@portier369.com',
                v_company, 'msg:' || new.id || ':' || r.email)
        on conflict do nothing;
      end loop;
    else
      v_link := v_base || case when t.owner_id is not null then '/portal/messages/' else '/resident/messages/' end || t.id;
      if t.owner_id is not null then select email, full_name into v_to, v_to_name from public.owners where id = t.owner_id;
      else select email, btrim(coalesce(first_name, '') || ' ' || coalesce(last_name, '')) into v_to, v_to_name from public.tenants where id = t.tenant_id; end if;
      if v_to is not null and btrim(v_to) like '%@%' then
        v_text := 'Hi ' || coalesce(nullif(v_to_name, ''), 'there') || ',' || chr(10) || chr(10)
               || coalesce(v_company, 'Your management company') || ' replied about "' || t.subject || '":' || chr(10) || chr(10)
               || new.body || chr(10) || chr(10) || 'Read the conversation and reply: ' || v_link;
        v_html := '<div style="font-family:system-ui,-apple-system,Segoe UI,Arial,sans-serif;white-space:pre-wrap;line-height:1.6;color:#111827">'
               || replace(replace(replace(v_text, '&', '&amp;'), '<', '&lt;'), '>', '&gt;') || '</div>';
        insert into public.email_queue (to_email, to_name, subject, body, association_id, portfolio_id, from_address, from_name, reply_to, owner_id, idempotency_key)
        values (lower(btrim(v_to)), nullif(v_to_name, ''), 'Re: ' || t.subject, v_html, t.association_id, t.portfolio_id, 'hello@portier369.com',
                v_company, v_support, t.owner_id, 'msg:' || new.id)
        on conflict do nothing;
      end if;
    end if;
  exception when others then
    begin
      insert into public.communications_log (portfolio_id, association_id, channel, direction, status, subject, body, error_message)
      values (t.portfolio_id, t.association_id, 'email', 'outbound', 'failed',
              'Email not sent for message: ' || coalesce(t.subject, 'conversation'),
              'The email about a new message in "' || coalesce(t.subject, 'a conversation') || '" was not sent. '
                || 'Open the conversation in the Inbox to follow up: ' || coalesce(v_base, '') || '/inbox/' || t.id,
              left(sqlerrm, 500));
    exception when others then
      raise warning 'message_notify failed for % and could not be logged: %', new.id, sqlerrm;
    end;
  end;
  return new;
end $_$;


ALTER FUNCTION "public"."message_notify"() OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."message_threads" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "portfolio_id" "uuid" NOT NULL,
    "association_id" "uuid" NOT NULL,
    "unit_id" "uuid",
    "owner_id" "uuid",
    "tenant_id" "uuid",
    "subject" "text" NOT NULL,
    "status" "text" DEFAULT 'open'::"text" NOT NULL,
    "assigned_to" "uuid",
    "started_by_role" "text" NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "last_message_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "last_message_preview" "text",
    "last_message_role" "text",
    "resident_unread" boolean DEFAULT false NOT NULL,
    "staff_unread" boolean DEFAULT false NOT NULL,
    "first_response_due_at" timestamp with time zone,
    "acknowledged_at" timestamp with time zone,
    "closed_at" timestamp with time zone,
    CONSTRAINT "message_threads_check" CHECK ((("owner_id" IS NULL) <> ("tenant_id" IS NULL))),
    CONSTRAINT "message_threads_last_message_role_check" CHECK (("last_message_role" = ANY (ARRAY['resident'::"text", 'staff'::"text"]))),
    CONSTRAINT "message_threads_started_by_role_check" CHECK (("started_by_role" = ANY (ARRAY['resident'::"text", 'staff'::"text"]))),
    CONSTRAINT "message_threads_status_check" CHECK (("status" = ANY (ARRAY['open'::"text", 'closed'::"text"]))),
    CONSTRAINT "message_threads_subject_check" CHECK ((("length"("btrim"("subject")) >= 1) AND ("length"("btrim"("subject")) <= 150)))
);


ALTER TABLE "public"."message_threads" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."message_thread_access"("p_thread" "uuid", "p_as" "text", OUT "role" "text", OUT "thread" "public"."message_threads") RETURNS "record"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_staff boolean; v_resident boolean;
begin
  if auth.uid() is null then raise exception 'Authentication required' using errcode = '42501'; end if;
  select * into thread from public.message_threads where id = p_thread for update;
  if not found then raise exception 'Conversation not found' using errcode = 'P0002'; end if;
  v_staff := public.is_messaging_staff() and public.can_access_portfolio(thread.portfolio_id)
             and public.can_manage_association(thread.association_id);
  v_resident := (thread.owner_id is not null and thread.owner_id in (select public.current_owner_ids()))
             or (thread.tenant_id is not null and thread.tenant_id in (select public.current_tenant_ids()));
  if p_as = 'resident' and v_resident then role := 'resident';
  elsif p_as = 'staff' and v_staff then role := 'staff';
  else raise exception 'Conversation not found' using errcode = 'P0002';
  end if;
end $$;


ALTER FUNCTION "public"."message_thread_access"("p_thread" "uuid", "p_as" "text", OUT "role" "text", OUT "thread" "public"."message_threads") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."message_thread_assignees"("p_thread" "uuid") RETURNS TABLE("id" "uuid", "name" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare t public.message_threads;
begin
  select * into t from public.message_threads where message_threads.id = p_thread;
  if not found or not public.is_messaging_staff() or not public.can_access_portfolio(t.portfolio_id)
     or not public.can_manage_association(t.association_id) then
    return;
  end if;
  return query
    select p.id, coalesce(nullif(btrim(p.full_name), ''), nullif(btrim(p.display_name), ''), p.email)
      from public.profiles p
     where public.can_be_assigned_message_thread(p.id, t.portfolio_id, t.association_id)
     order by 2;
end $$;


ALTER FUNCTION "public"."message_thread_assignees"("p_thread" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."metrics_monthly_trend"("p_months" "jsonb", "p_association_id" "uuid" DEFAULT NULL::"uuid", "p_portfolio_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    SET "plan_cache_mode" TO 'force_generic_plan'
    AS $$
declare
  m jsonb;
  v_from date;
  v_to date;
  v_start timestamptz;
  v_end timestamptz;
  v_ids uuid[] := case when p_association_id is null then null else array[p_association_id] end;
  v_charges numeric;
  v_payments numeric;
  v_ar numeric;
  v_overdue numeric;
  v_delinquent numeric;
  v_income numeric;
  v_expense numeric;
  v_wo_opened bigint;
  v_wo_completed bigint;
  v_violations bigint;
  v_out jsonb := '[]'::jsonb;
  v_ord bigint := 0;
  v_receivables jsonb;
begin
  if jsonb_typeof(p_months) is distinct from 'array' or jsonb_array_length(p_months) > 36 then
    raise exception 'p_months must be a list of at most 36 months' using errcode = '22023';
  end if;

  -- Every month end's receivables in one pass (was one query per month).
  select coalesce(jsonb_object_agg(s.ord::text, jsonb_build_array(s.ar_total, s.overdue_total, s.delinquent_units)), '{}'::jsonb)
    into v_receivables
    from public.receivable_summary_by_months(v_ids, p_months) s;

  for m in select value from jsonb_array_elements(p_months) loop
    v_ord := v_ord + 1;
    v_from := (m->>'from')::date;
    v_to := (m->>'to')::date;
    v_start := (m->>'start')::timestamptz;
    v_end := (m->>'end')::timestamptz;
    if v_from is null or v_to is null or v_start is null or v_end is null or v_to < v_from or v_end <= v_start then
      raise exception 'Each month needs from <= to and start < end' using errcode = '22023';
    end if;

    select coalesce(sum(b.charges_total), 0), coalesce(sum(b.payments_total), 0)
      into v_charges, v_payments
      from public.billing_collection_totals(v_from, v_to, v_ids) b;

    -- Balances as they stood at the end of the month.
    v_ar := coalesce((v_receivables->v_ord::text->>0)::numeric, 0);
    v_overdue := coalesce((v_receivables->v_ord::text->>1)::numeric, 0);
    v_delinquent := coalesce((v_receivables->v_ord::text->>2)::numeric, 0);

    -- Income is credit-normal, the expense section debit-normal.
    select coalesce(sum(case when j.account_type in ('income', 'other_income') then j.credit_total - j.debit_total else 0 end), 0),
           coalesce(sum(case when j.account_type in ('income', 'other_income') then 0 else j.debit_total - j.credit_total end), 0)
      into v_income, v_expense
      from public.journal_line_totals(p_portfolio_id, null, v_ids,
             array['income', 'other_income', 'expense', 'cost_of_goods_sold', 'other_expense', 'non_operating'],
             v_from, v_to) j;

    select count(*) into v_wo_opened
      from public.work_orders w
     where w.archived_at is null and w.created_at >= v_start and w.created_at < v_end
       and (p_association_id is null or w.association_id = p_association_id);

    select count(*) into v_wo_completed
      from public.work_orders w
     where w.archived_at is null and w.completed_date >= v_from and w.completed_date <= v_to
       and (p_association_id is null or w.association_id = p_association_id);

    select count(*) into v_violations
      from public.violations v
     where v.archived_at is null and v.created_at >= v_start and v.created_at < v_end
       and (p_association_id is null or v.association_id = p_association_id);

    v_out := v_out || jsonb_build_array(jsonb_build_object(
      'from', v_from,
      'charged', v_charges,
      'collected', v_payments,
      'ar_total', v_ar,
      'overdue_total', v_overdue,
      'delinquent_units', v_delinquent,
      'income', v_income,
      'expense', v_expense,
      'wo_opened', v_wo_opened,
      'wo_completed', v_wo_completed,
      'violations_opened', v_violations
    ));
  end loop;

  return v_out;
end
$$;


ALTER FUNCTION "public"."metrics_monthly_trend"("p_months" "jsonb", "p_association_id" "uuid", "p_portfolio_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."move_association_private_fields"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if tg_op = 'UPDATE' and public.is_self_service_caller() then
    new.management_end_reason := null;
    new.maintenance_notes := null;
    new.description := null;
    return new;
  end if;
  if new.management_end_reason is not null or new.description is not null then
    insert into public.association_private (association_id, management_end_reason, description, updated_at)
    values (new.id, nullif(btrim(new.management_end_reason), ''), nullif(btrim(new.description), ''), now())
    on conflict (association_id) do update set
      management_end_reason = case when new.management_end_reason is not null then excluded.management_end_reason else public.association_private.management_end_reason end,
      description = case when new.description is not null then excluded.description else public.association_private.description end,
      updated_at = now();
    new.management_end_reason := null;
    new.description := null;
  end if;
  if new.maintenance_notes is not null then
    insert into public.association_vendor_private (association_id, maintenance_notes, updated_at)
    values (new.id, nullif(btrim(new.maintenance_notes), ''), now())
    on conflict (association_id) do update set
      maintenance_notes = excluded.maintenance_notes,
      updated_at = now();
    new.maintenance_notes := null;
  end if;
  return new;
end $$;


