CREATE OR REPLACE FUNCTION "public"."move_owner_form_submission_notes"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_key text := 'app.ofs_note_' || replace(new.id::text, '-', '');
  v_note text := current_setting(v_key, true);
begin
  if v_note like 'n:%' then
    perform set_config(v_key, '', true);
    -- Owners, tenants, board members and vendors never write management's notes.
    if not public.is_self_service_caller() then
      insert into public.owner_form_submission_private (submission_id, notes, updated_at)
      values (new.id, nullif(btrim(substr(v_note, 3)), ''), now())
      on conflict (submission_id) do update set notes = excluded.notes, updated_at = now();
    end if;
  end if;
  return null;
end
$$;


