CREATE OR REPLACE FUNCTION "public"."open_board_approval_request"("p_portfolio_id" "uuid", "p_association_id" "uuid", "p_vendor_id" "uuid", "p_request_type" "text", "p_title" "text", "p_description" "text", "p_amount" numeric, "p_due_date" "date") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  settings_row public.board_approval_settings;
  member_ids uuid[];
  member_count integer;
  required_count integer;
  v_scheme public.voting_scheme;
  request_id uuid;
begin
  select * into settings_row from public.board_approval_settings where association_id = p_association_id;
  select coalesce(array_agg(bm.id order by bm.id), '{}'::uuid[])
    into member_ids
    from public.board_members bm
   where bm.association_id = p_association_id
     and bm.active
     and (coalesce(cardinality(settings_row.default_board_member_ids), 0) = 0 or bm.id = any(settings_row.default_board_member_ids));
  member_count := coalesce(cardinality(member_ids), 0);
  if member_count = 0 then raise exception 'No active board approvers are configured for this association'; end if;

  v_scheme := coalesce(settings_row.default_voting_scheme, 'majority_approval_required'::public.voting_scheme);
  required_count := case v_scheme
    when 'any_one_approver'::public.voting_scheme then 1
    when 'unanimous_approval_required'::public.voting_scheme then member_count
    when 'percentage_required'::public.voting_scheme then greatest(1, ceil(member_count * coalesce(settings_row.default_percentage_required, 100) / 100.0)::integer)
    else floor(member_count / 2.0)::integer + 1
  end;

  insert into public.approval_requests (
    portfolio_id, association_id, vendor_id, request_type, title, description,
    requested_by_name, requested_by_email, amount, due_date, status,
    voting_scheme, required_votes, signatures_required, board_member_ids,
    percentage_required, requested_at
  ) values (
    p_portfolio_id, p_association_id, p_vendor_id, p_request_type, p_title, p_description,
    coalesce((select full_name from public.profiles where id = auth.uid()), 'Management staff'),
    (select email from auth.users where id = auth.uid()), p_amount, p_due_date, 'pending',
    v_scheme, required_count, coalesce(settings_row.signatures_required, true),
    member_ids, settings_row.default_percentage_required, now()
  ) returning id into request_id;
  return request_id;
end;
$$;


ALTER FUNCTION "public"."open_board_approval_request"("p_portfolio_id" "uuid", "p_association_id" "uuid", "p_vendor_id" "uuid", "p_request_type" "text", "p_title" "text", "p_description" "text", "p_amount" numeric, "p_due_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."open_violation"("p_association_id" "uuid", "p_unit_id" "uuid", "p_house_rule_id" "uuid", "p_title" "text", "p_description" "text", "p_date_observed" "date", "p_violation_type" "public"."violation_type") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_rule public.house_rules; v_owner uuid; v_cure_days integer; v_first_days integer; v_id uuid; v_observed date := coalesce(p_date_observed, public.association_local_date(p_association_id));
begin
  if not public.can_manage_violations(p_association_id) then raise exception 'Permission denied' using errcode = '42501'; end if;
  if p_unit_id is not null and not exists (select 1 from public.units u join public.buildings b on b.id = u.building_id where u.id = p_unit_id and b.association_id = p_association_id and u.archived_at is null) then
    raise exception 'Unit is not in this association' using errcode = '22023';
  end if;
  if p_house_rule_id is not null then
    select * into v_rule from public.house_rules where id = p_house_rule_id and association_id = p_association_id and archived_at is null;
    if not found then raise exception 'Rule not found in this association' using errcode = 'P0002'; end if;
  end if;
  if coalesce(nullif(btrim(coalesce(p_title, '')), ''), v_rule.title) is null then raise exception 'Choose a rule or enter a title' using errcode = '22023'; end if;
  if v_observed > public.association_local_date(p_association_id) then raise exception 'Observed date cannot be in the future' using errcode = '22023'; end if;
  if p_unit_id is not null then
    select occ.owner_id into v_owner from public.occupancies occ
     where occ.unit_id = p_unit_id and occ.status = 'current' and occ.owner_id is not null
     order by occ.is_primary desc nulls last limit 1;
  end if;
  select coalesce(s.default_cure_days, 14) into v_cure_days from (select 1) one left join public.association_violation_settings s on s.association_id = p_association_id;
  select days_after_previous into v_first_days from public.violation_schedule(p_association_id, p_house_rule_id) where ordinal = 1;
  insert into public.violations (association_id, unit_id, owner_id, house_rule_id, violation_type, status, title, description, date_observed, reported_date, cure_deadline, due_date, governing_document_reference, next_followup_on, created_by)
  values (p_association_id, p_unit_id, v_owner, p_house_rule_id, coalesce(p_violation_type, v_rule.default_violation_type, 'other'), 'open',
    left(coalesce(nullif(btrim(coalesce(p_title, '')), ''), v_rule.title), 200),
    left(coalesce(nullif(btrim(coalesce(p_description, '')), ''), v_rule.description), 4000),
    v_observed, public.association_local_date(p_association_id), v_observed + v_cure_days, v_observed + v_cure_days,
    case when v_rule.id is not null then v_rule.rule_number || ' — ' || v_rule.title end,
    case when v_first_days is not null then v_observed + v_first_days end,
    case when exists (select 1 from public.profiles where id = auth.uid()) then auth.uid() end)
  returning id into v_id;
  perform public.log_violation_event(v_id, 'Violation opened', 'open', true);
  return v_id;
end;
$$;


ALTER FUNCTION "public"."open_violation"("p_association_id" "uuid", "p_unit_id" "uuid", "p_house_rule_id" "uuid", "p_title" "text", "p_description" "text", "p_date_observed" "date", "p_violation_type" "public"."violation_type") OWNER TO "postgres";


