CREATE OR REPLACE FUNCTION "public"."owner_settings_company_from_owner"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_portfolio uuid;
begin
  select o.portfolio_id into v_portfolio from public.owners o where o.id = new.owner_id;
  if v_portfolio is null then
    raise exception 'Owner not found' using errcode = '23503';
  end if;
  new.portfolio_id := v_portfolio;
  return new;
end
$$;


ALTER FUNCTION "public"."owner_settings_company_from_owner"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."owner_unit_tenants"() RETURNS TABLE("id" "uuid", "unit_id" "uuid", "unit_number" "text", "first_name" "text", "last_name" "text", "email" "text", "phone" "text", "lease_start" "date", "lease_end" "date", "status" "text", "insurance_expiration" "date")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select t.id, t.unit_id, u.unit_number, t.first_name, t.last_name, t.email, t.phone,
         t.lease_start, t.lease_end, t.status, t.insurance_expiration
    from public.tenants t
    join public.units u on u.id = t.unit_id
   where t.archived_at is null
     and t.owner_id in (select public.current_owner_ids())
     and exists (
       select 1 from public.occupancies occ
        where occ.owner_id = t.owner_id
          and occ.unit_id = t.unit_id
          and occ.status = 'current'
          and occ.occupancy_type = 'owner')
   order by u.unit_number, t.lease_start desc nulls last, t.last_name;
$$;


ALTER FUNCTION "public"."owner_unit_tenants"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."owner_update_tenant_lease"("p_tenant_id" "uuid", "p_lease_start" "date", "p_lease_end" "date") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if not exists (select 1 from public.current_owner_ids()) then
    raise exception 'Owner access required' using errcode = '42501';
  end if;
  if p_lease_start is null then
    raise exception 'Enter the lease start date' using errcode = '22023';
  end if;
  if p_lease_end is not null and p_lease_end < p_lease_start then
    raise exception 'The lease end date must be on or after the start date' using errcode = '22023';
  end if;
  update public.tenants t
     set lease_start = p_lease_start, lease_end = p_lease_end, updated_at = now()
   where t.id = p_tenant_id
     and t.archived_at is null
     and t.owner_id in (select public.current_owner_ids())
     and exists (
       select 1 from public.occupancies occ
        where occ.owner_id = t.owner_id and occ.unit_id = t.unit_id
          and occ.status = 'current' and occ.occupancy_type = 'owner');
  if not found then
    raise exception 'That tenant is not on a unit you own' using errcode = '42501';
  end if;
end;
$$;


ALTER FUNCTION "public"."owner_update_tenant_lease"("p_tenant_id" "uuid", "p_lease_start" "date", "p_lease_end" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."owner_violation_hearing_window"("p_violation_id" "uuid") RETURNS TABLE("deadline" "date", "today" "date")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v public.violations%rowtype;
  v_days integer;
begin
  if auth.uid() is null then
    return;
  end if;
  select * into v
    from public.violations x
   where x.id = p_violation_id
     and x.owner_id in (select public.current_owner_ids())
     and x.archived_at is null;
  if not found then
    return;
  end if;
  select coalesce(s.hearing_request_days, 14) into v_days
    from (select 1) one left join public.association_violation_settings s on s.association_id = v.association_id;
  today := public.association_local_date(v.association_id, now());
  deadline := case when v.notice_sent_at is null then null
                   else public.association_local_date(v.association_id, v.notice_sent_at) + coalesce(v_days, 14) end;
  return next;
end
$$;


ALTER FUNCTION "public"."owner_violation_hearing_window"("p_violation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."owners_self_service_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare n public.owners;
begin
  if pg_trigger_depth() > 1 or not public.is_self_service_caller() then return new; end if;
  n := new;
  new := old;
  new.phone := n.phone; new.email := n.email; new.phone_numbers := n.phone_numbers; new.emails := n.emails;
  new.mailing_address := n.mailing_address; new.address_street := n.address_street; new.address_city := n.address_city;
  new.address_state := n.address_state; new.address_zip := n.address_zip;
  new.preferred_comm := n.preferred_comm; new.electronic_consent := n.electronic_consent;
  new.electronic_consent_date := n.electronic_consent_date;
  new.emergency_contact_name := n.emergency_contact_name; new.emergency_contact_phone := n.emergency_contact_phone;
  return new;
end $$;


ALTER FUNCTION "public"."owners_self_service_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."owners_set_portfolio_from_association"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_portfolio_id uuid;
begin
  if new.association_id is null then
    raise exception 'A homeowner must belong to an association.' using errcode = '23502';
  end if;

  -- Locked, so a concurrent move of the association to another company waits
  -- for this row (and then carries it along), or this waits for the move.
  select a.portfolio_id into v_portfolio_id
  from public.associations a
  where a.id = new.association_id
  for share;

  if not found then
    raise exception 'Association not found for this homeowner.' using errcode = '23503';
  end if;
  if v_portfolio_id is null then
    raise exception 'This association has no company, so it cannot have homeowners yet.' using errcode = '23502';
  end if;

  if tg_op = 'UPDATE' and new.association_id is distinct from old.association_id and (exists (
    select 1 from public.occupancies o
    where o.owner_id = new.id and o.association_id <> new.association_id
  ) or exists (
    select 1 from public.unit_owners uo
      join public.units u on u.id = uo.unit_id
      join public.buildings bl on bl.id = u.building_id
     where uo.owner_id = new.id and bl.association_id <> new.association_id
  )) then
    raise exception 'This homeowner has units in their current association. Add them as a new homeowner of the other association instead.'
      using errcode = '23514';
  end if;

  new.portfolio_id := v_portfolio_id;
  return new;
end;
$$;


ALTER FUNCTION "public"."owners_set_portfolio_from_association"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."parse_bank_payment_description"("p_text" "text", OUT "sender" "text", OUT "memo" "text", OUT "reference" "text") RETURNS "record"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  s text := btrim(regexp_replace(coalesce(p_text, ''), '\s+', ' ', 'g'));
  v_rest text;
  v_pos int;
  v_prev text;
begin
  if s = '' then return; end if;

  memo := nullif(btrim(substring(s from '"([^"]*)"')), '');
  if memo is null then
    memo := nullif(btrim(substring(s from '(?i)\mmemo\M\s*:?\s*([^;]+)')), '');
  end if;
  reference := nullif(btrim(substring(s from '(?i)(?:\mconf(?:irmation)?|\mref(?:erence)?)\s*(?:#|no\.?|number)?\s*:?\s*([A-Za-z0-9]+)')), '');

  v_pos := position(' from ' in lower(' ' || s || ' '));
  if v_pos > 0 then
    v_rest := substr(s, v_pos + 5);
  elsif s ~* '^zelle\s' then
    -- PNC: "Zelle NAME Transfer"
    v_rest := regexp_replace(s, '^zelle\s+', '', 'i');
    v_rest := regexp_replace(v_rest, '(?i)\s+(transfer|payment|credit)\M.*$', '');
  else
    return;
  end if;

  v_rest := regexp_replace(v_rest, '[;"].*$', '');
  v_rest := regexp_replace(v_rest, '(?i)\s+(for|on|ref|reference|conf|confirmation|memo)\M.*$', '');
  v_rest := regexp_replace(v_rest, '(?i)\s+(transfer|payment)$', '');
  -- Drop trailing confirmation codes and dates (a name has no digits).
  loop
    v_prev := v_rest;
    v_rest := regexp_replace(v_rest, '\s+\S*[0-9]\S*$', '');
    exit when v_rest = v_prev;
  end loop;
  if v_rest ~ '[0-9]' and v_rest !~ '\s' then v_rest := ''; end if;
  sender := nullif(btrim(regexp_replace(v_rest, '[,.]+$', '')), '');
end
$_$;


ALTER FUNCTION "public"."parse_bank_payment_description"("p_text" "text", OUT "sender" "text", OUT "memo" "text", OUT "reference" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pay_owner_payable"("p_id" "uuid", "p_bank_account_id" "uuid", "p_payment_date" "date", "p_method" "text", "p_reference" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  r public.owner_payables := public.app_owner_payable_for_update(p_id);
  v_bank public.bank_accounts;
  v_ap uuid;
  v_entry uuid;
  v_owner text := (select full_name from public.owners where id = r.owner_id);
begin
  if r.status <> 'approved' or r.paid_at is not null then
    raise exception 'Only an approved, unpaid payable can be paid' using errcode = '22023';
  end if;
  if coalesce(p_method, '') not in ('check', 'echeck', 'ach', 'cash', 'other') then
    raise exception 'Choose how it was paid' using errcode = '22023';
  end if;
  if p_payment_date is null then raise exception 'Choose the payment date' using errcode = '22023'; end if;
  if r.payable_date is not null and p_payment_date < r.payable_date then
    raise exception 'The payment date can''t be before the payable''s date (%)', r.payable_date using errcode = '22023';
  end if;
  if p_payment_date > coalesce(public.association_local_date(r.association_id, now()), current_date) + 90 then
    raise exception 'The payment date can be at most 90 days ahead' using errcode = '22023';
  end if;
  if exists (select 1 from public.owner_financial_details f where f.owner_id = r.owner_id and f.hold_payments) then
    raise exception 'Payments to % are on hold. Clear "Hold payments" on the homeowner first.', coalesce(v_owner, 'this homeowner') using errcode = '22023';
  end if;
  select * into v_bank from public.bank_accounts b
   where b.id = coalesce(p_bank_account_id, r.bank_account_id) and b.portfolio_id = r.portfolio_id and b.archived_at is null
     and (b.association_id is null or b.association_id = r.association_id);
  if not found then raise exception 'Choose a bank account of this association' using errcode = '22023'; end if;
  if v_bank.gl_account_id is null then raise exception 'The bank account has no cash GL account' using errcode = '22023'; end if;
  -- Pay from the same A/P account the approval credited.
  select jl.gl_account_id into v_ap from public.journal_lines jl join public.journal_entries je on je.id = jl.entry_id
   where je.source_type = 'owner_payable' and je.source_id = r.id and jl.credit_amount > 0 limit 1;
  if v_ap is null then raise exception 'This payable was never posted to the ledger; void it and enter it again' using errcode = '22023'; end if;

  insert into public.journal_entries (portfolio_id, entry_date, description, memo, reference_number, source_type, source_id, created_by, posted, posted_at)
  values (r.portfolio_id, p_payment_date, 'Homeowner payment: ' || coalesce(v_owner, 'homeowner'), r.memo,
          nullif(btrim(coalesce(p_reference, '')), ''), 'owner_payable_payment', r.id, auth.uid(), true, now())
  returning id into v_entry;
  insert into public.journal_lines (entry_id, association_id, gl_account_id, debit_amount, credit_amount, memo, sort_order)
  values (v_entry, r.association_id, v_ap, r.amount, 0, r.memo, 1),
         (v_entry, r.association_id, v_bank.gl_account_id, 0, r.amount, r.memo, 2);

  update public.owner_payables set status = 'paid', paid_at = (p_payment_date::timestamp + interval '12 hours') at time zone 'UTC', bank_account_id = v_bank.id,
         payment_method = p_method, payment_reference = nullif(btrim(coalesce(p_reference, '')), ''), updated_at = now()
   where id = r.id;
  insert into public.audit_logs (portfolio_id, entity_type, entity_id, action, actor_id, changes)
  values (r.portfolio_id, 'owner_payable', r.id, 'paid', auth.uid(), jsonb_build_object('amount', r.amount, 'method', p_method, 'reference', p_reference));
  return v_entry;
end $$;


ALTER FUNCTION "public"."pay_owner_payable"("p_id" "uuid", "p_bank_account_id" "uuid", "p_payment_date" "date", "p_method" "text", "p_reference" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."payable_bill_within_board_approved_po"("p_bill_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  po public.purchase_orders;
  v_billed numeric;
begin
  select po_row.* into po
    from public.payable_bills b
    join public.purchase_orders po_row on po_row.id = b.purchase_order_id
   where b.id = p_bill_id
     and po_row.portfolio_id = b.portfolio_id
     and po_row.association_id is not distinct from b.association_id;
  if po.id is null
     or po.archived_at is not null
     or po.status::text = 'cancelled'
     or po.approval_status <> 'approved'
     or not coalesce(po.approval_required, false)
     or po.approval_request_id is null
     or not exists (select 1 from public.approval_requests r
                     where r.id = po.approval_request_id
                       and r.request_type = 'purchase_order'
                       and r.status = 'approved'::public.approval_request_status) then
    return false;
  end if;
  select coalesce(sum(b.amount), 0) into v_billed
    from public.payable_bills b
   where b.purchase_order_id = po.id and b.status::text <> 'void' and b.archived_at is null;
  return v_billed <= po.po_total;
end $$;


ALTER FUNCTION "public"."payable_bill_within_board_approved_po"("p_bill_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."payable_bills_po_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  po public.purchase_orders;
  v_other numeric;
  v_live boolean := new.status::text <> 'void' and new.archived_at is null;
begin
  if new.purchase_order_id is null then
    return new;
  end if;
  if tg_op = 'UPDATE' and new.purchase_order_id is not distinct from old.purchase_order_id
     and new.amount is not distinct from old.amount and new.status is not distinct from old.status
     and new.archived_at is not distinct from old.archived_at
     and new.vendor_id is not distinct from old.vendor_id and new.association_id is not distinct from old.association_id then
    return new;
  end if;
  select * into po from public.purchase_orders where id = new.purchase_order_id for update;
  if po.id is null then
    raise exception 'Purchase order not found' using errcode = '23503';
  end if;
  if po.portfolio_id <> new.portfolio_id or po.association_id is distinct from new.association_id or po.vendor_id is distinct from new.vendor_id then
    raise exception 'The bill''s association and vendor must match purchase order %', po.number using errcode = '22023';
  end if;
  if v_live and (tg_op = 'INSERT' or new.purchase_order_id is distinct from old.purchase_order_id) then
    if po.status::text = 'cancelled' or po.approval_status <> 'approved' then
      raise exception 'Purchase order % is not approved (or was cancelled) — it can''t be billed', po.number using errcode = '22023';
    end if;
  end if;
  if v_live then
    select coalesce(sum(b.amount), 0) into v_other
      from public.payable_bills b
     where b.purchase_order_id = po.id and b.id <> new.id and b.status::text <> 'void' and b.archived_at is null;
    if v_other + new.amount > po.po_total then
      raise exception 'Bills on purchase order % would total $% — more than the PO''s $% (remaining $%)',
        po.number, to_char(v_other + new.amount, 'FM999,999,990.00'), to_char(po.po_total, 'FM999,999,990.00'),
        to_char(greatest(po.po_total - v_other, 0), 'FM999,999,990.00') using errcode = '22023';
    end if;
  end if;
  return new;
end $_$;


ALTER FUNCTION "public"."payable_bills_po_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."payable_bills_po_sync"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if tg_op in ('UPDATE', 'DELETE') then
    perform public.purchase_order_refresh_billed(old.purchase_order_id);
  end if;
  if tg_op = 'INSERT' or (tg_op = 'UPDATE' and new.purchase_order_id is distinct from old.purchase_order_id) then
    perform public.purchase_order_refresh_billed(new.purchase_order_id);
  end if;
  return null;
end $$;


ALTER FUNCTION "public"."payable_bills_po_sync"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."payer_name_matches"("p_payer" "text", "p_first" "text", "p_last" "text", "p_full" "text") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_payer text := public.payment_sender_key(p_payer);
  v_full text := public.payment_sender_key(p_full);
  v_tokens text[];
  v_head text[];
  v_tail text;
  v_n int;
  v_pairs text[][] := '{}';
  v_last text;
  v_part text;
  v_words text[];
  v_parts text[];
  v_shared_last text;
  f text;
  l text;
  i int;
begin
  if v_payer is null then return false; end if;
  if v_full is not null and v_payer = v_full then return true; end if;
  -- Words of two letters or more, without suffixes and titles.
  select coalesce(array_agg(w), '{}') into v_tokens
    from unnest(string_to_array(v_payer, ' ')) w
   where char_length(w) >= 2 and w not in ('JR', 'SR', 'II', 'III', 'IV', 'MR', 'MRS', 'MS', 'DR', 'AND');
  v_n := cardinality(v_tokens);
  if v_n < 2 then return false; end if;
  v_head := v_tokens[1:v_n - 1];
  v_tail := v_tokens[v_n];

  -- (first, last) pairs: each first-name word with the last name's last word.
  v_last := public.payment_sender_key(p_last);
  if v_last is not null then
    v_words := string_to_array(v_last, ' ');
    v_last := v_words[cardinality(v_words)];
    foreach f in array coalesce(string_to_array(public.payment_sender_key(p_first), ' '), '{}') loop
      if char_length(f) >= 2 and f <> 'AND' then v_pairs := v_pairs || array[[f, v_last]]; end if;
    end loop;
  end if;
  -- And each person named in the full name ("A & B", "A and B", "A / B").
  if v_full is not null then
    v_parts := regexp_split_to_array(upper(p_full), '\s*(?:&|/|\mAND\M|\+)\s*');
    v_words := string_to_array(public.payment_sender_key(v_parts[cardinality(v_parts)]), ' ');
    v_shared_last := v_words[cardinality(v_words)];
    foreach v_part in array v_parts loop
      v_words := coalesce(string_to_array(public.payment_sender_key(v_part), ' '), '{}');
      if cardinality(v_words) >= 2 then
        v_pairs := v_pairs || array[[v_words[1], v_words[cardinality(v_words)]]];
      elsif cardinality(v_words) = 1 and v_shared_last is not null then
        v_pairs := v_pairs || array[[v_words[1], v_shared_last]];
      end if;
    end loop;
  end if;

  for i in 1 .. coalesce(array_length(v_pairs, 1), 0) loop
    f := v_pairs[i][1];
    l := v_pairs[i][2];
    continue when f is null or l is null or f = l or char_length(f) < 2 or char_length(l) < 2;
    if f = any (v_tokens) and l = any (v_tokens) then return true; end if;
    -- Cut short at the end: the payer's last word starts the other name.
    if char_length(v_tail) >= 3 then
      if f = any (v_head) and char_length(v_tail) < char_length(l) and left(l, char_length(v_tail)) = v_tail then return true; end if;
      if l = any (v_head) and char_length(v_tail) < char_length(f) and left(f, char_length(v_tail)) = v_tail then return true; end if;
    end if;
  end loop;
  return false;
end
$$;


ALTER FUNCTION "public"."payer_name_matches"("p_payer" "text", "p_first" "text", "p_last" "text", "p_full" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."payment_applications_removal_credit_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if current_user in ('authenticated', 'anon') then
    if (tg_op in ('INSERT', 'UPDATE') and public.is_late_fee_removal_credit(new.payment_id))
       or (tg_op in ('UPDATE', 'DELETE') and public.is_late_fee_removal_credit(old.payment_id)) then
      raise exception 'This credit removed a late fee and can''t be changed.' using errcode = '42501';
    end if;
  elsif tg_op in ('INSERT', 'UPDATE') and exists (
      select 1 from public.payments p
       where p.id = new.payment_id and p.method = 'credit' and p.reference = 'Late fee removed'
         and p.charge_id is distinct from new.charge_id) then
    raise exception 'A removed late fee''s credit applies only to that fee.' using errcode = '22023';
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end
$$;


ALTER FUNCTION "public"."payment_applications_removal_credit_guard"() OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."payments" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "unit_id" "uuid" NOT NULL,
    "charge_id" "uuid",
    "amount" numeric(10,2) NOT NULL,
    "payment_date" "date" DEFAULT CURRENT_DATE NOT NULL,
    "method" "text" DEFAULT 'manual'::"text" NOT NULL,
    "reference" "text",
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid",
    "gl_account_id" "uuid",
    "bank_account_id" "uuid",
    "processor" "text",
    "processor_account_id" "text",
    "processor_payment_intent_id" "text",
    "reversed_at" timestamp with time zone,
    "reversed_by" "uuid",
    "reversal_reason" "text",
    "reversal_charge_id" "uuid",
    "bank_deposit_id" "uuid",
    CONSTRAINT "payments_amount_check" CHECK (("amount" > (0)::numeric)),
    CONSTRAINT "payments_credit_needs_account" CHECK ((("method" <> 'credit'::"text") OR ("gl_account_id" IS NOT NULL))),
    CONSTRAINT "payments_method_check" CHECK (("method" = ANY (ARRAY['manual'::"text", 'check'::"text", 'ach'::"text", 'card'::"text", 'other'::"text", 'cash'::"text", 'money_order'::"text", 'cashiers_check'::"text", 'wire'::"text", 'online'::"text", 'credit'::"text", 'zelle'::"text"])))
);


ALTER TABLE "public"."payments" OWNER TO "postgres";


COMMENT ON COLUMN "public"."payments"."reversed_at" IS 'Set when the receipt was reversed (returned / NSF). The reversal is the charge in reversal_charge_id.';



CREATE OR REPLACE FUNCTION "public"."payment_gl_accounts"("p_payment" "public"."payments", OUT "portfolio_id" "uuid", OUT "association_id" "uuid", OUT "cash" "uuid", OUT "ar" "uuid") RETURNS "record"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_assoc uuid; v_portfolio uuid;
begin
  v_assoc := public.unit_association_id(p_payment.unit_id);
  select a.portfolio_id into v_portfolio from public.associations a where a.id = v_assoc;
  portfolio_id := v_portfolio;
  association_id := v_assoc;
  ar := coalesce(public.app_gl_map(v_portfolio, v_assoc, 'accounts_receivable'), public.gl_pick(v_portfolio, v_assoc, array['accounts_receivable'], null, '%allowance%'));
  if p_payment.method = 'credit' then
    cash := p_payment.gl_account_id;
    return;
  end if;
  cash := coalesce(
    (select ba.gl_account_id from public.bank_accounts ba where ba.id = p_payment.bank_account_id and ba.gl_account_id is not null),
    (select ba.gl_account_id from public.bank_accounts ba
      where ba.association_id = v_assoc and ba.gl_account_id is not null and ba.archived_at is null
      order by (ba.fund_type is distinct from 'operating'), ba.created_at limit 1),
    public.app_gl_map(v_portfolio, v_assoc, 'undeposited_funds'),
    public.gl_pick(v_portfolio, v_assoc, array['cash'], '%undeposited%'),
    public.gl_pick(v_portfolio, v_assoc, array['cash']));
end $$;


ALTER FUNCTION "public"."payment_gl_accounts"("p_payment" "public"."payments", OUT "portfolio_id" "uuid", OUT "association_id" "uuid", OUT "cash" "uuid", OUT "ar" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."payment_plan_paid_amount"("p_plan_id" "uuid") RETURNS numeric
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$#variable_conflict use_column
begin
  return (select s.x from (

  select greatest(0,
           coalesce((select sum(pm.amount) from public.payments pm
                      where pm.unit_id = p.unit_id
                        and pm.created_at >= p.created_at
                        and (w.window_end is null or pm.created_at <= w.window_end)
                        and coalesce(pm.method, '') <> 'credit'
                        and pm.reversed_at is null
                        -- inside a later plan (not cancelled): that plan's
                        and not exists (select 1 from public.payment_plans o
                                         where o.unit_id = p.unit_id
                                           and o.id <> p.id
                                           and o.status <> 'cancelled'
                                           and o.created_at > p.created_at
                                           and pm.created_at >= o.created_at
                                           and (least(o.cancelled_at, o.completed_at) is null
                                                or pm.created_at <= least(o.cancelled_at, o.completed_at)))), 0)
         -- ordinary charges
         - coalesce((select sum(c.amount) from public.charges c
                      where c.unit_id = p.unit_id
                        and c.created_at >= p.created_at
                        and c.due_date <= least(w.today, (p.cancelled_at at time zone w.tz)::date, (p.completed_at at time zone w.tz)::date)
                        and (w.window_end is null or c.created_at <= w.window_end)
                        and not exists (select 1 from public.payments r
                                         where r.unit_id = c.unit_id
                                           and r.reversal_charge_id = c.id)
                        -- inside a later plan (not cancelled): that plan's
                        and not exists (select 1 from public.payment_plans o
                                         where o.unit_id = p.unit_id
                                           and o.id <> p.id
                                           and o.status <> 'cancelled'
                                           and o.created_at > p.created_at
                                           and c.created_at >= o.created_at
                                           and c.due_date <= least(w.today, (o.cancelled_at at time zone w.tz)::date, (o.completed_at at time zone w.tz)::date)
                                           and (least(o.cancelled_at, o.completed_at) is null
                                                or c.created_at <= least(o.cancelled_at, o.completed_at)))), 0)
         -- bounces of receipts from before the plan
         - coalesce((select sum(c.amount) from public.payments r
                       join public.charges c on c.id = r.reversal_charge_id
                      where r.unit_id = p.unit_id
                        and r.created_at < p.created_at
                        and r.reversed_at >= p.created_at
                        and (p.cancelled_at is null or r.reversed_at <= p.cancelled_at)
                        and not exists (select 1 from public.payment_plans o
                                         where o.unit_id = p.unit_id
                                           and o.id <> p.id
                                           and o.status <> 'cancelled'
                                           and o.created_at < p.created_at
                                           and r.created_at >= o.created_at
                                           and (least(o.cancelled_at, o.completed_at) is null
                                                or r.created_at <= least(o.cancelled_at, o.completed_at)))
                        -- a later plan (not cancelled) had started when the
                        -- bounce was recorded: the latest such plan owns it
                        and not exists (select 1 from public.payment_plans o
                                         where o.unit_id = p.unit_id
                                           and o.id <> p.id
                                           and o.status <> 'cancelled'
                                           and o.created_at > p.created_at
                                           and o.created_at <= r.reversed_at)), 0))
    from public.payment_plans p
    cross join lateral (select least(p.cancelled_at, p.completed_at) as window_end, public.association_local_date(p.association_id) as today,
                              coalesce((select nullif(a.timezone, '') from public.associations a where a.id = p.association_id), 'America/Chicago') as tz) w
   where p.id = p_plan_id
  ) s(x) limit 1);
end$$;


ALTER FUNCTION "public"."payment_plan_paid_amount"("p_plan_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."payment_plan_schedule"("p_plan_id" "uuid") RETURNS TABLE("installment_number" integer, "due_date" "date", "amount" numeric, "covered" numeric, "status" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  with plan as (
    select p.* from public.payment_plans p
     where p.id = p_plan_id
       and (public.can_manage_association(p.association_id) or p.unit_id in (select public.current_resident_unit_ids())
            or coalesce(auth.role(), '') = 'service_role')
  ),
  paid as (
    select public.payment_plan_paid_amount(plan.id) as total, public.association_local_date(plan.association_id) as today from plan
  ),
  sched as (
    select i.installment_number, i.due_date, i.amount,
           sum(i.amount) over (order by i.installment_number) as cumulative
      from public.payment_plan_installments i join plan on plan.id = i.plan_id
  )
  select s.installment_number, s.due_date, s.amount,
         round(greatest(0, least(s.amount, paid.total - (s.cumulative - s.amount))), 2) as covered,
         case when paid.total >= s.cumulative then 'paid'
              when s.due_date < paid.today then 'behind'
              when s.due_date <= paid.today + 7 then 'due'
              else 'upcoming' end as status
    from sched s cross join paid
   order by s.installment_number;
$$;


ALTER FUNCTION "public"."payment_plan_schedule"("p_plan_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."payment_sender_key"("p_name" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  return nullif(btrim(regexp_replace(regexp_replace(upper(coalesce(p_name, '')), '[^A-Z0-9 ]+', ' ', 'g'), '\s+', ' ', 'g')), '');
end
$$;


