CREATE OR REPLACE FUNCTION "public"."platform_create_company"("p_company_name" "text", "p_admin_email" "text", "p_admin_full_name" "text", "p_message" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_portfolio_id uuid;
  v_invitation_id uuid;
  v_token text;
BEGIN
  -- Only platform operators can call this
  IF NOT public.is_platform_operator() THEN
    RAISE EXCEPTION 'Only platform operators can onboard companies' USING ERRCODE = '42501';
  END IF;

  IF p_company_name IS NULL OR length(trim(p_company_name)) = 0 THEN
    RAISE EXCEPTION 'Company name is required';
  END IF;
  IF p_admin_email IS NULL OR length(trim(p_admin_email)) = 0 THEN
    RAISE EXCEPTION 'Admin email is required';
  END IF;

  -- Create the portfolio (company)
  INSERT INTO public.portfolios (company_name)
  VALUES (trim(p_company_name))
  RETURNING id INTO v_portfolio_id;

  -- Create the invitation for the first Company Admin
  INSERT INTO public.user_invitations (
    portfolio_id, email, mvp_role, hoa_role,
    full_name, message, invited_by
  ) VALUES (
    v_portfolio_id,
    lower(trim(p_admin_email)),
    'company_admin',
    'manager',
    trim(coalesce(p_admin_full_name, '')),
    p_message,
    auth.uid()
  )
  RETURNING id, token INTO v_invitation_id, v_token;

  RETURN jsonb_build_object(
    'portfolio_id', v_portfolio_id,
    'invitation_id', v_invitation_id,
    'invitation_token', v_token,
    'admin_email', lower(trim(p_admin_email))
  );
END;
$$;


ALTER FUNCTION "public"."platform_create_company"("p_company_name" "text", "p_admin_email" "text", "p_admin_full_name" "text", "p_message" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."platform_create_company"("p_company_name" "text", "p_admin_email" "text", "p_admin_full_name" "text", "p_message" "text") IS 'Super-admin RPC: creates a portfolio + first Company Admin invitation. Returns IDs and the invitation token (the calling code is then responsible for sending the email via the invite-user edge function).';



CREATE OR REPLACE FUNCTION "public"."platform_health_summary"("p_hours" integer DEFAULT 24) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_since timestamptz;
  v_result jsonb;
begin
  if coalesce(auth.role(), '') <> 'service_role' and not public.is_platform_operator() then
    raise exception 'Only the platform operator can view system health.' using errcode = '42501';
  end if;

  v_since := now() - make_interval(hours => least(greatest(coalesce(p_hours, 24), 1), 24 * 31));

  select jsonb_build_object(
    'since', v_since,
    'cron_failures', coalesce((
      select jsonb_agg(f order by f.started_at desc)
      from (
        select j.jobname as job,
               d.start_time as started_at,
               d.status as status,
               left(coalesce(d.return_message, ''), 200) as message
        from cron.job_run_details d
        join cron.job j on j.jobid = d.jobid
        where d.start_time >= v_since
          and d.status = 'failed'
        order by d.start_time desc
        limit 50
      ) f), '[]'::jsonb),
    'emails_failed', (select count(*) from public.email_queue
                       where status = 'failed' and suppressed_at is null
                         and next_attempt_at >= v_since),
    'emails_stuck', (select count(*) from public.email_queue q
                      where (q.status = 'pending' or (q.status = 'failed' and q.attempt_count < 5))
                        and q.suppressed_at is null
                        and coalesce(q.next_attempt_at, q.created_at) < now() - interval '1 hour'
                        and not exists (
                          select 1 from public.portfolios pf
                           where pf.id = q.portfolio_id
                             and pf.suspended_at is not null
                             and not q.platform_mail)),
    'webhooks_failed', (select count(*) from public.webhook_deliveries
                         where status in ('failed', 'abandoned')
                           and coalesce(last_attempt_at, created_at) >= v_since),
    'reports_failed', (select count(*) from public.report_runs
                        where status = 'failed' and coalesce(finished_at, updated_at, created_at) >= v_since),
    'automations_failed', (select count(*) from public.automation_flow_runs
                            where status in ('failed', 'partial')  -- partial: some actions failed
                              and coalesce(last_attempt_at, fired_at) >= v_since),
    'stripe_events_failed', (select count(*) from public.stripe_webhook_events
                              where status = 'failed' and coalesce(processed_at, claimed_at) >= v_since),
    'autopay_failed', (select count(*) from public.stripe_autopay_runs
                        where status = 'failed' and coalesce(updated_at, created_at) >= v_since)
  ) into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "public"."platform_health_summary"("p_hours" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."platform_health_summary"("p_hours" integer) IS 'Failed scheduled jobs and failure counts (email, webhooks, reports, automations, Stripe) for the last p_hours. Platform operator or service role only. Counts and job names only.';



CREATE OR REPLACE FUNCTION "public"."platform_set_portfolio_custom_domain"("p_portfolio_id" "uuid", "p_domain" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  v_domain text := rtrim(lower(btrim(coalesce(p_domain, ''))), '.');
  v_old text;
begin
  if not (public.is_platform_operator() and public.is_platform_admin()) then
    raise exception 'Platform administrator access is required.' using errcode = '42501';
  end if;

  select custom_domain into v_old from public.portfolios where id = p_portfolio_id for update;
  if not found then
    raise exception 'Company not found.' using errcode = 'P0002';
  end if;

  if v_domain = '' then
    update public.portfolios set custom_domain = null where id = p_portfolio_id;
    return null;
  end if;

  if char_length(v_domain) > 253
     or v_domain !~ '^([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+([a-z]{2,63}|xn--[a-z0-9-]{1,59})$' then
    raise exception 'Enter a domain such as portal.yourcompany.com (no https:// and no path).'
      using errcode = '22023';
  end if;
  if v_domain = 'portier369.com' or v_domain like '%.portier369.com'
     or v_domain = 'vercel.app' or v_domain like '%.vercel.app'
     or v_domain like '%.localhost' then
    raise exception '"%" is a platform address. Use the company''s own domain.', v_domain using errcode = '22023';
  end if;

  if v_old is not distinct from v_domain then
    return v_domain;
  end if;
  if exists (select 1 from public.portfolios where lower(custom_domain) = v_domain and id <> p_portfolio_id) then
    raise exception '"%" is already another company''s domain.', v_domain using errcode = '23505';
  end if;

  update public.portfolios set custom_domain = v_domain where id = p_portfolio_id;
  return v_domain;
exception
  when unique_violation then
    raise exception '"%" is already another company''s domain.', v_domain using errcode = '23505';
end;
$_$;


ALTER FUNCTION "public"."platform_set_portfolio_custom_domain"("p_portfolio_id" "uuid", "p_domain" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."platform_set_portfolio_slug"("p_portfolio_id" "uuid", "p_slug" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  v_slug text := lower(btrim(coalesce(p_slug, '')));
  v_old text;
begin
  if not (public.is_platform_operator() and public.is_platform_admin()) then
    raise exception 'Platform administrator access is required.' using errcode = '42501';
  end if;
  if v_slug !~ '^[a-z0-9](?:[a-z0-9-]{0,30}[a-z0-9])$' then
    raise exception 'Use 2 to 32 lowercase letters, numbers or hyphens, starting and ending with a letter or number.'
      using errcode = '22023';
  end if;
  if public.reserved_portfolio_slug(v_slug) then
    raise exception '"%" is reserved. Choose another address.', v_slug using errcode = '22023';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('portfolio_slug_assignment', 0));

  select slug into v_old from public.portfolios where id = p_portfolio_id for update;
  if not found then
    raise exception 'Company not found.' using errcode = 'P0002';
  end if;
  if v_old = v_slug then
    return v_slug;
  end if;

  if exists (select 1 from public.portfolios where slug = v_slug and id <> p_portfolio_id) then
    raise exception '"%" is already another company''s address.', v_slug using errcode = '23505';
  end if;
  if exists (select 1 from public.portfolio_slug_aliases where slug = v_slug and portfolio_id <> p_portfolio_id) then
    raise exception '"%" was another company''s address and stays reserved for its old links.', v_slug
      using errcode = '23505';
  end if;

  if v_old is not null then
    insert into public.portfolio_slug_aliases (slug, portfolio_id)
    values (v_old, p_portfolio_id)
    on conflict (slug) do update set retired_at = now()
      where public.portfolio_slug_aliases.portfolio_id = excluded.portfolio_id;
  end if;

  update public.portfolios set slug = v_slug where id = p_portfolio_id;
  return v_slug;
end;
$_$;


ALTER FUNCTION "public"."platform_set_portfolio_slug"("p_portfolio_id" "uuid", "p_slug" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."platform_set_profile_role"("p_profile_id" "uuid", "p_hoa_role" "public"."hoa_role") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_actor_email text;
  v_target public.profiles;
  v_manager_role_id uuid;
begin
  select operator.email
  into v_actor_email
  from public.platform_operators operator
  where operator.auth_user_id = v_actor_id
    and operator.active
    and operator.role = 'admin';

  if v_actor_email is null then
    raise exception 'Active platform administrator access is required';
  end if;

  if p_profile_id = v_actor_id then
    raise exception 'You cannot change your own platform profile role here';
  end if;

  if exists (
    select 1
    from public.platform_operators operator
    where operator.auth_user_id = p_profile_id
  ) then
    raise exception 'Platform operator accounts must be managed separately';
  end if;

  select profile.*
  into v_target
  from public.profiles profile
  where profile.id = p_profile_id
  for update;

  if not found then
    raise exception 'User profile not found';
  end if;

  if p_hoa_role in ('company_admin', 'manager') and v_target.portfolio_id is null then
    raise exception 'Company staff must belong to a portfolio';
  end if;

  if p_hoa_role = 'manager' then
    select role.id
    into v_manager_role_id
    from public.user_roles role
    where role.name = 'Property Manager'
      and (
        role.portfolio_id = v_target.portfolio_id
        or (role.is_system and role.portfolio_id is null)
      )
    order by (role.portfolio_id = v_target.portfolio_id) desc nulls last
    limit 1;

    if v_manager_role_id is null then
      raise exception 'The Property Manager role is not configured';
    end if;
  end if;

  update public.profiles
  set hoa_role = p_hoa_role,
      role_id = case when p_hoa_role = 'manager' then v_manager_role_id else null end,
      updated_at = now()
  where id = p_profile_id;

  if v_target.hoa_role = 'manager' and p_hoa_role <> 'manager' then
    delete from public.association_managers
    where user_id = p_profile_id;
  end if;

  insert into public.audit_logs (
    portfolio_id,
    entity_type,
    entity_id,
    action,
    actor_id,
    actor_email,
    changes
  ) values (
    v_target.portfolio_id,
    'user',
    p_profile_id,
    'user_role_changed',
    v_actor_id,
    v_actor_email,
    jsonb_build_object(
      'previous_hoa_role', v_target.hoa_role,
      'hoa_role', p_hoa_role,
      'previous_role_id', v_target.role_id,
      'role_id', v_manager_role_id
    )
  );

  return jsonb_build_object(
    'profile_id', p_profile_id,
    'previous_hoa_role', v_target.hoa_role,
    'hoa_role', p_hoa_role,
    'role_id', v_manager_role_id
  );
end;
$$;


ALTER FUNCTION "public"."platform_set_profile_role"("p_profile_id" "uuid", "p_hoa_role" "public"."hoa_role") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_parking_assignments"() RETURNS TABLE("id" "uuid", "owner_id" "uuid", "unit_id" "uuid", "unit_number" "text", "status" "text", "start_date" "date", "end_date" "date", "monthly_fee" numeric, "vehicle_make" "text", "vehicle_model" "text", "vehicle_color" "text", "license_plate" "text", "insurance_company" "text", "insurance_policy_number" "text", "space_label" "text", "space_type" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if auth.uid() is null or not coalesce(public.is_portal_resident(), false) then
    return;
  end if;
  return query
  select pa.id, pa.owner_id, pa.unit_id, u.unit_number::text, pa.status::text, pa.start_date, pa.end_date,
         pa.monthly_fee, pa.vehicle_make::text, pa.vehicle_model::text, pa.vehicle_color::text,
         pa.license_plate::text, pa.insurance_company::text,
         -- The policy number only on the resident's own assignment.
         case when pa.owner_id in (select public.current_owner_ids()) then pa.insurance_policy_number::text end,
         ps.label::text, ps.space_type::text
    from public.parking_assignments pa
    join public.parking_spaces ps on ps.id = pa.parking_space_id
    left join public.units u on u.id = pa.unit_id
   where pa.owner_id in (select public.current_owner_ids())
      or (pa.status = 'active' and pa.unit_id in (select public.current_resident_unit_ids()))
   order by pa.start_date desc nulls last, pa.id;
end
$$;


ALTER FUNCTION "public"."portal_parking_assignments"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portfolios_guard_domain_verification"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if tg_op = 'INSERT' then
    if current_user in ('authenticated', 'anon') then
      new.custom_domain_verified_at := null;
    end if;
    return new;
  end if;

  if new.custom_domain is distinct from old.custom_domain then
    new.custom_domain_verified_at := null;
    return new;
  end if;

  if new.custom_domain_verified_at is distinct from old.custom_domain_verified_at
     and current_user in ('authenticated', 'anon') then
    raise exception 'The custom domain check sets this automatically.' using errcode = '42501';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."portfolios_guard_domain_verification"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portfolios_guard_platform_columns"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  -- Changed: the reactivation time is recorded here (below), never written
  -- directly by a signed-in user.
  if current_user in ('authenticated', 'anon')
     and new.reactivated_at is distinct from old.reactivated_at then
    raise exception 'The reactivation time is recorded automatically' using errcode = '42501';
  end if;
  -- Changed: lifting a suspension records when (cron_assess_late_fees holds
  -- late fees on due AutoPay units for a day after it). Who may lift it is
  -- checked further down.
  if old.suspended_at is not null and new.suspended_at is null then
    new.reactivated_at := now();
  end if;
  -- Changed: written only by the management-fee scheduler and the definer
  -- RPCs set_management_fee_schedule / run_management_fees (they run as their
  -- owner, not as the signed-in user), never directly by a signed-in user.
  if current_user in ('authenticated', 'anon')
     and (new.management_fee_auto_last_month is distinct from old.management_fee_auto_last_month
          or new.management_fee_auto_last_run is distinct from old.management_fee_auto_last_run) then
    raise exception 'The management fee schedule records its own runs' using errcode = '42501';
  end if;
  if current_user in ('authenticated', 'anon')
     and (new.management_fee_auto_enabled is distinct from old.management_fee_auto_enabled
          or new.management_fee_auto_day is distinct from old.management_fee_auto_day
          or new.management_fee_vendor_id is distinct from old.management_fee_vendor_id
          or new.management_fee_gl_account_id is distinct from old.management_fee_gl_account_id) then
    raise exception 'The management fee schedule can only be changed on the management fees page'
      using errcode = '42501';
  end if;
  -- Changed: the custom domain check (service client) records verification.
  -- A domain change clears it (portfolios_guard_domain_verification, which
  -- fires first); only platform support can change the domain itself (below).
  if current_user in ('authenticated', 'anon')
     and new.custom_domain_verified_at is distinct from old.custom_domain_verified_at
     and not (new.custom_domain is distinct from old.custom_domain
              and new.custom_domain_verified_at is null) then
    raise exception 'The custom domain check sets this automatically' using errcode = '42501';
  end if;
  if auth.uid() is null or (public.is_platform_operator() and public.is_platform_admin()) then
    return new;
  end if;
  if new.tier is distinct from old.tier
     or new.entitlements is distinct from old.entitlements
     or new.archived_at is distinct from old.archived_at
     or new.suspended_at is distinct from old.suspended_at
     or new.suspension_reason is distinct from old.suspension_reason
     or new.slug is distinct from old.slug
     or new.custom_domain is distinct from old.custom_domain
     or new.created_by is distinct from old.created_by then
    raise exception 'Plan, status and account identity can only be changed by platform support';
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."portfolios_guard_platform_columns"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."post_ad_hoc_charge"("p_unit_id" "uuid", "p_charge_category_id" "uuid", "p_amount" numeric, "p_description" "text", "p_due_date" "date" DEFAULT (CURRENT_DATE + 30)) RETURNS "public"."charges"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare cat public.charge_categories; row public.charges;
begin
  select * into cat from public.charge_categories where id = p_charge_category_id;
  if not found then raise exception 'charge category not found'; end if;
  if not public.can_manage_finance(cat.portfolio_id) then raise exception 'permission denied'; end if;
  insert into public.charges (
    unit_id, charge_category_id, charge_type, description, amount, due_date, gl_account_id, created_by
  ) values (
    p_unit_id, p_charge_category_id, cat.charge_type, p_description,
    p_amount, p_due_date, cat.gl_account_id, auth.uid()
  ) returning * into row;
  return row;
end;
$$;


ALTER FUNCTION "public"."post_ad_hoc_charge"("p_unit_id" "uuid", "p_charge_category_id" "uuid", "p_amount" numeric, "p_description" "text", "p_due_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."post_assessment_charges"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  charge_gl_id uuid;
  unit_row record;
  n_charges integer := 0;
begin
  if new.status <> 'posted' or (old.status = 'posted') then
    return new;
  end if;

  -- Look up a sensible GL account for HOA assessments (4xxx income range)
  select id into charge_gl_id
    from public.gl_accounts
   where association_id = new.association_id
     and account_type = 'income'
     and number between 4000 and 4999
     and active
   order by number
   limit 1;

  charge_gl_id := coalesce(public.app_gl_map((select a.portfolio_id from public.associations a where a.id = new.association_id),
                                            new.association_id, 'assessment_income'), charge_gl_id,
    (select g.id from public.gl_accounts g join public.associations a on a.id = new.association_id and g.portfolio_id = a.portfolio_id
      where g.association_id is null and g.account_type = 'income' and g.number between 4000 and 4999 and g.active order by g.number, g.id limit 1));

  -- Fan out charges for every active unit
  for unit_row in
    select u.id as unit_id, u.ownership_pct,
           round(((coalesce(u.ownership_pct, 0) / 100.0) * new.base_amount)::numeric, 2) as amount
      from public.units u
      join public.buildings b on b.id = u.building_id
     where b.association_id = new.association_id
       and u.archived_at is null
  loop
    if unit_row.amount > 0 then
      insert into public.charges (
        unit_id, assessment_period_id, charge_type, description,
        amount, due_date, gl_account_id, created_by
      ) values (
        unit_row.unit_id, new.id, 'assessment',
        new.name,
        unit_row.amount,
        coalesce(new.period_start, current_date),
        charge_gl_id,
        new.created_by
      )
      on conflict do nothing;
      n_charges := n_charges + 1;
    end if;
  end loop;

  -- Log to activity
  insert into public.activity (action, details)
  values ('assessment_posted',
          format('Posted %s charges for assessment "%s" (period %s)',
                 n_charges, new.name, new.id));

  return new;
end;
$$;


ALTER FUNCTION "public"."post_assessment_charges"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."post_bank_transaction"("p_id" "uuid", "p_gl_account_id" "uuid", "p_memo" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  t public.bank_transactions := public.app_bank_transaction_for_update(p_id);
  b public.bank_accounts;
  v_entry uuid;
  v_line uuid;
  v_amt numeric;
  v_memo text;
begin
  select * into b from public.bank_accounts where id = t.bank_account_id;
  if p_gl_account_id = b.gl_account_id or not exists (
       select 1 from public.gl_accounts g where g.id = p_gl_account_id and g.portfolio_id = b.portfolio_id and g.active
          and (g.association_id is null or g.association_id is not distinct from b.association_id)) then
    raise exception 'Choose another GL account of this bank account''s association' using errcode = '22023';
  end if;
  v_amt := abs(round(t.amount, 2));
  if v_amt = 0 then raise exception 'This transaction has no amount' using errcode = '22023'; end if;
  v_memo := coalesce(nullif(btrim(coalesce(p_memo, '')), ''), coalesce(t.merchant_name, t.name));
  insert into public.journal_entries (portfolio_id, entry_date, description, memo, source_type, source_id, created_by, posted, posted_at)
  values (b.portfolio_id, t.date, 'Bank transaction: ' || coalesce(t.name, 'bank feed'), v_memo, 'bank_transaction', t.id, auth.uid(), true, now())
  returning id into v_entry;
  insert into public.journal_lines (entry_id, association_id, gl_account_id, debit_amount, credit_amount, memo, sort_order)
  values (v_entry, b.association_id, b.gl_account_id, case when t.amount < 0 then v_amt else 0 end, case when t.amount > 0 then v_amt else 0 end, v_memo, 0)
  returning id into v_line;
  insert into public.journal_lines (entry_id, association_id, gl_account_id, debit_amount, credit_amount, memo, sort_order)
  values (v_entry, b.association_id, p_gl_account_id, case when t.amount > 0 then v_amt else 0 end, case when t.amount < 0 then v_amt else 0 end, v_memo, 1);
  update public.bank_transactions set matched_journal_line_id = v_line, matched_at = now(), match_method = 'posted',
         gl_account_id = p_gl_account_id, reviewed = true, ignored_at = null
   where id = t.id;
  return v_entry;
end $$;


ALTER FUNCTION "public"."post_bank_transaction"("p_id" "uuid", "p_gl_account_id" "uuid", "p_memo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."post_charge_to_gl"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare g record; v_memo text;
begin
  if tg_op in ('UPDATE', 'DELETE') then
    if tg_op = 'UPDATE' and new.amount is not distinct from old.amount and new.gl_account_id is not distinct from old.gl_account_id
       and new.unit_id is not distinct from old.unit_id and new.due_date is not distinct from old.due_date
       and new.charge_category_id is not distinct from old.charge_category_id
       and new.charge_type is not distinct from old.charge_type then
      return new;
    end if;
    perform public.reverse_subledger_source('charge', old.id, public.charge_ledger_date(old),
      format('Reversal: %s', coalesce(old.description, 'charge')));
  end if;
  if tg_op in ('INSERT', 'UPDATE') then
    select * into g from public.charge_gl_accounts(new);
    if g.portfolio_id is null then return new; end if;
    v_memo := coalesce(new.description, new.charge_type::text);
    perform public.post_subledger_entry(g.portfolio_id, g.association_id, public.charge_ledger_date(new),
      'charge', new.id, v_memo, g.ar, g.income, new.amount);
    return new;
  end if;
  return old;
end $$;


ALTER FUNCTION "public"."post_charge_to_gl"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."post_dues_increase"("p_dues_increase_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare increase_row public.dues_increases; line_row record; n integer := 0;
begin
  select * into increase_row from public.dues_increases where id = p_dues_increase_id for update;
  if not found then raise exception 'dues_increase not found'; end if;
  if increase_row.status <> 'scheduled' then
    raise exception 'dues_increase status must be scheduled (is %)', increase_row.status;
  end if;
  for line_row in select * from public.dues_increase_lines where dues_increase_id = p_dues_increase_id loop
    update public.occupancies
       set dues_amount = line_row.new_amount,
           last_dues_increase_date = increase_row.effective_date,
           last_dues_increase_amount = line_row.new_amount - line_row.old_amount,
           next_scheduled_increase_date = null, next_scheduled_increase_amount = null, updated_at = now()
     where id = line_row.occupancy_id;
    n := n + 1;
  end loop;
  update public.dues_increases set status = 'posted', posted_at = now(), posted_by = auth.uid(), updated_at = now()
   where id = p_dues_increase_id;
  return n;
end;
$$;


ALTER FUNCTION "public"."post_dues_increase"("p_dues_increase_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."post_homeowner_credit"("p_unit_id" "uuid", "p_amount" numeric, "p_credit_date" "date", "p_gl_account_id" "uuid", "p_memo" "text", "p_charge_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_assoc uuid := public.unit_association_id(p_unit_id);
  v_pid uuid;
  v_open numeric;
  v_id uuid;
begin
  select a.portfolio_id into v_pid from public.associations a where a.id = v_assoc;
  if v_pid is null or not public.can_manage_finance(v_pid) or not public.can_manage_association(v_assoc) then
    raise exception 'Unit not found' using errcode = 'P0002';
  end if;
  if p_amount is null or p_amount <= 0 then raise exception 'Enter a credit amount greater than zero' using errcode = '22023'; end if;
  if length(btrim(coalesce(p_memo, ''))) = 0 then raise exception 'Say why the credit is given' using errcode = '22023'; end if;
  if not exists (select 1 from public.gl_accounts g where g.id = p_gl_account_id and g.portfolio_id = v_pid and g.active
                   and (g.association_id is null or g.association_id = v_assoc)
                   and g.account_type::text in ('income', 'other_income', 'expense', 'other_expense')) then
    raise exception 'Choose an income or expense account for the credit' using errcode = '22023';
  end if;
  if p_charge_id is not null then
    select c.amount - coalesce((select sum(pa.amount_applied) from public.payment_applications pa where pa.charge_id = c.id), 0)
      into v_open from public.charges c where c.id = p_charge_id and c.unit_id = p_unit_id;
    if v_open is null then raise exception 'Charge not found on this unit' using errcode = 'P0002'; end if;
    if p_amount > v_open then
      raise exception 'The credit (%) is more than the open balance on that charge (%)', p_amount, v_open using errcode = '22023';
    end if;
  end if;

  insert into public.payments (unit_id, charge_id, amount, payment_date, method, reference, notes, gl_account_id, created_by)
  values (p_unit_id, p_charge_id, round(p_amount, 2), coalesce(p_credit_date, current_date), 'credit', 'Credit',
          btrim(p_memo), p_gl_account_id, auth.uid())
  returning id into v_id;

  insert into public.audit_logs (portfolio_id, entity_type, entity_id, action, actor_id, actor_email, changes)
  values (v_pid, 'unit', p_unit_id, 'homeowner_credit_posted', auth.uid(), (select email from auth.users where id = auth.uid()),
          jsonb_build_object('payment_id', v_id, 'amount', round(p_amount, 2), 'gl_account_id', p_gl_account_id,
                             'charge_id', p_charge_id, 'memo', btrim(p_memo)));
  return v_id;
end $$;


ALTER FUNCTION "public"."post_homeowner_credit"("p_unit_id" "uuid", "p_amount" numeric, "p_credit_date" "date", "p_gl_account_id" "uuid", "p_memo" "text", "p_charge_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."post_lockbox_batch"("p_batch" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  b record;
  i record;
  v_payment uuid;
  v_owner uuid;
  v_posted int := 0;
  v_failed int := 0;
  v_open int;
begin
  select * into b from public.lockbox_batches where id = p_batch;
  if not found or not public.can_manage_finance(b.portfolio_id) or not public.can_manage_association(b.association_id) then
    raise exception 'Lockbox batch not found' using errcode = 'P0002';
  end if;
  select * into b from public.lockbox_batches where id = p_batch for update;
  if not found then raise exception 'Lockbox batch not found' using errcode = 'P0002'; end if;

  perform pg_advisory_xact_lock(hashtextextended('unit-apply:' || u.unit_id::text, 0))
     from (select distinct unit_id from public.lockbox_items
            where batch_id = p_batch and not rejected and payment_id is null and unit_id is not null
            order by unit_id) u;
  for i in select * from public.lockbox_items
            where batch_id = p_batch and not rejected and payment_id is null and unit_id is not null and check_amount_cents > 0
            order by row_no nulls last, created_at
  loop
    begin
      if not exists (select 1 from public.units u join public.buildings bl on bl.id = u.building_id
                      where u.id = i.unit_id and bl.association_id = b.association_id and u.archived_at is null) then
        raise exception 'This unit is archived or not in the lockbox account''s association; choose the unit again' using errcode = '22023';
      end if;
      insert into public.payments (unit_id, amount, payment_date, method, reference, notes, bank_account_id, created_by)
      values (i.unit_id, i.check_amount_cents / 100.0, b.batch_date, 'check',
              coalesce('Check ' || i.check_number, 'Lockbox check'),
              btrim(concat_ws(' ' || chr(183) || ' ', 'Lockbox' || coalesce(' ' || b.deposit_reference, ''), i.payer_name, i.memo)),
              b.bank_account_id, auth.uid())
      returning id into v_payment;
      select occ.owner_id into v_owner from public.occupancies occ
       where occ.unit_id = i.unit_id and occ.status = 'current' and occ.occupancy_type = 'owner'
       order by occ.is_primary desc nulls last limit 1;
      update public.lockbox_items set payment_id = v_payment, owner_id = v_owner, posted_at = now(), post_error = null where id = i.id;
      v_posted := v_posted + 1;
    exception when others then
      update public.lockbox_items set post_error = left(sqlerrm, 300) where id = i.id;
      v_failed := v_failed + 1;
    end;
  end loop;

  select count(*) into v_open from public.lockbox_items where batch_id = p_batch and not rejected and payment_id is null;
  perform public.refresh_lockbox_batch_status(p_batch);
  insert into public.audit_logs (portfolio_id, entity_type, entity_id, action, actor_id, actor_email, changes)
  values (b.portfolio_id, 'lockbox_batch', p_batch, 'lockbox_posted', auth.uid(), (select email from auth.users where id = auth.uid()),
          jsonb_build_object('posted', v_posted, 'failed', v_failed, 'still_open', v_open));
  return jsonb_build_object('posted', v_posted, 'failed', v_failed, 'open', v_open);
end $$;


ALTER FUNCTION "public"."post_lockbox_batch"("p_batch" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."post_manual_journal_entry"("p_entry_date" "date", "p_description" "text", "p_reference" "text", "p_memo" "text", "p_lines" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_pid uuid := public.current_portfolio_id();
  v_lines jsonb;
  v_entry uuid;
begin
  if v_pid is null or not public.can_manage_finance(v_pid) then raise exception 'Permission denied' using errcode = '42501'; end if;
  if p_entry_date is null then raise exception 'Entry date is required' using errcode = '22023'; end if;
  if length(btrim(coalesce(p_description, ''))) = 0 then raise exception 'Description is required' using errcode = '22023'; end if;
  v_lines := public.app_normalize_je_lines(v_pid, p_lines, true);

  insert into public.journal_entries (portfolio_id, entry_date, description, reference_number, memo, created_by, posted)
  values (v_pid, p_entry_date, left(btrim(p_description), 500), nullif(btrim(coalesce(p_reference, '')), ''),
          nullif(btrim(coalesce(p_memo, '')), ''), auth.uid(), false)
  returning id into v_entry;
  insert into public.journal_lines (entry_id, gl_account_id, association_id, debit_amount, credit_amount, memo, sort_order)
  select v_entry, (l->>'gl_account_id')::uuid, (l->>'association_id')::uuid, (l->>'debit')::numeric, (l->>'credit')::numeric,
         l->>'memo', (ord - 1)::int
    from jsonb_array_elements(v_lines) with ordinality as t(l, ord);
  update public.journal_entries set posted = true, posted_at = now() where id = v_entry;
  return v_entry;
end $$;


ALTER FUNCTION "public"."post_manual_journal_entry"("p_entry_date" "date", "p_description" "text", "p_reference" "text", "p_memo" "text", "p_lines" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."post_message"("p_thread" "uuid", "p_body" "text", "p_internal" boolean, "p_as" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare a record; v_id uuid; v_name text;
begin
  select * into a from public.message_thread_access(p_thread, p_as);
  if a.role = 'resident' then
    if coalesce(p_internal, false) then raise exception 'Not allowed' using errcode = '42501'; end if;
    -- A former owner (sold, by the association's own date) reads their old
    -- conversations but doesn't reply.
    if (a.thread).owner_id is not null and not exists (
         select 1 from public.occupancies o
          where o.owner_id = (a.thread).owner_id and o.status = 'current'
            and (o.move_out_date is null or o.move_out_date > public.association_local_date(o.association_id))
            and ((a.thread).association_id is null or o.association_id = (a.thread).association_id)) then
      raise exception 'You can read this conversation but can''t reply, because you no longer own a unit in this association. Contact your management company if you need help' using errcode = '42501';
    end if;
    if (a.thread).owner_id is not null then select full_name into v_name from public.owners where id = (a.thread).owner_id;
    else select btrim(coalesce(first_name, '') || ' ' || coalesce(last_name, '')) into v_name from public.tenants where id = (a.thread).tenant_id; end if;
    insert into public.message_thread_messages (thread_id, author_id, author_role, author_name, body)
    values (p_thread, auth.uid(), 'resident', nullif(v_name, ''), btrim(p_body)) returning id into v_id;
    update public.message_threads
       set staff_unread = true, status = 'open', closed_at = null,
           last_message_at = now(), last_message_preview = left(btrim(p_body), 140), last_message_role = 'resident',
           first_response_due_at = case when last_message_role is distinct from 'resident' or first_response_due_at is null
                                        then now() + interval '48 hours' else first_response_due_at end,
           acknowledged_at = case when last_message_role = 'staff' then null else acknowledged_at end
     where id = p_thread;
  else
    insert into public.message_thread_messages (thread_id, author_id, author_role, author_name, body, internal)
    values (p_thread, auth.uid(), 'staff', public.message_author_name(), btrim(p_body), coalesce(p_internal, false)) returning id into v_id;
    if not coalesce(p_internal, false) then
      update public.message_threads
         set resident_unread = true, staff_unread = false,
             last_message_at = now(), last_message_preview = left(btrim(p_body), 140), last_message_role = 'staff',
             acknowledged_at = coalesce(acknowledged_at, now()),
             assigned_to = coalesce(assigned_to, auth.uid())
       where id = p_thread;
    end if;
  end if;
  return v_id;
end $$;


ALTER FUNCTION "public"."post_message"("p_thread" "uuid", "p_body" "text", "p_internal" boolean, "p_as" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."post_nsf_fee"("p_payment_id" "uuid", "p_reason" "text" DEFAULT 'NSF - returned payment'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  payment_row public.payments;
  v_association_id uuid;
  v_portfolio_id uuid;
  fee_amount numeric(10,2);
  new_charge_id uuid;
  v_paid_on date;
begin
  select * into payment_row from public.payments where id = p_payment_id;
  if not found then raise exception 'payment not found'; end if;
  v_paid_on := coalesce(payment_row.payment_date, payment_row.created_at::date);

  if (public.app_ownership_bounds(payment_row.unit_id, v_paid_on)).period_to <= current_date then
    raise exception 'This payment was made by a previous owner of the unit, so the NSF fee can''t be charged to the current owner. Reverse the payment without the NSF fee.'
      using errcode = '22023';
  end if;

  select a.id, a.portfolio_id into v_association_id, v_portfolio_id
    from public.units u
    join public.buildings b on b.id = u.building_id
    join public.associations a on a.id = b.association_id
   where u.id = payment_row.unit_id;

  select coalesce(a.nsf_fee_amount_override, p.default_nsf_fee_amount) into fee_amount
    from public.associations a
    join public.portfolios p on p.id = a.portfolio_id
   where a.id = v_association_id;

  insert into public.charges (unit_id, charge_type, description, amount, due_date)
  values (payment_row.unit_id, 'nsf_fee', p_reason, fee_amount, current_date + 15)
  returning id into new_charge_id;

  update public.occupancies
     set nsf_count = nsf_count + 1, updated_at = now()
   where unit_id = payment_row.unit_id and status = 'current' and occupancy_type = 'owner';

  return new_charge_id;
end $$;


ALTER FUNCTION "public"."post_nsf_fee"("p_payment_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."post_payment_to_gl"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare g record; v_memo text;
begin
  if tg_op in ('UPDATE', 'DELETE') then
    if tg_op = 'UPDATE' and new.amount is not distinct from old.amount and new.unit_id is not distinct from old.unit_id
       and new.payment_date is not distinct from old.payment_date and new.bank_account_id is not distinct from old.bank_account_id and new.method is not distinct from old.method and new.gl_account_id is not distinct from old.gl_account_id then
      return new;
    end if;
    perform public.reverse_subledger_source('payment', old.id, coalesce(old.payment_date, current_date),
      format('Reversal: payment %s', coalesce(old.reference, old.method, '')));
  end if;
  if tg_op in ('INSERT', 'UPDATE') then
    select * into g from public.payment_gl_accounts(new);
    if g.portfolio_id is null then return new; end if;
    v_memo := btrim(format('Owner payment %s %s', coalesce(new.method, ''), coalesce(new.reference, '')));
    perform public.post_subledger_entry(g.portfolio_id, g.association_id, coalesce(new.payment_date, current_date),
      'payment', new.id, v_memo, g.cash, g.ar, new.amount);
    return new;
  end if;
  return old;
end $$;


ALTER FUNCTION "public"."post_payment_to_gl"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."post_recurring_bills"("p_through" "date") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_pid uuid := public.current_portfolio_id();
  n integer;
begin
  if v_pid is null or not public.can_manage_finance(v_pid) then
    raise exception 'Permission denied' using errcode = '42501';
  end if;
  if public.manager_is_scoped() and not public.is_company_admin() then
    raise exception 'Posting recurring bills covers every association. Ask a company admin or a manager with access to all associations.' using errcode = '42501';
  end if;
  if p_through is null then raise exception 'Choose a post-through date' using errcode = '22023'; end if;
  if p_through > current_date + 366 then
    raise exception 'Post-through date can be at most a year ahead' using errcode = '22023';
  end if;
  n := public.generate_recurring_bills_through(v_pid, p_through, true);
  insert into public.audit_logs (portfolio_id, entity_type, entity_id, action, actor_id, actor_email, changes)
  values (v_pid, 'recurring_bill', null, 'posted', auth.uid(), (select email from auth.users where id = auth.uid()),
          jsonb_build_object('through', p_through, 'bills', n));
  return n;
end $$;


ALTER FUNCTION "public"."post_recurring_bills"("p_through" "date") OWNER TO "postgres";


