CREATE OR REPLACE FUNCTION "public"."post_stripe_ledger_payment"("p_intent_id" "uuid", "p_method" "text", "p_processor_payment_intent_id" "text", "p_processor_account_id" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  v_intent public.payment_intents%rowtype;
  v_association_account_id text;
  v_payment_id uuid;
begin
  if p_method not in ('card', 'ach') then
    raise exception 'Unsupported Stripe payment method';
  end if;
  if p_processor_payment_intent_id !~ '^pi_[A-Za-z0-9_]+$'
     or p_processor_account_id !~ '^acct_[A-Za-z0-9]+$' then
    raise exception 'Invalid Stripe processor identity';
  end if;

  select * into v_intent
  from public.payment_intents
  where id = p_intent_id
  for update;
  if not found then raise exception 'Payment intent not found'; end if;

  select stripe_account_id into v_association_account_id
  from public.associations
  where id = v_intent.association_id;

  if v_association_account_id is distinct from p_processor_account_id
     or (v_intent.processor_account_id is not null
         and v_intent.processor_account_id is distinct from p_processor_account_id) then
    raise exception 'Stripe account does not match payment association';
  end if;
  if lower(v_intent.currency) <> 'usd' then
    raise exception 'Unsupported payment intent currency';
  end if;
  if v_intent.processor_payment_intent_id is not null
     and v_intent.processor_payment_intent_id is distinct from p_processor_payment_intent_id then
    raise exception 'Payment intent is already bound to a different Stripe PaymentIntent';
  end if;
  if v_intent.payment_id is not null then
    return v_intent.payment_id;
  end if;

  insert into public.payments(
    unit_id,
    amount,
    payment_date,
    method,
    reference,
    notes,
    processor,
    processor_account_id,
    processor_payment_intent_id
  )
  values (
    v_intent.unit_id,
    v_intent.amount,
    current_date,
    p_method,
    p_processor_payment_intent_id,
    format('Online payment via Stripe Connect (%s)', p_method),
    'stripe',
    p_processor_account_id,
    p_processor_payment_intent_id
  )
  on conflict (processor, processor_account_id, processor_payment_intent_id)
    where processor = 'stripe'
      and processor_account_id is not null
      and processor_payment_intent_id is not null
  do nothing
  returning id into v_payment_id;

  if v_payment_id is null then
    select id into v_payment_id from public.payments
    where processor = 'stripe'
      and processor_account_id = p_processor_account_id
      and processor_payment_intent_id = p_processor_payment_intent_id
      and unit_id = v_intent.unit_id
      and amount = v_intent.amount;
  end if;
  if v_payment_id is null then raise exception 'Could not resolve Stripe ledger payment'; end if;

  update public.payment_intents
  set payment_id = v_payment_id,
      processor_account_id = p_processor_account_id,
      processor_payment_intent_id = p_processor_payment_intent_id,
      processor = 'stripe',
      method = p_method,
      status = 'succeeded',
      succeeded_at = coalesce(succeeded_at, now()),
      updated_at = now()
  where id = v_intent.id;

  return v_payment_id;
end;
$_$;


ALTER FUNCTION "public"."post_stripe_ledger_payment"("p_intent_id" "uuid", "p_method" "text", "p_processor_payment_intent_id" "text", "p_processor_account_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."post_subledger_entry"("p_portfolio" "uuid", "p_association" "uuid", "p_date" "date", "p_source_type" "text", "p_source_id" "uuid", "p_memo" "text", "p_debit_gl" "uuid", "p_credit_gl" "uuid", "p_amount" numeric) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_id uuid; v_amt numeric := round(coalesce(p_amount, 0), 2); v_dr uuid := p_debit_gl; v_cr uuid := p_credit_gl;
begin
  if v_amt = 0 then return null; end if;
  if v_dr is null or v_cr is null then
    raise exception 'Cannot post % to the general ledger: set up % for this association', p_source_type,
      case when v_dr is null then 'the debit account' else 'the credit account' end using errcode = '22023';
  end if;
  if v_amt < 0 then v_amt := -v_amt; v_dr := p_credit_gl; v_cr := p_debit_gl; end if;
  insert into public.journal_entries (portfolio_id, entry_date, memo, description, source_type, source_id, posted, created_by)
  values (p_portfolio, coalesce(p_date, current_date), left(p_memo, 500), left(p_memo, 500), p_source_type, p_source_id, false, auth.uid())
  returning id into v_id;
  insert into public.journal_lines (entry_id, gl_account_id, association_id, debit_amount, credit_amount, memo, sort_order) values
    (v_id, v_dr, p_association, v_amt, 0, left(p_memo, 500), 0),
    (v_id, v_cr, p_association, 0, v_amt, left(p_memo, 500), 1);
  update public.journal_entries set posted = true where id = v_id;
  return v_id;
end $$;


ALTER FUNCTION "public"."post_subledger_entry"("p_portfolio" "uuid", "p_association" "uuid", "p_date" "date", "p_source_type" "text", "p_source_id" "uuid", "p_memo" "text", "p_debit_gl" "uuid", "p_credit_gl" "uuid", "p_amount" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."post_unit_recurring_charges"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare row record; n integer := 0; new_charge_id uuid; next_due date;
begin
  for row in
    select urc.*, cc.name as category_name, cc.gl_account_id as category_gl,
           cc.charge_type as category_charge_type, cc.code as category_code
      from public.unit_recurring_charges urc
      join public.charge_categories cc on cc.id = urc.charge_category_id
      join public.units un on un.id = urc.unit_id
      join public.buildings b on b.id = un.building_id
      join public.associations a on a.id = b.association_id
     where urc.active and cc.active
       and un.archived_at is null                                    -- fix
       -- fix: due by the association's own date (same rule as
       -- association_local_date, inlined: no per-row function call).
       and urc.next_post_date <= (now() at time zone coalesce(nullif(a.timezone, ''), 'America/Chicago'))::date
       -- fix: a recurring charge whose category is not the association's
       -- (the category trigger refuses it) is skipped, so one bad row
       -- can't stop every association's posting.
       and (cc.portfolio_id is null or cc.portfolio_id = a.portfolio_id)
       and (cc.association_id is null or cc.association_id = b.association_id)
       and (urc.end_date is null or urc.next_post_date <= urc.end_date)
  loop
    perform 1 from public.units where id = row.unit_id for update;
    perform 1 from public.unit_recurring_charges u
     where u.id = row.id and u.active and u.next_post_date = row.next_post_date
       and (u.end_date is null or u.next_post_date <= u.end_date)
       for update;
    if not found then
      continue;
    end if;

    insert into public.charges (
      unit_id, charge_category_id, charge_type, description,
      amount, due_date, gl_account_id, created_by
    ) values (
      row.unit_id, row.charge_category_id, row.category_charge_type,
      coalesce(row.memo, row.category_name),
      row.amount, row.next_post_date, row.category_gl, row.created_by
    ) returning id into new_charge_id;

    next_due := public.recurring_next_date(row.next_post_date, row.frequency::text, 1,
      extract(day from coalesce(row.start_date, row.next_post_date))::integer);

    update public.unit_recurring_charges set next_post_date = next_due, last_posted_at = now(), updated_at = now() where id = row.id;
    n := n + 1;
  end loop;
  return n;
end;
$$;


ALTER FUNCTION "public"."post_unit_recurring_charges"() OWNER TO "postgres";


