CREATE OR REPLACE FUNCTION "public"."project_budget_vs_actual"("p_project_id" "uuid") RETURNS TABLE("line_id" "uuid", "category" "text", "gl_account_id" "uuid", "gl_label" "text", "budget_amount" numeric, "actual_amount" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  p public.capital_projects;
begin
  select * into p from public.capital_projects where id = p_project_id;
  if not found
     or not (public.is_any_staff() or public.is_company_admin() or public.is_platform_operator())
     or not public.can_access_portfolio(p.portfolio_id)
     or not public.can_view_association_row(p.association_id) then
    raise exception 'Project not found' using errcode = '42501';
  end if;

  return query
  with spend as (
    select b.gl_account_id as gl, sum(b.amount) as amount
      from public.capital_project_work_orders link
      join public.payable_bills b on b.work_order_id = link.work_order_id
     where link.project_id = p.id and b.archived_at is null
       and b.association_id = p.association_id
       and b.status::text in ('approved', 'paid')
     group by b.gl_account_id
  ),
  lines as (
    select l.*, (l.gl_account_id is null or public.can_read_gl(l.gl_account_id)) as readable
      from public.capital_project_budget_lines l where l.project_id = p.id
  ),
  spend_r as (
    select s.*, (s.gl is null or public.can_read_gl(s.gl)) as readable from spend s
  )
  select x.line_id, x.category, x.gl_account_id, x.gl_label, x.budget_amount, x.actual_amount
    from (
      select l.id as line_id, l.category, l.gl_account_id, concat_ws(' ', g.number, g.name) as gl_label,
             l.budget_amount, coalesce(s.amount, 0)::numeric(14, 2) as actual_amount, l.sort_order as ord
        from lines l
        left join public.gl_accounts g on g.id = l.gl_account_id
        left join spend s on s.gl = l.gl_account_id
       where l.readable
      union all
      select null::uuid, 'Other'::text, null::uuid, null::text, 0::numeric, sum(s.amount)::numeric(14, 2), 2147483646
        from spend_r s
       where s.readable and not exists (select 1 from lines l where l.gl_account_id is not distinct from s.gl)
      having sum(s.amount) is not null
      union all
      select null::uuid, 'Restricted accounts'::text, null::uuid, null::text,
             coalesce((select sum(l.budget_amount) from lines l where not l.readable), 0)::numeric(14, 2),
             coalesce((select sum(s.amount) from spend_r s where not s.readable), 0)::numeric(14, 2),
             2147483647
       where exists (select 1 from lines l where not l.readable) or exists (select 1 from spend_r s where not s.readable)
    ) x
   order by x.ord, x.category;
end $$;


ALTER FUNCTION "public"."project_budget_vs_actual"("p_project_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."project_cost_by_category"("p_project_id" "uuid") RETURNS TABLE("line_id" "uuid", "category" "text", "gl_account_id" "uuid", "gl_label" "text", "budget_amount" numeric, "committed_amount" numeric, "spent_amount" numeric)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  p public.capital_projects;
  v_fin boolean;
begin
  select * into p from public.capital_projects where id = p_project_id;
  if not found
     or not (public.is_any_staff() or public.is_company_admin() or public.is_platform_operator())
     or not public.can_access_portfolio(p.portfolio_id)
     or not public.can_view_association_row(p.association_id) then
    raise exception 'Project not found' using errcode = '42501';
  end if;
  -- Purchase orders are finance-only: their open amounts count only for
  -- finance staff (same check as the purchase_orders policy); other staff
  -- see bill-only figures.
  v_fin := coalesce(public.is_platform_operator(), false)
           or coalesce(public.my_finance_portfolio() = p.portfolio_id, false);

  return query
  with links as (
    select distinct link.work_order_id from public.capital_project_work_orders link where link.project_id = p.id
  ),
  bill_costs as (
    select b.gl_account_id as gl,
           coalesce(sum(b.amount) filter (where b.status::text in ('draft', 'pending_approval', 'approved')), 0) as committed,
           coalesce(sum(b.amount) filter (where b.status::text = 'paid'), 0) as spent
      from links lk
      join public.payable_bills b on b.work_order_id = lk.work_order_id
     where b.archived_at is null
       and b.association_id = p.association_id
     group by b.gl_account_id
  ),
  -- po_cost_by_billed_gl: a bill on the PO first uses up the PO lines of its
  -- own GL account; only what is billed beyond them (another account, or
  -- more than that account's lines) uses up the PO's remaining lines in
  -- order. So a $50 bill coded to B leaves A's $50 open, not B's.
  po_gl as (
    select po.id as po_id, l.gl_account_id as gl, sum(l.line_total) as lines, min(l.sort_order) as ord
      from links lk
      join public.purchase_orders po on po.work_order_id = lk.work_order_id
      join public.purchase_order_line_items l on l.purchase_order_id = po.id
     where v_fin
       and po.archived_at is null
       and po.association_id = p.association_id
       and po.approval_status = 'approved'
       and po.status::text <> 'cancelled'
     group by po.id, l.gl_account_id
  ),
  po_bill_gl as (
    select b.purchase_order_id as po_id, b.gl_account_id as gl, sum(b.amount) as billed
      from public.payable_bills b
     where b.purchase_order_id in (select g.po_id from po_gl g)
       and b.status::text <> 'void'
       and b.archived_at is null
     group by b.purchase_order_id, b.gl_account_id
  ),
  po_extra as (
    select pb.po_id, sum(greatest(pb.billed - coalesce(g.lines, 0), 0)) as extra
      from po_bill_gl pb
      left join po_gl g on g.po_id = pb.po_id and g.gl is not distinct from pb.gl
     group by pb.po_id
  ),
  po_open as (
    select g.po_id, g.gl,
           greatest(g.lines - coalesce(pb.billed, 0), 0) as open_gl,
           sum(greatest(g.lines - coalesce(pb.billed, 0), 0))
             over (partition by g.po_id order by g.ord, g.gl::text) as running
      from po_gl g
      left join po_bill_gl pb on pb.po_id = g.po_id and pb.gl is not distinct from g.gl
  ),
  po_costs as (
    select o.gl, sum(greatest(least(o.open_gl, o.running - coalesce(e.extra, 0)), 0)) as committed, 0::numeric as spent
      from po_open o
      left join po_extra e on e.po_id = o.po_id
     group by o.gl
  ),
  spend as (
    select c.gl, sum(c.committed) as committed, sum(c.spent) as spent
      from (select * from bill_costs union all select * from po_costs) c
     group by c.gl
     having sum(c.committed) <> 0 or sum(c.spent) <> 0
  ),
  lines as (
    select l.*, (l.gl_account_id is null or public.can_read_gl(l.gl_account_id)) as readable
      from public.capital_project_budget_lines l where l.project_id = p.id
  ),
  spend_r as (
    select s.*, (s.gl is null or public.can_read_gl(s.gl)) as readable from spend s
  )
  select x.line_id, x.category, x.gl_account_id, x.gl_label, x.budget_amount, x.committed_amount, x.spent_amount
    from (
      select l.id as line_id, l.category, l.gl_account_id, concat_ws(' ', g.number, g.name) as gl_label,
             l.budget_amount,
             coalesce(s.committed, 0)::numeric(14, 2) as committed_amount,
             coalesce(s.spent, 0)::numeric(14, 2) as spent_amount,
             l.sort_order as ord
        from lines l
        left join public.gl_accounts g on g.id = l.gl_account_id
        left join spend s on s.gl = l.gl_account_id
       where l.readable
      union all
      select null::uuid, 'Other'::text, null::uuid, null::text, 0::numeric,
             sum(s.committed)::numeric(14, 2), sum(s.spent)::numeric(14, 2), 2147483646
        from spend_r s
       where s.readable and not exists (select 1 from lines l where l.gl_account_id is not distinct from s.gl)
      having count(*) > 0
      union all
      select null::uuid, 'Restricted accounts'::text, null::uuid, null::text,
             coalesce((select sum(l.budget_amount) from lines l where not l.readable), 0)::numeric(14, 2),
             coalesce((select sum(s.committed) from spend_r s where not s.readable), 0)::numeric(14, 2),
             coalesce((select sum(s.spent) from spend_r s where not s.readable), 0)::numeric(14, 2),
             2147483647
       where exists (select 1 from lines l where not l.readable) or exists (select 1 from spend_r s where not s.readable)
    ) x
   order by x.ord, x.category;
end $_$;


ALTER FUNCTION "public"."project_cost_by_category"("p_project_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."provision_portfolio"("p_company_name" "text", "p_first_admin_email" "text", "p_first_admin_name" "text" DEFAULT NULL::"text", "p_tier" "public"."portfolio_tier" DEFAULT 'foundation'::"public"."portfolio_tier", "p_seats" integer DEFAULT 5, "p_trial_days" integer DEFAULT 14, "p_allowed_email_domains" "text"[] DEFAULT NULL::"text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  new_portfolio public.portfolios;
  new_subscription public.subscriptions;
  new_invitation public.user_invitations;
  president_role_id uuid;
begin
  if not (public.is_platform_operator() and public.is_platform_admin()) then
    raise exception 'provision_portfolio: platform administrator required';
  end if;

  insert into public.portfolios (
    company_name, tier, allowed_email_domains, created_by
  ) values (
    p_company_name, p_tier, coalesce(p_allowed_email_domains, '{}'), auth.uid()
  ) returning * into new_portfolio;

  insert into public.subscriptions (
    portfolio_id, tier, status, seats_included, trial_ends_at,
    billing_email, current_period_start
  ) values (
    new_portfolio.id, p_tier, 'trialing', p_seats,
    now() + make_interval(days => p_trial_days),
    p_first_admin_email,
    now()
  ) returning * into new_subscription;

  select id into president_role_id from public.user_roles
   where is_system and name = 'President' limit 1;

  insert into public.user_invitations (
    portfolio_id, email, hoa_role, role_id, invited_by,
    message, expires_at, metadata
  ) values (
    new_portfolio.id, lower(p_first_admin_email),
    'manager', president_role_id, auth.uid(),
    format('Welcome to %s — your management platform is ready.', p_company_name),
    now() + interval '30 days',
    jsonb_build_object('email_delivery', 'application')
  ) returning * into new_invitation;

  return jsonb_build_object(
    'portfolio_id', new_portfolio.id,
    'subscription_id', new_subscription.id,
    'invitation_id', new_invitation.id,
    'invitation_token', new_invitation.token,
    'invitation_expires_at', new_invitation.expires_at,
    'trial_ends_at', new_subscription.trial_ends_at
  );
end;
$$;


ALTER FUNCTION "public"."provision_portfolio"("p_company_name" "text", "p_first_admin_email" "text", "p_first_admin_name" "text", "p_tier" "public"."portfolio_tier", "p_seats" integer, "p_trial_days" integer, "p_allowed_email_domains" "text"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."provision_portfolio"("p_company_name" "text", "p_first_admin_email" "text", "p_first_admin_name" "text", "p_tier" "public"."portfolio_tier", "p_seats" integer, "p_trial_days" integer, "p_allowed_email_domains" "text"[]) IS 'Platform operator onboards a new management company. Creates portfolio + trialing subscription + invitation to the first President.';



CREATE OR REPLACE FUNCTION "public"."purchase_order_refresh_billed"("p_po_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_billed numeric;
begin
  if p_po_id is null then
    return;
  end if;
  select coalesce(sum(b.amount), 0) into v_billed
    from public.payable_bills b
   where b.purchase_order_id = p_po_id and b.status::text <> 'void' and b.archived_at is null;
  update public.purchase_orders
     set po_billed = v_billed,
         status = case
           when status::text = 'cancelled' then status
           when po_total > 0 and v_billed >= po_total then 'billed'::public.purchase_order_status
           when status::text = 'billed' then 'approved'::public.purchase_order_status
           else status end,
         updated_at = now()
   where id = p_po_id;
end $$;


ALTER FUNCTION "public"."purchase_order_refresh_billed"("p_po_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."purchase_orders_assign_number"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_n integer;
  v_number text;
begin
  new.number := nullif(btrim(coalesce(new.number, '')), '');
  -- Clearing the number on an edit keeps the one it has.
  if tg_op = 'UPDATE' and new.number is null then
    new.number := old.number;
  end if;
  if tg_op = 'UPDATE' and new.number is not distinct from old.number and new.portfolio_id is not distinct from old.portfolio_id then
    return new;
  end if;
  -- One numbering at a time per company, so two new POs can't take the same number.
  perform pg_advisory_xact_lock(hashtextextended('purchase-order-number:' || new.portfolio_id::text, 0));
  if new.number is null then
    loop
      insert into public.purchase_order_number_counters as c (portfolio_id, last_value)
      values (new.portfolio_id, 1)
      on conflict (portfolio_id) do update set last_value = c.last_value + 1
      returning c.last_value into v_n;
      v_number := 'PO-' || lpad(v_n::text, 5, '0');
      -- Skip a number someone typed in by hand.
      exit when not exists (select 1 from public.purchase_orders po
                             where po.portfolio_id = new.portfolio_id and lower(po.number) = lower(v_number));
    end loop;
    new.number := v_number;
  elsif exists (select 1 from public.purchase_orders po
                 where po.portfolio_id = new.portfolio_id and lower(po.number) = lower(new.number) and po.id <> new.id) then
    raise exception 'PO number % is already used. Choose another number or leave it blank to number it automatically.', new.number
      using errcode = '23505';
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."purchase_orders_assign_number"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."purge_assert_own"("p_table" "regclass", "p_col" "name", "p_ids" "uuid"[]) RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
declare
  v_assoc uuid := nullif(current_setting('purge.association_id', true), '')::uuid;
  v_portfolio uuid := nullif(current_setting('purge.portfolio_id', true), '')::uuid;
  v_other boolean;
begin
  if v_assoc is not null and exists (select 1 from pg_attribute pa where pa.attrelid = p_table
                                       and pa.attname = 'association_id' and not pa.attisdropped) then
    execute format('select exists (select 1 from %s where %I = any($1) and association_id is not null and association_id <> $2)',
                   p_table, p_col) into v_other using p_ids, v_assoc;
    if v_other then
      raise exception 'Rows in % that belong to another association depend on what would be deleted; nothing was deleted. Move or remove them first.', p_table;
    end if;
  end if;
  if v_portfolio is not null and exists (select 1 from pg_attribute pa where pa.attrelid = p_table
                                           and pa.attname = 'portfolio_id' and not pa.attisdropped) then
    execute format('select exists (select 1 from %s where %I = any($1) and portfolio_id is not null and portfolio_id <> $2)',
                   p_table, p_col) into v_other using p_ids, v_portfolio;
    if v_other then
      raise exception 'Rows in % that belong to another company depend on what would be deleted; nothing was deleted.', p_table;
    end if;
  end if;
end $_$;


ALTER FUNCTION "public"."purge_assert_own"("p_table" "regclass", "p_col" "name", "p_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."purge_pause_triggers"() RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
declare
  v_paused jsonb := '[]'::jsonb;
  t record;
begin
  for t in
    select c.relname, tg.tgname, tg.tgenabled
      from pg_trigger tg
      join pg_class c on c.oid = tg.tgrelid
      join pg_namespace n on n.oid = c.relnamespace
     where n.nspname = 'public' and c.relkind = 'r' and not tg.tgisinternal and tg.tgenabled <> 'D'
  loop
    execute format('alter table public.%I disable trigger %I', t.relname, t.tgname);
    v_paused := v_paused || jsonb_build_array(jsonb_build_object('t', t.relname, 'g', t.tgname, 'm', t.tgenabled::text));
  end loop;
  return v_paused;
end $$;


ALTER FUNCTION "public"."purge_pause_triggers"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."purge_polymorphic"("p_association_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
declare
  r record;
  v_ids uuid[];
  v_found boolean;
  v_round integer := 0;
  v_other boolean;
begin
  if to_regclass('pg_temp.purge_deleted') is null then
    create temp table purge_deleted (id uuid not null, tbl regclass not null, primary key (id, tbl)) on commit drop;
  end if;
  analyze purge_deleted;
  loop
    v_found := false;
    v_round := v_round + 1;
    if v_round > 10 then
      raise exception 'Attached records go too deep to delete safely; nothing was deleted.';
    end if;
    for r in
      select c.oid::regclass as tbl, idc.attname as col, tyc.attname as tcol,
             exists (select 1 from pg_attribute pa where pa.attrelid = c.oid and pa.attname = 'id'
                      and not pa.attisdropped and pa.atttypid = 'uuid'::regtype) as has_id
        from pg_class c
        join pg_namespace n on n.oid = c.relnamespace
        join pg_attribute idc on idc.attrelid = c.oid and not idc.attisdropped and idc.atttypid = 'uuid'::regtype
                             and idc.attname like '%\_id'
        join pg_attribute tyc on tyc.attrelid = c.oid and not tyc.attisdropped
                             and tyc.attname = left(idc.attname, length(idc.attname) - 3) || '_type'
       where n.nspname = 'public' and c.relkind = 'r'
    loop
      if r.has_id then
        execute format('select coalesce(array_agg(distinct t.id), ''{}'') from %s t join purge_deleted d on d.id = t.%I '
                    || 'where public.purge_type_matches(t.%I::text, d.tbl) '
                    || 'and not exists (select 1 from purge_deleted x where x.id = t.id and x.tbl = $1)',
                       r.tbl, r.col, r.tcol)
          into v_ids using r.tbl;
        if cardinality(v_ids) > 0 then
          if exists (select 1 from pg_attribute pa where pa.attrelid = r.tbl and pa.attname = 'association_id'
                      and not pa.attisdropped) then
            execute format('select exists (select 1 from %s where id = any($1) and association_id is not null '
                        || 'and association_id is distinct from $2)', r.tbl)
              into v_other using v_ids, p_association_id;
            if v_other then
              raise exception 'Records in % attached here belong to another association; nothing was deleted.', r.tbl;
            end if;
          end if;
          if r.tbl = 'public.journal_entries'::regclass and exists (
               select 1 from public.journal_lines l
                where l.entry_id = any(v_ids) and l.association_id is distinct from p_association_id) then
            raise exception 'Ledger entries made from these records have lines outside this association; nothing was deleted. Reverse or move them first.';
          end if;
          v_found := true;
          perform public.purge_rows(r.tbl, v_ids, 1);
        end if;
      else
        execute format('delete from %s t using purge_deleted d where d.id = t.%I and public.purge_type_matches(t.%I::text, d.tbl)',
                       r.tbl, r.col, r.tcol);
      end if;
    end loop;
    exit when not v_found;
  end loop;
end $_$;


ALTER FUNCTION "public"."purge_polymorphic"("p_association_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."purge_resume_triggers"("p_paused" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
declare
  v jsonb;
begin
  for v in select * from jsonb_array_elements(coalesce(p_paused, '[]'::jsonb)) loop
    execute format('alter table public.%I enable %s trigger %I', v->>'t',
      case v->>'m' when 'A' then 'always' when 'R' then 'replica' else '' end, v->>'g');
  end loop;
end $$;


ALTER FUNCTION "public"."purge_resume_triggers"("p_paused" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."purge_rows"("p_table" "regclass", "p_ids" "uuid"[], "p_depth" integer DEFAULT 0) RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
declare
  r record;
  v_child_ids uuid[];
  v_has_id boolean;
begin
  if p_ids is null or cardinality(p_ids) = 0 then return; end if;
  if p_depth > 30 then
    raise exception 'Links under % go too deep to delete safely; nothing was deleted.', p_table;
  end if;
  -- Reaching an association through links means another association's (or a
  -- company's) data points at what is being deleted: stop, never delete it.
  if p_depth > 0 and p_table in ('public.associations'::regclass, 'public.portfolios'::regclass) then
    raise exception 'Deleting this would also delete % rows that belong elsewhere; nothing was deleted. Remove that link first.', p_table;
  end if;
  if to_regclass('pg_temp.purge_deleted') is null then
    create temp table purge_deleted (id uuid not null, tbl regclass not null, primary key (id, tbl)) on commit drop;
  end if;
  perform public.purge_assert_own(p_table, 'id', p_ids);

  for r in
    select c.conrelid::regclass as tbl, a.attname as col, c.confdeltype as on_delete,
           cardinality(c.conkey) as ncols,
           (select ra.attname from pg_attribute ra where ra.attrelid = c.confrelid and ra.attnum = c.confkey[1]) as refcol
      from pg_constraint c
      join pg_attribute a on a.attrelid = c.conrelid and a.attnum = c.conkey[1]
     where c.contype = 'f' and c.confrelid = p_table
  loop
    if r.ncols <> 1 or r.refcol <> 'id' then
      raise exception 'Cannot follow %.% (its link to % is not a single id column); nothing was deleted.', r.tbl, r.col, p_table;
    end if;

    if r.tbl = p_table then
      -- Self-link: rows outside the set only lose the link.
      execute format('update %s set %I = null where %I = any($1) and not (id = any($1))', r.tbl, r.col, r.col) using p_ids;
      continue;
    end if;

    -- A "set null" link is cleared, except a row's own association_id when the
    -- association itself goes: messages, SMS threads, tenants... tagged with it
    -- are its records and go with it.
    if r.on_delete in ('n', 'd') and not (p_table = 'public.associations'::regclass and r.col = 'association_id') then
      -- Another association's row losing its link is still a change to its data: stop instead.
      perform public.purge_assert_own(r.tbl, r.col, p_ids);
      execute format('update %s set %I = null where %I = any($1)', r.tbl, r.col, r.col) using p_ids;
      continue;
    end if;

    select exists (select 1 from pg_attribute pa where pa.attrelid = r.tbl and pa.attname = 'id' and not pa.attisdropped
                    and pa.atttypid = 'uuid'::regtype) into v_has_id;
    if v_has_id then
      execute format('select coalesce(array_agg(id), ''{}'') from %s where %I = any($1)', r.tbl, r.col)
        into v_child_ids using p_ids;
      perform public.purge_rows(r.tbl, v_child_ids, p_depth + 1);
    else
      perform public.purge_assert_own(r.tbl, r.col, p_ids);
      execute format('delete from %s where %I = any($1)', r.tbl, r.col) using p_ids;
    end if;
  end loop;

  execute format('with d as (delete from %s where id = any($1) returning id) '
              || 'insert into purge_deleted select id, $2 from d on conflict do nothing', p_table) using p_ids, p_table;
end $_$;


ALTER FUNCTION "public"."purge_rows"("p_table" "regclass", "p_ids" "uuid"[], "p_depth" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."purge_type_matches"("p_type" "text", "p_tbl" "regclass") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
  with t as (select case lower(coalesce(p_type, '')) when 'homeowner' then 'owner' else lower(coalesce(p_type, '')) end as v),
  cands as (
    select c.oid from pg_class c join pg_namespace n on n.oid = c.relnamespace, t
     where n.nspname = 'public' and c.relkind = 'r' and t.v <> ''
       and (c.relname = t.v or c.relname = t.v || 's' or c.relname = regexp_replace(t.v, 'y$', 'ies')
            or c.relname like '%\_' || t.v || 's')
  )
  select exists (select 1 from cands where oid = p_tbl);
$_$;


ALTER FUNCTION "public"."purge_type_matches"("p_type" "text", "p_tbl" "regclass") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."quarantine_sms_delivery"("p_message_id" "uuid", "p_provider_message_id" "text", "p_error_message" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if coalesce(auth.role(), '') <> 'service_role' then raise exception 'Service role required'; end if;
  update public.sms_messages
  set status = 'failed', locked_at = null,
      provider = case when p_provider_message_id is null then provider else 'twilio' end,
      provider_message_id = coalesce(left(p_provider_message_id, 200), provider_message_id),
      error_code = 'provider_outcome_unknown',
      error_message = left(coalesce(p_error_message, 'Provider outcome is unknown; manual review required'), 1000),
      next_attempt_at = 'infinity'::timestamptz
  where id = p_message_id and direction = 'outbound';
end;
$$;


ALTER FUNCTION "public"."quarantine_sms_delivery"("p_message_id" "uuid", "p_provider_message_id" "text", "p_error_message" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."queue_calendar_sms"("p_event_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  ev record;
  v_digits text;
  their_number text;
  convo_id uuid;
  msg_id uuid;
  msg_body text;
begin
  select ce.id, ce.title, ce.start_datetime, ce.location, ce.maintenance_instructions, ce.portfolio_id,
         a.id as assoc_id, a.name as assoc_name, coalesce(nullif(a.timezone, ''), 'America/Chicago') as tz,
         a.maintenance_contact_phone, a.maintenance_contact_name,
         nullif(btrim(p.texting_phone_number), '') as our_number
    into ev
    from public.calendar_events ce
    left join public.associations a on a.id = ce.association_id
    left join public.portfolios p on p.id = ce.portfolio_id
   where ce.id = p_event_id;

  if ev.maintenance_contact_phone is null then
    update public.calendar_events set sms_notify_error = 'No maintenance contact phone on the association' where id = p_event_id;
    return null;
  end if;
  if ev.our_number is null then
    update public.calendar_events set sms_notify_error = 'Texting is not set up for this company (no texting phone number)' where id = p_event_id;
    return null;
  end if;

  v_digits := regexp_replace(ev.maintenance_contact_phone, '\D', '', 'g');
  their_number := case
    when length(v_digits) = 10 then '+1' || v_digits
    when length(v_digits) = 11 and left(v_digits, 1) = '1' then '+' || v_digits
    when left(btrim(ev.maintenance_contact_phone), 1) = '+' then '+' || v_digits
    else null end;
  if their_number is null then
    update public.calendar_events set sms_notify_error = 'The maintenance contact phone is not a valid number' where id = p_event_id;
    return null;
  end if;

  if not exists (select 1 from public.sms_opt_ins o
                  where o.portfolio_id = ev.portfolio_id and o.phone_number = their_number and o.opted_in) then
    update public.calendar_events
       set sms_notify_error = 'The maintenance contact has not agreed to receive texts from this company'
     where id = p_event_id;
    return null;
  end if;

  select id into convo_id from public.sms_conversations
   where portfolio_id = ev.portfolio_id and with_phone_number = their_number and our_phone_number = ev.our_number
   limit 1;
  if convo_id is null then
    insert into public.sms_conversations
      (portfolio_id, association_id, with_entity_type, with_entity_id, with_name, with_phone_number, our_phone_number)
    values (ev.portfolio_id, ev.assoc_id, 'maintenance', ev.assoc_id,
            coalesce(ev.maintenance_contact_name, 'Maintenance'), their_number, ev.our_number)
    returning id into convo_id;
  end if;

  msg_body := '[' || coalesce(ev.assoc_name, 'Association') || '] ' || ev.title
              || E'\n' || to_char(ev.start_datetime at time zone ev.tz, 'Mon DD, FMHH12:MI AM')
              || case when ev.location is not null then ' @ ' || ev.location else '' end
              || case when ev.maintenance_instructions is not null then E'\n' || ev.maintenance_instructions else '' end;

  insert into public.sms_messages (conversation_id, direction, body, from_number, to_number, status, provider)
  values (convo_id, 'outbound', left(msg_body, 1600), ev.our_number, their_number, 'queued', 'pending')
  returning id into msg_id;

  update public.calendar_events set sms_notified_at = now(), sms_notify_error = null where id = p_event_id;
  return msg_id;
end;
$$;


ALTER FUNCTION "public"."queue_calendar_sms"("p_event_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."queue_invitation_email"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  rendered jsonb;
  pf_email jsonb;
  pf_from_addr text;
  pf_from_name text;
  pf_reply_to text;
begin
  if new.status <> 'pending'
     or new.metadata ->> 'email_delivery' = 'application' then
    return new;
  end if;

  rendered := public.render_invitation_email(new);

  select email_settings into pf_email
  from public.portfolios
  where id = new.portfolio_id;

  pf_from_addr := pf_email ->> 'from_address';
  pf_from_name := pf_email ->> 'from_name';
  pf_reply_to := pf_email ->> 'reply_to';

  if pf_from_addr is null or pf_from_addr = '' then
    pf_from_addr := 'noreply@portier369.com';
  end if;
  if pf_from_name is null or pf_from_name = '' then
    select company_name into pf_from_name
    from public.portfolios
    where id = new.portfolio_id;
  end if;

  insert into public.email_queue (
    portfolio_id,
    to_email,
    to_name,
    subject,
    body,
    from_address,
    from_name,
    reply_to,
    status
  ) values (
    new.portfolio_id,
    new.email,
    new.full_name,
    rendered ->> 'subject',
    rendered ->> 'html',
    pf_from_addr,
    pf_from_name,
    pf_reply_to,
    'pending'
  );

  return new;
end;
$$;


ALTER FUNCTION "public"."queue_invitation_email"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."queue_invitation_email"() IS 'On each new pending invitation, drops a rendered HTML email into email_queue. The process-email-queue cron picks it up within ~2 minutes.';



CREATE OR REPLACE FUNCTION "public"."queue_payment_reminders"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  p record;
  r record;
  n_sent integer := 0;
  v_day integer;
  v_portal text;
  v_inserted integer;
begin
  for p in
    select id, company_name, slug, custom_domain, custom_domain_verified_at, coalesce(default_payment_reminder_days, '{}') as days
      from public.portfolios where suspended_at is null
  loop
    v_portal := case when p.custom_domain is not null and p.custom_domain_verified_at > now() - interval '3 hours' then 'https://' || p.custom_domain || '/portal/pay' when p.slug ~ '^[a-z0-9][a-z0-9-]{0,62}$'
                     then 'https://' || p.slug || '.portier369.com/portal/pay'
                     else 'https://portier369.com/portal/pay' end;
    foreach v_day in array p.days loop
      for r in
        select occ.id as occupancy_id, occ.allow_online_payments, o.id as owner_id, o.email, o.full_name,
               u.id as unit_id, u.unit_number, a.id as association_id, a.name as association_name,
               sum(cb.balance) as due_amount,
               string_agg(coalesce(nullif(btrim(cb.description), ''), 'Charge') || ' ' || to_char(cb.balance, 'FM$999,999,990.00'), ', ' order by cb.description) as items,
               (select coalesce(sum(b2.balance), 0) from (
                  select c2.amount - coalesce((select sum(pa.amount_applied) from public.payment_applications pa where pa.charge_id = c2.id), 0) as balance
                    from public.charges c2 where c2.unit_id = u.id) b2 where b2.balance > 0) as unit_balance
          from (select c.id, c.unit_id, c.description, c.due_date,
                       c.amount - coalesce((select sum(pa.amount_applied) from public.payment_applications pa where pa.charge_id = c.id), 0) as balance
                  from public.charges c
                 where c.due_date = current_date + v_day) cb
          join public.units u on u.id = cb.unit_id
          join public.buildings b on b.id = u.building_id
          join public.associations a on a.id = b.association_id and a.portfolio_id = p.id
          join public.occupancies occ on occ.unit_id = u.id and occ.status = 'current' and occ.occupancy_type = 'owner'
          join public.owners o on o.id = occ.owner_id
         where cb.balance > 0
           and occ.send_dues_reminders
           and not occ.in_collections and not occ.in_foreclosure
           and o.archived_at is null and o.email is not null and btrim(o.email) <> ''
         group by occ.id, occ.allow_online_payments, o.id, o.email, o.full_name, u.id, u.unit_number, a.id, a.name
      loop
        insert into public.email_queue (to_email, to_name, subject, body, portfolio_id, association_id,
                                        owner_id, status, idempotency_key)
        values (
          r.email, r.full_name,
          case when v_day > 0 then format('Payment reminder: %s due in %s day%s', to_char(r.due_amount, 'FM$999,999,990.00'), v_day, case when v_day = 1 then '' else 's' end)
               when v_day = 0 then format('Payment due today: %s', to_char(r.due_amount, 'FM$999,999,990.00'))
               else format('Past due: %s was due %s day%s ago', to_char(r.due_amount, 'FM$999,999,990.00'), -v_day, case when v_day = -1 then '' else 's' end) end,
          '<div style="font-family:system-ui,-apple-system,Segoe UI,Arial,sans-serif;line-height:1.6;color:#111827">'
            || '<p>Hello ' || public.html_escape(coalesce(nullif(btrim(r.full_name), ''), 'Homeowner')) || ',</p>'
            || '<p>' || case when v_day > 0 then 'This is a friendly reminder that a payment for '
                             when v_day = 0 then 'A payment is due today for '
                             else 'We have not yet received a payment that was due on ' || to_char(current_date + v_day, 'FMMonth FMDD, YYYY') || ' for ' end
            || '<strong>Unit ' || public.html_escape(r.unit_number) || '</strong> at ' || public.html_escape(r.association_name)
            || case when v_day > 0 then ' is due on ' || to_char(current_date + v_day, 'FMMonth FMDD, YYYY') else '' end || '.</p>'
            || '<p>' || public.html_escape(r.items) || '</p>'
            || '<p>Total balance on the account: <strong>' || to_char(r.unit_balance, 'FM$999,999,990.00') || '</strong></p>'
            || case when r.allow_online_payments
                    then '<p><a href="' || v_portal || '" style="display:inline-block;background:#111827;color:#fff;padding:10px 16px;border-radius:8px;text-decoration:none">Pay online</a></p>'
                    else '<p>Please contact the management office to arrange payment.</p>' end
            || '<p style="color:#6b7280;font-size:13px">If you have already paid, thank you — please disregard this message.</p>'
            || '<p style="color:#6b7280;font-size:13px">' || public.html_escape(p.company_name) || '</p></div>',
          p.id, r.association_id, r.owner_id, 'pending',
          'dues-reminder:' || r.occupancy_id || ':' || current_date || ':' || v_day)
        on conflict do nothing;
        get diagnostics v_inserted = row_count;
        n_sent := n_sent + v_inserted;
      end loop;
    end loop;
  end loop;
  return n_sent;
end $_$;


ALTER FUNCTION "public"."queue_payment_reminders"() OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."report_runs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "portfolio_id" "uuid" NOT NULL,
    "definition_id" "uuid" NOT NULL,
    "saved_report_id" "uuid",
    "scheduled_report_id" "uuid",
    "status" "public"."report_run_status" DEFAULT 'queued'::"public"."report_run_status" NOT NULL,
    "parameters" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "output_format" "public"."report_format" DEFAULT 'pdf'::"public"."report_format" NOT NULL,
    "output_url" "text",
    "output_size_bytes" bigint,
    "row_count" integer,
    "started_at" timestamp with time zone,
    "finished_at" timestamp with time zone,
    "duration_ms" integer GENERATED ALWAYS AS (
CASE
    WHEN (("started_at" IS NOT NULL) AND ("finished_at" IS NOT NULL)) THEN ((EXTRACT(epoch FROM ("finished_at" - "started_at")) * (1000)::numeric))::integer
    ELSE NULL::integer
END) STORED,
    "error_message" "text",
    "triggered_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."report_runs" OWNER TO "postgres";


COMMENT ON TABLE "public"."report_runs" IS 'Async generation log. duration_ms is computed from started_at/finished_at.';



CREATE OR REPLACE FUNCTION "public"."queue_report_run"("p_definition_id" "uuid", "p_parameters" "jsonb" DEFAULT '{}'::"jsonb", "p_saved_report_id" "uuid" DEFAULT NULL::"uuid", "p_output_format" "public"."report_format" DEFAULT 'csv'::"public"."report_format") RETURNS "public"."report_runs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  def public.report_definitions;
  row public.report_runs;
  target_portfolio uuid;
  v_error text;
begin
  select * into def from public.report_definitions where id = p_definition_id and active;
  if not found then raise exception 'report definition not found'; end if;
  target_portfolio := coalesce(def.portfolio_id, public.current_portfolio_id());
  if target_portfolio is null then raise exception 'cannot determine target portfolio for report run'; end if;
  if not public.can_access_portfolio(target_portfolio) then
    raise exception 'insufficient permissions for portfolio %', target_portfolio using errcode = '42501';
  end if;
  v_error := public.report_params_access_error(target_portfolio, def.slug, coalesce(p_parameters, '{}'::jsonb));
  if v_error is not null then raise exception '%', v_error using errcode = '42501'; end if;
  if p_saved_report_id is not null and not exists (
       select 1 from public.saved_reports s where s.id = p_saved_report_id and s.portfolio_id = target_portfolio) then
    raise exception 'saved report not found' using errcode = 'P0002';
  end if;

  insert into public.report_runs (portfolio_id, definition_id, saved_report_id, status, parameters, output_format, triggered_by)
  values (target_portfolio, p_definition_id, p_saved_report_id, 'queued', coalesce(p_parameters, '{}'::jsonb), p_output_format, auth.uid())
  returning * into row;
  return row;
end $$;


ALTER FUNCTION "public"."queue_report_run"("p_definition_id" "uuid", "p_parameters" "jsonb", "p_saved_report_id" "uuid", "p_output_format" "public"."report_format") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rate_work_order"("p_work_order_id" "uuid", "p_score" integer, "p_quality" integer, "p_timeliness" integer, "p_communication" integer, "p_would_hire_again" boolean, "p_comment" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare wo record; v_role text; v_id uuid;
begin
  if auth.uid() is null then raise exception 'Sign in to rate this job' using errcode = '42501'; end if;
  select w.id, w.status::text as status, w.vendor_id, w.unit_id, w.association_id, w.created_at,
         coalesce(w.portfolio_id, a.portfolio_id) as portfolio_id
    into wo
    from public.work_orders w left join public.associations a on a.id = w.association_id
   where w.id = p_work_order_id and w.archived_at is null;
  if not found then raise exception 'Work order not found' using errcode = 'P0002'; end if;

  if public.can_access_portfolio(wo.portfolio_id) and public.can_view_association_row(wo.association_id) then
    v_role := 'staff';
  elsif false then
    v_role := 'board';
  elsif wo.unit_id is not null and exists (
          select 1 from public.occupancies o
           where o.unit_id = wo.unit_id and o.owner_id in (select public.current_owner_ids())
             and o.status = 'current'::public.occupancy_status)
        and wo.unit_id in (select public.current_resident_unit_ids())
        and (public.current_resident_unit_since(wo.unit_id) is null
             or public.association_local_date(wo.association_id, wo.created_at) >= public.current_resident_unit_since(wo.unit_id)) /* work_orders_fixes */ then
    v_role := 'owner';
  else
    raise exception 'Work order not found' using errcode = 'P0002';
  end if;

  if wo.status not in ('done', 'completed', 'billed', 'closed') then
    raise exception 'You can rate the job once it is completed' using errcode = '55000';
  end if;
  if wo.vendor_id is null then
    raise exception 'This job had no vendor to rate' using errcode = '55000';
  end if;
  if p_score is null or p_score not between 1 and 5
     or (p_quality is not null and p_quality not between 1 and 5)
     or (p_timeliness is not null and p_timeliness not between 1 and 5)
     or (p_communication is not null and p_communication not between 1 and 5) then
    raise exception 'Ratings are from 1 to 5 stars' using errcode = '22023';
  end if;
  if length(coalesce(p_comment, '')) > 2000 then
    raise exception 'Comments are limited to 2,000 characters' using errcode = '22023';
  end if;

  insert into public.work_order_ratings as r
    (portfolio_id, work_order_id, vendor_id, rated_by, rater_role, score, quality, timeliness, communication, would_hire_again, comment)
  values (wo.portfolio_id, wo.id, wo.vendor_id, auth.uid(), v_role, p_score, p_quality, p_timeliness, p_communication,
          p_would_hire_again, nullif(btrim(p_comment), ''))
  on conflict (work_order_id, rated_by) do update set
    score = excluded.score, quality = excluded.quality, timeliness = excluded.timeliness,
    communication = excluded.communication, would_hire_again = excluded.would_hire_again,
    comment = excluded.comment, rater_role = excluded.rater_role, updated_at = now()
  returning id into v_id;
  return v_id;
end $$;


ALTER FUNCTION "public"."rate_work_order"("p_work_order_id" "uuid", "p_score" integer, "p_quality" integer, "p_timeliness" integer, "p_communication" integer, "p_would_hire_again" boolean, "p_comment" "text") OWNER TO "postgres";


