    CONSTRAINT "portfolios_company_name_check" CHECK ((("length"("company_name") >= 1) AND ("length"("company_name") <= 200))),
    CONSTRAINT "portfolios_company_name_not_blank" CHECK (("company_name" ~ '[^[:space:] ]'::"text")),
    CONSTRAINT "portfolios_company_name_visible" CHECK (("company_name" ~ (('[^[:space:]'::"text" || "chr"(160)) || ']'::"text"))),
    CONSTRAINT "portfolios_company_name_visible_chars" CHECK (("company_name" ~ '[^	-  ­͏؀-؅؜۝܏࢐-࢑࣢ᅟ-ᅠ ឴-឵᠋-᠏ -‏ -  -⁯　ㅤ︀-️﻿ﾠ￰-￻𑂽𑃍𓐰-𓐿𛲠-𛲣𝅳-𝅺󠀀-󠿿]'::"text")),
    CONSTRAINT "portfolios_convenience_fee_ach_fixed_cents_check" CHECK (("convenience_fee_ach_fixed_cents" >= 0)),
