ALTER TABLE "public"."portfolios" OWNER TO "postgres";


COMMENT ON TABLE "public"."portfolios" IS 'Top-level tenant (management company) — multi-tenancy root';



COMMENT ON COLUMN "public"."portfolios"."default_payment_reminder_days" IS 'Days relative to charge.due_date when reminders fire. Positive = before due; negative = after due.';



COMMENT ON COLUMN "public"."portfolios"."convenience_fee_mode" IS 'How to handle processor fees. pass_through is the cheapest path for the management company.';



COMMENT ON COLUMN "public"."portfolios"."slug" IS 'URL-safe identifier used as a subdomain on portier369.com (e.g. "beacon" → beacon.portier369.com).';



COMMENT ON COLUMN "public"."portfolios"."custom_domain" IS 'Optional vanity domain mapped via CNAME to Vercel (e.g. "app.managebeacon.com").';



COMMENT ON COLUMN "public"."portfolios"."logo_url" IS 'Public Supabase Storage URL for the tenant''s brand mark. Shown on auth pages and the resident portal when reached via the tenant''s subdomain or custom domain.';



COMMENT ON COLUMN "public"."portfolios"."website" IS 'Public-facing website. Shown on the portal and owner statements.';



COMMENT ON COLUMN "public"."portfolios"."brand_email" IS 'Public-facing inbox (e.g. info@beacon.co). Shown on the owner portal & invoices.';



COMMENT ON COLUMN "public"."portfolios"."billing_email_from" IS 'From: address on outbound statements (defaults to billing@portier369.com if blank).';



COMMENT ON COLUMN "public"."portfolios"."favicon_url" IS 'Public Supabase Storage URL for the tenant''s favicon. Served via <link rel="icon"> when the request reaches us via the tenant''s subdomain or custom domain.';



COMMENT ON COLUMN "public"."portfolios"."email_settings" IS 'Per-portfolio email configuration. Shape:
{
  "provider": "resend" | "smtp" | "sendgrid" | "postmark",
  "from_address": "manager@company.com",
  "from_name": "Company Name",
  "reply_to": "support@company.com",
  "smtp": { "host": "", "port": 587, "user": "", "pass_encrypted": null }
}';



COMMENT ON COLUMN "public"."portfolios"."ai_api_key_ciphertext" IS 'Application-encrypted BYO AI credential (AES-256-GCM envelope); never plaintext.';



COMMENT ON COLUMN "public"."portfolios"."custom_domain_verified_at" IS 'Last time the domain check reached this company over HTTPS on custom_domain. Never set by API users; reset when custom_domain changes.';



COMMENT ON COLUMN "public"."portfolios"."reactivated_at" IS 'When the company''s last suspension was lifted. Set by portfolios_guard_platform_columns; not writable by signed-in users. cron_assess_late_fees holds late fees on units with due AutoPay for 24 hours after it.';



CREATE OR REPLACE FUNCTION "public"."reactivate_portfolio"("p_portfolio_id" "uuid") RETURNS "public"."portfolios"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  updated public.portfolios;
begin
  if not public.is_platform_operator() then
    raise exception 'reactivate_portfolio: platform operator required';
  end if;

  update public.portfolios
     set suspended_at = null, suspension_reason = null, updated_at = now()
   where id = p_portfolio_id
   returning * into updated;

  update public.subscriptions set status = 'active', updated_at = now()
   where portfolio_id = p_portfolio_id and status = 'paused';
  return updated;
end;
$$;


ALTER FUNCTION "public"."reactivate_portfolio"("p_portfolio_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reallocate_payment"("p_payment_id" "uuid", "p_allocations" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  pay public.payments;
  v_assoc uuid;
  v_pid uuid;
  a record;
  v_charge record;
  v_open numeric(14,2);
  v_total numeric(14,2) := 0;
begin
  select * into pay from public.payments where id = p_payment_id for update;
  if not found then raise exception 'Payment not found' using errcode = 'P0002'; end if;
  v_assoc := public.unit_association_id(pay.unit_id);
  select portfolio_id into v_pid from public.associations where id = v_assoc;
  if v_pid is null or not public.can_manage_finance(v_pid) or not public.can_manage_association(v_assoc) then
    raise exception 'You do not have accounting access to this association' using errcode = '42501';
  end if;
  if pay.reversed_at is not null then
    raise exception 'This payment was reversed and cannot be reallocated' using errcode = '22023';
  end if;
  -- removed_late_fee_no_reallocation: a removed late fee's credit stays on that fee.
  if pay.method = 'credit' and pay.reference = 'Late fee removed' then
    raise exception 'This credit removed a late fee and stays applied to it.' using errcode = '22023';
  end if;
  if p_allocations is null or jsonb_typeof(p_allocations) <> 'array' then
    raise exception 'Allocations must be a list' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('unit-apply:' || pay.unit_id::text, 0));
  delete from public.payment_applications where payment_id = p_payment_id;

  for a in
    select (x->>'charge_id')::uuid as charge_id, round(sum((x->>'amount')::numeric), 2) as amount
      from jsonb_array_elements(p_allocations) x
     where nullif(x->>'charge_id', '') is not null and coalesce((x->>'amount')::numeric, 0) > 0
     group by 1
  loop
    select c.id, c.unit_id, c.amount, c.description into v_charge from public.charges c where c.id = a.charge_id for update;
    if not found or v_charge.unit_id is distinct from pay.unit_id then
      raise exception 'A selected charge is not on this unit' using errcode = '23514';
    end if;
    v_open := v_charge.amount - coalesce((select sum(pa.amount_applied) from public.payment_applications pa where pa.charge_id = a.charge_id), 0);
    if a.amount > v_open then
      raise exception 'Applying % to "%" is more than its open balance (%)', a.amount, coalesce(v_charge.description, 'charge'), v_open using errcode = '23514';
    end if;
    v_total := v_total + a.amount;
    if v_total > pay.amount then
      raise exception 'The allocations (%) are more than the payment (%)', v_total, pay.amount using errcode = '23514';
    end if;
    insert into public.payment_applications (payment_id, charge_id, amount_applied, applied_by, application_method)
    values (p_payment_id, a.charge_id, a.amount, auth.uid(), 'manual');
  end loop;

  insert into public.audit_logs (portfolio_id, entity_type, entity_id, action, actor_id, actor_email, changes)
  values (v_pid, 'payment', p_payment_id, 'payment_reallocated', auth.uid(), (select email from auth.users where id = auth.uid()),
          jsonb_build_object('allocations', p_allocations, 'applied', v_total));

  return jsonb_build_object('applied', v_total, 'unapplied', pay.amount - v_total);
end
$$;


ALTER FUNCTION "public"."reallocate_payment"("p_payment_id" "uuid", "p_allocations" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."receipt_deposit_groups"("p_association_id" "uuid" DEFAULT NULL::"uuid", "p_unit_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS TABLE("payment_date" "date", "bank_account_id" "uuid", "bank_account_name" "text", "bank_name" "text", "receipt_count" bigint, "total" numeric)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    SET "plan_cache_mode" TO 'force_generic_plan'
    AS $$
begin
  return query
  select l.payment_date,
         l.bank_account_id,
         min(l.bank_account_name),
         min(l.bank_name),
         count(*),
         coalesce(sum(l.amount), 0)
    from public.receivable_payments_ledger l
   where (l.method is null or l.method <> 'credit')
     and (p_association_id is null or l.association_id = p_association_id)
     and (p_unit_ids is null or l.unit_id = any (p_unit_ids))
   group by l.payment_date, l.bank_account_id;
end
$$;


