CREATE OR REPLACE FUNCTION "public"."receivable_summary"("p_association_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_as_of" "date" DEFAULT NULL::"date") RETURNS TABLE("ar_total" numeric, "overdue_total" numeric, "delinquent_units" integer, "weighted_days" numeric)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  with open_rows as (
    select r.unit_id, r.balance_due, r.due_date, r.association_id
      from public.aged_receivables r
     where (p_association_ids is null or r.association_id = any (p_association_ids))
       and r.balance_due > 0
  ),
  days as materialized (
    select x.association_id, coalesce(p_as_of, public.association_local_date(x.association_id)) as as_of
      from (select distinct association_id from open_rows) x
  ),
  ar as (
    select r.unit_id, r.balance_due, r.due_date, d.as_of
      from open_rows r join days d on d.association_id = r.association_id
  )
  select coalesce(sum(ar.balance_due), 0)::numeric,
         coalesce(sum(ar.balance_due) filter (where ar.due_date < ar.as_of), 0)::numeric,
         (count(distinct ar.unit_id) filter (where ar.due_date < ar.as_of))::integer,
         case when coalesce(sum(ar.balance_due) filter (where ar.due_date is not null), 0) > 0
              then sum(greatest(0, ar.as_of - ar.due_date) * ar.balance_due) filter (where ar.due_date is not null)
                   / sum(ar.balance_due) filter (where ar.due_date is not null)
              else null end::numeric
    from ar;
$$;


ALTER FUNCTION "public"."receivable_summary"("p_association_ids" "uuid"[], "p_as_of" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."receivable_summary_as_of"("p_association_ids" "uuid"[], "p_as_of" "date", "p_cutoff" timestamp with time zone) RETURNS TABLE("ar_total" numeric, "overdue_total" numeric, "delinquent_units" integer)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  with bal as (
    select c.unit_id,
           c.due_date,
           c.amount - coalesce((
             select sum(pa.amount_applied)
               from public.payment_applications pa
              where pa.charge_id = c.id
                and coalesce(pa.applied_at, pa.created_at) < p_cutoff
           ), 0) as due
      from public.charges c
      join public.units u on u.id = c.unit_id
      join public.buildings b on b.id = u.building_id
     where c.created_at < p_cutoff
       and (p_association_ids is null or b.association_id = any (p_association_ids))
  )
  select coalesce(sum(due) filter (where due > 0), 0)::numeric,
         coalesce(sum(due) filter (where due > 0 and due_date < p_as_of), 0)::numeric,
         (count(distinct unit_id) filter (where due > 0 and due_date < p_as_of))::integer
    from bal;
$$;


ALTER FUNCTION "public"."receivable_summary_as_of"("p_association_ids" "uuid"[], "p_as_of" "date", "p_cutoff" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."receivable_summary_by_months"("p_association_ids" "uuid"[], "p_months" "jsonb") RETURNS TABLE("ord" bigint, "ar_total" numeric, "overdue_total" numeric, "delinquent_units" integer)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  with m as (
    select x.ord, (x.v->>'to')::date as as_of, (x.v->>'end')::timestamptz as cutoff
      from jsonb_array_elements(p_months) with ordinality as x(v, ord)
  ),
  c as (
    select c.id, c.unit_id, c.due_date, c.amount, c.created_at
      from public.charges c
      join public.units u on u.id = c.unit_id
      join public.buildings b on b.id = u.building_id
     where (p_association_ids is null or b.association_id = any (p_association_ids))
       and c.created_at < (select max(cutoff) from m)
  ),
  pa as (
    select pa.charge_id, pa.amount_applied, coalesce(pa.applied_at, pa.created_at) as applied
      from public.payment_applications pa
     where pa.charge_id in (select id from c)
  ),
  -- A join, not a per-row subquery: each charge's applications are summed
  -- once per month end instead of rescanning every application.
  bal as (
    select m.ord, m.as_of, c.unit_id, c.due_date,
           c.amount - coalesce(sum(p.amount_applied), 0) as due
      from m
      join c on c.created_at < m.cutoff
      left join pa p on p.charge_id = c.id and p.applied < m.cutoff
     group by m.ord, m.as_of, c.id, c.unit_id, c.due_date, c.amount
  )
  select m.ord,
         coalesce(sum(b.due) filter (where b.due > 0), 0)::numeric,
         coalesce(sum(b.due) filter (where b.due > 0 and b.due_date < m.as_of), 0)::numeric,
         (count(distinct b.unit_id) filter (where b.due > 0 and b.due_date < m.as_of))::integer
    from m
    left join bal b on b.ord = m.ord
   group by m.ord
$$;


ALTER FUNCTION "public"."receivable_summary_by_months"("p_association_ids" "uuid"[], "p_months" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."receivable_unit_totals"("p_unit_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS TABLE("outstanding_total" numeric, "delinquent_count" integer, "delinquent_balance" numeric)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    SET "plan_cache_mode" TO 'force_generic_plan'
    AS $$
declare
  v_open numeric;
  v_credit numeric;
  v_count integer;
  v_balance numeric;
begin
  -- Open charges less credit on file (unapplied payments and credits).
  if p_unit_ids is null then
    select coalesce(sum(ar.balance_due), 0) into v_open from public.aged_receivables ar;
    select coalesce(sum(uc.unapplied_amount), 0) into v_credit from public.v_unapplied_credits uc;
    select count(*)::integer, coalesce(sum(du.balance), 0) into v_count, v_balance from public.delinquent_units du;
  else
    select coalesce(sum(ar.balance_due), 0) into v_open from public.aged_receivables ar where ar.unit_id = any (p_unit_ids);
    select coalesce(sum(uc.unapplied_amount), 0) into v_credit from public.v_unapplied_credits uc where uc.unit_id = any (p_unit_ids);
    select count(*)::integer, coalesce(sum(du.balance), 0) into v_count, v_balance from public.delinquent_units du where du.unit_id = any (p_unit_ids);
  end if;

  return query select (v_open - v_credit)::numeric, v_count, v_balance::numeric;
end
$$;


ALTER FUNCTION "public"."receivable_unit_totals"("p_unit_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."receivables_page_totals"("p_association_id" "uuid" DEFAULT NULL::"uuid", "p_owner_unit_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_totals_unit_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    SET "plan_cache_mode" TO 'force_generic_plan'
    AS $$
declare
  v_receipts jsonb;
  v_delinquent jsonb;
  v_delinquent_count integer;
  v_delinquent_balance numeric;
  v_unit_totals jsonb;
  v_open numeric;
  v_credit numeric;
  v_categories jsonb := '[]'::jsonb;
begin
  -- Cash receipts: homeowner credits are not receipts; returned (NSF)
  -- payments were never collected.
  select jsonb_build_object('count', count(*), 'amount', coalesce(sum(l.amount), 0))
    into v_receipts
    from public.payments l
   where (l.method is null or l.method <> 'credit')
     and l.reversed_at is null
     and (p_association_id is null
          or exists (select 1
                       from public.units u
                       join public.buildings b on b.id = u.building_id
                       join public.associations a on a.id = b.association_id
                      where u.id = l.unit_id and a.id = p_association_id))
     and (p_owner_unit_ids is null or l.unit_id = any (p_owner_unit_ids));

  select coalesce(jsonb_agg(jsonb_build_object(
           'unit_id', d.unit_id, 'unit_number', d.unit_number, 'association_id', d.association_id,
           'balance', d.balance, 'oldest_due', d.oldest_due) order by d.unit_id), '[]'::jsonb),
         count(*)::integer,
         coalesce(sum(d.balance), 0)
    into v_delinquent, v_delinquent_count, v_delinquent_balance
    from public.delinquent_units d
   where (p_association_id is null or d.association_id = p_association_id)
     and (p_owner_unit_ids is null or d.unit_id = any (p_owner_unit_ids));

  if p_totals_unit_ids is null and p_association_id is null and p_owner_unit_ids is null then
    -- Same expressions as receivable_unit_totals(null); delinquent_units is
    -- not read a second time.
    select coalesce(sum(ar.balance_due), 0) into v_open from public.aged_receivables ar;
    select coalesce(sum(uc.unapplied_amount), 0) into v_credit from public.v_unapplied_credits uc;
    v_unit_totals := jsonb_build_object(
      'outstanding_total', (v_open - v_credit)::numeric,
      'delinquent_count', v_delinquent_count,
      'delinquent_balance', v_delinquent_balance::numeric);
  else
    select to_jsonb(t) into v_unit_totals from public.receivable_unit_totals(p_totals_unit_ids) t;
  end if;

  if p_association_id is null and p_owner_unit_ids is null then
    select coalesce(jsonb_agg(c), '[]'::jsonb)
      into v_categories
      from (select v.category_id,
                   min(v.category_name) as category_name,
                   sum(v.charge_count) as charge_count,
                   sum(v.outstanding_balance) as outstanding_balance
              from public.v_charges_by_category v
             group by v.category_id) c;
  end if;

  return jsonb_build_object(
    'receipts', v_receipts,
    'delinquent', v_delinquent,
    'unit_totals', v_unit_totals,
    'categories', v_categories
  );
end
$$;


ALTER FUNCTION "public"."receivables_page_totals"("p_association_id" "uuid", "p_owner_unit_ids" "uuid"[], "p_totals_unit_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."receivables_task_associations"() RETURNS TABLE("association_id" "uuid", "name" "text", "unapplied" numeric, "late_fee_enabled" boolean, "late_fee_amount" numeric, "late_fee_is_percent" boolean, "late_fee_grace_days" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select a.id, a.name,
         coalesce((select sum(v.unapplied_amount) from public.v_unapplied_credits v
                     join public.units u on u.id = v.unit_id join public.buildings b on b.id = u.building_id
                    where b.association_id = a.id and v.unapplied_amount > 0.005), 0),
         coalesce(a.late_fee_enabled, false) and coalesce(a.late_fee_amount, 0) > 0,
         a.late_fee_amount, a.late_fee_is_percent, coalesce(a.late_fee_grace_days, 0)::integer
    from public.associations a
   where a.archived_at is null
     and public.can_manage_finance(a.portfolio_id)
     and public.can_manage_association(a.id)
   order by a.name;
$$;


ALTER FUNCTION "public"."receivables_task_associations"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."receive_bank_transaction_as_payment"("p_id" "uuid", "p_unit_id" "uuid", "p_remember_sender" boolean DEFAULT true) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  t public.bank_transactions;
  b public.bank_accounts;
  v_assocs uuid[];
  v_unit_assoc uuid;
  v_desc text;
  p record;
  v_sender text;
  v_key text;
  v_method text;
  v_conf numeric;
  v_reason text;
  v_payment uuid;
  v_deposit uuid;
begin
  -- Locks the line (FOR UPDATE), checks finance access and association scope,
  -- refuses pending or already matched lines.
  t := public.app_bank_transaction_for_update(p_id);
  if t.ignored_at is not null then
    raise exception 'This transaction is ignored: put it back in review first' using errcode = '22023';
  end if;
  if t.amount is null or t.amount >= 0 then
    raise exception 'Only money coming in can be received as an owner payment' using errcode = '22023';
  end if;
  select * into b from public.bank_accounts where id = t.bank_account_id;
  v_assocs := public.app_bank_account_association_ids(b.id);

  select bl.association_id into v_unit_assoc
    from public.units u join public.buildings bl on bl.id = u.building_id
   where u.id = p_unit_id and u.archived_at is null;
  if v_unit_assoc is null or not (v_unit_assoc = any (v_assocs)) or not public.can_view_association_row(v_unit_assoc) then
    raise exception 'Choose a unit in this bank account''s association' using errcode = '22023';
  end if;

  v_desc := coalesce(nullif(btrim(t.original_description), ''), t.name, '');
  select * into p from public.parse_bank_payment_description(v_desc);
  v_sender := coalesce(nullif(btrim(t.payer_name), ''), p.sender);
  v_key := public.payment_sender_key(v_sender);
  -- A remembered sender is a name of two words or more: a single word
  -- ("CHK" from "ONLINE TRANSFER FROM CHK 1234") would match unrelated credits.
  if position(' ' in coalesce(v_key, '')) = 0 then v_key := null; end if;
  v_method := case
    when v_desc ~* 'zelle' or coalesce(t.name, '') ~* 'zelle' then 'zelle'
    when v_desc ~* '\m(ach|ppd|ccd|web)\M' then 'ach'
    else 'other' end;

  select s.confidence, s.reason into v_conf, v_reason
    from public.suggest_bank_transaction_payment(t.id) s where s.unit_id = p_unit_id;

  -- The normal receipt path: the payments triggers apply it to the unit's
  -- charges and post Dr bank / Cr A/R (closed periods refuse it there).
  insert into public.payments (unit_id, amount, payment_date, method, reference, notes, bank_account_id, created_by)
  values (p_unit_id, round(-t.amount, 2), t.date, v_method,
          left(coalesce(case when v_method = 'zelle' then 'Zelle' else 'Bank' end || ' ' || p.reference,
                        case when v_method = 'zelle' then 'Zelle' else 'Bank transfer' end), 100),
          left(btrim(concat_ws(' ' || chr(183) || ' ', 'Received from the bank feed', v_sender, nullif(btrim(coalesce(p.memo, t.payment_reason, '')), ''))), 1000),
          b.id, auth.uid())
  returning id into v_payment;

  v_deposit := public.create_bank_deposit(b.id, t.date, array[v_payment], null::uuid[], 'Owner payment received from the bank feed');
  perform public.match_bank_transaction_to_deposit(t.id, v_deposit);
  update public.bank_transactions
     set match_method = 'owner_payment', match_confidence = v_conf
   where id = t.id;

  if coalesce(p_remember_sender, true) and v_key is not null then
    insert into public.payment_sender_aliases (portfolio_id, association_id, unit_id, sender_key, created_by)
    values (b.portfolio_id, v_unit_assoc, p_unit_id, left(v_key, 200), auth.uid())
    on conflict (association_id, sender_key)
      do update set unit_id = excluded.unit_id, last_used_at = now();
  end if;

  insert into public.audit_logs (portfolio_id, entity_type, entity_id, action, actor_id, actor_email, changes)
  values (b.portfolio_id, 'bank_transaction', t.id, 'received_as_owner_payment', auth.uid(),
          (select email from auth.users where id = auth.uid()),
          jsonb_build_object('payment_id', v_payment, 'bank_deposit_id', v_deposit, 'unit_id', p_unit_id,
                             'method', v_method, 'suggested', v_reason is not null, 'reason', v_reason,
                             'remembered_sender', coalesce(p_remember_sender, true) and v_key is not null));
  return v_payment;
end
$$;


ALTER FUNCTION "public"."receive_bank_transaction_as_payment"("p_id" "uuid", "p_unit_id" "uuid", "p_remember_sender" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recent_failed_attempts"("p_email" "text", "p_window_minutes" integer DEFAULT 15) RETURNS integer
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$#variable_conflict use_column
begin
  return (select s.x from (

  select count(*)::integer
    from public.login_attempts
   where lower(email) = lower(p_email)
     and not success
     and at > now() - make_interval(mins => p_window_minutes)
  ) s(x) limit 1);
end$$;


