CREATE OR REPLACE FUNCTION "public"."reclassify_service_request"("p_id" "uuid", "p_kind" "text", "p_topic" "text", "p_category" "public"."work_order_category") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v public.service_requests;
begin
  v := public.service_request_staff_scope(p_id);
  if p_kind not in ('maintenance', 'admin') then raise exception 'Unknown request type' using errcode = '22023'; end if;
  if p_kind = 'admin' and (p_topic is null or p_topic not in ('account', 'documents', 'insurance', 'move', 'access', 'governance')) then
    raise exception 'Pick what the question is about' using errcode = '22023';
  end if;
  update public.service_requests
     set request_kind = p_kind,
         admin_topic = case when p_kind = 'admin' then p_topic end,
         category = case when p_kind = 'admin' then 'other' else coalesce(p_category, category, 'general_repair') end,
         updated_at = now()
   where id = p_id;
end $$;


ALTER FUNCTION "public"."reclassify_service_request"("p_id" "uuid", "p_kind" "text", "p_topic" "text", "p_category" "public"."work_order_category") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_approval_decision"("p_request_id" "uuid", "p_decision" "text", "p_note" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  r public.approval_requests%rowtype;
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
  v_name text;
  v_money boolean;
begin
  if auth.uid() is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  if p_decision is null or p_decision not in ('approved', 'rejected') then
    raise exception 'Choose approved or rejected' using errcode = '22023';
  end if;
  if v_note is not null and char_length(v_note) > 1000 then
    raise exception 'The note must be 1,000 characters or fewer' using errcode = '22023';
  end if;

  select * into r from public.approval_requests where id = p_request_id for update;
  if not found or r.archived_at is not null then
    raise exception 'Approval request not found' using errcode = 'P0002';
  end if;

  -- A request behind a bill or purchase order is a money decision.
  v_money := exists (select 1 from public.payable_bills b where b.approval_request_id = r.id)
          or exists (select 1 from public.purchase_orders po where po.approval_request_id = r.id);
  if not public.operator_may_write(false)
     or not (case when v_money
                  then public.can_manage_finance(r.portfolio_id) and public.can_view_association_row(r.association_id)
                  else public.can_edit_association_mvp(r.association_id) end) then
    raise exception 'Permission denied' using errcode = '42501';
  end if;
  if r.status is distinct from 'pending'::public.approval_request_status then
    raise exception 'This approval request is already decided' using errcode = '55000';
  end if;

  select coalesce(nullif(btrim(full_name), ''), 'Management staff') into v_name from public.profiles where id = auth.uid();

  insert into public.approval_decisions (approval_request_id, decided_by, decision, signature_name, comment, decided_at)
  values (r.id, auth.uid(), case p_decision when 'approved' then 'approve' else 'reject' end,
          'Board decision recorded by ' || coalesce(v_name, 'management staff'), v_note, now())
  on conflict (approval_request_id, decided_by) do update
     set decision = excluded.decision, signature_name = excluded.signature_name,
         comment = excluded.comment, decided_at = excluded.decided_at;

  perform set_config('app.approval_decision', 'on', true);
  update public.approval_requests
     set status = p_decision::public.approval_request_status,
         decision_by = auth.uid(),
         decision_at = now(),
         notes = case when v_note is null then notes
                      else concat_ws(E'\n', nullif(notes, ''), 'Board decision: ' || v_note) end,
         updated_at = now()
   where id = r.id;
  perform set_config('app.approval_decision', 'off', true);
end
$$;


ALTER FUNCTION "public"."record_approval_decision"("p_request_id" "uuid", "p_decision" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_bank_deposit"("p_bank_account_id" "uuid", "p_credit_gl_id" "uuid", "p_deposit_date" "date", "p_amount" numeric, "p_memo" "text", "p_received_from" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_bank public.bank_accounts;
  v_entry uuid;
  v_memo text := nullif(btrim(coalesce(p_memo, '')), '');
begin
  select * into v_bank from public.bank_accounts where id = p_bank_account_id and archived_at is null;
  if not found or not public.can_manage_finance(v_bank.portfolio_id)
     or (v_bank.association_id is not null and not public.can_view_association_row(v_bank.association_id)) then
    raise exception 'Bank account not found' using errcode = 'P0002';
  end if;
  if v_bank.gl_account_id is null then
    raise exception '"%" has no linked GL account. Link one on the bank account before recording deposits.', v_bank.name using errcode = '22023';
  end if;
  if p_deposit_date is null then raise exception 'Deposit date is required' using errcode = '22023'; end if;
  if p_amount is null or p_amount <= 0 then raise exception 'Deposit amount must be greater than zero' using errcode = '22023'; end if;
  if p_credit_gl_id = v_bank.gl_account_id then
    raise exception 'The credited GL account must differ from the bank account''s GL account' using errcode = '22023';
  end if;
  if not exists (select 1 from public.gl_accounts g where g.id = p_credit_gl_id and g.portfolio_id = v_bank.portfolio_id and g.active
                   and (g.association_id is null or g.association_id is not distinct from v_bank.association_id)) then
    raise exception 'Choose a GL account of this bank account''s association' using errcode = '22023';
  end if;

  insert into public.journal_entries (portfolio_id, entry_date, description, memo, source_type, source_id, created_by, posted, posted_at)
  values (v_bank.portfolio_id, p_deposit_date,
          'Bank deposit — ' || v_bank.name || coalesce(' (from ' || nullif(btrim(coalesce(p_received_from, '')), '') || ')', ''),
          v_memo, 'bank_deposit', v_bank.id, auth.uid(), true, now())
  returning id into v_entry;
  insert into public.journal_lines (entry_id, association_id, gl_account_id, debit_amount, credit_amount, memo, sort_order)
  values (v_entry, v_bank.association_id, v_bank.gl_account_id, round(p_amount, 2), 0, v_memo, 0),
         (v_entry, v_bank.association_id, p_credit_gl_id, 0, round(p_amount, 2), v_memo, 1);
  return v_entry;
end $$;


ALTER FUNCTION "public"."record_bank_deposit"("p_bank_account_id" "uuid", "p_credit_gl_id" "uuid", "p_deposit_date" "date", "p_amount" numeric, "p_memo" "text", "p_received_from" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_bank_transfer"("p_from" "uuid", "p_to" "uuid", "p_amount" numeric, "p_transfer_date" "date", "p_reference" "text", "p_memo" "text", "p_authorize_cross_fund" boolean, "p_authorization_note" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_pid uuid := public.current_portfolio_id();
  f public.bank_accounts;
  d public.bank_accounts;
  v_id uuid;
  v_entry uuid;
  v_amt numeric := round(p_amount, 2);
  v_memo text := nullif(btrim(coalesce(p_memo, '')), '');
  v_ref text := nullif(btrim(coalesce(p_reference, '')), '');
  v_cross boolean;
begin
  if v_pid is null or not public.can_manage_finance(v_pid) then raise exception 'Permission denied' using errcode = '42501'; end if;
  if v_amt is null or v_amt <= 0 then raise exception 'Enter an amount greater than zero' using errcode = '22023'; end if;
  if p_transfer_date is null then raise exception 'Choose the transfer date' using errcode = '22023'; end if;
  perform public.app_check_transfer_accounts(v_pid, p_from, p_to);
  select * into f from public.bank_accounts where id = p_from;
  select * into d from public.bank_accounts where id = p_to;
  v_cross := f.fund_type is distinct from d.fund_type;
  if v_cross and (not coalesce(p_authorize_cross_fund, false) or length(btrim(coalesce(p_authorization_note, ''))) = 0) then
    raise exception 'Moving money from a % account to a % account needs authorization: tick the box and note the board approval or reason',
      coalesce(f.fund_type::text, 'unclassified'), coalesce(d.fund_type::text, 'unclassified') using errcode = '22023';
  end if;

  insert into public.bank_transfers (portfolio_id, from_bank_account_id, to_bank_account_id, amount, transfer_date,
    reference_number, memo, created_by, authorized_by, authorization_note)
  values (v_pid, f.id, d.id, v_amt, p_transfer_date, v_ref, v_memo, auth.uid(),
          case when v_cross then auth.uid() end, case when v_cross then left(btrim(p_authorization_note), 1000) end)
  returning id into v_id;

  insert into public.journal_entries (portfolio_id, entry_date, description, reference_number, memo, source_type, source_id, posted, created_by)
  values (v_pid, p_transfer_date, 'Bank transfer — ' || f.name || ' → ' || d.name, v_ref, v_memo, 'bank_transfer', v_id, false, auth.uid())
  returning id into v_entry;
  insert into public.journal_lines (entry_id, gl_account_id, association_id, debit_amount, credit_amount, memo, sort_order) values
    (v_entry, d.gl_account_id, d.association_id, v_amt, 0, v_memo, 0),
    (v_entry, f.gl_account_id, f.association_id, 0, v_amt, v_memo, 1);
  update public.journal_entries set posted = true, posted_at = now() where id = v_entry;
  update public.bank_transfers set journal_entry_id = v_entry where id = v_id;
  return v_id;
end $$;


ALTER FUNCTION "public"."record_bank_transfer"("p_from" "uuid", "p_to" "uuid", "p_amount" numeric, "p_transfer_date" "date", "p_reference" "text", "p_memo" "text", "p_authorize_cross_fund" boolean, "p_authorization_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_bill_payment"("p_bank_account_id" "uuid", "p_bill_ids" "uuid"[], "p_payment_date" "date", "p_reference" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_bank public.bank_accounts;
  v_bill public.payable_bills;
  v_vendor public.vendors;
  v_id uuid;
  v_ap uuid;
  v_entry uuid;
  v_check uuid;
  v_amount numeric;
  v_method text;
  v_label text;
  n integer := 0;
begin
  if p_bank_account_id is null or coalesce(cardinality(p_bill_ids), 0) = 0 then
    raise exception 'Choose a bank account and at least one bill' using errcode = '22023';
  end if;
  if p_payment_date is null then raise exception 'Choose the payment date' using errcode = '22023'; end if;
  select * into v_bank from public.bank_accounts where id = p_bank_account_id and archived_at is null for update;
  if not found or not public.can_manage_finance(v_bank.portfolio_id) then raise exception 'Permission denied' using errcode = '42501'; end if;
  if not public.can_view_association_row(v_bank.association_id) then raise exception 'Permission denied' using errcode = '42501'; end if;
  if v_bank.gl_account_id is null then raise exception 'The bank account has no cash GL account' using errcode = '22023'; end if;
  if (select count(distinct x) from unnest(p_bill_ids) x) <> cardinality(p_bill_ids) then
    raise exception 'A bill is selected twice' using errcode = '22023';
  end if;

  foreach v_id in array p_bill_ids loop
    select * into v_bill from public.payable_bills where id = v_id for update;
    if not found or v_bill.portfolio_id is distinct from v_bank.portfolio_id then raise exception 'Bill not found' using errcode = 'P0002'; end if;
    if not public.can_view_association_row(v_bill.association_id) then raise exception 'Bill not found' using errcode = 'P0002'; end if;
    if v_bank.association_id is not null and v_bill.association_id is distinct from v_bank.association_id then
      raise exception 'Bill % is not in the bank account''s association', coalesce(v_bill.bill_number, v_id::text) using errcode = '22023';
    end if;
    if v_bill.status <> 'approved' or v_bill.paid_at is not null or v_bill.archived_at is not null then
      raise exception 'Bill % is not approved and unpaid', coalesce(v_bill.bill_number, v_id::text) using errcode = '22023';
    end if;
    if p_payment_date < v_bill.bill_date then
      raise exception 'The payment date can''t be before the date of bill %', coalesce(v_bill.bill_number, v_id::text) using errcode = '22023';
    end if;
    if p_payment_date > coalesce(public.association_local_date(v_bill.association_id, now()), current_date) + 90 then
      raise exception 'The payment date for bill % can be at most 90 days ahead', coalesce(v_bill.bill_number, v_id::text) using errcode = '22023';
    end if;
    select * into v_vendor from public.vendors where id = v_bill.vendor_id;
    if coalesce(v_vendor.hold_payments, false) then
      raise exception 'Payments to % are on hold. Clear "Hold payments" on the vendor first.', coalesce(v_vendor.name, 'this vendor') using errcode = '22023';
    end if;
    if v_vendor.payment_type::text = 'check' and not coalesce(v_vendor.is_auto_pay, false) then
      raise exception '% is paid by check; pay this bill in the check run', v_vendor.name using errcode = '22023';
    end if;
    v_method := case when v_vendor.payment_type::text = 'check' then 'online' else v_vendor.payment_type::text end;
    v_label := case v_method when 'echeck' then 'eCheck' when 'ach' then 'ACH' else 'Online payment' end;
    v_amount := v_bill.amount - coalesce(v_bill.credit_applied, 0);
    if v_amount <= 0 then raise exception 'Bill % has nothing left to pay', coalesce(v_bill.bill_number, v_id::text) using errcode = '22023'; end if;

    perform public.ensure_payable_bill_accrual(v_id);
    select jl.gl_account_id into v_ap from public.journal_lines jl join public.journal_entries je on je.id = jl.entry_id
     where je.source_type = 'payable_bill' and je.source_id = v_id and jl.credit_amount > 0 limit 1;

    insert into public.journal_entries (portfolio_id, entry_date, description, memo, reference_number, source_type, source_id, created_by, posted, posted_at)
    values (v_bill.portfolio_id, p_payment_date, v_label || ': ' || coalesce(v_bill.bill_number, v_vendor.name), v_bill.memo,
            nullif(btrim(coalesce(p_reference, '')), ''), 'check_payment', v_id, auth.uid(), true, now())
    returning id into v_entry;
    insert into public.journal_lines (entry_id, association_id, gl_account_id, debit_amount, credit_amount, memo, sort_order)
    values (v_entry, v_bill.association_id, v_ap, v_amount, 0, v_bill.memo, 1),
           (v_entry, v_bill.association_id, v_bank.gl_account_id, 0, v_amount, v_bill.memo, 2);

    insert into public.payable_checks (portfolio_id, association_id, bill_id, vendor_id, bank_account_id, check_number, amount,
                                       payment_date, payment_entry_id, issued_by, payment_method, reference)
    values (v_bill.portfolio_id, v_bill.association_id, v_id, v_bill.vendor_id, v_bank.id, null, v_amount,
            p_payment_date, v_entry, auth.uid(), v_method, nullif(btrim(coalesce(p_reference, '')), ''))
    returning id into v_check;
    update public.journal_entries set source_id = v_check where id = v_entry;
    update public.payable_bills set status = 'paid', paid_at = (p_payment_date::timestamp + interval '12 hours') at time zone 'UTC', bank_account_id = v_bank.id,
           check_number = null, updated_at = now()
     where id = v_id;
    n := n + 1;
  end loop;
  return n;
end $$;


ALTER FUNCTION "public"."record_bill_payment"("p_bank_account_id" "uuid", "p_bill_ids" "uuid"[], "p_payment_date" "date", "p_reference" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_check_run"("p_bank_account_id" "uuid", "p_bill_ids" "uuid"[], "p_starting_check_number" integer, "p_payment_date" "date", "p_authorization_confirmed" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  bank_portfolio_id uuid;
  signer_label text;
  result jsonb;
begin
  if not coalesce(p_authorization_confirmed, false) then
    raise exception 'Check signing authorization must be acknowledged';
  end if;

  select portfolio_id, nullif(trim(check_signature), '') into bank_portfolio_id, signer_label
    from public.bank_accounts
   where id = p_bank_account_id
     and archived_at is null;
  if bank_portfolio_id is null or not public.can_manage_finance(bank_portfolio_id) then
    raise exception 'Permission denied';
  end if;
  if not public.can_view_association_row((select association_id from public.bank_accounts where id = p_bank_account_id))
     or exists (select 1 from public.payable_bills b where b.id = any(p_bill_ids) and not public.can_view_association_row(b.association_id)) then
    raise exception 'Permission denied';
  end if;
  if signer_label is null then
    raise exception 'Configure an authorized signer on the bank account before issuing checks';
  end if;

  -- The legacy implementation retains the complete tenant, state, sequence,
  -- and accounting checks. It is no longer executable by client roles.
  result := public.record_check_run_legacy(
    p_bank_account_id,
    p_bill_ids,
    p_starting_check_number,
    p_payment_date
  );

  update public.payable_checks
     set authorized_signer_label = signer_label,
         authorization_acknowledged_at = transaction_timestamp()
   where run_transaction_id = txid_current()
     and issued_by = auth.uid();

  return result;
end;
$$;


ALTER FUNCTION "public"."record_check_run"("p_bank_account_id" "uuid", "p_bill_ids" "uuid"[], "p_starting_check_number" integer, "p_payment_date" "date", "p_authorization_confirmed" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_check_run_legacy"("p_bank_account_id" "uuid", "p_bill_ids" "uuid"[], "p_starting_check_number" integer, "p_payment_date" "date" DEFAULT CURRENT_DATE) RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  bill_id uuid;
  bill_row public.payable_bills;
  bank_row public.bank_accounts;
  ap_account_id uuid;
  payment_entry_id uuid;
  idx integer := 0;
  expected_count integer;
  results jsonb := '[]'::jsonb;
begin
  if p_bank_account_id is null or coalesce(cardinality(p_bill_ids), 0) = 0 then raise exception 'A bank account and at least one bill are required'; end if;
  if p_starting_check_number is null or p_starting_check_number < 1 then raise exception 'Starting check number must be positive'; end if;
  if p_payment_date is null then raise exception 'Payment date is required'; end if;
  select * into bank_row from public.bank_accounts where id = p_bank_account_id and archived_at is null for update;
  if not found then raise exception 'Bank account not found or archived'; end if;
  if not public.can_manage_finance(bank_row.portfolio_id) then raise exception 'Permission denied'; end if;
  if bank_row.gl_account_id is null then raise exception 'Bank account requires a cash GL account'; end if;
  if bank_row.next_check_number is not null and p_starting_check_number <> bank_row.next_check_number then
    raise exception 'Starting check number must match the bank account next check number (%)', bank_row.next_check_number;
  end if;
  select count(distinct id)::integer into expected_count from public.payable_bills where id = any(p_bill_ids);
  if expected_count <> cardinality(p_bill_ids) then raise exception 'Bill selection contains a duplicate or unknown bill'; end if;

  foreach bill_id in array p_bill_ids loop
    select * into bill_row from public.payable_bills where id = bill_id for update;
    if bill_row.portfolio_id is distinct from bank_row.portfolio_id then raise exception 'Bill % is not in the bank account portfolio', bill_id; end if;
    if bank_row.association_id is not null and bill_row.association_id is distinct from bank_row.association_id then raise exception 'Bill % is not in the bank account association', bill_id; end if;
    if bill_row.status <> 'approved'::public.payable_bill_status or bill_row.paid_at is not null or bill_row.check_number is not null then raise exception 'Bill % is not approved and unpaid', bill_id; end if;
    if bill_row.amount - coalesce(bill_row.credit_applied, 0) <= 0 then raise exception 'Bill % has a non-positive amount', bill_id; end if;
    if bill_row.archived_at is not null then raise exception 'Bill % is not approved and unpaid', bill_id; end if;
    if p_payment_date < bill_row.bill_date then
      raise exception 'The check date can''t be before the date of bill %', coalesce(bill_row.bill_number, bill_id::text) using errcode = '22023';
    end if;
    if p_payment_date > coalesce(public.association_local_date(bill_row.association_id, now()), current_date) + 90 then
      raise exception 'The check date for bill % can be at most 90 days ahead', coalesce(bill_row.bill_number, bill_id::text) using errcode = '22023';
    end if;
    if exists (select 1 from public.vendors v where v.id = bill_row.vendor_id and v.hold_payments) then
      raise exception 'Payments to % are on hold. Clear "Hold payments" on the vendor first.',
        coalesce((select v.name from public.vendors v where v.id = bill_row.vendor_id), 'this vendor') using errcode = '22023';
    end if;
    if exists (select 1 from public.journal_entries where source_type = 'check_payment' and source_id = bill_id) then raise exception 'Bill % already has a check-payment ledger entry', bill_id; end if;
    perform public.ensure_payable_bill_accrual(bill_id);
  end loop;
  if exists (select 1 from public.payable_bills where bank_account_id = p_bank_account_id and check_number between p_starting_check_number and p_starting_check_number + cardinality(p_bill_ids) - 1)
     or exists (select 1 from public.payable_checks pc where pc.bank_account_id = p_bank_account_id and pc.check_number between p_starting_check_number and p_starting_check_number + cardinality(p_bill_ids) - 1) then
    raise exception 'Check number already used: one or more of checks #% to #% were already written from this bank account. Choose a different starting check number.',
      p_starting_check_number, p_starting_check_number + cardinality(p_bill_ids) - 1 using errcode = '22023';
  end if;

  foreach bill_id in array p_bill_ids loop
    select * into bill_row from public.payable_bills where id = bill_id;
    select jl.gl_account_id into ap_account_id from public.journal_lines jl join public.journal_entries je on je.id = jl.entry_id
     where je.source_type = 'payable_bill' and je.source_id = bill_id and je.posted and jl.credit_amount > 0
     order by je.created_at desc limit 1;
    ap_account_id := coalesce(ap_account_id, public.app_ap_account(bill_row.portfolio_id, bill_row.association_id));

    insert into public.journal_entries (
      portfolio_id, entry_date, description, memo, reference_number,
      source_type, source_id, created_by, posted, posted_at
    ) values (
      bill_row.portfolio_id, p_payment_date,
      'Check #' || (p_starting_check_number + idx)::text || ': ' || coalesce(bill_row.bill_number, bill_id::text),
      bill_row.memo, (p_starting_check_number + idx)::text,
      'check_payment', bill_id, auth.uid(), true, now()
    ) returning id into payment_entry_id;
    insert into public.journal_lines (entry_id, association_id, gl_account_id, debit_amount, credit_amount, memo, sort_order)
    values
      (payment_entry_id, bill_row.association_id, ap_account_id, bill_row.amount - coalesce(bill_row.credit_applied, 0), 0, bill_row.memo, 1),
      (payment_entry_id, bill_row.association_id, bank_row.gl_account_id, 0, bill_row.amount - coalesce(bill_row.credit_applied, 0), bill_row.memo, 2);

    update public.payable_bills set status = 'paid'::public.payable_bill_status, paid_at = (p_payment_date::timestamp + interval '12 hours') at time zone 'UTC',
      bank_account_id = p_bank_account_id, check_number = p_starting_check_number + idx, updated_at = now() where id = bill_id;
    results := results || jsonb_build_object('bill_id', bill_id, 'check_number', p_starting_check_number + idx, 'journal_entry_id', payment_entry_id);
    idx := idx + 1;
  end loop;
  update public.bank_accounts set next_check_number = p_starting_check_number + idx, updated_at = now() where id = p_bank_account_id;
  return jsonb_build_object('checks_written', idx, 'starting_check_number', p_starting_check_number,
    'next_check_number', p_starting_check_number + idx, 'results', results);
end;
$$;


ALTER FUNCTION "public"."record_check_run_legacy"("p_bank_account_id" "uuid", "p_bill_ids" "uuid"[], "p_starting_check_number" integer, "p_payment_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_credit_card_charge"("p_card_id" "uuid", "p_association_id" "uuid", "p_charge_date" "date", "p_payee" "text", "p_vendor_id" "uuid", "p_gl_account_id" "uuid", "p_amount" numeric, "p_reference" "text", "p_description" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_card public.credit_card_accounts;
  v_assoc uuid;
  v_payee text := nullif(btrim(coalesce(p_payee, '')), '');
  v_amt numeric := round(p_amount, 2);
  v_gl public.gl_accounts;
  v_charge uuid;
  v_entry uuid;
begin
  select * into v_card from public.credit_card_accounts where id = p_card_id and archived_at is null for update;
  if v_card.id is null or not public.can_manage_finance(v_card.portfolio_id) then
    raise exception 'Card account not found' using errcode = '42501';
  end if;
  v_assoc := coalesce(v_card.association_id, p_association_id);
  if v_assoc is null then
    raise exception 'Choose the association this purchase is for' using errcode = '22023';
  end if;
  if v_card.association_id is not null and p_association_id is not null and p_association_id <> v_card.association_id then
    raise exception 'This card belongs to another association' using errcode = '22023';
  end if;
  if not exists (select 1 from public.associations a where a.id = v_assoc and a.portfolio_id = v_card.portfolio_id and a.archived_at is null)
     or not public.can_manage_association(v_assoc) then
    raise exception 'Association not found' using errcode = '42501';
  end if;
  if p_charge_date is null or p_charge_date > current_date + 31 or p_charge_date < date '2000-01-01' then
    raise exception 'Enter a valid charge date' using errcode = '22023';
  end if;
  if v_amt is null or v_amt <= 0 or v_amt > 10000000 then
    raise exception 'Enter an amount greater than zero' using errcode = '22023';
  end if;
  if p_vendor_id is not null then
    select coalesce(v_payee, v.name) into v_payee from public.vendors v where v.id = p_vendor_id and v.portfolio_id = v_card.portfolio_id;
    if not found then raise exception 'Vendor not found' using errcode = '22023'; end if;
  end if;
  if v_payee is null then
    raise exception 'Enter who the card was charged by' using errcode = '22023';
  end if;
  select * into v_gl from public.gl_accounts g
   where g.id = p_gl_account_id and g.portfolio_id = v_card.portfolio_id and coalesce(g.active, true)
     and (g.association_id is null or g.association_id = v_assoc);
  if v_gl.id is null then
    raise exception 'GL account not found' using errcode = '22023';
  end if;
  if not exists (select 1 from public.gl_accounts lg where lg.id = v_card.gl_account_id and coalesce(lg.active, true)
                   and lg.account_type::text in ('liability', 'accounts_payable')) then
    raise exception 'The card''s liability account is inactive or no longer a liability — fix it on the card first' using errcode = '22023';
  end if;
  if v_gl.id = v_card.gl_account_id or v_gl.account_type::text in ('cash', 'accounts_receivable', 'accounts_payable') then
    raise exception 'Choose the expense (or asset) account the purchase is for' using errcode = '22023';
  end if;

  insert into public.credit_card_charges (portfolio_id, card_id, association_id, charge_date, payee, vendor_id, gl_account_id,
                                          amount, reference, description, created_by)
  values (v_card.portfolio_id, v_card.id, v_assoc, p_charge_date, left(v_payee, 200), p_vendor_id, v_gl.id, v_amt,
          nullif(left(btrim(coalesce(p_reference, '')), 100), ''), nullif(left(btrim(coalesce(p_description, '')), 1000), ''), auth.uid())
  returning id into v_charge;

  insert into public.journal_entries (portfolio_id, entry_date, reference_number, description, memo, source_type, source_id, posted, created_by)
  values (v_card.portfolio_id, p_charge_date, nullif(left(btrim(coalesce(p_reference, '')), 100), ''),
          left(v_card.name || ' — ' || v_payee, 250), nullif(left(btrim(coalesce(p_description, '')), 1000), ''),
          'credit_card_charge', v_charge, false, auth.uid())
  returning id into v_entry;
  insert into public.journal_lines (entry_id, gl_account_id, association_id, debit_amount, credit_amount, memo, sort_order)
  values (v_entry, v_gl.id, v_assoc, v_amt, 0, left(v_payee, 200), 0),
         (v_entry, v_card.gl_account_id, v_assoc, 0, v_amt, left(v_card.name || ' — ' || v_payee, 250), 1);
  update public.journal_entries set posted = true, posted_at = now() where id = v_entry;
  update public.credit_card_charges set journal_entry_id = v_entry where id = v_charge;
  return v_charge;
end $$;


ALTER FUNCTION "public"."record_credit_card_charge"("p_card_id" "uuid", "p_association_id" "uuid", "p_charge_date" "date", "p_payee" "text", "p_vendor_id" "uuid", "p_gl_account_id" "uuid", "p_amount" numeric, "p_reference" "text", "p_description" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_delinquency_board_referral_vote"("p_case_id" "uuid", "p_meeting_date" "date", "p_votes_for" integer, "p_votes_against" integer, "p_note" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare c public.delinquency_cases; v_approved boolean;
begin
  select * into c from public.delinquency_cases where id = p_case_id for update;
  if not found then raise exception 'Delinquency case not found'; end if;
  if not public.can_view_association_row(c.association_id) then raise exception 'Delinquency case not found'; end if;
  if not (public.can_access_portfolio(c.portfolio_id) and (public.is_any_staff() or public.is_company_admin() or public.is_platform_operator())) then
    raise exception 'Not authorized to manage this delinquency case';
  end if;
  if p_meeting_date is null or p_meeting_date > public.association_local_date(c.association_id) then raise exception 'Meeting date must be today or earlier'; end if;
  if p_votes_for is null or p_votes_against is null or p_votes_for < 0 or p_votes_against < 0 or p_votes_for + p_votes_against = 0 then raise exception 'Enter the recorded vote count'; end if;
  if char_length(btrim(coalesce(p_note, ''))) < 10 then raise exception 'Reference the minutes or motion (10+ characters)'; end if;
  v_approved := p_votes_for > p_votes_against;
  insert into public.delinquency_case_events (case_id, event_type, step_number, balance_snapshot, note, metadata)
  values (p_case_id, case when v_approved then 'board_referral_approved' else 'board_referral_denied' end, c.current_step_number, c.balance_snapshot, left(btrim(p_note), 2000),
          jsonb_build_object('meeting_date', p_meeting_date, 'votes_for', p_votes_for, 'votes_against', p_votes_against));
  if not v_approved and c.status in ('open', 'legal_review') then
    update public.delinquency_cases set status = 'on_hold', hold_reason = 'Board declined referral: ' || left(btrim(p_note), 400) where id = p_case_id;
  end if;
  return case when v_approved then 'approved' else 'denied' end;
end;
$$;


ALTER FUNCTION "public"."record_delinquency_board_referral_vote"("p_case_id" "uuid", "p_meeting_date" "date", "p_votes_for" integer, "p_votes_against" integer, "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_delinquency_payment_plan_offer"("p_case_id" "uuid", "p_offered_on" "date", "p_months" integer, "p_terms" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare c public.delinquency_cases;
begin
  select * into c from public.delinquency_cases where id = p_case_id for update;
  if not found then raise exception 'Delinquency case not found'; end if;
  if not (public.can_access_portfolio(c.portfolio_id) and (public.is_any_staff() or public.is_company_admin() or public.is_platform_operator())
          and public.can_view_association_row(c.association_id)) then
    raise exception 'Not authorized to manage this delinquency case';
  end if;
  if p_offered_on is null or p_offered_on > public.association_local_date(c.association_id) then raise exception 'Offer date must be today or earlier'; end if;
  if p_months is null or p_months not between 1 and 60 then raise exception 'Plan length must be 1–60 months'; end if;
  if char_length(btrim(coalesce(p_terms, ''))) < 10 then raise exception 'Describe the offered terms (10+ characters)'; end if;
  insert into public.delinquency_case_events (case_id, event_type, step_number, balance_snapshot, note, metadata)
  values (p_case_id, 'payment_plan_offered', c.current_step_number, c.balance_snapshot, left(btrim(p_terms), 2000), jsonb_build_object('offered_on', p_offered_on, 'months', p_months));
end;
$$;


ALTER FUNCTION "public"."record_delinquency_payment_plan_offer"("p_case_id" "uuid", "p_offered_on" "date", "p_months" integer, "p_terms" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_email_event"("p_provider_message_id" "text", "p_event_type" "text", "p_occurred_at" timestamp with time zone, "p_provider_event_id" "text" DEFAULT NULL::"text", "p_detail" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_email uuid; v_at timestamptz := coalesce(p_occurred_at, now()); v_inserted int;
begin
  select id into v_email from public.email_queue where provider_message_id = p_provider_message_id limit 1;
  if v_email is null then return false; end if;
  insert into public.email_events (email_id, provider_event_id, event_type, occurred_at, detail)
  values (v_email, nullif(p_provider_event_id, ''), p_event_type, v_at, left(p_detail, 500))
  on conflict (provider_event_id) do nothing;
  get diagnostics v_inserted = row_count;
  if v_inserted = 0 then return true; end if;
  update public.email_queue set
    delivered_at = case when p_event_type = 'delivered' then coalesce(delivered_at, v_at) else delivered_at end,
    first_opened_at = case when p_event_type = 'opened' then least(coalesce(first_opened_at, v_at), v_at) else first_opened_at end,
    last_opened_at = case when p_event_type = 'opened' then greatest(coalesce(last_opened_at, v_at), v_at) else last_opened_at end,
    open_count = open_count + case when p_event_type = 'opened' then 1 else 0 end,
    clicked_at = case when p_event_type = 'clicked' then coalesce(clicked_at, v_at) else clicked_at end,
    bounced_at = case when p_event_type = 'bounced' then coalesce(bounced_at, v_at) else bounced_at end,
    complained_at = case when p_event_type = 'complained' then coalesce(complained_at, v_at) else complained_at end,
    delivery_status = case
      when p_event_type in ('bounced', 'complained', 'failed') then p_event_type
      when delivery_status in ('bounced', 'complained', 'failed') then delivery_status
      when p_event_type in ('opened', 'clicked') then 'opened'
      when p_event_type = 'delivered' and coalesce(delivery_status, '') <> 'opened' then 'delivered'
      when p_event_type = 'delivery_delayed' and delivery_status is null then 'delayed'
      else delivery_status end
  where id = v_email;
  return true;
end $$;


ALTER FUNCTION "public"."record_email_event"("p_provider_message_id" "text", "p_event_type" "text", "p_occurred_at" timestamp with time zone, "p_provider_event_id" "text", "p_detail" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_inventory_movement"("p_item_id" "uuid", "p_kind" "text", "p_quantity" numeric, "p_direction" "text", "p_work_order_id" "uuid", "p_unit_cost" numeric, "p_note" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  it public.inventory_items;
  wo record;
  v_assoc uuid;
  v_change numeric;
  v_after numeric;
  v_id uuid;
begin
  -- Changed: company admins record inventory too.
  if not (public.is_any_staff() or public.is_company_admin()) then
    raise exception 'Only company staff can record inventory' using errcode = '42501';
  end if;
  select * into it from public.inventory_items where id = p_item_id and archived_at is null for update;
  if it.id is null or it.portfolio_id is distinct from public.current_portfolio_id() then
    raise exception 'Inventory item not found' using errcode = '42501';
  end if;
  p_quantity := round(p_quantity, 2);
  if p_quantity is null or p_quantity <= 0 then
    raise exception 'Enter a quantity greater than zero' using errcode = '22023';
  end if;
  if p_kind = 'received' then
    v_change := p_quantity;
  elsif p_kind = 'used' then
    v_change := -p_quantity;
  elsif p_kind = 'adjusted' then
    if p_direction not in ('add', 'remove') then
      raise exception 'Choose whether the adjustment adds or removes stock' using errcode = '22023';
    end if;
    v_change := case when p_direction = 'add' then p_quantity else -p_quantity end;
  else
    raise exception 'Unknown inventory movement' using errcode = '22023';
  end if;

  if p_work_order_id is not null then
    if p_kind <> 'used' then
      raise exception 'Only stock used can be tied to a work order' using errcode = '22023';
    end if;
    select w.id, w.association_id, w.portfolio_id into wo from public.work_orders w where w.id = p_work_order_id;
    if wo.id is null or wo.portfolio_id is distinct from it.portfolio_id
       or (wo.association_id is not null and not public.can_manage_association(wo.association_id)) then
      raise exception 'Work order not found' using errcode = '42501';
    end if;
    v_assoc := wo.association_id;
  end if;

  v_after := coalesce(it.quantity_on_hand, 0) + v_change;
  if v_after < 0 then
    -- (Same message; the dash is written as chr(8212) so applying it keeps it.)
    raise exception using errcode = '22023',
      message = format('Only %s on hand %s you cannot use or remove more than that', coalesce(it.quantity_on_hand, 0), chr(8212));
  end if;

  perform set_config('app.inventory_movement', 'on', true);
  update public.inventory_items
     set quantity_on_hand = v_after,
         unit_cost = case when p_kind = 'received' and p_unit_cost is not null and p_unit_cost >= 0 then p_unit_cost else unit_cost end
   where id = it.id;
  perform set_config('app.inventory_movement', 'off', true);

  insert into public.inventory_movements (portfolio_id, item_id, kind, quantity_change, quantity_after, unit_cost,
                                          work_order_id, association_id, note, created_by)
  values (it.portfolio_id, it.id, p_kind, v_change, v_after,
          case when p_kind = 'received' and p_unit_cost is not null and p_unit_cost >= 0 then p_unit_cost else it.unit_cost end,
          p_work_order_id, v_assoc, nullif(btrim(coalesce(p_note, '')), ''), auth.uid())
  returning id into v_id;
  return v_id;
end $$;


ALTER FUNCTION "public"."record_inventory_movement"("p_item_id" "uuid", "p_kind" "text", "p_quantity" numeric, "p_direction" "text", "p_work_order_id" "uuid", "p_unit_cost" numeric, "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_label"("p_entity_type" "text", "p_entity_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$#variable_conflict use_column
begin
  return (select s.x from (

  select case p_entity_type
    when 'association' then (select a.name from public.associations a where a.id = p_entity_id)
    when 'unit' then (select 'Unit ' || u.unit_number || coalesce(' · ' || a.name, '') from public.units u
                        join public.buildings b on b.id = u.building_id
                        join public.associations a on a.id = b.association_id
                       where u.id = p_entity_id)
    when 'owner' then (select o.full_name from public.owners o where o.id = p_entity_id)
    when 'vendor' then (select v.name from public.vendors v where v.id = p_entity_id)
  end
  ) s(x) limit 1);
end$$;


ALTER FUNCTION "public"."record_label"("p_entity_type" "text", "p_entity_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_loan_payment"("p_loan_id" "uuid", "p_payment_date" "date", "p_amount" numeric, "p_interest" numeric, "p_bank_account_id" "uuid", "p_reference" "text", "p_memo" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  l public.association_loans;
  v_bank public.bank_accounts;
  v_amount numeric(14,2) := round(p_amount, 2);
  v_interest numeric(14,2);
  v_principal numeric(14,2);
  v_months integer;
  v_payment uuid;
  v_entry uuid;
  v_label text;
begin
  if auth.uid() is null then
    raise exception 'Sign in to record loan payments' using errcode = '42501';
  end if;
  select * into l from public.association_loans where id = p_loan_id and archived_at is null for update;
  if l.id is null then
    raise exception 'Loan not found';
  end if;
  if not ((public.can_manage_finance(l.portfolio_id) and public.can_manage_association(l.association_id)) or public.is_platform_operator()) then
    raise exception 'You do not have accounting access to this association' using errcode = '42501';
  end if;
  if l.gl_account_id is null or l.interest_gl_account_id is null then
    raise exception 'Set the loan''s liability and interest expense GL accounts first' using errcode = '22023';
  end if;
  if not exists (select 1 from public.gl_accounts g where g.id = l.gl_account_id and coalesce(g.active, true) and g.portfolio_id = l.portfolio_id and (g.association_id is null or g.association_id = l.association_id) and g.account_type::text = 'liability')
     or not exists (select 1 from public.gl_accounts g where g.id = l.interest_gl_account_id and coalesce(g.active, true) and g.portfolio_id = l.portfolio_id and (g.association_id is null or g.association_id = l.association_id) and g.account_type::text in ('expense', 'other_expense')) then
    raise exception 'The loan''s liability or interest account is inactive or the wrong type — fix the loan setup first' using errcode = '22023';
  end if;
  if coalesce(l.status, 'active') <> 'active' then
    raise exception 'Payments can only be recorded on active loans (this one is %)', replace(l.status, '_', ' ') using errcode = '22023';
  end if;
  if coalesce(l.current_balance, 0) <= 0 then
    raise exception 'This loan has no balance left' using errcode = '22023';
  end if;
  if p_payment_date is null or p_payment_date > current_date + 31 or p_payment_date < date '2000-01-01' then
    raise exception 'Enter a valid payment date' using errcode = '22023';
  end if;
  if v_amount is null or v_amount <= 0 then
    raise exception 'Payment amount must be greater than zero' using errcode = '22023';
  end if;

  select * into v_bank from public.bank_accounts
   where id = coalesce(p_bank_account_id, l.bank_account_id) and archived_at is null
     and portfolio_id = l.portfolio_id and (association_id is null or association_id = l.association_id);
  if v_bank.id is null then
    raise exception 'Choose a bank account that belongs to this association' using errcode = '22023';
  end if;
  if v_bank.gl_account_id is null then
    raise exception 'Bank account "%" has no linked GL account', v_bank.name using errcode = '22023';
  end if;
  if not exists (select 1 from public.gl_accounts g where g.id = v_bank.gl_account_id and g.portfolio_id = l.portfolio_id
                   and (g.association_id is null or g.association_id = l.association_id)
                   and g.account_type::text = 'cash' and coalesce(g.active, true)) then
    raise exception 'Bank account "%" is linked to a GL account that is inactive, not a cash account, or belongs to another association', v_bank.name using errcode = '22023';
  end if;

  v_interest := coalesce(round(p_interest, 2),
                         round(l.current_balance * coalesce(l.interest_rate, 0) / 100 / public.loan_periods_per_year(l.payment_frequency), 2));
  if v_interest < 0 or v_interest > v_amount then
    raise exception 'Interest must be between $0 and the payment amount' using errcode = '22023';
  end if;
  v_principal := v_amount - v_interest;
  if v_principal > l.current_balance then
    raise exception 'Principal ($%) would exceed the remaining balance ($%) — lower the payment or record the payoff amount',
      to_char(v_principal, 'FM999,999,990.00'), to_char(l.current_balance, 'FM999,999,990.00') using errcode = '22023';
  end if;

  v_label := 'Loan payment — ' || left(l.lender, 120);
  insert into public.loan_payments (loan_id, portfolio_id, association_id, payment_date, amount, principal, interest, balance_after,
                                    previous_next_payment_date, bank_account_id, reference, memo, created_by)
  values (l.id, l.portfolio_id, l.association_id, p_payment_date, v_amount, v_principal, v_interest, l.current_balance - v_principal,
          l.next_payment_date, v_bank.id, nullif(left(btrim(coalesce(p_reference, '')), 100), ''), nullif(left(btrim(coalesce(p_memo, '')), 1000), ''), auth.uid())
  returning id into v_payment;

  insert into public.journal_entries (portfolio_id, entry_date, reference_number, description, memo, source_type, source_id, posted, created_by)
  values (l.portfolio_id, p_payment_date, nullif(left(btrim(coalesce(p_reference, '')), 100), ''), v_label,
          nullif(left(btrim(coalesce(p_memo, '')), 1000), ''), 'loan_payment', v_payment, false, auth.uid())
  returning id into v_entry;
  if v_principal > 0 then
    insert into public.journal_lines (entry_id, gl_account_id, association_id, debit_amount, credit_amount, memo, sort_order)
    values (v_entry, l.gl_account_id, l.association_id, v_principal, 0, v_label || ' (principal)', 0);
  end if;
  if v_interest > 0 then
    insert into public.journal_lines (entry_id, gl_account_id, association_id, debit_amount, credit_amount, memo, sort_order)
    values (v_entry, l.interest_gl_account_id, l.association_id, v_interest, 0, v_label || ' (interest)', 1);
  end if;
  insert into public.journal_lines (entry_id, gl_account_id, association_id, debit_amount, credit_amount, memo, sort_order)
  values (v_entry, v_bank.gl_account_id, l.association_id, 0, v_amount, v_label, 2);
  update public.journal_entries set posted = true, posted_at = now() where id = v_entry;
  update public.loan_payments set journal_entry_id = v_entry where id = v_payment;

  v_months := 12 / public.loan_periods_per_year(l.payment_frequency);
  perform set_config('app.loan_ledger', 'on', true);
  update public.association_loans
     set current_balance = current_balance - v_principal,
         next_payment_date = case when current_balance - v_principal <= 0 then null
                                  when next_payment_date is null then null
                                  else (next_payment_date + make_interval(months => v_months))::date end,
         status = case when current_balance - v_principal <= 0 then 'paid_off' else coalesce(status, 'active') end,
         updated_at = now()
   where id = l.id;
  perform set_config('app.loan_ledger', '', true);
  update public.loan_payments set next_payment_date_after = (select a.next_payment_date from public.association_loans a where a.id = l.id) where id = v_payment;
  return v_payment;
end $_$;


ALTER FUNCTION "public"."record_loan_payment"("p_loan_id" "uuid", "p_payment_date" "date", "p_amount" numeric, "p_interest" numeric, "p_bank_account_id" "uuid", "p_reference" "text", "p_memo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_login_attempt"("p_email" "text", "p_auth_user_id" "uuid", "p_success" boolean, "p_ip_address" "text" DEFAULT NULL::"text", "p_user_agent" "text" DEFAULT NULL::"text", "p_failure_reason" "text" DEFAULT NULL::"text", "p_mfa_used" boolean DEFAULT false) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  attempt_id uuid;
  user_portfolio uuid;
begin
  select portfolio_id into user_portfolio from public.profiles where id = p_auth_user_id;

  select la.id
    into attempt_id
    from public.login_attempts la
   where la.at >= now() - interval '30 seconds'
     and la.ip_address is null
     and la.success = p_success
     and (
       (p_auth_user_id is not null and la.auth_user_id = p_auth_user_id)
       or
       (p_auth_user_id is null and lower(la.email) = lower(p_email))
     )
   order by la.at desc
   limit 1
   for update skip locked;

  if attempt_id is not null then
    update public.login_attempts
       set ip_address = p_ip_address,
           user_agent = p_user_agent,
           failure_reason = coalesce(p_failure_reason, failure_reason),
           mfa_used = p_mfa_used
     where id = attempt_id;
  else
    insert into public.login_attempts (
      email, auth_user_id, portfolio_id, ip_address, user_agent,
      success, failure_reason, mfa_used
    ) values (
      lower(p_email), p_auth_user_id, user_portfolio, p_ip_address, p_user_agent,
      p_success, p_failure_reason, p_mfa_used
    ) returning id into attempt_id;
  end if;

  if p_success and p_auth_user_id is not null then
    update public.profiles
       set last_login_at = now(), last_login_ip = p_ip_address, updated_at = now()
     where id = p_auth_user_id;
    update public.owners
       set portal_login_last_at = now()
     where auth_user_id = p_auth_user_id
       and archived_at is null;
  end if;

  return attempt_id;
end;
$$;


ALTER FUNCTION "public"."record_login_attempt"("p_email" "text", "p_auth_user_id" "uuid", "p_success" boolean, "p_ip_address" "text", "p_user_agent" "text", "p_failure_reason" "text", "p_mfa_used" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."record_login_attempt"("p_email" "text", "p_auth_user_id" "uuid", "p_success" boolean, "p_ip_address" "text", "p_user_agent" "text", "p_failure_reason" "text", "p_mfa_used" boolean) IS 'Call from an Auth hook edge function on every sign-in attempt. Logs to login_attempts and updates profiles.last_login_* on success.';



CREATE OR REPLACE FUNCTION "public"."record_manual_certified_mail_delivery"("p_id" "uuid", "p_tracking_number" "text", "p_delivered_on" "date", "p_note" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  mail public.physical_mail_deliveries%rowtype;
  tracking text := upper(regexp_replace(btrim(coalesce(p_tracking_number, '')), '\s+', '', 'g'));
  evidence_note text := btrim(coalesce(p_note, ''));
begin
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;

  select * into mail
  from public.physical_mail_deliveries
  where id = p_id
  for update;

  if mail.id is null then
    raise exception 'Physical-mail record not found';
  end if;
  if not (public.can_admin_portfolio(mail.portfolio_id) or public.is_platform_operator()) then
    raise exception 'Portfolio administrator access required';
  end if;
  if mail.delinquency_case_id is null then
    raise exception 'Manual delivery evidence is limited to a delinquency case';
  end if;
  if mail.status = 'delivered' then
    raise exception 'Delivery is already confirmed';
  end if;
  if tracking !~ '^[A-Z0-9-]{8,40}$' then
    raise exception 'Enter a valid certified-mail tracking number';
  end if;
  if p_delivered_on is null or p_delivered_on > current_date then
    raise exception 'Delivery date must be today or earlier';
  end if;
  if char_length(evidence_note) < 20 then
    raise exception 'Delivery evidence note must be at least 20 characters';
  end if;

  update public.physical_mail_deliveries
  set status = 'delivered',
      provider = 'manual_usps',
      provider_piece_id = tracking,
      provider_url = null,
      expected_delivery_date = p_delivered_on,
      delivered_at = p_delivered_on::timestamp at time zone 'UTC',
      delivery_verified_by = auth.uid(),
      delivery_verified_at = now(),
      manual_delivery_note = left(evidence_note, 2000),
      last_status_at = now(),
      locked_at = null,
      error_message = null
  where id = p_id;

  insert into public.audit_logs (entity_type, entity_id, action, actor_id, changes)
  values (
    'physical_mail_delivery',
    p_id,
    'manual_certified_mail_delivery_recorded',
    auth.uid(),
    jsonb_build_object(
      'portfolio_id', mail.portfolio_id,
      'association_id', mail.association_id,
      'delinquency_case_id', mail.delinquency_case_id,
      'tracking_number', tracking,
      'delivered_on', p_delivered_on,
      'note', left(evidence_note, 2000)
    )
  );

  return jsonb_build_object('success', true, 'status', 'delivered');
end;
$_$;


ALTER FUNCTION "public"."record_manual_certified_mail_delivery"("p_id" "uuid", "p_tracking_number" "text", "p_delivered_on" "date", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_meeting_attendance"("p_meeting_id" "uuid", "p_attendee_name" "text", "p_owner_id" "uuid" DEFAULT NULL::"uuid", "p_attendee_role" "text" DEFAULT 'owner'::"text", "p_signature_data" "text" DEFAULT NULL::"text", "p_voting_eligible" boolean DEFAULT true, "p_notes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if not public.meeting_tenant_scope_valid(p_meeting_id)
     or not public.can_access_meeting(p_meeting_id) then
    raise exception 'Meeting not found or access denied' using errcode = '42501';
  end if;
  return public.record_meeting_attendance_tenant_checked_impl(
    p_meeting_id,
    p_attendee_name,
    p_owner_id,
    p_attendee_role,
    p_signature_data,
    p_voting_eligible,
    p_notes
  );
end;
$$;


ALTER FUNCTION "public"."record_meeting_attendance"("p_meeting_id" "uuid", "p_attendee_name" "text", "p_owner_id" "uuid", "p_attendee_role" "text", "p_signature_data" "text", "p_voting_eligible" boolean, "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_meeting_attendance_tenant_checked_impl"("p_meeting_id" "uuid", "p_attendee_name" "text", "p_owner_id" "uuid" DEFAULT NULL::"uuid", "p_attendee_role" "text" DEFAULT 'owner'::"text", "p_signature_data" "text" DEFAULT NULL::"text", "p_voting_eligible" boolean DEFAULT true, "p_notes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_meeting public.meetings%rowtype;
  v_attendee_id uuid;
  v_is_staff boolean;
  v_is_board boolean;
  v_is_resident boolean;
  v_current_owner_id uuid;
  v_effective_owner_id uuid;
  v_effective_name text;
  v_effective_role text;
  v_effective_voting boolean;
begin
  if auth.uid() is null or p_meeting_id is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  if length(coalesce(p_attendee_name, '')) > 200
     or length(coalesce(p_notes, '')) > 2000
     or octet_length(coalesce(p_signature_data, '')) > 1048576
     or p_attendee_role is null
     or p_attendee_role not in ('board_member', 'owner', 'manager', 'guest') then
    raise exception 'Invalid meeting attendance input' using errcode = '22023';
  end if;

  select * into v_meeting
  from public.meetings m
  where m.id = p_meeting_id;
  if not found then
    raise exception 'Meeting not found' using errcode = 'P0002';
  end if;

  v_is_staff := public.is_platform_operator()
    or (
      (public.is_any_staff() or public.is_company_admin())
      and public.can_access_portfolio(v_meeting.portfolio_id)
    );
  v_is_board := public.is_board_user()
    and v_meeting.association_id in (select public.current_board_association_ids());
  v_is_resident := public.is_portal_resident()
    and v_meeting.association_id in (select public.current_resident_association_ids());

  if not (v_is_staff or v_is_resident) then
    raise exception 'Not authorized for this meeting' using errcode = '42501';
  end if;

  if v_is_staff then
    v_effective_owner_id := p_owner_id;
    v_effective_name := trim(p_attendee_name);
    v_effective_role := p_attendee_role;
    v_effective_voting := coalesce(p_voting_eligible, false);

    if length(v_effective_name) not between 1 and 200 then
      raise exception 'Attendee name is required' using errcode = '22023';
    end if;
    if v_effective_owner_id is not null
       and not exists (
         select 1
         from public.occupancies o
         where o.owner_id = v_effective_owner_id
           and o.association_id = v_meeting.association_id
           and o.status = 'current'
       ) then
      raise exception 'Owner is outside the meeting association' using errcode = '23514';
    end if;
  else
    select o.owner_id into v_current_owner_id
      from public.occupancies o
     where o.owner_id in (select public.current_owner_ids())
       and o.association_id = v_meeting.association_id
       and o.status = 'current'
     order by o.created_at, o.id
     limit 1;

    if v_current_owner_id is not null then
      if p_owner_id is not null and p_owner_id <> v_current_owner_id then
        raise exception 'Residents may only sign in themselves' using errcode = '42501';
      end if;
      select o.id, o.full_name
      into v_effective_owner_id, v_effective_name
      from public.owners o
      where o.id = v_current_owner_id;
      v_effective_role := case when v_is_board then 'board_member' else 'owner' end;
      v_effective_voting := true;
    elsif v_is_board then
      if p_owner_id is not null then
        raise exception 'Board user owner identity does not match' using errcode = '42501';
      end if;
      select coalesce(nullif(trim(p.full_name), ''), nullif(trim(p.email), ''), 'Board member')
      into v_effective_name
      from public.profiles p
      where p.id = auth.uid();
      v_effective_owner_id := null;
      v_effective_role := 'board_member';
      v_effective_voting := true;
    else
      raise exception 'Current owner record is required' using errcode = '42501';
    end if;
  end if;

  if v_effective_owner_id is not null then
    select ma.id into v_attendee_id
    from public.meeting_attendees ma
    where ma.meeting_id = p_meeting_id
      and ma.owner_id = v_effective_owner_id
    order by ma.created_at
    limit 1
    for update;
  end if;

  if v_attendee_id is not null then
    update public.meeting_attendees ma
    set signature_data = coalesce(p_signature_data, ma.signature_data),
        present = true,
        attendee_name = v_effective_name,
        attendee_role = v_effective_role,
        voting_eligible = v_effective_voting,
        notes = coalesce(nullif(trim(p_notes), ''), ma.notes),
        check_in_time = pg_catalog.now()
    where ma.id = v_attendee_id;
  else
    insert into public.meeting_attendees (
      meeting_id, owner_id, attendee_name, attendee_role,
      check_in_time, signature_data, present, voting_eligible, notes
    ) values (
      p_meeting_id, v_effective_owner_id, v_effective_name, v_effective_role,
      pg_catalog.now(), p_signature_data, true, v_effective_voting, nullif(trim(p_notes), '')
    )
    returning meeting_attendees.id into v_attendee_id;
  end if;

  perform public.calculate_meeting_quorum(p_meeting_id);
  return v_attendee_id;
end;
$$;


ALTER FUNCTION "public"."record_meeting_attendance_tenant_checked_impl"("p_meeting_id" "uuid", "p_attendee_name" "text", "p_owner_id" "uuid", "p_attendee_role" "text", "p_signature_data" "text", "p_voting_eligible" boolean, "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_other_receipt"("p_association_id" "uuid", "p_bank_account_id" "uuid", "p_receipt_date" "date", "p_payer_type" "text", "p_vendor_id" "uuid", "p_payer_name" "text", "p_reference" "text", "p_memo" "text", "p_lines" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_portfolio uuid;
  v_bank public.bank_accounts;
  v_vendor public.vendors;
  v_payer text := nullif(btrim(coalesce(p_payer_name, '')), '');
  v_total numeric(12,2) := 0;
  v_line jsonb;
  v_gl public.gl_accounts;
  v_amt numeric;
  v_receipt uuid;
  v_entry uuid;
  v_i integer := 0;
begin
  if auth.uid() is null then
    raise exception 'Sign in to record receipts' using errcode = '42501';
  end if;
  select portfolio_id into v_portfolio from public.associations where id = p_association_id and archived_at is null;
  if v_portfolio is null then
    raise exception 'Association not found';
  end if;
  if not ((public.can_manage_finance(v_portfolio) and public.can_manage_association(p_association_id))
          or public.is_platform_operator()) then
    raise exception 'You do not have accounting access to this association' using errcode = '42501';
  end if;
  if p_receipt_date is null or p_receipt_date > current_date + 31 or p_receipt_date < date '2000-01-01' then
    raise exception 'Enter a valid receipt date';
  end if;

  select * into v_bank from public.bank_accounts where id = p_bank_account_id and archived_at is null;
  if v_bank.id is null or v_bank.portfolio_id <> v_portfolio
     or (v_bank.association_id is not null and v_bank.association_id <> p_association_id) then
    raise exception 'That bank account does not belong to this association';
  end if;
  if v_bank.gl_account_id is null then
    raise exception 'Bank account "%" has no linked GL account. Link one on the bank account first.', v_bank.name;
  end if;

  if p_payer_type not in ('vendor', 'other') then
    raise exception 'Choose who the money came from';
  end if;
  if p_payer_type = 'vendor' then
    select * into v_vendor from public.vendors where id = p_vendor_id and portfolio_id = v_portfolio;
    if v_vendor.id is null then
      raise exception 'Vendor not found';
    end if;
    v_payer := coalesce(v_payer, v_vendor.name);
  elsif p_vendor_id is not null then
    raise exception 'Only vendor receipts can name a vendor';
  end if;
  if v_payer is null then
    raise exception 'Enter who the money came from';
  end if;

  if jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then
    raise exception 'Add at least one line';
  end if;
  if jsonb_array_length(p_lines) > 20 then
    raise exception 'A receipt can have at most 20 lines';
  end if;

  insert into public.other_receipts (portfolio_id, association_id, bank_account_id, receipt_date, payer_type, vendor_id,
                                     payer_name, reference, memo, amount, created_by)
  values (v_portfolio, p_association_id, v_bank.id, p_receipt_date, p_payer_type,
          case when p_payer_type = 'vendor' then v_vendor.id end, left(v_payer, 200),
          nullif(left(btrim(coalesce(p_reference, '')), 100), ''), nullif(left(btrim(coalesce(p_memo, '')), 1000), ''),
          0.01, auth.uid())
  returning id into v_receipt;

  for v_line in select * from jsonb_array_elements(p_lines) loop
    v_i := v_i + 1;
    begin
      v_amt := round((v_line ->> 'amount')::numeric, 2);
    exception when others then
      raise exception 'Line %: enter a valid amount', v_i;
    end;
    if v_amt is null or v_amt <= 0 or v_amt > 10000000 then
      raise exception 'Line %: amount must be greater than zero', v_i;
    end if;
    select * into v_gl from public.gl_accounts
     where id = nullif(v_line ->> 'gl_account_id', '')::uuid and portfolio_id = v_portfolio and coalesce(active, true)
       and (association_id is null or association_id = p_association_id);
    if v_gl.id is null then
      raise exception 'Line %: GL account not found', v_i;
    end if;
    if v_gl.id = v_bank.gl_account_id or v_gl.account_type::text in ('cash', 'accounts_receivable') then
      raise exception 'Line %: % can''t be credited here — homeowner payments are recorded as homeowner receipts and bank moves as transfers', v_i, v_gl.name;
    end if;
    insert into public.other_receipt_lines (receipt_id, gl_account_id, amount, memo, sort_order)
    values (v_receipt, v_gl.id, v_amt, nullif(left(btrim(coalesce(v_line ->> 'memo', '')), 300), ''), v_i);
    v_total := v_total + v_amt;
  end loop;

  update public.other_receipts set amount = v_total where id = v_receipt;

  insert into public.journal_entries (portfolio_id, entry_date, reference_number, description, memo, source_type, source_id, posted, created_by)
  values (v_portfolio, p_receipt_date, nullif(left(btrim(coalesce(p_reference, '')), 100), ''),
          'Receipt from ' || left(v_payer, 150), nullif(left(btrim(coalesce(p_memo, '')), 1000), ''),
          'other_receipt', v_receipt, false, auth.uid())
  returning id into v_entry;

  insert into public.journal_lines (entry_id, gl_account_id, association_id, debit_amount, credit_amount, memo, sort_order)
  values (v_entry, v_bank.gl_account_id, p_association_id, v_total, 0, 'Receipt from ' || left(v_payer, 150), 0);
  insert into public.journal_lines (entry_id, gl_account_id, association_id, debit_amount, credit_amount, memo, sort_order)
  select v_entry, l.gl_account_id, p_association_id, 0, l.amount, coalesce(l.memo, 'Receipt from ' || left(v_payer, 150)), l.sort_order
    from public.other_receipt_lines l where l.receipt_id = v_receipt;

  update public.journal_entries set posted = true, posted_at = now() where id = v_entry;
  update public.other_receipts set journal_entry_id = v_entry where id = v_receipt;
  return v_receipt;
end $$;


ALTER FUNCTION "public"."record_other_receipt"("p_association_id" "uuid", "p_bank_account_id" "uuid", "p_receipt_date" "date", "p_payer_type" "text", "p_vendor_id" "uuid", "p_payer_name" "text", "p_reference" "text", "p_memo" "text", "p_lines" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_portfolio_id"("p_entity_type" "text", "p_entity_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$#variable_conflict use_column
begin
  return (select s.x from (

  select case p_entity_type
    when 'association' then (select a.portfolio_id from public.associations a where a.id = p_entity_id)
    when 'unit' then (select a.portfolio_id from public.units u
                        join public.buildings b on b.id = u.building_id
                        join public.associations a on a.id = b.association_id
                       where u.id = p_entity_id)
    when 'owner' then (select o.portfolio_id from public.owners o where o.id = p_entity_id)
    when 'vendor' then (select v.portfolio_id from public.vendors v where v.id = p_entity_id)
  end
  ) s(x) limit 1);
end$$;


ALTER FUNCTION "public"."record_portfolio_id"("p_entity_type" "text", "p_entity_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_violation_hearing"("p_violation_id" "uuid", "p_decision" "text", "p_hearing_at" timestamp with time zone, "p_notes" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare v public.violations; v_today date;
begin
  select * into v from public.violations where id = p_violation_id for update;
  if not found or not public.can_manage_violations(v.association_id) then raise exception 'Permission denied' using errcode = '42501'; end if;
  if p_decision not in ('upheld', 'dismissed') then raise exception 'Decision must be upheld or dismissed' using errcode = '22023'; end if;
  if v.status in ('cured', 'closed') then raise exception 'This violation is already resolved' using errcode = '22023'; end if;
  v_today := public.association_local_date(v.association_id, now());
  update public.violations
     set board_decision = p_decision, hearing_at = coalesce(p_hearing_at, now()), hearing_required = true,
         status = case when p_decision = 'dismissed' then 'closed'::public.violation_status when status = 'hearing_pending' then (case when coalesce(fines_total, 0) > 0 then 'fined' else 'notice_sent' end)::public.violation_status else status end,
         closed_at = case when p_decision = 'dismissed' then now() else closed_at end,
         next_followup_on = case when p_decision = 'dismissed' then null when next_followup_on is null or next_followup_on < v_today then v_today else next_followup_on end
   where id = v.id;
  -- The owner sees the decision and the board's notes ...
  perform public.log_violation_event(v.id, 'Hearing held — violation ' || p_decision
      || case when nullif(btrim(coalesce(p_notes, '')), '') is not null then '. ' || btrim(p_notes) else '' end,
    case when p_decision = 'dismissed' then 'closed'::public.violation_status else null end, true);
  -- ... and the reminder to credit fines stays with staff.
  if p_decision = 'dismissed' and coalesce(v.fines_total, 0) > 0 then
    perform public.log_violation_event(v.id, 'Fines already posted ($' || to_char(v.fines_total, 'FM999,999,990.00')
        || ') remain on the owner ledger: credit them if the dismissal reverses them.', null, false);
  end if;
end;
$_$;


ALTER FUNCTION "public"."record_violation_hearing"("p_violation_id" "uuid", "p_decision" "text", "p_hearing_at" timestamp with time zone, "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recount_seats_used"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  affected uuid;
begin
  -- Recount for both the old and new portfolio when relevant
  for affected in
    select distinct p from (values (new.portfolio_id), (case when tg_op = 'UPDATE' then old.portfolio_id end)) v(p)
    where p is not null
  loop
    update public.subscriptions
       set seats_used = (select count(*) from public.profiles
                         where portfolio_id = affected and hoa_role = 'manager'),
           updated_at = now()
     where portfolio_id = affected;
  end loop;
  return new;
end;
$$;


ALTER FUNCTION "public"."recount_seats_used"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recurring_next_date"("p_date" "date", "p_frequency" "text", "p_interval" integer) RETURNS "date"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
  select public.recurring_next_date(p_date, p_frequency, p_interval, null::integer);
$$;


ALTER FUNCTION "public"."recurring_next_date"("p_date" "date", "p_frequency" "text", "p_interval" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recurring_next_date"("p_date" "date", "p_frequency" "text", "p_interval" integer, "p_anchor_day" integer) RETURNS "date"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_months integer;
  v_anchor integer;
  v_target date;
  v_last integer;
begin
  if p_date is null then return null; end if;
  if p_frequency = 'daily' then return p_date + make_interval(days => p_interval); end if;
  if p_frequency = 'weekly' then return p_date + make_interval(weeks => p_interval); end if;
  v_months := case p_frequency
    when 'monthly' then p_interval
    when 'quarterly' then 3 * p_interval
    when 'annually' then 12 * p_interval
  end;
  if v_months is null then return null; end if;
  v_anchor := coalesce(p_anchor_day,
    case when p_date = (date_trunc('month', p_date) + interval '1 month - 1 day')::date then 31
         else extract(day from p_date)::integer end);
  v_target := (date_trunc('month', p_date) + make_interval(months => v_months))::date;
  v_last := extract(day from (v_target + interval '1 month - 1 day'))::integer;
  return v_target + (least(greatest(v_anchor, 1), v_last) - 1);
end;
$$;


ALTER FUNCTION "public"."recurring_next_date"("p_date" "date", "p_frequency" "text", "p_interval" integer, "p_anchor_day" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_lockbox_batch_status"("p_batch" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_open int; v_posted int;
begin
  select count(*) filter (where not rejected and payment_id is null), count(*) filter (where payment_id is not null)
    into v_open, v_posted from public.lockbox_items where batch_id = p_batch;
  update public.lockbox_batches
     set status = case
                    when v_open > 0 and v_posted > 0 then 'processing'::public.lockbox_batch_status
                    when v_open > 0 then 'received'::public.lockbox_batch_status
                    when v_posted > 0 then 'deposited'::public.lockbox_batch_status
                    else 'rejected'::public.lockbox_batch_status end,
         deposited_at = case when v_open = 0 and v_posted > 0 then coalesce(deposited_at, now()) else deposited_at end,
         updated_at = now()
   where id = p_batch;
end $$;


ALTER FUNCTION "public"."refresh_lockbox_batch_status"("p_batch" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_service_request_open_work_order"("p_sr" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  perform pg_advisory_xact_lock(hashtextextended('sr-triage:' || p_sr::text, 0));
  update public.service_requests s
     set has_open_work_order = exists (
           select 1 from public.work_orders w
            where w.service_request_id = s.id and w.archived_at is null
              and w.status not in ('done', 'completed', 'billed', 'closed', 'cancelled'))
   where s.id = p_sr;
end $$;


