CREATE OR REPLACE FUNCTION "public"."relink_all_portal_users"() RETURNS TABLE("target_table" "text", "rows_linked" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  n_owners integer;
  n_board integer;
  n_vendors integer;
  n_tenants integer;
begin
  -- Owner records are linked only by their own invitations, never by email.
  n_owners := 0;

  with upd as (
    update public.board_members bm
       set auth_user_id = u.id
      from auth.users u
      join public.profiles p on p.id = u.id and p.disabled_at is null and p.hoa_role = 'board'
     where bm.auth_user_id is null
       and bm.active
       and lower(u.email) = lower(bm.email)
       and exists (
         select 1 from public.associations a
         where a.id = bm.association_id and a.portfolio_id = p.portfolio_id
       )
    returning 1
  ) select count(*) into n_board from upd;

  -- At most one vendor record per sign-in: the oldest unlinked match, and
  -- only for sign-ins not linked to a vendor record yet.
  with pick as (
    select distinct on (u.id) u.id as user_id, v.id as vendor_id
      from auth.users u
      join public.profiles p on p.id = u.id and p.disabled_at is null and p.hoa_role = 'vendor'
      join public.vendors v on v.portfolio_id = p.portfolio_id
     where v.auth_user_id is null
       and v.archived_at is null
       and not exists (select 1 from public.vendor_portal_logins l where l.vendor_id = v.id and l.revoked_at is null)
       and exists (
         select 1 from jsonb_array_elements_text(v.emails) as e(email)
         where lower(e.email) = lower(u.email)
       )
       and not exists (select 1 from public.vendors linked where linked.auth_user_id = u.id)
       -- A pending vendor invitation links its exact record when accepted
       -- (link_vendor_on_invitation_accept), as in auto_link_portal_user.
       and not exists (
         select 1 from public.user_invitations i
         where i.portfolio_id = p.portfolio_id and i.hoa_role::text = 'vendor' and i.status::text = 'pending'
           and (i.expires_at is null or i.expires_at > now())
           and lower(btrim(i.email)) = lower(btrim(u.email))
       )
     order by u.id, v.created_at, v.id
  ), upd as (
    update public.vendors v
       set auth_user_id = pick.user_id
      from pick
     where v.id = pick.vendor_id
    returning 1
  ) select count(*) into n_vendors from upd;

  with candidates as (
    select distinct on (u.id) t.id as tenant_id, u.id as auth_user_id
    from auth.users u
    join public.profiles p
      on p.id = u.id
     and p.disabled_at is null
     and p.hoa_role = 'tenant'
    join public.tenants t
      on t.portfolio_id = p.portfolio_id
     and t.auth_user_id is null
     and t.status = 'active'
     and t.archived_at is null
     and lower(u.email) = lower(t.email)
    order by u.id, t.created_at desc, t.id
  ), upd as (
    update public.tenants t
       set auth_user_id = candidates.auth_user_id,
           portal_activated = true,
           updated_at = now()
      from candidates
     where t.id = candidates.tenant_id
    returning 1
  ) select count(*) into n_tenants from upd;

  return query values
    ('owners', n_owners),
    ('board_members', n_board),
    ('vendors', n_vendors),
    ('tenants', n_tenants);
end;
$$;


ALTER FUNCTION "public"."relink_all_portal_users"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."relink_all_portal_users"() IS 'One-shot backfill. Run after bulk importing owners/vendors/board_members to link them to existing auth users. Returns counts per table.';



CREATE OR REPLACE FUNCTION "public"."relink_portal_user_on_email_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if new.email is distinct from old.email then
    update public.owners set auth_user_id = null
      where auth_user_id = new.id and lower(email) <> lower(new.email);
    update public.owner_portal_logins l set revoked_at = now()
      where l.auth_user_id = new.id
        and l.revoked_at is null
        and not exists (select 1 from public.owners o
                         where o.id = l.owner_id and lower(btrim(o.email)) = lower(btrim(new.email)));
    update public.board_members set auth_user_id = null
      where auth_user_id = new.id and lower(email) <> lower(new.email);
    update public.vendors v set auth_user_id = null
      where v.auth_user_id = new.id
        and not exists (
          select 1 from jsonb_array_elements_text(v.emails) as e(email)
          where lower(e.email) = lower(new.email)
        );
    update public.vendor_portal_logins l set revoked_at = now()
      where l.auth_user_id = new.id
        and l.revoked_at is null
        and not exists (
          select 1 from public.vendors v, jsonb_array_elements(case when jsonb_typeof(v.emails) = 'array' then v.emails else '[]'::jsonb end) as e(val)
           where v.id = l.vendor_id
             and lower(btrim(case jsonb_typeof(e.val)
                                when 'string' then e.val #>> '{}'
                                when 'object' then e.val ->> 'email'
                              end)) = lower(btrim(new.email)));
    update public.tenants set auth_user_id = null, portal_activated = false, updated_at = now()
      where auth_user_id = new.id and lower(email) <> lower(new.email);
    -- Nothing new is linked by the changed email.
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."relink_portal_user_on_email_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_late_fee"("p_charge_id" "uuid", "p_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  c public.charges;
  v_assoc uuid;
  v_pid uuid;
  v_open numeric;
  v_income uuid;
  v_reason text := left(btrim(coalesce(p_reason, '')), 400);
  v_credit uuid;
begin
  select * into c from public.charges where id = p_charge_id;
  if not found then raise exception 'Late fee not found' using errcode = 'P0002'; end if;
  v_assoc := public.unit_association_id(c.unit_id);
  select a.portfolio_id into v_pid from public.associations a where a.id = v_assoc;
  if v_pid is null or not public.can_manage_finance(v_pid) or not public.can_manage_association(v_assoc) then
    raise exception 'Late fee not found' using errcode = 'P0002';
  end if;
  if c.charge_type <> 'late_fee' then
    raise exception 'Only a late fee can be removed here; use a credit for other charges' using errcode = '22023';
  end if;
  if char_length(v_reason) < 3 then
    raise exception 'Say why the late fee is removed' using errcode = '22023';
  end if;
  -- Same lock as payment application on the unit, so two removals (or a
  -- removal and a payment) can't both take the same open amount.
  perform pg_advisory_xact_lock(hashtextextended('unit-apply:' || c.unit_id::text, 0));
  v_open := c.amount - coalesce((select sum(pa.amount_applied) from public.payment_applications pa where pa.charge_id = c.id), 0);
  if v_open <= 0.005 then
    raise exception 'This late fee is already paid or removed. To give the money back, post a credit or a refund' using errcode = '22023';
  end if;
  -- The account the fee's own posting credited (net of any reposting). Only
  -- this company's entries and this association's accounts count, so an
  -- entry someone else pointed at the charge can't steer or block it.
  select jl.gl_account_id into v_income
    from public.journal_lines jl
    join public.journal_entries je on je.id = jl.entry_id
    join public.gl_accounts g on g.id = jl.gl_account_id
   where je.source_type = 'charge' and je.source_id = c.id and je.posted
     and je.portfolio_id = v_pid
     and g.portfolio_id = v_pid and (g.association_id is null or g.association_id = v_assoc)
   group by jl.gl_account_id
  having sum(jl.credit_amount - jl.debit_amount) > 0
   order by sum(jl.credit_amount - jl.debit_amount) desc
   limit 1;
  if v_income is null then
    select g.income into v_income from public.charge_gl_accounts(c) g;
  end if;
  if v_income is null then
    raise exception 'Set the income account on the late fee charge category first' using errcode = '22023';
  end if;
  if not exists (select 1 from public.gl_accounts g where g.id = v_income and g.active) then
    raise exception 'The income account this late fee was posted to is inactive. Reactivate it in the chart of accounts, then remove the fee' using errcode = '22023';
  end if;
  v_credit := public.post_homeowner_credit(c.unit_id, round(v_open, 2), public.association_local_date(v_assoc), v_income,
                                           'Late fee removed: ' || v_reason, c.id);
  -- The owner's ledger shows the reference (the reason stays staff-only in
  -- payment_private), so the credit reads as a removed fee, not a payment.
  update public.payments set reference = 'Late fee removed' where id = v_credit;
  insert into public.audit_logs (portfolio_id, entity_type, entity_id, action, actor_id, actor_email, changes)
  values (v_pid, 'unit', c.unit_id, 'late_fee_removed', auth.uid(), (select email from auth.users where id = auth.uid()),
          jsonb_build_object('charge_id', c.id, 'amount', round(v_open, 2), 'credit_payment_id', v_credit,
                             'income_gl_account_id', v_income, 'reason', v_reason));
  return v_credit;
end
$$;


ALTER FUNCTION "public"."remove_late_fee"("p_charge_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_staff_member"("p_profile_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "public"."profiles"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  target public.profiles;
  updated public.profiles;
begin
  select * into target from public.profiles where id = p_profile_id;
  if not found then
    raise exception 'remove_staff_member: profile not found';
  end if;

  if not public.can_admin_portfolio(target.portfolio_id) then
    raise exception 'remove_staff_member: must be admin of profile''s portfolio';
  end if;

  if target.hoa_role is null or target.hoa_role::text not in ('manager', 'company_admin') then
    raise exception 'remove_staff_member: only staff members can be removed from the team (target is %)', coalesce(target.hoa_role::text, 'unknown');
  end if;

  if p_profile_id = auth.uid() then
    raise exception 'remove_staff_member: cannot remove yourself';
  end if;

  update public.profiles
     set portfolio_id = null,
         role_id = null,
         hoa_role = 'owner',
         updated_at = now()
   where id = p_profile_id
   returning * into updated;

  -- Log reason separately into audit log details
  insert into public.permission_audit_log (
    actor_user_id, actor_portfolio_id, target_entity_type, target_entity_id,
    action, details
  ) values (
    auth.uid(), target.portfolio_id, 'profile', p_profile_id,
    'staff_removed',
    jsonb_build_object('reason', p_reason)
  );

  return updated;
end;
$$;


ALTER FUNCTION "public"."remove_staff_member"("p_profile_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."render_invitation_email"("inv" "public"."user_invitations") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  portfolio_row public.portfolios;
  role_name text;
  inviter_email text;
  company text;
  base_url text;
  accept_url text;
  runbook_base text;
  runbook_url text;
  html text;
  txt text;
  subject text;
begin
  select * into portfolio_row from public.portfolios where id = inv.portfolio_id;
  select name into role_name from public.user_roles where id = inv.role_id;
  select email into inviter_email from auth.users where id = inv.invited_by;

  if inv.token is null or inv.token !~ '^[A-Za-z0-9_-]{16,128}$' then
    raise exception 'render_invitation_email: invitation token has an invalid format';
  end if;

  company := coalesce(nullif(btrim(portfolio_row.company_name), ''), 'your management company');

  base_url := case
    when portfolio_row.slug ~ '^[a-z0-9](?:[a-z0-9-]{0,30}[a-z0-9])$'
      then 'https://' || portfolio_row.slug || '.portier369.com'
    else rtrim(public.app_portal_url(), '/')
  end;
  accept_url := base_url || '/invite?token=' || inv.token;
  runbook_base := case
    when portfolio_row.custom_domain is not null
     and portfolio_row.custom_domain_verified_at > now() - interval '3 hours'
      then 'https://' || portfolio_row.custom_domain
    else base_url
  end;
  runbook_url := case when inv.hoa_role::text = 'manager'
    then runbook_base || '/manuals/manager-runbook.pdf' end;

  subject := format('You''re invited to %s', company);

  html := format($html$<!doctype html>
<html><body style="font-family:-apple-system,Segoe UI,sans-serif;max-width:560px;margin:40px auto;padding:24px;color:#1a1a1a;">
  <h2 style="margin:0 0 16px;">You're invited to %s</h2>
  <p>%s invited you to join <strong>%s</strong>%s.</p>
  %s
  <p style="margin:24px 0;"><a href="%s" style="background:#2563eb;color:white;padding:10px 16px;border-radius:6px;text-decoration:none;display:inline-block;">Accept invitation</a></p>
  %s
  <p style="font-size:12px;color:#666;">This invitation expires on %s. If you can't click the button, copy this link into your browser:<br/><code style="font-size:11px;word-break:break-all;">%s</code></p>
</body></html>$html$,
    public.html_escape(company),
    public.html_escape(coalesce(inviter_email, 'An administrator')),
    public.html_escape(company),
    case when role_name is not null then ' as a ' || public.html_escape(role_name) else '' end,
    case when inv.message is not null and length(btrim(inv.message)) > 0 then
      '<p style="background:#f3f4f6;padding:12px 16px;border-radius:6px;font-style:italic;">' || public.html_escape(inv.message) || '</p>'
    else '' end,
    public.html_escape(accept_url),
    case when runbook_url is not null then
      '<p>Your operating guide (Manager Runbook), worth bookmarking: <a href="' || public.html_escape(runbook_url) || '">Manager Runbook</a></p>'
    else '' end,
    to_char(inv.expires_at at time zone 'UTC', 'Mon DD YYYY "at" HH24:MI "UTC"'),
    public.html_escape(accept_url)
  );

  txt := format(E'You''re invited to %s.\n\n%s invited you to join %s%s.\n\n%sAccept the invitation: %s\n\n%sExpires: %s',
    company,
    coalesce(inviter_email, 'An administrator'),
    company,
    case when role_name is not null then ' as a ' || role_name else '' end,
    case when inv.message is not null and length(btrim(inv.message)) > 0 then inv.message || E'\n\n' else '' end,
    accept_url,
    case when runbook_url is not null then 'Your operating guide (Manager Runbook): ' || runbook_url || E'\n\n' else '' end,
    to_char(inv.expires_at at time zone 'UTC', 'Mon DD YYYY HH24:MI UTC')
  );

  return jsonb_build_object('subject', subject, 'html', html, 'text', txt);
end;
$_$;


ALTER FUNCTION "public"."render_invitation_email"("inv" "public"."user_invitations") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."render_invitation_email"("inv" "public"."user_invitations") IS 'Subject/html/text for an invitation email. Accept link on the company workspace <slug>.portier369.com (app_portal_url() only when the slug is unusable); staff invitations link the Manager Runbook (verified custom domain, else the workspace).';



CREATE OR REPLACE FUNCTION "public"."reopen_budget"("p_association_id" "uuid", "p_fiscal_year" integer, "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_portfolio uuid;
begin
  if not public.can_mutate_association_budget(p_association_id) then
    raise exception 'Finance authorization required' using errcode = '42501';
  end if;
  if length(btrim(coalesce(p_reason, ''))) < 5 or length(p_reason) > 2000 then
    raise exception 'Give a reason for reopening the adopted budget' using errcode = '22023';
  end if;
  update public.association_budgets set status = 'draft', updated_at = now()
   where association_id = p_association_id and fiscal_year = p_fiscal_year and status = 'adopted'
  returning portfolio_id into v_portfolio;
  if not found then raise exception 'This budget is not adopted' using errcode = '22023'; end if;
  insert into public.audit_logs (portfolio_id, entity_type, entity_id, action, actor_id, actor_email, changes)
  values (v_portfolio, 'association', p_association_id, 'budget_reopened', auth.uid(), (select email from auth.users where id = auth.uid()),
          jsonb_build_object('fiscal_year', p_fiscal_year, 'reason', p_reason));
end $$;


ALTER FUNCTION "public"."reopen_budget"("p_association_id" "uuid", "p_fiscal_year" integer, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reorder_agenda_items"("p_meeting_id" "uuid", "p_item_ids" "uuid"[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_association_id uuid;
  v_status public.meeting_status;
  v_item_count integer;
  v_updated_count integer;
begin
  if auth.uid() is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  if p_meeting_id is null
     or p_item_ids is null
     or cardinality(p_item_ids) not between 1 and 500
     or exists (select 1 from unnest(p_item_ids) as item(item_id) where item.item_id is null)
     or (select count(distinct item.item_id) from unnest(p_item_ids) as item(item_id))
        <> cardinality(p_item_ids) then
    raise exception 'Invalid agenda ordering input' using errcode = '22023';
  end if;

  select m.association_id, m.status
  into v_association_id, v_status
  from public.meetings m
  join public.associations a
    on a.id = m.association_id
   and a.portfolio_id = m.portfolio_id
  where m.id = p_meeting_id;

  if not found then
    raise exception 'Meeting not found or tenant scope is invalid' using errcode = 'P0002';
  end if;
  if not public.can_edit_association_mvp(v_association_id) then
    raise exception 'Meeting editor authorization required' using errcode = '42501';
  end if;
  if v_status in ('completed', 'cancelled') then
    raise exception 'A finalized meeting agenda cannot be reordered' using errcode = '55000';
  end if;

  perform 1
  from public.agenda_items ai
  where ai.meeting_id = p_meeting_id
  for update;

  select count(*)::integer
  into v_item_count
  from public.agenda_items ai
  where ai.meeting_id = p_meeting_id;

  if v_item_count <> cardinality(p_item_ids)
     or exists (
       select 1
       from unnest(p_item_ids) as requested(item_id)
       left join public.agenda_items ai
         on ai.id = requested.item_id
        and ai.meeting_id = p_meeting_id
       where ai.id is null
     ) then
    raise exception 'Agenda ordering must include every item exactly once' using errcode = '23514';
  end if;

  update public.agenda_items ai
  set sort_order = (ordered.ordinal - 1)::integer,
      updated_at = now()
  from unnest(p_item_ids) with ordinality as ordered(item_id, ordinal)
  where ai.id = ordered.item_id
    and ai.meeting_id = p_meeting_id;

  get diagnostics v_updated_count = row_count;
  if v_updated_count <> cardinality(p_item_ids) then
    raise exception 'Agenda ordering changed concurrently' using errcode = '40001';
  end if;
end;
$$;


ALTER FUNCTION "public"."reorder_agenda_items"("p_meeting_id" "uuid", "p_item_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."report_access_error_as"("p_user_id" "uuid", "p_portfolio_id" "uuid", "p_slug" "text", "p_params" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_claims text := current_setting('request.jwt.claims', true);
  v_sub text := current_setting('request.jwt.claim.sub', true);
  v_error text;
begin
  if p_user_id is null then return 'This schedule has no user to run as.'; end if;
  perform set_config('request.jwt.claim.sub', '', true);
  perform set_config('request.jwt.claims', json_build_object('sub', p_user_id, 'role', 'authenticated')::text, true);
  v_error := public.report_params_access_error(p_portfolio_id, p_slug, coalesce(p_params, '{}'::jsonb));
  perform set_config('request.jwt.claims', coalesce(v_claims, ''), true);
  perform set_config('request.jwt.claim.sub', coalesce(v_sub, ''), true);
  return v_error;
end $$;


ALTER FUNCTION "public"."report_access_error_as"("p_user_id" "uuid", "p_portfolio_id" "uuid", "p_slug" "text", "p_params" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."report_allowed_recipients"("p_portfolio_id" "uuid", "p_slug" "text", "p_params" "jsonb", "p_targets" "jsonb") RETURNS TABLE("email" "text", "full_name" "text", "error" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
#variable_conflict use_column
declare
  v_target text;
  v_profile_id uuid;
  v_profile_name text;
  v_error text;
begin
  if p_targets is null or jsonb_typeof(p_targets) <> 'array' then return; end if;
  for v_target in
    select distinct lower(btrim(t.value)) from jsonb_array_elements_text(p_targets) t where btrim(t.value) <> ''
  loop
    select p.id, p.full_name into v_profile_id, v_profile_name
      from public.profiles p
     where lower(p.email) = v_target
       and p.portfolio_id = p_portfolio_id
       and p.disabled_at is null
       and p.hoa_role::text in ('manager', 'company_admin')
     order by p.created_at, p.id
     limit 1;
    if not found then
      email := v_target; full_name := null;
      error := format('%s is not an active user of this company. Scheduled reports are emailed only to your company''s staff.', v_target);
      return next;
      continue;
    end if;
    v_error := public.report_access_error_as(v_profile_id, p_portfolio_id, p_slug, p_params);
    email := v_target; full_name := v_profile_name;
    error := case when v_error is null then null else format('%s is not allowed to receive this report.', v_target) end;
    return next;
  end loop;
end $$;


ALTER FUNCTION "public"."report_allowed_recipients"("p_portfolio_id" "uuid", "p_slug" "text", "p_params" "jsonb", "p_targets" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."report_data_account_totals"("p_portfolio_id" "uuid", "p_params" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$#variable_conflict use_column
begin
  return (select s.x from (

  select coalesce(jsonb_agg(to_jsonb(r.*)), '[]'::jsonb) from (
    with prm as (select * from public.rpt_prm(p_params))
    select g.number, g.name, g.account_type::text as account_type,
             sum(jl.debit_amount) as total_debits, sum(jl.credit_amount) as total_credits,
             sum(public.rpt_sign(g.account_type::text, jl.debit_amount, jl.credit_amount)) as balance
      from public.journal_lines jl
      join public.journal_entries je on je.id = jl.entry_id and je.posted and je.portfolio_id = p_portfolio_id
      join public.gl_accounts g on g.id = jl.gl_account_id
      cross join prm
      left join public.associations a on a.id = jl.association_id
      where (prm.aid is null or jl.association_id = prm.aid) and je.entry_date between prm.df and prm.dt
      group by g.id order by g.number
  ) r
  ) s(x) limit 1);
end$$;


