CREATE OR REPLACE FUNCTION "public"."report_data_board_rollup"("p_portfolio_id" "uuid", "p_params" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$#variable_conflict use_column
