CREATE OR REPLACE FUNCTION "public"."report_data_cash_flow"("p_portfolio_id" "uuid", "p_params" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$#variable_conflict use_column
begin
  return (select s.x from (

  select coalesce(jsonb_agg(to_jsonb(r.*) order by r.number), '[]'::jsonb) from (
    with prm as (select * from public.rpt_prm(p_params))
    select g.number, g.name,
           coalesce(sum(jl.debit_amount) filter (where je.entry_date < prm.df), 0)
             - coalesce(sum(jl.credit_amount) filter (where je.entry_date < prm.df), 0) as opening_balance,
           coalesce(sum(jl.debit_amount) filter (where je.entry_date between prm.df and prm.dt), 0) as cash_in,
           coalesce(sum(jl.credit_amount) filter (where je.entry_date between prm.df and prm.dt), 0) as cash_out,
           coalesce(sum(jl.debit_amount - jl.credit_amount) filter (where je.entry_date between prm.df and prm.dt), 0) as net_change,
           coalesce(sum(jl.debit_amount - jl.credit_amount) filter (where je.entry_date <= prm.dt), 0) as closing_balance
      from public.journal_lines jl
      join public.journal_entries je on je.id = jl.entry_id and je.posted and je.portfolio_id = p_portfolio_id
      join public.gl_accounts g on g.id = jl.gl_account_id and g.account_type::text = 'cash'
      cross join prm
     where (prm.aid is null or jl.association_id = prm.aid)
       and je.entry_date <= prm.dt
     group by g.id, g.number, g.name
  ) r
  ) s(x) limit 1);
end$$;


ALTER FUNCTION "public"."report_data_cash_flow"("p_portfolio_id" "uuid", "p_params" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."report_data_cash_flow_12_month"("p_portfolio_id" "uuid", "p_params" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$#variable_conflict use_column
begin
  return (select s.x from (

  select coalesce(jsonb_agg(to_jsonb(r.*)), '[]'::jsonb) from (
    with prm as (select * from public.rpt_prm(p_params))
    select to_char(m.month, 'YYYY-MM') as month,
             coalesce(sum(jl.credit_amount - jl.debit_amount) filter (where g.account_type::text in ('income','other_income')), 0) as income,
             coalesce(sum(jl.debit_amount - jl.credit_amount) filter (where g.account_type::text in ('expense','cost_of_goods_sold','other_expense','non_operating')), 0) as expenses,
             coalesce(sum(jl.credit_amount - jl.debit_amount) filter (where (g.account_type::text in ('income','other_income') or g.account_type::text in ('expense','cost_of_goods_sold','other_expense','non_operating'))), 0) as net_cash_flow
      from prm
      cross join generate_series(date_trunc('month', prm.dt) - interval '11 months', date_trunc('month', prm.dt), interval '1 month') m(month)
      left join public.journal_entries je on je.portfolio_id = p_portfolio_id and je.posted and date_trunc('month', je.entry_date) = m.month
      left join public.journal_lines jl on jl.entry_id = je.id and (prm.aid is null or jl.association_id = prm.aid)
      left join public.gl_accounts g on g.id = jl.gl_account_id and (g.account_type::text in ('income','other_income') or g.account_type::text in ('expense','cost_of_goods_sold','other_expense','non_operating'))
      group by m.month order by m.month
  ) r
  ) s(x) limit 1);
end$$;


