CREATE OR REPLACE FUNCTION "public"."report_data_cash_flow_association_comparison"("p_portfolio_id" "uuid", "p_params" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
