CREATE OR REPLACE FUNCTION "public"."report_data_work_orders"("p_portfolio_id" "uuid", "p_params" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  f_from date;
  f_to date;
  f_status text := nullif(p_params->>'status', '');
  f_association uuid;
begin
  begin
    f_from := coalesce(
      nullif(p_params->>'date_from', '')::date,
      nullif(p_params->>'from_date', '')::date,
      nullif(p_params->>'date_start', '')::date,
      current_date - interval '90 days'
    );
    f_to := coalesce(
      nullif(p_params->>'date_to', '')::date,
      nullif(p_params->>'to_date', '')::date,
      nullif(p_params->>'date_end', '')::date,
      current_date
    );
    f_association := nullif(p_params->>'association_id', '')::uuid;
  exception when invalid_text_representation or datetime_field_overflow then
    raise exception 'invalid work-order report parameters';
  end;

  if f_from > f_to then
    raise exception 'report start date must not be after end date';
  end if;

  if f_association is not null and not exists (
    select 1 from public.associations a
    where a.id = f_association
      and a.portfolio_id = p_portfolio_id
      and a.archived_at is null
  ) then
    raise exception 'association is not accessible for this portfolio';
  end if;

  return (
    select coalesce(jsonb_agg(to_jsonb(r.*) order by r.created_at desc), '[]'::jsonb)
    from (
      select w.number, w.title, w.status::text, w.priority::text,
             w.category::text, w.trade::text, a.name as association,
             u.unit_number, v.name as vendor, w.scheduled_date,
             w.completed_date, w.created_at, w.assigned_to
      from public.work_orders w
      join public.associations a on a.id = w.association_id
      left join public.units u on u.id = w.unit_id
      left join public.vendors v on v.id = w.vendor_id
      where a.portfolio_id = p_portfolio_id
        and (f_association is null or a.id = f_association)
        and w.created_at::date between f_from and f_to
        and w.archived_at is null
        and (f_status is null or w.status::text = f_status)
    ) r
  );
end;
$$;


ALTER FUNCTION "public"."report_data_work_orders"("p_portfolio_id" "uuid", "p_params" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."report_params_access_error"("p_portfolio_id" "uuid", "p_slug" "text", "p_params" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  v_assoc uuid;
  v_unit uuid;
  v_unit_assoc uuid;
  v_slug text := coalesce(p_slug, '');
begin
  begin
    v_assoc := nullif(p_params ->> 'association_id', '')::uuid;
    v_unit := nullif(p_params ->> 'unit_id', '')::uuid;
  exception when invalid_text_representation then
    return 'The selected association or unit is not valid.';
  end;

  if not public.can_access_portfolio(p_portfolio_id) then
    return 'You no longer have access to this company.';
  end if;
  if v_slug ~ '(1099|_tax_|^corporate_|^customer_ledger$)' and not public.can_manage_finance(p_portfolio_id) then
    return 'Tax and corporate accounting reports are limited to finance staff.';
  end if;
  -- po_decisions: purchase orders are readable by finance staff only.
  if v_slug ~ '^purchase_order' and not public.can_manage_finance(p_portfolio_id) then
    return 'Purchase order reports are limited to finance staff.';
  end if;
  -- People data: who works here, their roles and every sign-in attempt.
  if v_slug in ('users', 'users_and_permissions', 'user_roles_permissions', 'login_audit')
     and not (public.is_full_access_staff() or public.is_company_admin() or public.is_platform_operator()) then
    return 'User and sign-in reports are limited to company admins and full-access staff.';
  end if;
  if v_slug in ('association_log', 'email_delivery_errors', 'survey_results', 'users', 'users_and_permissions', 'data_diagnostics_summary', 'login_audit',
                'user_roles_permissions', 'vendor_directory', 'inventory_status', 'property_group_directory')
     and public.manager_is_scoped() then
    return 'This company-wide report is limited to staff with access to every association.';
  end if;
  if v_assoc is not null and not exists (
       select 1 from public.associations a
        where a.id = v_assoc and a.portfolio_id = p_portfolio_id and public.can_view_association_row(a.id)) then
    return 'You cannot access the selected association.';
  end if;
  if v_assoc is null and public.manager_is_scoped() then
    return 'Choose one of your associations for this report.';
  end if;
  if nullif(p_params ->> 'owner_id', '') is not null then
    return 'This report cannot be filtered by homeowner. Choose an association instead.';
  end if;
  if v_unit is not null then
    if v_slug not in ('owner_ledger', 'homeowner_ledger', 'homeowner_resale') then
      return 'This report cannot be filtered by unit. Choose an association instead.';
    end if;
    select b.association_id into v_unit_assoc
      from public.units u join public.buildings b on b.id = u.building_id
      join public.associations a on a.id = b.association_id
     where u.id = v_unit and a.portfolio_id = p_portfolio_id;
    if v_unit_assoc is null or not public.can_view_association_row(v_unit_assoc) then
      return 'You cannot access the selected unit.';
    end if;
    if v_assoc is not null and v_unit_assoc <> v_assoc then
      return 'The selected unit is not in the selected association.';
    end if;
  end if;
  return null;
end $_$;


ALTER FUNCTION "public"."report_params_access_error"("p_portfolio_id" "uuid", "p_slug" "text", "p_params" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."report_recipients_error"("p_portfolio_id" "uuid", "p_slug" "text", "p_params" "jsonb", "p_targets" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_error text;
  v_count integer := 0;
begin
  if not public.can_access_portfolio(p_portfolio_id) then
    return 'You no longer have access to this company.';
  end if;
  if p_targets is not null and jsonb_typeof(p_targets) = 'array' then
    select count(distinct lower(btrim(t.value))) into v_count
      from jsonb_array_elements_text(p_targets) t where btrim(t.value) <> '';
  end if;
  if v_count = 0 then
    return 'Add at least one recipient for email delivery.';
  end if;
  if v_count > 25 then
    return 'Add at most 25 recipients.';
  end if;
  select r.error into v_error
    from public.report_allowed_recipients(p_portfolio_id, p_slug, p_params, p_targets) r
   where r.error is not null
   limit 1;
  return v_error;
end $$;


ALTER FUNCTION "public"."report_recipients_error"("p_portfolio_id" "uuid", "p_slug" "text", "p_params" "jsonb", "p_targets" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."report_run_access_error"("p_run_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_run record;
  v_claims text := current_setting('request.jwt.claims', true);
  v_sub text := current_setting('request.jwt.claim.sub', true);
  v_error text;
begin
  select r.portfolio_id, r.parameters, r.triggered_by, d.slug
    into v_run
    from public.report_runs r
    left join public.report_definitions d on d.id = r.definition_id
   where r.id = p_run_id;
  if not found then return 'Report run not found.'; end if;
  if v_run.triggered_by is null then return 'This report run has no requesting user.'; end if;

  perform set_config('request.jwt.claim.sub', '', true);
  perform set_config('request.jwt.claims', json_build_object('sub', v_run.triggered_by, 'role', 'authenticated')::text, true);
  v_error := public.report_params_access_error(v_run.portfolio_id, v_run.slug, coalesce(v_run.parameters, '{}'::jsonb));
  perform set_config('request.jwt.claims', coalesce(v_claims, ''), true);
  perform set_config('request.jwt.claim.sub', coalesce(v_sub, ''), true);
  return v_error;
end $$;


ALTER FUNCTION "public"."report_run_access_error"("p_run_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."data_export_requests" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "portfolio_id" "uuid",
    "subject_auth_user_id" "uuid",
    "scope" "public"."export_scope" DEFAULT 'portfolio_full'::"public"."export_scope" NOT NULL,
    "requested_by" "uuid",
    "status" "public"."export_status" DEFAULT 'pending'::"public"."export_status" NOT NULL,
    "format" "text" DEFAULT 'json'::"text" NOT NULL,
    "file_url" "text",
    "file_size_bytes" bigint,
    "error_message" "text",
    "started_at" timestamp with time zone,
    "completed_at" timestamp with time zone,
    "expires_at" timestamp with time zone DEFAULT ("now"() + '7 days'::interval),
    "download_count" integer DEFAULT 0 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "data_export_requests_format_check" CHECK (("format" = ANY (ARRAY['json'::"text", 'csv'::"text", 'zip'::"text"])))
);


ALTER TABLE "public"."data_export_requests" OWNER TO "postgres";


COMMENT ON TABLE "public"."data_export_requests" IS 'Async data export jobs. Portfolio admins request via admin panel (requires data_export entitlement). Expired exports are purged by cron.';



CREATE OR REPLACE FUNCTION "public"."request_data_export"("p_portfolio_id" "uuid", "p_scope" "public"."export_scope" DEFAULT 'portfolio_full'::"public"."export_scope", "p_format" "text" DEFAULT 'json'::"text") RETURNS "public"."data_export_requests"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  row public.data_export_requests;
begin
  if not public.can_admin_portfolio(p_portfolio_id) then
    raise exception 'request_data_export: portfolio admin required';
  end if;
  if not public.has_entitlement(p_portfolio_id, 'data_export') then
    raise exception 'request_data_export: data_export entitlement required (upgrade to Max tier)';
  end if;

  insert into public.data_export_requests (
    portfolio_id, scope, format, requested_by
  ) values (
    p_portfolio_id, p_scope, p_format, auth.uid()
  ) returning * into row;
  return row;
end;
$$;


ALTER FUNCTION "public"."request_data_export"("p_portfolio_id" "uuid", "p_scope" "public"."export_scope", "p_format" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_owner_violation_hearing"("p_violation_id" "uuid", "p_reason" "text") RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_violation public.violations%rowtype;
  v_reason text := trim(p_reason);
  v_days integer;
  v_notice date;
  v_today date;
begin
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;
  if not exists (select 1 from public.current_owner_ids()) then
    raise exception 'Active owner portal access is required';
  end if;
  if char_length(v_reason) < 10 or char_length(v_reason) > 1000 then
    raise exception 'Hearing request reason must be 10 to 1,000 characters';
  end if;

  select * into v_violation
  from public.violations v
  where v.id = p_violation_id
    and v.owner_id in (select public.current_owner_ids())
    and v.archived_at is null
  for update;

  if not found then
    raise exception 'Violation not found';
  end if;
  if v_violation.status in ('cured', 'closed') then
    raise exception 'A hearing cannot be requested for a closed violation';
  end if;
  if v_violation.hearing_requested_at is not null then
    return v_violation.hearing_requested_at;
  end if;

  -- A hearing can be requested once the first notice is sent, and only
  -- within the window that runs from it (advance_violation's fine gate uses
  -- the same clock).
  if v_violation.notice_sent_at is null then
    raise exception 'A hearing can be requested once the association sends its first notice about this violation.';
  end if;
  if v_violation.notice_sent_at is not null then
    select coalesce(s.hearing_request_days, 14) into v_days
      from (select 1) x left join public.association_violation_settings s on s.association_id = v_violation.association_id;
    v_notice := public.association_local_date(v_violation.association_id, v_violation.notice_sent_at);
    v_today := public.association_local_date(v_violation.association_id, now());
    if v_today > v_notice + coalesce(v_days, 14) then
      raise exception 'The time to request a hearing ended on %. Contact your association manager.',
        to_char(v_notice + coalesce(v_days, 14), 'Mon DD, YYYY');
    end if;
  end if;

  update public.violations
  set hearing_required = true,
      hearing_requested_at = now(),
      hearing_request_note = v_reason,
      status = 'hearing_pending'
  where id = p_violation_id
  returning hearing_requested_at into v_violation.hearing_requested_at;

  return v_violation.hearing_requested_at;
end;
$$;


ALTER FUNCTION "public"."request_owner_violation_hearing"("p_violation_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_payable_bill_approval"("p_bill_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  bill_row public.payable_bills;
  settings_row public.board_approval_settings;
  member_ids uuid[];
  member_count integer;
  required_count integer;
  request_id uuid;
  vendor_name text;
begin
  select * into bill_row from public.payable_bills where id = p_bill_id for update;
  if not found then raise exception 'Bill not found'; end if;
  if not public.can_manage_finance(bill_row.portfolio_id) then raise exception 'Permission denied'; end if;
  if not public.can_view_association_row(bill_row.association_id) then raise exception 'Bill not found'; end if;
  if not public.operator_may_write(false) then raise exception 'Permission denied'; end if;
  if bill_row.status not in ('draft'::public.payable_bill_status, 'pending_approval'::public.payable_bill_status) then
    raise exception 'Only draft or pending bills can be submitted for approval';
  end if;
  if bill_row.approval_request_id is not null then return bill_row.approval_request_id; end if;

  -- po_decisions: a bill within a board-approved PO's amount (checked now,
  -- with every bill on the PO) doesn't go to the board again.
  if bill_row.approval_required and bill_row.purchase_order_id is not null
     and public.payable_bill_within_board_approved_po(p_bill_id) then
    update public.payable_bills set approval_required = false where id = p_bill_id;
    bill_row.approval_required := false;
  end if;

  if not bill_row.approval_required then
    update public.payable_bills
       set status = 'pending_approval'::public.payable_bill_status, updated_at = now()
     where id = p_bill_id;
    return null;
  end if;
  if bill_row.association_id is null then
    raise exception 'Board-approved bills require an association';
  end if;

  select * into settings_row from public.board_approval_settings
   where association_id = bill_row.association_id;
  select coalesce(array_agg(bm.id order by bm.id), '{}'::uuid[])
    into member_ids
    from public.board_members bm
   where bm.association_id = bill_row.association_id
     and bm.active
     and (
       coalesce(cardinality(settings_row.default_board_member_ids), 0) = 0
       or bm.id = any(settings_row.default_board_member_ids)
     );
  member_count := coalesce(cardinality(member_ids), 0);
  if member_count = 0 then raise exception 'No active board approvers are configured'; end if;

  settings_row.default_voting_scheme := coalesce(settings_row.default_voting_scheme, 'majority_approval_required'::public.voting_scheme);
  settings_row.signatures_required := coalesce(settings_row.signatures_required, true);
  required_count := case settings_row.default_voting_scheme
    when 'any_one_approver'::public.voting_scheme then 1
    when 'unanimous_approval_required'::public.voting_scheme then member_count
    when 'percentage_required'::public.voting_scheme then greatest(1, ceil(member_count * coalesce(settings_row.default_percentage_required, 100) / 100.0)::integer)
    else floor(member_count / 2.0)::integer + 1
  end;
  select name into vendor_name from public.vendors where id = bill_row.vendor_id;

  insert into public.approval_requests (
    portfolio_id, association_id, vendor_id, request_type, title, description,
    requested_by_name, requested_by_email, amount, due_date, status,
    voting_scheme, required_votes, signatures_required, board_member_ids,
    percentage_required, requested_at
  ) values (
    bill_row.portfolio_id, bill_row.association_id, bill_row.vendor_id, 'expense',
    'Bill ' || coalesce(nullif(trim(bill_row.bill_number), ''), left(bill_row.id::text, 8)) || ' ' || chr(8212) || ' ' || coalesce(vendor_name, 'Vendor'),
    bill_row.memo, coalesce((select full_name from public.profiles where id = auth.uid()), 'Management staff'),
    (select email from auth.users where id = auth.uid()), bill_row.amount, bill_row.due_date, 'pending',
    settings_row.default_voting_scheme, required_count, settings_row.signatures_required,
    member_ids, settings_row.default_percentage_required, now()
  ) returning id into request_id;

  update public.payable_bills
     set status = 'pending_approval'::public.payable_bill_status,
         approval_request_id = request_id,
         updated_at = now()
   where id = p_bill_id;
  return request_id;
end;
$$;


ALTER FUNCTION "public"."request_payable_bill_approval"("p_bill_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resend_invitation"("p_invitation_id" "uuid") RETURNS "public"."user_invitations"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  old_inv public.user_invitations;
  new_inv public.user_invitations;
begin
  select * into old_inv from public.user_invitations where id = p_invitation_id;
  if not found then raise exception 'resend_invitation: not found'; end if;
  if not public.can_admin_portfolio(old_inv.portfolio_id) then
    raise exception 'resend_invitation: must be admin of portfolio';
  end if;
  if old_inv.status <> 'pending' then
    raise exception 'resend_invitation: only pending invitations can be resent';
  end if;

  update public.user_invitations set status = 'revoked', updated_at = now() where id = p_invitation_id;

  insert into public.user_invitations (
    portfolio_id, email, hoa_role, role_id, invited_by, message, expires_at
  ) values (
    old_inv.portfolio_id, old_inv.email, old_inv.hoa_role, old_inv.role_id,
    auth.uid(), old_inv.message, now() + interval '14 days'
  ) returning * into new_inv;
  return new_inv;
end;
$$;


ALTER FUNCTION "public"."resend_invitation"("p_invitation_id" "uuid") OWNER TO "postgres";


