    AS $$
  select ub.unit_id, ub.balance
    from public.unit_balances ub
   where public.is_portal_resident()
     and ub.unit_id in (select public.current_resident_unit_ids());
$$;


ALTER FUNCTION "public"."resident_unit_balances"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_portfolio_for_host"("p_host" "text") RETURNS TABLE("id" "uuid", "slug" "text", "company_name" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with h as (
    select lower(split_part(p_host, ':', 1)) as host
  )
  select p.id, p.slug, p.company_name
    from public.portfolios p, h
   where p.archived_at is null
     and (
       lower(p.custom_domain) = h.host
       or (
         h.host like '%.portier369.com'
         and p.slug = split_part(h.host, '.', 1)
       )
     )
   order by case when lower(p.custom_domain) = h.host then 0 else 1 end
   limit 1;
$$;


ALTER FUNCTION "public"."resolve_portfolio_for_host"("p_host" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."resolve_portfolio_for_host"("p_host" "text") IS 'Resolves an HTTP host header to a portfolio. Called from Next.js middleware via the anon role to set tenant branding context BEFORE authentication. Granted to anon by design — see _REDESIGN_README.md.';



CREATE OR REPLACE FUNCTION "public"."resolve_service_request"("p_id" "uuid", "p_note" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v public.service_requests; v_note text := nullif(btrim(p_note), '');
begin
  v := public.service_request_staff_scope(p_id);
  if v_note is null then raise exception 'Write the reply the resident will see' using errcode = '22023'; end if;
  if v.status not in ('open', 'waiting') then raise exception 'This request is already closed' using errcode = '22023'; end if;
  if exists (select 1 from public.work_orders w where w.service_request_id = p_id and w.archived_at is null
              and w.status not in ('done', 'completed', 'billed', 'closed', 'cancelled')) then
    raise exception 'A work order on this request is still open — finish or cancel it first' using errcode = '22023';
  end if;
  update public.service_requests
     set status = 'completed', resolution_note = v_note, resolved_at = now(), resolved_by = auth.uid(),
         acknowledged_at = coalesce(acknowledged_at, now()), acknowledged_by = coalesce(acknowledged_by, auth.uid()),
         updated_at = now()
   where id = p_id;
end $$;


ALTER FUNCTION "public"."resolve_service_request"("p_id" "uuid", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_violation"("p_violation_id" "uuid", "p_resolution" "text", "p_note" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v public.violations;
begin
  select * into v from public.violations where id = p_violation_id for update;
  if not found or not public.can_manage_violations(v.association_id) then raise exception 'Permission denied' using errcode = '42501'; end if;
  if p_resolution not in ('cured', 'closed') then raise exception 'Resolution must be cured or closed' using errcode = '22023'; end if;
  if v.status in ('cured', 'closed') then return; end if;
  update public.violations
     set status = p_resolution::public.violation_status, cured_at = case when p_resolution = 'cured' then now() else cured_at end, closed_at = now(), next_followup_on = null
   where id = v.id;
  perform public.log_violation_event(v.id, case when p_resolution = 'cured' then 'Marked corrected' else 'Closed' end
      || case when nullif(btrim(coalesce(p_note, '')), '') is not null then '. ' || btrim(p_note) else '' end,
    p_resolution::public.violation_status, true);
end;
$$;


ALTER FUNCTION "public"."resolve_violation"("p_violation_id" "uuid", "p_resolution" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reverse_homeowner_payment"("p_payment_id" "uuid", "p_reason" "text", "p_reversal_date" "date" DEFAULT NULL::"date", "p_charge_nsf_fee" boolean DEFAULT false) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  pay public.payments;
  v_assoc uuid;
  v_pid uuid;
  v_cash uuid;
  v_date date;
  v_reason text := left(btrim(coalesce(p_reason, '')), 200);
  v_charge_id uuid;
begin
  select * into pay from public.payments where id = p_payment_id for update;
  if not found then raise exception 'Payment not found' using errcode = 'P0002'; end if;
  v_assoc := public.unit_association_id(pay.unit_id);
  select portfolio_id into v_pid from public.associations where id = v_assoc;
  if v_pid is null or not public.can_manage_finance(v_pid) or not public.can_manage_association(v_assoc) then
    raise exception 'You do not have accounting access to this association' using errcode = '42501';
  end if;
  if pay.method = 'credit' then
    raise exception 'A credit is not a payment; it cannot be reversed as returned' using errcode = '22023';
  end if;
  if pay.reversed_at is not null then
    raise exception 'This payment was already reversed' using errcode = '22023';
  end if;
  if v_reason = '' then
    raise exception 'Enter why the payment was returned' using errcode = '22023';
  end if;
  v_date := coalesce(p_reversal_date, public.association_local_date(v_assoc));
  if v_date < pay.payment_date then
    raise exception 'The reversal date cannot be before the payment date (%)', pay.payment_date using errcode = '22023';
  end if;

  -- The account the receipt's own posting debited (net of any reposting).
  select jl.gl_account_id into v_cash
    from public.journal_lines jl
    join public.journal_entries je on je.id = jl.entry_id
   where je.source_type = 'payment' and je.source_id = pay.id and je.posted
   group by jl.gl_account_id
  having sum(jl.debit_amount - jl.credit_amount) > 0
   order by sum(jl.debit_amount - jl.credit_amount) desc
   limit 1;
  if v_cash is null then
    select g.cash into v_cash from public.payment_gl_accounts(pay) g;
  end if;
  if v_cash is null then
    raise exception 'No cash account found for this payment' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('unit-apply:' || pay.unit_id::text, 0));
  -- The charges this payment paid are open again.
  delete from public.payment_applications where payment_id = p_payment_id;

  -- Dr A/R, Cr the receipt's cash account, on the reversal date.
  insert into public.charges (unit_id, charge_type, description, amount, due_date, gl_account_id, created_by)
  values (pay.unit_id, 'other',
          left(format('Returned payment%s: %s', coalesce(' ' || nullif(pay.reference, ''), ''), v_reason), 500),
          pay.amount, v_date, v_cash, auth.uid())
  returning id into v_charge_id;

  -- The returned receipt settles its own reversal charge (and nothing else);
  -- undo any credit the new-charge trigger applied to it.
  delete from public.payment_applications where charge_id = v_charge_id;
  insert into public.payment_applications (payment_id, charge_id, amount_applied, applied_by, application_method)
  values (p_payment_id, v_charge_id, pay.amount, auth.uid(), 'manual');

  update public.payments
     set reversed_at = now(), reversed_by = auth.uid(), reversal_reason = v_reason, reversal_charge_id = v_charge_id
   where id = p_payment_id;

  if p_charge_nsf_fee then
    perform public.post_nsf_fee(p_payment_id, 'NSF fee: returned payment');
  end if;

  insert into public.audit_logs (portfolio_id, entity_type, entity_id, action, actor_id, actor_email, changes)
  values (v_pid, 'payment', p_payment_id, 'payment_reversed', auth.uid(), (select email from auth.users where id = auth.uid()),
          jsonb_build_object('amount', pay.amount, 'reason', v_reason, 'reversal_date', v_date,
                             'reversal_charge_id', v_charge_id, 'nsf_fee', p_charge_nsf_fee));
  return v_charge_id;
end
$$;


ALTER FUNCTION "public"."reverse_homeowner_payment"("p_payment_id" "uuid", "p_reason" "text", "p_reversal_date" "date", "p_charge_nsf_fee" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reverse_journal_entry"("p_id" "uuid", "p_reversal_date" "date", "p_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  e public.journal_entries;
  v_rev uuid;
  v_assoc uuid;
begin
  select * into e from public.journal_entries where id = p_id for update;
  if not found or not public.can_manage_finance(e.portfolio_id)
     or exists (select 1 from public.journal_lines jl where jl.entry_id = e.id
                 and jl.association_id is not null and not public.can_manage_association(jl.association_id)) then
    raise exception 'Journal entry not found' using errcode = 'P0002';
  end if;
  if not e.posted then raise exception 'Only a posted entry can be reversed; discard the draft instead' using errcode = '22023'; end if;
  if e.reversed_by_entry_id is not null then raise exception 'This entry is already reversed' using errcode = '22023'; end if;
  if e.source_type = 'je_reversal' then raise exception 'This is a reversing entry; post a new entry instead' using errcode = '22023'; end if;
  if e.source_type is not null and e.source_type not in ('manual', 'adjustment', 'recurring_je', 'je_batch', 'bank_deposit') then
    raise exception 'This entry belongs to a %; void or reverse it from that record', replace(e.source_type, '_', ' ') using errcode = '22023';
  end if;
  if length(btrim(coalesce(p_reason, ''))) < 3 then raise exception 'Give a reason for the reversal' using errcode = '22023'; end if;

  select jl.association_id into v_assoc from public.journal_lines jl
   where jl.entry_id = e.id and jl.association_id is not null order by jl.sort_order, jl.id limit 1;

  insert into public.journal_entries (portfolio_id, entry_date, description, memo, reference_number, source_type, source_id, created_by, posted)
  values (e.portfolio_id,
          coalesce(p_reversal_date, case when v_assoc is not null then public.association_local_date(v_assoc, now()) end, current_date),
          left('Reversal: ' || coalesce(e.description, e.memo, 'journal entry'), 500),
          btrim(p_reason), e.reference_number, 'je_reversal', e.id, auth.uid(), false)
  returning id into v_rev;
  insert into public.journal_lines (entry_id, gl_account_id, association_id, debit_amount, credit_amount, memo, sort_order)
  select v_rev, gl_account_id, association_id, credit_amount, debit_amount, 'Reversal: ' || coalesce(memo, ''), sort_order
    from public.journal_lines where entry_id = e.id;
  update public.journal_entries set posted = true, posted_at = now() where id = v_rev;
  update public.journal_entries set reversed_by_entry_id = v_rev where id = e.id;
  insert into public.audit_logs (portfolio_id, entity_type, entity_id, action, actor_id, changes)
  values (e.portfolio_id, 'journal_entry', e.id, 'reversed', auth.uid(), jsonb_build_object('reversal_entry_id', v_rev, 'reason', btrim(p_reason)));
  return v_rev;
end $$;


ALTER FUNCTION "public"."reverse_journal_entry"("p_id" "uuid", "p_reversal_date" "date", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reverse_subledger_source"("p_source_type" "text", "p_source_id" "uuid", "p_date" "date", "p_memo" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_id uuid; v_portfolio uuid;
begin
  select je.portfolio_id into v_portfolio from public.journal_entries je
   where je.source_type = p_source_type and je.source_id = p_source_id and je.posted limit 1;
  if v_portfolio is null then return null; end if;
  if not exists (
    select 1 from public.journal_lines jl join public.journal_entries je on je.id = jl.entry_id
     where je.source_type = p_source_type and je.source_id = p_source_id and je.posted
     group by jl.gl_account_id, jl.association_id having sum(jl.debit_amount - jl.credit_amount) <> 0) then
    return null;
  end if;
  insert into public.journal_entries (portfolio_id, entry_date, memo, description, source_type, source_id, posted, created_by)
  values (v_portfolio, coalesce(p_date, current_date), left(p_memo, 500), left(p_memo, 500), p_source_type, p_source_id, false, auth.uid())
  returning id into v_id;
  insert into public.journal_lines (entry_id, gl_account_id, association_id, debit_amount, credit_amount, memo, sort_order)
  select v_id, x.gl, x.aid, greatest(-x.net, 0), greatest(x.net, 0), left(p_memo, 500), row_number() over () - 1
    from (select jl.gl_account_id gl, jl.association_id aid, sum(jl.debit_amount - jl.credit_amount) net
            from public.journal_lines jl join public.journal_entries je on je.id = jl.entry_id
           where je.source_type = p_source_type and je.source_id = p_source_id and je.posted and je.id <> v_id
           group by 1, 2 having sum(jl.debit_amount - jl.credit_amount) <> 0) x;
  update public.journal_entries set posted = true where id = v_id;
  return v_id;
end $$;


ALTER FUNCTION "public"."reverse_subledger_source"("p_source_type" "text", "p_source_id" "uuid", "p_date" "date", "p_memo" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."review_delinquency_legal_gate"("p_case_id" "uuid", "p_approved" boolean, "p_note" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  case_row public.delinquency_cases;
begin
  select * into case_row from public.delinquency_cases where id = p_case_id for update;
  if not found then raise exception 'Delinquency case not found'; end if;
  if not (public.can_admin_portfolio(case_row.portfolio_id) or public.is_platform_operator()) then
    raise exception 'Only a human portfolio administrator may review legal escalation';
  end if;
  if case_row.status <> 'legal_review' then raise exception 'Case is not awaiting legal review'; end if;
  if char_length(btrim(coalesce(p_note, ''))) < 20 then
    raise exception 'Legal review note must be at least 20 characters';
  end if;
  update public.delinquency_cases
  set status = case when p_approved then 'approved_for_counsel' else 'on_hold' end,
      hold_reason = case when p_approved then null else btrim(p_note) end,
      legal_reviewed_at = now(), legal_reviewed_by = auth.uid(), legal_review_note = btrim(p_note)
  where id = p_case_id;
  insert into public.delinquency_case_events (case_id, event_type, step_number, balance_snapshot, note)
  values (p_case_id, case when p_approved then 'counsel_referral_approved' else 'legal_escalation_rejected' end,
          case_row.current_step_number, case_row.balance_snapshot, btrim(p_note));
end;
$$;


ALTER FUNCTION "public"."review_delinquency_legal_gate"("p_case_id" "uuid", "p_approved" boolean, "p_note" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."review_delinquency_legal_gate"("p_case_id" "uuid", "p_approved" boolean, "p_note" "text") IS 'Records a human administrative decision only. It never files, sends, or executes legal action.';



CREATE OR REPLACE FUNCTION "public"."review_vendor_document_request"("p_request_id" "uuid", "p_approve" boolean, "p_note" "text", "p_expires_on" "date") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare r record; v_col text; v_path text;
begin
  select * into r from public.document_requests where id = p_request_id and vendor_id is not null for update;
  if not found or not public.can_access_portfolio(r.portfolio_id)
     or not public.can_view_association_row((select ven.association_id from public.vendors ven where ven.id = r.vendor_id)) then
    raise exception 'Request not found' using errcode = 'P0002';
  end if;
  -- Reviewing changes the vendor (expiration dates): the management company
  -- is for company-wide staff, as with any other change to it.
  if not public.can_write_vendor_row((select ven.association_id from public.vendors ven where ven.id = r.vendor_id)) then
    raise exception 'Only company-wide staff can review the management company''s documents' using errcode = '42501';
  end if;
  if r.status::text <> 'submitted' then
    raise exception 'Only submitted documents can be reviewed' using errcode = '55000';
  end if;
  if not p_approve and length(btrim(coalesce(p_note, ''))) < 3 then
    raise exception 'Tell the vendor what is wrong so they can fix it' using errcode = '22023';
  end if;
  v_col := public.vendor_expiration_column(r.doc_type);
  if p_approve and v_col is not null and p_expires_on is null then
    raise exception 'Enter the expiration date from the document' using errcode = '22023';
  end if;

  update public.document_requests
     set status = case when p_approve then 'approved' else 'rejected' end::public.document_request_status,
         reviewed_at = now(), reviewed_by = auth.uid(), review_note = nullif(btrim(p_note), ''), updated_at = now()
   where id = r.id;

  if p_approve and v_col is not null then
    execute format('update public.vendors set %I = $1, updated_at = now() where id = $2', v_col) using p_expires_on, r.vendor_id;
    v_path := r.attachment_urls ->> (jsonb_array_length(r.attachment_urls) - 1);
    if v_path is not null then
      update public.documents set expires_at = p_expires_on::timestamptz
       where entity_type = 'vendor' and entity_id = r.vendor_id and file_url = v_path;
    end if;
  end if;

  insert into public.audit_logs (portfolio_id, entity_type, entity_id, action, actor_id, actor_email, changes)
  values (r.portfolio_id, 'vendor', r.vendor_id, case when p_approve then 'vendor_document_approved' else 'vendor_document_rejected' end,
          auth.uid(), (select email from auth.users where id = auth.uid()),
          jsonb_build_object('request_id', r.id, 'doc_type', r.doc_type, 'expires_on', p_expires_on, 'note', p_note));
end $_$;


ALTER FUNCTION "public"."review_vendor_document_request"("p_request_id" "uuid", "p_approve" boolean, "p_note" "text", "p_expires_on" "date") OWNER TO "postgres";


