CREATE OR REPLACE FUNCTION "public"."rotate_api_key"("p_api_key_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  old_key public.api_keys;
  new_key_result jsonb;
begin
  select * into old_key from public.api_keys where id = p_api_key_id;
  if not found then
    raise exception 'rotate_api_key: key not found';
  end if;
  if not public.can_admin_portfolio(old_key.portfolio_id) then
    raise exception 'rotate_api_key: must be portfolio admin';
  end if;

  update public.api_keys
     set revoked_at = now(), revoked_by = auth.uid(), updated_at = now()
   where id = p_api_key_id;

  new_key_result := public.create_api_key(
    old_key.portfolio_id,
    old_key.name || ' (rotated)',
    old_key.scopes,
    case when old_key.expires_at is not null then extract(day from (old_key.expires_at - now()))::integer end
  );

  return jsonb_build_object(
    'old_key_id', p_api_key_id,
    'new_key', new_key_result
  );
end;
$$;


ALTER FUNCTION "public"."rotate_api_key"("p_api_key_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rotate_signature_signer_token"("p_signer_id" "uuid", "p_token_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare sg public.signature_signers; r public.signature_requests;
begin
  select * into sg from public.signature_signers where id = p_signer_id for update;
  if not found then raise exception 'Signer not found'; end if;
  select * into r from public.signature_requests where id = sg.request_id;
  if not public.can_manage_signatures(r.portfolio_id)
     or not public.can_view_association_row(r.association_id) then
    raise exception 'Permission denied' using errcode = '42501';
  end if;
  if r.status <> 'sent' or sg.status in ('signed', 'declined') then raise exception 'This signer can no longer be reminded' using errcode = '22023'; end if;
  if r.sequential and exists (
    select 1 from public.signature_signers o
     where o.request_id = r.id and o.sign_order < sg.sign_order and o.status <> 'signed'
  ) then raise exception 'This signer''s turn has not come yet; they are emailed when the signer before them signs' using errcode = '22023'; end if;
  if p_token_hash !~ '^[0-9a-f]{64}$' then raise exception 'Invalid token' using errcode = '22023'; end if;
  update public.signature_signers set token_hash = p_token_hash, last_sent_at = now() where id = p_signer_id;
  insert into public.signature_events (request_id, signer_id, event_type, actor_id) values (r.id, sg.id, 'reminder_sent', auth.uid());
  return jsonb_build_object('name', sg.name, 'email', sg.email, 'title', r.title, 'message', r.message, 'expires_at', r.expires_at);
end;
$_$;


ALTER FUNCTION "public"."rotate_signature_signer_token"("p_signer_id" "uuid", "p_token_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."row_association_id"("p_row" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$#variable_conflict use_column
begin
  return (select s.x from (

  select case
    when p_row is null then null
    when p_row ? 'association_id' and p_row->>'association_id' is not null then (p_row->>'association_id')::uuid
    when p_row ? 'unit_id' and p_row->>'unit_id' is not null then public.unit_association_id((p_row->>'unit_id')::uuid)
    when p_row ? 'entity_type' and lower(p_row->>'entity_type') = 'association' then (p_row->>'entity_id')::uuid
    when p_row ? 'entity_type' and lower(p_row->>'entity_type') = 'unit' then public.unit_association_id((p_row->>'entity_id')::uuid)
  end
  ) s(x) limit 1);
end$$;


ALTER FUNCTION "public"."row_association_id"("p_row" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpt_prm"("p_params" "jsonb") RETURNS TABLE("aid" "uuid", "df" "date", "dt" "date", "cmp" "date")
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_today date;
  v_zone text := nullif(p_params ->> 'time_zone', '');
begin
  aid := nullif(p_params ->> 'association_id', '')::uuid;
  if aid is null and v_zone is not null then
    begin
      v_today := (now() at time zone v_zone)::date;
    exception when others then
      v_today := null;
    end;
  end if;
  v_today := coalesce(v_today, public.association_local_date(aid));
  dt := coalesce(nullif(p_params ->> 'date_to', '')::date, v_today);
  df := coalesce(nullif(p_params ->> 'date_from', '')::date, date_trunc('year', dt)::date);
  cmp := coalesce(nullif(p_params ->> 'compare_to', '')::date, (dt - interval '1 year')::date);
  return next;
end $$;


ALTER FUNCTION "public"."rpt_prm"("p_params" "jsonb") OWNER TO "postgres";


