    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$ select case when t in ('asset','cash','accounts_receivable','fixed_asset','expense','cost_of_goods_sold','other_expense','non_operating') then d - c else c - d end $$;


ALTER FUNCTION "public"."rpt_sign"("t" "text", "d" numeric, "c" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."run_autopay_mandates"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  m record;
  processed_count integer := 0;
  amount_cents integer;
  target_charge_id uuid;
begin
  for m in
    select am.*,
           coalesce(am.association_id, a.id) as resolved_association_id,
           coalesce(am.portfolio_id, a.portfolio_id) as resolved_portfolio_id
      from public.autopay_mandates am
      left join public.units u on u.id = am.unit_id
      left join public.buildings b on b.id = u.building_id
      left join public.associations a on a.id = b.association_id
     where am.status = 'active'
       and am.next_run_date <= current_date
       and (am.end_date is null or current_date <= am.end_date)
  loop
    if m.unit_id is null
       or m.resolved_association_id is null
       or m.resolved_portfolio_id is null then
      continue;
    end if;

    select c.id,
           round((c.amount - coalesce((select sum(p.amount) from public.payments p where p.charge_id = c.id), 0)) * 100)::integer
      into target_charge_id, amount_cents
      from public.charges c
     where c.unit_id = m.unit_id
       and c.charge_type = 'assessment'
       and (c.amount - coalesce((select sum(p.amount) from public.payments p where p.charge_id = c.id), 0)) > 0
     order by c.due_date
     limit 1;

    if amount_cents is not null
       and amount_cents > 0
       and amount_cents <= m.authorized_amount_max_cents then
      insert into public.payment_intents (
        portfolio_id, association_id, unit_id, owner_id,
        amount, method, processor, processor_account_id,
        breakdown, status, idempotency_key
      )
      select
        m.resolved_portfolio_id,
        m.resolved_association_id,
        m.unit_id,
        m.owner_id,
        (amount_cents / 100.0)::numeric(14, 2),
        'ach',
        pm.processor::text,
        pm.processor_account_id,
        jsonb_build_array(jsonb_build_object(
          'charge_id', target_charge_id,
          'amount_cents', amount_cents,
          'autopay_mandate_id', m.id,
          'payment_method_id', m.payment_method_id
        )),
        'pending',
        'autopay:' || m.id::text || ':' || target_charge_id::text || ':' || current_date::text
      from public.payment_methods pm
      where pm.id = m.payment_method_id
        and pm.portfolio_id = m.resolved_portfolio_id
        and pm.owner_id = m.owner_id
        and pm.archived_at is null;

      if found then
        update public.autopay_mandates
           set next_run_date = case frequency
                 when 'monthly' then (current_date + interval '1 month')::date
                 when 'quarterly' then (current_date + interval '3 months')::date
                 when 'annually' then (current_date + interval '1 year')::date
                 when 'on_charge_posted' then null
               end,
               last_run_at = now(),
               updated_at = now()
         where id = m.id;
        processed_count := processed_count + 1;
      end if;
    end if;
  end loop;

  return processed_count;
end;
$$;


ALTER FUNCTION "public"."run_autopay_mandates"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."run_management_fees"("p_month" "date", "p_association_ids" "uuid"[], "p_vendor_id" "uuid", "p_gl_account_id" "uuid", "p_bill_date" "date" DEFAULT NULL::"date") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_pid uuid := public.current_portfolio_id();
  v_ids uuid[];
  n integer;
begin
  if v_pid is null or not public.can_manage_finance(v_pid) then raise exception 'Permission denied' using errcode = '42501'; end if;
  if coalesce(cardinality(p_association_ids), 0) = 0 then raise exception 'Select at least one association' using errcode = '22023'; end if;
  select coalesce(array_agg(a.id), '{}') into v_ids
    from public.associations a
   where a.id = any (p_association_ids) and a.portfolio_id = v_pid and public.can_manage_association(a.id);

  n := public.app_bill_management_fees(v_pid, p_month, v_ids, p_vendor_id, p_gl_account_id, p_bill_date, auth.uid(), 'manual');

  if not (public.manager_is_scoped() is true and not public.is_company_admin()) then
    update public.portfolios set management_fee_vendor_id = p_vendor_id, management_fee_gl_account_id = p_gl_account_id
     where id = v_pid;
  end if;
  return n;
end $$;


ALTER FUNCTION "public"."run_management_fees"("p_month" "date", "p_association_ids" "uuid"[], "p_vendor_id" "uuid", "p_gl_account_id" "uuid", "p_bill_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."run_scheduled_management_fees"("p_today" "date" DEFAULT CURRENT_DATE) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  p record;
  v_month date := (date_trunc('month', p_today) - interval '1 month')::date;
  v_ids uuid[];
  n integer;
  n_companies integer := 0;
  n_bills integer := 0;
  n_failed integer := 0;
begin
  for p in
    select id, management_fee_vendor_id, management_fee_gl_account_id
      from public.portfolios
     where management_fee_auto_enabled and archived_at is null
       -- Changed: not for a suspended company.
       and suspended_at is null
       and extract(day from p_today)::int >= management_fee_auto_day
       and (management_fee_auto_last_month is null or management_fee_auto_last_month < v_month)
     order by id
  loop
    n_companies := n_companies + 1;
    begin
      select coalesce(array_agg(c.association_id), '{}') into v_ids
        from public.app_management_fee_calc(p.id, v_month) c;
      n := public.app_bill_management_fees(p.id, v_month, v_ids, p.management_fee_vendor_id,
             p.management_fee_gl_account_id, null, null, 'schedule');
      update public.portfolios
         set management_fee_auto_last_month = v_month,
             management_fee_auto_last_run = jsonb_build_object('month', v_month, 'ran_at', now(), 'bills', n)
       where id = p.id;
      n_bills := n_bills + n;
    exception when others then
      n_failed := n_failed + 1;
      update public.portfolios
         set management_fee_auto_last_run = jsonb_build_object('month', v_month, 'ran_at', now(), 'error', sqlerrm)
       where id = p.id;
    end;
  end loop;
  return jsonb_build_object('month', v_month, 'companies', n_companies, 'bills', n_bills, 'failed', n_failed);
end $$;


ALTER FUNCTION "public"."run_scheduled_management_fees"("p_today" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_board_report_settings"("p_association_id" "uuid", "p_sections" "text"[], "p_share_scope" "text", "p_auto_publish" boolean, "p_publish_day" integer, "p_notify_board" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_portfolio uuid; v_before jsonb;
begin
  if not public.can_manage_association(p_association_id) then
    raise exception 'Not authorized for this association' using errcode = '42501';
  end if;
  if p_sections is null or cardinality(p_sections) = 0 then
    raise exception 'Choose at least one report for the board package' using errcode = '22023';
  end if;
  select portfolio_id into v_portfolio from public.associations where id = p_association_id;
  select to_jsonb(s) into v_before from public.association_board_report_settings s where association_id = p_association_id;
  insert into public.association_board_report_settings as s
    (association_id, portfolio_id, sections, share_scope, auto_publish, publish_day, notify_board, updated_at, updated_by)
  values (p_association_id, v_portfolio, (select array_agg(distinct x order by x) from unnest(p_sections) x),
          coalesce(p_share_scope, 'board'), coalesce(p_auto_publish, false), coalesce(p_publish_day, 10), coalesce(p_notify_board, true), now(), auth.uid())
  on conflict (association_id) do update set
    sections = excluded.sections, share_scope = excluded.share_scope, auto_publish = excluded.auto_publish,
    publish_day = excluded.publish_day, notify_board = excluded.notify_board, updated_at = now(), updated_by = auth.uid();
  insert into public.audit_logs (portfolio_id, entity_type, entity_id, action, actor_id, actor_email, changes)
  values (v_portfolio, 'association', p_association_id, 'board_report_settings_updated', auth.uid(),
          (select email from auth.users where id = auth.uid()),
          jsonb_build_object('before', v_before, 'after', (select to_jsonb(s) from public.association_board_report_settings s where association_id = p_association_id)));
exception
  when check_violation then raise exception 'Choose valid reports and a publish day between 1 and 28' using errcode = '22023';
end $$;


ALTER FUNCTION "public"."save_board_report_settings"("p_association_id" "uuid", "p_sections" "text"[], "p_share_scope" "text", "p_auto_publish" boolean, "p_publish_day" integer, "p_notify_board" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_budget_worksheet"("p_association_id" "uuid", "p_fiscal_year" integer, "p_lines" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_portfolio uuid;
  r record;
  v_amounts numeric[];
  v_section text;
  n integer := 0;
  v_income numeric := 0;
  v_expense numeric := 0;
begin
  if p_association_id is null or p_fiscal_year not between 2000 and 2100 then
    raise exception 'Invalid budget scope' using errcode = '22023';
  end if;
  if not public.can_mutate_association_budget(p_association_id) then
    raise exception 'Finance authorization required' using errcode = '42501';
  end if;
  if p_lines is null or jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) > 1000 then
    raise exception 'Send between 0 and 1000 lines' using errcode = '22023';
  end if;
  select portfolio_id into v_portfolio from public.associations where id = p_association_id;

  if exists (select 1 from public.association_budgets where association_id = p_association_id and fiscal_year = p_fiscal_year and status = 'adopted') then
    raise exception 'The FY% budget is adopted. Reopen it before editing.', p_fiscal_year using errcode = '55000';
  end if;
  insert into public.association_budgets (portfolio_id, association_id, fiscal_year)
  values (v_portfolio, p_association_id, p_fiscal_year)
  on conflict (association_id, fiscal_year) do update set updated_at = now();

  for r in select (x->>'gl_account_id')::uuid as gid, x->'monthly_amounts' as amts, nullif(btrim(x->>'notes'), '') as notes
             from jsonb_array_elements(p_lines) x loop
    if r.gid is null or not public.budget_gl_account_scope_valid(p_association_id, r.gid) then
      raise exception 'A GL account does not belong to this association' using errcode = '22023';
    end if;
    select public.gl_section(account_type::text) into v_section from public.gl_accounts where id = r.gid;
    if v_section not in ('income', 'expense') then
      raise exception 'Only income and expense accounts can be budgeted' using errcode = '22023';
    end if;
    if r.amts is null or jsonb_typeof(r.amts) <> 'array' or jsonb_array_length(r.amts) <> 12 then
      raise exception 'Each line needs 12 monthly amounts' using errcode = '22023';
    end if;
    begin
      select array_agg(round(v::numeric, 2) order by o) into v_amounts from jsonb_array_elements_text(r.amts) with ordinality t(v, o);
    exception when others then
      raise exception 'Monthly amounts must be numbers' using errcode = '22023';
    end;
    if exists (select 1 from unnest(v_amounts) a where a is null or a::text = 'NaN' or a < 0 or a > 1000000000) then
      raise exception 'Monthly amounts must be between 0 and 1,000,000,000' using errcode = '22023';
    end if;
    if length(coalesce(r.notes, '')) > 10000 then
      raise exception 'Notes are limited to 10,000 characters' using errcode = '22023';
    end if;

    if (select sum(a) from unnest(v_amounts) a) = 0 and r.notes is null then
      delete from public.budget_lines where association_id = p_association_id and gl_account_id = r.gid and fiscal_year = p_fiscal_year;
    else
      insert into public.budget_lines (association_id, gl_account_id, fiscal_year, monthly_amounts, category, notes)
      values (p_association_id, r.gid, p_fiscal_year, v_amounts, v_section::public.budget_category, r.notes)
      on conflict (association_id, gl_account_id, fiscal_year)
      do update set monthly_amounts = excluded.monthly_amounts, category = excluded.category, notes = excluded.notes, updated_at = now();
      n := n + 1;
      if v_section = 'income' then v_income := v_income + (select sum(a) from unnest(v_amounts) a);
      else v_expense := v_expense + (select sum(a) from unnest(v_amounts) a); end if;
    end if;
  end loop;

  insert into public.audit_logs (portfolio_id, entity_type, entity_id, action, actor_id, actor_email, changes)
  values (v_portfolio, 'association', p_association_id, 'budget_worksheet_saved', auth.uid(),
          (select email from auth.users where id = auth.uid()),
          jsonb_build_object('fiscal_year', p_fiscal_year, 'lines', n, 'income', v_income, 'expense', v_expense));
  return n;
end $$;


ALTER FUNCTION "public"."save_budget_worksheet"("p_association_id" "uuid", "p_fiscal_year" integer, "p_lines" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_credit_card_account"("p_card_id" "uuid", "p_association_id" "uuid", "p_name" "text", "p_issuer" "text", "p_last_four" "text", "p_gl_account_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  v_pid uuid := public.current_portfolio_id();
  v_card public.credit_card_accounts;
  v_id uuid;
begin
  if v_pid is null or not public.can_manage_finance(v_pid) then
    raise exception 'You do not have accounting access' using errcode = '42501';
  end if;
  if p_association_id is not null and not exists (
       select 1 from public.associations a where a.id = p_association_id and a.portfolio_id = v_pid and a.archived_at is null
         and public.can_manage_association(a.id)) then
    raise exception 'Association not found' using errcode = '42501';
  end if;
  if nullif(btrim(coalesce(p_name, '')), '') is null then
    raise exception 'Name the card account' using errcode = '22023';
  end if;
  if nullif(btrim(coalesce(p_last_four, '')), '') is not null and btrim(p_last_four) !~ '^[0-9]{4}$' then
    raise exception 'Enter only the last four digits of the card' using errcode = '22023';
  end if;
  if not exists (select 1 from public.gl_accounts g where g.id = p_gl_account_id and g.portfolio_id = v_pid and coalesce(g.active, true)
                   and g.account_type::text in ('liability', 'accounts_payable')
                   and (g.association_id is null or g.association_id is not distinct from p_association_id)) then
    raise exception 'Choose an active liability account for the card balance (e.g. Credit Card Payable)' using errcode = '22023';
  end if;

  if p_card_id is null then
    insert into public.credit_card_accounts (portfolio_id, association_id, name, issuer, last_four, gl_account_id, created_by)
    values (v_pid, p_association_id, btrim(p_name), nullif(btrim(coalesce(p_issuer, '')), ''),
            nullif(btrim(coalesce(p_last_four, '')), ''), p_gl_account_id, auth.uid())
    returning id into v_id;
    return v_id;
  end if;

  select * into v_card from public.credit_card_accounts where id = p_card_id for update;
  if v_card.id is null or v_card.portfolio_id <> v_pid
     or (v_card.association_id is not null and not public.can_manage_association(v_card.association_id)) then
    raise exception 'Card account not found' using errcode = '42501';
  end if;
  if exists (select 1 from public.credit_card_charges c where c.card_id = v_card.id)
     and (p_gl_account_id is distinct from v_card.gl_account_id or p_association_id is distinct from v_card.association_id) then
    raise exception 'This card has charges — its liability account and association can no longer change' using errcode = '22023';
  end if;
  update public.credit_card_accounts
     set association_id = p_association_id, name = btrim(p_name), issuer = nullif(btrim(coalesce(p_issuer, '')), ''),
         last_four = nullif(btrim(coalesce(p_last_four, '')), ''), gl_account_id = p_gl_account_id, updated_at = now()
   where id = v_card.id;
  return v_card.id;
end $_$;


ALTER FUNCTION "public"."save_credit_card_account"("p_card_id" "uuid", "p_association_id" "uuid", "p_name" "text", "p_issuer" "text", "p_last_four" "text", "p_gl_account_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_delinquency_compliance"("p_association_id" "uuid", "p_pre_referral_notice_days" integer, "p_notice_method" "text", "p_payment_plan_offer_required" boolean, "p_payment_plan_min_months" integer, "p_board_vote_required" boolean, "p_foreclosure_min_balance" numeric, "p_foreclosure_min_months" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_portfolio uuid; v_before jsonb;
begin
  select portfolio_id into v_portfolio from public.associations where id = p_association_id;
  if v_portfolio is null then raise exception 'Association not found'; end if;
  if not (public.can_admin_portfolio(v_portfolio) or public.is_platform_operator()) then
    raise exception 'Only a portfolio administrator may change collection compliance settings';
  end if;
  if p_pre_referral_notice_days is null or p_pre_referral_notice_days not between 0 and 180 then raise exception 'Notice period must be 0–180 days'; end if;
  if p_notice_method not in ('first_class', 'certified_mail') then raise exception 'Invalid notice method'; end if;
  if p_payment_plan_min_months is not null and p_payment_plan_min_months not between 1 and 60 then raise exception 'Payment plan length must be 1–60 months'; end if;
  select to_jsonb(p) into v_before from public.delinquency_policies p where association_id = p_association_id;
  if v_before is null then raise exception 'Initialize the association''s collection policy first'; end if;
  update public.delinquency_policies
     set pre_referral_notice_days = p_pre_referral_notice_days, notice_method = p_notice_method,
         payment_plan_offer_required = coalesce(p_payment_plan_offer_required, false), payment_plan_min_months = p_payment_plan_min_months,
         board_vote_required = coalesce(p_board_vote_required, true), foreclosure_min_balance = p_foreclosure_min_balance,
         foreclosure_min_months = p_foreclosure_min_months, updated_at = now()
   where association_id = p_association_id;
  insert into public.audit_logs (portfolio_id, entity_type, entity_id, action, actor_id, changes)
  values (v_portfolio, 'association', p_association_id, 'delinquency_compliance_updated', auth.uid(),
          jsonb_build_object('before', v_before, 'after', (select to_jsonb(p) from public.delinquency_policies p where association_id = p_association_id)));
end;
$$;


ALTER FUNCTION "public"."save_delinquency_compliance"("p_association_id" "uuid", "p_pre_referral_notice_days" integer, "p_notice_method" "text", "p_payment_plan_offer_required" boolean, "p_payment_plan_min_months" integer, "p_board_vote_required" boolean, "p_foreclosure_min_balance" numeric, "p_foreclosure_min_months" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_house_rule"("p_id" "uuid", "p_association_id" "uuid", "p_rule_number" "text", "p_title" "text", "p_description" "text", "p_action_to_resolve" "text", "p_category" "text", "p_default_violation_type" "public"."violation_type", "p_fine_amount" numeric, "p_active" boolean) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_id uuid; v_existing public.house_rules;
begin
  if not public.can_manage_violations(p_association_id) then raise exception 'Permission denied' using errcode = '42501'; end if;
  if nullif(btrim(coalesce(p_rule_number, '')), '') is null or nullif(btrim(coalesce(p_title, '')), '') is null or nullif(btrim(coalesce(p_description, '')), '') is null then
    raise exception 'Rule number, title, and rule text are required' using errcode = '22023';
  end if;
  if length(p_title) > 200 or length(p_description) > 8000 or length(coalesce(p_action_to_resolve, '')) > 2000 then
    raise exception 'Rule text is too long' using errcode = '22023';
  end if;
  if p_fine_amount is not null and (p_fine_amount < 0 or p_fine_amount > 100000) then
    raise exception 'Default fine must be between 0 and 100,000' using errcode = '22023';
  end if;
  if p_id is not null then
    select * into v_existing from public.house_rules where id = p_id for update;
    if not found or v_existing.association_id <> p_association_id or v_existing.archived_at is not null then
      raise exception 'Rule not found' using errcode = 'P0002';
    end if;
    update public.house_rules
       set rule_number = btrim(p_rule_number), title = btrim(p_title), description = btrim(p_description),
           action_to_resolve = nullif(btrim(coalesce(p_action_to_resolve, '')), ''),
           category = coalesce(nullif(btrim(coalesce(p_category, '')), ''), 'general'),
           default_violation_type = coalesce(p_default_violation_type, 'other'),
           fine_amount = p_fine_amount, active = coalesce(p_active, true), updated_at = now()
     where id = p_id returning id into v_id;
  else
    insert into public.house_rules (association_id, rule_number, title, description, action_to_resolve, category, default_violation_type, fine_amount, active, sort_order)
    values (p_association_id, btrim(p_rule_number), btrim(p_title), btrim(p_description), nullif(btrim(coalesce(p_action_to_resolve, '')), ''),
      coalesce(nullif(btrim(coalesce(p_category, '')), ''), 'general'), coalesce(p_default_violation_type, 'other'), p_fine_amount, coalesce(p_active, true),
      coalesce((select max(sort_order) + 1 from public.house_rules where association_id = p_association_id), 0))
    returning id into v_id;
  end if;
  return v_id;
exception when unique_violation then
  raise exception 'Rule number % is already used in this association', btrim(p_rule_number) using errcode = '23505';
end;
$$;


ALTER FUNCTION "public"."save_house_rule"("p_id" "uuid", "p_association_id" "uuid", "p_rule_number" "text", "p_title" "text", "p_description" "text", "p_action_to_resolve" "text", "p_category" "text", "p_default_violation_type" "public"."violation_type", "p_fine_amount" numeric, "p_active" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_inspection_checklist"("p_inspection_id" "uuid", "p_rows" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_assoc uuid;
  r jsonb;
  v_cond text;
  n integer := 0;
begin
  select i.association_id into v_assoc from public.inspections i where i.id = p_inspection_id and i.archived_at is null;
  if v_assoc is null or not public.can_manage_association(v_assoc) then
    raise exception 'Inspection not found' using errcode = '42501';
  end if;
  if p_rows is null or jsonb_typeof(p_rows) <> 'array' then return 0; end if;
  for r in select * from jsonb_array_elements(p_rows) loop
    v_cond := nullif(r ->> 'condition', '');
    if v_cond is not null and v_cond not in ('good', 'fair', 'poor', 'na') then
      raise exception 'Unknown condition' using errcode = '22023';
    end if;
    update public.inspection_checklist_items
       set condition = v_cond, note = nullif(left(btrim(coalesce(r ->> 'note', '')), 1000), ''), updated_at = now()
     where id = nullif(r ->> 'id', '')::uuid and inspection_id = p_inspection_id
       and (condition is distinct from v_cond or note is distinct from nullif(left(btrim(coalesce(r ->> 'note', '')), 1000), ''));
    if found then n := n + 1; end if;
  end loop;
  return n;
end $$;


ALTER FUNCTION "public"."save_inspection_checklist"("p_inspection_id" "uuid", "p_rows" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_inspection_template"("p_id" "uuid", "p_name" "text", "p_inspection_type" "text", "p_items" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_pid uuid := public.current_portfolio_id();
  v_id uuid := p_id;
  v_items jsonb := public.app_inspection_template_items(p_items);
begin
  if v_pid is null or not public.is_any_staff() or not public.can_access_portfolio(v_pid) then
    raise exception 'Permission denied' using errcode = '42501';
  end if;
  if length(btrim(coalesce(p_name, ''))) = 0 then raise exception 'Name the template' using errcode = '22023'; end if;
  if v_id is null then
    insert into public.inspection_templates (portfolio_id, name, inspection_type, items, created_by)
    values (v_pid, left(btrim(p_name), 200), nullif(left(btrim(coalesce(p_inspection_type, '')), 100), ''), v_items, auth.uid())
    returning id into v_id;
  else
    update public.inspection_templates
       set name = left(btrim(p_name), 200), inspection_type = nullif(left(btrim(coalesce(p_inspection_type, '')), 100), ''),
           items = v_items, updated_at = now()
     where id = v_id and portfolio_id = v_pid and archived_at is null;
    if not found then raise exception 'Template not found' using errcode = 'P0002'; end if;
  end if;
  return v_id;
end $$;


ALTER FUNCTION "public"."save_inspection_template"("p_id" "uuid", "p_name" "text", "p_inspection_type" "text", "p_items" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_project_budget_line"("p_project_id" "uuid", "p_id" "uuid", "p_category" "text", "p_gl_account_id" "uuid", "p_budget_amount" numeric) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  p public.capital_projects;
  v_id uuid := p_id;
begin
  select * into p from public.capital_projects where id = p_project_id and archived_at is null;
  if not found or not public.can_manage_finance(p.portfolio_id) or not public.can_manage_association(p.association_id) then
    raise exception 'Project not found' using errcode = '42501';
  end if;
  if length(btrim(coalesce(p_category, ''))) = 0 then raise exception 'Name the cost category' using errcode = '22023'; end if;
  if p_budget_amount is null or p_budget_amount < 0 then raise exception 'Enter a budget of zero or more' using errcode = '22023'; end if;
  if p_gl_account_id is null or not exists (
    select 1 from public.gl_accounts g
     where g.id = p_gl_account_id and g.portfolio_id = p.portfolio_id and g.active
       and (g.association_id is null or g.association_id = p.association_id)
       and g.account_type::text in ('expense', 'other_expense', 'cost_of_goods_sold', 'fixed_asset', 'asset')) then
    raise exception 'Choose an expense or asset account for this association' using errcode = '22023';
  end if;

  if v_id is null then
    insert into public.capital_project_budget_lines (project_id, category, gl_account_id, budget_amount, sort_order, created_by)
    values (p.id, left(btrim(p_category), 120), p_gl_account_id, round(p_budget_amount, 2),
            coalesce((select max(sort_order) + 1 from public.capital_project_budget_lines where project_id = p.id), 0), auth.uid())
    returning id into v_id;
  else
    update public.capital_project_budget_lines
       set category = left(btrim(p_category), 120), gl_account_id = p_gl_account_id,
           budget_amount = round(p_budget_amount, 2), updated_at = now()
     where id = v_id and project_id = p.id;
    if not found then raise exception 'Budget line not found' using errcode = 'P0002'; end if;
  end if;
  return v_id;
exception when unique_violation then
  raise exception 'This project already has a line for that account' using errcode = '23505';
end $$;


ALTER FUNCTION "public"."save_project_budget_line"("p_project_id" "uuid", "p_id" "uuid", "p_category" "text", "p_gl_account_id" "uuid", "p_budget_amount" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_purchase_order"("p_purchase_order_id" "uuid", "p_portfolio_id" "uuid", "p_association_id" "uuid", "p_vendor_id" "uuid", "p_work_order_id" "uuid", "p_number" "text", "p_description" "text", "p_needed_by" "date", "p_notes" "text", "p_lines" "jsonb", "p_submit" boolean) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  po_row public.purchase_orders;
  po_id uuid;
  line jsonb;
  v_qty numeric;
  v_price numeric;
  v_gl uuid;
  v_desc text;
  v_total numeric := 0;
  v_sort integer := 0;
  board_mode text := 'never';
  board_threshold numeric;
begin
  if p_portfolio_id is null or not public.can_manage_finance(p_portfolio_id)
     or (p_association_id is not null and not public.can_manage_association(p_association_id))
     or (p_purchase_order_id is not null and exists (
           select 1 from public.purchase_orders po
            where po.id = p_purchase_order_id and po.association_id is not null
              and not public.can_manage_association(po.association_id))) then
    raise exception 'Permission denied';
  end if;
  if p_association_id is null or not exists (
    select 1 from public.associations a where a.id = p_association_id and a.portfolio_id = p_portfolio_id and a.archived_at is null
  ) then
    raise exception 'Association is outside your portfolio or archived';
  end if;
  if p_vendor_id is null or not exists (
    select 1 from public.vendors v where v.id = p_vendor_id and v.portfolio_id = p_portfolio_id and v.archived_at is null
  ) then
    raise exception 'Vendor is outside your portfolio or archived';
  end if;
  if p_work_order_id is not null and not exists (
    select 1 from public.work_orders w where w.id = p_work_order_id and w.portfolio_id = p_portfolio_id and w.association_id = p_association_id
  ) then
    raise exception 'Work order does not belong to this association';
  end if;
  if p_lines is null or jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then
    raise exception 'Add at least one line item';
  end if;
  if jsonb_array_length(p_lines) > 100 then
    raise exception 'A purchase order can have at most 100 line items';
  end if;

  if p_purchase_order_id is not null then
    select * into po_row from public.purchase_orders where id = p_purchase_order_id for update;
    if not found or po_row.portfolio_id <> p_portfolio_id then raise exception 'Purchase order not found'; end if;
    if po_row.archived_at is not null or po_row.status = 'cancelled'::public.purchase_order_status then
      raise exception 'Cancelled purchase orders cannot be edited';
    end if;
    if po_row.approval_status not in ('draft', 'rejected') then
      raise exception 'Only draft or rejected purchase orders can be edited';
    end if;
  end if;

  for line in select * from jsonb_array_elements(p_lines) loop
    v_desc := nullif(btrim(coalesce(line ->> 'description', '')), '');
    v_qty := nullif(line ->> 'qty', '')::numeric;
    v_price := nullif(line ->> 'unit_price', '')::numeric;
    v_gl := nullif(line ->> 'gl_account_id', '')::uuid;
    if v_desc is null then raise exception 'Every line item needs a description'; end if;
    if v_qty is null or v_qty <= 0 then raise exception 'Line quantity must be greater than zero'; end if;
    if v_price is null or v_price < 0 then raise exception 'Line unit price cannot be negative'; end if;
    if v_gl is not null and not exists (
      select 1 from public.gl_accounts g
       where g.id = v_gl and g.portfolio_id = p_portfolio_id and g.active
         and (g.association_id is null or g.association_id = p_association_id)
    ) then
      raise exception 'GL account is outside this association or inactive';
    end if;
    v_total := v_total + round(v_qty * v_price, 2);
  end loop;
  if v_total <= 0 then raise exception 'Purchase order total must be greater than zero'; end if;

  select coalesce(s.sends_pos_to_board, 'never'), s.pos_threshold
    into board_mode, board_threshold
    from public.board_approval_settings s
   where s.association_id = p_association_id;
  board_mode := coalesce(board_mode, 'never');

  if p_purchase_order_id is null then
    insert into public.purchase_orders (
      portfolio_id, association_id, vendor_id, work_order_id, number, status,
      po_total, notes, description, needed_by, approval_status, approval_required, created_by
    ) values (
      p_portfolio_id, p_association_id, p_vendor_id, p_work_order_id,
      nullif(btrim(coalesce(p_number, '')), ''), 'open'::public.purchase_order_status,
      v_total, nullif(btrim(coalesce(p_notes, '')), ''), nullif(btrim(coalesce(p_description, '')), ''),
      p_needed_by, 'draft',
      board_mode = 'always' or (board_mode = 'over_threshold' and v_total >= coalesce(board_threshold, 0)),
      auth.uid()
    ) returning id into po_id;
  else
    po_id := p_purchase_order_id;
    update public.purchase_orders
       set association_id = p_association_id,
           vendor_id = p_vendor_id,
           work_order_id = p_work_order_id,
           number = nullif(btrim(coalesce(p_number, '')), ''),
           po_total = v_total,
           notes = nullif(btrim(coalesce(p_notes, '')), ''),
           description = nullif(btrim(coalesce(p_description, '')), ''),
           needed_by = p_needed_by,
           approval_status = 'draft',
           approval_required = board_mode = 'always' or (board_mode = 'over_threshold' and v_total >= coalesce(board_threshold, 0)),
           approval_request_id = null,
           submitted_at = null,
           decided_at = null,
           updated_at = now()
     where id = po_id;
    delete from public.purchase_order_line_items where purchase_order_id = po_id;
  end if;

  for line in select * from jsonb_array_elements(p_lines) loop
    v_sort := v_sort + 1;
    v_qty := (line ->> 'qty')::numeric;
    v_price := (line ->> 'unit_price')::numeric;
    insert into public.purchase_order_line_items (
      purchase_order_id, description, qty, unit_price, gl_account_id, sort_order
    ) values (
      po_id, btrim(line ->> 'description'), v_qty, v_price,
      nullif(line ->> 'gl_account_id', '')::uuid, v_sort
    );
  end loop;

  if coalesce(p_submit, false) then
    perform public.submit_purchase_order(po_id);
  end if;
  return po_id;
end;
$$;


ALTER FUNCTION "public"."save_purchase_order"("p_purchase_order_id" "uuid", "p_portfolio_id" "uuid", "p_association_id" "uuid", "p_vendor_id" "uuid", "p_work_order_id" "uuid", "p_number" "text", "p_description" "text", "p_needed_by" "date", "p_notes" "text", "p_lines" "jsonb", "p_submit" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_recurring_bill"("p_id" "uuid", "p_vendor_id" "uuid", "p_association_id" "uuid", "p_gl_account_id" "uuid", "p_bank_account_id" "uuid", "p_name" "text", "p_memo" "text", "p_amount" numeric, "p_frequency" "text", "p_interval" integer, "p_start_date" "date", "p_end_date" "date", "p_due_days" integer, "p_active" boolean) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_pid uuid := public.current_portfolio_id();
  v_id uuid := p_id;
  v_existing record;
begin
  if v_pid is null or not public.can_manage_finance(v_pid) then
    raise exception 'Permission denied' using errcode = '42501';
  end if;
  if length(btrim(coalesce(p_name, ''))) = 0 then raise exception 'Name the recurring bill' using errcode = '22023'; end if;
  if p_amount is null or p_amount <= 0 then raise exception 'Amount must be greater than zero' using errcode = '22023'; end if;
  if p_frequency not in ('daily', 'weekly', 'monthly', 'quarterly', 'annually') then raise exception 'Choose a frequency' using errcode = '22023'; end if;
  if p_start_date is null then raise exception 'Choose a start date' using errcode = '22023'; end if;
  if p_end_date is not null and p_end_date < p_start_date then raise exception 'End date is before the start date' using errcode = '22023'; end if;
  if not exists (select 1 from public.vendors v where v.id = p_vendor_id and v.portfolio_id = v_pid and v.archived_at is null) then
    raise exception 'Vendor not found' using errcode = 'P0002';
  end if;
  if p_association_id is null or not public.can_manage_association(p_association_id) then
    raise exception 'Choose an association' using errcode = '22023';
  end if;
  if p_gl_account_id is null or not exists (select 1 from public.gl_accounts g where g.id = p_gl_account_id and g.portfolio_id = v_pid and g.active
             and (g.association_id is null or g.association_id = p_association_id)) then
    raise exception 'Choose an expense GL account for this association' using errcode = '22023';
  end if;
  if p_bank_account_id is not null and not exists (select 1 from public.bank_accounts b where b.id = p_bank_account_id and b.portfolio_id = v_pid
             and b.archived_at is null and (b.association_id is null or b.association_id = p_association_id)) then
    raise exception 'Bank account does not belong to this association' using errcode = '22023';
  end if;

  if v_id is null then
    insert into public.recurring_bills (portfolio_id, vendor_id, association_id, gl_account_id, bank_account_id,
      name, memo, amount, frequency, interval_count, start_date, end_date, next_post_date, due_days,
      auto_generate, is_auto_pay, created_by)
    values (v_pid, p_vendor_id, p_association_id, p_gl_account_id, p_bank_account_id,
      btrim(p_name), nullif(btrim(coalesce(p_memo, '')), ''), p_amount, p_frequency::public.recurring_frequency,
      greatest(coalesce(p_interval, 1), 1), p_start_date, p_end_date, p_start_date, coalesce(p_due_days, 0),
      coalesce(p_active, true), false, auth.uid())
    returning id into v_id;
  else
    select * into v_existing from public.recurring_bills where id = v_id and portfolio_id = v_pid and archived_at is null for update;
    if not found then raise exception 'Recurring bill not found' using errcode = 'P0002'; end if;
    if not public.can_view_association_row(v_existing.association_id) then raise exception 'Recurring bill not found' using errcode = 'P0002'; end if;
    update public.recurring_bills set
      vendor_id = p_vendor_id, association_id = p_association_id, gl_account_id = p_gl_account_id,
      bank_account_id = p_bank_account_id, name = btrim(p_name), memo = nullif(btrim(coalesce(p_memo, '')), ''),
      amount = p_amount, frequency = p_frequency::public.recurring_frequency,
      interval_count = greatest(coalesce(p_interval, 1), 1), start_date = p_start_date, end_date = p_end_date,
      next_post_date = case when p_start_date > coalesce(v_existing.next_post_date, p_start_date) then p_start_date
                            else coalesce(v_existing.next_post_date, p_start_date) end,
      due_days = coalesce(p_due_days, 0), auto_generate = coalesce(p_active, true), last_error = null, updated_at = now()
    where id = v_id;
  end if;
  insert into public.audit_logs (portfolio_id, entity_type, entity_id, action, actor_id, actor_email, changes)
  values (v_pid, 'recurring_bill', v_id, case when p_id is null then 'created' else 'updated' end, auth.uid(),
          (select email from auth.users where id = auth.uid()),
          jsonb_build_object('name', btrim(p_name), 'amount', p_amount, 'frequency', p_frequency, 'active', coalesce(p_active, true)));
  return v_id;
end $$;


ALTER FUNCTION "public"."save_recurring_bill"("p_id" "uuid", "p_vendor_id" "uuid", "p_association_id" "uuid", "p_gl_account_id" "uuid", "p_bank_account_id" "uuid", "p_name" "text", "p_memo" "text", "p_amount" numeric, "p_frequency" "text", "p_interval" integer, "p_start_date" "date", "p_end_date" "date", "p_due_days" integer, "p_active" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_recurring_journal_entry"("p_id" "uuid", "p_name" "text", "p_memo" "text", "p_frequency" "text", "p_interval" integer, "p_next_date" "date", "p_lines" "jsonb", "p_active" boolean) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_pid uuid := public.current_portfolio_id();
  v_id uuid := p_id;
  v_debits numeric; v_credits numeric; v_count int;
begin
  if v_pid is null or not public.can_manage_finance(v_pid) then raise exception 'Permission denied' using errcode = '42501'; end if;
  if length(btrim(coalesce(p_name, ''))) = 0 then raise exception 'Name the recurring entry' using errcode = '22023'; end if;
  if p_frequency not in ('daily', 'weekly', 'monthly', 'quarterly', 'annually') then raise exception 'Choose a frequency' using errcode = '22023'; end if;
  if p_next_date is null then raise exception 'Choose the first posting date' using errcode = '22023'; end if;
  if jsonb_typeof(p_lines) <> 'array' then raise exception 'Add journal lines' using errcode = '22023'; end if;

  select count(*), coalesce(sum(coalesce((l->>'debit')::numeric, 0)), 0), coalesce(sum(coalesce((l->>'credit')::numeric, 0)), 0)
    into v_count, v_debits, v_credits from jsonb_array_elements(p_lines) l;
  if v_count < 2 then raise exception 'A journal entry needs at least two lines' using errcode = '22023'; end if;
  if v_debits <= 0 or v_debits <> v_credits then
    raise exception 'Debits (%) must equal credits (%)', v_debits, v_credits using errcode = '22023';
  end if;
  if exists (select 1 from jsonb_array_elements(p_lines) l
              where (coalesce((l->>'debit')::numeric, 0) < 0 or coalesce((l->>'credit')::numeric, 0) < 0)
                 or ((coalesce((l->>'debit')::numeric, 0) > 0) = (coalesce((l->>'credit')::numeric, 0) > 0))
                 or (nullif(l->>'association_id', '') is not null and not public.can_manage_association((l->>'association_id')::uuid))
                 or not exists (select 1 from public.gl_accounts g
                                 where g.id = (l->>'gl_account_id')::uuid and g.portfolio_id = v_pid and g.active
                                   and (g.association_id is null or g.association_id = nullif(l->>'association_id', '')::uuid))) then
    raise exception 'Each line needs one of debit or credit and an active GL account that belongs to the line''s association' using errcode = '22023';
  end if;

  if v_id is null then
    insert into public.recurring_journal_entries (portfolio_id, name, memo, frequency, interval_count, next_post_date,
                                                  auto_generate, template_lines, created_by)
    values (v_pid, btrim(p_name), nullif(btrim(coalesce(p_memo, '')), ''), p_frequency::public.recurring_frequency,
            greatest(coalesce(p_interval, 1), 1), p_next_date, coalesce(p_active, true), p_lines, auth.uid())
    returning id into v_id;
  else
    update public.recurring_journal_entries set name = btrim(p_name), memo = nullif(btrim(coalesce(p_memo, '')), ''),
      frequency = p_frequency::public.recurring_frequency, interval_count = greatest(coalesce(p_interval, 1), 1),
      next_post_date = p_next_date, auto_generate = coalesce(p_active, true), template_lines = p_lines,
      last_error = null, updated_at = now()
     where id = v_id and portfolio_id = v_pid and archived_at is null and public.app_recurring_je_in_scope(template_lines);
    if not found then raise exception 'Recurring entry not found' using errcode = 'P0002'; end if;
  end if;
  return v_id;
end $$;


ALTER FUNCTION "public"."save_recurring_journal_entry"("p_id" "uuid", "p_name" "text", "p_memo" "text", "p_frequency" "text", "p_interval" integer, "p_next_date" "date", "p_lines" "jsonb", "p_active" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_recurring_journal_entry"("p_id" "uuid", "p_name" "text", "p_memo" "text", "p_frequency" "text", "p_interval" integer, "p_next_date" "date", "p_lines" "jsonb", "p_active" boolean, "p_end_date" "date") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_pid uuid := public.current_portfolio_id();
  v_id uuid := p_id;
  v_lines jsonb;
begin
  if v_pid is null or not public.can_manage_finance(v_pid) then raise exception 'Permission denied' using errcode = '42501'; end if;
  if length(btrim(coalesce(p_name, ''))) = 0 then raise exception 'Name the recurring entry' using errcode = '22023'; end if;
  if p_frequency not in ('daily', 'weekly', 'monthly', 'quarterly', 'annually') then raise exception 'Choose a frequency' using errcode = '22023'; end if;
  if p_next_date is null then raise exception 'Choose the next posting date' using errcode = '22023'; end if;
  if p_end_date is not null and p_end_date < p_next_date then raise exception 'The end date is before the next posting date' using errcode = '22023'; end if;
  v_lines := public.app_normalize_je_lines(v_pid, p_lines, true);

  if v_id is null then
    insert into public.recurring_journal_entries (portfolio_id, name, memo, frequency, interval_count, next_post_date, end_date,
                                                  auto_generate, template_lines, created_by)
    values (v_pid, btrim(p_name), nullif(btrim(coalesce(p_memo, '')), ''), p_frequency::public.recurring_frequency,
            greatest(coalesce(p_interval, 1), 1), p_next_date, p_end_date, coalesce(p_active, true), v_lines, auth.uid())
    returning id into v_id;
  else
    update public.recurring_journal_entries set name = btrim(p_name), memo = nullif(btrim(coalesce(p_memo, '')), ''),
      frequency = p_frequency::public.recurring_frequency, interval_count = greatest(coalesce(p_interval, 1), 1),
      next_post_date = p_next_date, end_date = p_end_date, auto_generate = coalesce(p_active, true), template_lines = v_lines,
      last_error = null, updated_at = now()
     where id = v_id and portfolio_id = v_pid and archived_at is null and public.app_recurring_je_in_scope(template_lines);
    if not found then raise exception 'Recurring entry not found' using errcode = 'P0002'; end if;
  end if;
  return v_id;
end $$;


ALTER FUNCTION "public"."save_recurring_journal_entry"("p_id" "uuid", "p_name" "text", "p_memo" "text", "p_frequency" "text", "p_interval" integer, "p_next_date" "date", "p_lines" "jsonb", "p_active" boolean, "p_end_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_recurring_purchase_order"("p_source_po_id" "uuid", "p_name" "text", "p_frequency" "text", "p_interval" integer, "p_start_date" "date", "p_end_date" "date", "p_needed_by_days" integer) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  po public.purchase_orders;
  v_lines jsonb;
  v_id uuid;
  v_notes text;
begin
  select * into po from public.purchase_orders where id = p_source_po_id;
  if not found or not public.can_manage_finance(po.portfolio_id) or not public.can_manage_association(po.association_id) then
    raise exception 'Purchase order not found' using errcode = '42501';
  end if;
  if po.vendor_id is null then raise exception 'The purchase order has no vendor' using errcode = '22023'; end if;
  if length(btrim(coalesce(p_name, ''))) = 0 then raise exception 'Name the recurring purchase order' using errcode = '22023'; end if;
  if p_frequency not in ('weekly', 'monthly', 'quarterly', 'annually') then raise exception 'Choose how often it repeats' using errcode = '22023'; end if;
  if p_start_date is null then raise exception 'Choose the first date' using errcode = '22023'; end if;
  if p_end_date is not null and p_end_date < p_start_date then raise exception 'End date is before the first date' using errcode = '22023'; end if;
  if coalesce(p_needed_by_days, 0) not between 0 and 365 then raise exception 'Needed-by days must be 0 to 365' using errcode = '22023'; end if;

  select jsonb_agg(jsonb_build_object('description', l.description, 'qty', l.qty, 'unit_price', l.unit_price,
                                      'gl_account_id', l.gl_account_id) order by l.sort_order)
    into v_lines
    from public.purchase_order_line_items l where l.purchase_order_id = po.id;
  if v_lines is null then raise exception 'The purchase order has no line items' using errcode = '22023'; end if;

  v_notes := coalesce((select pp.notes from public.purchase_order_private pp where pp.purchase_order_id = po.id), po.notes);

  insert into public.recurring_purchase_orders (
    portfolio_id, association_id, vendor_id, name, description, notes, lines, frequency, interval_count,
    start_date, end_date, next_post_date, needed_by_days, source_purchase_order_id, created_by)
  values (
    po.portfolio_id, po.association_id, po.vendor_id, btrim(p_name), po.description, v_notes, v_lines,
    p_frequency::public.recurring_frequency, least(greatest(coalesce(p_interval, 1), 1), 60),
    p_start_date, p_end_date, p_start_date, coalesce(p_needed_by_days, 0), po.id, auth.uid())
  returning id into v_id;

  insert into public.audit_logs (portfolio_id, entity_type, entity_id, action, actor_id, changes)
  values (po.portfolio_id, 'recurring_purchase_order', v_id, 'created', auth.uid(),
          jsonb_build_object('name', btrim(p_name), 'frequency', p_frequency, 'source_purchase_order_id', po.id));
  return v_id;
end $$;


ALTER FUNCTION "public"."save_recurring_purchase_order"("p_source_po_id" "uuid", "p_name" "text", "p_frequency" "text", "p_interval" integer, "p_start_date" "date", "p_end_date" "date", "p_needed_by_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_violation_schedule"("p_association_id" "uuid", "p_house_rule_id" "uuid", "p_steps" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare step jsonb; n integer := 0; v_fee numeric; v_days integer; v_gl uuid; v_tpl uuid; v_portfolio uuid; v_methods text[];
begin
  if not public.can_manage_violations(p_association_id) then raise exception 'Permission denied' using errcode = '42501'; end if;
  select portfolio_id into v_portfolio from public.associations where id = p_association_id;
  if p_house_rule_id is not null and not exists (select 1 from public.house_rules where id = p_house_rule_id and association_id = p_association_id and archived_at is null) then
    raise exception 'Rule not found' using errcode = 'P0002';
  end if;
  if p_steps is null or jsonb_typeof(p_steps) <> 'array' then raise exception 'Steps must be a list' using errcode = '22023'; end if;
  if jsonb_array_length(p_steps) > 12 then raise exception 'A schedule can have at most 12 steps' using errcode = '22023'; end if;
  if p_house_rule_id is null and jsonb_array_length(p_steps) = 0 then raise exception 'The association default schedule needs at least one step' using errcode = '22023'; end if;
  update public.violation_followup_steps set archived_at = now(), updated_at = now()
   where association_id = p_association_id and house_rule_id is not distinct from p_house_rule_id and archived_at is null;
  for step in select * from jsonb_array_elements(p_steps) loop
    n := n + 1;
    v_days := coalesce(nullif(step ->> 'days_after_previous', '')::integer, 0);
    v_fee := coalesce(nullif(step ->> 'fee', '')::numeric, 0);
    v_gl := nullif(step ->> 'gl_account_id', '')::uuid;
    v_tpl := nullif(step ->> 'letter_template_id', '')::uuid;
    if nullif(btrim(coalesce(step ->> 'follow_up_name', '')), '') is null then raise exception 'Every step needs a name' using errcode = '22023'; end if;
    if v_days < 0 or v_days > 365 then raise exception 'Days must be between 0 and 365' using errcode = '22023'; end if;
    if v_fee < 0 or v_fee > 100000 then raise exception 'Fine must be between 0 and 100,000' using errcode = '22023'; end if;
    if v_gl is not null and not exists (select 1 from public.gl_accounts g where g.id = v_gl and g.portfolio_id = v_portfolio and g.active and (g.association_id is null or g.association_id = p_association_id)) then
      raise exception 'GL account is outside this association' using errcode = '42501';
    end if;
    if v_tpl is not null and not exists (select 1 from public.document_templates t where t.id = v_tpl and t.portfolio_id = v_portfolio and t.archived_at is null) then
      raise exception 'Letter template is outside this portfolio' using errcode = '42501';
    end if;
    select coalesce(array_agg(m), '{}'::text[]) into v_methods
      from jsonb_array_elements_text(coalesce(step -> 'delivery_methods', '[]'::jsonb)) as m where m in ('email', 'portal', 'mail', 'certified_mail');
    insert into public.violation_followup_steps (association_id, house_rule_id, step_order, days_after_previous, follow_up_name, letter_template_id, delivery_methods, fee, gl_account_id, offers_hearing)
    values (p_association_id, p_house_rule_id, n, v_days, left(btrim(step ->> 'follow_up_name'), 120), v_tpl, v_methods, v_fee, v_gl, coalesce((step ->> 'offers_hearing')::boolean, false));
  end loop;
  if p_house_rule_id is not null then
    update public.house_rules set custom_schedule = (n > 0), updated_at = now() where id = p_house_rule_id;
  end if;
  return n;
end;
$$;


ALTER FUNCTION "public"."save_violation_schedule"("p_association_id" "uuid", "p_house_rule_id" "uuid", "p_steps" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_violation_settings"("p_association_id" "uuid", "p_hearing_required_before_fine" boolean, "p_hearing_request_days" integer, "p_default_cure_days" integer, "p_fine_charge_category_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_portfolio uuid;
begin
  if not public.can_manage_violations(p_association_id) then raise exception 'Permission denied' using errcode = '42501'; end if;
  select portfolio_id into v_portfolio from public.associations where id = p_association_id;
  if p_fine_charge_category_id is not null and not exists (select 1 from public.charge_categories c where c.id = p_fine_charge_category_id and c.portfolio_id = v_portfolio and c.active) then
    raise exception 'Charge category is outside this portfolio' using errcode = '42501';
  end if;
  if p_hearing_request_days not between 0 and 90 or p_default_cure_days not between 0 and 365 then raise exception 'Days are out of range' using errcode = '22023'; end if;
  insert into public.association_violation_settings (association_id, hearing_required_before_fine, hearing_request_days, default_cure_days, fine_charge_category_id, updated_at, updated_by)
  values (p_association_id, coalesce(p_hearing_required_before_fine, true), p_hearing_request_days, p_default_cure_days, p_fine_charge_category_id, now(), auth.uid())
  on conflict (association_id) do update
     set hearing_required_before_fine = excluded.hearing_required_before_fine, hearing_request_days = excluded.hearing_request_days,
         default_cure_days = excluded.default_cure_days, fine_charge_category_id = excluded.fine_charge_category_id, updated_at = now(), updated_by = auth.uid();
  insert into public.audit_logs (portfolio_id, entity_type, entity_id, action, actor_id, actor_email, changes)
  values (v_portfolio, 'association', p_association_id, 'violation_settings_updated', auth.uid(), (select email from auth.users where id = auth.uid()),
          jsonb_build_object('hearing_required_before_fine', p_hearing_required_before_fine, 'hearing_request_days', p_hearing_request_days, 'default_cure_days', p_default_cure_days));
end;
$$;


ALTER FUNCTION "public"."save_violation_settings"("p_association_id" "uuid", "p_hearing_required_before_fine" boolean, "p_hearing_request_days" integer, "p_default_cure_days" integer, "p_fine_charge_category_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."scan_data_diagnostics"("p_portfolio_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
begin
  insert into public.data_diagnostics (portfolio_id, category, entity_type, entity_id, severity, title)
  select distinct p_portfolio_id, 'invalid_phone', 'owner', o.id, 'warning'::public.diagnostic_severity,
         'Owner ' || coalesce(o.full_name,'<unknown>') || ' has unparseable phone: ' || o.phone
    from public.owners o
   where o.portfolio_id = p_portfolio_id
     and o.phone is not null
     and o.phone !~ '^\+?[0-9 ().-]{10,20}$'
     and o.archived_at is null
  on conflict (portfolio_id, category, (coalesce(entity_id, '00000000-0000-0000-0000-000000000000'::uuid)), title) where resolved_at is null
  do update set last_seen_at = now(), occurrence_count = public.data_diagnostics.occurrence_count + 1;

  insert into public.data_diagnostics (portfolio_id, category, entity_type, entity_id, severity, title)
  select distinct p_portfolio_id, 'missing_email', 'owner', o.id, 'warning'::public.diagnostic_severity,
         'Owner ' || coalesce(o.full_name,'<unknown>') || ' prefers email but email is missing'
    from public.owners o
   where o.portfolio_id = p_portfolio_id
     and o.preferred_comm = 'email'
     and (o.email is null or o.email = '')
     and o.archived_at is null
  on conflict (portfolio_id, category, (coalesce(entity_id, '00000000-0000-0000-0000-000000000000'::uuid)), title) where resolved_at is null
  do update set last_seen_at = now(), occurrence_count = public.data_diagnostics.occurrence_count + 1;

  insert into public.data_diagnostics (portfolio_id, category, entity_type, entity_id, severity, title)
  select distinct p_portfolio_id, 'missing_taxpayer_id', 'vendor', v.id, 'error'::public.diagnostic_severity,
         'Vendor ' || v.name || ' has send_1099=true but no taxpayer_id'
    from public.vendors v
   where v.portfolio_id = p_portfolio_id
     and v.send_1099 = true
     and not v.has_taxpayer_id
     and v.archived_at is null
  on conflict (portfolio_id, category, (coalesce(entity_id, '00000000-0000-0000-0000-000000000000'::uuid)), title) where resolved_at is null
  do update set last_seen_at = now(), occurrence_count = public.data_diagnostics.occurrence_count + 1;

  insert into public.data_diagnostics (portfolio_id, category, entity_type, entity_id, severity, title)
  select distinct p_portfolio_id, 'vendor_compliance_expired', 'vendor', v.id, 'error'::public.diagnostic_severity,
         'Vendor ' || v.name || ' has expired compliance documents'
    from public.vendors v
    join public.vendor_compliance vc on vc.vendor_id = v.id
   where v.portfolio_id = p_portfolio_id
     and v.archived_at is null
     and (vc.workers_comp_expiration < current_date
          or vc.general_liability_expiration < current_date
          or vc.auto_insurance_expiration < current_date)
  on conflict (portfolio_id, category, (coalesce(entity_id, '00000000-0000-0000-0000-000000000000'::uuid)), title) where resolved_at is null
  do update set last_seen_at = now(), occurrence_count = public.data_diagnostics.occurrence_count + 1;

  insert into public.data_diagnostics (portfolio_id, category, entity_type, entity_id, severity, title)
  select distinct p_portfolio_id, 'unit_no_current_occupancy', 'unit', u.id, 'info'::public.diagnostic_severity,
         'Unit ' || u.unit_number || ' has no current occupancy record'
    from public.units u
    join public.buildings b on b.id = u.building_id
    join public.associations a on a.id = b.association_id
   where a.portfolio_id = p_portfolio_id
     and u.archived_at is null
     and not exists (select 1 from public.occupancies occ
                      where occ.unit_id = u.id and occ.status = 'current')
  on conflict (portfolio_id, category, (coalesce(entity_id, '00000000-0000-0000-0000-000000000000'::uuid)), title) where resolved_at is null
  do update set last_seen_at = now(), occurrence_count = public.data_diagnostics.occurrence_count + 1;

  update public.data_diagnostics d
     set resolved_at = now()
   where d.portfolio_id = p_portfolio_id
     and d.resolved_at is null
     and d.category in ('invalid_phone', 'missing_email', 'missing_taxpayer_id',
                        'vendor_compliance_expired', 'unit_no_current_occupancy')
     and d.last_seen_at < now();

  return (select count(*) from public.data_diagnostics
          where portfolio_id = p_portfolio_id and resolved_at is null);
end;
$_$;


ALTER FUNCTION "public"."scan_data_diagnostics"("p_portfolio_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."scan_financial_diagnostics"("p_portfolio_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare n integer := 0; m integer := 0;
begin
  insert into public.data_diagnostics (portfolio_id, category, entity_type, entity_id, severity, title, details)
  select distinct p_portfolio_id, 'reconciliation_lapsed', 'bank_account', ba.id, 'error'::public.diagnostic_severity,
         'Bank account ' || ba.name || ' has not been reconciled in over 60 days',
         'Last reconciled: ' || coalesce(ba.last_reconciliation_date::text, 'never') || ' ('
           || (current_date - coalesce(ba.last_reconciliation_date, ba.created_at::date))::text || ' days ago).'
    from public.bank_accounts ba
   where ba.portfolio_id = p_portfolio_id
     and ba.archived_at is null
     and (ba.last_reconciliation_date is null or ba.last_reconciliation_date < current_date - interval '60 days')
  on conflict (portfolio_id, category, (coalesce(entity_id, '00000000-0000-0000-0000-000000000000'::uuid)), title) where resolved_at is null
  do update set details = excluded.details,
                last_seen_at = now(),
                occurrence_count = public.data_diagnostics.occurrence_count + 1;

  insert into public.data_diagnostics (portfolio_id, category, entity_type, entity_id, severity, title)
  select distinct p_portfolio_id, 'unused_prepayment', 'unit', u.id, 'info'::public.diagnostic_severity,
         'Unit ' || u.unit_number || ' has credit balance of ' || to_char(-ub.balance, 'FM$999,999.00')
    from public.unit_balances ub
    join public.units u on u.id = ub.unit_id
    join public.buildings b on b.id = u.building_id
    join public.associations a on a.id = b.association_id
   where a.portfolio_id = p_portfolio_id and ub.balance < -0.01
  on conflict (portfolio_id, category, (coalesce(entity_id, '00000000-0000-0000-0000-000000000000'::uuid)), title) where resolved_at is null
  do update set last_seen_at = now(), occurrence_count = public.data_diagnostics.occurrence_count + 1;
  perform public.app_scan_unapplied_credits(p_portfolio_id);

  insert into public.data_diagnostics (portfolio_id, category, entity_type, entity_id, severity, title)
  select distinct p_portfolio_id, 'vendor_insurance_expiring', 'vendor', v.id, 'warning'::public.diagnostic_severity,
         'Vendor ' || v.name || ' has insurance expiring within 30 days'
    from public.vendors v
    join public.vendor_compliance vc on vc.vendor_id = v.id
   where v.portfolio_id = p_portfolio_id and v.archived_at is null
     and ((vc.workers_comp_expiration between current_date and current_date + interval '30 days')
          or (vc.general_liability_expiration between current_date and current_date + interval '30 days')
          or (vc.auto_insurance_expiration between current_date and current_date + interval '30 days'))
  on conflict (portfolio_id, category, (coalesce(entity_id, '00000000-0000-0000-0000-000000000000'::uuid)), title) where resolved_at is null
  do update set last_seen_at = now(), occurrence_count = public.data_diagnostics.occurrence_count + 1;
  get diagnostics n = row_count;

  insert into public.data_diagnostics (portfolio_id, category, entity_type, entity_id, severity, title, details)
  select distinct p_portfolio_id, 'receivable_not_posted', 'association', a.id, 'error'::public.diagnostic_severity,
         a.name || ': owner charges or payments are missing from the general ledger',
         x.n || ' charge(s)/payment(s) have no journal entry. Run backfill_receivables_to_gl for this association after review.'
    from public.associations a
    join lateral (
      select (select count(*) from public.charges c
                where public.unit_association_id(c.unit_id) = a.id
                  and not exists (select 1 from public.journal_entries je where je.source_type = 'charge' and je.source_id = c.id))
           + (select count(*) from public.payments p
                where public.unit_association_id(p.unit_id) = a.id
                  and not exists (select 1 from public.journal_entries je where je.source_type = 'payment' and je.source_id = p.id)) as n
    ) x on true
   where a.portfolio_id = p_portfolio_id and a.archived_at is null and x.n > 0
  on conflict (portfolio_id, category, (coalesce(entity_id, '00000000-0000-0000-0000-000000000000'::uuid)), title) where resolved_at is null
  do update set details = excluded.details, last_seen_at = now(), occurrence_count = public.data_diagnostics.occurrence_count + 1;
  get diagnostics m = row_count; n := n + m;

  insert into public.data_diagnostics (portfolio_id, category, entity_type, entity_id, severity, title, details)
  select distinct p_portfolio_id, 'receivables_gl_mismatch', 'association', a.id, 'warning'::public.diagnostic_severity,
         a.name || ': GL accounts receivable does not match owner balances',
         'GL accounts receivable ' || to_char(x.gl, 'FM$999,999,990.00') || ' vs owner balances ' || to_char(x.sub, 'FM$999,999,990.00')
           || ' (difference ' || to_char(x.gl - x.sub, 'FM$999,999,990.00') || '). Look for manual journal entries to A/R.'
    from public.associations a
    join lateral (
      select coalesce((select sum(jl.debit_amount - jl.credit_amount)
                         from public.journal_lines jl
                         join public.journal_entries je on je.id = jl.entry_id and je.posted
                         join public.gl_accounts g on g.id = jl.gl_account_id and g.account_type::text = 'accounts_receivable' and g.name not ilike '%allowance%'
                        where jl.association_id = a.id), 0) as gl,
             coalesce((select sum(c.amount) from public.charges c where public.unit_association_id(c.unit_id) = a.id), 0)
           - coalesce((select sum(p.amount) from public.payments p where public.unit_association_id(p.unit_id) = a.id), 0) as sub
    ) x on true
   where a.portfolio_id = p_portfolio_id and a.archived_at is null and abs(x.gl - x.sub) > 0.01
  on conflict (portfolio_id, category, (coalesce(entity_id, '00000000-0000-0000-0000-000000000000'::uuid)), title) where resolved_at is null
  do update set details = excluded.details, last_seen_at = now(), occurrence_count = public.data_diagnostics.occurrence_count + 1;
  get diagnostics m = row_count; n := n + m;

  update public.data_diagnostics d
     set resolved_at = now()
   where d.portfolio_id = p_portfolio_id
     and d.resolved_at is null
     and d.category in ('reconciliation_lapsed', 'unused_prepayment', 'vendor_insurance_expiring',
                        'receivable_not_posted', 'receivables_gl_mismatch')
     and d.last_seen_at < now();

  return n;
end $_$;


ALTER FUNCTION "public"."scan_financial_diagnostics"("p_portfolio_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."schedule_owner_dues"("p_occupancy_id" "uuid", "p_start" "date" DEFAULT CURRENT_DATE) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_occ record;
  v_cat uuid;
  v_n integer;
  v_cats uuid[];
  v_first date;
  v_amount numeric;
  v_freq public.recurring_frequency;
  v_keep uuid;
  v_id uuid;
  v_today date;
begin
  if auth.uid() is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;

  select o.unit_id, o.dues_amount, o.dues_frequency, o.occupancy_type, o.status,
         b.association_id, a.portfolio_id, a.timezone
    into v_occ
    from public.occupancies o
    join public.units u on u.id = o.unit_id
    join public.buildings b on b.id = u.building_id
    join public.associations a on a.id = b.association_id
   where o.id = p_occupancy_id;
  if not found then
    raise exception 'Occupancy not found' using errcode = 'P0002';
  end if;

  if not (public.is_platform_operator()
          or (public.is_any_staff() and public.can_manage_association(v_occ.association_id))) then
    raise exception 'Not authorized for this association' using errcode = '42501';
  end if;

  if v_occ.occupancy_type <> 'owner' or v_occ.status = 'past' then
    return null;
  end if;

  select array_agg(cc.id order by (cc.association_id is not null) desc, cc.created_at, cc.id) into v_cats
    from public.charge_categories cc
   where cc.portfolio_id = v_occ.portfolio_id and cc.active and cc.charge_type = 'assessment'
     and (cc.association_id = v_occ.association_id or cc.association_id is null)
     and upper(coalesce(cc.code, '')) = 'DUES';
  if v_cats is not null then
    v_cat := v_cats[1];
  else
    select count(*), min(cc.id::text)::uuid into v_n, v_cat
      from public.charge_categories cc
     where cc.portfolio_id = v_occ.portfolio_id and cc.active and cc.charge_type = 'assessment'
       and (cc.association_id = v_occ.association_id or cc.association_id is null);
    if v_n <> 1 and coalesce(v_occ.dues_amount, 0) <= 0 then
      return null;
    elsif v_n = 0 then
      raise exception 'No active assessment charge category exists, so monthly dues were not scheduled' using errcode = '23514';
    elsif v_n > 1 then
      raise exception 'Several assessment charge categories exist and none has code DUES, so monthly dues were not scheduled' using errcode = '23514';
    end if;
    v_cats := array[v_cat];
  end if;

  perform 1 from public.units where id = v_occ.unit_id for update;

  select o.unit_id, o.dues_amount, o.dues_frequency, o.occupancy_type, o.status,
         b.association_id, a.portfolio_id, a.timezone
    into v_occ
    from public.occupancies o
    join public.units u on u.id = o.unit_id
    join public.buildings b on b.id = u.building_id
    join public.associations a on a.id = b.association_id
   where o.id = p_occupancy_id;
  if not found or v_occ.status = 'past' then
    return null;
  end if;

  v_amount := round(coalesce(v_occ.dues_amount, 0), 2);
  v_freq := coalesce(v_occ.dues_frequency, 'monthly'::public.recurring_frequency);
  v_today := (now() at time zone coalesce(nullif(v_occ.timezone, ''), 'America/Chicago'))::date;
  v_first := greatest(coalesce(p_start, v_today), v_today);
  if extract(day from v_first) <> 1 then
    v_first := (date_trunc('month', v_first) + interval '1 month')::date;
  end if;

  if exists (select 1 from public.charges c
              where c.unit_id = v_occ.unit_id and c.charge_category_id = any(v_cats)
                and c.due_date = v_first and c.amount <> 0) then
    v_first := (v_first + interval '1 month')::date;
  end if;

  update public.unit_recurring_charges urc
     set active = false, updated_at = now()
   where urc.unit_id = v_occ.unit_id and urc.active and urc.charge_category_id = any(v_cats)
     and urc.last_posted_at is null and urc.next_post_date < v_first;

  select urc.id into v_keep
    from public.unit_recurring_charges urc
   where urc.unit_id = v_occ.unit_id and urc.active and urc.charge_category_id = any(v_cats)
     and urc.amount = v_amount and urc.frequency = v_freq
     and coalesce(urc.start_date, urc.next_post_date) <= v_first
     and extract(day from urc.next_post_date) = 1
     and urc.end_date is null
   order by (urc.last_posted_at is not null) desc, urc.created_at desc
   limit 1;
  if v_keep is not null then
    update public.unit_recurring_charges urc
       set active = false, updated_at = now()
     where urc.unit_id = v_occ.unit_id and urc.active and urc.charge_category_id = any(v_cats)
       and urc.id <> v_keep
       and coalesce(urc.start_date, urc.next_post_date) >= v_first;
    update public.unit_recurring_charges urc
       set end_date = v_first - 1, updated_at = now()
     where urc.unit_id = v_occ.unit_id and urc.active and urc.charge_category_id = any(v_cats)
       and urc.id <> v_keep
       and (urc.end_date is null or urc.end_date >= v_first);
    return v_keep;
  end if;

  select greatest(v_first, coalesce(date_trunc('month', max(urc.next_post_date) filter (where urc.last_posted_at is not null))::date, v_first))
    into v_first
    from public.unit_recurring_charges urc
   where urc.unit_id = v_occ.unit_id and urc.active and urc.charge_category_id = any(v_cats)
     and urc.frequency = v_freq
     and (urc.end_date is null or urc.end_date >= v_first);
  if extract(day from v_first) <> 1 then
    v_first := (date_trunc('month', v_first) + interval '1 month')::date;
  end if;
  if exists (select 1 from public.charges c
              where c.unit_id = v_occ.unit_id and c.charge_category_id = any(v_cats)
                and c.due_date = v_first and c.amount <> 0) then
    v_first := (v_first + interval '1 month')::date;
  end if;

  update public.unit_recurring_charges urc
     set active = false, updated_at = now()
   where urc.unit_id = v_occ.unit_id and urc.active and urc.charge_category_id = any(v_cats)
     and coalesce(urc.start_date, urc.next_post_date) >= v_first;
  update public.unit_recurring_charges urc
     set end_date = v_first - 1, updated_at = now()
   where urc.unit_id = v_occ.unit_id and urc.active and urc.charge_category_id = any(v_cats)
     and (urc.end_date is null or urc.end_date >= v_first);

  if v_amount <= 0 then
    return null;
  end if;

  insert into public.unit_recurring_charges
    (unit_id, charge_category_id, amount, frequency, start_date, next_post_date, created_by)
  values (v_occ.unit_id, v_cat, v_amount, v_freq, v_first, v_first, auth.uid())
  returning id into v_id;
  return v_id;
end $$;


ALTER FUNCTION "public"."schedule_owner_dues"("p_occupancy_id" "uuid", "p_start" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."scheduled_report_delivery_recipients"("p_run_id" "uuid") RETURNS TABLE("email" "text", "full_name" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v record;
begin
  select r.portfolio_id, r.parameters, r.status::text as status, d.slug, s.delivery_channel::text as channel, s.delivery_targets
    into v
    from public.report_runs r
    join public.scheduled_reports s on s.id = r.scheduled_report_id
    left join public.report_definitions d on d.id = r.definition_id
   where r.id = p_run_id;
  if not found or v.status <> 'succeeded' or v.channel <> 'email' then return; end if;
  return query
    select a.email, a.full_name
      from public.report_allowed_recipients(v.portfolio_id, v.slug, coalesce(v.parameters, '{}'::jsonb), v.delivery_targets) a
     where a.error is null;
end $$;


ALTER FUNCTION "public"."scheduled_report_delivery_recipients"("p_run_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."scheduled_report_next_run"("p_frequency" "public"."schedule_frequency", "p_day_of_week" integer, "p_day_of_month" integer, "p_hour_utc" integer, "p_after" timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  after_utc timestamp := p_after at time zone 'UTC';
  hr interval := make_interval(hours => coalesce(p_hour_utc, 8));
  dow integer := coalesce(p_day_of_week, 1);
  dom integer := coalesce(p_day_of_month, 1);
  step interval;
  period_start timestamp;
  candidate timestamp;
  i integer;
begin
  if p_frequency in ('daily') then
    candidate := date_trunc('day', after_utc) + hr;
    if candidate <= after_utc then candidate := candidate + interval '1 day'; end if;
    return candidate at time zone 'UTC';
  end if;

  if p_frequency in ('weekly', 'biweekly') then
    candidate := date_trunc('week', after_utc) - interval '1 day' + make_interval(days => dow) + hr;
    while candidate <= after_utc loop candidate := candidate + interval '7 days'; end loop;
    return candidate at time zone 'UTC';
  end if;

  step := case p_frequency when 'monthly' then interval '1 month' when 'quarterly' then interval '3 months' else interval '1 year' end;
  period_start := date_trunc(case p_frequency when 'monthly' then 'month' when 'quarterly' then 'quarter' else 'year' end, after_utc);
  for i in 0..1 loop
    candidate := period_start
      + make_interval(days => least(dom, extract(day from (period_start + interval '1 month' - interval '1 day'))::integer) - 1)
      + hr;
    if candidate > after_utc then return candidate at time zone 'UTC'; end if;
    period_start := period_start + step;
  end loop;
  return candidate at time zone 'UTC';
end;
$$;


ALTER FUNCTION "public"."scheduled_report_next_run"("p_frequency" "public"."schedule_frequency", "p_day_of_week" integer, "p_day_of_month" integer, "p_hour_utc" integer, "p_after" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."scheduled_report_next_run"("p_frequency" "public"."schedule_frequency", "p_day_of_week" integer, "p_day_of_month" integer, "p_hour" integer, "p_time_zone" "text", "p_after" timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  zone text := coalesce(nullif(p_time_zone, ''), 'UTC');
  after_local timestamp;
  hr interval := make_interval(hours => coalesce(p_hour, 8));
  dow integer := coalesce(p_day_of_week, 1);
  dom integer := coalesce(p_day_of_month, 1);
  step interval;
  period_start timestamp;
  candidate timestamp;
  i integer;
begin
  after_local := p_after at time zone zone;

  if p_frequency = 'daily' then
    candidate := date_trunc('day', after_local) + hr;
    if candidate <= after_local then candidate := candidate + interval '1 day'; end if;
    return candidate at time zone zone;
  end if;

  if p_frequency in ('weekly', 'biweekly') then
    candidate := date_trunc('week', after_local) - interval '1 day' + make_interval(days => dow) + hr;
    while candidate <= after_local loop candidate := candidate + interval '7 days'; end loop;
    return candidate at time zone zone;
  end if;

  step := case p_frequency when 'monthly' then interval '1 month' when 'quarterly' then interval '3 months' else interval '1 year' end;
  period_start := date_trunc(case p_frequency when 'monthly' then 'month' when 'quarterly' then 'quarter' else 'year' end, after_local);
  for i in 0..1 loop
    candidate := period_start
      + make_interval(days => least(dom, extract(day from (period_start + interval '1 month' - interval '1 day'))::integer) - 1)
      + hr;
    if candidate > after_local then return candidate at time zone zone; end if;
    period_start := period_start + step;
  end loop;
  return candidate at time zone zone;
end;
$$;


ALTER FUNCTION "public"."scheduled_report_next_run"("p_frequency" "public"."schedule_frequency", "p_day_of_week" integer, "p_day_of_month" integer, "p_hour" integer, "p_time_zone" "text", "p_after" timestamp with time zone) OWNER TO "postgres";


