CREATE OR REPLACE FUNCTION "public"."select_payment_processor"("p_portfolio_id" "uuid", "p_method" "text") RETURNS "public"."payment_processor"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  chosen public.payment_processor;
begin
  -- Prefer configured default if it supports the method
  select processor into chosen
    from public.payment_processor_configs
   where portfolio_id = p_portfolio_id
     and is_active
     and is_default
     and (
       (p_method in ('ach','echeck') and supports_ach)
       or (p_method in ('card','credit_card','debit_card') and supports_card)
     )
   limit 1;

  if chosen is not null then
    return chosen;
  end if;

  -- Fall back to cheapest ACH processor configured
  if p_method in ('ach','echeck') then
    select processor into chosen
      from public.payment_processor_configs
     where portfolio_id = p_portfolio_id and is_active and supports_ach
     order by coalesce(ach_fee_fixed_cents, 999999) + coalesce(ach_fee_bps, 0) * 10
     limit 1;
  else
    select processor into chosen
      from public.payment_processor_configs
     where portfolio_id = p_portfolio_id and is_active and supports_card
     order by coalesce(card_fee_bps, 0) * 10 + coalesce(card_fee_fixed_cents, 0)
     limit 1;
  end if;

  return coalesce(chosen, 'stripe'::public.payment_processor);
end;
$$;


ALTER FUNCTION "public"."select_payment_processor"("p_portfolio_id" "uuid", "p_method" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."send_test_webhook"("p_endpoint_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  endpoint_row public.webhook_endpoints;
  delivery_id uuid;
begin
  select * into endpoint_row from public.webhook_endpoints where id = p_endpoint_id;
  if not found or not public.can_admin_portfolio(endpoint_row.portfolio_id) then
    raise exception 'Webhook endpoint not found.' using errcode = '42501';
  end if;
  if not public.has_entitlement(endpoint_row.portfolio_id, 'webhooks') then
    raise exception 'Webhooks are not enabled for this portfolio.' using errcode = '42501';
  end if;
  -- Lock the endpoint row (only after the access checks) and re-read it, so
  -- the enabled check uses its current state and overlapping calls wait here
  -- and can't both pass the one-per-minute check below.
  select * into endpoint_row from public.webhook_endpoints where id = endpoint_row.id for update;
  if not found or not endpoint_row.active or (endpoint_row.disabled_until is not null and endpoint_row.disabled_until > now()) then
    raise exception 'Enable this endpoint before sending a test event.' using errcode = '22023';
  end if;
  perform 1 from public.webhook_deliveries
   where endpoint_id = endpoint_row.id
     and event_type = 'ping'::public.webhook_event
     and created_at > now() - interval '1 minute';
  if found then
    raise exception 'A test event was sent to this endpoint less than a minute ago.' using errcode = '22023';
  end if;

  insert into public.webhook_deliveries (endpoint_id, event_type, payload)
  values (
    endpoint_row.id,
    'ping'::public.webhook_event,
    jsonb_build_object(
      'type', 'ping',
      'test', true,
      'message', 'Test event from your property management platform. No action needed.',
      'endpoint_id', endpoint_row.id,
      'portfolio_id', endpoint_row.portfolio_id,
      'sent_at', now()
    )
  )
  returning id into delivery_id;
  return delivery_id;
end;
$$;


ALTER FUNCTION "public"."send_test_webhook"("p_endpoint_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."service_request_emergency_alert"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_assoc text; v_unit text; v_company text; v_support text; v_text text; v_html text; r record;
begin
  if new.priority <> 'emergency' then return new; end if;
  begin
    select a.name into v_assoc from public.associations a where a.id = new.association_id;
    select u.unit_number into v_unit from public.units u where u.id = new.unit_id;
    select p.company_name, p.support_email into v_company, v_support from public.portfolios p where p.id = new.portfolio_id;
    v_text := 'An emergency service request was just submitted.' || chr(10) || chr(10)
           || 'Request: #' || coalesce(new.number, '—') || chr(10)
           || 'Association: ' || coalesce(v_assoc, '—') || chr(10)
           || 'Unit: ' || coalesce(v_unit, 'common area') || chr(10)
           || 'Permission to enter: ' || case when new.permission_to_enter then 'yes' else 'no' end || chr(10) || chr(10)
           || coalesce(new.description, '') || chr(10) || chr(10)
           || 'Respond within 2 hours. Open the Service Requests queue to dispatch a vendor.';
    v_html := '<div style="font-family:system-ui,-apple-system,Segoe UI,Arial,sans-serif;white-space:pre-wrap;line-height:1.6;color:#111827">'
           || replace(replace(replace(v_text, '&', '&amp;'), '<', '&lt;'), '>', '&gt;')
           || '</div>';
    for r in
      select distinct lower(btrim(e)) as email from (
        select pr.email as e
          from public.association_managers am join public.profiles pr on pr.id = am.user_id
         where am.association_id = new.association_id and am.ended_at is null and pr.disabled_at is null
        union all
        select pr.email
          from public.profiles pr
         where pr.portfolio_id = new.portfolio_id and pr.hoa_role = 'manager' and pr.disabled_at is null
           and not exists (select 1 from public.association_managers own where own.user_id = pr.id)
           and not exists (select 1 from public.association_managers am
                            where am.association_id = new.association_id and am.ended_at is null)
        union all select v_support
      ) x where e is not null and btrim(e) like '%@%'
    loop
      insert into public.email_queue (to_email, subject, body, association_id, portfolio_id, from_address, from_name, idempotency_key)
      values (r.email,
              'EMERGENCY service request #' || coalesce(new.number, '') || ' — ' || coalesce(v_assoc, 'association') || coalesce(' unit ' || v_unit, ''),
              v_html, new.association_id, new.portfolio_id, 'hello@portier369.com', v_company,
              'sr-emergency:' || new.id || ':' || r.email)
      on conflict do nothing;
    end loop;
  exception when others then
    raise warning 'service_request_emergency_alert failed for %: %', new.id, sqlerrm;
  end;
  return new;
end $$;


ALTER FUNCTION "public"."service_request_emergency_alert"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."service_request_guard_update"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_status public.service_request_status;
  v_open boolean;
  v_resolved timestamptz; -- work_orders_fixes
  v_resolved_by uuid; -- work_orders_followups
  v_is_staff boolean := public.is_platform_operator() or public.is_any_staff() or public.is_company_admin();
begin
  if not v_is_staff and auth.uid() is not null then
    v_status := new.status;
    v_open := new.has_open_work_order;
    v_resolved := new.resolved_at;
    v_resolved_by := new.resolved_by;
    new := old;
    new.status := v_status;
    if pg_trigger_depth() > 1 then
      new.has_open_work_order := v_open;
      new.resolved_at := v_resolved;
      new.resolved_by := v_resolved_by;
    end if;
    new.updated_at := now();
    return new;
  end if;
  if old.acknowledged_at is null and new.acknowledged_at is null
     and (new.status is distinct from old.status or new.resolution_note is distinct from old.resolution_note)
     and auth.uid() is not null then
    new.acknowledged_at := now();
    new.acknowledged_by := auth.uid();
  end if;
  if new.acknowledged_at is null and new.priority is distinct from old.priority then
    new.first_response_due_at := old.created_at + public.service_request_response_window(new.priority);
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."service_request_guard_update"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."service_request_intake"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'extensions'
    AS $$
declare
  c record;
  -- Staff of this request's association (not staff at another company).
  v_is_staff boolean := (public.is_platform_operator() or public.is_any_staff() or public.is_company_admin())
    and public.can_access_association(coalesce(new.association_id,
          (select b.association_id from public.units u join public.buildings b on b.id = u.building_id where u.id = new.unit_id)));
  v_dup uuid; v_score numeric;
begin
  if not v_is_staff and auth.uid() is not null then
    new.status := 'open';
    new.number := null; new.category := null;
    new.acknowledged_at := null; new.acknowledged_by := null;
    new.resolution_note := null; new.resolved_at := null; new.resolved_by := null;
    -- Owners file new requests: never already triaged or back-dated.
    new.has_open_work_order := false;
    new.created_at := now();
    new.created_by := auth.uid(); new.archived_at := null;
  end if;
  -- derive scope from the unit for non-staff callers
  if not v_is_staff and auth.uid() is not null and new.unit_id is not null then
    select b.association_id, a.portfolio_id into new.association_id, new.portfolio_id
      from public.units u
      join public.buildings b on b.id = u.building_id
      join public.associations a on a.id = b.association_id
     where u.id = new.unit_id;
  end if;
  if new.portfolio_id is null and new.association_id is not null then
    select portfolio_id into new.portfolio_id from public.associations where id = new.association_id;
  end if;
  -- work_orders_fixes: the association's own date, once the association is known
  -- (residents always; staff only when they left the date empty).
  if (not v_is_staff and auth.uid() is not null) or new.created_on is null then
    new.created_on := public.association_local_date(new.association_id, coalesce(new.created_at, now()));
  end if;
  if new.number is null and new.portfolio_id is not null then
    new.number := public.next_maintenance_number(new.portfolio_id)::text;
  end if;
  select * into c from public.classify_service_request(new.description);
  new.request_kind   := c.kind;
  new.admin_topic    := c.topic;
  new.category       := coalesce(new.category, c.category);
  new.triage_reasons := coalesce(c.reasons, '{}');
  new.submitted_priority := coalesce(new.priority, 'normal');
  new.priority := greatest(coalesce(new.priority, 'normal'), c.priority_floor);
  if new.priority > new.submitted_priority then
    new.triage_reasons := new.triage_reasons || ('Priority raised from ' || new.submitted_priority || ' to ' || new.priority);
  end if;
  new.first_response_due_at := coalesce(new.created_at, now()) + public.service_request_response_window(new.priority);
  new.duplicate_of := null; new.duplicate_score := null; new.duplicate_reviewed := false;
  if new.request_kind = 'maintenance' and new.association_id is not null and length(coalesce(new.description, '')) >= 10 then
    select s.id, round(extensions.similarity(lower(s.description), lower(new.description))::numeric, 3)
      into v_dup, v_score
      from public.service_requests s
     where s.association_id = new.association_id
       and s.archived_at is null
       and s.status in ('open', 'waiting')
       and s.duplicate_of is null
       and s.created_at > now() - interval '30 days'
       and (extensions.similarity(lower(s.description), lower(new.description)) >= 0.5
            or (s.unit_id is not distinct from new.unit_id and s.category = new.category
                and extensions.similarity(lower(s.description), lower(new.description)) >= 0.3))
     order by extensions.similarity(lower(s.description), lower(new.description)) desc, s.created_at
     limit 1;
    if v_dup is not null then
      new.duplicate_of := v_dup;
      new.duplicate_score := v_score;
    end if;
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."service_request_intake"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."service_request_response_window"("p_priority" "public"."service_request_priority") RETURNS interval
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select case p_priority when 'emergency' then interval '2 hours' when 'high' then interval '24 hours'
                         when 'low' then interval '72 hours' else interval '48 hours' end;
$$;


ALTER FUNCTION "public"."service_request_response_window"("p_priority" "public"."service_request_priority") OWNER TO "postgres";


