    CONSTRAINT "service_requests_description_check" CHECK (("length"("description") >= 1)),
    CONSTRAINT "service_requests_request_kind_check" CHECK (("request_kind" = ANY (ARRAY['maintenance'::"text", 'admin'::"text"])))
);


