CREATE OR REPLACE FUNCTION "public"."service_request_staff_scope"("p_id" "uuid") RETURNS "public"."service_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v public.service_requests;
begin
  if auth.uid() is null then raise exception 'Authentication required' using errcode = '42501'; end if;
  select * into v from public.service_requests where id = p_id and archived_at is null for update;
  if not found then raise exception 'Service request not found' using errcode = 'P0002'; end if;
  if not (public.is_platform_operator()
          or ((public.is_any_staff() or public.is_company_admin())
              and public.can_access_portfolio(v.portfolio_id)
              and public.can_manage_association(v.association_id))) then
    raise exception 'Service request not found' using errcode = 'P0002';
  end if;
  return v;
end $$;


ALTER FUNCTION "public"."service_request_staff_scope"("p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_accounting_period_status"("p_period_id" "uuid", "p_status" "text", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  period_row public.accounting_periods;
  start_date date;
  next_date date;
  end_date date;
  unposted_count integer := 0;
  unreconciled_count integer := 0;
begin
  if p_status not in ('open', 'soft_closed', 'closed') then
    raise exception 'Invalid accounting period status';
  end if;

  select * into period_row
  from public.accounting_periods
  where id = p_period_id
  for update;
  if not found then raise exception 'Accounting period not found'; end if;
  if not (public.can_manage_finance(period_row.portfolio_id) or public.can_admin_portfolio(period_row.portfolio_id) or public.is_platform_operator()) then
    raise exception 'Not authorized to manage this accounting period';
  end if;
  -- Months are company-wide: closing or reopening one affects every
  -- association, so a manager limited to some associations can't.
  if public.manager_is_scoped() is true and not public.is_platform_operator() then
    raise exception 'Months are closed for the whole company. Ask a company admin or a manager who is not limited to specific associations.' using errcode = '42501';
  end if;

  start_date := make_date(period_row.fiscal_year, period_row.period_month, 1);
  next_date := (start_date + interval '1 month')::date;
  end_date := next_date - 1;

  if p_status = 'closed' then
    select count(*) into unposted_count
    from public.journal_entries
    where portfolio_id = period_row.portfolio_id
      and entry_date >= start_date
      and entry_date < next_date
      and not posted;

    select count(*) into unreconciled_count
    from public.bank_accounts
    where portfolio_id = period_row.portfolio_id
      and archived_at is null
      and gl_account_id is not null
      and (last_reconciliation_date is null or last_reconciliation_date < end_date);

    if unposted_count > 0 then
      raise exception 'Post or remove % draft journal entries before closing this period', unposted_count;
    end if;
    if unreconciled_count > 0 then
      raise exception 'Reconcile % bank accounts through % before closing this period', unreconciled_count, end_date;
    end if;
  elsif period_row.status = 'closed' and p_status <> 'closed'
        and char_length(btrim(coalesce(p_note, ''))) < 10 then
    raise exception 'A reopening reason of at least 10 characters is required';
  end if;

  -- A month in a finalized year-end package stays closed until the package
  -- is superseded (months are company-wide).
  if period_row.status = 'closed' and p_status <> 'closed' and exists (
       select 1 from public.year_end_packages y
        where y.portfolio_id = period_row.portfolio_id and y.status = 'finalized'
          and start_date <= y.period_end and end_date >= y.period_start) then
    raise exception 'This month is part of a finalized year-end package. Supersede the package before reopening the month.' using errcode = '55000';
  end if;

  update public.accounting_periods
  set status = p_status::public.period_status,
      closed_at = case when p_status = 'closed' then now() else closed_at end,
      closed_by = case when p_status = 'closed' then auth.uid() else closed_by end,
      reopened_at = case when period_row.status = 'closed' and p_status <> 'closed' then now() else reopened_at end,
      reopened_by = case when period_row.status = 'closed' and p_status <> 'closed' then auth.uid() else reopened_by end,
      notes = case when btrim(coalesce(p_note, '')) <> '' then btrim(p_note) else notes end
  where id = p_period_id;

  insert into public.audit_logs (entity_type, entity_id, action, actor_id, changes)
  values (
    'accounting_period', p_period_id, 'accounting_period_status_changed', auth.uid(),
    jsonb_build_object(
      'from', period_row.status,
      'to', p_status,
      'fiscal_year', period_row.fiscal_year,
      'period_month', period_row.period_month,
      'note', nullif(btrim(coalesce(p_note, '')), '')
    )
  );

  return jsonb_build_object('success', true, 'status', p_status);
end;
$$;


ALTER FUNCTION "public"."set_accounting_period_status"("p_period_id" "uuid", "p_status" "text", "p_note" "text") OWNER TO "postgres";


