ALTER FUNCTION "public"."set_bank_transaction_ignored"("p_id" "uuid", "p_ignored" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_board_approval_settings"("p_association_id" "uuid", "p_signatures_required" boolean, "p_voting_scheme" "public"."voting_scheme", "p_percentage_required" smallint, "p_bills_mode" "text", "p_bills_threshold" numeric, "p_pos_mode" "text", "p_pos_threshold" numeric) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_portfolio uuid;
  before_row jsonb;
begin
  select a.portfolio_id into v_portfolio from public.associations a where a.id = p_association_id and a.archived_at is null;
  if v_portfolio is null then raise exception 'Association not found'; end if;
  if not (public.is_platform_operator() or (public.is_full_access_staff() and v_portfolio = public.current_portfolio_id() and public.can_view_association_row(p_association_id))) then
    raise exception 'Permission denied';
  end if;
  if p_bills_mode not in ('never', 'always', 'over_threshold') or p_pos_mode not in ('never', 'always', 'over_threshold') then
    raise exception 'Invalid approval routing mode';
  end if;
  if (p_bills_mode = 'over_threshold' and (p_bills_threshold is null or p_bills_threshold < 0))
     or (p_pos_mode = 'over_threshold' and (p_pos_threshold is null or p_pos_threshold < 0)) then
    raise exception 'Enter a dollar threshold of zero or more';
  end if;
  if p_voting_scheme = 'percentage_required'::public.voting_scheme
     and (p_percentage_required is null or p_percentage_required not between 1 and 100) then
    raise exception 'Enter a percentage between 1 and 100';
  end if;

  select to_jsonb(s) into before_row from public.board_approval_settings s where s.association_id = p_association_id;

  insert into public.board_approval_settings (
    association_id, signatures_required, default_voting_scheme, default_percentage_required,
    sends_bills_to_board, bills_threshold, sends_pos_to_board, pos_threshold
  ) values (
    p_association_id, coalesce(p_signatures_required, true), p_voting_scheme,
    case when p_voting_scheme = 'percentage_required'::public.voting_scheme then p_percentage_required end,
    p_bills_mode, case when p_bills_mode = 'over_threshold' then p_bills_threshold end,
    p_pos_mode, case when p_pos_mode = 'over_threshold' then p_pos_threshold end
  )
  on conflict (association_id) do update
     set signatures_required = excluded.signatures_required,
         default_voting_scheme = excluded.default_voting_scheme,
         default_percentage_required = excluded.default_percentage_required,
         sends_bills_to_board = excluded.sends_bills_to_board,
         bills_threshold = excluded.bills_threshold,
         sends_pos_to_board = excluded.sends_pos_to_board,
         pos_threshold = excluded.pos_threshold,
         updated_at = now();

  insert into public.audit_logs (portfolio_id, entity_type, entity_id, action, actor_id, actor_email, changes)
  values (
    v_portfolio, 'association', p_association_id, 'board_approval_settings_updated', auth.uid(),
    (select email from auth.users where id = auth.uid()),
    jsonb_build_object('before', before_row, 'after', (select to_jsonb(s) from public.board_approval_settings s where s.association_id = p_association_id))
  );
end;
$$;


ALTER FUNCTION "public"."set_board_approval_settings"("p_association_id" "uuid", "p_signatures_required" boolean, "p_voting_scheme" "public"."voting_scheme", "p_percentage_required" smallint, "p_bills_mode" "text", "p_bills_threshold" numeric, "p_pos_mode" "text", "p_pos_threshold" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_delinquency_case_hold"("p_case_id" "uuid", "p_hold" boolean, "p_note" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare case_row public.delinquency_cases;
begin
  select * into case_row from public.delinquency_cases where id = p_case_id for update;
  if not found then raise exception 'Delinquency case not found'; end if;
  if not public.can_view_association_row(case_row.association_id) then raise exception 'Delinquency case not found'; end if;
  if not (public.can_access_portfolio(case_row.portfolio_id) and (public.is_any_staff() or public.is_company_admin() or public.is_platform_operator())) then
    raise exception 'Not authorized to manage this delinquency case';
  end if;
  if p_hold and case_row.status <> 'open' then raise exception 'Only an open case may be placed on hold'; end if;
  if not p_hold and case_row.status <> 'on_hold' then raise exception 'Case is not on hold'; end if;
  if p_hold and char_length(btrim(coalesce(p_note, ''))) < 10 then raise exception 'Hold reason must be at least 10 characters'; end if;
  update public.delinquency_cases
  set status = case when p_hold then 'on_hold' else 'open' end,
      hold_reason = case when p_hold then btrim(p_note) else null end
  where id = p_case_id;
  insert into public.delinquency_case_events (case_id, event_type, step_number, balance_snapshot, note)
  values (p_case_id, case when p_hold then 'hold_placed' else 'hold_released' end,
          case_row.current_step_number, case_row.balance_snapshot, nullif(btrim(coalesce(p_note, '')), ''));
end;
$$;


ALTER FUNCTION "public"."set_delinquency_case_hold"("p_case_id" "uuid", "p_hold" boolean, "p_note" "text") OWNER TO "postgres";


