CREATE OR REPLACE FUNCTION "public"."set_gl_account_map"("p_key" "text", "p_gl_account_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_pid uuid := public.current_portfolio_id();
  v_type text;
begin
  if v_pid is null or not public.can_manage_finance(v_pid) then raise exception 'Permission denied' using errcode = '42501'; end if;
  if public.manager_is_scoped() is true and not public.is_company_admin() and not public.is_platform_operator() then
    raise exception 'GL account defaults apply to the whole company. Ask a company admin or a manager who is not limited to specific associations.' using errcode = '42501';
  end if;
  if p_key is null or p_gl_account_id is null then raise exception 'Choose an account for this default' using errcode = '22023'; end if;
  select account_type::text into v_type from public.gl_accounts
   where id = p_gl_account_id and portfolio_id = v_pid and active and association_id is null;
  if v_type is null then
    raise exception 'Choose an active company-wide GL account' using errcode = '22023';
  end if;
  if not (
       (p_key = 'accounts_receivable' and v_type = 'accounts_receivable')
    or (p_key = 'accounts_payable' and v_type in ('accounts_payable', 'liability'))
    or (p_key in ('late_fee_income', 'default_income', 'assessment_income') and v_type in ('income', 'other_income'))
    or (p_key = 'undeposited_funds' and v_type in ('cash', 'asset'))) then
    raise exception 'That account type does not fit this default' using errcode = '22023';
  end if;
  if p_key = 'accounts_receivable' and exists (
       select 1 from public.gl_accounts g
        where g.portfolio_id = v_pid and g.account_type = 'accounts_receivable' and g.id <> p_gl_account_id
          and g.name not ilike '%allowance%'
          and round((select coalesce(sum(jl.debit_amount - jl.credit_amount), 0)
                       from public.journal_lines jl join public.journal_entries je on je.id = jl.entry_id and je.posted
                      where jl.gl_account_id = g.id), 2) <> 0) then
    raise exception 'Another A/R account still holds receivables; move that balance to this account with a journal entry before changing the default' using errcode = '22023';
  end if;
  insert into public.gl_account_map (portfolio_id, association_id, map_key, gl_account_id, updated_by)
  values (v_pid, null, p_key, p_gl_account_id, auth.uid())
  on conflict (portfolio_id, coalesce(association_id, '00000000-0000-0000-0000-000000000000'::uuid), map_key)
  do update set gl_account_id = excluded.gl_account_id, updated_by = excluded.updated_by, updated_at = now();
  insert into public.audit_logs (portfolio_id, entity_type, entity_id, action, actor_id, changes)
  values (v_pid, 'gl_account_map', p_gl_account_id, 'mapped', auth.uid(), jsonb_build_object('key', p_key));
end $$;


ALTER FUNCTION "public"."set_gl_account_map"("p_key" "text", "p_gl_account_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_gl_role_permission"("p_gl_account_id" "uuid", "p_role_id" "uuid", "p_permission" "public"."gl_permission") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  account_portfolio uuid;
  role_portfolio uuid;
  prior_permission public.gl_permission;
begin
  select portfolio_id into account_portfolio from public.gl_accounts where id = p_gl_account_id;
  select portfolio_id into role_portfolio from public.user_roles where id = p_role_id;
  if account_portfolio is null or role_portfolio is null or account_portfolio <> role_portfolio then
    raise exception 'GL account and role must belong to the same portfolio';
  end if;
  if not (public.can_admin_portfolio(account_portfolio) or public.is_platform_operator()) then
    raise exception 'Not authorized to administer GL permissions';
  end if;

  select permission into prior_permission
  from public.gl_account_role_permissions
  where gl_account_id = p_gl_account_id and role_id = p_role_id;

  insert into public.gl_account_role_permissions (gl_account_id, role_id, permission)
  values (p_gl_account_id, p_role_id, p_permission)
  on conflict (gl_account_id, role_id)
  do update set permission = excluded.permission, updated_at = now();

  insert into public.permission_audit_log (
    actor_user_id, actor_portfolio_id, target_entity_type, target_entity_id,
    action, before_state, after_state
  ) values (
    auth.uid(), account_portfolio, 'gl_account_role_permission', p_gl_account_id,
    'set', to_jsonb(prior_permission),
    jsonb_build_object('role_id', p_role_id, 'permission', p_permission)
  );
end;
$$;


ALTER FUNCTION "public"."set_gl_role_permission"("p_gl_account_id" "uuid", "p_role_id" "uuid", "p_permission" "public"."gl_permission") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_management_fee_schedule"("p_enabled" boolean, "p_day" integer, "p_vendor_id" "uuid", "p_gl_account_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_pid uuid := public.current_portfolio_id();
begin
  if v_pid is null or not public.can_manage_finance(v_pid) then raise exception 'Permission denied' using errcode = '42501'; end if;
  if public.manager_is_scoped() and not public.is_company_admin() then
    raise exception 'Only company-wide finance staff can schedule management fees' using errcode = '42501';
  end if;
  if p_day is null or p_day not between 1 and 28 then
    raise exception 'Choose a day between 1 and 28' using errcode = '22023';
  end if;
  if p_vendor_id is not null and not exists (
       select 1 from public.vendors v
        where v.id = p_vendor_id and v.portfolio_id = v_pid and v.archived_at is null and v.is_management_company) then
    raise exception 'Choose the management company vendor (a vendor marked as the management company)' using errcode = '22023';
  end if;
  if coalesce(p_enabled, false) then
    if not exists (select 1 from public.vendors v where v.id = coalesce(p_vendor_id, (select management_fee_vendor_id from public.portfolios where id = v_pid))
                     and v.portfolio_id = v_pid and v.archived_at is null and v.is_management_company) then
      raise exception 'Choose the management company vendor' using errcode = '22023';
    end if;
    if not exists (select 1 from public.gl_accounts g where g.id = p_gl_account_id and g.portfolio_id = v_pid and g.active
                     and g.association_id is null and g.account_type::text in ('expense', 'other_expense')) then
      raise exception 'Choose a company-wide expense account for management fees' using errcode = '22023';
    end if;
  end if;
  update public.portfolios
     set management_fee_auto_enabled = coalesce(p_enabled, false),
         management_fee_auto_day = p_day,
         management_fee_vendor_id = coalesce(p_vendor_id, management_fee_vendor_id),
         management_fee_gl_account_id = coalesce(p_gl_account_id, management_fee_gl_account_id)
   where id = v_pid;
  insert into public.audit_logs (portfolio_id, entity_type, entity_id, action, actor_id, actor_email, changes)
  values (v_pid, 'management_fees', null, 'management_fee_schedule_updated', auth.uid(),
          (select email from auth.users where id = auth.uid()),
          jsonb_build_object('enabled', coalesce(p_enabled, false), 'day', p_day, 'vendor_id', p_vendor_id, 'gl_account_id', p_gl_account_id));
end $$;


ALTER FUNCTION "public"."set_management_fee_schedule"("p_enabled" boolean, "p_day" integer, "p_vendor_id" "uuid", "p_gl_account_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_manager_association_scope"("p_manager_id" "uuid", "p_association_ids" "uuid"[] DEFAULT ARRAY[]::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_portfolio_id uuid;
  v_actor_email text;
  v_association_ids uuid[] := coalesce(p_association_ids, array[]::uuid[]);
  v_association_count integer;
begin
  select p.portfolio_id, p.email
    into v_portfolio_id, v_actor_email
  from public.profiles p
  where p.id = v_actor_id
    and p.hoa_role = 'company_admin'
    and p.disabled_at is null;

  if v_portfolio_id is null then
    raise exception 'Active company administrator access is required';
  end if;

  if not exists (
    select 1
    from public.profiles manager
    where manager.id = p_manager_id
      and manager.portfolio_id = v_portfolio_id
      and manager.hoa_role = 'manager'
  ) then
    raise exception 'Manager not found in your portfolio';
  end if;

  if exists (
    select 1
    from unnest(v_association_ids) requested(association_id)
    left join public.associations association
      on association.id = requested.association_id
     and association.portfolio_id = v_portfolio_id
     and association.archived_at is null
    where association.id is null
  ) then
    raise exception 'One or more associations are outside your portfolio';
  end if;

  delete from public.association_managers
  where user_id = p_manager_id;

  insert into public.association_managers (
    user_id,
    association_id,
    portfolio_id,
    assigned_by
  )
  select
    p_manager_id,
    requested.association_id,
    v_portfolio_id,
    v_actor_id
  from (
    select distinct association_id
    from unnest(v_association_ids) item(association_id)
  ) requested;

  get diagnostics v_association_count = row_count;

  insert into public.audit_logs (
    portfolio_id,
    entity_type,
    entity_id,
    action,
    actor_id,
    actor_email,
    changes
  ) values (
    v_portfolio_id,
    'user',
    p_manager_id,
    'manager_association_scope_updated',
    v_actor_id,
    v_actor_email,
    jsonb_build_object(
      'association_ids', to_jsonb(v_association_ids),
      'full_portfolio_access', v_association_count = 0
    )
  );

  return jsonb_build_object(
    'manager_id', p_manager_id,
    'association_count', v_association_count,
    'full_portfolio_access', v_association_count = 0
  );
end;
$$;


ALTER FUNCTION "public"."set_manager_association_scope"("p_manager_id" "uuid", "p_association_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_message_thread_status"("p_thread" "uuid", "p_status" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare a record;
begin
  select * into a from public.message_thread_access(p_thread, 'staff');
  if p_status not in ('open', 'closed') then raise exception 'Unknown status' using errcode = '22023'; end if;
  update public.message_threads
     set status = p_status, closed_at = case when p_status = 'closed' then now() end,
         staff_unread = case when p_status = 'closed' then false else staff_unread end
   where id = p_thread;
end $$;


ALTER FUNCTION "public"."set_message_thread_status"("p_thread" "uuid", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_occupancy_collection_status"("p_occupancy_id" "uuid", "p_in_foreclosure" boolean, "p_in_collections" boolean, "p_certified_funds_only" boolean, "p_allow_online_payments" boolean, "p_require_full_online_payment" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare o record;
begin
  select occ.*, a.portfolio_id as pid into o
    from public.occupancies occ join public.associations a on a.id = occ.association_id
   where occ.id = p_occupancy_id for update of occ;
  if not found or not public.can_manage_finance(o.pid) or not public.can_manage_association(o.association_id) then
    raise exception 'Ownership record not found' using errcode = 'P0002';
  end if;
  update public.occupancies set
    in_foreclosure = coalesce(p_in_foreclosure, false),
    in_collections = coalesce(p_in_collections, false) or coalesce(p_in_foreclosure, false),
    certified_funds_only = coalesce(p_certified_funds_only, false),
    allow_online_payments = coalesce(p_allow_online_payments, true),
    require_full_online_payment = coalesce(p_require_full_online_payment, false),
    updated_at = now()
  where id = p_occupancy_id;
  insert into public.audit_logs (portfolio_id, entity_type, entity_id, action, actor_id, actor_email, changes)
  values (o.pid, 'owner', o.owner_id, 'collection_status_updated', auth.uid(),
          (select email from auth.users where id = auth.uid()),
          jsonb_build_object('occupancy_id', p_occupancy_id, 'unit_id', o.unit_id,
            'before', jsonb_build_object('in_foreclosure', o.in_foreclosure, 'in_collections', o.in_collections,
              'certified_funds_only', o.certified_funds_only, 'allow_online_payments', o.allow_online_payments,
              'require_full_online_payment', o.require_full_online_payment),
            'after', jsonb_build_object('in_foreclosure', coalesce(p_in_foreclosure, false),
              'in_collections', coalesce(p_in_collections, false) or coalesce(p_in_foreclosure, false),
              'certified_funds_only', coalesce(p_certified_funds_only, false),
              'allow_online_payments', coalesce(p_allow_online_payments, true),
              'require_full_online_payment', coalesce(p_require_full_online_payment, false))));
end $$;


ALTER FUNCTION "public"."set_occupancy_collection_status"("p_occupancy_id" "uuid", "p_in_foreclosure" boolean, "p_in_collections" boolean, "p_certified_funds_only" boolean, "p_allow_online_payments" boolean, "p_require_full_online_payment" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_occupancy_dues_reminders"("p_occupancy_id" "uuid", "p_enabled" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare o record;
begin
  select occ.id, occ.owner_id, occ.unit_id, occ.association_id, occ.send_dues_reminders, a.portfolio_id as pid into o
    from public.occupancies occ join public.associations a on a.id = occ.association_id
   where occ.id = p_occupancy_id for update of occ;
  if not found or not public.is_any_staff() or not public.can_manage_association(o.association_id) then
    raise exception 'Ownership record not found' using errcode = 'P0002';
  end if;
  if o.send_dues_reminders is distinct from coalesce(p_enabled, true) then
    update public.occupancies set send_dues_reminders = coalesce(p_enabled, true), updated_at = now() where id = p_occupancy_id;
    insert into public.audit_logs (portfolio_id, entity_type, entity_id, action, actor_id, actor_email, changes)
    values (o.pid, 'owner', o.owner_id, 'dues_reminders_updated', auth.uid(),
            (select email from auth.users where id = auth.uid()),
            jsonb_build_object('occupancy_id', p_occupancy_id, 'unit_id', o.unit_id,
                               'before', o.send_dues_reminders, 'after', coalesce(p_enabled, true)));
  end if;
end $$;


ALTER FUNCTION "public"."set_occupancy_dues_reminders"("p_occupancy_id" "uuid", "p_enabled" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_owner_late_fee_override"("p_occupancy_id" "uuid", "p_exempt" boolean, "p_amount" numeric, "p_is_percent" boolean, "p_until" "date", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare o record; v_portfolio uuid;
begin
  select occ.*, a.portfolio_id as pid into o
    from public.occupancies occ join public.associations a on a.id = occ.association_id
   where occ.id = p_occupancy_id for update of occ;
  if not found or not public.can_manage_finance(o.pid) or not public.can_access_association(o.association_id) then
    raise exception 'Ownership record not found' using errcode = 'P0002';
  end if;
  if p_amount is not null and (p_amount < 0 or (coalesce(p_is_percent, false) and p_amount > 100)) then
    raise exception 'Enter a fee of $0 or more, or a percentage up to 100' using errcode = '22023';
  end if;
  if (coalesce(p_exempt, false) or p_amount is not null) and length(btrim(coalesce(p_reason, ''))) < 3 then
    raise exception 'Give a reason for the late-fee exception' using errcode = '22023';
  end if;
  if p_until is not null and p_until < public.association_local_date(o.association_id) then
    raise exception 'The end date must be today or later' using errcode = '22023';
  end if;
  update public.occupancies set
    late_fee_exempt = coalesce(p_exempt, false),
    late_fee_override_amount = case when coalesce(p_exempt, false) then null else p_amount end,
    late_fee_override_is_percent = case when coalesce(p_exempt, false) or p_amount is null then false else coalesce(p_is_percent, false) end,
    late_fee_override_until = case when coalesce(p_exempt, false) or p_amount is not null then p_until end,
    updated_at = now()
  where id = p_occupancy_id;
  insert into public.occupancy_private (occupancy_id, late_fee_override_reason, updated_at)
  values (p_occupancy_id,
          case when coalesce(p_exempt, false) or p_amount is not null then nullif(btrim(p_reason), '') end,
          now())
  on conflict (occupancy_id) do update
    set late_fee_override_reason = excluded.late_fee_override_reason, updated_at = now();
  insert into public.audit_logs (portfolio_id, entity_type, entity_id, action, actor_id, actor_email, changes)
  values (o.pid, 'owner', o.owner_id, 'late_fee_override_updated', auth.uid(), (select email from auth.users where id = auth.uid()),
          jsonb_build_object('occupancy_id', p_occupancy_id, 'unit_id', o.unit_id,
            'before', jsonb_build_object('exempt', o.late_fee_exempt, 'amount', o.late_fee_override_amount, 'is_percent', o.late_fee_override_is_percent, 'until', o.late_fee_override_until),
            'after', jsonb_build_object('exempt', coalesce(p_exempt, false), 'amount', p_amount, 'is_percent', p_is_percent, 'until', p_until, 'reason_given', p_reason is not null and btrim(p_reason) <> '')));
end $_$;


ALTER FUNCTION "public"."set_owner_late_fee_override"("p_occupancy_id" "uuid", "p_exempt" boolean, "p_amount" numeric, "p_is_percent" boolean, "p_until" "date", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_payable_bill_expense_account"("p_bill_id" "uuid", "p_gl_account_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  b public.payable_bills%rowtype;
begin
  select * into b from public.payable_bills where id = p_bill_id for update;
  if not found then raise exception 'Bill not found' using errcode = 'P0002'; end if;
  if not public.can_manage_finance(b.portfolio_id) or not public.operator_may_write(false) then
    raise exception 'Permission denied' using errcode = '42501';
  end if;
  if not public.can_view_association_row(b.association_id) then
    raise exception 'Bill not found' using errcode = 'P0002';
  end if;
  if b.status not in ('draft'::public.payable_bill_status, 'pending_approval'::public.payable_bill_status) or b.archived_at is not null then
    raise exception 'The expense account can be changed only before the bill is approved' using errcode = '55000';
  end if;
  perform 1 from public.gl_accounts g
   where g.id = p_gl_account_id
     and g.portfolio_id = b.portfolio_id
     and g.active
     and g.account_type in ('expense', 'cost_of_goods_sold', 'other_expense')
     and (g.association_id is null or g.association_id = b.association_id);
  if not found then
    raise exception 'Choose an active expense account for this association' using errcode = '22023';
  end if;
  update public.payable_bills set gl_account_id = p_gl_account_id, updated_at = now() where id = p_bill_id;
end
$$;


ALTER FUNCTION "public"."set_payable_bill_expense_account"("p_bill_id" "uuid", "p_gl_account_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_record_tags"("p_entity_type" "text", "p_entity_id" "uuid", "p_tags" "text"[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_pid uuid := public.record_portfolio_id(p_entity_type, p_entity_id);
  v_names text[];
  v_before text[];
begin
  if p_entity_type not in ('association', 'unit', 'owner', 'vendor') then
    raise exception 'Tags are not supported on this record' using errcode = '22023';
  end if;
  if v_pid is null or not public.can_access_portfolio(v_pid) or not public.app_record_in_manager_scope(p_entity_type, p_entity_id) then
    raise exception 'Record not found' using errcode = 'P0002';
  end if;

  select coalesce(array_agg(coalesce(t.name, d.n) order by lower(d.n)), '{}') into v_names
    from (select distinct on (lower(n)) n
            from (select btrim(regexp_replace(x, '\s+', ' ', 'g')) n, i
                    from unnest(coalesce(p_tags, '{}')) with ordinality u(x, i)) s
           where length(n) between 1 and 40
           order by lower(n), i) d
    left join public.tags t on t.portfolio_id = v_pid and lower(t.name) = lower(d.n);
  if cardinality(v_names) > 20 then
    raise exception 'A record can have at most 20 tags' using errcode = '22023';
  end if;

  select coalesce(array_agg(t.name order by lower(t.name)), '{}') into v_before
    from public.tag_assignments ta join public.tags t on t.id = ta.tag_id
   where ta.entity_type = p_entity_type::public.tag_entity_type and ta.entity_id = p_entity_id;

  insert into public.tags (portfolio_id, name)
  select v_pid, n from unnest(v_names) n
   where not exists (select 1 from public.tags t where t.portfolio_id = v_pid and lower(t.name) = lower(n));

  delete from public.tag_assignments ta using public.tags t
   where t.id = ta.tag_id and ta.entity_type = p_entity_type::public.tag_entity_type
     and ta.entity_id = p_entity_id
     and not exists (select 1 from unnest(v_names) n where lower(n) = lower(t.name));

  insert into public.tag_assignments (tag_id, entity_type, entity_id, created_by)
  select t.id, p_entity_type::public.tag_entity_type, p_entity_id, auth.uid()
    from public.tags t
   where t.portfolio_id = v_pid and exists (select 1 from unnest(v_names) n where lower(n) = lower(t.name))
  on conflict (tag_id, entity_type, entity_id) do nothing;

  if v_before is distinct from v_names then
    insert into public.audit_logs (portfolio_id, entity_type, entity_id, action, actor_id, actor_email, changes)
    values (v_pid, p_entity_type, p_entity_id, 'tags_updated', auth.uid(),
            (select email from auth.users where id = auth.uid()),
            jsonb_build_object('before', to_jsonb(v_before), 'after', to_jsonb(v_names)));
  end if;
end $$;


ALTER FUNCTION "public"."set_record_tags"("p_entity_type" "text", "p_entity_id" "uuid", "p_tags" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_recurring_purchase_order_state"("p_id" "uuid", "p_state" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  r public.recurring_purchase_orders;
begin
  select * into r from public.recurring_purchase_orders where id = p_id and archived_at is null for update;
  if not found or not public.can_manage_finance(r.portfolio_id) or not public.can_manage_association(r.association_id) then
    raise exception 'Recurring purchase order not found' using errcode = '42501';
  end if;
  if p_state = 'pause' then
    update public.recurring_purchase_orders set auto_generate = false, updated_at = now() where id = p_id;
  elsif p_state = 'resume' then
    update public.recurring_purchase_orders
       set auto_generate = true, last_error = null, updated_at = now(),
           -- purchase_orders_fixes: the association's own day.
           next_post_date = greatest(coalesce(next_post_date, start_date),
                                     coalesce(public.association_local_date(r.association_id), current_date))
     where id = p_id;
  elsif p_state = 'stop' then
    update public.recurring_purchase_orders set archived_at = now(), auto_generate = false, updated_at = now() where id = p_id;
  else
    raise exception 'Unknown action' using errcode = '22023';
  end if;
end $$;


ALTER FUNCTION "public"."set_recurring_purchase_order_state"("p_id" "uuid", "p_state" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."setup_edge_function_secrets"("p_project_url" "text", "p_service_role_key" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'vault'
    AS $$
declare
  existing_url_id uuid;
  existing_key_id uuid;
begin
  -- Refuse unless caller is a platform admin or running as service role
  if not (public.is_platform_operator() or current_user = 'service_role') then
    raise exception 'setup_edge_function_secrets: platform operator or service_role required';
  end if;

  select id into existing_url_id from vault.secrets where name = 'project_url';
  select id into existing_key_id from vault.secrets where name = 'service_role_key';

  if existing_url_id is null then
    perform vault.create_secret(p_project_url, 'project_url', 'Supabase project URL for edge function invocation');
  else
    perform vault.update_secret(existing_url_id, p_project_url);
  end if;

  if existing_key_id is null then
    perform vault.create_secret(p_service_role_key, 'service_role_key', 'Supabase service role key for edge function invocation');
  else
    perform vault.update_secret(existing_key_id, p_service_role_key);
  end if;

  return 'secrets configured';
end;
$$;


ALTER FUNCTION "public"."setup_edge_function_secrets"("p_project_url" "text", "p_service_role_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."setup_edge_function_secrets"("p_project_url" "text", "p_service_role_key" "text") IS 'One-shot setup for the edge function cron system. Call via service_role (e.g., from a one-time psql session or a Supabase SQL Editor query) to populate project_url and service_role_key Vault secrets.';



CREATE OR REPLACE FUNCTION "public"."sign_signature_request"("p_token_hash" "text", "p_signature_name" "text", "p_consented" boolean, "p_document_sha256" "text", "p_ip" "text", "p_user_agent" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare sg public.signature_signers; r public.signature_requests; v_remaining integer;
begin
  select * into sg from public.signature_signers where token_hash = lower(p_token_hash) for update;
  if not found then raise exception 'This signing link is not valid'; end if;
  select * into r from public.signature_requests where id = sg.request_id for update;
  if r.status <> 'sent' then raise exception 'This request is no longer open for signature'; end if;
  if r.expires_at < now() then raise exception 'This signing link has expired'; end if;
  if sg.status in ('signed', 'declined') then raise exception 'You have already responded to this request'; end if;
  if r.sequential and exists (
    select 1 from public.signature_signers o where o.request_id = r.id and o.sign_order < sg.sign_order and o.status <> 'signed'
  ) then raise exception 'An earlier signer must sign first'; end if;
  if not coalesce(p_consented, false) then raise exception 'Consent to sign electronically is required'; end if;
  if char_length(btrim(coalesce(p_signature_name, ''))) < 2 then raise exception 'Type your full name to sign'; end if;
  if lower(coalesce(p_document_sha256, '')) <> r.document_sha256 then
    raise exception 'The document changed after it was sent — signing is blocked';
  end if;
  update public.signature_signers
     set status = 'signed', consented_at = now(), signed_at = now(), signature_name = left(btrim(p_signature_name), 120),
         signed_ip = left(p_ip, 128), signed_user_agent = left(p_user_agent, 400)
   where id = sg.id;
  insert into public.signature_events (request_id, signer_id, event_type, ip, user_agent, detail)
  values (r.id, sg.id, 'signed', left(p_ip, 128), left(p_user_agent, 400),
          jsonb_build_object('signature_name', left(btrim(p_signature_name), 120), 'document_sha256', r.document_sha256, 'consent', true));
  select count(*) into v_remaining from public.signature_signers where request_id = r.id and status <> 'signed';
  if v_remaining = 0 then
    update public.signature_requests set status = 'completed', completed_at = now() where id = r.id;
    insert into public.signature_events (request_id, event_type, detail) values (r.id, 'completed', jsonb_build_object('document_sha256', r.document_sha256));
    if r.subject_type = 'management_agreement' and r.subject_id is not null then
      update public.management_agreements
         set signed_at = coalesce(signed_at, now()),
             signed_by_owner = coalesce(signed_by_owner, (select signature_name from public.signature_signers where request_id = r.id order by sign_order limit 1)),
             status = case when status = 'draft' then 'active' else status end,
             updated_at = now()
       where id = r.subject_id and portfolio_id = r.portfolio_id;
    end if;
  end if;
  return jsonb_build_object('completed', v_remaining = 0, 'request_id', r.id);
end;
$$;


ALTER FUNCTION "public"."sign_signature_request"("p_token_hash" "text", "p_signature_name" "text", "p_consented" boolean, "p_document_sha256" "text", "p_ip" "text", "p_user_agent" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."signature_session"("p_token_hash" "text", "p_ip" "text", "p_user_agent" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare sg public.signature_signers; r public.signature_requests; v_blocked text; v_show_document boolean;
begin
  select * into sg from public.signature_signers where token_hash = lower(p_token_hash);
  if not found then return null; end if;
  select * into r from public.signature_requests where id = sg.request_id;
  if r.status = 'sent' and r.expires_at < now() then v_blocked := 'expired'; end if;
  if r.sequential and sg.status not in ('signed', 'declined') and exists (
    select 1 from public.signature_signers o where o.request_id = r.id and o.sign_order < sg.sign_order and o.status <> 'signed'
  ) then v_blocked := coalesce(v_blocked, 'waiting'); end if;
  if sg.status = 'pending' and r.status = 'sent' and v_blocked is null then
    update public.signature_signers set status = 'viewed', viewed_at = now() where id = sg.id;
    insert into public.signature_events (request_id, signer_id, event_type, ip, user_agent)
    values (r.id, sg.id, 'viewed', left(p_ip, 128), left(p_user_agent, 400));
    sg.status := 'viewed';
  end if;
  -- Open and not blocked, or completed for a signer who signed.
  v_show_document := (r.status = 'sent' and v_blocked is null)
                     or (r.status = 'completed' and sg.status = 'signed');
  return jsonb_build_object(
    'request', jsonb_build_object('id', r.id, 'title', r.title, 'message', r.message, 'status', r.status,
      'document_kind', r.document_kind, 'document_path', case when v_show_document then r.document_path end,
      'body_text', case when v_show_document then r.body_text end,
      'document_sha256', r.document_sha256, 'expires_at', r.expires_at, 'completed_at', r.completed_at,
      'association', (select name from public.associations where id = r.association_id),
      'company', (select company_name from public.portfolios where id = r.portfolio_id)),
    'signer', jsonb_build_object('id', sg.id, 'name', sg.name, 'email', sg.email, 'role_label', sg.role_label,
      'status', sg.status, 'signed_at', sg.signed_at, 'signature_name', sg.signature_name),
    'signers', (select jsonb_agg(jsonb_build_object('name', o.name, 'role_label', o.role_label, 'status', o.status, 'signed_at', o.signed_at) order by o.sign_order)
                  from public.signature_signers o where o.request_id = r.id),
    'blocked', v_blocked);
end;
$$;


ALTER FUNCTION "public"."signature_session"("p_token_hash" "text", "p_ip" "text", "p_user_agent" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."slugify_association_name"("p_name" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select coalesce(nullif(
    trim(both '-' from
      regexp_replace(
        regexp_replace(
          regexp_replace(
            lower(coalesce(p_name, '')),
            '\m(condominium|condominiums|condo|association|associations|assoc|hoa|homeowners|homeowner|owners|community|communities|incorporated|inc|llc|ltd|the)\M',
            ' ', 'g'),
          '[^a-z0-9]+', '-', 'g'),
        '-+', '-', 'g')
    ), ''), 'assoc');
$$;


ALTER FUNCTION "public"."slugify_association_name"("p_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sms_messages_guard_provider_from"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if current_user in ('authenticated', 'anon') then
    if tg_op = 'INSERT' then
      new.provider_from_number := null;
      new.provider_message_id := null;
    else
      new.provider_from_number := old.provider_from_number;
      new.provider_message_id := old.provider_message_id;
      new.to_number := old.to_number;
      new.conversation_id := old.conversation_id;
      new.direction := old.direction;
    end if;
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."sms_messages_guard_provider_from"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sms_reply_conversations"("p_from" "text", "p_to" "text") RETURNS TABLE("id" "uuid", "portfolio_id" "uuid", "archived_at" timestamp with time zone, "last_message_at" timestamp with time zone)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select c.id, c.portfolio_id, c.archived_at, c.last_message_at
    from public.sms_conversations c
   where c.with_phone_number = p_from
     and exists (
       select 1 from public.sms_messages m
        where m.conversation_id = c.id and m.direction = 'outbound'
          and m.provider_from_number = p_to and m.to_number = p_from)
$$;


