CREATE OR REPLACE FUNCTION "public"."start_resident_message_thread"("p_unit" "uuid", "p_subject" "text", "p_body" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_owner uuid; v_tenant uuid; v_assoc uuid; v_portfolio uuid; v_name text; v_id uuid; v_open int;
begin
  if auth.uid() is null then raise exception 'Authentication required' using errcode = '42501'; end if;
  select b.association_id, a.portfolio_id into v_assoc, v_portfolio
    from public.units u join public.buildings b on b.id = u.building_id join public.associations a on a.id = b.association_id
   where u.id = p_unit;
  if v_assoc is null then raise exception 'Unit not found' using errcode = 'P0002'; end if;
  select o.owner_id into v_owner
    from public.occupancies o
   where o.unit_id = p_unit
     and o.owner_id in (select public.current_owner_ids())
     and o.status = 'current'
     and (o.move_out_date is null or o.move_out_date > current_date)
   order by o.created_at, o.id
   limit 1;
  if v_owner is not null then
    select full_name into v_name from public.owners where id = v_owner;
  else
    select t.id, btrim(coalesce(t.first_name, '') || ' ' || coalesce(t.last_name, '')) into v_tenant, v_name
      from public.tenants t
     where t.unit_id = p_unit and t.id in (select public.current_tenant_ids()) and t.archived_at is null
     limit 1;
    if v_tenant is null then raise exception 'Unit not found' using errcode = 'P0002'; end if;
  end if;
  select count(*) into v_open from public.message_threads
   where status = 'open' and (owner_id = v_owner or tenant_id = v_tenant);
  if v_open >= 25 then
    raise exception 'You have 25 open conversations — reply in one of those instead' using errcode = '22023';
  end if;
  insert into public.message_threads (portfolio_id, association_id, unit_id, owner_id, tenant_id, subject, started_by_role,
                                      created_by, staff_unread, first_response_due_at, last_message_preview, last_message_role)
  values (v_portfolio, v_assoc, p_unit, v_owner, v_tenant, btrim(p_subject), 'resident', auth.uid(), true, now() + interval '48 hours',
          left(btrim(p_body), 140), 'resident')
  returning id into v_id;
  insert into public.message_thread_messages (thread_id, author_id, author_role, author_name, body)
  values (v_id, auth.uid(), 'resident', nullif(v_name, ''), btrim(p_body));
  return v_id;
end $$;


ALTER FUNCTION "public"."start_resident_message_thread"("p_unit" "uuid", "p_subject" "text", "p_body" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."start_staff_message_thread"("p_owner" "uuid", "p_tenant" "uuid", "p_subject" "text", "p_body" "text", "p_unit" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_assoc uuid; v_portfolio uuid; v_unit uuid; v_id uuid; v_count int;
begin
  if auth.uid() is null or not public.is_messaging_staff() then raise exception 'Not allowed' using errcode = '42501'; end if;
  if (p_owner is null) = (p_tenant is null) then raise exception 'Pick one recipient' using errcode = '22023'; end if;
  if p_owner is not null then
    with owned as (
      select o.unit_id from public.occupancies o
       where o.owner_id = p_owner and o.status = 'current' and o.occupancy_type = 'owner'
      union
      select uo.unit_id from public.unit_owners uo where uo.owner_id = p_owner and uo.end_date is null
    ), scoped as (
      select u.id as unit_id, b.association_id, a.portfolio_id
        from owned join public.units u on u.id = owned.unit_id
        join public.buildings b on b.id = u.building_id join public.associations a on a.id = b.association_id
       where public.can_access_portfolio(a.portfolio_id) and public.can_manage_association(b.association_id)
    )
    select count(*) into v_count from scoped;
    if p_unit is not null then
      select s.association_id, s.portfolio_id, s.unit_id into v_assoc, v_portfolio, v_unit
        from (
          select u.id as unit_id, b.association_id, a.portfolio_id
            from public.units u join public.buildings b on b.id = u.building_id join public.associations a on a.id = b.association_id
           where u.id = p_unit
             and (exists (select 1 from public.occupancies o where o.unit_id = u.id and o.owner_id = p_owner and o.status = 'current' and o.occupancy_type = 'owner')
                  or exists (select 1 from public.unit_owners uo where uo.unit_id = u.id and uo.owner_id = p_owner and uo.end_date is null))
        ) s;
    elsif v_count = 1 then
      select s.association_id, s.portfolio_id, s.unit_id into v_assoc, v_portfolio, v_unit
        from (
          select u.id as unit_id, b.association_id, a.portfolio_id
            from public.units u join public.buildings b on b.id = u.building_id join public.associations a on a.id = b.association_id
           where u.id in (select o.unit_id from public.occupancies o where o.owner_id = p_owner and o.status = 'current' and o.occupancy_type = 'owner'
                          union select uo.unit_id from public.unit_owners uo where uo.owner_id = p_owner and uo.end_date is null)
             and public.can_access_portfolio(a.portfolio_id) and public.can_manage_association(b.association_id)
        ) s;
    elsif v_count > 1 then
      raise exception 'This owner has more than one unit — pick the unit the message is about' using errcode = '22023';
    end if;
  else
    select t.association_id, t.portfolio_id, t.unit_id into v_assoc, v_portfolio, v_unit
      from public.tenants t where t.id = p_tenant and t.archived_at is null;
  end if;
  if v_assoc is null or not public.can_access_portfolio(v_portfolio) or not public.can_manage_association(v_assoc) then
    raise exception 'Recipient not found' using errcode = 'P0002';
  end if;
  insert into public.message_threads (portfolio_id, association_id, unit_id, owner_id, tenant_id, subject, started_by_role,
                                      created_by, resident_unread, assigned_to, acknowledged_at,
                                      last_message_preview, last_message_role)
  values (v_portfolio, v_assoc, v_unit, p_owner, p_tenant, btrim(p_subject), 'staff', auth.uid(), true, auth.uid(), now(),
          left(btrim(p_body), 140), 'staff')
  returning id into v_id;
  insert into public.message_thread_messages (thread_id, author_id, author_role, author_name, body)
  values (v_id, auth.uid(), 'staff', public.message_author_name(), btrim(p_body));
  return v_id;
end $$;


ALTER FUNCTION "public"."start_staff_message_thread"("p_owner" "uuid", "p_tenant" "uuid", "p_subject" "text", "p_body" "text", "p_unit" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_owner_message"("p_subject" "text", "p_body" "text", "p_idempotency_key" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
begin
  return public.submit_owner_message(p_subject, p_body, p_idempotency_key, public.current_owner_id());
end;
$$;


ALTER FUNCTION "public"."submit_owner_message"("p_subject" "text", "p_body" "text", "p_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_owner_message"("p_subject" "text", "p_body" "text", "p_idempotency_key" "uuid", "p_owner_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  owner_row public.owners%rowtype;
  occupancy_row record;
  sender_name text;
  sender_email text;
  existing_id uuid;
  message_id uuid;
  recipient record;
  v_recipient_count integer := 0;
  safe_body text;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  if p_idempotency_key is null then raise exception 'Message request key is required'; end if;
  p_subject := btrim(coalesce(p_subject, ''));
  p_body := btrim(coalesce(p_body, ''));
  if length(p_subject) < 2 or length(p_subject) > 200 then
    raise exception 'Subject must be between 2 and 200 characters';
  end if;
  if length(p_body) < 2 or length(p_body) > 10000 then
    raise exception 'Message must be between 2 and 10,000 characters';
  end if;

  -- Only one of the login's own active records.
  select * into owner_row from public.owners o
   where o.id = p_owner_id
     and o.id in (select public.current_owner_ids())
     and o.portal_activated
     and o.archived_at is null;
  if not found then raise exception 'Active owner portal access is required'; end if;

  select oc.association_id, oc.unit_id, a.portfolio_id, u.unit_number
    into occupancy_row
    from public.occupancies oc
    join public.associations a on a.id = oc.association_id and a.archived_at is null
    join public.units u on u.id = oc.unit_id
   where oc.owner_id = owner_row.id
     and oc.association_id = owner_row.association_id
     and oc.occupancy_type = 'owner'
     and oc.status = 'current'
   order by oc.created_at, oc.id
   limit 1;
  if not found then raise exception 'No active association occupancy was found'; end if;

  select id into existing_id from public.communications_log
   where sender_id = auth.uid() and idempotency_key = p_idempotency_key;
  if existing_id is not null then return existing_id; end if;

  if (
    select count(*) from public.communications_log
     where sender_id = auth.uid()
       and direction = 'inbound'
       and created_at >= now() - interval '1 hour'
  ) >= 10 then
    raise exception 'Message limit reached. Please wait before sending another message';
  end if;

  select coalesce(nullif(full_name, ''), nullif(email, ''), 'A homeowner'), email
    into sender_name, sender_email
    from public.profiles where id = auth.uid();
  sender_name := coalesce(sender_name, 'A homeowner');
  safe_body := replace(replace(replace(p_body, '&', '&amp;'), '<', '&lt;'), '>', '&gt;');

  insert into public.communications_log (
    portfolio_id, association_id, sender_id, direction, channel,
    recipient_count, status, subject, body, idempotency_key
  ) values (
    occupancy_row.portfolio_id, occupancy_row.association_id, auth.uid(),
    'inbound', 'email', 0, 'sent', p_subject, p_body, p_idempotency_key
  ) returning id into message_id;

  for recipient in
    with candidates as (
      select p.email, p.full_name as name, 1 as priority
        from public.associations a
        join public.profiles p on p.id = a.site_manager_user_id
       where a.id = occupancy_row.association_id and nullif(btrim(p.email), '') is not null and p.disabled_at is null
      union all
      select p.email, p.full_name, 2
        from public.profiles p
       where p.portfolio_id = occupancy_row.portfolio_id
         and p.hoa_role = 'company_admin'
         and nullif(btrim(p.email), '') is not null
         and p.disabled_at is null
      union all
      select p.support_email, p.company_name, 3
        from public.portfolios p
       where p.id = occupancy_row.portfolio_id
         and nullif(btrim(p.support_email), '') is not null
    ), selected as (
      select * from candidates where priority = (select min(priority) from candidates)
    )
    select distinct on (lower(email)) email, name from selected order by lower(email)
  loop
    insert into public.email_queue (
      to_email, to_name, subject, body, association_id, portfolio_id,
      sent_by, status, from_address, from_name, reply_to, communication_log_id
    ) values (
      recipient.email, recipient.name, '[Owner message] ' || p_subject,
      '<div style="font-family:system-ui,-apple-system,Segoe UI,Arial,sans-serif;white-space:pre-wrap;line-height:1.6;color:#111827">'
        || 'New message from ' || public.html_escape(sender_name)
        || case when occupancy_row.unit_number is null then '' else ' (Unit ' || public.html_escape(occupancy_row.unit_number) || ')' end
        || ' via the owner portal.' || E'\n\n' || safe_body || E'\n\n' || chr(8212) || ' Sent by ' || public.html_escape(sender_name)
        || case when sender_email is null then '' else ' &lt;' || public.html_escape(sender_email) || '&gt;' end || '</div>',
      occupancy_row.association_id, occupancy_row.portfolio_id,
      auth.uid(), 'pending', 'hello@portier369.com', null, sender_email, message_id
    );
    v_recipient_count := v_recipient_count + 1;
  end loop;

  if v_recipient_count = 0 then
    raise exception 'No management email recipient is configured for this association';
  end if;
  update public.communications_log set recipient_count = v_recipient_count
   where id = message_id;
  return message_id;
end;
$$;


ALTER FUNCTION "public"."submit_owner_message"("p_subject" "text", "p_body" "text", "p_idempotency_key" "uuid", "p_owner_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_purchase_order"("p_purchase_order_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  po_row public.purchase_orders;
  vendor_name text;
  request_id uuid;
  line_count integer;
  v_mode text;
  v_threshold numeric;
begin
  select * into po_row from public.purchase_orders where id = p_purchase_order_id for update;
  if not found then raise exception 'Purchase order not found'; end if;
  if not public.can_manage_finance(po_row.portfolio_id)
     or (po_row.association_id is not null and not public.can_manage_association(po_row.association_id)) then
    raise exception 'Permission denied';
  end if;
  if po_row.archived_at is not null or po_row.status = 'cancelled'::public.purchase_order_status then
    raise exception 'Cancelled purchase orders cannot be submitted';
  end if;
  if po_row.approval_status not in ('draft', 'rejected') then
    raise exception 'This purchase order has already been submitted';
  end if;
  select count(*) into line_count from public.purchase_order_line_items where purchase_order_id = p_purchase_order_id;
  if line_count = 0 or po_row.po_total <= 0 then raise exception 'Add at least one priced line item before submitting'; end if;

  -- purchase_orders_fixes: the association's board rules today decide, not
  -- the rules when the draft was saved (or generated from a recurring PO).
  select s.sends_pos_to_board, s.pos_threshold into v_mode, v_threshold
    from public.board_approval_settings s where s.association_id = po_row.association_id;
  v_mode := coalesce(v_mode, 'never');
  po_row.approval_required := v_mode = 'always' or (v_mode = 'over_threshold' and po_row.po_total >= coalesce(v_threshold, 0));
  update public.purchase_orders set approval_required = po_row.approval_required where id = p_purchase_order_id;

  if not po_row.approval_required then
    update public.purchase_orders
       set approval_status = 'approved',
           status = 'approved'::public.purchase_order_status,
           submitted_at = now(),
           approved_at = now(),
           approved_by = auth.uid(),
           decided_at = now(),
           decision_note = 'Approved within manager spending authority',
           -- purchase_orders_resubmit: a resubmitted PO that no longer needs
           -- the board drops its old (rejected) request; it stays as history.
           approval_request_id = null,
           updated_at = now()
     where id = p_purchase_order_id;
    return 'approved';
  end if;

  select name into vendor_name from public.vendors where id = po_row.vendor_id;
  request_id := public.open_board_approval_request(
    po_row.portfolio_id, po_row.association_id, po_row.vendor_id, 'purchase_order',
    'PO ' || coalesce(po_row.number, left(po_row.id::text, 8)) || ' — ' || coalesce(vendor_name, 'Vendor'),
    coalesce(po_row.description, po_row.notes), po_row.po_total, po_row.needed_by
  );
  update public.purchase_orders
     set approval_status = 'pending_approval',
         approval_request_id = request_id,
         submitted_at = now(),
         decided_at = null,
         decision_note = null,
         updated_at = now()
   where id = p_purchase_order_id;
  return 'pending_approval';
end;
$$;


ALTER FUNCTION "public"."submit_purchase_order"("p_purchase_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_tenant_message"("p_subject" "text", "p_body" "text", "p_idempotency_key" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
declare
  v_tenant public.tenants%rowtype;
  v_association_id uuid;
  v_unit_number text;
  v_message_id uuid;
  v_existing_id uuid;
  v_sender_name text;
  v_sender_email text;
  v_safe_body text;
  v_recipient record;
  v_recipient_count integer := 0;
begin
  if auth.uid() is null or not public.is_tenant_user() then
    raise exception 'Resident portal access is required';
  end if;
  if p_idempotency_key is null then
    raise exception 'Message request key is required';
  end if;

  p_subject := btrim(coalesce(p_subject, ''));
  p_body := btrim(coalesce(p_body, ''));
  if char_length(p_subject) < 2 or char_length(p_subject) > 200 then
    raise exception 'Subject must be between 2 and 200 characters';
  end if;
  if char_length(p_body) < 2 or char_length(p_body) > 10000 then
    raise exception 'Message must be between 2 and 10000 characters';
  end if;

  select t.* into v_tenant
  from public.tenants t
  where t.id = public.current_tenant_id();
  if not found then
    raise exception 'No active resident record was found';
  end if;

  select b.association_id, u.unit_number
    into v_association_id, v_unit_number
  from public.units u
  join public.buildings b on b.id = u.building_id
  where u.id = v_tenant.unit_id and u.archived_at is null;
  if v_association_id is null then
    raise exception 'No active association was found for this resident';
  end if;

  select id into v_existing_id
  from public.communications_log
  where sender_id = auth.uid() and idempotency_key = p_idempotency_key;
  if v_existing_id is not null then
    return v_existing_id;
  end if;

  if (
    select count(*)
    from public.communications_log
    where sender_id = auth.uid()
      and direction = 'inbound'
      and created_at >= now() - interval '1 hour'
  ) >= 10 then
    raise exception 'Message limit reached. Please wait before sending another message';
  end if;

  v_sender_name := nullif(btrim(concat_ws(' ', v_tenant.first_name, v_tenant.last_name)), '');
  v_sender_name := coalesce(v_sender_name, 'A resident');
  v_sender_email := v_tenant.email;
  v_safe_body := replace(replace(replace(p_body, '&', '&amp;'), '<', '&lt;'), '>', '&gt;');

  insert into public.communications_log (
    portfolio_id, association_id, sender_id, direction, channel,
    recipient_count, status, subject, body, idempotency_key
  ) values (
    v_tenant.portfolio_id, v_association_id, auth.uid(), 'inbound', 'email',
    0, 'sent', p_subject, p_body, p_idempotency_key
  ) returning id into v_message_id;

  for v_recipient in
    with candidates as (
      select p.email, p.full_name as name, 1 as priority
      from public.associations a
      join public.profiles p on p.id = a.site_manager_user_id
      where a.id = v_association_id and nullif(btrim(p.email), '') is not null and p.disabled_at is null
      union all
      select p.email, p.full_name, 2
      from public.profiles p
      where p.portfolio_id = v_tenant.portfolio_id
        and p.hoa_role = 'company_admin'
        and p.disabled_at is null
        and nullif(btrim(p.email), '') is not null
      union all
      select p.support_email, p.company_name, 3
      from public.portfolios p
      where p.id = v_tenant.portfolio_id
        and nullif(btrim(p.support_email), '') is not null
    ), selected as (
      select * from candidates where priority = (select min(priority) from candidates)
    )
    select distinct on (lower(email)) email, name
    from selected
    order by lower(email)
  loop
    insert into public.email_queue (
      to_email, to_name, subject, body, association_id, portfolio_id,
      sent_by, status, from_address, from_name, reply_to, communication_log_id
    ) values (
      v_recipient.email,
      v_recipient.name,
      '[Resident message] ' || p_subject,
      '<div style="font-family:system-ui,-apple-system,Segoe UI,Arial,sans-serif;white-space:pre-wrap;line-height:1.6;color:#111827">'
        || 'New message from ' || public.html_escape(v_sender_name)
        || case when v_unit_number is null then '' else ' (Unit ' || public.html_escape(v_unit_number) || ')' end
        || ' via the resident portal.' || E'\n\n' || v_safe_body || E'\n\n— Sent by ' || public.html_escape(v_sender_name)
        || case when v_sender_email is null then '' else ' &lt;' || public.html_escape(v_sender_email) || '&gt;' end || '</div>',
      v_association_id,
      v_tenant.portfolio_id,
      auth.uid(),
      'pending',
      'hello@portier369.com',
      null,
      v_sender_email,
      v_message_id
    );
    v_recipient_count := v_recipient_count + 1;
  end loop;

  if v_recipient_count = 0 then
    raise exception 'No management email recipient is configured for this association';
  end if;

  update public.communications_log
     set recipient_count = v_recipient_count
   where id = v_message_id;
  return v_message_id;
end;
$$;


ALTER FUNCTION "public"."submit_tenant_message"("p_subject" "text", "p_body" "text", "p_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_tenant_service_request"("p_unit_id" "uuid", "p_description" "text", "p_priority" "public"."service_request_priority" DEFAULT 'normal'::"public"."service_request_priority", "p_permission_to_enter" boolean DEFAULT false, "p_access_notes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_tenant public.tenants%rowtype;
  v_association_id uuid;
  v_request_id uuid;
  v_description text;
begin
  if auth.uid() is null or not public.is_tenant_user() then
    raise exception 'Resident portal access is required';
  end if;

  v_description := btrim(coalesce(p_description, ''));
  if char_length(v_description) < 10 or char_length(v_description) > 10000 then
    raise exception 'Description must be between 10 and 10000 characters';
  end if;
  if p_access_notes is not null and char_length(p_access_notes) > 2000 then
    raise exception 'Access notes must be 2000 characters or fewer';
  end if;

  select t.*
    into v_tenant
  from public.tenants t
  where t.id in (select public.current_tenant_ids())
    and t.unit_id = p_unit_id
  order by t.created_at, t.id
  limit 1;

  if not found then
    raise exception 'Unit is not linked to this resident account';
  end if;

  select b.association_id
    into v_association_id
  from public.units u
  join public.buildings b on b.id = u.building_id
  join public.associations a on a.id = b.association_id
  where u.id = v_tenant.unit_id
    and u.archived_at is null
    and b.archived_at is null
    and a.archived_at is null
    and a.portfolio_id = v_tenant.portfolio_id
    and (v_tenant.association_id is null or v_tenant.association_id = a.id);

  if v_association_id is null
     or (v_tenant.association_id is not null and v_tenant.association_id <> v_association_id) then
    raise exception 'Resident unit association is invalid';
  end if;

  if nullif(btrim(coalesce(p_access_notes, '')), '') is not null then
    v_description := v_description || E'\n\nAccess notes: ' || btrim(p_access_notes);
  end if;

  insert into public.service_requests (
    portfolio_id,
    association_id,
    unit_id,
    tenant_id,
    homeowner_id,
    owner_id,
    description,
    priority,
    permission_to_enter,
    source,
    status,
    created_by
  ) values (
    v_tenant.portfolio_id,
    v_association_id,
    v_tenant.unit_id,
    v_tenant.id,
    null,
    null,
    v_description,
    coalesce(p_priority, 'normal'),
    coalesce(p_permission_to_enter, false),
    'resident',
    'open',
    auth.uid()
  )
  returning id into v_request_id;

  return v_request_id;
end;
$$;


ALTER FUNCTION "public"."submit_tenant_service_request"("p_unit_id" "uuid", "p_description" "text", "p_priority" "public"."service_request_priority", "p_permission_to_enter" boolean, "p_access_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_vendor_invoice"("p_work_order_id" "uuid", "p_bill_number" "text", "p_bill_date" "date", "p_due_date" "date", "p_amount" numeric, "p_memo" "text", "p_attachment_path" "text", "p_file_name" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_vendor_id uuid;
  v_portfolio_id uuid;
  v_association_id uuid;
  v_bill_id uuid := gen_random_uuid();
  v_bill_number text := trim(p_bill_number);
  v_file_name text := trim(p_file_name);
  v_status text;
  v_po_id uuid;
  v_po_count integer;
  v_board_mode text;
  v_board_threshold numeric;
  v_requires_board boolean;
begin
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;

  if not exists (select 1 from public.current_vendor_ids()) then
    raise exception 'Active vendor portal access is required';
  end if;

  select wo.vendor_id, wo.portfolio_id, wo.association_id, wo.status::text
    into v_vendor_id, v_portfolio_id, v_association_id, v_status
  from public.work_orders wo
  where wo.id = p_work_order_id
    and wo.vendor_id in (select public.current_vendor_ids())
    and wo.archived_at is null;

  if v_vendor_id is null or v_portfolio_id is null or v_association_id is null then
    raise exception 'Assigned work order not found';
  end if;
  if v_status not in ('done', 'completed', 'billed', 'closed') then
    raise exception 'Mark the job done before sending an invoice';
  end if;
  select count(*), min(po.id::text)::uuid into v_po_count, v_po_id
    from public.purchase_orders po
   where po.work_order_id = p_work_order_id
     and po.vendor_id = v_vendor_id
     and po.approval_status = 'approved'
     and po.cancelled_at is null
     and po.archived_at is null;
  if v_po_count > 1 then
    raise exception 'This job has more than one approved purchase order. Ask management which one applies before sending the invoice';
  elsif v_po_count = 0 then
    v_po_id := null;
  end if;
  if v_bill_number = '' or char_length(v_bill_number) > 100 then
    raise exception 'Invoice number must be 1 to 100 characters';
  end if;
  if p_amount is null or p_amount <= 0 or scale(p_amount) > 2 then
    raise exception 'Invoice amount must be positive with no more than two decimal places';
  end if;
  if p_bill_date is null then
    raise exception 'Invoice date is required';
  end if;
  if p_bill_date > coalesce(public.association_local_date(v_association_id, now()), current_date) + 30 then
    raise exception 'Invoice date can''t be more than 30 days ahead';
  end if;
  if p_due_date is not null and p_due_date < p_bill_date then
    raise exception 'Due date cannot be before invoice date';
  end if;
  if p_memo is not null and char_length(p_memo) > 1000 then
    raise exception 'Memo must be 1,000 characters or fewer';
  end if;
  if v_file_name = '' or char_length(v_file_name) > 255 then
    raise exception 'Invoice file name is invalid';
  end if;
  if p_attachment_path not like 'vendors/' || v_vendor_id::text || '/invoice/%'
     or not public.document_path_matches_entity('vendor', v_vendor_id, p_attachment_path) then
    raise exception 'Invalid invoice attachment reference';
  end if;

  -- Serialize a vendor/invoice-number pair so rapid retries cannot create two
  -- accounting records even without a broad index over historical data.
  perform pg_advisory_xact_lock(hashtextextended(v_vendor_id::text || ':' || lower(v_bill_number), 0));
  if exists (
    select 1 from public.payable_bills pb
    where pb.vendor_id = v_vendor_id
      and pb.archived_at is null
      and lower(trim(pb.bill_number)) = lower(v_bill_number)
  ) then
    raise exception 'Invoice number already exists for this vendor';
  end if;

  -- Board approval follows the association's setting, as for a bill staff
  -- enter. Staff set the expense account before approving.
  select coalesce(s.sends_bills_to_board, 'never'), s.bills_threshold
    into v_board_mode, v_board_threshold
    from public.board_approval_settings s
   where s.association_id = v_association_id;
  v_requires_board := coalesce(coalesce(v_board_mode, 'never') = 'always'
    or (v_board_mode = 'over_threshold' and p_amount >= coalesce(v_board_threshold, 0)), false);

  insert into public.payable_bills (
    id, portfolio_id, vendor_id, association_id, work_order_id, purchase_order_id,
    bill_number, bill_date, due_date, occurred_on, amount, memo,
    status, approval_required, created_by
  ) values (
    v_bill_id, v_portfolio_id, v_vendor_id, v_association_id, p_work_order_id, v_po_id,
    v_bill_number, p_bill_date, p_due_date, p_bill_date, p_amount, nullif(trim(p_memo), ''),
    'pending_approval', v_requires_board, auth.uid()
  );

  insert into public.documents (
    entity_type, entity_id, doc_type, file_name, file_url, uploaded_by
  ) values (
    'vendor', v_vendor_id, 'vendor_invoice', v_file_name, p_attachment_path, auth.uid()
  );

  return v_bill_id;
end;
$$;


ALTER FUNCTION "public"."submit_vendor_invoice"("p_work_order_id" "uuid", "p_bill_number" "text", "p_bill_date" "date", "p_due_date" "date", "p_amount" numeric, "p_memo" "text", "p_attachment_path" "text", "p_file_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_vendor_request_upload"("p_token_hash" "text", "p_path" "text", "p_file_name" "text", "p_expires_on" "date") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare r record; v_doc uuid;
begin
  select req.* into r
    from public.document_request_links l join public.document_requests req on req.id = l.request_id
   where l.token_hash = p_token_hash and l.expires_at > now()
   for update of req;
  if not found then raise exception 'This upload link is not valid' using errcode = 'P0002'; end if;
  if r.status::text not in ('requested', 'in_progress', 'rejected') then
    raise exception 'This request has already been answered' using errcode = '55000';
  end if;
  if p_path is null or p_path not like 'vendors/' || r.vendor_id::text || '/compliance/%' or p_path ~ '\.\.' then
    raise exception 'Invalid document reference' using errcode = '22023';
  end if;
  if p_expires_on is not null and (p_expires_on < current_date - 1 or p_expires_on > current_date + 3660) then
    raise exception 'Enter the expiration date shown on the document' using errcode = '22023';
  end if;
  insert into public.documents (entity_type, entity_id, doc_type, file_name, file_url, expires_at)
  values ('vendor', r.vendor_id,
          case when r.doc_type in ('workers_comp', 'general_liability', 'auto_insurance', 'epa_certification', 'state_license', 'contract', 'w9') then r.doc_type else 'other' end,
          left(coalesce(nullif(btrim(p_file_name), ''), 'document'), 200), p_path,
          case when p_expires_on is not null then p_expires_on::timestamptz end)
  returning id into v_doc;
  update public.document_requests
     set status = 'submitted', submitted_at = now(), updated_at = now(),
         attachment_urls = coalesce(attachment_urls, '[]'::jsonb) || to_jsonb(p_path)
   where id = r.id;
  insert into public.audit_logs (portfolio_id, entity_type, entity_id, action, changes)
  values (r.portfolio_id, 'vendor', r.vendor_id, 'vendor_document_submitted',
          jsonb_build_object('request_id', r.id, 'document_id', v_doc, 'doc_type', r.doc_type, 'expires_on', p_expires_on, 'via', 'upload_link'));
  return v_doc;
end $$;


ALTER FUNCTION "public"."submit_vendor_request_upload"("p_token_hash" "text", "p_path" "text", "p_file_name" "text", "p_expires_on" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."subscribe_association_to_charge"("p_association_id" "uuid", "p_charge_category_id" "uuid", "p_amount" numeric DEFAULT NULL::numeric, "p_frequency" "public"."recurring_frequency" DEFAULT NULL::"public"."recurring_frequency") RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare cat public.charge_categories; unit_row record; n integer := 0;
begin
  select * into cat from public.charge_categories where id = p_charge_category_id;
  if not found then raise exception 'charge category not found'; end if;
  if not public.can_manage_finance(cat.portfolio_id) then raise exception 'permission denied'; end if;
  for unit_row in
    select u.id from public.units u
    join public.buildings b on b.id = u.building_id
    where b.association_id = p_association_id and u.archived_at is null
  loop
    insert into public.unit_recurring_charges (
      unit_id, charge_category_id, amount, frequency, created_by
    ) values (
      unit_row.id, p_charge_category_id,
      coalesce(p_amount, cat.default_amount),
      coalesce(p_frequency, cat.default_frequency),
      auth.uid()
    ) on conflict do nothing;
    n := n + 1;
  end loop;
  return n;
end;
$$;


ALTER FUNCTION "public"."subscribe_association_to_charge"("p_association_id" "uuid", "p_charge_category_id" "uuid", "p_amount" numeric, "p_frequency" "public"."recurring_frequency") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."unit_recurring_charges" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "unit_id" "uuid" NOT NULL,
    "charge_category_id" "uuid" NOT NULL,
    "amount" numeric(12,2) NOT NULL,
    "frequency" "public"."recurring_frequency" DEFAULT 'monthly'::"public"."recurring_frequency" NOT NULL,
    "start_date" "date" DEFAULT CURRENT_DATE NOT NULL,
    "end_date" "date",
    "next_post_date" "date" DEFAULT CURRENT_DATE NOT NULL,
    "last_posted_at" timestamp with time zone,
    "memo" "text",
    "active" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid",
    "identifier" "text",
    CONSTRAINT "unit_recurring_charges_amount_check" CHECK (("amount" >= (0)::numeric)),
    CONSTRAINT "unit_recurring_charges_check" CHECK ((("end_date" IS NULL) OR ("end_date" >= "start_date")))
);


ALTER TABLE "public"."unit_recurring_charges" OWNER TO "postgres";


COMMENT ON COLUMN "public"."unit_recurring_charges"."identifier" IS 'Optional asset identifier for this fee, e.g. parking space # or locker #.';



CREATE OR REPLACE FUNCTION "public"."subscribe_unit_to_charge"("p_unit_id" "uuid", "p_charge_category_id" "uuid", "p_amount" numeric DEFAULT NULL::numeric, "p_frequency" "public"."recurring_frequency" DEFAULT NULL::"public"."recurring_frequency", "p_start_date" "date" DEFAULT NULL::"date", "p_memo" "text" DEFAULT NULL::"text") RETURNS "public"."unit_recurring_charges"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare cat public.charge_categories; row public.unit_recurring_charges; v_start date;
begin
  select * into cat from public.charge_categories where id = p_charge_category_id;
  if not found then raise exception 'charge category not found'; end if;
  if not public.can_manage_finance(cat.portfolio_id) then raise exception 'permission denied'; end if;
  -- fix: a blank start date is the association's today, not UTC's (the unit
  -- read under the caller's own access).
  v_start := p_start_date;
  if v_start is null then
    select public.association_local_date(b.association_id) into v_start
      from public.units u join public.buildings b on b.id = u.building_id
     where u.id = p_unit_id;
    if v_start is null then raise exception 'unit not found'; end if;
  end if;
  insert into public.unit_recurring_charges (
    unit_id, charge_category_id, amount, frequency, start_date, next_post_date, memo, created_by
  ) values (
    p_unit_id, p_charge_category_id,
    coalesce(p_amount, cat.default_amount),
    coalesce(p_frequency, cat.default_frequency),
    v_start, v_start, p_memo, auth.uid()
  ) returning * into row;
  return row;
end;
$$;


