CREATE OR REPLACE FUNCTION "public"."suggest_bank_transaction_payment"("p_id" "uuid") RETURNS TABLE("unit_id" "uuid", "unit_label" "text", "owner_name" "text", "confidence" numeric, "reason" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
#variable_conflict use_column
declare
  t public.bank_transactions;
  b public.bank_accounts;
  v_assocs uuid[];
  p record;
  m record;
  r record;
  v_sender text;
  v_key text;
  v_amount numeric;
  v_tokens text[];
  v_tok text;
  v_assoc uuid;
  v_found boolean := false;
  v_n int;
  v_names jsonb;
  c jsonb := '{}'::jsonb;  -- unit_id -> {"c": confidence, "r": reason}
begin
  select * into t from public.bank_transactions bt where bt.id = p_id;
  if not found then raise exception 'Bank transaction not found' using errcode = 'P0002'; end if;
  select * into b from public.bank_accounts ba where ba.id = t.bank_account_id;
  if b.id is null or not public.can_manage_finance(b.portfolio_id)
     or (b.association_id is not null and not public.can_view_association_row(b.association_id)) then
    raise exception 'Bank transaction not found' using errcode = 'P0002';
  end if;
  -- Only money coming in that is still open.
  if t.amount is null or t.amount >= 0 or t.pending or t.ignored_at is not null or t.matched_at is not null
     or t.matched_journal_line_id is not null or t.matched_bank_deposit_id is not null then
    return;
  end if;
  select coalesce(array_agg(x), '{}') into v_assocs
    from unnest(public.app_bank_account_association_ids(b.id)) x
   where public.can_view_association_row(x);
  if cardinality(v_assocs) = 0 then return; end if;

  v_amount := round(-t.amount, 2);
  select * into p from public.parse_bank_payment_description(coalesce(nullif(btrim(t.original_description), ''), t.name));
  v_sender := coalesce(nullif(btrim(t.payer_name), ''), p.sender);
  v_key := public.payment_sender_key(v_sender);
  -- A remembered sender is a name of two words or more: a single word
  -- ("CHK" from "ONLINE TRANSFER FROM CHK 1234") would match unrelated credits.
  if position(' ' in coalesce(v_key, '')) = 0 then v_key := null; end if;

  -- 1. Remembered sender.
  if v_key is not null then
    for r in
      select a.unit_id, a.last_used_at,
             exists (select 1 from public.occupancies o
                      where o.unit_id = a.unit_id and o.status = 'current' and o.occupancy_type = 'owner'
                        and o.move_in_date > a.last_used_at::date) as new_owner
        from public.payment_sender_aliases a join public.units u on u.id = a.unit_id
       where a.association_id = any (v_assocs) and a.sender_key = v_key and u.archived_at is null
    loop
      if r.new_owner then
        c := c || jsonb_build_object(r.unit_id::text, jsonb_build_object('c', 0.60, 'r', 'Remembered sender (the unit has a new owner since)'));
      else
        c := c || jsonb_build_object(r.unit_id::text, jsonb_build_object('c', 0.98, 'r', 'Remembered sender'));
      end if;
    end loop;
  end if;

  -- 2. Unit number in the memo (the lockbox matcher's unit step).
  if nullif(btrim(coalesce(p.memo, t.payment_reason, '')), '') is not null then
    v_tok := btrim(coalesce(p.memo, t.payment_reason));
    v_tokens := array[v_tok];
    v_tokens := v_tokens || coalesce((select array_agg(x[1]) from regexp_matches(v_tok, '(?:unit|apt|apartment|suite|ste|#)\s*#?\s*([A-Za-z0-9-]+)', 'gi') x), '{}');
    v_tokens := v_tokens || coalesce((select array_agg(w) from (select w from unnest(regexp_split_to_array(v_tok, '[\s,;:#]+')) w where w <> '' limit 8) s), '{}');
    <<tokens>>
    foreach v_tok in array v_tokens loop
      foreach v_assoc in array v_assocs loop
        select * into m from public.lockbox_match_unit(v_assoc, v_tok, null, null);
        if m.unit_id is not null and m.reason = 'Unit number' then
          if coalesce((c -> m.unit_id::text ->> 'c')::numeric, 0) < 0.95 then
            c := c || jsonb_build_object(m.unit_id::text, jsonb_build_object('c', 0.95, 'r', format('Unit number in the memo (%s)', v_tok)));
          end if;
          v_found := true;
        end if;
      end loop;
      exit tokens when v_found;
    end loop;
  end if;

  -- 3. Sender name against the current owners' names.
  if v_sender is not null then
    -- One pass over the current owners (at most 10 matching units kept).
    select coalesce(jsonb_agg(jsonb_build_object('u', m2.unit_id, 'n', m2.full_name)), '[]'::jsonb) into v_names
      from (select o.unit_id, min(w.full_name) as full_name
              from public.occupancies o join public.owners w on w.id = o.owner_id
             where o.association_id = any (v_assocs) and o.status = 'current' and o.occupancy_type = 'owner'
               and public.payer_name_matches(v_sender, w.first_name, w.last_name, w.full_name)
             group by o.unit_id
             limit 10) m2;
    v_n := jsonb_array_length(v_names);
    for r in select x ->> 'u' as unit_id, x ->> 'n' as full_name from jsonb_array_elements(v_names) x loop
      if coalesce((c -> r.unit_id ->> 'c')::numeric, 0) < (case when v_n = 1 then 0.80 else 0.60 end) then
        c := c || jsonb_build_object(r.unit_id, jsonb_build_object(
               'c', case when v_n = 1 then 0.80 else 0.60 end,
               'r', format('Sender name matches owner %s', r.full_name)));
      end if;
    end loop;
  end if;

  -- 4. Amount equal to the open balance: a tie-breaker for the candidates
  --    above, or on its own when it points at exactly one unit.
  if c <> '{}'::jsonb then
    for r in
      select k.key::uuid as unit_id
        from jsonb_each(c) k
       where round(coalesce((select sum(ch.amount - coalesce((select sum(pa.amount_applied) from public.payment_applications pa where pa.charge_id = ch.id), 0))
                               from public.charges ch where ch.unit_id = k.key::uuid), 0), 2) = v_amount
    loop
      c := jsonb_set(c, array[r.unit_id::text], jsonb_build_object(
             'c', least(0.99, (c -> r.unit_id::text ->> 'c')::numeric + 0.04),
             'r', (c -> r.unit_id::text ->> 'r') || ' ' || chr(183) || ' amount equals the open balance'));
    end loop;
  else
    foreach v_assoc in array v_assocs loop
      select * into m from public.lockbox_match_unit(v_assoc, null, null, v_amount);
      if m.unit_id is not null then
        c := c || jsonb_build_object(m.unit_id::text, jsonb_build_object('c', 0.50, 'r', 'Amount equals the open balance'));
      end if;
    end loop;
  end if;

  return query
    select u.id,
           case when cardinality(v_assocs) > 1 then format('Unit %s %s %s', u.unit_number, chr(183), a.name) else format('Unit %s', u.unit_number) end,
           (select string_agg(w.full_name, ' & ' order by o.is_primary desc nulls last, w.full_name)
              from public.occupancies o join public.owners w on w.id = o.owner_id
             where o.unit_id = u.id and o.status = 'current' and o.occupancy_type = 'owner'),
           (k.value ->> 'c')::numeric,
           k.value ->> 'r'
      from jsonb_each(c) k
      join public.units u on u.id = k.key::uuid
      join public.buildings bl on bl.id = u.building_id
      join public.associations a on a.id = bl.association_id
     where bl.association_id = any (v_assocs) and u.archived_at is null
     order by (k.value ->> 'c')::numeric desc, u.unit_number
     limit 10;
end
$$;


ALTER FUNCTION "public"."suggest_bank_transaction_payment"("p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."suggest_bank_transaction_payments"("p_ids" "uuid"[]) RETURNS TABLE("transaction_id" "uuid", "unit_id" "uuid", "unit_label" "text", "owner_name" "text", "confidence" numeric, "reason" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_id uuid;
begin
  if p_ids is null then return; end if;
  if cardinality(p_ids) > 100 then
    raise exception 'Ask for at most 100 bank transactions at a time' using errcode = '22023';
  end if;
  foreach v_id in array p_ids loop
    begin
      return query select v_id, s.unit_id, s.unit_label, s.owner_name, s.confidence, s.reason
                     from public.suggest_bank_transaction_payment(v_id) s;
    exception when sqlstate 'P0002' then
      null;  -- not found or not the caller's: no suggestions
    end;
  end loop;
end
$$;


ALTER FUNCTION "public"."suggest_bank_transaction_payments"("p_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."supersede_year_end_package"("p_package_id" "uuid", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare pkg public.year_end_packages;
begin
  select * into pkg from public.year_end_packages where id = p_package_id for update;
  if not found then raise exception 'Package not found'; end if;
  if not (public.can_admin_portfolio(pkg.portfolio_id) or public.is_platform_operator()) then
    raise exception 'Only a portfolio administrator can supersede a finalized package' using errcode = '42501';
  end if;
  if pkg.status <> 'finalized' then raise exception 'Only a finalized package can be superseded'; end if;
  if char_length(btrim(coalesce(p_reason, ''))) < 20 then raise exception 'Explain why the package is being superseded (20+ characters)'; end if;
  update public.year_end_packages set status = 'superseded', superseded_by = auth.uid(), superseded_at = now(), supersede_reason = btrim(p_reason) where id = p_package_id;
  insert into public.audit_logs (portfolio_id, entity_type, entity_id, action, actor_id, changes)
  values (pkg.portfolio_id, 'association', pkg.association_id, 'year_end_package_superseded', auth.uid(),
          jsonb_build_object('package_id', pkg.id, 'fiscal_year', pkg.fiscal_year, 'reason', btrim(p_reason)));
end;
$$;


ALTER FUNCTION "public"."supersede_year_end_package"("p_package_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."suspend_portfolio"("p_portfolio_id" "uuid", "p_reason" "text") RETURNS "public"."portfolios"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  updated public.portfolios;
begin
  if not (public.is_platform_operator() and public.is_platform_admin()) then
    raise exception 'suspend_portfolio: platform administrator required';
  end if;

  update public.portfolios
     set suspended_at = now(), suspension_reason = p_reason, updated_at = now()
   where id = p_portfolio_id
   returning * into updated;

  update public.subscriptions set status = 'paused', updated_at = now()
   where portfolio_id = p_portfolio_id;

  insert into public.permission_audit_log (
    actor_user_id, actor_portfolio_id, target_entity_type, target_entity_id,
    action, details
  ) values (
    auth.uid(), null, 'portfolio', p_portfolio_id,
    'suspended',
    jsonb_build_object('reason', p_reason)
  );
  return updated;
end;
$$;


ALTER FUNCTION "public"."suspend_portfolio"("p_portfolio_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_association_unit_count"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  affected uuid[];
begin
  select array_agg(distinct b.association_id) into affected
  from public.buildings b
  where b.id in (coalesce(new.building_id, old.building_id), coalesce(old.building_id, new.building_id));

  update public.associations a
  set unit_count = (
    select count(*) from public.units u
    join public.buildings b on b.id = u.building_id
    where b.association_id = a.id
  )
  where a.id = any(affected);

  return coalesce(new, old);
end;
$$;


ALTER FUNCTION "public"."sync_association_unit_count"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_owner_delinquency_cases"("p_portfolio_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  synced_count integer := 0;
  cured_count integer := 0;
begin
  if not (public.can_access_portfolio(p_portfolio_id) and (public.is_any_staff() or public.is_company_admin() or public.is_platform_operator())) then
    raise exception 'Not authorized to synchronize delinquency cases';
  end if;

  insert into public.delinquency_cases (
    portfolio_id, association_id, policy_id, unit_id, owner_id,
    status, balance_snapshot, oldest_due_date, last_synced_at
  )
  select
    p_portfolio_id,
    due.association_id,
    policy.id,
    due.unit_id,
    ownership.owner_id,
    'open',
    due.balance,
    due.oldest_due,
    now()
  from public.delinquent_units due
  join public.associations association on association.id = due.association_id
  left join public.delinquency_policies policy
    on policy.association_id = due.association_id and policy.active
  left join lateral (
    select unit_owner.owner_id
    from public.unit_owners unit_owner
    where unit_owner.unit_id = due.unit_id and unit_owner.end_date is null
    order by unit_owner.is_primary desc, unit_owner.start_date desc
    limit 1
  ) ownership on true
  where association.portfolio_id = p_portfolio_id
    and due.unit_id is not null
    and public.can_view_association_row(due.association_id)
    and due.balance >= coalesce(policy.minimum_balance, 0)
  on conflict (unit_id) do update
    set association_id = excluded.association_id,
        policy_id = excluded.policy_id,
        owner_id = excluded.owner_id,
        balance_snapshot = excluded.balance_snapshot,
        oldest_due_date = excluded.oldest_due_date,
        last_synced_at = now(),
        resolved_at = null,
        status = case
          when delinquency_cases.status = 'resolved'
            or (delinquency_cases.owner_id is not null and excluded.owner_id is distinct from delinquency_cases.owner_id)
          then 'open' else delinquency_cases.status end,
        current_step_number = case
          when delinquency_cases.status = 'resolved'
            or (delinquency_cases.owner_id is not null and excluded.owner_id is distinct from delinquency_cases.owner_id)
          then 0 else delinquency_cases.current_step_number end,
        next_action_at = case
          when delinquency_cases.status = 'resolved'
            or (delinquency_cases.owner_id is not null and excluded.owner_id is distinct from delinquency_cases.owner_id)
          then null else delinquency_cases.next_action_at end,
        hold_reason = case
          when delinquency_cases.status = 'resolved'
            or (delinquency_cases.owner_id is not null and excluded.owner_id is distinct from delinquency_cases.owner_id)
          then null else delinquency_cases.hold_reason end,
        legal_reviewed_at = case
          when delinquency_cases.status = 'resolved'
            or (delinquency_cases.owner_id is not null and excluded.owner_id is distinct from delinquency_cases.owner_id)
          then null else delinquency_cases.legal_reviewed_at end,
        legal_reviewed_by = case
          when delinquency_cases.status = 'resolved'
            or (delinquency_cases.owner_id is not null and excluded.owner_id is distinct from delinquency_cases.owner_id)
          then null else delinquency_cases.legal_reviewed_by end,
        legal_review_note = case
          when delinquency_cases.status = 'resolved'
            or (delinquency_cases.owner_id is not null and excluded.owner_id is distinct from delinquency_cases.owner_id)
          then null else delinquency_cases.legal_review_note end
    where public.can_view_association_row(delinquency_cases.association_id);
  get diagnostics synced_count = row_count;

  with cured as (
    update public.delinquency_cases case_record
    set status = 'resolved', resolved_at = now(), balance_snapshot = 0, last_synced_at = now()
    where case_record.portfolio_id = p_portfolio_id
      and case_record.status not in ('resolved', 'closed')
      and public.can_view_association_row(case_record.association_id)
      and not exists (
        select 1
        from public.delinquent_units due
        left join public.delinquency_policies policy
          on policy.association_id = due.association_id and policy.active
        where due.unit_id = case_record.unit_id
          and due.balance >= coalesce(policy.minimum_balance, 0)
      )
    returning case_record.id
  ), logged as (
    insert into public.delinquency_case_events (case_id, event_type, balance_snapshot, note)
    select id, 'balance_cured', 0, 'Resolved after ledger sync confirmed no qualifying overdue balance.'
    from cured returning 1
  )
  select count(*) into cured_count from logged;

  return jsonb_build_object('synced', synced_count, 'cured', cured_count);
end;
$$;


ALTER FUNCTION "public"."sync_owner_delinquency_cases"("p_portfolio_id" "uuid") OWNER TO "postgres";


