CREATE OR REPLACE FUNCTION "public"."tenant_service_request_scope_valid"("p_tenant_id" "uuid", "p_portfolio_id" "uuid", "p_association_id" "uuid", "p_unit_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$#variable_conflict use_column
begin
  return (select s.x from (

  select exists (
    select 1
    from public.tenants t
    join public.units u on u.id = t.unit_id
    join public.buildings b on b.id = u.building_id
    join public.associations a on a.id = b.association_id
    where t.id = p_tenant_id
      and t.id in (select public.current_tenant_ids())
      and t.portfolio_id = p_portfolio_id
      and t.unit_id = p_unit_id
      and a.portfolio_id = t.portfolio_id
      and a.id = p_association_id
      and (t.association_id is null or t.association_id = a.id)
      and t.archived_at is null
      and u.archived_at is null
      and b.archived_at is null
      and a.archived_at is null
  )
  ) s(x) limit 1);
end$$;


