CREATE OR REPLACE FUNCTION "public"."triage_service_request_to_work_order"("p_service_request_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_request public.service_requests%rowtype;
  v_work_order_id uuid;
  v_requestor text;
begin
  if auth.uid() is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  if p_service_request_id is null then
    raise exception 'Service request is required' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_service_request_id::text, 0));

  select * into v_request
  from public.service_requests sr
  where sr.id = p_service_request_id
    and sr.archived_at is null
  for update;

  if not found then
    raise exception 'Service request not found' using errcode = 'P0002';
  end if;

  if not (
    public.is_platform_operator()
    or (
      (public.is_any_staff() or public.is_company_admin())
      and public.can_access_portfolio(v_request.portfolio_id)
      and public.can_manage_association(v_request.association_id)
    )
  ) then
    raise exception 'Not authorized for this service request' using errcode = '42501';
  end if;

  select wo.id into v_work_order_id
  from public.work_orders wo
  where wo.service_request_id = v_request.id
    and wo.archived_at is null
    and wo.status not in ('done', 'completed', 'billed', 'closed', 'cancelled')
  order by wo.created_at, wo.id
  limit 1;
  if v_work_order_id is not null then
    return v_work_order_id;
  end if;
  -- work_orders_fixes: a finished work order is not replaced by a new one.
  if exists (
    select 1 from public.work_orders wo
     where wo.service_request_id = v_request.id
       and wo.archived_at is null
       and wo.status::text <> 'cancelled'
  ) then
    raise exception 'This request already has a work order' using errcode = '23505';
  end if;

  if v_request.status in ('completed', 'cancelled') then
    raise exception 'Only open service requests can be triaged' using errcode = '23514';
  end if;

  v_requestor := case when v_request.tenant_id is not null then 'Resident portal' else 'Owner portal' end;

  insert into public.work_orders (
    portfolio_id,
    association_id,
    unit_id,
    service_request_id,
    title,
    issue,
    description,
    category,
    priority,
    requested_by,
    status,
    created_by
  ) values (
    v_request.portfolio_id,
    v_request.association_id,
    v_request.unit_id,
    v_request.id,
    left(regexp_replace(v_request.description, E'[\\n\\r]+', ' ', 'g'), 80),
    v_request.description,
    left(v_request.description, 2000),
    coalesce(v_request.category, 'general_repair'),
    v_request.priority::text::public.work_order_priority,
    v_requestor,
    'new',
    auth.uid()
  ) returning id into v_work_order_id;

  insert into public.work_order_updates (
    work_order_id,
    note,
    new_status,
    created_by
  ) values (
    v_work_order_id,
    'Created from service request ' || coalesce(v_request.number, left(v_request.id::text, 8)),
    'new',
    auth.uid()
  );

  update public.service_requests
  set status = 'waiting', updated_at = now(), acknowledged_at = coalesce(acknowledged_at, now()), acknowledged_by = coalesce(acknowledged_by, auth.uid())
  where id = v_request.id;

  return v_work_order_id;
end;
$$;


ALTER FUNCTION "public"."triage_service_request_to_work_order"("p_service_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."unapply_payment"("p_payment_id" "uuid", "p_charge_id" "uuid" DEFAULT NULL::"uuid") RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare n integer;
begin
  if p_charge_id is null then
    -- Remove ALL applications for this payment
    delete from public.payment_applications where payment_id = p_payment_id;
  else
    delete from public.payment_applications where payment_id = p_payment_id and charge_id = p_charge_id;
  end if;
  get diagnostics n = row_count;
  return n;
end;
$$;


ALTER FUNCTION "public"."unapply_payment"("p_payment_id" "uuid", "p_charge_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."undo_bank_reconciliation"("p_reconciliation_id" "uuid", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  r public.bank_reconciliations;
  v_bank public.bank_accounts;
  v_previous date;
  v_reason text := btrim(coalesce(p_reason, ''));
begin
  if char_length(v_reason) < 10 then
    raise exception 'Give a reason of at least 10 characters for undoing the reconciliation.' using errcode = '23514';
  end if;
  select * into r from public.bank_reconciliations where id = p_reconciliation_id;
  if not found then
    raise exception 'Reconciliation not found.' using errcode = '42501';
  end if;
  select * into v_bank from public.bank_accounts where id = r.bank_account_id;
  if not found or not public.app_can_reconcile_bank(v_bank) then
    raise exception 'Reconciliation not found.' using errcode = '42501';
  end if;
  perform 1 from public.bank_accounts where id = v_bank.id for update;
  select * into r from public.bank_reconciliations where id = p_reconciliation_id for update;
  if r.status <> 'completed' then
    raise exception 'Only a completed reconciliation can be undone.' using errcode = '55000';
  end if;
  if exists (select 1 from public.bank_reconciliations x
              where x.bank_account_id = r.bank_account_id and x.status = 'completed'
                and x.statement_date > r.statement_date) then
    raise exception 'Undo the latest reconciliation of this account first.' using errcode = '55000';
  end if;
  if exists (select 1 from public.bank_reconciliations x
              where x.bank_account_id = r.bank_account_id and x.status = 'in_progress') then
    raise exception 'A reconciliation of this account is in progress. Complete or discard it first.' using errcode = '55000';
  end if;
  perform 1 from public.accounting_periods where portfolio_id = r.portfolio_id for share;
  select max(x.statement_date) into v_previous from public.bank_reconciliations x
   where x.bank_account_id = r.bank_account_id and x.status = 'completed' and x.id <> r.id;
  if exists (select 1 from public.accounting_periods p
              where p.portfolio_id = r.portfolio_id and p.status = 'closed'
                and (make_date(p.fiscal_year, p.period_month, 1) + interval '1 month' - interval '1 day')::date
                    > coalesce(v_previous, '-infinity'::date)) then
    raise exception 'A month this reconciliation covers is closed. Reopen the month before undoing it.' using errcode = '55000';
  end if;

  perform set_config('app.bank_reconciliation_undo', r.id::text, true);
  update public.bank_reconciliations
     set status = 'in_progress', undone_at = now(), undone_by = auth.uid(), undo_reason = left(v_reason, 500)
   where id = r.id;
  perform set_config('app.bank_reconciliation_undo', '', true);

  update public.bank_accounts
     set last_reconciliation_date = v_previous, updated_at = now()
   where id = v_bank.id;

  insert into public.audit_logs (portfolio_id, entity_type, entity_id, action, actor_id, changes)
  values (r.portfolio_id, 'bank_reconciliation', r.id, 'bank_reconciliation_undone', auth.uid(),
          jsonb_build_object('bank_account_id', r.bank_account_id, 'statement_date', r.statement_date,
                             'statement_balance', r.statement_balance, 'completed_at', r.completed_at,
                             'reconciled_through_now', v_previous, 'reason', left(v_reason, 500)));
end $$;


ALTER FUNCTION "public"."undo_bank_reconciliation"("p_reconciliation_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."unit_association_id"("p_unit_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$#variable_conflict use_column
begin
  return (select s.x from (

  select b.association_id from public.units u join public.buildings b on b.id = u.building_id where u.id = p_unit_id
  ) s(x) limit 1);
end$$;


ALTER FUNCTION "public"."unit_association_id"("p_unit_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."unit_late_fee_override"("p_unit_id" "uuid") RETURNS TABLE("exempt" boolean, "amount" numeric, "is_percent" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select bool_or(o.late_fee_exempt),
         (array_agg(o.late_fee_override_amount order by o.is_primary desc, o.move_in_date desc nulls last)
            filter (where o.late_fee_override_amount is not null))[1],
         (array_agg(o.late_fee_override_is_percent order by o.is_primary desc, o.move_in_date desc nulls last)
            filter (where o.late_fee_override_amount is not null))[1]
    from public.occupancies o
   where o.unit_id = p_unit_id
     and o.status = 'current'::public.occupancy_status
     and o.occupancy_type::text = 'owner'
     and (o.late_fee_override_until is null or o.late_fee_override_until >= public.association_local_date(o.association_id))
     and (o.late_fee_exempt or o.late_fee_override_amount is not null);
$$;


ALTER FUNCTION "public"."unit_late_fee_override"("p_unit_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."unit_owners_same_association"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_unit_association_id uuid;
  v_owner_association_id uuid;
begin
  select b.association_id into v_unit_association_id
    from public.units u join public.buildings b on b.id = u.building_id
   where u.id = new.unit_id
     for share of u, b;
  select ow.association_id into v_owner_association_id
    from public.owners ow where ow.id = new.owner_id for share;
  if v_unit_association_id is not null and v_owner_association_id is not null
     and v_unit_association_id <> v_owner_association_id then
    raise exception 'This homeowner belongs to another association. Add them as a new homeowner of this association.'
      using errcode = '23514';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."unit_owners_same_association"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."unit_portfolio_id"("p_unit_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$#variable_conflict use_column
begin
  return (select s.x from (

  select a.portfolio_id
    from public.units u
    join public.buildings b on b.id = u.building_id
    join public.associations a on a.id = b.association_id
   where u.id = p_unit_id
     and u.archived_at is null
     and b.archived_at is null
     and a.archived_at is null
  ) s(x) limit 1);
end$$;


ALTER FUNCTION "public"."unit_portfolio_id"("p_unit_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."units_move_keeps_association"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_old uuid;
  v_new uuid;
begin
  -- Locked, so a concurrent move of either building to another association
  -- waits for this (and its guard then sees the unit), or this sees the move.
  select b.association_id into v_old from public.buildings b where b.id = old.building_id for share;
  select b.association_id into v_new from public.buildings b where b.id = new.building_id for share;
  if v_old is distinct from v_new and (
       exists (select 1 from public.occupancies o where o.unit_id = new.id)
       or exists (select 1 from public.unit_owners uo where uo.unit_id = new.id)) then
    raise exception 'This unit has homeowners or residents, so it cannot move to another association.'
      using errcode = '23514';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."units_move_keeps_association"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."unlink_owner_logins"("p_owner_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_owner public.owners;
  v_added integer := 0;
begin
  select * into v_owner from public.owners where id = p_owner_id for update;
  if not found then
    raise exception 'Owner not found.' using errcode = 'P0002';
  end if;
  -- Staff of the owner's association (scoped managers: their associations
  -- only); platform operators only when they may change company data.
  if not (public.is_any_staff() or public.is_company_admin() or public.is_platform_operator())
     or not public.can_manage_association(v_owner.association_id)
     or not public.operator_may_write(false) then
    raise exception 'You cannot change this owner''s logins.' using errcode = '42501';
  end if;

  update public.owner_portal_logins
     set revoked_at = now()
   where owner_id = p_owner_id
     and revoked_at is null;
  get diagnostics v_added = row_count;

  if v_owner.auth_user_id is not null or v_owner.portal_activated then
    update public.owners
       set auth_user_id = null, portal_activated = false
     where id = p_owner_id;
  end if;

  insert into public.audit_logs (portfolio_id, entity_type, entity_id, action, actor_id, changes)
  values (v_owner.portfolio_id, 'owner', p_owner_id, 'owner_logins_unlinked', auth.uid(),
          jsonb_build_object('original_login', v_owner.auth_user_id, 'added_logins_revoked', v_added));

  return v_added + case when v_owner.auth_user_id is not null then 1 else 0 end;
end;
$$;


ALTER FUNCTION "public"."unlink_owner_logins"("p_owner_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."unpaid_bills_total"("p_portfolio_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("unpaid_total" numeric, "unpaid_count" integer, "overdue_total" numeric)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select coalesce(sum(pb.amount - coalesce(pb.credit_applied, 0)), 0)::numeric,
         count(*)::integer,
         coalesce(sum(pb.amount - coalesce(pb.credit_applied, 0)) filter (where pb.due_date < current_date), 0)::numeric
    from public.payable_bills pb
   where pb.archived_at is null
     and pb.status not in ('paid', 'void')
     and (p_portfolio_id is null or pb.portfolio_id = p_portfolio_id);
$$;


ALTER FUNCTION "public"."unpaid_bills_total"("p_portfolio_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_association_document"("p_document_id" "uuid", "p_folder" "text", "p_share_scope" "text", "p_description" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare d record; v_portfolio uuid;
begin
  select * into d from public.documents where id = p_document_id and entity_type = 'association' for update;
  if not found or not public.can_manage_association(d.entity_id) then
    raise exception 'Document not found' using errcode = 'P0002';
  end if;
  if p_share_scope not in ('staff', 'board', 'owners') then
    raise exception 'Choose who can see this document' using errcode = '22023';
  end if;
  if length(btrim(coalesce(p_folder, ''))) > 60 or length(coalesce(p_description, '')) > 500 then
    raise exception 'Folder names are limited to 60 characters and descriptions to 500' using errcode = '22023';
  end if;
  update public.documents
     set folder = nullif(btrim(p_folder), ''), share_scope = p_share_scope, description = nullif(btrim(p_description), '')
   where id = p_document_id;
  select portfolio_id into v_portfolio from public.associations where id = d.entity_id;
  if d.share_scope is distinct from p_share_scope or d.folder is distinct from nullif(btrim(p_folder), '') then
    insert into public.audit_logs (portfolio_id, entity_type, entity_id, action, actor_id, actor_email, changes)
    values (v_portfolio, 'association', d.entity_id, 'document_sharing_updated', auth.uid(),
            (select email from auth.users where id = auth.uid()),
            jsonb_build_object('document_id', d.id, 'file_name', d.file_name,
                               'before', jsonb_build_object('folder', d.folder, 'share_scope', d.share_scope),
                               'after', jsonb_build_object('folder', nullif(btrim(p_folder), ''), 'share_scope', p_share_scope)));
  end if;
end $$;


ALTER FUNCTION "public"."update_association_document"("p_document_id" "uuid", "p_folder" "text", "p_share_scope" "text", "p_description" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_association_settings"("p_association_id" "uuid", "p_values" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  allowed text[] := array[
    'name', 'legal_name', 'property_type', 'address', 'address_line_2', 'city', 'state', 'zip', 'county',
    'description', 'year_built', 'tax_id', 'timezone', 'status',
    'management_start_date', 'management_end_date', 'management_end_reason',
    'fiscal_year_start', 'vendor_1099_payer', 'reserve_funds', 'basis_for_owner_packets', 'nsf_fee_amount_override',
    'late_fee_eligible_charges',
    'payment_frequency', 'owner_can_override_frequency', 'hide_calendar_in_portal', 'disable_contacts_editing_in_portal',
    'disable_renter_editing_in_portal', 'residents_check_fee_coverage_enabled',
    'annual_interest_rate', 'interest_grace_days', 'interest_post_day_of_month', 'interest_grace_balance', 'interest_income_gl_account_id',
    'budget_variance_threshold_amount', 'budget_variance_threshold_pct', 'budget_variance_threshold_op',
    'maintenance_limit', 'insurance_expiration', 'home_warranty_covered', 'unit_entry_pre_authorized',
    'disable_online_maintenance_requests', 'maintenance_contact_name', 'maintenance_contact_phone', 'maintenance_contact_email',
    'maintenance_notes', 'online_maintenance_request_instructions',
    'violation_sender_name', 'violation_sender_email_uses_logged_in_user', 'violation_sender_email', 'electronic_doc_delivery_terms'
  ];
  v_keys text[]; v_cols text; v_before jsonb; v_portfolio uuid; v_gl uuid;
begin
  if not public.can_manage_association(p_association_id) then raise exception 'Permission denied' using errcode = '42501'; end if;
  if p_values is null or jsonb_typeof(p_values) <> 'object' then raise exception 'Nothing to save'; end if;
  select array_agg(k) into v_keys from jsonb_object_keys(p_values) k where k = any(allowed);
  if coalesce(cardinality(v_keys), 0) = 0 then raise exception 'None of the submitted fields can be edited here'; end if;
  if exists (select 1 from jsonb_object_keys(p_values) k where not (k = any(allowed))) then raise exception 'Unknown or protected field submitted'; end if;

  if p_values ? 'name' and char_length(btrim(coalesce(p_values ->> 'name', ''))) < 2 then raise exception 'Name is required'; end if;
  if p_values ? 'payment_frequency' and (p_values ->> 'payment_frequency') not in ('monthly', 'quarterly', 'semi_annually', 'annually') then raise exception 'Invalid payment frequency'; end if;
  if p_values ? 'late_fee_eligible_charges' and coalesce(p_values ->> 'late_fee_eligible_charges', 'all') not in ('all', 'recurring_only') then raise exception 'Invalid late-fee eligible charges'; end if;
  if p_values ? 'annual_interest_rate' and nullif(p_values ->> 'annual_interest_rate', '') is not null
     and (p_values ->> 'annual_interest_rate')::numeric not between 0 and 36 then raise exception 'Annual interest rate must be between 0 and 36%%'; end if;
  if p_values ? 'interest_post_day_of_month' and nullif(p_values ->> 'interest_post_day_of_month', '') is not null
     and (p_values ->> 'interest_post_day_of_month')::integer not between 1 and 28 then raise exception 'Interest posting day must be 1–28'; end if;
  if p_values ? 'violation_sender_email' and nullif(p_values ->> 'violation_sender_email', '') is not null
     and (p_values ->> 'violation_sender_email') !~* '^[^@\s]+@[^@\s]+\.[^@\s]+$' then raise exception 'Enter a valid violation sender email'; end if;
  select portfolio_id into v_portfolio from public.associations where id = p_association_id;
  v_gl := nullif(p_values ->> 'interest_income_gl_account_id', '')::uuid;
  if v_gl is not null and not exists (
    select 1 from public.gl_accounts g where g.id = v_gl and g.portfolio_id = v_portfolio and g.active
      and (g.association_id is null or g.association_id = p_association_id)
  ) then raise exception 'Interest income GL account is outside this association'; end if;

  select to_jsonb(a) into v_before from public.associations a where a.id = p_association_id for update;
  select string_agg(format('%I', k), ', ') into v_cols from unnest(v_keys) k;
  execute format('update public.associations set (%s) = (select %s from jsonb_populate_record(null::public.associations, $1)) where id = $2', v_cols, v_cols)
  using (select jsonb_object_agg(k, case when p_values -> k = '""'::jsonb then 'null'::jsonb else p_values -> k end) from unnest(v_keys) k), p_association_id;

  insert into public.audit_logs (portfolio_id, entity_type, entity_id, action, actor_id, actor_email, changes)
  select v_portfolio, 'association', p_association_id, 'association_settings_updated', auth.uid(),
         (select email from auth.users where id = auth.uid()),
         jsonb_build_object('before', (select jsonb_object_agg(k, v_before -> k) from unnest(v_keys) k),
                            'after', (select jsonb_object_agg(k, to_jsonb(a) -> k) from unnest(v_keys) k))
    from public.associations a where a.id = p_association_id;
end;
$_$;


ALTER FUNCTION "public"."update_association_settings"("p_association_id" "uuid", "p_values" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_bank_account_reconciliation_date"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if new.status = 'completed' and old.status is distinct from 'completed' then
    update public.bank_accounts
       set last_reconciliation_date = greatest(coalesce(last_reconciliation_date, new.statement_date), new.statement_date),
           updated_at = now()
     where id = new.bank_account_id
       and portfolio_id = new.portfolio_id;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."update_bank_account_reconciliation_date"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_company_logo"("p_logo_url" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  v_portfolio uuid := public.current_portfolio_id();
  v_url text := nullif(btrim(coalesce(p_logo_url, '')), '');
begin
  if auth.uid() is null or v_portfolio is null
     or not (public.is_company_admin() or public.is_full_access_staff() or public.is_platform_operator()) then
    raise exception 'Permission denied' using errcode = '42501';
  end if;
  if v_url is not null and v_url !~* '^https?://[^\s]+$' then
    raise exception 'Logo URL must be a full http(s) address' using errcode = '22023';
  end if;
  if v_url is not null and length(v_url) > 2000 then
    raise exception 'Logo URL is too long' using errcode = '22023';
  end if;

  update public.portfolios
     set logo_url   = v_url,
         updated_at = now()
   where id = v_portfolio;
  if not found then raise exception 'Portfolio not found' using errcode = 'P0002'; end if;
end;
$_$;


ALTER FUNCTION "public"."update_company_logo"("p_logo_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_company_profile"("p_company_name" "text", "p_phone_number" "text", "p_address_street" "text", "p_address_city" "text", "p_address_state" "text", "p_address_zip" "text", "p_support_email" "text", "p_brand_color" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  v_portfolio uuid := public.current_portfolio_id();
begin
  if auth.uid() is null or v_portfolio is null
     or not (public.is_company_admin() or public.is_full_access_staff() or public.is_platform_operator()) then
    raise exception 'Permission denied' using errcode = '42501';
  end if;
  if nullif(btrim(coalesce(p_company_name, '')), '') is null then
    raise exception 'Company name is required' using errcode = '22023';
  end if;
  if p_brand_color is not null and p_brand_color !~ '^#[0-9A-Fa-f]{6}$' then
    raise exception 'Brand color must be a hex color like #10B981' using errcode = '22023';
  end if;
  if nullif(btrim(coalesce(p_support_email, '')), '') is not null
     and p_support_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then
    raise exception 'Enter a valid support email' using errcode = '22023';
  end if;

  update public.portfolios
     set company_name   = left(btrim(p_company_name), 200),
         phone_number   = nullif(btrim(coalesce(p_phone_number, '')), ''),
         address_street = nullif(btrim(coalesce(p_address_street, '')), ''),
         address_city   = nullif(btrim(coalesce(p_address_city, '')), ''),
         address_state  = nullif(btrim(coalesce(p_address_state, '')), ''),
         address_zip    = nullif(btrim(coalesce(p_address_zip, '')), ''),
         support_email  = nullif(lower(btrim(coalesce(p_support_email, ''))), ''),
         brand_color    = coalesce(p_brand_color, brand_color),
         updated_at     = now()
   where id = v_portfolio;
  if not found then raise exception 'Portfolio not found' using errcode = 'P0002'; end if;
end;
$_$;


