CREATE OR REPLACE FUNCTION "public"."update_record_note"("p_note_id" "uuid", "p_pinned" boolean DEFAULT NULL::boolean, "p_archive" boolean DEFAULT false) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare n record;
begin
  select * into n from public.record_notes where id = p_note_id for update;
  if not found or not public.can_access_portfolio(n.portfolio_id) or not public.app_record_in_manager_scope(n.entity_type, n.entity_id) then
    raise exception 'Note not found' using errcode = 'P0002';
  end if;
  if p_archive then
    if n.created_by is distinct from auth.uid() and not public.can_manage_finance(n.portfolio_id)
       and not public.is_company_admin() and not public.is_platform_operator() then
      raise exception 'Only the author or an administrator can remove this note' using errcode = '42501';
    end if;
    update public.record_notes set archived_at = now(), archived_by = auth.uid() where id = p_note_id;
    insert into public.audit_logs (portfolio_id, entity_type, entity_id, action, actor_id, actor_email, changes)
    values (n.portfolio_id, n.entity_type, n.entity_id, 'note_removed', auth.uid(),
            (select email from auth.users where id = auth.uid()),
            jsonb_build_object('note_id', n.id, 'body', left(n.body, 500), 'author', n.created_by_name));
  elsif p_pinned is not null then
    update public.record_notes set pinned = p_pinned where id = p_note_id;
  end if;
end $$;


ALTER FUNCTION "public"."update_record_note"("p_note_id" "uuid", "p_pinned" boolean, "p_archive" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_tenant_portal_profile"("p_tenant_id" "uuid", "p_phone" "text", "p_emergency_contact_name" "text", "p_emergency_contact_phone" "text", "p_insurance_policy_number" "text", "p_insurance_expiration" "date") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_updated uuid;
begin
  if auth.uid() is null or not public.is_tenant_user() then
    raise exception 'Resident portal access is required';
  end if;

  if char_length(coalesce(p_phone, '')) > 50
     or char_length(coalesce(p_emergency_contact_name, '')) > 200
     or char_length(coalesce(p_emergency_contact_phone, '')) > 50
     or char_length(coalesce(p_insurance_policy_number, '')) > 200 then
    raise exception 'One or more profile fields are too long';
  end if;

  update public.tenants t
     set phone = nullif(btrim(p_phone), ''),
         emergency_contact_name = nullif(btrim(p_emergency_contact_name), ''),
         emergency_contact_phone = nullif(btrim(p_emergency_contact_phone), ''),
         insurance_policy_number = nullif(btrim(p_insurance_policy_number), ''),
         insurance_expiration = p_insurance_expiration,
         updated_at = now()
   where t.id = p_tenant_id
     and t.id in (select public.current_tenant_ids())
  returning t.id into v_updated;

  return v_updated is not null;
end;
$$;


