CREATE OR REPLACE FUNCTION "public"."upsert_budget_line"("p_id" "uuid", "p_association_id" "uuid", "p_gl_account_id" "uuid", "p_fiscal_year" integer, "p_monthly_amounts" numeric[], "p_category" "text", "p_notes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_id uuid;
  v_target_association_id uuid;
  v_target_portfolio_id uuid;
begin
  if p_id is not null then
    select bl.association_id
    into v_target_association_id
    from public.budget_lines bl
    where bl.id = p_id
    for update;

    if not found then
      raise exception 'Budget line not found' using errcode = 'P0002';
    end if;
    if p_association_id is distinct from v_target_association_id then
      raise exception 'Budget line association cannot be changed' using errcode = '22023';
    end if;
  else
    v_target_association_id := p_association_id;
  end if;

  if v_target_association_id is null
     or p_gl_account_id is null
     or p_fiscal_year is null
     or p_fiscal_year not between 1900 and 2200
     or p_monthly_amounts is null
     or cardinality(p_monthly_amounts) <> 12
     or p_category is null
     or p_category not in ('income', 'expense')
     or length(coalesce(p_notes, '')) > 10000
     or exists (
       select 1
       from unnest(p_monthly_amounts) as amount(value)
       where amount.value is null
          or amount.value::text = 'NaN'
          or amount.value < 0
          or amount.value > 1000000000000
     ) then
    raise exception 'Invalid budget line input' using errcode = '22023';
  end if;

  if not public.can_mutate_association_budget(v_target_association_id) then
    raise exception 'Finance authorization required' using errcode = '42501';
  end if;

  select a.portfolio_id
  into v_target_portfolio_id
  from public.associations a
  where a.id = v_target_association_id;

  if v_target_portfolio_id is null
     or not exists (
       select 1
       from public.gl_accounts ga
       where ga.id = p_gl_account_id
         and ga.portfolio_id = v_target_portfolio_id
         and (ga.association_id is null or ga.association_id = v_target_association_id)
     ) then
    raise exception 'GL account is outside the association scope' using errcode = '23514';
  end if;

  if p_id is not null then
    update public.budget_lines bl
    set gl_account_id = p_gl_account_id,
        fiscal_year = p_fiscal_year,
        monthly_amounts = p_monthly_amounts,
        category = p_category::public.budget_category,
        notes = nullif(trim(p_notes), ''),
        updated_at = pg_catalog.now()
    where bl.id = p_id
      and bl.association_id = v_target_association_id
    returning bl.id into v_id;
  else
    insert into public.budget_lines (
      association_id, gl_account_id, fiscal_year, monthly_amounts, category, notes
    ) values (
      v_target_association_id, p_gl_account_id, p_fiscal_year,
      p_monthly_amounts, p_category::public.budget_category, nullif(trim(p_notes), '')
    )
    returning budget_lines.id into v_id;
  end if;

  return v_id;
end;
$$;


ALTER FUNCTION "public"."upsert_budget_line"("p_id" "uuid", "p_association_id" "uuid", "p_gl_account_id" "uuid", "p_fiscal_year" integer, "p_monthly_amounts" numeric[], "p_category" "text", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."user_invitations_server_token"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if current_user in ('authenticated', 'anon') then
    if tg_op = 'INSERT' then
      new.token := replace(gen_random_uuid()::text, '-', '') || replace(gen_random_uuid()::text, '-', '');
    elsif new.token is distinct from old.token then
      raise exception 'Invitation tokens are generated by the server and cannot be changed';
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."user_invitations_server_token"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_invitation_email_domain"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  domains text[];
  invitee_domain text;
begin
  select allowed_email_domains into domains
    from public.portfolios
   where id = new.portfolio_id;

  if domains is null or array_length(domains, 1) is null then
    return new;  -- no restriction
  end if;

  invitee_domain := lower(split_part(new.email, '@', 2));
  if invitee_domain = '' then
    raise exception 'invalid email: %', new.email;
  end if;

  if not (invitee_domain = any(domains)) then
    raise exception 'email domain % not in portfolio allowlist (%)', invitee_domain, array_to_string(domains, ', ');
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."validate_invitation_email_domain"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_journal_entry_balance"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  total_debit numeric;
  total_credit numeric;
  should_check boolean;
begin
  should_check := false;
  if tg_op = 'INSERT' and new.posted = true then
    should_check := true;
  elsif tg_op = 'UPDATE' and new.posted = true and (old.posted is distinct from true) then
    should_check := true;
  end if;

  if should_check then
    select coalesce(sum(debit_amount), 0), coalesce(sum(credit_amount), 0)
      into total_debit, total_credit
      from public.journal_lines
      where entry_id = new.id;

    if abs(total_debit - total_credit) > 0.001 then
      raise exception 'Journal entry % unbalanced: debits=% credits=%', new.id, total_debit, total_credit;
    end if;
    if new.posted_at is null then
      new.posted_at := now();
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."validate_journal_entry_balance"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_meeting_attendee_tenant_scope"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_association_id uuid;
begin
  select m.association_id
  into v_association_id
  from public.meetings m
  join public.associations a
    on a.id = m.association_id
   and a.portfolio_id = m.portfolio_id
  where m.id = new.meeting_id;

  if v_association_id is null then
    raise exception 'Meeting tenant scope is invalid' using errcode = '23514';
  end if;
  if length(trim(new.attendee_name)) not between 1 and 200
     or length(coalesce(new.notes, '')) > 2000
     or octet_length(coalesce(new.signature_data, '')) > 1048576
     or new.attendee_role is null
     or new.attendee_role not in ('board_member', 'owner', 'manager', 'guest') then
    raise exception 'Invalid meeting attendance input' using errcode = '22023';
  end if;
  if new.owner_id is not null
     and not exists (
       select 1
       from public.occupancies o
       where o.owner_id = new.owner_id
         and o.association_id = v_association_id
     ) then
    raise exception 'Owner is outside the meeting association' using errcode = '23514';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_meeting_attendee_tenant_scope"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_meeting_tenant_scope"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if not exists (
    select 1
    from public.associations a
    where a.id = new.association_id
      and a.portfolio_id = new.portfolio_id
  ) then
    raise exception 'Meeting tenant scope is invalid' using errcode = '23514';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."validate_meeting_tenant_scope"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_owner_payable_tenant_scope"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if tg_op = 'UPDATE' and new.portfolio_id <> old.portfolio_id then
    raise exception 'Owner payable portfolio cannot be changed';
  end if;

  if not exists (
    select 1 from public.associations a
    where a.id = new.association_id
      and a.portfolio_id = new.portfolio_id
      and a.archived_at is null
  ) then
    raise exception 'Owner payable association is outside the portfolio';
  end if;

  if not exists (
    select 1 from public.occupancies o
    where o.owner_id = new.owner_id
      and o.association_id = new.association_id
  ) and not exists (
    select 1 from public.unit_owners uo
      join public.units u on u.id = uo.unit_id
      join public.buildings b on b.id = u.building_id
     where uo.owner_id = new.owner_id and b.association_id = new.association_id
  ) then
    raise exception 'Owner payable owner is outside the association';
  end if;

  if new.gl_account_id is not null and not exists (
    select 1 from public.gl_accounts g
    where g.id = new.gl_account_id
      and (g.portfolio_id is null or g.portfolio_id = new.portfolio_id)
  ) then
    raise exception 'Owner payable GL account is outside the portfolio';
  end if;

  if new.bank_account_id is not null and not exists (
    select 1 from public.bank_accounts b
    where b.id = new.bank_account_id
      and b.portfolio_id = new.portfolio_id
      and (b.association_id is null or b.association_id = new.association_id)
  ) then
    raise exception 'Owner payable bank account is outside the association';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."validate_owner_payable_tenant_scope"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_payable_bill_integrity"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if new.amount is null or new.amount <= 0 then
    raise exception 'Bill amount must be positive';
  end if;
  if not exists (
    select 1 from public.vendors v
     where v.id = new.vendor_id and v.portfolio_id = new.portfolio_id and v.archived_at is null
  ) then
    raise exception 'Vendor is outside the bill portfolio or archived';
  end if;
  if new.association_id is not null and not exists (
    select 1 from public.associations a
     where a.id = new.association_id and a.portfolio_id = new.portfolio_id and a.archived_at is null
  ) then
    raise exception 'Association is outside the bill portfolio or archived';
  end if;
  if new.gl_account_id is not null and not exists (
    select 1 from public.gl_accounts g
     where g.id = new.gl_account_id
       and g.portfolio_id = new.portfolio_id
       and g.active
       and (g.association_id is null or g.association_id = new.association_id)
  ) then
    raise exception 'Expense GL account is outside the bill portfolio/association or inactive';
  end if;
  if new.bank_account_id is not null and not exists (
    select 1 from public.bank_accounts b
     where b.id = new.bank_account_id
       and b.portfolio_id = new.portfolio_id
       and b.archived_at is null
       and (b.association_id is null or b.association_id = new.association_id)
  ) then
    raise exception 'Bank account is outside the bill portfolio/association or archived';
  end if;
  if new.approval_request_id is not null and not exists (
    select 1 from public.approval_requests r
     where r.id = new.approval_request_id
       and r.portfolio_id = new.portfolio_id
       and r.association_id = new.association_id
       and r.vendor_id is not distinct from new.vendor_id
       and r.amount is not distinct from new.amount
  ) then
    raise exception 'Approval request does not match the bill';
  end if;

  if current_user not in ('postgres', 'service_role', 'supabase_admin') then
    if tg_op = 'INSERT' and (
      new.status not in ('draft'::public.payable_bill_status, 'pending_approval'::public.payable_bill_status)
      or new.approved_by is not null or new.approved_at is not null
      or new.paid_at is not null or new.check_number is not null
      or coalesce(new.credit_applied, 0) <> 0
    ) then
      raise exception 'Bill workflow state must be changed through an authorized workflow';
    end if;
    if tg_op = 'UPDATE' and (
      new.status is distinct from old.status
      or new.approved_by is distinct from old.approved_by
      or new.approved_at is distinct from old.approved_at
      or new.paid_at is distinct from old.paid_at
      or new.check_number is distinct from old.check_number
      or new.approval_request_id is distinct from old.approval_request_id
      or new.credit_applied is distinct from old.credit_applied
    ) then
      raise exception 'Bill workflow state must be changed through an authorized workflow';
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."validate_payable_bill_integrity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validate_payment_accounts"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_assoc uuid := public.unit_association_id(new.unit_id); v_pid uuid; v_charge record; v_open numeric;
        v_bank_assoc uuid;
begin
  select a.portfolio_id into v_pid from public.associations a where a.id = v_assoc;
  if v_pid is null then raise exception 'Payment unit is not in an association' using errcode = '23514'; end if;

  if new.bank_account_id is not null then
    select b.association_id into v_bank_assoc from public.bank_accounts b
     where b.id = new.bank_account_id and b.portfolio_id = v_pid and b.archived_at is null;
    if not found or (v_bank_assoc is not null and v_bank_assoc <> v_assoc) then
      raise exception 'That bank account does not belong to this unit''s association' using errcode = '23514';
    end if;
    -- A company-wide account: only one the unit's association uses.
    if v_bank_assoc is null
       and (tg_op = 'INSERT'
            or new.bank_account_id is distinct from old.bank_account_id
            or new.unit_id is distinct from old.unit_id)
       and not (v_assoc = any (public.app_bank_account_association_ids(new.bank_account_id))) then
      raise exception 'That bank account does not belong to this unit''s association' using errcode = '23514';
    end if;
  end if;

  if new.charge_id is not null then
    select c.id, c.unit_id, c.amount into v_charge from public.charges c where c.id = new.charge_id for update;
    if not found or v_charge.unit_id is distinct from new.unit_id then
      raise exception 'That charge is not on this unit' using errcode = '23514';
    end if;
    if new.method = 'credit' and tg_op = 'INSERT' then
      v_open := v_charge.amount - coalesce((select sum(pa.amount_applied) from public.payment_applications pa where pa.charge_id = new.charge_id), 0);
      if new.amount > v_open then
        raise exception 'The credit (%) is more than the open balance on that charge (%)', new.amount, v_open using errcode = '23514';
      end if;
    end if;
  end if;

  if new.method = 'credit' then
    if new.bank_account_id is not null then
      raise exception 'A credit does not go to a bank account' using errcode = '23514';
    end if;
    if not exists (
         select 1 from public.gl_accounts g
          where g.id = new.gl_account_id and g.portfolio_id = v_pid and g.active
            and (g.association_id is null or g.association_id = v_assoc)
            and g.account_type::text in ('income', 'other_income', 'expense', 'other_expense')) then
      raise exception 'A credit needs an active income or expense account of this association' using errcode = '23514';
    end if;
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."validate_payment_accounts"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."vendor_1099_totals"("p_tax_year" integer) RETURNS TABLE("association_id" "uuid", "vendor_id" "uuid", "total_paid" numeric, "bill_count" integer)
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select pb.association_id,
         pb.vendor_id,
         coalesce(sum(pb.amount - coalesce(pb.credit_applied, 0)), 0)::numeric,
         (count(*) filter (where pb.amount - coalesce(pb.credit_applied, 0) > 0))::integer
    from public.payable_bills pb
    join public.vendors v on v.id = pb.vendor_id
    left join public.associations a on a.id = pb.association_id
   where pb.status = 'paid'
     and pb.archived_at is null
     and v.send_1099
     -- every time zone is within a day of UTC: narrows to the year's bills
     and pb.paid_at >= make_date(p_tax_year, 1, 1)::timestamp at time zone 'UTC' - interval '2 days'
     and pb.paid_at <  make_date(p_tax_year + 1, 1, 1)::timestamp at time zone 'UTC' + interval '2 days'
     -- the local payment date is in the tax year
     and pb.paid_at >= (make_date(p_tax_year, 1, 1)::timestamp at time zone coalesce(nullif(a.timezone, ''), 'America/Chicago'))
     and pb.paid_at <  (make_date(p_tax_year + 1, 1, 1)::timestamp at time zone coalesce(nullif(a.timezone, ''), 'America/Chicago'))
   group by pb.association_id, pb.vendor_id;
$$;


