CREATE OR REPLACE FUNCTION "public"."vendors_default_gl_in_association"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_gl_association uuid;
  v_gl_portfolio uuid;
  v_vendor_portfolio uuid;
begin
  if new.default_gl_account_id is null then
    return new;
  end if;
  -- Locked, so a concurrent move of the account (trg_gl_account_vendor_default_scope)
  -- waits for this row and then sees the new default, or this sees the move.
  select g.association_id, g.portfolio_id into v_gl_association, v_gl_portfolio
    from public.gl_accounts g where g.id = new.default_gl_account_id
     for share;
  if not found then
    return new;  -- a missing account is left to the foreign key
  end if;
  -- The vendor's company comes from its association (this trigger can run
  -- before trg_vendors_set_portfolio_from_association derives it).
  v_vendor_portfolio := coalesce((select a.portfolio_id from public.associations a where a.id = new.association_id),
                                 new.portfolio_id);
  if v_gl_portfolio is distinct from v_vendor_portfolio
     or (v_gl_association is not null and v_gl_association is distinct from new.association_id) then
    raise exception 'A vendor''s default account must be company-wide or one of its association''s accounts.'
      using errcode = '23514';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."vendors_default_gl_in_association"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."vendors_guard_legacy_financials"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if auth.uid() is null or public.is_platform_operator() or public.can_manage_finance(old.portfolio_id) then
    return new;
  end if;
  if new.taxpayer_id is distinct from old.taxpayer_id
     or new.tax_account_number is distinct from old.tax_account_number
     or new.bank_routing_number is distinct from old.bank_routing_number
     or new.bank_account_number is distinct from old.bank_account_number then
    raise exception 'Only accounting staff can change a vendor''s tax or bank details' using errcode = '42501';
  end if;
  return new;
end $$;


