CREATE OR REPLACE FUNCTION "public"."vendors_move_financials_to_private"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  f jsonb := '{}'::jsonb;
begin
  if pg_trigger_depth() > 1 then
    return new;
  end if;
  if tg_op = 'INSERT' and tg_when = 'BEFORE' then
    new.has_taxpayer_id := false;
    new.has_bank_account := false;
    return new;
  end if;
  if tg_op = 'UPDATE' then
    if new.taxpayer_id is distinct from old.taxpayer_id and new.taxpayer_id is not null then f := f || jsonb_build_object('taxpayer_id', new.taxpayer_id); end if;
    if new.tax_account_number is distinct from old.tax_account_number and new.tax_account_number is not null then f := f || jsonb_build_object('tax_account_number', new.tax_account_number); end if;
    if new.bank_routing_number is distinct from old.bank_routing_number and new.bank_routing_number is not null then f := f || jsonb_build_object('bank_routing_number', new.bank_routing_number); end if;
    if new.bank_account_number is distinct from old.bank_account_number and new.bank_account_number is not null then f := f || jsonb_build_object('bank_account_number', new.bank_account_number); end if;
    if f <> '{}'::jsonb then
      insert into public.vendor_financial_details (vendor_id, portfolio_id, taxpayer_id, tax_account_number, bank_routing_number, bank_account_number, updated_by)
      values (new.id, new.portfolio_id, f ->> 'taxpayer_id', f ->> 'tax_account_number', f ->> 'bank_routing_number', f ->> 'bank_account_number', auth.uid())
      on conflict (vendor_id) do update set
        taxpayer_id         = case when f ? 'taxpayer_id' then excluded.taxpayer_id else vendor_financial_details.taxpayer_id end,
        tax_account_number  = case when f ? 'tax_account_number' then excluded.tax_account_number else vendor_financial_details.tax_account_number end,
        bank_routing_number = case when f ? 'bank_routing_number' then excluded.bank_routing_number else vendor_financial_details.bank_routing_number end,
        bank_account_number = case when f ? 'bank_account_number' then excluded.bank_account_number else vendor_financial_details.bank_account_number end,
        updated_at = now(), updated_by = excluded.updated_by;
    end if;
    if f ? 'bank_routing_number' or f ? 'bank_account_number' then
      new.ach_status := 'pending';
      new.ach_verified_at := null; new.ach_verified_by := null;
      new.ach_activated_at := null; new.ach_activated_by := null;
      new.is_auto_pay := false;
    end if;
    new.taxpayer_id := null; new.tax_account_number := null;
    new.bank_routing_number := null; new.bank_account_number := null;
    new.has_taxpayer_id := coalesce((select nullif(btrim(d.taxpayer_id), '') is not null
                                       from public.vendor_financial_details d where d.vendor_id = new.id), false);
    new.has_bank_account := coalesce((select nullif(btrim(d.bank_routing_number), '') is not null
                                             and nullif(btrim(d.bank_account_number), '') is not null
                                        from public.vendor_financial_details d where d.vendor_id = new.id), false);
    return new;
  end if;
  if new.taxpayer_id is not null or new.tax_account_number is not null
     or new.bank_routing_number is not null or new.bank_account_number is not null then
    insert into public.vendor_financial_details (vendor_id, portfolio_id, taxpayer_id, tax_account_number, bank_routing_number, bank_account_number, updated_by)
    values (new.id, new.portfolio_id, new.taxpayer_id, new.tax_account_number, new.bank_routing_number, new.bank_account_number, auth.uid())
    on conflict (vendor_id) do nothing;
    update public.vendors
       set taxpayer_id = null, tax_account_number = null, bank_routing_number = null, bank_account_number = null,
           has_taxpayer_id = nullif(btrim(coalesce(new.taxpayer_id, '')), '') is not null,
           has_bank_account = nullif(btrim(coalesce(new.bank_routing_number, '')), '') is not null
                              and nullif(btrim(coalesce(new.bank_account_number, '')), '') is not null
     where id = new.id;
  end if;
  return null;
end $$;


ALTER FUNCTION "public"."vendors_move_financials_to_private"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."vendors_self_service_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare n public.vendors;
begin
  -- board_vendor_fixes: trigger depth alone is not trusted.
  if not public.is_self_service_caller() then return new; end if;
  n := new;
  new := old;
  if pg_trigger_depth() > 1 then
    -- Linking this login to the record, or unlinking it.
    if n.auth_user_id is null or n.auth_user_id = auth.uid() then
      new.auth_user_id := n.auth_user_id;
    end if;
    if n.portal_activated then new.portal_activated := true; end if;
    -- Flags kept in step with vendor_financial_details.
    new.has_taxpayer_id := n.has_taxpayer_id;
    new.has_bank_account := n.has_bank_account;
    -- Changed bank details reset ACH to pending, never the other way.
    if n.ach_status = 'pending' and n.ach_verified_at is null and n.ach_verified_by is null
       and n.ach_activated_at is null and n.ach_activated_by is null and not coalesce(n.is_auto_pay, false) then
      new.ach_status := n.ach_status;
      new.ach_verified_at := null; new.ach_verified_by := null;
      new.ach_activated_at := null; new.ach_activated_by := null;
      new.is_auto_pay := false;
    end if;
    -- Financial fields are only ever cleared here (they live privately).
    if n.taxpayer_id is null then new.taxpayer_id := null; end if;
    if n.tax_account_number is null then new.tax_account_number := null; end if;
    if n.bank_routing_number is null then new.bank_routing_number := null; end if;
    if n.bank_account_number is null then new.bank_account_number := null; end if;
  end if;
  new.phone_numbers := n.phone_numbers; new.emails := n.emails;
  new.address_street := n.address_street; new.address_city := n.address_city;
  new.address_state := n.address_state; new.address_zip := n.address_zip;
  new.updated_at := now();
  return new;
end $$;


ALTER FUNCTION "public"."vendors_self_service_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."vendors_set_portfolio_from_association"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_portfolio_id uuid;
  v_linked uuid[];
begin
  if new.is_management_company then
    if new.association_id is not null then
      raise exception 'The management company belongs to the company, not to one association.' using errcode = '23514';
    end if;
    -- Its bills, work orders, documents and default account belong to its
    -- company: it never moves to another one.
    if tg_op = 'UPDATE' and new.portfolio_id is distinct from old.portfolio_id then
      raise exception 'The management company cannot move to another company.' using errcode = '23514';
    end if;
  else
    if new.association_id is null then
      raise exception 'A vendor must belong to an association.' using errcode = '23502';
    end if;
    -- Locked, so a concurrent move of the association to another company waits
    -- for this row (and then carries it along), or this waits for the move.
    select a.portfolio_id into v_portfolio_id
      from public.associations a
     where a.id = new.association_id
       for share;
    if not found then
      raise exception 'Association not found for this vendor.' using errcode = '23503';
    end if;
    if v_portfolio_id is null then
      raise exception 'This association has no company, so it cannot have vendors yet.' using errcode = '23502';
    end if;
    -- A vendor's tax and bank records, documents, invitations and company-level
    -- rows belong to its company: it never moves to another company.
    if tg_op = 'UPDATE' and old.portfolio_id is not null and v_portfolio_id is distinct from old.portfolio_id then
      raise exception 'A vendor cannot move to an association of another company. Add it as a new vendor there.'
        using errcode = '23514';
    end if;
    new.portfolio_id := v_portfolio_id;
  end if;

  -- Marking a vendor as the management company makes it company-wide (every
  -- association can use it and every manager sees it): only company-wide
  -- finance staff or a company admin may do it, as with the management-fee
  -- schedule. Sessions without a signed-in user (migrations, the SQL editor,
  -- trusted server jobs) are exempt.
  if auth.uid() is not null
     and ((tg_op = 'INSERT' and new.is_management_company)
          or (tg_op = 'UPDATE' and new.is_management_company is distinct from old.is_management_company))
     and not (public.can_manage_finance(new.portfolio_id)
              and (not public.manager_is_scoped() or public.is_company_admin())) then
    raise exception 'Only company-wide accounting staff or a company admin can mark the management company.'
      using errcode = '42501';
  end if;

  -- Only staff move a vendor between associations (a vendor's own portal
  -- session may edit its contact details, not which association it serves).
  if tg_op = 'UPDATE' and auth.uid() is not null
     and new.association_id is distinct from old.association_id
     and not public.is_any_staff() then
    raise exception 'Only staff can move a vendor to another association.' using errcode = '42501';
  end if;

  if tg_op = 'UPDATE' and (new.association_id is distinct from old.association_id
                           or new.is_management_company is distinct from old.is_management_company) then
    v_linked := public.vendor_linked_association_ids(new.id);
    if not new.is_management_company and exists (select 1 from unnest(v_linked) x where x <> new.association_id) then
      raise exception 'This vendor has work orders, bills or other records in its current association. Add it as a new vendor of the other association instead.'
        using errcode = '23514';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."vendors_set_portfolio_from_association"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."verify_api_key"("p_raw_key" "text") RETURNS TABLE("portfolio_id" "uuid", "key_id" "uuid", "scopes" "text"[])
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'extensions'
    AS $$
declare
  k_hash text;
  k_row public.api_keys;
begin
  if p_raw_key is null or length(p_raw_key) < 16 then
    return;
  end if;

  k_hash := encode(extensions.digest(p_raw_key, 'sha256'), 'hex');

  select * into k_row
    from public.api_keys
   where key_hash = k_hash
     and revoked_at is null
     and (expires_at is null or expires_at > now())
   limit 1;

  if not found then
    return;
  end if;

  update public.api_keys
     set last_used_at = now(), use_count = use_count + 1
   where id = k_row.id;

  insert into public.api_key_usage_daily (api_key_id, portfolio_id, usage_date, request_count)
  values (k_row.id, k_row.portfolio_id, (now() at time zone 'UTC')::date, 1)
  on conflict (api_key_id, usage_date)
  do update set request_count = public.api_key_usage_daily.request_count + 1;

  portfolio_id := k_row.portfolio_id;
  key_id := k_row.id;
  scopes := k_row.scopes;
  return next;
end;
$$;


ALTER FUNCTION "public"."verify_api_key"("p_raw_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."violation_case_links_valid"("p_association_id" "uuid", "p_house_rule_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$#variable_conflict use_column
begin
  return (select s.x from (

  select exists (
    select 1
    from public.associations a
    where a.id = p_association_id
      and (
        p_house_rule_id is null
        or exists (
          select 1 from public.house_rules hr
          where hr.id = p_house_rule_id
            and hr.association_id = a.id
        )
      )
  )
  ) s(x) limit 1);
end$$;


ALTER FUNCTION "public"."violation_case_links_valid"("p_association_id" "uuid", "p_house_rule_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."violation_current_step_letter"("p_violation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v public.violations;
begin
  select * into v from public.violations where id = p_violation_id;
  if v.id is null or not public.can_manage_violations(v.association_id) then
    raise exception 'Permission denied' using errcode = '42501';
  end if;
  if coalesce(v.current_step, 0) < 1 then
    raise exception 'No follow-up step has been recorded yet' using errcode = '22023';
  end if;
  if v.current_step_terms is null or (v.current_step_terms ->> 'step')::integer <> v.current_step then
    raise exception 'This step was recorded before letter terms were saved — send a notice from Generate notice instead' using errcode = '22023';
  end if;
  return v.current_step_terms;
end $$;


ALTER FUNCTION "public"."violation_current_step_letter"("p_violation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."violation_letters_bind"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v public.violations;
begin
  if tg_op = 'INSERT' then
    select * into v from public.violations where id = new.violation_id;
    if v.id is null then
      raise exception 'Violation not found' using errcode = '23503';
    end if;
    new.association_id := v.association_id;
    new.owner_id := v.owner_id;
    new.created_by := auth.uid();
    new.created_at := now();
    if new.email_status = 'queued' then
      new.email_status := 'pending';
    end if;
    if new.pdf_path not like 'violations/' || v.id::text || '/letters/%' then
      raise exception 'Letter file must be stored under the violation' using errcode = '22023';
    end if;
    return new;
  end if;
  if new.mail_status is distinct from old.mail_status then
    if not (old.mail_status = 'to_mail' and new.mail_status = 'mailed') then
      raise exception 'A letter can only move from "to mail" to "mailed"' using errcode = '22023';
    end if;
    new.mailed_at := now();
    new.mailed_by := auth.uid();
  end if;
  if new.email_status is distinct from old.email_status then
    if old.email_status = 'pending' and new.email_status = 'queued' then
      null;
    elsif old.email_status = 'no_email_on_file' and new.email_status = 'pending'
          and 'email' = any (old.delivery_methods)
          and nullif(btrim(coalesce(new.emailed_to, '')), '') is not null then
      new.emailed_to := btrim(new.emailed_to);
    else
      raise exception 'A letter''s email can only move from "pending" to "queued" (or get an address when none was on file)' using errcode = '22023';
    end if;
  end if;
  if not (old.email_status = 'no_email_on_file' and new.email_status = 'pending') then
    new.emailed_to := old.emailed_to;
  end if;
  new.id := old.id; new.violation_id := old.violation_id; new.association_id := old.association_id;
  new.owner_id := old.owner_id; new.step_order := old.step_order; new.step_name := old.step_name;
  new.subject := old.subject; new.body := old.body; new.pdf_path := old.pdf_path;
  new.delivery_methods := old.delivery_methods;
  new.created_by := old.created_by; new.created_at := old.created_at;
  if new.mail_status is not distinct from old.mail_status then
    new.mailed_at := old.mailed_at; new.mailed_by := old.mailed_by;
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."violation_letters_bind"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."violation_report_type"("p_type" "text") RETURNS "public"."violation_type"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  select case p_type
    when 'noise' then 'noise'
    when 'parking' then 'parking'
    when 'pet' then 'pets'
    when 'construction' then 'exterior_modification'
    when 'balcony' then 'exterior_modification'
    when 'waste' then 'trash_debris'
    when 'subletting' then 'lease_violation'
    else 'other'
  end::public.violation_type;
$$;


ALTER FUNCTION "public"."violation_report_type"("p_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."violation_schedule"("p_association_id" "uuid", "p_house_rule_id" "uuid") RETURNS TABLE("ordinal" integer, "id" "uuid", "follow_up_name" "text", "days_after_previous" integer, "letter_template_id" "uuid", "delivery_methods" "text"[], "fee" numeric, "gl_account_id" "uuid", "offers_hearing" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
  with use_custom as (
    select coalesce((select hr.custom_schedule from public.house_rules hr where hr.id = p_house_rule_id and hr.association_id = p_association_id), false) as custom
  )
  select (row_number() over (order by s.step_order, s.created_at))::integer, s.id, s.follow_up_name, s.days_after_previous, s.letter_template_id,
         s.delivery_methods, coalesce(s.fee, 0), s.gl_account_id, s.offers_hearing
    from public.violation_followup_steps s, use_custom
   where s.association_id = p_association_id and s.archived_at is null
     and ((use_custom.custom and s.house_rule_id = p_house_rule_id) or (not use_custom.custom and s.house_rule_id is null));
$$;


ALTER FUNCTION "public"."violation_schedule"("p_association_id" "uuid", "p_house_rule_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."void_bank_deposit"("p_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare d public.bank_deposits;
begin
  select * into d from public.bank_deposits where id = p_id and voided_at is null for update;
  if not found or not public.can_manage_finance(d.portfolio_id)
     or (d.association_id is not null and not public.can_view_association_row(d.association_id)) then
    raise exception 'Bank deposit not found' using errcode = 'P0002';
  end if;
  if exists (
    select 1 from public.bank_reconciliation_items i
      join public.bank_reconciliations r on r.id = i.reconciliation_id and r.status = 'completed'
      join public.journal_lines jl on jl.id = i.journal_line_id
      join public.journal_entries je on je.id = jl.entry_id
     where i.is_cleared
       and ((je.source_type = 'payment' and je.source_id in (select id from public.payments where bank_deposit_id = p_id))
         or je.id in (select journal_entry_id from public.other_receipts where bank_deposit_id = p_id))) then
    raise exception 'This deposit cleared on a completed bank reconciliation and can no longer be undone' using errcode = '22023';
  end if;
  if exists (select 1 from public.bank_transactions where matched_bank_deposit_id = p_id) then
    raise exception 'The bank feed matched this deposit to a bank transaction; it can no longer be undone' using errcode = '22023';
  end if;
  update public.payments set bank_deposit_id = null where bank_deposit_id = p_id;
  update public.other_receipts set bank_deposit_id = null where bank_deposit_id = p_id;
  update public.bank_deposits set voided_at = now(), voided_by = auth.uid() where id = p_id;
  insert into public.audit_logs (portfolio_id, entity_type, entity_id, action, actor_id, changes)
  values (d.portfolio_id, 'bank_deposit', p_id, 'voided', auth.uid(), jsonb_build_object('amount', d.amount));
end $$;


ALTER FUNCTION "public"."void_bank_deposit"("p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."void_bank_transfer"("p_id" "uuid", "p_void_date" "date", "p_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  t public.bank_transfers;
  f public.bank_accounts;
  d public.bank_accounts;
  v_rev uuid;
  v_src uuid;
  v_first uuid;
begin
  select * into t from public.bank_transfers where id = p_id for update;
  if not found or not public.can_manage_finance(t.portfolio_id) then raise exception 'Transfer not found' using errcode = 'P0002'; end if;
  select * into f from public.bank_accounts where id = t.from_bank_account_id;
  select * into d from public.bank_accounts where id = t.to_bank_account_id;
  if not public.can_view_association_row(f.association_id) or not public.can_view_association_row(d.association_id) then
    raise exception 'This transfer involves an association you do not manage' using errcode = '42501';
  end if;
  if t.voided_at is not null then raise exception 'This transfer is already void' using errcode = '22023'; end if;
  if coalesce(p_void_date, current_date) < t.transfer_date then
    raise exception 'The void date can''t be before the transfer date (%)', t.transfer_date using errcode = '22023';
  end if;
  if length(btrim(coalesce(p_reason, ''))) < 3 then raise exception 'Give a reason for voiding the transfer' using errcode = '22023'; end if;
  if exists (select 1 from public.journal_entries where source_type = 'bank_transfer' and source_id = t.id and not posted) then
    raise exception 'This transfer has a draft journal entry. Discard it on Journal Entries (Drafts), then void the transfer.' using errcode = '22023';
  end if;

  for v_src in
    select id from public.journal_entries
     where posted and (id = t.journal_entry_id or (source_type = 'bank_transfer' and source_id = t.id))
     order by created_at
  loop
    insert into public.journal_entries (portfolio_id, entry_date, description, memo, reference_number, source_type, source_id, posted, created_by)
    values (t.portfolio_id, coalesce(p_void_date, current_date), 'Void bank transfer — ' || f.name || ' → ' || d.name,
            btrim(p_reason), t.reference_number, 'bank_transfer_void', t.id, false, auth.uid())
    returning id into v_rev;
    insert into public.journal_lines (entry_id, gl_account_id, association_id, debit_amount, credit_amount, memo, sort_order)
    select v_rev, gl_account_id, association_id, credit_amount, debit_amount, 'Void: ' || btrim(p_reason), sort_order
      from public.journal_lines where entry_id = v_src;
    update public.journal_entries set posted = true, posted_at = now() where id = v_rev;
    v_first := coalesce(v_first, v_rev);
  end loop;

  update public.bank_transfers set voided_at = now(), voided_by = auth.uid(), void_reason = btrim(p_reason), void_entry_id = v_first, updated_at = now()
   where id = t.id;
  insert into public.audit_logs (portfolio_id, entity_type, entity_id, action, actor_id, changes)
  values (t.portfolio_id, 'bank_transfer', t.id, 'voided', auth.uid(), jsonb_build_object('reason', btrim(p_reason), 'amount', t.amount));
  return v_first;
end $$;


ALTER FUNCTION "public"."void_bank_transfer"("p_id" "uuid", "p_void_date" "date", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."void_credit_card_charge"("p_charge_id" "uuid", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  c public.credit_card_charges;
  v_entry uuid;
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
begin
  select * into c from public.credit_card_charges where id = p_charge_id for update;
  if c.id is null or not (public.can_manage_finance(c.portfolio_id) and public.can_manage_association(c.association_id)) then
    raise exception 'Charge not found' using errcode = '42501';
  end if;
  if c.voided_at is not null then
    raise exception 'This charge is already void' using errcode = '22023';
  end if;
  if v_reason is null then
    raise exception 'Enter a reason for voiding' using errcode = '22023';
  end if;
  insert into public.journal_entries (portfolio_id, entry_date, reference_number, description, memo, source_type, source_id, posted, created_by)
  values (c.portfolio_id,
          coalesce(case when c.association_id is not null then public.association_local_date(c.association_id, now()) end, current_date),
          'VOID-' || coalesce(c.reference, left(c.id::text, 8)),
          left('Void: card charge ' || c.payee, 250), left(v_reason, 1000), 'credit_card_charge_void', c.id, false, auth.uid())
  returning id into v_entry;
  insert into public.journal_lines (entry_id, gl_account_id, association_id, debit_amount, credit_amount, memo, sort_order)
  select v_entry, jl.gl_account_id, jl.association_id, jl.credit_amount, jl.debit_amount, 'Void: ' || coalesce(jl.memo, ''), jl.sort_order
    from public.journal_lines jl where jl.entry_id = c.journal_entry_id;
  update public.journal_entries set posted = true, posted_at = now() where id = v_entry;
  update public.credit_card_charges
     set voided_at = now(), voided_by = auth.uid(), void_reason = left(v_reason, 500), void_journal_entry_id = v_entry
   where id = c.id;
end $$;


ALTER FUNCTION "public"."void_credit_card_charge"("p_charge_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."void_loan_payment"("p_payment_id" "uuid", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  p public.loan_payments;
  v_entry uuid;
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
  v_latest boolean;
begin
  if auth.uid() is null then
    raise exception 'Sign in to void loan payments' using errcode = '42501';
  end if;
  select * into p from public.loan_payments where id = p_payment_id for update;
  if p.id is null then
    raise exception 'Payment not found';
  end if;
  if not ((public.can_manage_finance(p.portfolio_id) and public.can_manage_association(p.association_id)) or public.is_platform_operator()) then
    raise exception 'You do not have accounting access to this association' using errcode = '42501';
  end if;
  if p.voided_at is not null then
    raise exception 'This payment is already void' using errcode = '22023';
  end if;
  if v_reason is null then
    raise exception 'Enter a reason for voiding' using errcode = '22023';
  end if;
  perform 1 from public.association_loans where id = p.loan_id for update;
  if exists (select 1 from public.loan_payments x where x.loan_id = p.loan_id and x.voided_at is null and x.id <> p.id
              and x.recorded_seq > p.recorded_seq) then
    raise exception 'Void the later payments on this loan first (newest first) so the balance and due date stay correct' using errcode = '22023';
  end if;

  insert into public.journal_entries (portfolio_id, entry_date, reference_number, description, memo, source_type, source_id, posted, created_by)
  values (p.portfolio_id, coalesce(public.association_local_date(p.association_id, now()), current_date),
          'VOID-' || coalesce(p.reference, left(p.id::text, 8)), 'Void: loan payment',
          left(v_reason, 1000), 'loan_payment_void', p.id, false, auth.uid())
  returning id into v_entry;
  insert into public.journal_lines (entry_id, gl_account_id, association_id, debit_amount, credit_amount, memo, sort_order)
  select v_entry, jl.gl_account_id, jl.association_id, jl.credit_amount, jl.debit_amount, 'Void: ' || coalesce(jl.memo, ''), jl.sort_order
    from public.journal_lines jl where jl.entry_id = p.journal_entry_id;
  update public.journal_entries set posted = true, posted_at = now() where id = v_entry;

  v_latest := not exists (select 1 from public.loan_payments x where x.loan_id = p.loan_id and x.voided_at is null
                            and x.id <> p.id and (x.created_at > p.created_at));
  perform set_config('app.loan_ledger', 'on', true);
  update public.association_loans
     set current_balance = current_balance + p.principal,
         status = case when status = 'paid_off' then 'active' else status end,
         next_payment_date = case when next_payment_date is not distinct from p.next_payment_date_after
                                  then p.previous_next_payment_date else next_payment_date end,
         updated_at = now()
   where id = p.loan_id;
  perform set_config('app.loan_ledger', '', true);

  update public.loan_payments
     set voided_at = now(), voided_by = auth.uid(), void_reason = left(v_reason, 500), void_journal_entry_id = v_entry
   where id = p.id;
end $$;


ALTER FUNCTION "public"."void_loan_payment"("p_payment_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."void_other_receipt"("p_receipt_id" "uuid", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  r public.other_receipts;
  v_entry uuid;
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
begin
  if auth.uid() is null then
    raise exception 'Sign in to void receipts' using errcode = '42501';
  end if;
  select * into r from public.other_receipts where id = p_receipt_id for update;
  if r.id is null then
    raise exception 'Receipt not found';
  end if;
  if not ((public.can_manage_finance(r.portfolio_id) and public.can_manage_association(r.association_id))
          or public.is_platform_operator()) then
    raise exception 'You do not have accounting access to this association' using errcode = '42501';
  end if;
  if r.voided_at is not null then
    raise exception 'This receipt is already void';
  end if;
  if r.bank_deposit_id is not null then
    raise exception 'This receipt is on a bank deposit. Remove it from its bank deposit first.' using errcode = '55000';
  end if;
  if v_reason is null then
    raise exception 'Enter a reason for voiding';
  end if;

  insert into public.journal_entries (portfolio_id, entry_date, reference_number, description, memo, source_type, source_id, posted, created_by)
  values (r.portfolio_id, current_date, 'VOID-' || coalesce(r.reference, left(r.id::text, 8)),
          'Void: receipt from ' || left(r.payer_name, 150), left(v_reason, 1000), 'other_receipt_void', r.id, false, auth.uid())
  returning id into v_entry;
  insert into public.journal_lines (entry_id, gl_account_id, association_id, debit_amount, credit_amount, memo, sort_order)
  select v_entry, jl.gl_account_id, jl.association_id, jl.credit_amount, jl.debit_amount, 'Void: ' || coalesce(jl.memo, ''), jl.sort_order
    from public.journal_lines jl where jl.entry_id = r.journal_entry_id;
  update public.journal_entries set posted = true, posted_at = now() where id = v_entry;

  update public.other_receipts
     set voided_at = now(), voided_by = auth.uid(), void_reason = left(v_reason, 500), void_journal_entry_id = v_entry
   where id = r.id;
end $$;


ALTER FUNCTION "public"."void_other_receipt"("p_receipt_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."void_owner_payable"("p_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  r public.owner_payables := public.app_owner_payable_for_update(p_id);
  v_rev uuid;
begin
  if r.status = 'paid' then raise exception 'Void the payment first' using errcode = '22023'; end if;
  if r.status = 'void' then return null; end if;
  if r.status = 'approved' then
    v_rev := public.app_reverse_owner_payable_entry(r, 'owner_payable', 'owner_payable_void', 'Void homeowner payable');
  end if;
  update public.owner_payables set status = 'void', updated_at = now() where id = r.id;
  insert into public.audit_logs (portfolio_id, entity_type, entity_id, action, actor_id, changes)
  values (r.portfolio_id, 'owner_payable', r.id, 'voided', auth.uid(), '{}'::jsonb);
  return v_rev;
end $$;


ALTER FUNCTION "public"."void_owner_payable"("p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."void_owner_payable_payment"("p_id" "uuid", "p_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  r public.owner_payables := public.app_owner_payable_for_update(p_id);
  v_rev uuid;
begin
  if r.status <> 'paid' then raise exception 'This payable has not been paid' using errcode = '22023'; end if;
  if length(btrim(coalesce(p_reason, ''))) < 3 then raise exception 'Give a reason for voiding the payment' using errcode = '22023'; end if;
  v_rev := public.app_reverse_owner_payable_entry(r, 'owner_payable_payment', 'owner_payable_payment_void', 'Void homeowner payment: ' || btrim(p_reason));
  update public.owner_payables set status = 'approved', paid_at = null, payment_method = null, payment_reference = null, updated_at = now() where id = r.id;
  insert into public.audit_logs (portfolio_id, entity_type, entity_id, action, actor_id, changes)
  values (r.portfolio_id, 'owner_payable', r.id, 'payment_voided', auth.uid(), jsonb_build_object('reason', btrim(p_reason)));
  return v_rev;
end $$;


ALTER FUNCTION "public"."void_owner_payable_payment"("p_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."void_payable_bill"("p_bill_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  bill_row public.payable_bills;
  accrual_id uuid;
  reversal_id uuid;
  line record;
begin
  select * into bill_row from public.payable_bills where id = p_bill_id for update;
  if not found then raise exception 'Bill not found'; end if;
  if not public.can_manage_finance(bill_row.portfolio_id) then raise exception 'Permission denied'; end if;
  if not public.can_view_association_row(bill_row.association_id) then raise exception 'Bill not found'; end if;
  if not public.operator_may_write(false) then raise exception 'Permission denied'; end if;
  if coalesce(bill_row.credit_applied, 0) > 0 then
    raise exception '%', 'A vendor credit is applied to this bill ' || chr(8212) || ' it can''t be voided' using errcode = '22023';
  end if;
  if bill_row.status = 'paid'::public.payable_bill_status or bill_row.paid_at is not null then
    raise exception 'Paid bills require a check void/stop-payment workflow';
  end if;
  if bill_row.status = 'void'::public.payable_bill_status then
    select id into reversal_id from public.journal_entries where source_type = 'payable_bill_void' and source_id = p_bill_id;
    return reversal_id;
  end if;

  select id into accrual_id from public.journal_entries where source_type = 'payable_bill' and source_id = p_bill_id;
  if accrual_id is not null then
    insert into public.journal_entries (
      portfolio_id, entry_date, description, memo, reference_number,
      source_type, source_id, created_by, posted, posted_at
    ) values (
      bill_row.portfolio_id, coalesce(public.association_local_date(bill_row.association_id, now()), current_date),
      'Void bill: ' || coalesce(bill_row.bill_number, p_bill_id::text), bill_row.memo,
      bill_row.bill_number, 'payable_bill_void', p_bill_id, auth.uid(), true, now()
    ) returning id into reversal_id;
    for line in select * from public.journal_lines where entry_id = accrual_id order by sort_order loop
      insert into public.journal_lines (entry_id, association_id, gl_account_id, debit_amount, credit_amount, memo, sort_order)
      values (reversal_id, line.association_id, line.gl_account_id, line.credit_amount, line.debit_amount, 'Reversal: ' || coalesce(line.memo, ''), line.sort_order);
    end loop;
  end if;
  update public.payable_bills set status = 'void'::public.payable_bill_status, updated_at = now() where id = p_bill_id;
  return reversal_id;
end;
$$;


ALTER FUNCTION "public"."void_payable_bill"("p_bill_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."void_payable_check"("p_check_id" "uuid", "p_reason" "text", "p_stop_payment" boolean DEFAULT false) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  check_row public.payable_checks;
  bill_row public.payable_bills;
  reversal_id uuid;
  line record;
  v_label text;
begin
  if length(trim(coalesce(p_reason, ''))) < 3 then raise exception 'A void/stop-payment reason is required'; end if;
  select * into check_row from public.payable_checks where id = p_check_id for update;
  if not found then raise exception 'Check not found'; end if;
  if not public.can_manage_finance(check_row.portfolio_id) then raise exception 'Permission denied'; end if;
  if not public.can_view_association_row(check_row.association_id) then raise exception 'Check not found'; end if;
  if check_row.status <> 'issued' then raise exception 'Only an issued check can be voided or stopped'; end if;

  select * into bill_row from public.payable_bills where id = check_row.bill_id for update;
  if bill_row.status <> 'paid'::public.payable_bill_status
     or bill_row.bank_account_id is distinct from check_row.bank_account_id
     or bill_row.check_number::integer is distinct from check_row.check_number then
    raise exception 'Bill no longer matches this issued check';
  end if;

  v_label := case when check_row.check_number is not null then 'check #' || check_row.check_number::text
                  else 'payment' || coalesce(' ' || check_row.reference, '') end;
  insert into public.journal_entries (
    portfolio_id, entry_date, description, memo, reference_number,
    source_type, source_id, created_by, posted, posted_at
  ) values (
    check_row.portfolio_id, coalesce(public.association_local_date(coalesce(check_row.association_id, bill_row.association_id), now()), current_date),
    case when p_stop_payment then 'Stop payment ' else 'Void ' end || v_label,
    trim(p_reason), coalesce(check_row.check_number::text, check_row.reference),
    'check_payment_void', check_row.id, auth.uid(), true, now()
  ) returning id into reversal_id;
  for line in select * from public.journal_lines where entry_id = check_row.payment_entry_id order by sort_order loop
    insert into public.journal_lines (entry_id, association_id, gl_account_id, debit_amount, credit_amount, memo, sort_order)
    values (reversal_id, line.association_id, line.gl_account_id, line.credit_amount, line.debit_amount,
      case when p_stop_payment then 'Stop payment: ' else 'Void: ' end || trim(p_reason), line.sort_order);
  end loop;

  update public.payable_checks set
    status = case when p_stop_payment then 'stop_payment' else 'voided' end,
    void_entry_id = reversal_id, voided_by = auth.uid(), voided_at = now(), void_reason = trim(p_reason)
   where id = p_check_id;
  update public.payable_bills set
    status = 'approved'::public.payable_bill_status,
    paid_at = null, check_number = null, updated_at = now()
   where id = check_row.bill_id;
  return reversal_id;
end;
$$;


ALTER FUNCTION "public"."void_payable_check"("p_check_id" "uuid", "p_reason" "text", "p_stop_payment" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."void_signature_request"("p_id" "uuid", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare r public.signature_requests;
begin
  select * into r from public.signature_requests where id = p_id for update;
  if not found
     or not public.can_manage_signatures(r.portfolio_id)
     or not public.can_view_association_row(r.association_id) then
    raise exception 'Permission denied' using errcode = '42501';
  end if;
  if r.status <> 'sent' then raise exception 'Only an in-progress request can be voided' using errcode = '22023'; end if;
  if char_length(btrim(coalesce(p_reason, ''))) < 5 then raise exception 'Enter a reason' using errcode = '22023'; end if;
  update public.signature_requests set status = 'voided', voided_at = now(), void_reason = left(btrim(p_reason), 500) where id = p_id;
  insert into public.signature_events (request_id, event_type, actor_id, detail) values (p_id, 'voided', auth.uid(), jsonb_build_object('reason', left(btrim(p_reason), 500)));
end;
$$;


ALTER FUNCTION "public"."void_signature_request"("p_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."work_order_assign_number"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare v_sr_number text; v_portfolio uuid; v_n int;
begin
  if new.number is not null then return new; end if;
  if new.service_request_id is not null then
    perform pg_advisory_xact_lock(hashtextextended('wo-number:' || new.service_request_id::text, 0));
    select number into v_sr_number from public.service_requests where id = new.service_request_id;
    if v_sr_number is not null then
      select coalesce(max(nullif(split_part(number, '-', 2), '')::int), 0) + 1 into v_n
        from public.work_orders
       where service_request_id = new.service_request_id and number ~ '^[0-9]+-[0-9]+$';
      new.number := v_sr_number || '-' || v_n;
      return new;
    end if;
  end if;
  v_portfolio := new.portfolio_id;
  if v_portfolio is null and new.association_id is not null then
    select portfolio_id into v_portfolio from public.associations where id = new.association_id;
  end if;
  if v_portfolio is not null then
    new.number := public.next_maintenance_number(v_portfolio) || '-1';
  end if;
  return new;
end $_$;


ALTER FUNCTION "public"."work_order_assign_number"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."work_order_staff"("p_work_order" "uuid") RETURNS TABLE("id" "uuid", "name" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare w record;
begin
  select wo.id, coalesce(wo.portfolio_id, a.portfolio_id) as portfolio_id, wo.association_id into w
    from public.work_orders wo left join public.associations a on a.id = wo.association_id
   where wo.id = p_work_order;
  if w.id is null or not (public.is_platform_operator() or public.is_any_staff() or public.is_company_admin())
     or not public.can_access_portfolio(w.portfolio_id) or not public.can_manage_association(w.association_id) then
    return;
  end if;
  return query
    select p.id, coalesce(nullif(btrim(p.full_name), ''), nullif(btrim(p.display_name), ''), p.email)
      from public.profiles p
     where p.portfolio_id = w.portfolio_id and p.disabled_at is null and p.hoa_role in ('manager', 'company_admin')
       and (p.hoa_role = 'company_admin'
            or not exists (select 1 from public.association_managers am where am.user_id = p.id)
            or exists (select 1 from public.association_managers am where am.user_id = p.id and am.association_id = w.association_id))
     order by 2;
end $$;


ALTER FUNCTION "public"."work_order_staff"("p_work_order" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."work_order_stamp_completion"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare finishing text[] := array['done', 'completed', 'billed', 'closed'];
begin
  if new.status::text = any (finishing) then
    if tg_op = 'UPDATE' and old.status::text = any (finishing) then
      if new.status is distinct from old.status then
        new.completed_date := coalesce(old.completed_date, new.completed_date, public.association_local_date(new.association_id));
      end if;
      new.completed_by_assignee_id := old.completed_by_assignee_id;
    else
      if new.completed_date is null then new.completed_date := public.association_local_date(new.association_id); end if;
      new.completed_by_assignee_id := new.assignee_id;
    end if;
  elsif new.status = 'cancelled' then
    if tg_op = 'INSERT' or old.status is distinct from 'cancelled' then new.completed_date := null; end if;
    new.completed_by_assignee_id := null;
  else
    if tg_op = 'UPDATE' and (old.status::text = any (finishing) or old.status = 'cancelled') then
      new.completed_date := null;
    end if;
    new.completed_by_assignee_id := null;
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."work_order_stamp_completion"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."work_order_sync_request_triage"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  -- work_orders_fixes: open = not finished, cancelled or archived.
  v_old_open boolean := tg_op <> 'INSERT' and old.archived_at is null
    and old.status::text not in ('done', 'completed', 'billed', 'closed', 'cancelled');
  v_new_open boolean := tg_op <> 'DELETE' and new.archived_at is null
    and new.status::text not in ('done', 'completed', 'billed', 'closed', 'cancelled');
  v_sr uuid;
begin
  if tg_op in ('UPDATE', 'DELETE') and old.service_request_id is not null then
    perform public.refresh_service_request_open_work_order(old.service_request_id);
  end if;
  if tg_op in ('INSERT', 'UPDATE') and new.service_request_id is not null
     and (tg_op = 'INSERT' or new.service_request_id is distinct from old.service_request_id
          or new.status is distinct from old.status or new.archived_at is distinct from old.archived_at) then
    perform public.refresh_service_request_open_work_order(new.service_request_id);
  end if;

  -- An open work order finished, was cancelled, archived, deleted or moved
  -- to another request (or one was added already finished): when no open
  -- work order is left and one is finished, the request is completed.
  if v_old_open and old.service_request_id is not null
     and (tg_op = 'DELETE' or not v_new_open or new.service_request_id is distinct from old.service_request_id) then
    v_sr := old.service_request_id;
  elsif tg_op = 'INSERT' and new.service_request_id is not null and new.archived_at is null
     and new.status::text in ('done', 'completed', 'billed', 'closed') then
    v_sr := new.service_request_id;
  end if;
  if v_sr is not null then
    update public.service_requests s
       set status = 'completed',
           resolved_at = coalesce(s.resolved_at, now())
     where s.id = v_sr
       and s.archived_at is null
       and s.status in ('open', 'waiting')
       and not exists (
         select 1 from public.work_orders w
          where w.service_request_id = s.id
            and w.archived_at is null
            and w.status::text not in ('done', 'completed', 'billed', 'closed', 'cancelled'))
       and exists (
         select 1 from public.work_orders w
          where w.service_request_id = s.id
            and w.archived_at is null
            and w.status::text in ('done', 'completed', 'billed', 'closed'));
  end if;

  -- work_orders_followups: an open work order newly in this request (added,
  -- moved in, unarchived, or reopened from finished or cancelled): its
  -- completed request is waiting again (a cancelled request stays cancelled).
  if v_new_open and new.service_request_id is not null
     and (tg_op = 'INSERT' or not v_old_open
          or new.service_request_id is distinct from old.service_request_id) then
    update public.service_requests s
       set status = 'waiting',
           resolved_at = null,
           resolved_by = null
     where s.id = new.service_request_id
       and s.archived_at is null
       and s.status = 'completed';
  end if;
  return null;
end $$;


ALTER FUNCTION "public"."work_order_sync_request_triage"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."work_order_unit_in_association"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_portfolio uuid;
begin
  if new.association_id is not null then
    select portfolio_id into v_portfolio from public.associations where id = new.association_id;
    if new.portfolio_id is null then
      new.portfolio_id := v_portfolio;
    elsif v_portfolio is not null and new.portfolio_id <> v_portfolio then
      raise exception 'That association belongs to a different company' using errcode = '23514';
    end if;
  end if;
  if new.unit_id is not null
     and (tg_op = 'INSERT' or new.unit_id is distinct from old.unit_id or new.association_id is distinct from old.association_id)
     and not exists (select 1 from public.units u join public.buildings b on b.id = u.building_id
                      where u.id = new.unit_id and b.association_id = new.association_id) then
    raise exception 'That unit is not in the selected association' using errcode = '23514';
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."work_order_unit_in_association"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."work_order_vendor_in_company"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_vendor_portfolio uuid; v_portfolio uuid;
begin
  if new.vendor_id is null then return new; end if;
  if tg_op = 'UPDATE' and new.vendor_id is not distinct from old.vendor_id
     and new.portfolio_id is not distinct from old.portfolio_id then
    return new;
  end if;
  v_portfolio := new.portfolio_id;
  if v_portfolio is null and new.association_id is not null then
    select a.portfolio_id into v_portfolio from public.associations a where a.id = new.association_id;
  end if;
  select v.portfolio_id into v_vendor_portfolio from public.vendors v where v.id = new.vendor_id;
  if v_vendor_portfolio is null or v_vendor_portfolio is distinct from v_portfolio then
    raise exception 'That vendor belongs to a different company' using errcode = '23514';
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."work_order_vendor_in_company"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."work_orders_vendor_update_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare v_status public.work_order_status;
begin
  if auth.uid() is null
     or public.is_platform_operator() or public.is_any_staff() or public.is_company_admin() then
    return new;
  end if;
  v_status := new.status;
  new := old;
  if v_status is distinct from old.status then
    if old.status::text not in ('new', 'assigned', 'scheduled', 'in_progress')
       or v_status::text not in ('scheduled', 'in_progress', 'done') then
      raise exception 'Vendors can only mark a job scheduled, in progress or complete; a completed job can only be reopened by management' using errcode = '42501';
    end if;
    new.status := v_status;
  end if;
  new.updated_at := now();
  return new;
end $$;


ALTER FUNCTION "public"."work_orders_vendor_update_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."year_end_readiness"("p_association_id" "uuid", "p_fiscal_year" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $_$
declare
  v_portfolio uuid; w record; v_open_periods integer; v_missing_periods integer; v_unposted integer; v_unreconciled integer;
  v_debits numeric; v_credits numeric; v_clearing numeric; v_1099 integer; v_budget integer; items jsonb := '[]'::jsonb;
begin
  select portfolio_id into v_portfolio from public.associations where id = p_association_id;
  if v_portfolio is null then raise exception 'Association not found'; end if;
  if not (public.can_access_portfolio(v_portfolio) and public.can_view_association_row(p_association_id)
          and (public.is_any_staff() or public.is_company_admin() or public.is_platform_operator())) then
    raise exception 'Permission denied' using errcode = '42501';
  end if;
  select * into w from public.association_fiscal_window(p_association_id, p_fiscal_year);

  select count(*) filter (where ap.id is null), count(*) filter (where ap.id is not null and ap.status::text <> 'closed')
    into v_missing_periods, v_open_periods
    from generate_series(w.period_start, w.period_end, interval '1 month') g(month_start)
    left join public.accounting_periods ap
      on ap.portfolio_id = v_portfolio
     and ap.fiscal_year = extract(year from g.month_start)::integer
     and ap.period_month = extract(month from g.month_start)::integer;

  select count(distinct je.id) into v_unposted
    from public.journal_entries je join public.journal_lines jl on jl.entry_id = je.id
   where jl.association_id = p_association_id and not je.posted and je.entry_date between w.period_start and w.period_end;

  select count(*) into v_unreconciled from public.bank_accounts b
   where b.association_id = p_association_id and b.archived_at is null
     and (b.last_reconciliation_date is null or b.last_reconciliation_date < w.period_end);

  select coalesce(sum(jl.debit_amount), 0), coalesce(sum(jl.credit_amount), 0) into v_debits, v_credits
    from public.journal_lines jl join public.journal_entries je on je.id = jl.entry_id
   where jl.association_id = p_association_id and je.posted and je.entry_date <= w.period_end;

  select coalesce(sum(abs(t.bal)), 0) into v_clearing from (
    select sum(jl.debit_amount - jl.credit_amount) bal
      from public.journal_lines jl join public.journal_entries je on je.id = jl.entry_id join public.gl_accounts g on g.id = jl.gl_account_id
     where jl.association_id = p_association_id and je.posted and je.entry_date <= w.period_end
       and (g.name ilike '%clearing%' or g.name ilike '%suspense%')
     group by g.id) t;

  select count(*) into v_1099 from (
    select b.vendor_id from public.payable_bills b join public.vendors v on v.id = b.vendor_id
     where b.association_id = p_association_id and b.status::text = 'paid'
       and b.paid_at::date between w.period_start and w.period_end
       and coalesce(v.send_1099, false) and not v.has_taxpayer_id
     group by b.vendor_id having sum(b.amount - b.credit_applied) >= 600) x;

  select count(*) into v_budget from public.budget_lines where association_id = p_association_id and fiscal_year = p_fiscal_year;

  items := jsonb_build_array(
    jsonb_build_object('key', 'periods_closed', 'required', true, 'ok', v_open_periods = 0 and v_missing_periods = 0,
      'label', 'All accounting months in the fiscal year are closed',
      'detail', case when v_missing_periods > 0 then v_missing_periods || ' month(s) not initialized'
                     when v_open_periods > 0 then v_open_periods || ' month(s) still open' else 'All 12 months closed' end),
    jsonb_build_object('key', 'no_drafts', 'required', true, 'ok', v_unposted = 0,
      'label', 'No draft journal entries in the year', 'detail', v_unposted || ' draft entr' || case when v_unposted = 1 then 'y' else 'ies' end),
    jsonb_build_object('key', 'banks_reconciled', 'required', true, 'ok', v_unreconciled = 0,
      'label', 'Every bank account reconciled through year end', 'detail', v_unreconciled || ' account(s) not reconciled through ' || w.period_end),
    jsonb_build_object('key', 'trial_balance', 'required', true, 'ok', abs(v_debits - v_credits) < 0.005,
      'label', 'Trial balance is in balance', 'detail', 'Debits $' || to_char(v_debits, 'FM999,999,990.00') || ' · credits $' || to_char(v_credits, 'FM999,999,990.00')),
    jsonb_build_object('key', 'clearing_zero', 'required', false, 'ok', v_clearing < 0.005,
      'label', 'Clearing and suspense accounts are zero', 'detail', '$' || to_char(v_clearing, 'FM999,999,990.00') || ' unresolved'),
    jsonb_build_object('key', 'vendor_tins', 'required', false, 'ok', v_1099 = 0,
      'label', '1099 vendors paid $600+ have a taxpayer ID', 'detail', v_1099 || ' vendor(s) missing a TIN'),
    jsonb_build_object('key', 'budget', 'required', false, 'ok', v_budget > 0,
      'label', 'An annual budget exists for comparison', 'detail', v_budget || ' budget line(s)')
  );
  return jsonb_build_object('period_start', w.period_start, 'period_end', w.period_end, 'items', items,
    'ready', not exists (select 1 from jsonb_array_elements(items) i where (i ->> 'required')::boolean and not (i ->> 'ok')::boolean));
end;
$_$;


