CREATE OR REPLACE FUNCTION "rls_private"."my_budget_readable_association_ids"() RETURNS SETOF "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  -- Every association can_read_association_budget() lets the caller read.
  if auth.uid() is null then
    return;
  end if;
  if coalesce(public.is_platform_operator(), false) then
    return query select a.id from public.associations a;
    return;
  end if;
  if coalesce(public.is_any_staff(), false) or coalesce(public.is_company_admin(), false) then
    -- can_access_portfolio for a non-operator is "the caller's company";
    -- a scoped manager only their associations (can_access_association).
    return query select a.id from public.associations a
      where a.portfolio_id = public.my_access_portfolio()
        and (not coalesce(public.manager_is_scoped(), false)
             or a.id in (select public.my_managed_association_ids()));
  end if;
  if coalesce(public.is_board_user(), false) then
    return query select a.id from public.associations a where a.id in (select public.current_board_association_ids());
  end if;
end
$$;


ALTER FUNCTION "rls_private"."my_budget_readable_association_ids"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "rls_private"."my_confidential_meeting_association_ids"() RETURNS SETOF "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  -- can_access_confidential_meeting_mvp, as a set. Change both together.
  if not coalesce(public.is_current_identity_enabled(), false) then
    return;
  end if;
  if coalesce(public.is_platform_operator(), false) then
    return query select a.id from public.associations a;
    return;
  end if;
  return query
  select a.id
    from public.profiles p
    join public.associations a on a.portfolio_id = p.portfolio_id
   where p.id = auth.uid()
     and (p.mvp_role in ('company_admin', 'accountant') or p.hoa_role = 'company_admin')
  union
  select a.id
    from public.profiles p
    join public.association_managers am on am.user_id = p.id and am.ended_at is null
    join public.associations a on a.id = am.association_id and a.portfolio_id = p.portfolio_id
   where p.id = auth.uid()
     and (p.mvp_role = 'manager' or (p.mvp_role is null and p.hoa_role = 'manager'))
  union
  select a.id
    from public.profiles p
    join public.associations a on a.portfolio_id = p.portfolio_id
   where p.id = auth.uid()
     and p.hoa_role = 'manager'
     and (p.mvp_role is null or p.mvp_role = 'manager')
     and public.manager_is_scoped() is not true
  union
  select a.id
    from public.profiles p
    join public.association_managers am on am.user_id = p.id and am.ended_at is null
    join public.associations a on a.id = am.association_id and a.portfolio_id = p.portfolio_id
   where p.id = auth.uid()
     and p.disabled_at is null
     and p.mvp_role = 'assistant_manager'
  union
  select bm.association_id
    from public.board_members bm
   where bm.auth_user_id = auth.uid()
     and bm.active = true
     and bm.association_id is not null;
end
$$;


ALTER FUNCTION "rls_private"."my_confidential_meeting_association_ids"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "rls_private"."my_document_entity_ids"("p_entity_type" "text") RETURNS SETOF "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
declare
  v_op boolean := coalesce(public.is_platform_operator(), false);
  v_pf uuid := public.my_access_portfolio();
begin
  -- Ids of the records of one documents.entity_type whose company
  -- can_access_portfolio() lets the caller reach (document_portfolio_id twin;
  -- 'general' returns profile ids, matched with coalesce(uploaded_by, me)).
  -- Change together with public.document_portfolio_id.
  if not v_op and v_pf is null then
    return;
  end if;
  if p_entity_type = 'association' then
    return query select a.id from public.associations a
      where case when v_op then a.portfolio_id is not null else a.portfolio_id = v_pf end;
  elsif p_entity_type = 'owner' then
    return query select o.id from public.owners o
      where case when v_op then o.portfolio_id is not null else o.portfolio_id = v_pf end;
  elsif p_entity_type = 'vendor' then
    return query select v.id from public.vendors v
      where case when v_op then v.portfolio_id is not null else v.portfolio_id = v_pf end;
  elsif p_entity_type = 'unit' then
    return query select u.id from public.units u
      join public.buildings b on b.id = u.building_id
      join public.associations a on a.id = b.association_id
      where case when v_op then a.portfolio_id is not null else a.portfolio_id = v_pf end;
  elsif p_entity_type = 'general' then
    return query select p.id from public.profiles p
      where case when v_op then p.portfolio_id is not null else p.portfolio_id = v_pf end;
  end if;
end
$$;


ALTER FUNCTION "rls_private"."my_document_entity_ids"("p_entity_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "rls_private"."my_hidden_journal_entry_ids"() RETURNS SETOF "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  if (select public.manager_is_scoped()) is not true then
    return;
  end if;
  -- Entries of the caller's company whose every line is in an association
  -- the scoped manager is not assigned to.
  return query
  select je.id
    from public.journal_entries je
   where je.portfolio_id = (select public.my_access_portfolio())
     and exists (select 1 from public.journal_lines l where l.entry_id = je.id)
     and not exists (
       select 1 from public.journal_lines l
        where l.entry_id = je.id
          and (l.association_id is null
               or l.association_id in (select public.my_managed_association_ids())));
end
$$;


