CREATE OR REPLACE FUNCTION "rls_private"."resident_visible_statement_ids"() RETURNS SETOF "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
#variable_conflict use_column
begin
  return query
  select s.id
    from public.statements s
   where s.owner_id in (select public.current_owner_ids())
  union
  select s.id
    from public.statements s
    join rls_private.resident_unit_tenure() t on t.unit_id = s.unit_id
   where (t.since is null
          or make_date(s.period_year, s.period_month, 1) >= date_trunc('month', t.since)::date)
     and exists (
       select 1 from public.occupancies o
        where o.unit_id = s.unit_id
          and o.owner_id = s.owner_id
          and o.occupancy_type = 'owner'
          and o.status = 'current'
          and (o.move_out_date is null
               or o.move_out_date > public.association_local_date(o.association_id)));
end
$$;


ALTER FUNCTION "rls_private"."resident_visible_statement_ids"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "rls_private"."resident_visible_work_order_ids"() RETURNS SETOF "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
#variable_conflict use_column
begin
  -- work_orders_fixes: a work order's day is its association's local date.
  return query
  select w.id
    from public.work_orders w
    join rls_private.resident_unit_tenure() t on t.unit_id = w.unit_id
    left join public.associations a on a.id = w.association_id
   where t.since is null
      or (w.created_at at time zone coalesce(nullif(a.timezone, ''), 'America/Chicago'))::date >= t.since;
end
$$;


ALTER FUNCTION "rls_private"."resident_visible_work_order_ids"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "rls_private"."tenant_visible_work_order_ids"() RETURNS SETOF "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
#variable_conflict use_column
begin
  -- work_orders_fixes: a work order's day is its association's local date.
  return query
  select w.id
    from public.work_orders w
    join public.tenants t on t.unit_id = w.unit_id
    left join public.associations a on a.id = w.association_id
   where t.id in (select public.current_tenant_ids())
     and w.unit_id in (select public.current_tenant_unit_ids())
     and w.archived_at is null
     and (t.lease_start is null
          or (w.created_at at time zone coalesce(nullif(a.timezone, ''), 'America/Chicago'))::date >= t.lease_start);
end
$$;


ALTER FUNCTION "rls_private"."tenant_visible_work_order_ids"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "rls_private"."vendor_work_order_status"("p_work_order_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public'
    AS $$
begin
  return (select wo.status::text from public.work_orders wo
           where wo.id = p_work_order_id
             and wo.vendor_id in (select public.current_vendor_ids()));
end
$$;


