CREATE OR REPLACE VIEW "public"."capital_project_financials" WITH ("security_invoker"='true') AS
 SELECT "project"."id" AS "project_id",
    ("count"(DISTINCT "link"."work_order_id"))::integer AS "work_order_count",
    (COALESCE("sum"("bill"."amount") FILTER (WHERE ("bill"."status" = ANY (ARRAY['approved'::"public"."payable_bill_status", 'paid'::"public"."payable_bill_status"]))), (0)::numeric))::numeric(16,2) AS "committed_spend"
   FROM (("public"."capital_projects" "project"
     LEFT JOIN "public"."capital_project_work_orders" "link" ON (("link"."project_id" = "project"."id")))
     LEFT JOIN "public"."payable_bills" "bill" ON ((("bill"."work_order_id" = "link"."work_order_id") AND ("bill"."archived_at" IS NULL))))
  GROUP BY "project"."id";


ALTER VIEW "public"."capital_project_financials" OWNER TO "postgres";


