CREATE OR REPLACE VIEW "public"."v_charge_balances" WITH ("security_invoker"='true') AS
 SELECT "c"."id" AS "charge_id",
    "c"."unit_id",
    "c"."assessment_period_id",
    "c"."charge_type",
    "c"."description",
    "c"."amount" AS "charged_amount",
    COALESCE("pa"."paid", (0)::numeric) AS "applied_amount",
    ("c"."amount" - COALESCE("pa"."paid", (0)::numeric)) AS "balance_due",
    "c"."due_date",
        CASE
            WHEN ((("c"."amount" - COALESCE("pa"."paid", (0)::numeric)) <= (0)::numeric) AND ("c"."charge_type" = 'late_fee'::"public"."charge_type") AND (EXISTS ( SELECT 1
               FROM ("public"."payment_applications" "ra"
                 JOIN "public"."payments" "rp" ON (("rp"."id" = "ra"."payment_id")))
              WHERE (("ra"."charge_id" = "c"."id") AND ("rp"."charge_id" = "c"."id") AND ("rp"."method" = 'credit'::"text") AND ("rp"."reference" = 'Late fee removed'::"text") AND ("rp"."reversed_at" IS NULL))))) THEN 'removed'::"text"
            WHEN (("c"."amount" - COALESCE("pa"."paid", (0)::numeric)) <= (0)::numeric) THEN 'paid'::"text"
            WHEN (COALESCE("pa"."paid", (0)::numeric) = (0)::numeric) THEN 'outstanding'::"text"
            ELSE 'partial'::"text"
        END AS "payment_status",
        CASE
            WHEN ((("c"."amount" - COALESCE("pa"."paid", (0)::numeric)) > (0)::numeric) AND ("c"."due_date" <= (("now"() AT TIME ZONE 'UTC'::"text"))::"date") AND ("c"."due_date" < COALESCE(( SELECT (("now"() AT TIME ZONE COALESCE(NULLIF("a"."timezone", ''::"text"), 'America/Chicago'::"text")))::"date" AS "timezone"
               FROM (("public"."units" "u"
                 JOIN "public"."buildings" "b" ON (("b"."id" = "u"."building_id")))
                 JOIN "public"."associations" "a" ON (("a"."id" = "b"."association_id")))
              WHERE ("u"."id" = "c"."unit_id")), (("now"() AT TIME ZONE 'UTC'::"text"))::"date"))) THEN true
            ELSE false
        END AS "is_past_due"
   FROM ("public"."charges" "c"
     LEFT JOIN LATERAL ( SELECT "sum"("p"."amount_applied") AS "paid"
           FROM "public"."payment_applications" "p"
          WHERE ("p"."charge_id" = "c"."id")) "pa" ON (true));


ALTER VIEW "public"."v_charge_balances" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_charge_balances" IS 'Per-charge balance = charged - sum(payment_applications.amount_applied). This is the live status of every charge.';



CREATE OR REPLACE VIEW "public"."v_charges_by_category" WITH ("security_invoker"='true') AS
 SELECT "a"."portfolio_id",
    "a"."id" AS "association_id",
    "a"."name" AS "association_name",
    "cc"."id" AS "category_id",
    "cc"."name" AS "category_name",
    "cc"."code" AS "category_code",
    "cc"."is_assessment",
    "cc"."is_fee",
    ("date_trunc"('month'::"text", ("c"."due_date")::timestamp with time zone))::"date" AS "period_month",
    "count"(*) AS "charge_count",
    "sum"("c"."amount") AS "total_charged",
    "sum"(COALESCE("pa"."paid", (0)::numeric)) AS "total_applied",
    "sum"(("c"."amount" - COALESCE("pa"."paid", (0)::numeric))) AS "outstanding_balance"
   FROM ((((("public"."charges" "c"
     JOIN "public"."units" "u" ON (("u"."id" = "c"."unit_id")))
     JOIN "public"."buildings" "b" ON (("b"."id" = "u"."building_id")))
     JOIN "public"."associations" "a" ON (("a"."id" = "b"."association_id")))
     LEFT JOIN "public"."charge_categories" "cc" ON (("cc"."id" = "c"."charge_category_id")))
     LEFT JOIN LATERAL ( SELECT "sum"("p"."amount_applied") AS "paid"
           FROM "public"."payment_applications" "p"
          WHERE ("p"."charge_id" = "c"."id")) "pa" ON (true))
  GROUP BY "a"."portfolio_id", "a"."id", "a"."name", "cc"."id", "cc"."name", "cc"."code", "cc"."is_assessment", "cc"."is_fee", ("date_trunc"('month'::"text", ("c"."due_date")::timestamp with time zone));


ALTER VIEW "public"."v_charges_by_category" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_check_writing_queue" WITH ("security_invoker"='true') AS
 SELECT "pb"."id" AS "bill_id",
    "pb"."portfolio_id",
    "pb"."vendor_id",
    "v"."name" AS "vendor_name",
    "v"."address_street",
    "v"."address_city",
    "v"."address_state",
    "v"."address_zip",
    "pb"."association_id",
    "a"."name" AS "association_name",
    (("pb"."amount" - "pb"."credit_applied"))::numeric(14,2) AS "amount",
    "pb"."bill_date",
    "pb"."due_date",
    "pb"."memo",
    "pb"."gl_account_id",
    "pb"."bank_account_id",
    (CURRENT_DATE - "pb"."due_date") AS "days_past_due",
    "pb"."amount" AS "bill_amount",
    "pb"."credit_applied"
   FROM (("public"."payable_bills" "pb"
     JOIN "public"."vendors" "v" ON (("v"."id" = "pb"."vendor_id")))
     LEFT JOIN "public"."associations" "a" ON (("a"."id" = "pb"."association_id")))
  WHERE (("pb"."archived_at" IS NULL) AND ("pb"."status" = 'approved'::"public"."payable_bill_status") AND ("pb"."paid_at" IS NULL) AND ("v"."payment_type" = 'check'::"public"."vendor_payment_type") AND (NOT "v"."is_auto_pay") AND (NOT "v"."hold_payments"))
  ORDER BY "pb"."due_date", "v"."name";


ALTER VIEW "public"."v_check_writing_queue" OWNER TO "postgres";


COMMENT ON VIEW "public"."v_check_writing_queue" IS 'Bills awaiting check-writing: approved, unpaid, vendor pays by check, not auto-pay. Used by the weekly check run UI.';



