    "would_hire_again" boolean,
    "comment" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "work_order_ratings_comment_check" CHECK ((("comment" IS NULL) OR ("length"("comment") <= 2000))),
    CONSTRAINT "work_order_ratings_communication_check" CHECK ((("communication" >= 1) AND ("communication" <= 5))),
    CONSTRAINT "work_order_ratings_quality_check" CHECK ((("quality" >= 1) AND ("quality" <= 5))),
    CONSTRAINT "work_order_ratings_rater_role_check" CHECK (("rater_role" = ANY (ARRAY['staff'::"text", 'owner'::"text", 'board'::"text"]))),
    CONSTRAINT "work_order_ratings_score_check" CHECK ((("score" >= 1) AND ("score" <= 5))),
    CONSTRAINT "work_order_ratings_timeliness_check" CHECK ((("timeliness" >= 1) AND ("timeliness" <= 5)))
);


ALTER TABLE "public"."work_order_ratings" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."work_order_updates" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "work_order_id" "uuid" NOT NULL,
    "note" "text" NOT NULL,
    "new_status" "public"."work_order_status",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "staff_only" boolean DEFAULT false NOT NULL,
    CONSTRAINT "work_order_updates_note_check" CHECK ((("length"("note") >= 1) AND ("length"("note") <= 2000)))
);


ALTER TABLE "public"."work_order_updates" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."work_order_vendor_private" (
    "work_order_id" "uuid" NOT NULL,
    "vendor_instructions" "text",
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."work_order_vendor_private" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."workflows" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "description" "text",
    "steps" "jsonb" DEFAULT '[]'::"jsonb",
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"()
);


ALTER TABLE "public"."workflows" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."year_end_packages" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "portfolio_id" "uuid" NOT NULL,
    "association_id" "uuid" NOT NULL,
    "fiscal_year" integer NOT NULL,
    "period_start" "date" NOT NULL,
    "period_end" "date" NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "checklist" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "snapshot" "jsonb" NOT NULL,
    "snapshot_sha256" "text" NOT NULL,
    "notes" "text",
    "generated_by" "uuid",
    "generated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "finalized_by" "uuid",
    "finalized_at" timestamp with time zone,
    "superseded_by" "uuid",
    "superseded_at" timestamp with time zone,
    "supersede_reason" "text",
    "signature_request_id" "uuid",
    CONSTRAINT "year_end_packages_fiscal_year_check" CHECK ((("fiscal_year" >= 2000) AND ("fiscal_year" <= 2100))),
    CONSTRAINT "year_end_packages_snapshot_sha256_check" CHECK (("snapshot_sha256" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "year_end_packages_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'finalized'::"text", 'superseded'::"text"])))
);


ALTER TABLE "public"."year_end_packages" OWNER TO "postgres";


