CASE "lower"("btrim"("entity_type"))
    WHEN 'association'::"text" THEN COALESCE(("entity_id" IN ( SELECT "rls_private"."my_document_entity_ids"('association'::"text") AS "my_document_entity_ids")), false)
    WHEN 'owner'::"text" THEN COALESCE(("entity_id" IN ( SELECT "rls_private"."my_document_entity_ids"('owner'::"text") AS "my_document_entity_ids")), false)
    WHEN 'vendor'::"text" THEN COALESCE(("entity_id" IN ( SELECT "rls_private"."my_document_entity_ids"('vendor'::"text") AS "my_document_entity_ids")), false)
    WHEN 'unit'::"text" THEN COALESCE(("entity_id" IN ( SELECT "rls_private"."my_document_entity_ids"('unit'::"text") AS "my_document_entity_ids")), false)
    WHEN 'general'::"text" THEN COALESCE((COALESCE("uploaded_by", ( SELECT "auth"."uid"() AS "uid")) IN ( SELECT "rls_private"."my_document_entity_ids"('general'::"text") AS "my_document_entity_ids")), false)
    ELSE false
END)) WITH CHECK (((( SELECT "auth"."uid"() AS "uid") IS NOT NULL) AND (( SELECT "public"."is_any_staff"() AS "is_any_staff") OR ( SELECT "public"."is_company_admin"() AS "is_company_admin")) AND (("uploaded_by" IS NULL) OR ("uploaded_by" = ( SELECT "auth"."uid"() AS "uid"))) AND "public"."document_path_matches_entity"("entity_type", "entity_id", "file_url") AND
CASE "lower"("btrim"("entity_type"))
    WHEN 'association'::"text" THEN COALESCE(("entity_id" IN ( SELECT "rls_private"."my_document_entity_ids"('association'::"text") AS "my_document_entity_ids")), false)
    WHEN 'owner'::"text" THEN COALESCE(("entity_id" IN ( SELECT "rls_private"."my_document_entity_ids"('owner'::"text") AS "my_document_entity_ids")), false)
    WHEN 'vendor'::"text" THEN COALESCE(("entity_id" IN ( SELECT "rls_private"."my_document_entity_ids"('vendor'::"text") AS "my_document_entity_ids")), false)
    WHEN 'unit'::"text" THEN COALESCE(("entity_id" IN ( SELECT "rls_private"."my_document_entity_ids"('unit'::"text") AS "my_document_entity_ids")), false)
    WHEN 'general'::"text" THEN COALESCE((COALESCE("uploaded_by", ( SELECT "auth"."uid"() AS "uid")) IN ( SELECT "rls_private"."my_document_entity_ids"('general'::"text") AS "my_document_entity_ids")), false)
    ELSE false
END));



